 araros:{a:[_t(1291,'Hipótesis III del Pluto de Aristófanes (Araros presenta las últimas obras de su padre)'),_t(1292,'Escolio a Platón, Apología 19c'),_t(1293,'Suda, s.v. Araros'),_t(1294,'Fragmentos de Araros en Kassel-Austin, PCG II')],m:[_t(1295,'H.-G. Nesselrath, Die attische Mittlere Komödie (1990)')],n:[_t(1296,'Según la tradición, Aristófanes hizo presentar al público a su hijo con el Cócalo, hacia el 387; las fechas son inseguras.')]},
 antifanes:{a:[_t(1297,'Antífanes, fr. 189 K-A, Poíesis (Ateneo VI 222a-223a: la comedia lo tiene más difícil que la tragedia)'),_t(1298,'Suda, s.v. Antiphanes (empieza a estrenar hacia el 385)'),_t(1299,'Ateneo, Banquete de los eruditos (cita cientos de fragmentos)')],m:[_t(1300,'Nesselrath (1990)'),_t(1301,'R. Hunter, The New Comedy of Greece and Rome (1985)')],n:[_t(1302,'El fragmento sobre la tragedia es auténtico; la escena de Antífanes en el teatro es inventada.')]},
 ificrates:{a:[_t(1303,'Jenofonte, Helénicas IV 5.11-18 (la mora espartana destruida en el Lequeo, 390)'),_t(1304,'Diodoro XV 44 (reformas de los peltastas)'),_t(1305,'Cornelio Nepote, Ifícrates'),_t(1306,'Plutarco, Moralia 187a-b (dichos de Ifícrates)')],m:[_t(1307,'J. G. P. Best, Thracian Peltasts and their Influence on Greek Warfare (1969)'),_t(1308,'M. Trundle, Greek Mercenaries (2004)')],n:[_t(1309,'Tras la Paz del Rey, Ifícrates sirvió como mercenario en Tracia; es posible que no estuviera en el Pireo en el 386. Diodoro atribuye sus reformas a una época posterior.')]},
 cabrias:{a:[_t(1310,'Jenofonte, Helénicas V 1.10-13 (Cabrias en Egina, 388)'),_t(1311,'Cornelio Nepote, Cabrias'),_t(1312,'Diodoro XV 29 y 32-33 (la posición de rodilla en tierra; Egipto)'),_t(1313,'Demóstenes XX 75-86 (honores a Cabrias)')],m:[_t(1314,'Trundle (2004)'),_t(1315,'J. Kirchner, Prosopographia Attica (1901-1903)')],n:[_t(1316,'Tras la Paz del Rey, Cabrias marchó a Chipre y Egipto como mercenario; su presencia en Atenas en el 386 es una licencia.')]},
 aristipo:{a:[_t(1317,'Diógenes Laercio II 65-104 (Aristipo y los cirenaicos)'),_t(1318,'Jenofonte, Memorables II 1 y III 8 (conversaciones con Sócrates)'),_t(1319,'Heródoto IV 150-205 (fundación de Cirene y los Batíadas)'),_t(1320,'Píndaro, Píticas IV-V (para Arcesilao IV)')],m:[_t(1321,'F. Chamoux, Cyrène sous la monarchie des Battiades (1953)'),_t(1322,'K. Lampe, The Birth of Hedonism (2015)')],n:[_t(1323,'No sabemos dónde vivía Aristipo en el 386; la tradición lo sitúa en Atenas, Siracusa y Cirene. La genealogía batíada es la de Heródoto; el fundador argonauta Eufemo procede de Píndaro.')]},
 esparta:{a:[_t(1324,'Heródoto VI 51-60 (los dos reyes) y VII 204, VIII 131 (genealogías)'),_t(1325,'Jenofonte, Helénicas III 3.1-4 (sucesión de Agesilao)'),_t(1326,'Jenofonte, Constitución de los lacedemonios 13-15'),_t(1327,'Plutarco, Agesilao y Lisandro')],m:[_t(1328,'P. Cartledge, Sparta and Lakonia (1979)'),_t(1329,'P. Cartledge, Agesilaos and the Crisis of Sparta (1987)')],n:[_t(1330,'Teleclo es un personaje inventado. Las primeras generaciones de ambas dinastías son legendarias y sus listas no coinciden en todas las fuentes.')]},
