 dicasta:{a:[_t(1498,'Aristóteles, Constitución de los atenienses 24.3 (6.000 jurados), 27.4 (Pericles introduce el pago), 62.2 (tres óbolos) y 63-69 (procedimiento de sorteo y votación en el siglo IV)'),_t(1499,'Platón, Apología 36a (con treinta votos más habría sido absuelto)'),_t(1500,'Diógenes Laercio II 41-42 (cifras de la votación)'),_t(1501,'Aristófanes, Avispas (422 a.C.), parodia de un jurado anciano')],m:[_t(1502,'A. L. Boegehold, The Lawcourts at Athens (The Athenian Agora XXVIII, 1995)'),_t(1252,'S. C. Todd, The Shape of Athenian Law (1993)'),_t(1503,'D. Nails, The People of Plato (2002)')],n:[_t(1504,'El recuento de 280 contra 221 es una deducción a partir de la Apología; las fuentes no lo dan de forma directa.'),_t(1505,'La identificación de la Heliea con el recinto rectangular del suroeste del Ágora es discutida.'),_t(1506,'Lisímaco es un personaje inventado.')]},
 carcelero:{a:[_t(1507,'Platón, Fedón 57a-59c y 115b-118a (los últimos días y la muerte; «le debemos un gallo a Asclepio», 118a)'),_t(1508,'Platón, Critón (la propuesta de fuga y la respuesta de Sócrates)'),_t(1509,'Platón, Apología (el juicio)'),_t(1510,'Jenofonte, Memorables IV 8.2 (treinta días de espera) y Apología de Sócrates'),_t(1511,'Esquines, Contra Timarco 173 (Sócrates, condenado por haber sido maestro de Critias)')],m:[_t(1512,'R. Waterfield, Why Socrates Died (2009)'),_t(1503,'D. Nails, The People of Plato (2002)'),_t(1513,'Camp (1986), sobre el edificio identificado como prisión')],n:[_t(1514,'El Fedón menciona al servidor de los Once, que llora al traer el veneno, pero no da su nombre: Sosias es inventado.'),_t(1515,'La identificación arqueológica de la prisión con un edificio del suroeste del Ágora es una propuesta, no una certeza.')]},
 platon:{a:[_t(1516,'Platón, República VII 514a-517a (la caverna), V 473c-d (los filósofos-reyes) y VI 488a-489a (la nave del Estado)'),_t(1517,'Platón, Carta VII 324b-326b (desencanto político y viajes a Italia y Sicilia)'),_t(1518,'Diógenes Laercio, Vidas III (biografía y fundación de la Academia)'),_t(1519,'Platón, Fedón y Banquete (teoría de las Ideas)')],m:[_t(1268,'J. Dillon, The Heirs of Plato (2003)'),_t(1520,'W. K. C. Guthrie, Historia de la filosofía griega, vol. IV'),_t(1521,'R. Kraut (ed.), The Cambridge Companion to Plato (1992)')],n:[_t(1522,'La República se escribió hacia el 375: en el juego Platón anticipa ideas que entonces estaba elaborando.'),_t(1523,'La inscripción «Que no entre quien no sepa geometría» solo aparece en comentaristas del siglo VI d.C.: es una tradición tardía.'),_t(1524,'El viaje a Egipto lo cuentan biógrafos posteriores; la Carta VII solo habla de Italia y Sicilia. La fecha de la Academia (c. 387) es aproximada.')]},
 isocrates:{a:[_t(1525,'Isócrates, Contra los sofistas (c. 390), Antídosis (354) y Panegírico (380)'),_t(1526,'Isócrates, Panatenaico 9-10 y Filipo 81 (su voz débil y su falta de audacia)'),_t(1527,'Pseudo-Plutarco, Vidas de los diez oradores, Isócrates (padre fabricante de flautas, honorarios de mil dracmas)'),_t(1528,'Isócrates, Panegírico 115-121 y 175-180 (contra la Paz del Rey)')],m:[_t(1529,'Y. L. Too, The Rhetoric of Identity in Isocrates (1995)'),_t(1530,'T. Poulakos y D. Depew (eds.), Isocrates and Civic Education (2004)')],n:[_t(1531,'El Panegírico se publicó en el 380; en el 386 Isócrates podía estar preparándolo, pero eso es una suposición del juego.')]},
