function homeGate(to){
  if(MODE==='roma')return{ostia:[-1000,385],tibur:[1280,-30],praeneste:[1280,-30],ciminia:[-1000,385],soracte:[-690,-1520],nemi:[1270,1160],etruria:[-1000,385],umbria:[-690,-1520],picenum:[-40,-1480],samnium:[1280,-30],campania:[1270,1160]}[to];
  return{pentelico:[LYCEUM.x+150,LYCEUM.z-260],citeron:[NG.x-20,NG.z-410],megara:[SG.x+SG.ox*420+90,SG.z+SG.oz*420],platea:[NG.x-20,NG.z-410],maraton:[LYCEUM.x+150,LYCEUM.z-260]}[to];}
const GATES_W=[];
const llOf=id=>(MODE==='roma'?MED_POS_RO:MED_POS)[id];
function bearing(a,b){const A=llOf(a),B=llOf(b);if(!A||!B)return null;const dx=(B[0]-A[0])*Math.cos(A[1]*Math.PI/180),dz=-(B[1]-A[1]),l=Math.hypot(dx,dz);return{dx:dx/l,dz:dz/l,km:l*111};}
function dirName(dx,dz){const a=Math.atan2(-dz,dx);const k=((Math.round(a/(Math.PI/4))%8)+8)%8;return['este','noreste','norte','noroeste','oeste','suroeste','sur','sureste'][k];}
function mapName(id){return id==='atenas'?homeName():(ISLANDS.find(I=>I.id===id)||{name:id}).name;}
// ============================================================ ESCENARIOS CUADRADOS
// Cada mapa es un cuadrado: la ciudad de partida (con el Pireo o con Ostia y los montes) y cada destino. Más allá del borde se levantan
// montes que no se pueden subir (o está el mar); cada vecino por tierra tiene un tramo del borde, en el lado que mira hacia él, y al
// cruzarlo se viaja hasta allí (días y coste como antes), llegando por el lado opuesto. Por mar se sigue viajando desde el puerto.
function regionSquare(k){if(k==='atenas')return{cx:INNER.x,cz:INNER.z,h:INNER.size/2};   // la ciudad: el cuadrado de su malla de terreno
  const I=ISLANDS.find(q=>q.id===k);if(!I)return null;return{cx:I.x,cz:I.z,h:I.R*(I.land?1.25:1.4)};}
function sqClamp(p){if(BOAT&&BOAT.on)return;const I=islandOf(p.x);if(!I)return;const S=regionSquare(I.id);if(!S||sqOut(S,player.x,player.z)>250||player.feet>600)return;   // lejos (Creta, sueños, cuevas) no se toca
  p.x=clamp(p.x,S.cx-S.h+20,S.cx+S.h-20);p.z=clamp(p.z,S.cz-S.h+20,S.cz+S.h-20);}
function sqOut(S,x,z){return Math.max(Math.abs(x-S.cx),Math.abs(z-S.cz))-S.h;}   // >0: fuera del cuadrado
// tramos del borde para los vecinos por tierra de un mapa: cada uno en el lado que mira hacia él; si hay varios en un lado, repartidos
function edgeSlots(f){const C=edgeSlots._c||(edgeSlots._c={}),key=MODE+':'+f;if(C[key])return C[key];const S=regionSquare(f),out={};if(!S)return C[key]=out;
  const links=[];for(const[a,b]of WORLD_LINKS[MODE==='roma'?'roma':'atenas']){const t=a===f?b:b===f?a:null;if(!t)continue;const br=bearing(f,t);if(br)links.push({t,br});}
  const side=br=>Math.abs(br.dx)>=Math.abs(br.dz)?(br.dx>0?'E':'W'):(br.dz>0?'S':'N');const bySide={};for(const L of links)(bySide[side(L.br)]=bySide[side(L.br)]||[]).push(L);
  for(const sd in bySide){const L=bySide[sd],ns=sd==='E'||sd==='W';L.sort((a,b)=>ns?a.br.dz-b.br.dz:a.br.dx-b.br.dx);
    L.forEach((l,i)=>{const t=L.length===1?(ns?l.br.dz:l.br.dx)*0.5:((i+1)/(L.length+1)*2-1)*0.7,o=sd==='E'?[1,0]:sd==='W'?[-1,0]:sd==='S'?[0,1]:[0,-1],tg=[-o[1],o[0]];
      out[l.t]={x:S.cx+o[0]*(S.h-26)+tg[0]*t*S.h,z:S.cz+o[1]*(S.h-26)+tg[1]*t*S.h,ox:o[0],oz:o[1],side:sd};});}   // a 26 m del borde: el paso se corta a 20
  return C[key]=out;}
// montes más allá del borde (solo en tierra; el mar sigue siendo mar), con un paso abierto en cada salida
function sqMount(k,x,z,h){if(h<0.6)return h;let S;try{S=regionSquare(k);}catch(err){return h;}if(!S)return h;const e=sqOut(S,x,z);if(e<-22)return h;
  const e2=Math.max(0,e+22);let add=260*(1-Math.exp(-e2*0.75/260))+Math.max(0,fbm(x*0.011+3.1,z*0.011)-0.35)*Math.min(1,Math.max(0,e+22)/50)*40;
  let G;try{G=edgeSlots(k);}catch(err){G={};}for(const t in G){const g=G[t],lat=Math.abs((x-g.x)*(-g.oz)+(z-g.z)*g.ox);const ee=Math.max(0,e),w0=9+ee*0.4,rp=31+ee*0.9;if(lat<w0+rp)add*=sstep(clamp((lat-w0)/rp,0,1));}   // el paso se abre en valle a medida que se aleja del borde
  if(e>3000)add*=Math.max(0,1-(e-3000)/1500);   // muy lejos, la sierra baja despacio
  return h+add;}
// antes de construir el terreno: la puerta de cada destino y un camino aplanado (pads) desde la llegada hasta ella
function defineGates(){
  GATES_W.length=0;const has=id=>id==='atenas'||ISLANDS.some(I=>I.id===id);
  for(const[a,b]of WORLD_LINKS[MODE==='roma'?'roma':'atenas']){if(!has(a)||!has(b))continue;
    for(const[f,t]of[[a,b],[b,a]]){const br=bearing(f,t);if(!br)continue;let gx,gz,path=null;
      const sl=edgeSlots(f)[t];
      if(f==='atenas'){const p=homeGate(t);if(!p)continue;if(sl){gx=sl.x;gz=sl.z;const L=Math.hypot(gx-p[0],gz-p[1]),n=Math.max(2,Math.ceil(L/14));path=[];for(let i=0;i<=n;i++)path.push([lerp(p[0],gx,i/n),lerp(p[1],gz,i/n)]);}else{gx=p[0];gz=p[1];}}
      else{const I=ISLANDS.find(q=>q.id===f),th0=Math.atan2(br.dz,br.dx);let best=null;
        let bc=1e9;   // dentro de la dirección del vecino (±50°), el paso más llano: la puerta sale por el valle, no por la cumbre
        if(sl&&I.land)best=[sl.x,sl.z];else   // en tierra firme, la puerta está en su tramo del borde del cuadrado
        for(let k=-6;k<=6;k++){const th=th0+k*0.15,x=I.x+Math.cos(th)*I.R*0.86,z=I.z+Math.sin(th)*I.R*0.86;if(islandBase(I,x,z)<=2||!GATES_W.every(g=>Math.hypot(g.x-x,g.z-z)>60))continue;
          let c=0,ph=islandBase(I,I.x+Math.cos(th)*I.R*0.3,I.z+Math.sin(th)*I.R*0.3);for(let r=0.34;r<=0.861;r+=0.04){const hh=islandBase(I,I.x+Math.cos(th)*I.R*r,I.z+Math.sin(th)*I.R*r);if(hh<0.5)c+=50;c+=Math.abs(hh-ph);ph=hh;}
          c+=Math.abs(k)*3;if(c<bc){bc=c;best=[x,z];}}
        if(!best)continue;[gx,gz]=best;
        // camino: de la llegada (o del centro) a la puerta, con la pendiente limitada
        const gd=Math.hypot(gx-I.x,gz-I.z),s={x:I.x+(gx-I.x)/gd*I.R*0.42,z:I.z+(gz-I.z)/gd*I.R*0.42},L=Math.hypot(gx-s.x,gz-s.z),n=Math.max(3,Math.ceil(L/12));path=[];   // desde las afueras del pueblo, sin cruzar sus edificios
        for(let i=0;i<=n;i++){const u=i/n;path.push([lerp(s.x,gx,u),lerp(s.z,gz,u)]);}
        const hs=path.map(p=>islandBase(I,p[0],p[1]));hs[0]=s.h!==undefined?s.h:hs[0];const st=L/n*0.22;
        for(let r=0;r<3;r++){for(let i=1;i<hs.length;i++)hs[i]=clamp(hs[i],hs[i-1]-st,hs[i-1]+st);for(let i=hs.length-2;i>0;i--)hs[i]=clamp(hs[i],hs[i+1]-st,hs[i+1]+st);}
        path.forEach((p,i)=>{pad(I,p[0]-I.x,p[1]-I.z,i?6:10,0,Math.max(1.6,hs[i])).road=true;});}
      let ox=gx-(f==='atenas'?INNER.x:ISLANDS.find(q=>q.id===f).x),oz=gz-(f==='atenas'?INNER.z:ISLANDS.find(q=>q.id===f).z),ol=Math.hypot(ox,oz)||1;
      if(sl&&(f==='atenas'||ISLANDS.find(q=>q.id===f).land)&&Math.hypot(gx-sl.x,gz-sl.z)<1){ox=sl.ox;oz=sl.oz;ol=1;}
      GATES_W.push({from:f,to:t,x:gx,z:gz,ox:ox/ol,oz:oz/ol,br,path});}}
}
// después del terreno: el camino de tierra, dos mojones y un letrero en cada puerta
function buildGates(){
  const dirt=new THREE.MeshLambertMaterial({color:'#a8957a',polygonOffset:true,polygonOffsetFactor:-2,polygonOffsetUnits:-2}),st=MODE==='roma'?TRAV_STONE():M.limestone;
  for(const g of GATES_W){
    if(g.path){const pos=[],P=g.path;for(let i=0;i<P.length-1;i++){const[a,b]=[P[i],P[i+1]],dx=b[0]-a[0],dz=b[1]-a[1],l=Math.hypot(dx,dz)||1,nx=-dz/l*2.2,nz=dx/l*2.2,
        q=(x,z)=>[x,terrainH(x,z)+0.07,z],A=q(a[0]+nx,a[1]+nz),Bv=q(a[0]-nx,a[1]-nz),C=q(b[0]-nx,b[1]-nz),D=q(b[0]+nx,b[1]+nz);pos.push(...A,...Bv,...C,...A,...C,...D);}
      const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));geo.computeVertexNormals();const m=new THREE.Mesh(geo,dirt);m.material.side=THREE.DoubleSide;m.receiveShadow=true;m.userData.drape=true;scene.add(m);}
    const a=Math.atan2(g.ox,g.oz),gy=terrainH(g.x,g.z),grpG=grp(g.x,gy,g.z,a);
    // puerta ancha y alta (vídeo de Roma): dos pilares de 7 m a 10 m uno de otro y un dintel, para pasar a pie, a caballo o volando
    for(const s of[-1,1]){box(1.2,7.2,1.2,st,s*5,3.4,0,grpG);box(1.6,0.5,1.6,st,s*5,7.05,0,grpG);const p=toW(s*5,0,g.x,g.z,a);addBox(p[0],p[1],1.2,1.2,a);}
    box(11.6,0.7,1.3,st,0,7.6,0,grpG);
    box(0.14,2.2,0.14,M.wood,6.6,1.1,-2,grpG);const sg=box(1.6,0.5,0.08,lam('#c9b48b'),7.1,2.05,-2,grpG);sg.rotation.y=0.3;
    const days=Math.max(1,Math.round(g.br.km/30)),lb=labelSprite('Hacia '+mapName(g.to),'por el '+dirName(g.ox,g.oz)+' · unos '+days+(days>1?_t(2607,' días'):_t(2608,' día'))+' de camino');
    lb.position.set(0,9,0);lb.visible=false;grpG.add(lb);g.lb=lb;}
  try{gateClearWalls();}catch(e){}
}
// los muretes de piedra seca de los campos no pueden cruzar el paso de una puerta (en la salida hacia Ostia uno la cortaba)
function gateClearWalls(){const m=new THREE.Matrix4(),v=new THREE.Vector3(),Z=new THREE.Matrix4().makeScale(0,0,0);
  for(const ch of CHUNKS){const im=ch.im;if(!im||!im.userData.low)continue;let c=false;for(let i=0;i<im.count;i++){im.getMatrixAt(i,m);v.setFromMatrixPosition(m);
    for(const g of GATES_W){const dx=v.x-g.x,dz=v.z-g.z;if(Math.abs(dx)>40||Math.abs(dz)>40)continue;const along=-(dx*g.ox+dz*g.oz),side=Math.abs(dx*g.oz-dz*g.ox);if(Math.abs(along)<30&&side<8){im.setMatrixAt(i,Z);c=true;break;}}}
    if(c)im.instanceMatrix.needsUpdate=true;}}
// franja que sigue el relieve (caminos, cañadas, lindes): una losa plana larga queda enterrada o flotando
function drapeStrip(x0,z0,x1,z1,w,mat,lift){const L=Math.hypot(x1-x0,z1-z0),n=Math.max(1,Math.ceil(L/4)),nx=-(z1-z0)/L*w/2,nz=(x1-x0)/L*w/2,pos=[],y=(x,z)=>terrainH(x,z)+Math.max(w>8?0.4:0.22,lift||0);   // las franjas anchas, un poco más altas: en Cartago la hierba y el camino parpadeaban
  const P=[];for(let i=0;i<=n;i++){const x=lerp(x0,x1,i/n),z=lerp(z0,z1,i/n);P.push([x+nx,y(x+nx,z+nz),z+nz,x-nx,y(x-nx,z-nz),z-nz]);}
  for(let i=0;i<n;i++){const a=P[i],b=P[i+1];if(Math.max(Math.abs(a[1]-a[4]),Math.abs(b[1]-b[4]),Math.abs(a[1]-b[1]),Math.abs(a[4]-b[4]))>Math.max(2.5,w*0.35))continue;   // en las laderas muy empinadas no se pinta
  pos.push(a[0],a[1],a[2],b[0],b[1],b[2],a[3],a[4],a[5],a[3],a[4],a[5],b[0],b[1],b[2],b[3],b[4],b[5]);}
  const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));g.computeVertexNormals();
  const m=new THREE.Mesh(g,mat);m.material.side=THREE.DoubleSide;m.material.polygonOffset=true;m.material.polygonOffsetFactor=-4;m.material.polygonOffsetUnits=-4;m.receiveShadow=true;m.userData.drape=true;scene.add(m);return m;}
const TRAV_STONE=()=>lam('#d8ccb0');
// al llegar a una puerta se camina hasta el mapa vecino
let gateT=0,gateCool=0;
function gatesTick(dt){gateCool=Math.max(0,gateCool-dt);gateT+=dt;if(gateT<0.2)return;gateT=0;if(ui!=='play'||!GATES_W.length)return;
  const reg=regionOf(player.x);
  for(const g of GATES_W){if(regionOf(g.x)!==reg)continue;const d=Math.hypot(player.x-g.x,player.z-g.z);if(g.lb)g.lb.visible=d<70;
    if(d<5.5&&!gateCool&&player.feet-terrainH(g.x,g.z)<9){gateTravel(g);return;}}}
function gateTravel(g){
  const tg=GATES_W.find(q=>q.from===g.to&&q.to===g.from);if(!tg)return;
  ui='voyage';releasePointer();if(MOUNT.riding)dismount();if(MOUNT.g){MOUNT.g.visible=false;MOUNT.st='away';}
  const days=Math.max(1,Math.round(g.br.km/30)),v=$('voyage');v.classList.add('land');
  v.querySelector('.vt').textContent=_t(2609,'Caminas hacia el ')+dirName(g.ox,g.oz)+_t(2610,', rumbo a ')+mapName(g.to);
  v.querySelector('.vs').textContent=_t(2611,'Unos ')+Math.round(g.br.km)+_t(2612,' kilómetros: ')+(days>1?days+_t(2607,' días'):_t(2613,'un día'))+_t(2614,' de camino.');
  v.querySelector('.vf').textContent=pick(MODE==='roma'?ROMA_LAND_FACTS:LAND_FACTS);v.hidden=false;requestAnimationFrame(()=>v.classList.add('show'));
  setTimeout(()=>{const x=tg.x-tg.ox*14,z=tg.z-tg.oz*14;player.x=x;player.z=z;player.feet=floorAt(x,z);player.camY=player.feet+player.eye;player.vy=0;player.yaw=Math.atan2(tg.ox,tg.oz);player.pitch=0;
    curZone=null;addHours(Math.min(30,g.br.km/5));updateSky();gateCool=3;
    v.classList.remove('show');setTimeout(()=>{v.hidden=true;ui='play';toast(_t(2615,'<span class="label">Llegas a ')+mapName(g.to)+_t(2616,'</span><br>El camino de vuelta hacia ')+mapName(g.from)+_t(2617,' sale por el ')+dirName(tg.ox,tg.oz)+'.');},700);},2200);
}
// mapas de paso que completan Grecia e Italia: un pueblo, un santuario o monumento y una estela
function defineSimple(I,o){for(const b of o.blobs||[])I.blobs.push({x:I.x+b[0],z:I.z+b[1],R:b[2],H:b[3]});
  if(o.lake)I.lake={x:I.x+o.lake[0],z:I.z+o.lake[1],rx:o.lake[2],rz:o.lake[3]};if(o.tint)I.tint=o.tint;
  // el pueblo no puede caer dentro del lago (Nemi, el Estínfalo y Galilea tenían una «isla» con casas en medio del agua): se corre hacia la llegada
  let TX=o.tx||0,TZ=o.tz||0,TR=o.tr||70;if(o.lake){const L=o.lake,A=o.arr||[-I.R*0.72,30],wet=(x,z,r)=>Math.hypot((x-L[0])/(L[2]+r),(z-L[1])/(L[3]+r))<1.08;
    if(wet(TX,TZ,TR)){TR=Math.min(TR,45);let ok=false;for(let t=0.05;t<=1.001;t+=0.05){const x=lerp(TX,A[0],t),z=lerp(TZ,A[1],t);if(!wet(x,z,TR)){TX=x;TZ=z;ok=true;break;}}if(!ok){TX=A[0];TZ=A[1];TR=30;}}}
  I.arrive=pad(I,...(o.arr||[-I.R*0.72,30]),24,0,3);I.town=pad(I,TX,TZ,TR,0,Math.max(4,islandBase(I,I.x+TX,I.z+TZ)));   /* el pueblo, a la altura del terreno: fijado a 4 m, en los mapas de monte abría un pozo de paredes verticales (el Eta, el Liceo, las Escironias…) */I.town.house=true;
  if(o.site)I.site=pad(I,o.site[0],o.site[1],o.site[2]||22,0,o.site[3]);
  for(const q of o.pads||[])pad(I,q[0],q[1],q[2]);}   // espacios libres de árboles para escenas y objetos
function buildSimple(I,o){const t=I.town,s=I.site;
  if(o.temple&&s)temple(Object.assign({x:s.x,z:s.z,gy:s.h,rot:Math.PI/2,W:12,L:24,nW:6,nL:12,colD:1,colH:6,cella:{w:7.5,l:14,door:2.4}},o.temple));
  if(o.rtemple&&s)romanTemple(Object.assign({x:s.x,z:s.z,gy:s.h-0.2,rot:0,W:14,L:24,pod:2.5,colD:0.9,colH:9,nW:6,deep:2},o.rtemple));
  if(typeof NAT_NY!=='undefined'&&NAT_NY[I.id])footprints.push({x:I.x+NAT_NY[I.id].dx,z:I.z+NAT_NY[I.id].dz,r:4});   // el sitio del dios o la ninfa del lugar, reservado en todos los mapas (antes solo en los «early»: en Selinunte una casa tapaba al genio)
  if(o.early&&o.extra){I.chkFree=true;o.extra(I);}   // los mapas nuevos levantan sus edificios antes que las casas, y las casas evitan lo ya construido
  destHouses(I,t.x,t.z,o.houses||30,o.spread||120,!!o.roman);
  const a=I.arrive;(o.steles||[]).forEach((S,i)=>place(S[0],S[1],S[2],S[3],a.x+9,a.z-8+i*12,-Math.PI/2));
  if(o.npc)NPC_POS[o.npc]=[a.x+16,a.z+10,-Math.PI/2];
  if(o.extra&&!o.early)o.extra(I);
  if(o.roman)romaArrive(I,o.label);else if(I.land)greekArrive(I,o.label);}
const SIMPLE_GR={
 larisa:{npc:'tisandro',label:_t(2401,'Larisa'),blobs:[[0,-620,420,190],[-650,0,300,150]],site:[120,-80,22],temple:{name:_t(2618,'Templo de Apolo de Larisa')},
  steles:[['larisa_llanura',_t(2619,'La llanura de Tesalia'),'ΘΕΣΣΑΛΙΑ',_t(2620,'La mayor llanura de Grecia, regada por el río Peneo y rodeada de montañas: el Olimpo al norte, el Pindo al oeste, el Otris al sur. Aquí se crían los mejores caballos y se forma la mejor caballería griega. La tierra la poseen unas pocas familias aristocráticas, como los Aléuadas de Larisa, y la trabajan los penestas, campesinos sometidos que no son libres ni del todo esclavos. Hacia el norte se llega a Macedonia por el estrecho valle del Tempe; hacia el oeste, cruzando el Pindo, al Epiro.')]],
  extra(I){if(!GLB.ok)return;for(let i=0;i<7;i++){const x=I.x+150+rr(-60,60),z=I.z+160+rr(-50,50),g=grp(x,terrainH(x,z),z,R()*TAU);animalGLB('A_horse',g,pick(['#6b4a2e','#3a2a1e','#d8cfc0','#8a6a4a']),'#2a1e16');addCirc(x,z,1);}}},
 pela:{npc:'teodoto_pela',label:_t(2404,'Pela'),blobs:[[300,-500,260,90]],site:[-60,-130,30],temple:{name:_t(2621,'Santuario de Pela'),W:14,L:26},
  steles:[['pela_capital',_t(2622,'Pela, capital de Macedonia'),'ΠΕΛΛΑ',_t(2623,'El rey Arquelao trasladó hace unos años la capital de Macedonia desde Egas hasta aquí, junto a una laguna comunicada con el mar. Quiso hacer de su corte una pequeña Atenas: invitó al pintor Zeuxis a decorar su palacio y al poeta Eurípides, que murió en Macedonia en el 406. Ahora reina Amintas III, que lucha por conservar el trono frente a los ilirios y a la liga de Olinto. En el sur de Grecia se discute si los macedonios son griegos de verdad. Dentro de cuatro años nacerá aquí su hijo Filipo, que dominará Grecia, y de Filipo nacerá Alejandro.')]]},
 dodona:{npc:'anthis',label:_t(2407,'Dodona'),blobs:[[-50,-600,380,260],[500,0,300,200],[-100,520,320,180]],site:[60,-40,30],houses:12,spread:90,
  steles:[['dodona_oraculo',_t(2624,'El oráculo de Dodona'),'ΔΩΔΩΝΗ',_t(2625,'El oráculo más antiguo de Grecia, según Heródoto. Zeus habla por el rumor de las hojas de una encina sagrada, y sus sacerdotes, los selos, duermen en el suelo y no se lavan los pies, como ya cuenta la Ilíada. Alrededor del árbol hay un círculo de calderos de bronce sobre trípodes: al tocar uno, el sonido pasa de caldero en caldero. Los fieles escriben sus preguntas en láminas de plomo: si les conviene casarse, si el hijo que espera su mujer es suyo, si deben emigrar. Se han encontrado miles.')]],
  extra(I){const s=I.site;if(GLB.ok)treesGLB([{x:s.x,z:s.z,kind:'plane',k:2.4,collide:true}]);try{forestBuild(I,520,true);}catch(e){console.warn('dodona bosque',e);}
   for(let i=0;i<14;i++){const a=i/14*TAU,x=s.x+Math.cos(a)*11,z=s.z+Math.sin(a)*11,g=grp(x,s.h,z,0);for(let k=0;k<3;k++){const l=box(0.06,1.3,0.06,M.bronze,Math.cos(k*2.1)*0.3,0.65,Math.sin(k*2.1)*0.3,g);}const c=new THREE.Mesh(new THREE.SphereGeometry(0.42,12,8,0,TAU,Math.PI/2,Math.PI/2),M.bronze);c.position.y=1.5;g.add(c);addCirc(x,z,0.45);}}},
 calidon:{npc:'laodoco',label:_t(2410,'Calidón'),blobs:[[60,-450,300,160]],site:[160,-160,26],temple:{name:_t(2626,'Templo de Ártemis Lafria')},
  steles:[['calidon_jabali',_t(2627,'El jabalí de Calidón'),'ΚΑΛΥΔΩΝ',_t(2628,'Aquí sitúa el mito la cacería del jabalí monstruoso que Ártemis envió contra Calidón porque el rey Eneo la había olvidado en sus sacrificios. Acudieron héroes de toda Grecia; la cazadora Atalanta fue la primera en herirlo y Meleagro lo mató y le regaló la piel, lo que desató la discordia. Sobre la ciudad está el santuario de Ártemis Lafria. Muchos etolios viven aún en aldeas sin murallas y tienen fama de guerreros de armas ligeras: en el 426 derrotaron en sus montes a los atenienses de Demóstenes.')]]},
 egio:{npc:'xenias',label:_t(2413,'Egio'),blobs:[[0,520,360,220]],site:[110,60,24],temple:{name:_t(2629,'Santuario de Zeus Homario')},
  steles:[['egio_aqueos',_t(2630,'Egio y los aqueos'),'ΑΙΓΙΟΝ',_t(2631,'Las ciudades de Acaya, en la costa norte del Peloponeso, forman una liga que se reúne en el santuario de Poseidón de Hélice, a poca distancia de aquí. Hélice no lo sabe, pero dentro de trece años, en el 373, un terremoto nocturno y una ola gigante la tragarán entera, y durante siglos los viajeros verán sus ruinas bajo el agua. Después, los aqueos se reunirán aquí, en Egio.')]]},
 itome:{npc:'damon_itome',label:_t(2416,'Itome'),blobs:[[120,-140,170,80]],site:[120,-140,16],temple:{name:_t(2632,'Santuario de Zeus Itomatas'),W:9,L:16,nW:4,nL:8,colH:5,colD:0.8,cella:{w:6,l:9,door:2}},
  steles:[['itome_hilotas',_t(2633,'Mesenia y los hilotas'),'ΙΘΩΜΗ',_t(2634,'Mesenia es una de las tierras más fértiles de Grecia, y por eso Esparta la conquistó hace siglos. Sus habitantes son hilotas: siervos que cultivan la tierra para sus amos espartanos y les entregan la mitad de la cosecha. Se han sublevado varias veces; en la gran rebelión que siguió al terremoto del 464 resistieron diez años aquí, en el monte Itome, junto al santuario de Zeus Itomatas. Dentro de diecisiete años, Epaminondas de Tebas liberará Mesenia y fundará en esta ladera la ciudad de Mesene.')]]},
 calcis:{npc:'lisimaco_calcis',label:_t(2419,'Calcis'),site:[90,-90,24],temple:{name:_t(2635,'Templo de Apolo de Calcis')},
  steles:[['calcis_euripo',_t(2636,'El Euripo'),'ΕΥΡΙΠΟΣ',_t(2637,'Calcis está junto al Euripo, el estrecho que separa la isla de Eubea de Beocia: en su parte más angosta mide unos cuarenta metros, y desde el 411 lo cruza un puente. Sus corrientes cambian de sentido varias veces al día, tan deprisa que los barcos tienen que esperar, y nadie sabe por qué. Aristóteles, que pasará aquí sus últimos días, intentará explicarlo. Calcis fundó hace siglos colonias por todo el Mediterráneo, de Sicilia y el sur de Italia a la península que lleva su nombre, la Calcídica.')]]}
};
