function checkZone(){{const fz=fzIn();if(fz){const k='fz_'+fz+(fz==='inf'&&player.z-6000>155?'2':'');if(curZone!==k){curZone=k;const T={fz_race:MODE==='roma'?[_t(2889,'Un trigal del Lacio'),'CAMILLA',_t(2890,'Eneida VII 803-817')]:[_t(2891,'El estadio'),'ΣΤΑΔΙΟΝ',_t(2892,'La carrera contra Atalanta')],fz_tel:[_t(2893,'El Telesterion'),'ΤΕΛΕΣΤΗΡΙΟΝ',_t(2894,'Eleusis, la noche de los Misterios')],fz_inf:[_t(2895,'Los Infiernos'),'AVERNVS',_t(2896,'Eneida, libro VI')],fz_inf2:[_t(2897,'Los Campos Elíseos'),'ELYSIVM',_t(2898,'Eneida VI 637-678')]}[k];showZone(T[0],T[1],T[2]);}return;}}if(cavIn()){const lz=player.z-CAV.Z,k=MODE==='roma'?'somnium':lz<95?'caverna':player.feet<CAV.Y+50?'cav_fuera':'ideas';if(curZone!==k){curZone=k;const T={somnium:[_t(2899,'El Sueño de Escipión'),'SOMNIVM SCIPIONIS',_t(2900,'Cicerón, República, libro VI')],caverna:[_t(2901,'La caverna'),'ΣΠΗΛΑΙΟΝ',_t(2902,'Platón, República, libro VII')],cav_fuera:[_t(2903,'Fuera de la caverna'),'ΤΟ ΦΩΣ',_t(2904,'La luz del sol')],ideas:[_t(2905,'El mundo de las Ideas'),'ΑΙ ΙΔΕΑΙ',_t(2906,'Lo que es siempre')]}[k];showZone(T[0],T[1],T[2]);}return;}if(player.feet>MOON.y-50){if(curZone!=='luna'){curZone='luna';showZone(_t(2907,'La Luna'),'ΣΕΛΗΝΗ',_t(2908,'El reino de Endimión, según Luciano'));}return;}if(player.feet>CASA.Y-50){if(curZone!=='casa'){curZone='casa';showZone(_t(2909,'Tu casa'),MODE==='roma'?'DOMVS':'ΟΙΚΙΑ',MODE==='roma'?_t(2910,'En el Quirinal'):_t(2911,'En Melite'));}return;}if(OLYM.built&&player.feet>OLYM.y-50&&player.feet<CASA.Y-50){if(curZone!=='olimpo'){curZone='olimpo';showZone(_t(2912,'El Olimpo'),'ΟΛΥΜΠΟΣ',_t(2913,'La morada de los dioses'));}return;}const z=ZONES.find(zn=>zn.test(player.x,player.z));if(z&&z.id!==curZone){curZone=z.id;showZone(z.name,z.gr,z.sub);fxZone(z.id);}}

// brújula
const CDIRS=[['N',0],['NE',45],['E',90],['SE',135],['S',180],[_t(2914,'SO'),225],[_t(2915,'O'),270],[_t(2916,'NO'),315]];
function drawCompass(){
  const el=$('compass'),W=el.clientWidth,fov=110;const head=-player.yaw*180/Math.PI;let h='';
  for(const[l,b]of CDIRS){const d=((b-head+540)%360)-180;if(Math.abs(d)<fov/2)h+='<span class="c'+(l.length>1?' minor':'')+'" style="left:'+(W/2+d/fov*W)+'px">'+l+'</span>';}
  const t=guideTarget();if(t){const b=Math.atan2(t.x-player.x,-(t.z-player.z))*180/Math.PI;let d=((b-head+540)%360)-180;d=clamp(d,-fov/2+3,fov/2-3);h+='<span class="c obj" style="left:'+(W/2+d/fov*W)+'px">◆</span>';}
  el.innerHTML=h;
}

