  n.topics.forEach((t,i)=>add(t[0],seen.includes(i)?'seen':'',()=>{state.seen[n.id]=Array.from(new Set(seen.concat(i)));save();$('dBody').innerHTML='<p>'+t[1]+'</p>';renderOpts();}));
  const more=MORE[n.id];if(more&&seen.length){const xs=state.seen['x:'+n.id]||[];add(_t(2919,'Cuéntame más (')+xs.length+' de '+more.length+_t(2920,' temas escuchados)'),'quiz',()=>moreMenu(n));}
  if(n.sophistHire)add(state.sophist?_t(2921,'Contratar a otro sofista o despedirlo'):_t(2922,'Contratar a un sofista para una clase en casa'),'quiz',()=>sophistMenu(n));
