  if(n.aiChat&&AI.sample)add(_t(2926,'Discutir libremente con Platón (diálogo con IA)'),'quiz',()=>aiChat(n));
  if(n.latinBrowser)add(_t(2927,'Explícame un latinismo (tengo ')+LATIN.length+_t(2928,' en mis tablillas)'),'quiz',()=>latinMenu());
  if(n.mythBrowser)add(_t(2929,'Cuéntame un mito (tengo ')+MYTHS.length+_t(2930,' en mis rollos)'),'quiz',()=>mythMenu());
  if(n.wedding)add(state.seen.boda?_t(2931,'Volver a ver la boda de Valeria y Quinto'):_t(2932,'Asistir a la boda de Valeria y Quinto (catorce escenas)'),'quiz',()=>epiStart(ROMA_BODA));
  if(n.event)add(state.lessons.includes(n.event)?_t(2933,'Quiero volver a hacer de jurado'):_t(2934,'Quiero ser jurado hoy: llévame a un juicio'),'quiz',startTrial);
  if(!learned)add(seen.length?_t(2935,'Ponme a prueba: ¿lo he entendido?'):_t(2936,'Ponme a prueba (mejor después de escuchar)'),'quiz',startQuiz);
  if(FRIENDS[n.id]&&FRIENDS[n.id].m===MODE){const a=fz(n.id);add(a.t>=FRIENDS[n.id].e.length?_t(2937,'Charlar con un amigo (')+fGrade(a.p)+')':_t(2938,'Pasar un rato juntos · afinidad ')+a.p+'/100','quiz',()=>friendMenu(n));}
