  for(const mid of discOf()){const M=MASTERS[mid];if(M&&M.debate[n.id]&&!dz().deb[mid+':'+n.id])add(_t(2945,'Aceptar el reto: debatir con ')+n.name,'quiz',()=>debateMenu(n,mid));}
  if(n.id===HORSE_NPC()&&hz().own)add(_t(2946,'Cambiar el nombre de ')+horseName(),'quiz',()=>horseNameDlg(horseName(),()=>{$('dBody').innerHTML='<p>«'+horseName()+_t(2947,'. Buen nombre. Que corra tanto como suena».</p>');renderOpts();}));
  fxOpts(n,add);egOpts(n,add);m386Opts(n,add);cavOpts(n,add);finOpts(n,add);progOpts(n,add);acaOpts(n,add);cvOpts(n,add);hdOpts(n,add);
  if(n.id===HORSE_NPC()&&!hz().own)add(hz().q==='caught'?_t(2948,'Te traigo la yegua'):hz().q==='on'?_t(2949,'Sobre la yegua escapada…'):_t(2950,'¿Me darías un caballo?'),'quiz',()=>horseQuest(n));
  add(_t(2951,'Despedirse'),'',closeDialog);
