  if(SEAG.hint===1&&SEAG.pos>C.s0-0.8){SEAG.hint=2;seaSay(_t(3066,'El estrecho: a la izquierda, la cueva de Escila; a la derecha, el remolino de Caribdis.'),4.5);}
  if(SEAG.hint===2&&SEAG.pos>C.s1+0.4){SEAG.hint=3;seaSay(_t(3067,'Mar abierto. El sueño se desvanece…'),3);}
  SEAG.msgT-=dt;if(SEAG.msgT<0&&SEAG.msg){SEAG.msg='';$('seaMsg').innerHTML=SEAG.ear?_t(3068,'Oídos tapados'):'';}
  if(!SEAG.msg)$('seaMsg').innerHTML=SEAG.ear?_t(3068,'Oídos tapados'):'';
  SEAG.shake=Math.max(0,SEAG.shake-dt);
