function mapClamp(){MV.s=clamp(MV.s,1,8);const w=(MB.x1-MB.x0)/MV.s/2,h=(MB.z1-MB.z0)/MV.s/2;MV.cx=clamp(MV.cx,MB.x0+w,MB.x1-w);MV.cz=clamp(MV.cz,MB.z0+h,MB.z1-h);}
