  const dx=m[0]-o[0],dy=m[1]-o[1];if(Math.abs(dx)+Math.abs(dy)>2)MV.moved=true;
  if(MED.on){if(MV.moved&&MED.v.s>1.01){MED.v.cx-=dx/MED.v.s;MED.v.cy-=dy/MED.v.s;medClamp(c.width,c.height);drawMap();}return;}
