  for(let i=0;i<12;i++){const lx=-sw*0.42+i*sw*0.84/11;for(const lv of[0,1]){const wp=toW(lx,R0+1.2,o.x,o.z,a);addColumn(wp[0],gy+1.2+lv*(H*0.45),wp[1],0.4,H*0.42,a,'corinthian',true);}}
