  for(const sg of[-1,1]){for(let k=1;k<=10;k++){const lx=sg*(L/2+k*2-1),p=toW(lx,0,mx,mz,a),t=deck-k*0.4;if(t<terrainH(p[0],p[1])-0.2)break;addPlat(p[0],p[1],2.1,w,a,t);box(2.1,1,w,mat,lx,t-0.5,0,g);}}
