  for(const R of[R0,R1])for(let i=0;i<102;i++){const u0=i/120,u1=(i+1)/120,p=st(u0,R),q=st(u1,R),pw=toW(p[0],p[1],x,z,a),qw=toW(q[0],q[1],x,z,a);addSeg(pw[0],pw[1],qw[0],qw[1],0.6);}
