  R2(_t(4087,'Vía Lata'),5,[[-190,-110],[-320,-380],[-470,-760]]);
  R2(_t(4076,'Vía Apia'),5,[[330,180],[440,440],[700,680],[1000,900],[1300,1180]]);
  R2(_t(5144,'Vía Ostiense'),4.5,[[-200,420],[-260,560],[-180,760],[-80,900],[60,1300]]);
  R2(_t(5145,'Puentes de la isla'),3.5,[[-300,140],[-440,250],[-520,250],[-600,250],[-760,320],[-950,380]]);
