  R2(_t(5148,'Calle del Velabro'),3.5,[[-90,45],[-200,100],[-300,140],[-440,180],[-444,290],[-442,360],[-420,430],[-416,520],[-424,590],[-445,640]]);
  R2(_t(5149,'Clivo de Escauro'),3.5,[[300,140],[420,240],[560,300],[800,400]]);
  R2(_t(5150,'Calle del Trastévere'),3.5,[[-760,620],[-760,320],[-820,0],[-820,-60]]);
  // calles de los barrios del norte y del este (por su trazado conocido, comprimido como el resto)
  R2(_t(5151,'Vía Flaminia'),5,[[-470,-760],[-620,-1180],[-700,-1600]]);
  R2(_t(5152,'Vico Patricio'),3.5,[[230,-380],[300,-560],[420,-900],[560,-1400]]);
