// ============================================================ acabado: texturas procedurales y luz
// Las texturas son de detalle (casi grises): el color de cada material las tiñe. Se proyectan según la posición en el mundo
// (proyección triplanar), así que un muro de 30 m y un pilar de 1 m tienen la textura a la misma escala, sin depender de las UV:
// sirve igual para cajas, columnas instanciadas, piezas de Blender (que no tienen UV) y el terreno.
function pnoise(x,y,P,seed){const xi=Math.floor(x),yi=Math.floor(y),xf=x-xi,yf=y-yi,h=(i,j)=>{const a=((i%P)+P)%P,b=((j%P)+P)%P,s=Math.sin(a*127.1+b*311.7+seed*74.7)*43758.5453;return s-Math.floor(s);};
  const u=sstep(xf),v=sstep(yf);return lerp(lerp(h(xi,yi),h(xi+1,yi),u),lerp(h(xi,yi+1),h(xi+1,yi+1),u),v);}
function pfbm(x,y,P,seed,oct){let s=0,a=0.5,f=1,n=0;for(let o=0;o<(oct||4);o++){s+=pnoise(x*f,y*f,P*f,seed+o*7)*a;n+=a;a*=0.5;f*=2;}return s/n;}
// textura de N x N px: fn(u,v) en [0,1) devuelve [r,g,b] en [0,1]
function procTex(N,fn){const c=document.createElement('canvas');c.width=c.height=N;const x=c.getContext('2d'),img=x.createImageData(N,N);
  for(let j=0;j<N;j++)for(let i=0;i<N;i++){const p=fn(i/N,j/N),k=(j*N+i)*4;img.data[k]=clamp(p[0],0,1)*255;img.data[k+1]=clamp(p[1],0,1)*255;img.data[k+2]=clamp(p[2],0,1)*255;img.data[k+3]=255;}
  x.putImageData(img,0,0);const t=new THREE.CanvasTexture(c);t.wrapS=t.wrapT=THREE.RepeatWrapping;t.anisotropy=4;return t;}
const g3=v=>[v,v,v];
// sillería: hiladas de bloques al tresbolillo, con juntas y vetas suaves
function ashlarTex(rows,cols,rough,veins,seed){return procTex(256,(u,v)=>{const r=Math.floor(v*rows),off=(r%2)*0.5,cu=u*cols+off,c=Math.floor(cu),fu=cu-c,fv=v*rows-r;
  const joint=Math.min(fu,1-fu)*256/cols<1.6||Math.min(fv,1-fv)*256/rows<1.6;const blk=hash(c%cols+seed,r+seed*3);
  let val=0.9+blk*0.08-(pfbm(u*8,v*8,8,seed,4)-0.5)*rough;if(veins){const w=Math.sin((u*3+v*1.3+pfbm(u*4,v*4,4,seed+9,3)*2.2)*TAU*2);val-=Math.pow(Math.abs(w),18)*0.12;}
  if(joint)val*=0.72;return g3(val);});}
const PTEX={
 marble:ashlarTex(4,2,0.08,true,3),
 stone:ashlarTex(5,3,0.22,false,11),
 brick:procTex(256,(u,v)=>{const rows=22,r=Math.floor(v*rows),off=(r%2)*0.5,cu=u*7+off,c=Math.floor(cu),fu=cu-c,fv=v*rows-r;const mortar=fv<0.24||Math.min(fu,1-fu)<0.03;
   if(mortar)return[0.98,0.95,0.9];const b=0.74+hash(c,r)*0.18-(pfbm(u*16,v*16,16,5,3)-0.5)*0.12;return[b,b*0.97,b*0.94];}),
 plaster:procTex(256,(u,v)=>{let val=0.93-(pfbm(u*5,v*5,5,21,5)-0.5)*0.22-Math.pow(pfbm(u*24,v*24,24,4,2),3)*0.06;const st=pfbm(u*2,v*9,2,33,3);val-=Math.max(0,st-0.62)*0.25;return[val,val*0.99,val*0.96];}),
 tile:procTex(256,(u,v)=>{const cols=8,rows=6,cu=u*cols,c=Math.floor(cu),fu=cu-c,fv=(v*rows)%1;let val=0.72+0.28*Math.sin(fu*Math.PI);val*=0.85+0.15*fv;val*=0.92+hash(c,Math.floor(v*rows))*0.1;return[val,val*0.96,val*0.92];}),
 wood:procTex(256,(u,v)=>{const pl=Math.floor(u*5),g=pfbm(u*5*2,v*1.2,10,pl+2,4);let val=0.78+0.18*Math.sin((u*5*12+g*6)*TAU*0.5)*0.5+hash(pl,1)*0.08;if((u*5)%1<0.04)val*=0.6;return[val,val*0.94,val*0.88];}),
 leaf:procTex(128,(u,v)=>{const val=0.7+pfbm(u*12,v*12,12,51,3)*0.38;return[val*0.95,val,val*0.9];}),
 bark:procTex(128,(u,v)=>{const val=0.68+pfbm(u*14,v*3,14,61,4)*0.42;return[val,val*0.95,val*0.9];}),
 // detalle del suelo por zonas (ver terrainMat): roca, hierba, grava y tierra cuarteada
 rock:procTex(256,(u,v)=>{const b=pfbm(u*6,v*6,6,81,5),c=Math.abs(pnoise(u*10,v*10,10,83)-0.5),c2=Math.abs(pnoise(u*22,v*22,22,85)-0.5);let val=0.66+b*0.36;if(c<0.025)val*=0.62;if(c2<0.018)val*=0.78;return[val,val*0.98,val*0.95];}),
 grass:procTex(256,(u,v)=>{const a=pnoise(u*96,v*18,96,91),b=pnoise(u*20,v*96,20,93),c=pfbm(u*8,v*8,8,95,3);const val=0.68+Math.max(a,b)*0.34+c*0.12;return[val*0.9,val,val*0.74];}),
 gravel:procTex(256,(u,v)=>{const N=26,cu=u*N,cv=v*N;let best=9,sh=0;for(let dj=-1;dj<=1;dj++)for(let di=-1;di<=1;di++){const ci=Math.floor(cu)+di,cj=Math.floor(cv)+dj,a=((ci%N)+N)%N,b=((cj%N)+N)%N,px=ci+hash(a,b*7+1),py=cj+hash(a*3+5,b),r=0.22+hash(a+9,b+4)*0.25,d=Math.hypot(cu-px,cv-py)/r;if(d<best){best=d;sh=((cu-px)+(cv-py))/r;}}
   let val=0.8+(pnoise(u*60,v*60,60,97)-0.5)*0.1;if(best<1)val=best>0.82?0.6:0.92-sh*0.07+hash(Math.floor(cu),Math.floor(cv))*0.08;return[val,val*0.97,val*0.92];}),
 cracks:procTex(256,(u,v)=>{const N=12,cu=u*N,cv=v*N;let f1=9,f2=9;for(let dj=-1;dj<=1;dj++)for(let di=-1;di<=1;di++){const ci=Math.floor(cu)+di,cj=Math.floor(cv)+dj,a=((ci%N)+N)%N,b=((cj%N)+N)%N,d=Math.hypot(cu-ci-hash(a,b+3),cv-cj-hash(a+7,b));if(d<f1){f2=f1;f1=d;}else if(d<f2)f2=d;}
   let val=0.9+(pfbm(u*12,v*12,12,99,3)-0.5)*0.12;const w=pfbm(u*20,v*20,20,101,2);if(f2-f1<0.02+w*0.025)val*=0.8+w*0.12;return[val,val*0.97,val*0.93];}),
 ground:procTex(256,(u,v)=>{const big=pfbm(u*4,v*4,4,71,4),fine=pnoise(u*64,v*64,64,7),peb=Math.pow(pnoise(u*40,v*40,40,9),6);let val=0.8+big*0.18+fine*0.06-peb*0.25;return[val,val*(0.98+big*0.03),val*0.95];})
};
// proyección triplanar en un MeshLambertMaterial (con o sin instancias); 'scale' son los metros que ocupa la textura; flat: solo desde arriba (terreno)
// relieve de detalle (212): la textura se «graba» con la luz del sol: más clara donde sube hacia el sol, más oscura donde baja
const GFXU={uLd:{value:LIGHTDIR},uEmb:{value:1.0}};
function triplanar(mat,tex,scale,flat){
  mat.map=tex;mat.customProgramCacheKey=()=>'tp'+(flat?'f':'')+(mat.userData.grime?'g':'');mat.userData.tpScale=1/scale;
  mat.onBeforeCompile=sh=>{sh.uniforms.tpScale={value:mat.userData.tpScale};sh.uniforms.uLd=GFXU.uLd;sh.uniforms.uEmb=GFXU.uEmb;
    sh.vertexShader='varying vec3 vTpPos;\nvarying vec3 vTpNor;\n'+sh.vertexShader.replace('#include <project_vertex>','#include <project_vertex>\nvec4 tpw=vec4(transformed,1.0);vec3 tpn=objectNormal;\n#ifdef USE_INSTANCING\ntpw=instanceMatrix*tpw;tpn=mat3(instanceMatrix)*tpn;\n#endif\ntpw=modelMatrix*tpw;vTpPos=tpw.xyz;vTpNor=normalize(mat3(modelMatrix)*tpn);'+(mat.userData.grime?'vec4 tpo=vec4(0.0,0.0,0.0,1.0);\n#ifdef USE_INSTANCING\ntpo=instanceMatrix*tpo;\n#endif\nvTpBase=(modelMatrix*tpo).y;':''));if(mat.userData.grime)sh.vertexShader='varying float vTpBase;\n'+sh.vertexShader;
    sh.fragmentShader='uniform float tpScale,uEmb;uniform vec3 uLd;\nvarying vec3 vTpPos;\nvarying vec3 vTpNor;\n'+sh.fragmentShader.replace('#include <map_fragment>',flat?
      'vec4 tc=texture2D(map,vTpPos.xz*tpScale);diffuseColor*=tc;':
      'vec3 tb=pow(abs(normalize(vTpNor)),vec3(4.0));tb/=(tb.x+tb.y+tb.z);vec4 tc=texture2D(map,vTpPos.zy*tpScale)*tb.x+texture2D(map,vTpPos.xz*tpScale)*tb.y+texture2D(map,vTpPos.xy*tpScale)*tb.z;vec3 pB=vTpPos+uLd*0.035/max(tpScale*3.0,0.2);vec4 tB=texture2D(map,pB.zy*tpScale)*tb.x+texture2D(map,pB.xz*tpScale)*tb.y+texture2D(map,pB.xy*tpScale)*tb.z;diffuseColor*=tc*(1.0+clamp((dot(tc.rgb,vec3(0.333))-dot(tB.rgb,vec3(0.333)))*uEmb*1.6,-0.22,0.22));'+(mat.userData.grime?'\n{float gh=vTpPos.y-vTpBase;float gn=fract(sin(dot(floor(vTpPos.xz*1.7+vTpPos.y*0.4),vec2(12.9898,78.233)))*43758.5453);float wav=0.55+0.25*sin(vTpPos.x*2.3+vTpPos.z*1.9)+0.2*gn;float damp=(1.0-smoothstep(0.0,wav,gh))*step(abs(normalize(vTpNor).y),0.6);diffuseColor.rgb*=1.0-damp*0.28;diffuseColor.rgb=mix(diffuseColor.rgb,diffuseColor.rgb*vec3(0.92,0.9,0.84),smoothstep(0.55,0.95,gn)*0.25);}':''));if(mat.userData.grime)sh.fragmentShader='varying float vTpBase;\n'+sh.fragmentShader;};
  mat.needsUpdate=true;return mat;}
const ROLE_TEX={wall:['plaster',5],plaster:['plaster',5],brick:['brick',2.6],roof:['tile',3],foliage:['leaf',2.2],travertine:['stone',3.4],socle:['stone',2.6],stone:['stone',2],bark:['bark',1.6],wood:['wood',2],marble:['marble',4],granite:['marble',3],vine:['leaf',1.5]};
const WHITE_ROLE={},ROLE_MAT={};
const GRIME_ROLES=['wall','plaster','brick','socle'];   // paredes con historia (217): humedad que sube del suelo y manchas
function whiteRole(role){const t=ROLE_TEX[role];if(!t)return WHITE_M;if(!WHITE_ROLE[role]){WHITE_ROLE[role]=triplanar(new THREE.MeshLambertMaterial({color:0xffffff}),PTEX[t[0]],t[1]);if(GRIME_ROLES.includes(role))WHITE_ROLE[role].userData.grime=1;}return WHITE_ROLE[role];}
function roleMat(role){const c=ROLE_C[role]||'#999999',t=ROLE_TEX[role];if(!t)return lam(c);if(!ROLE_MAT[role]){ROLE_MAT[role]=triplanar(new THREE.MeshLambertMaterial({color:c}),PTEX[t[0]],t[1]);if(GRIME_ROLES.includes(role))ROLE_MAT[role].userData.grime=1;}return ROLE_MAT[role];}
// los mapas y escalas del suelo son uniformes compartidos (TERR_U): 209 los cambia por los escaneos de Poly Haven cuando llegan
const TERR_U={uLd:GFXU.uLd,uEmb:GFXU.uEmb,tpScale:{value:1/9},groundMap:{value:PTEX.ground},rockMap:{value:PTEX.rock},grassMap:{value:PTEX.grass},gravMap:{value:PTEX.gravel},crackMap:{value:PTEX.cracks},rS:{value:0.2},hS:{value:0.6},vS:{value:0.42},cS:{value:0.11},cShK:{value:0},cShC:{value:0.6},cShO:{value:new THREE.Vector2()},uWet:{value:0},uWetSky:{value:new THREE.Color('#b8c4cc')}};
function terrainMat(){const m=new THREE.MeshLambertMaterial({vertexColors:true,color:'#e2c99e'});TERR_MATS.push(m);triplanar(m,PTEX.ground,9,true);m.customProgramCacheKey=()=>'terr2';
  // el suelo cambia según el sitio: roca en las pendientes, hierba donde el color es verde, grava y tierra cuarteada a manchas,
  // y grandes manchas de color (tierra roja, zonas más claras u oscuras) para que no se repita la misma textura cada 9 m
  m.onBeforeCompile=sh=>{Object.assign(sh.uniforms,TERR_U);
    sh.vertexShader='varying vec3 vTpPos;\nvarying vec3 vTpNor;\n'+sh.vertexShader.replace('#include <project_vertex>','#include <project_vertex>\nvec4 tpw=modelMatrix*vec4(transformed,1.0);vTpPos=tpw.xyz;vTpNor=normalize(mat3(modelMatrix)*objectNormal);');
    sh.fragmentShader='uniform float tpScale,rS,hS,vS,cS,uEmb,cShK,cShC,uWet;uniform vec2 cShO;uniform vec3 uWetSky;uniform vec3 uLd;uniform sampler2D groundMap,rockMap,grassMap,gravMap,crackMap;\nvarying vec3 vTpPos;\nvarying vec3 vTpNor;\n'+
     'float tH(vec2 p){p=mod(p,289.0);return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}\nfloat tV(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.0-2.0*f);return mix(mix(tH(i),tH(i+vec2(1.0,0.0)),f.x),mix(tH(i+vec2(0.0,1.0)),tH(i+vec2(1.0,1.0)),f.x),f.y);}\n'+
     sh.fragmentShader.replace('#include <map_fragment>',[
      'vec2 wp=vTpPos.xz;float m1=tV(wp*0.006),m2=tV(wp*0.021+3.7)*0.7+tV(wp*0.06+9.1)*0.3,m3=tV(wp*0.08+11.3);',
      'vec2 rw=mat2(0.8,-0.6,0.6,0.8)*wp;vec3 col=mix(texture2D(groundMap,wp*tpScale).rgb,texture2D(groundMap,rw*tpScale*0.31).rgb,0.3+0.3*m3);',   // dos escalas giradas: sin repetición visible
      'vec3 nn=abs(normalize(vTpNor));float slope=1.0-nn.y;',
      'vec3 rk=nn.x>nn.z?texture2D(rockMap,vTpPos.zy*rS).rgb:texture2D(rockMap,vTpPos.xy*rS).rgb;rk=mix(rk,texture2D(rockMap,wp*rS).rgb,nn.y);',
      '#ifdef USE_COLOR\nfloat green=smoothstep(0.0,0.05,vColor.g-vColor.r*0.93);\n#else\nfloat green=0.0;\n#endif',
      'float rockW=smoothstep(0.2,0.48,slope+(m2-0.5)*0.22);',
      'float grassW=green*(0.5+0.5*m3)*(1.0-rockW);',
      'float dry=(1.0-green)*(1.0-rockW);float gravW=dry*smoothstep(0.62,0.78,m2)*0.5;float crackW=dry*smoothstep(0.7,0.88,m1)*(1.0-gravW)*0.25;',
      'col=mix(col,texture2D(gravMap,wp*vS).rgb,gravW);col=mix(col,texture2D(crackMap,wp*cS).rgb,crackW);col=mix(col,texture2D(grassMap,wp*hS).rgb,grassW*0.8);col=mix(col,rk,rockW);',
      '{vec2 eo=normalize(uLd.xz+vec2(1e-4))*0.012/tpScale;float eA=dot(texture2D(groundMap,wp*tpScale).rgb,vec3(0.333)),eB=dot(texture2D(groundMap,(wp+eo)*tpScale).rgb,vec3(0.333));col*=1.0+clamp((eA-eB)*uEmb*(1.6-uLd.y),-0.3,0.3)*(1.0-rockW);}',   // relieve (212)
      'col*=0.86+0.26*m1;',   // manchas grandes más claras u oscuras
      'col=mix(col,col*vec3(1.08,0.95,0.84),smoothstep(0.55,0.82,m2)*0.55*dry);',   // tierra rojiza (terra rossa) a manchas
      'col=mix(col,col*vec3(0.9,0.97,1.0),smoothstep(0.62,0.88,m3)*0.25);',
      'if(cShK>0.0){vec2 cq=wp*0.0045+cShO*60.0;float cn=tV(cq)*0.62+tV(cq*2.7+5.3)*0.38;col*=1.0-cShK*smoothstep(cShC,cShC+0.14,cn);}',   // sombras de nubes (214)
      'if(uWet>0.0){float flat0=smoothstep(0.82,0.97,nn.y);float pd=uWet*flat0*smoothstep(0.6,0.68,tV(wp*0.33+7.1))*(1.0-rockW)*(1.0-grassW);col*=1.0-uWet*0.28*(1.0-grassW*0.5);vec3 vd=normalize(cameraPosition-vTpPos);float fr=pow(1.0-clamp(vd.y,0.0,1.0),3.0);col=mix(col,uWetSky*0.9,clamp(pd*(0.45+0.5*fr)+uWet*flat0*fr*0.12,0.0,0.8));}',   // suelo mojado y charcos (217)
      'diffuseColor.rgb*=col;'].join('\n'));};
  m.needsUpdate=true;return m;}   // tinte cálido: compensa la desaturación del mapeo tonal
// materiales de los edificios
triplanar(M.marble,PTEX.marble,4);triplanar(M.marbleShade,PTEX.marble,4);triplanar(M.stone,PTEX.stone,3);triplanar(M.limestone,PTEX.stone,3);
triplanar(M.tile,PTEX.tile,3);triplanar(M.wood,PTEX.wood,2);
triplanar(TRAV,PTEX.stone,3.6);triplanar(TRAV2,PTEX.stone,3.6);triplanar(BRICK,PTEX.brick,2.6);triplanar(PLAST,PTEX.plaster,5);triplanar(TUFA,PTEX.stone,3);
triplanar(RING_M,PTEX.stone,3);
for(const c of['#e8dfcc','#e6dcc6','#e3d8c2','#d9c7a8'])triplanar(lam(c),PTEX.plaster,5);   // enlucidos de casas griegas, escuelas y palestra
// luz: mapeo tonal filmico (los blancos ya no se queman), sombras más nítidas y amplias
renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.05;
{const sm=2048;sun.shadow.mapSize.set(sm,sm);}   // 4096 costaba mucho en escritorio y apenas se notabaObject.assign(sun.shadow.camera,{left:-130,right:130,top:130,bottom:-130,far:700});sun.shadow.camera.updateProjectionMatrix();sun.shadow.bias=-0.0005;sun.shadow.normalBias=0.5;

// ============================================================ «La escuela de Atenas» de Rafael: biblioteca, sueño en la Academia y diálogo libre con Platón
let RAFAEL_SRC='';   // se rellena al llegar datos/rafaelimg.txt (más abajo, con la imagen de Roma)
// figuras del fresco: [id, nombre, x %, y %, texto]
const RAF_FIG=[
 ['platon',_t(85,'Platón'),48.4,58,_t(7305,'Con los rasgos de Leonardo da Vinci, señala al cielo y lleva el <i>Timeo</i>: para él lo verdaderamente real son las Ideas, eternas, que solo capta la razón. En el 386 a.C. tiene unos 42 años y acaba de fundar la Academia.')],
 ['aristoteles',_t(7306,'Aristóteles'),54.3,60,_t(7307,'Lleva la <i>Ética</i> y tiende la mano hacia la tierra: el conocimiento empieza por observar las cosas concretas. En el 386 a.C. aún no ha nacido: nacerá en Estagira en el 384 y entrará en la Academia en el 367, con 17 años.')],
 ['socrates',_t(5575,'Sócrates'),35,57,_t(7308,'De verde oliva, de perfil, cuenta argumentos con los dedos: es el método socrático, preguntar hasta que el otro descubre lo que no sabe. Fue condenado a muerte en el 399 a.C.: en el año del juego lleva trece años muerto.')],
 ['alcibiades',_t(7309,'Alcibíades o Jenofonte'),22.3,58,_t(7310,'El joven con casco y armadura que escucha a Sócrates. Suele identificarse con Alcibíades, el brillante y temerario discípulo de Sócrates (muerto en el 404), o con Jenofonte, otro discípulo, militar y escritor, que vive en el 386.')],
 ['epicuro',_t(7311,'Epicuro'),10.5,62,_t(7312,'Con una corona de pámpanos, quizá Epicuro (341-270 a.C.), que enseñará que la felicidad es la ausencia de dolor y de miedo. Nacerá 45 años después del año del juego.')],
 ['hipatia',_t(7313,'¿Hipatia?'),26.2,70,_t(7314,'La figura de blanco que mira al espectador. La tradición moderna la llama Hipatia, matemática y filósofa de Alejandría asesinada en el 415 d.C.; otros creen que es un joven, quizá Francesco Maria della Rovere. No hay ningún documento de la época que lo confirme.')],
 ['pitagoras',_t(7315,'Pitágoras'),19.5,82,_t(7316,'Escribe en un libro mientras un muchacho le sostiene una tablilla con las proporciones de la armonía musical. Pitágoras de Samos (c. 570-495 a.C.) enseñó que el universo está ordenado por números. En el 386, sus seguidores, como Arquitas de Tarento, siguen activos.')],
 ['heraclito',_t(7317,'Heráclito'),42,83,_t(7318,'Apoyado en un bloque, escribe pensativo. Rafael le dio los rasgos de Miguel Ángel y lo añadió cuando la obra estaba casi terminada. Heráclito de Éfeso (c. 540-480 a.C.) decía que todo fluye y que la guerra es el padre de todas las cosas.')],
 ['diogenes',_t(7319,'Diógenes'),58.8,79,_t(7320,'Tumbado en la escalinata, medio desnudo, con una copa: Diógenes el cínico, que vivía en una tinaja y despreciaba las convenciones. En el 386 a.C. es un muchacho de unos 26 años en Sinope; llegará a Atenas años después.')],
 ['euclides',_t(7321,'Euclides o Arquímedes'),86.7,86,_t(7322,'Se inclina con un compás sobre una pizarra, rodeado de alumnos. Tiene los rasgos del arquitecto Bramante. Euclides (c. 300 a.C.) escribirá los <i>Elementos</i> de geometría, el libro de matemáticas más leído de la historia.')],
 ['zoroastro',_t(7323,'Zoroastro'),90,68,_t(7324,'Sostiene la esfera celeste, con las estrellas. Zoroastro o Zaratustra, el profeta persa, simboliza aquí la astronomía y la sabiduría oriental.')],
 ['ptolomeo',_t(7325,'Ptolomeo'),95.5,76,_t(7326,'De espaldas, con una corona y el globo terrestre: Claudio Ptolomeo (siglo II d.C.), astrónomo y geógrafo de Alejandría, al que Rafael confunde con los reyes Ptolomeos de Egipto.')],
 ['rafael',_t(7327,'Rafael'),98.2,63,_t(7328,'Con un gorro oscuro, mira directamente al espectador: es el autorretrato de Rafael Sanzio (1483-1520), que se pintó entre los sabios. Junto a él, su colega Sodoma.')],
 ['apolo',_t(5551,'Apolo'),17.5,30,_t(7329,'En la hornacina de la izquierda, el dios Apolo con su lira: la música, la poesía y la armonía.')],
 ['atenea',_t(7330,'Atenea (Minerva)'),84.5,32,_t(7331,'En la hornacina de la derecha, Atenea, la diosa de la sabiduría, con el escudo de la Gorgona.')]
];
ESSAYS.push({id:'rafael',cat:_t(1867,'Contexto'),title:_t(7332,'«La escuela de Atenas» de Rafael'),body:[
 _t(7333,'Rafael pintó este fresco entre 1509 y 1511 en la Estancia de la Signatura del Palacio Vaticano, por encargo del papa Julio II. Mide unos 5 por 7,7 metros y representa la Filosofía: frente a él está la <i>Disputa del Sacramento</i>, que representa la Teología. Toca cada figura para saber quién es (muchas identificaciones son tradicionales y se discuten).'),
 '@@RF@@',
 _t(7334,'Es una reunión imposible: junta a pensadores separados por casi dos mil años, en un edificio que nunca existió en Atenas. Su arquitectura, con bóvedas de casetones, se inspira en el proyecto de Bramante para la nueva basílica de San Pedro y en las basílicas romanas, como la de Majencio (siglo IV d.C.). En el año del juego, el 386 a.C., Platón tiene unos 42 años y acaba de fundar la Academia; Sócrates ha muerto hace trece años, y Aristóteles todavía no ha nacido.'),
 _t(7335,'En el juego, junto a la Academia hay una estela que te deja dormir bajo los olivos y soñar con el fresco: allí puedes hablar con sus figuras. Y en la Academia, si el juego tiene acceso a Claude, puedes discutir libremente con Platón.')],
 src:{a:[_t(7336,'Giorgio Vasari, Vidas de los artistas (1550), vida de Rafael')],m:[_t(7337,'K. Hall (ed.), Raphael’s School of Athens (1997)'),_t(7338,'G. Most, Leggere Raffaello. La Scuola di Atene e il suo pre-testo (1999)')],n:[_t(7339,'Rafael murió en 1520: la obra es de dominio público. La identificación de muchas figuras, incluida la de Hipatia, es moderna y discutida.')]}});
function rfHTML(){return RAFAEL_SRC?'<div class="rf"><img src="'+RAFAEL_SRC+_t(7340,'" alt="La escuela de Atenas, de Rafael">')+RAF_FIG.map((f,i)=>'<button class="rf-spot" data-rf="'+i+'" style="left:'+f[2]+'%;top:'+f[3]+'%" aria-label="'+f[1]+'" title="'+f[1]+'"></button>').join('')+_t(7341,'</div><div class="rf-info" id="rfInfo">Toca un punto del cuadro.</div>'):_t(7342,'<i>(La imagen del fresco no está disponible en esta copia.)</i>');}
document.addEventListener('click',e=>{const b=e.target.closest&&e.target.closest('.rf-spot');if(!b)return;const f=RAF_FIG[+b.dataset.rf],box=document.getElementById('rfInfo');if(box)box.innerHTML='<b>'+f[1]+'.</b> '+f[4];document.querySelectorAll('.rf-spot').forEach(s=>s.classList.toggle('on',s===b));});

// ------------------------------------------------------------ el sueño: la sala del fresco, a 600 m de altura sobre los campos junto a la Academia
const DREAM={x:0,z:0,y:600,on:false};
function buildRaphaelHall(){
  const X=ACADEMY.x+260,Z=ACADEMY.z+60,Y=600,UP=1.5;Object.assign(DREAM,{x:X,z:Z});
  const g=grp(X,Y,Z,0),wall=M.marbleShade,mar=M.marble;DREAM.g=g;g.visible=false;   // oculta mientras no se sueña: desde la ciudad se veía flotando en el cielo
  // suelo delantero con el dibujo de mármoles del fresco, escalinata y suelo superior
  const flo=canvasTex(256,256,(x)=>{x.fillStyle='#d8cbb4';x.fillRect(0,0,256,256);x.fillStyle='#8a5a4a';x.fillRect(16,16,224,224);x.fillStyle='#efe6d4';x.fillRect(40,40,176,176);x.fillStyle='#8a5a4a';x.fillRect(64,64,128,128);x.fillStyle='#efe6d4';x.fillRect(96,96,64,64);});
  const fl=new THREE.Mesh(new THREE.BoxGeometry(40,1,20),[mar,mar,texMat(flo,6,3),mar,mar,mar]);fl.position.set(0,-0.5,14);fl.receiveShadow=true;g.add(fl);addPlat(X,Z+14,40,20,0,Y);
  for(let i=0;i<5;i++){const top=(i+1)*0.3,zc=4-i*0.45;box(38,top+1,0.46,mar,0,top/2-0.5,zc,g);addPlat(X,Z+zc,38,0.46,0,Y+top);}
  box(40,UP+1,60,mar,0,UP/2-0.5,-28.3,g);addPlat(X,Z-28.3,40,60,0,Y+UP);
  // muros laterales con pilastras, hornacinas y estatuas
  for(const s of[-1,1]){box(2,22,82,wall,s*19,11,-17,g);addSeg(X+s*18,Z-58,X+s*18,Z+24,0.3);
    for(let k=0;k<7;k++){const zc=-50+k*11;box(1.8,18,1.8,mar,s*17.6,UP+9,zc,g);box(2.2,0.8,2.2,mar,s*17.6,UP+18.4,zc,g);
      if(k<6){box(0.3,7,4,lam('#c9bfa9'),s*17.9,UP+6.5,zc+5.5,g);const st=makePerson({chiton:'#ece4d6',himation:'#ece4d6',skin:'#ece4d6',hair:'#ece4d6',female:k===4,attrRoles:{cloth:mar,drape:mar,skin:mar,hair:mar,sandal:mar,eye:mar}});st.scale.setScalar(k===5?1.9:1.3);st.position.set(s*17.2,UP+(k===5?1.2:3.2),zc+5.5);st.rotation.y=-s*Math.PI/2;g.add(st);if(k===5)box(1.6,1.2,2,mar,s*17.2,UP+0.6,zc+5.5,g);}}}
  box(40,1.2,1.2,mar,0,UP+18.2,-56,g);
  // bóveda de cañón con casetones y arcos fajones, como en el fresco
  const cof=canvasTex(128,128,(x)=>{x.fillStyle='#bfb29a';x.fillRect(0,0,128,128);for(let i=0;i<2;i++)for(let j=0;j<2;j++){const o=[i*64+6,j*64+6];x.fillStyle='#8e826c';x.fillRect(o[0],o[1],52,52);x.fillStyle='#a69a82';x.fillRect(o[0]+8,o[1]+8,36,36);x.fillStyle='#7c715d';x.fillRect(o[0]+16,o[1]+16,20,20);}});
  const vg=new THREE.CylinderGeometry(18,18,82,40,1,true,Math.PI/2,Math.PI);vg.rotateX(Math.PI/2);const vm=new THREE.MeshLambertMaterial({map:cof,side:THREE.DoubleSide});cof.repeat.set(10,12);
  const vault=new THREE.Mesh(vg,vm);vault.position.set(0,UP+18.8,-17);g.add(vault);
  for(const zc of[-50,-28,-6,16]){const t=new THREE.Mesh(new THREE.TorusGeometry(17.6,0.7,8,32,Math.PI),mar);t.position.set(0,UP+18.8,zc);g.add(t);}
  // muro del fondo con un gran arco abierto al cielo, y otro arco más allá
  for(const[zc,w,r,hs]of[[-57,40,7,9],[-76,30,5,7]]){const sh=new THREE.Shape();const H2=r+hs+18;sh.moveTo(-w/2,0);sh.lineTo(-w/2,H2);sh.lineTo(w/2,H2);sh.lineTo(w/2,0);sh.lineTo(r,0);sh.lineTo(r,hs);sh.absarc(0,hs,r,0,Math.PI,false);sh.lineTo(-r,0);sh.lineTo(-w/2,0);
    const m=new THREE.Mesh(new THREE.ExtrudeGeometry(sh,{depth:2,bevelEnabled:false,curveSegments:16}),wall);m.position.set(0,UP,zc-1);g.add(m);addSeg(X-w/2,Z+zc,X-r,Z+zc,1);addSeg(X+r,Z+zc,X+w/2,Z+zc,1);}
  box(30,UP+1,20,mar,0,UP/2-0.5,-67,g);addPlat(X,Z-67,30,20,0,Y+UP);for(const s of[-1,1]){box(2,18,20,wall,s*14,UP+9,-67,g);addSeg(X+s*14,Z-77,X+s*14,Z-57,0.5);}addSeg(X-15,Z-77,X+15,Z-77,0.5);
  // balaustrada delantera (debajo, el vacío)
  box(40,1,0.6,mar,0,0.5,23.7,g);addSeg(X-20,Z+23.7,X+20,Z+23.7,0.4);
  footprints.push({x:X,z:Z-20,w:40,d:90,a:0,c:'#efe7d8',name:_t(7343,'Sueño: la escuela de Atenas'),reserve:true});
  // figuras secundarias del fresco
  const extra=[['#c44a2a','#e8d9b0',-6,-2],['#6a8a4a','#e2d6c0',-9,-4],['#3d6aa8','#d8c9a8',8,-3],['#c97a2a','#efe6d2',11,-1],['#8a5a8a','#e2d6c0',-13,6],['#a8392b','#efe6d2',14,8],['#4f6a7d','#e8dfcc',3,-6],['#7a6a3a','#d7c9ab',-3,-7]];
  for(const[hi,ch,lx,lz]of extra){const p=makePerson({chiton:ch,himation:hi,beard:R()<0.7,hair:pick(['#8d8a85','#3e2c1f','#5b4532'])});p.position.set(X+lx,floorAt(X+lx,Z+lz),Z+lz);p.rotation.y=Math.atan2(-lx,8-lz)*0.6;scene.add(p);}
  // posiciones de los filósofos (como en el fresco: Platón y Aristóteles arriba, en el centro)
  const P=(lx,lz,r)=>[X+lx,Z+lz,r];
  Object.assign(NPC_POS,{r_platon:P(-1.2,-2,0),r_aristoteles:P(1.2,-2,0),r_socrates:P(-8,0,Math.PI/2),r_alcibiades:P(-10.5,0.6,-Math.PI/2),r_pitagoras:P(-9,12,0.4),r_heraclito:P(-3,11,0.2),
    r_diogenes:P(3,4.6,-0.3),r_euclides:P(10,13,-0.6),r_ptolomeo:P(15,10,-1.2),r_zoroastro:P(13.5,8.5,-1),r_hipatia:P(-12,9,0.6),r_epicuro:P(-15,7,0.5),r_rafael:P(16,15,-0.8)});
  place('ro_sueno_salida',_t(2982,'Despertar'),'ΕΓΡΗΓΟΡΣΙΣ',_t(7344,'Estás dentro de un sueño: la sala que Rafael pintó en el Vaticano en 1509-1511, con los sabios de dos mil años reunidos en una misma escalinata. Habla con ellos. Cuando quieras, toca esta estela para despertar bajo los olivos de la Academia.'),X+4,Z+20,Math.PI);PLACES[PLACES.length-1].go='academia';
  const sp=toW(18,40,ACADEMY.x,ACADEMY.z,0);
  place('sueno',_t(7345,'Los olivos de Academo'),'ΟΝΕΙΡΟΣ',_t(7346,'Bajo los olivos sagrados del bosque de Academo, donde Platón pasea con sus discípulos, se está bien a la sombra. Dicen que quien duerme aquí sueña con los sabios del pasado y del futuro. Toca esta estela para dormir y soñar con «La escuela de Atenas», el fresco que Rafael pintará dentro de diecinueve siglos.'),sp[0],sp[1],0);PLACES[PLACES.length-1].go='sueno';
}
// posturas del fresco (después de placeNPCs)
function poseDream(){
  const pose={r_diogenes:(g)=>{g.rotation.z=Math.PI/2;g.position.y+=0.3;},r_pitagoras:(g)=>{g.position.y-=0.55;if(g.userData.arms)g.userData.arms[1].rotation.x=-1;},r_heraclito:(g)=>{g.position.y-=0.6;g.rotation.x=0.15;if(g.userData.arms){g.userData.arms[0].rotation.x=-1.5;g.userData.arms[1].rotation.x=-0.9;}},
    r_euclides:(g)=>{g.rotation.x=0.5;if(g.userData.arms)g.userData.arms[1].rotation.x=-1.5;},r_platon:(g)=>{if(g.userData.arms)g.userData.arms[1].rotation.x=-2.9;},r_aristoteles:(g)=>{if(g.userData.arms)g.userData.arms[1].rotation.x=-1.4;},
    r_socrates:(g)=>{if(g.userData.arms){g.userData.arms[0].rotation.x=-1.2;g.userData.arms[1].rotation.x=-1.2;}},
    r_ptolomeo:(g)=>{const s=new THREE.Mesh(new THREE.SphereGeometry(0.32,16,12),lam('#6f8a6a'));s.position.set(0,1.35,0.45);g.add(s);},r_zoroastro:(g)=>{const s=new THREE.Mesh(new THREE.SphereGeometry(0.32,16,12),lam('#3a4f8a'));s.position.set(0,1.35,0.45);g.add(s);}};
  for(const n of npcObjs){if(!/^r_/.test(n.data.id))continue;n.noTurn=true;const f=pose[n.data.id];if(f)f(n.g);}
}
function dreamTravel(to){
  closeDialog();ui='voyage';if(MOUNT.riding)dismount();if(MOUNT.g){MOUNT.g.visible=false;MOUNT.st='away';}
  const v=$('voyage');v.querySelector('.vt').textContent=to==='sueno'?_t(7347,'Te quedas dormido…'):_t(7348,'Despiertas…');v.classList.toggle('land',true);
  v.querySelector('.vs').textContent=to==='sueno'?_t(7349,'Bajo los olivos de Academo, el rumor de las hojas te adormece.'):_t(7350,'El sol se filtra entre los olivos. ¿Ha sido solo un sueño?');
  v.querySelector('.vf').textContent=to==='sueno'?_t(7351,'Rafael pintó «La escuela de Atenas» en 1509-1511, diecinueve siglos después de tu viaje.'):_t(7352,'Platón enseñará en la Academia hasta su muerte, en el 348/347 a.C.');
  v.hidden=false;requestAnimationFrame(()=>v.classList.add('show'));
  setTimeout(()=>{if(to==='sueno'){player.x=DREAM.x;player.z=DREAM.z+18;player.yaw=0;}else{const p=toW(18,46,ACADEMY.x,ACADEMY.z,0);player.x=p[0];player.z=p[1];player.yaw=Math.PI;}
    player.feet=floorAt(player.x,player.z);player.camY=player.feet+player.eye;player.vy=0;player.pitch=0.05;curZone=null;DREAM.on=to==='sueno';if(DREAM.g)DREAM.g.visible=DREAM.on;
    v.classList.remove('show');setTimeout(()=>{v.hidden=true;ui='play';},700);},2600);
}

// imagen real (no generada) en la pantalla de inicio: la Loba Capitolina en Roma, «La escuela de Atenas» en Atenas
let LOBA_SRC='';
const LOBA_CAP='<b>El Vesubio en erupción, de noche</b>Pintura de época moderna (siglos XVIII-XIX), con el faro del puerto de Nápoles. En el año 79, hace solo uno, el volcán sepultó Pompeya y Herculano; Plinio el Viejo murió al acercarse para verlo y ayudar a los vecinos (Plinio el Joven, Cartas VI 16).';
function stImgFill(){const f=document.getElementById('stImg');if(!f)return;const roma=typeof MODE!=='undefined'&&MODE==='roma';const src=roma?LOBA_SRC:RAFAEL_SRC;if(!src){f.hidden=true;return;}
  f.querySelector('img').src=src;f.querySelector('img').alt=roma?'La Loba Capitolina con Rómulo y Remo':'La escuela de Atenas, de Rafael';
  f.querySelector('figcaption').innerHTML=roma?LOBA_CAP:'<b>La escuela de Atenas</b>Rafael la pintó en el Vaticano en 1509-1511, casi dos mil años después de tu partida: es una Atenas imaginada. En el centro, Platón, que en 386 a.C. empieza a enseñar en la Academia, y su futuro alumno Aristóteles. <i>Dominio público.</i>';f.hidden=false;}
setTimeout(stImgFill,0);
// las dos imágenes llegan aparte (en atenas.html, de datos/): al llegar, se ponen en la pantalla de inicio y en la presentación si ya estaban abiertas
for(const[id,set]of[['rafaelimg',v=>RAFAEL_SRC=v],['lobaimg',v=>LOBA_SRC=v]])datoGet(id).then(t=>{t=t.trim();if(t.length<100)return;set('data:image/jpeg;base64,'+t);
  try{stImgFill();const b=document.querySelector('#intro .ibg');if(b&&!/url\(["']?data:/.test(b.style.backgroundImage))b.style.backgroundImage='url('+((MODE==='roma')?LOBA_SRC:RAFAEL_SRC)+')';}catch(e){}});
// ============================================================ esferas de sueño: momentos míticos
// Cada esfera flota junto a un lugar; al tocarla se monta un escenario muy por encima de la ciudad (a 3000 m, donde
// la niebla oculta el mundo) y una cámara guiada recorre el episodio en escenas que se avanzan con E o Enter.
const EPI={cur:null,S:null,beat:0,t:0,spheres:[],cp:new THREE.Vector3(),ct:new THREE.Vector3(),snap:true,ret:null,saveH:10};
const EPI_TEX=(()=>{const c=document.createElement('canvas');c.width=c.height=64;const x=c.getContext('2d');const g=x.createRadialGradient(32,32,0,32,32,32);g.addColorStop(0,'rgba(235,245,255,1)');g.addColorStop(0.3,'rgba(150,190,255,0.55)');g.addColorStop(1,'rgba(120,150,255,0)');x.fillStyle=g;x.fillRect(0,0,64,64);return new THREE.CanvasTexture(c);})();
function epiDone(E){return!!(state.seen&&state.seen['ep:'+E.id]);}
function buildSpheres(){
  for(const E of EPISODES){if(E.mode!==MODE)continue;const p=E.at&&E.at();if(!p)continue;const[x,z]=freeSpot(p[0],p[1]);const gy=floorAt(x,z);
    const g=grp(x,gy+1.7,z,0);
    const core=new THREE.Mesh(new THREE.SphereGeometry(0.42,24,16),new THREE.MeshBasicMaterial({color:0xbfd8ff,transparent:true,opacity:0.5,depthWrite:false,fog:false}));g.add(core);
    const inner=new THREE.Mesh(new THREE.IcosahedronGeometry(0.2,1),new THREE.MeshBasicMaterial({color:0xffffff,wireframe:true,transparent:true,opacity:0.8,fog:false}));g.add(inner);
    const ring=new THREE.Mesh(new THREE.TorusGeometry(0.62,0.015,6,48),new THREE.MeshBasicMaterial({color:0xd9e6ff,transparent:true,opacity:0.7,fog:false}));g.add(ring);
    const halo=new THREE.Sprite(new THREE.SpriteMaterial({map:EPI_TEX,blending:THREE.AdditiveBlending,depthWrite:false,transparent:true,fog:false}));halo.scale.set(2.6,2.6,1);g.add(halo);
    const lb=labelSprite(E.name,_t(7353,'Esfera de sueño'));lb.position.y=1.05;lb.visible=false;g.add(lb);
    EPI.spheres.push({kind:'sphere',data:E,x,z,g,core,inner,ring,halo,lb,gy});
    if(epiDone(E))core.material.color.set(0x9fb0c8);}
}
// un sitio libre cerca (sin muros, sin agua)
function freeSpot(x,z){for(let r=0;r<40;r+=2)for(let k=0;k<(r?12:1);k++){const a=k/12*TAU,px=x+Math.cos(a)*r,pz=z+Math.sin(a)*r;if(floorAt(px,pz)<-0.5)continue;const q={x:px,z:pz};resolve(q,1.2);if(Math.hypot(q.x-px,q.z-pz)<0.01)return[px,pz];}return[x,z];}
function updateSpheres(dt,t){
  for(const s of EPI.spheres){const d=Math.hypot(s.x-player.x,s.z-player.z);s.g.visible=d<220;if(!s.g.visible)continue;s.lb.visible=d<14;
    s.g.position.y=s.gy+1.7+Math.sin(t*1.4+s.x)*0.12;s.inner.rotation.y=t*0.9;s.inner.rotation.x=t*0.5;s.ring.rotation.x=1.2+Math.sin(t*0.7)*0.3;s.ring.rotation.y=t*0.6;
    const f=1+Math.sin(t*2.3+s.z)*0.08;s.halo.scale.set(2.6*f,2.6*f,1);}
}
function openSphere(s){
  const E=s.data,done=epiDone(E);dlg={n:null};ui='dialog';releasePointer();
  $('dGlyph').textContent='Ο';setName(E.name);$('dTitle').textContent=(E.hist?_t(7354,'Esfera de sueño · momento histórico'):_t(7355,'Esfera de sueño · momento mítico'))+(done?_t(7356,' · ya lo has soñado'):'');
  $('dBody').innerHTML=_t(7357,'<p>Una esfera de luz flota en el aire, tibia como el aliento de alguien dormido. Dentro se mueven sombras: ')+E.teaser+'</p><p class="sub">'+(E.hist?_t(7358,'Esto pasó de verdad: es historia, no mito, aunque la conocemos por lo que contaron los autores antiguos.'):_t(7359,'Es un mito, no historia: lo que contaban los antiguos sobre su propio pasado.'))+'</p>';
  const o=$('dOpts');o.innerHTML='';let k=1;const add=(txt,fn,cls)=>{const b=document.createElement('button');if(cls)b.className=cls;b.innerHTML='<span class="n">'+(k++)+'</span><span>'+txt+'</span>';b.onclick=fn;o.appendChild(b);};
  add(done?_t(7360,'Volver a soñarlo'):_t(7361,'Tocar la esfera y soñar'),()=>epiStart(E),'quiz');add(_t(7362,'Ahora no'),closeDialog);
  $('dialog').hidden=false;setTimeout(()=>{const b=o.querySelector('button');b&&b.focus({preventScroll:true});},30);
}
// ------------------------------------------------------------ escenario
function stageKit(E){
  const o=E.origin?E.origin():[player.x,3000,player.z],ox=o[0],oy=o[1],oz=o[2],g=grp(ox,oy,oz,0);   // origin: escenas en el mundo real (la boda romana)
  const S={ox,oy,oz,g,a:{},
    ground(col,r){const m=new THREE.Mesh(new THREE.CircleGeometry(r||900,48),lam(col||'#7d8a52'));m.rotation.x=-Math.PI/2;m.receiveShadow=true;g.add(m);return m;},
    hill(x,z,r,h,col){const m=new THREE.Mesh(new THREE.SphereGeometry(1,24,12,0,TAU,0,Math.PI/2),lam(col||'#7b8a4e'));m.scale.set(r,h,r*0.8);m.position.set(x,0,z);m.receiveShadow=true;m.castShadow=true;g.add(m);return m;},
    water(x,z,w,d,a){const m=new THREE.Mesh(new THREE.PlaneGeometry(w,d),new THREE.MeshPhongMaterial({color:'#3f7a8a',shininess:80}));m.rotation.x=-Math.PI/2;m.rotation.z=a||0;m.position.set(x,0.05,z);g.add(m);return m;},
    tree(x,z,s,col){const t=new THREE.Group();t.position.set(x,0,z);const tr=new THREE.Mesh(new THREE.CylinderGeometry(0.15,0.25,3,6),lam('#5a4330'));tr.position.y=1.5;t.add(tr);
      const c=new THREE.Mesh(new THREE.SphereGeometry(1.8,10,8),lam(col||'#4f6b3a'));c.position.y=3.6;c.scale.y=0.8;c.castShadow=true;t.add(c);t.scale.setScalar(s||1);g.add(t);return t;},
    person(o,x,z,r){const p=makePerson(Object.assign({noVary:true},o));p.position.set(x,0,z);p.rotation.y=r||0;g.add(p);return p;},
    box(w,h,d,col,x,y,z){return box(w,h,d,typeof col==='string'?lam(col):col,x,y,z,g);},
    beast(kind,x,z,r){return makeBeast(kind,g,x,z,r);},
    bird(){const b=new THREE.Group(),m=lam('#2a2420');const bd=new THREE.Mesh(new THREE.SphereGeometry(0.25,8,6),m);bd.scale.set(0.8,0.6,1.6);b.add(bd);
      const wg=new THREE.BoxGeometry(1.4,0.04,0.45);wg.translate(0.7,0,0);const l=new THREE.Mesh(wg,m),r2=new THREE.Mesh(wg,m);r2.rotation.y=Math.PI;b.add(l);b.add(r2);b.userData.w=[l,r2];g.add(b);return b;}};
  return S;
}
// animales sencillos: lobo, buey, vaca, caballo, toro
function makeBeast(kind,parent,x,z,r){const b=new THREE.Group();b.position.set(x,0,z);b.rotation.y=r||0;parent.add(b);
  if(kind==='caballo'&&GLB.ok){b.userData.legs=animalGLB('A_horse',b,'#d8cfc0','#6b5a48');return b;}
  const big=kind!=='lobo',col=lam(kind==='lobo'?'#6b5d4f':kind==='vaca'?'#d8cbb4':kind==='toro'?'#2a2220':'#8a6a4a'),dk=lam(kind==='lobo'?'#3e342b':'#2e2420');
  const L=big?2.1:1.1,H=big?1.5:0.75,W=big?0.85:0.34;
  box(W,H*0.55,L,col,0,H*0.78,0,b);
  const hd=box(W*0.62,H*0.36,big?0.62:0.42,col,0,H*1.02,L/2+(big?0.25:0.18),b);if(kind==='lobo'){box(0.16,0.14,0.26,dk,0,H*0.97,L/2+0.48,b);for(const s of[-1,1])box(0.07,0.14,0.05,dk,s*0.08,H*1.24,L/2+0.16,b);}
  if(kind==='buey'||kind==='vaca'||kind==='toro'){for(const s of[-1,1]){const h=new THREE.Mesh(new THREE.ConeGeometry(0.07,0.5,6),lam('#e9e0cc'));h.position.set(s*0.34,H*1.22,L/2+0.2);h.rotation.z=-s*1.0;b.add(h);}}
  const legs=[];for(const[px,pz]of[[-1,-1],[1,-1],[-1,1],[1,1]]){const lg=new THREE.Group();lg.position.set(px*W*0.36,H*0.55,pz*L*0.38);const m=box(W*0.2,H*0.55,W*0.2,dk,0,-H*0.27,0,lg);b.add(lg);legs.push(lg);}
  const tl=box(0.08,0.08,big?0.7:0.5,dk,0,H*0.85,-L/2-0.25,b);tl.rotation.x=kind==='lobo'?0.7:1.2;
  b.userData.legs=legs;return b;}
function walkLegs(b,ph,amp){const l=b.userData.legs;if(!l)return;l.forEach((g,i)=>{g.rotation.x=Math.sin(ph+(i%2?Math.PI:0)+(i>1?Math.PI:0))*amp;});}
// mover a alguien de A a B entre los instantes t0 y t1, balanceando brazos o patas
function walkTo(o,a,b,t0,t1,t){const k=clamp((t-t0)/(t1-t0),0,1);o.position.x=lerp(a[0],b[0],k);o.position.z=lerp(a[1],b[1],k);
  if(k>0&&k<1){o.rotation.y=Math.atan2(b[0]-a[0],b[1]-a[1]);const ar=o.userData.arms;if(ar){ar[0].rotation.x=Math.sin(t*7)*0.4;ar[1].rotation.x=-Math.sin(t*7)*0.4;}walkLegs(o,t*8,0.5);}
  else{const ar=o.userData.arms;if(ar&&!o.userData.pose){ar[0].rotation.x*=0.9;ar[1].rotation.x*=0.9;}}return k;}
function epiFlash(){const f=$('epiFlash');f.classList.remove('go');void f.offsetWidth;f.classList.add('go');sfxThunder();}
function sfxThunder(){if(!aOK())return;const c=AUD.ctx,t=c.currentTime+0.15;const s=c.createBufferSource();s.buffer=AUD.noise;const f=c.createBiquadFilter();f.type='lowpass';f.frequency.value=140;s.connect(f).connect(envGain(t,0.7,0.05,2.2));s.start(t,Math.random());s.stop(t+2.6);}
// ------------------------------------------------------------ desarrollo
function epiStart(E){
  closeDialog();ui='voyage';releasePointer();if(MOUNT.riding)dismount();if(MOUNT.g){MOUNT.g.visible=false;MOUNT.st='away';}
  if(E.walk)return E.walk();
  const v=$('voyage');v.classList.add('land');v.querySelector('.vt').textContent=E.vt||_t(7363,'Tocas la esfera…');v.querySelector('.vs').textContent=E.name;v.querySelector('.vf').textContent=E.vf?E.vf:E.hist?_t(7364,'Un sueño de algo que pasó de verdad, tal como lo cuentan las fuentes antiguas.'):_t(7365,'Un sueño de lo que contaban los antiguos: no es historia, sino mito.');
  v.hidden=false;requestAnimationFrame(()=>v.classList.add('show'));
  setTimeout(()=>{EPI.ret={x:player.x,z:player.z,yaw:player.yaw,feet:player.feet};EPI.saveH=clock.h;
    const S=stageKit(E);EPI.S=S;EPI.cur=E;if(E.onStart)E.onStart();E.build(S);EPI.beat=-1;EPI.snap=true;$('hud').hidden=true;$('epi').hidden=false;ui='episode';epiBeat(0);
    v.classList.remove('show');setTimeout(()=>{v.hidden=true;},700);},1800);
}
function epiBeat(i){const E=EPI.cur;if(!E)return;if(i<0)return;if(i>=E.beats.length)return epiEnd(true);
  const prev=EPI.beat;EPI.beat=i;EPI.t=0;const B=E.beats[i];if(B.cut||prev<0)EPI.snap=true;if(B.enter)B.enter(EPI.S);
  clock.h=B.h!==undefined?B.h:E.h;updateSky();
  $('epiExit').innerHTML=E.exitLabel||_t(7366,'Despertar · Esc');
  $('epiT').textContent=E.name;$('epiN').textContent=(i+1)+' / '+E.beats.length;$('epiX').innerHTML=B.txt;
  $('epiNext').innerHTML=i===E.beats.length-1?(E.endLabel||_t(7367,'Despertar · E')):_t(7368,'Seguir · E');$('epiPrev').disabled=i===0;
}
function epiTick(dt,t){
  const E=EPI.cur,S=EPI.S;if(!E||!S)return;const B=E.beats[EPI.beat];EPI.t+=dt;
  const k=sstep(clamp(EPI.t/(B.d||10),0,1)),c0=B.camf?B.camf(EPI.t,S):B.cam,c1=B.camf?c0:(B.cam2||B.cam);
  const px=S.ox+lerp(c0[0],c1[0],k),py=S.oy+lerp(c0[1],c1[1],k),pz=S.oz+lerp(c0[2],c1[2],k),tx=S.ox+lerp(c0[3],c1[3],k),ty=S.oy+lerp(c0[4],c1[4],k),tz=S.oz+lerp(c0[5],c1[5],k);
  if(EPI.snap){EPI.cp.set(px,py,pz);EPI.ct.set(tx,ty,tz);EPI.snap=false;}else{const a=1-Math.exp(-dt*2.2);EPI.cp.lerp(_v3a.set(px,py,pz),a);EPI.ct.lerp(_v3a.set(tx,ty,tz),a);}
  camera.position.copy(EPI.cp);camera.lookAt(EPI.ct);
  if(B.upd)B.upd(EPI.t,dt,S);if(E.upd)E.upd(t,dt,S);
  clock.h=B.h!==undefined?B.h:E.h;STARS.visible=!B.storm;if(B.storm)SKY.uniforms.glow.value=0;
  player.x=S.ox;player.z=S.oz;player.feet=S.oy;player.vy=0;player.camY=S.oy+1.6;
  sun.position.set(S.ox+LIGHTDIR.x*250,S.oy+LIGHTDIR.y*250,S.oz+LIGHTDIR.z*250);sun.target.position.set(S.ox,S.oy,S.oz);
  skyMesh.position.copy(camera.position);STARS.position.copy(camera.position);
}
const _v3a=new THREE.Vector3();
function epiEnd(complete){
  const E=EPI.cur,S=EPI.S;if(!E)return;EPI.cur=null;EPI.S=null;
  scene.remove(S.g);if(E.onEnd)E.onEnd();
  $('epi').hidden=true;ui='voyage';STARS.visible=true;
  const v=$('voyage');v.classList.add('land');v.querySelector('.vt').textContent=E.vtEnd||_t(7348,'Despiertas…');v.querySelector('.vs').textContent=E.name;v.querySelector('.vf').textContent='';v.hidden=false;v.classList.add('show');
  const R=EPI.ret;player.x=R.x;player.z=R.z;player.yaw=R.yaw;player.feet=floorAt(R.x,R.z);player.camY=player.feet+player.eye;player.pitch=0;clock.h=(EPI.saveH+0.25)%24;updateSky();
  setTimeout(()=>{v.classList.remove('show');setTimeout(()=>{v.hidden=true;$('hud').hidden=false;ui='play';
    if(complete){epiReward(E);setTimeout(()=>storyHook('dream',E.id),300);}},700);},1100);
}
function epiReward(E){if(E.reward){if(state.seen&&!state.seen['ep:'+E.id]){state.seen['ep:'+E.id]=1;save();}const r=E.reward();dreamCheck();return r;}if(epiDone(E))return;state.seen['ep:'+E.id]=1;state.obols+=2+(qLv('eu')>=3?1:0);qAdd('eu',1);qAdd('so',1);save();updateStats();sfxCoin();
  const s=EPI.spheres.find(q=>q.data===E);if(s)s.core.material.color.set(0x9fb0c8);
  const n=EPISODES.filter(e=>e.mode===MODE).length,d=EPISODES.filter(e=>e.mode===MODE&&epiDone(e)).length;
  toast('<span class="label">'+(E.hist?_t(7369,'Momento histórico revivido'):_t(7370,'Momento mítico revivido'))+'</span><br>'+E.name+' · +2'+(MODE==='roma'?_t(2855,' sestercios'):_t(2856,' óbolos'))+' · '+d+' / '+n);dreamCheck();}
function epiKey(e){
  if(e.code==='KeyE'||e.code==='Enter'||e.code==='Space'||e.code==='ArrowRight'){e.preventDefault();epiBeat(EPI.beat+1);}
  else if(e.code==='ArrowLeft'||e.code==='Backspace'){e.preventDefault();epiBeat(EPI.beat-1);}
  else if(e.code==='Escape')epiEnd(false);
}
$('epiNext').onclick=()=>{if(ui==='episode')epiBeat(EPI.beat+1);};$('epiPrev').onclick=()=>{if(ui==='episode')epiBeat(EPI.beat-1);};$('epiExit').onclick=()=>{if(ui==='episode')epiEnd(false);};

// ------------------------------------------------------------ los episodios
function plXZ(id,dx,dz){const p=PLACES.find(q=>q.id===id);return p?[p.x+(dx||0),p.z+(dz||0)]:null;}
function hillY(H,x,z){const u=(x-H[0])/H[2],v=(z-H[1])/(H[2]*0.8),q=1-u*u-v*v;return q>0?H[3]*Math.sqrt(q):0;}
function onHill(o,H,x,z){o.position.set(x,hillY(H,x,z),z);return o;}
function flock(S,n,c,r){const a=[];for(let i=0;i<n;i++){const b=S.bird();b.visible=false;b.userData.i=i;a.push(b);}return{a,c,r,n};}
function flyFlock(F,t,on){for(const b of F.a){b.visible=on;if(!on)continue;const i=b.userData.i,an=t*0.55+i/F.n*TAU,rr2=F.r*(0.75+0.25*Math.sin(i*1.7));
  b.position.set(F.c[0]+Math.cos(an)*rr2,F.c[1]+Math.sin(t*0.8+i)*1.6+(i%3)*1.2,F.c[2]+Math.sin(an)*rr2);b.rotation.y=-an;b.rotation.z=0.25;
  const w=Math.sin(t*5+i)*0.35;b.userData.w[0].rotation.z=w;b.userData.w[1].rotation.z=-w;}}
function rainSys(S){const n=1800,p=new Float32Array(n*3);for(let i=0;i<n;i++){p[i*3]=(Math.random()-0.5)*120;p[i*3+1]=Math.random()*50;p[i*3+2]=(Math.random()-0.5)*120;}
  const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.BufferAttribute(p,3));const m=new THREE.Points(g,new THREE.PointsMaterial({color:0x9aaabb,size:0.07,transparent:true,opacity:0.6}));m.visible=false;S.g.add(m);
  m.userData.tick=dt=>{const a=g.attributes.position.array;for(let i=0;i<n;i++){a[i*3+1]-=dt*28;if(a[i*3+1]<0)a[i*3+1]+=50;}g.attributes.position.needsUpdate=true;};return m;}
function glowSprite(S,x,y,z,s,col){const sp=new THREE.Sprite(new THREE.SpriteMaterial({map:EPI_TEX,color:col||0xffffff,blending:THREE.AdditiveBlending,depthWrite:false,transparent:true}));sp.position.set(x,y,z);sp.scale.set(s,s,1);S.g.add(sp);return sp;}
function fireSprite(S,x,y,z,s){const sp=new THREE.Sprite(new THREE.SpriteMaterial({map:TORCH_TEX,blending:THREE.AdditiveBlending,depthWrite:false,transparent:true}));sp.position.set(x,y,z);sp.scale.set(s,s*1.3,1);S.g.add(sp);return sp;}
function armUp(p,l,r){const a=p.userData.arms;if(!a)return;p.userData.pose=1;if(l!==null&&l!==undefined)a[0].rotation.x=l;if(r!==null&&r!==undefined)a[1].rotation.x=r;}
function fall(p,k){p.rotation.x=-Math.PI/2*sstep(clamp(k,0,1));p.position.y=0.25*sstep(clamp(k,0,1));}
function olive(S,x,z,s){if(GLB.ok){const o=glbPart('T_olive');if(o){const g=new THREE.Group();g.add(o);g.position.set(x,0,z);g.scale.setScalar(s||1);S.g.add(g);return g;}}return S.tree(x,z,s||1,'#7d8a62');}
