   A.wolf=S.beast('lobo',-62,40,Math.PI);A.faust=S.person({chiton:'#8a7a5a',himation:'#5a4a3a',beard:true,hair:'#3a2a1e',staff:true,noHimation:true},-10,40,0);
   A.rom=S.person(Object.assign({},ROM,{himation:'#b0402f'}),0,0,0);A.rem=S.person(Object.assign({},ROM,{chiton:'#d9cbb0',himation:'#3f5a7a'}),0,0,0);
   A.fr=[];for(let i=0;i<4;i++)A.fr.push(S.person(Object.assign({},ROM,{chiton:pick(['#d8ccb4','#cdbf9f','#e6dccb'])}),0,0,0));
