   const A=S.a;S.box(7,1.2,7,'#cdbf9f',0,0.6,0);A.rom=S.person({chiton:'#efe6d4',himation:'#7a2a3a',hair:'#3b2a1e',beard:true,attrs:[_t(4665,'G_wreath'),_t(4531,'G_scepter')]},0,0,0);A.rom.position.y=1.2;A.rom.rotation.y=0;
   A.sold=[];for(let r=0;r<4;r++)for(let c=0;c<7;c++){const p=S.person({chiton:'#c9b48b',soldier:true,short:true,hair:'#3b2a1e'},-12+c*4,16+r*3.2,Math.PI);A.sold.push(p);}
   A.sen=[];for(let i=0;i<7;i++){const p=S.person({chiton:'#efe6d4',toga:true,hair:pick(['#8d8a85','#3e2c1f','#5b4532']),beard:true},-9+i*3,-6-Math.abs(i-3)*0.6,0);A.sen.push(p);}
   A.cloud=new THREE.Group();for(let i=0;i<14;i++){const c=new THREE.Mesh(new THREE.SphereGeometry(rr(1.4,2.6),12,10),new THREE.MeshBasicMaterial({color:'#5d626e',transparent:true,opacity:0.92}));c.position.set(rr(-2.5,2.5),rr(0.5,5),rr(-2.5,2.5));A.cloud.add(c);}S.g.add(A.cloud);A.cloud.visible=false;
