    box(1.6,1.2,0.8,wall2,-4.8,0.6,-6.6,g);box(1.6,1.4,0.15,lam('#c8553d'),-4.8,1.9,-6.95,g);box(1.8,0.2,1,wall2,-4.8,2.7,-6.6,g);
