      _t(10272,'<p class="sub">Llevas: ')+comCargaTxt()+_t(10273,' · Espacio: ')+comTot()+' de '+comCap()+(barcoOwn()?_t(10274,' (tu barco)'):_t(10275,' (sin barco propio: pagarás 1 ')+(MODE==='roma'?'sestercio':_t(2849,'óbolo'))+_t(10276,' de flete por cada bulto al venderlo)'))+_t(10277,' · Tienes ')+state.obols+' '+mon386()+'.</p>';
    for(const g of goods){const P=comPrice(g,false);add(_t(10278,'Comprar 1 ')+COM[g].n+' por '+P.p+' '+mon386(),()=>{if(comTot()>=comCap())return draw(_t(10279,'No te cabe nada más.'));if(state.obols<P.p&&!(qLv('kl')>=4&&state.obols-P.p>=-15))return draw(_t(10280,'No te llega el dinero.'));state.obols-=P.p;progMark('buy');m.carga[g]=(m.carga[g]||0)+1;save();updateStats();sfxCoin();draw(_t(10281,'Hecho: se carga en el barco.'));},'quiz');}
