function tmTick(){if(!isTouch)return;const tc=$('touch');if(!tc)return;tc.classList.toggle('off',ui!=='play');if(ui!=='play')return;
  const b=$('tTalk'),nm=$('tAName');let kind=null,name='';
  if(focus){kind=focus.kind;name=(focus.data&&focus.data.name)||'';if(kind==='fauna'&&focus.F){const I=faunaInfo(focus.F.info);name=I?I[0]:'';}}
  else if(typeof horseNear==='function'&&horseNear()&&!MOUNT.riding){kind='horse';name='Montar el caballo';}
  if(kind!==TM.lastKind){TM.lastKind=kind;b.hidden=!kind;if(kind)b.innerHTML='<svg class="ic" viewBox="0 0 24 24" aria-hidden="true">'+TM_IC[tmIcon(kind)]+'</svg>';}
  if(name!==TM.lastName){TM.lastName=name;nm.textContent=name;}nm.classList.toggle('on',!!kind&&!!name);
  const hs=hz();$('tHorse').hidden=!(hs&&hs.own)||kind==='horse';$('tFly').hidden=!(wz().own);$('tTorch').hidden=!(DAYF<0.3||TORCH.on);$('tDown').hidden=!FLY.on;$('tJump').hidden=!FLY.on;   // el botón de salto solo al volar (para subir); a pie se salta tocando el joystick o la pantalla
  keys.run=Math.hypot(joy.x,joy.y)>0.93;}
if(isTouch){document.body.classList.add('tm');
  const zone=$('joyZone'),jz=$('joy'),kn=$('knob');let zid=null,cx=0,cy=0;const home=()=>{jz.style.left='';jz.style.top='';jz.style.bottom='';jz.classList.remove('on');};
  let zt0=0,zmax=0;   // toque corto en el joystick (poner y quitar el dedo en menos de 250 ms, casi sin moverlo) = saltar
  zone.addEventListener('touchstart',e=>{if(ui!=='play'||zid!==null)return;const t=e.changedTouches[0];zid=t.identifier;cx=t.clientX;cy=t.clientY;zt0=performance.now();zmax=0;const r=jz.getBoundingClientRect();jz.style.left=(cx-r.width/2)+'px';jz.style.top=(cy-r.height/2)+'px';jz.style.bottom='auto';jz.classList.add('on');e.preventDefault();},{passive:false});
  zone.addEventListener('touchmove',e=>{for(const t of e.changedTouches)if(t.identifier===zid){let dx=t.clientX-cx,dy=t.clientY-cy;const L=Math.hypot(dx,dy),m=52;zmax=Math.max(zmax,L);if(L>m){dx*=m/L;dy*=m/L;}joy.x=dx/m;joy.y=dy/m;kn.style.transform='translate('+dx+'px,'+dy+'px)';}e.preventDefault();},{passive:false});
  const endZ=e=>{for(const t of e.changedTouches)if(t.identifier===zid){zid=null;joy.x=joy.y=0;kn.style.transform='';home();if(e.type==='touchend'&&ui==='play'&&!FLY.on&&performance.now()-zt0<250&&zmax<12)jump();}};zone.addEventListener('touchend',endZ);zone.addEventListener('touchcancel',endZ);
  // saltar (y, volando, subir mientras se mantiene) y bajar
  const hold=(id,k,tap)=>{const el=$(id);el.onclick=null;el.addEventListener('pointerdown',e=>{e.preventDefault();if(FLY.on)keys[k]=true;else if(tap)tap();});for(const ev of['pointerup','pointerleave','pointercancel'])el.addEventListener(ev,()=>{keys[k]=false;});};
  hold('tJump','jump',()=>jump());hold('tDown','down');
  $('tFly').onclick=()=>{if(ui==='play')toggleWings();};$('tTalk').onclick=()=>{if(ui!=='play')return;if(focus)interact();else if(horseNear()&&hz().own)mountHorse();};$('tHorse').onclick=()=>{if(ui==='play')callHorse();};$('tTorch').onclick=()=>toggleTorch();$('mini').addEventListener('click',()=>{if(ui==='play')openMap();});
  $('stats').addEventListener('click',e=>{if(e.target.closest('button'))return;$('stats').classList.toggle('open');});
  const sheet=$('mSheet'),openS=()=>{if(ui!=='play')return;sheet.hidden=false;ui='sheet';const c=$('clock');$('mClock').textContent=c?c.textContent:'';const sb=sheet.querySelector('[data-m="sound"]');sb.setAttribute('aria-pressed',AUD_ON?'true':'false');sheet.querySelector('[data-m="cam"]').setAttribute('aria-pressed',GF.reduced?'false':'true');},closeS=()=>{sheet.hidden=true;if(ui==='sheet')ui='play';};
  $('tMenu').onclick=()=>gmOpen();$('mClose').onclick=closeS;sheet.addEventListener('click',e=>{if(e.target===sheet)closeS();});
  sheet.querySelectorAll('[data-m]').forEach(b=>b.onclick=()=>{const m=b.dataset.m;closeS();
    if(m==='journal')openJournal();else if(m==='map')openMap();else if(m==='lib')openLibrary();else if(m==='time')advanceTime();else if(m==='view')toggleView();else if(m==='torch')toggleTorch();else if(m==='horse')callHorse();
    else if(m==='sound'){initAudio();toggleSound();}else if(m==='cam')gfToggleMotion();else if(m==='era')$('bEra').click();
    else if(m==='full'){const d=document.documentElement;try{if(document.fullscreenElement)document.exitFullscreen();else(d.requestFullscreen||d.webkitRequestFullscreen).call(d);}catch(e){}}});}

// ============================================================ polvo bajo los cascos y la cinemática de la yegua recuperada
const DUST={pool:[],tex:null,acc:0,stepAcc:0};
function dustTex(){if(DUST.tex)return DUST.tex;const c=document.createElement('canvas');c.width=c.height=64;const x=c.getContext('2d'),g=x.createRadialGradient(32,32,2,32,32,30);g.addColorStop(0,'rgba(255,255,255,.9)');g.addColorStop(0.5,'rgba(255,255,255,.35)');g.addColorStop(1,'rgba(255,255,255,0)');x.fillStyle=g;x.fillRect(0,0,64,64);DUST.tex=new THREE.CanvasTexture(c);return DUST.tex;}
function dustPuff(x,y,z,s,col){let P=DUST.pool.find(p=>!p.on);if(!P){if(DUST.pool.length>=70)return;const m=new THREE.SpriteMaterial({map:dustTex(),transparent:true,depthWrite:false,color:0xd8c49a});P={sp:new THREE.Sprite(m),on:false};scene.add(P.sp);DUST.pool.push(P);}
  P.on=true;P.t=0;P.life=1.1+Math.random()*0.6;P.s0=(s||1)*(0.5+Math.random()*0.4);P.vx=(Math.random()-0.5)*0.8;P.vz=(Math.random()-0.5)*0.8;P.vy=0.35+Math.random()*0.35;P.a=0.42+Math.random()*0.15;
  P.sp.material.color.set(col||'#d8c49a');P.sp.position.set(x,y+0.25,z);P.sp.visible=true;}
function dustTick(dt){for(const P of DUST.pool){if(!P.on)continue;P.t+=dt;const k=P.t/P.life;if(k>=1){P.on=false;P.sp.visible=false;continue;}
  P.sp.position.x+=P.vx*dt;P.sp.position.z+=P.vz*dt;P.sp.position.y+=P.vy*dt;P.vy*=0.97;const sc=P.s0*(1+k*2.2);P.sp.scale.set(sc,sc,1);P.sp.material.opacity=P.a*(1-k)*(k<0.15?k/0.15:1);}}
function dustSurfaceOK(x,z){if(inWaterK()<1)return null;const fl=floorAt(x,z),th=terrainH(x,z);if(fl>th+0.05)return null;   // sobre pavimento o tarima, nada
  if(MODE==='roma'&&x<8000&&romaInUrbs(x,z))return null;   // las calles de Roma están empedradas
  const I=player.x>8000?islandOf(x):null;if(I&&I.desert)return'#e2cf9e';if(I&&th<2.6)return'#e0d0a8';if(I&&(I.green||MODE==='roma'))return null;return'#cdb88c';}
function dustGame(dt){
  if(MOUNT.riding&&MOUNT.g&&ui==='play'){const v=MOUNT.v||0;if(v>7){const col=dustSurfaceOK(player.x,player.z);if(col){DUST.acc+=dt*v*0.22;while(DUST.acc>1){DUST.acc-=1;const g=MOUNT.g,ry=g.rotation.y,bx=-Math.sin(ry),bz=-Math.cos(ry),sd=(Math.random()-0.5)*0.8;
      dustPuff(g.position.x+bx*(0.9+Math.random()*0.6)+Math.cos(ry)*sd,floorAt(g.position.x,g.position.z),g.position.z+bz*(0.9+Math.random()*0.6)-Math.sin(ry)*sd,v>18?1.5:1.1,col);}}}}
  else if(ui==='play'&&!FLY.on&&!BOAT.on&&player.grounded&&keys.run){const sp=Math.hypot(GF.vx,GF.vz);if(sp>7){const col=dustSurfaceOK(player.x,player.z);if(col&&col!=='#cdb88c'){DUST.stepAcc+=dt*sp;if(DUST.stepAcc>2.6){DUST.stepAcc=0;dustPuff(player.x+GF.vx*-0.05,floorAt(player.x,player.z),player.z+GF.vz*-0.05,0.6,col);}}}}
  dustTick(dt);}
// ---- el relincho: una voz nasal que sube, tiembla y cae
function sfxNeigh(){if(!aOK())return;const c=AUD.ctx,t=c.currentTime+0.02;for(const[base,vol,typ]of[[620,0.05,'sawtooth'],[1240,0.018,'square']]){const o=c.createOscillator();o.type=typ;const f=c.createBiquadFilter();f.type='bandpass';f.frequency.value=1500;f.Q.value=2.2;
   const lfo=c.createOscillator();lfo.frequency.setValueAtTime(11,t);lfo.frequency.linearRampToValueAtTime(16,t+1.2);const lg=c.createGain();lg.gain.value=base*0.09;lfo.connect(lg).connect(o.frequency);
   o.frequency.setValueAtTime(base*0.8,t);o.frequency.linearRampToValueAtTime(base*1.45,t+0.25);o.frequency.linearRampToValueAtTime(base*1.2,t+0.7);o.frequency.exponentialRampToValueAtTime(base*0.55,t+1.35);
   const g=c.createGain();g.gain.setValueAtTime(0.0001,t);g.gain.exponentialRampToValueAtTime(vol,t+0.06);g.gain.setValueAtTime(vol,t+0.6);g.gain.exponentialRampToValueAtTime(0.0001,t+1.4);o.connect(f).connect(g).connect(AUD.master);o.start(t);o.stop(t+1.45);lfo.start(t);lfo.stop(t+1.45);}
  gfNoise(t+1.3,'lowpass',500,0.7,0.06,0.05,0.35);}   // el resoplido final
function sfxHoofThud(){if(!aOK())return;const t=AUD.ctx.currentTime;gfNoise(t,'lowpass',220,0.8,0.25,0.004,0.2);gfNoise(t+0.07,'lowpass',260,0.8,0.18,0.004,0.16);}
// ---- la yegua con un pivote en las patas traseras para poder encabritarse
function mareRig(x,z,coat){const g=grp(x,floorAt(x,z),z,0),piv=new THREE.Group(),inner=new THREE.Group();piv.position.z=-0.85;inner.position.z=0.85;piv.add(inner);g.add(piv);
  let legs=[];if(GLB.ok)legs=animalGLB('A_horse',inner,coat,'#2e2018');else{const c=lam(coat),dk=lam('#1e140e');box(0.75,0.8,1.95,c,0,1.55,0,inner);box(0.33,0.36,0.8,c,0,2.6,1.3,inner);for(const[px,pz]of[[0.25,0.75],[-0.25,0.75],[0.25,-0.75],[-0.25,-0.75]])legs.push(box(0.15,1.2,0.15,dk,px,0.6,pz,inner));}
  return{g,piv,legs};}
const CINE={on:false};
function cineCSS(){if($('cineCSS'))return;const s=document.createElement('style');s.id='cineCSS';s.textContent='#cine{position:fixed;inset:0;z-index:58;pointer-events:auto;cursor:pointer}#cine:before,#cine:after{content:"";position:absolute;left:0;right:0;height:0;background:#000;transition:height .5s ease}#cine:before{top:0}#cine:after{bottom:0}#cine.on:before,#cine.on:after{height:11vh}#cine .cap{position:absolute;left:50%;bottom:calc(11vh + 18px);transform:translateX(-50%);max-width:min(680px,90vw);text-align:center;color:#f1e8d8;font:italic 1.05rem Georgia,serif;text-shadow:0 1px 4px #000;opacity:0;transition:opacity .5s}#cine .cap.on{opacity:1}#cine .sk{position:absolute;right:16px;top:calc(11vh + 10px);font-size:.75rem;color:rgba(241,232,216,.6)}@media (prefers-reduced-motion:reduce){#cine:before,#cine:after,#cine .cap{transition:none}}';document.head.appendChild(s);}
function cineCap(t){const c=CINE.d&&CINE.d.querySelector('.cap');if(!c)return;c.classList.remove('on');setTimeout(()=>{c.textContent=t;c.classList.add('on');},t?180:0);}
function mareCine(){const h=hz(),ro=MODE==='roma',nm=ro?'la yegua blanca':'Aura';if(MARE.g){scene.remove(MARE.g);MARE.g=null;}
  if(MOUNT.riding)dismount();FLY.on=false;cineCSS();
  const R0=mareRig(h.mx,h.mz,ro?'#d8cfc0':'#8a6a4a'),g=R0.g;
  // de perfil respecto a quien juega
  const dx=h.mx-player.x,dz=h.mz-player.z,dl=Math.hypot(dx,dz)||1;g.rotation.y=Math.atan2(-dz/dl,dx/dl);
  const npc=npcAt(HORSE_NPC());
  const d=document.createElement('div');d.id='cine';d.innerHTML='<div class="cap"></div><div class="sk">'+(isTouch?'Toca para saltar':'Esc o clic para saltar')+'</div>';document.body.appendChild(d);requestAnimationFrame(()=>d.classList.add('on'));
  Object.assign(CINE,{on:true,t:0,R:R0,d,npc,phase:0,cam:{x:camera.position.x,y:camera.position.y,z:camera.position.z},ui0:ui});ui='cine';releasePointer();
  d.onclick=()=>cineEnd();cineCap('Coges la brida. '+(ro?'La yegua':'Aura')+' se asusta…');}
function cineEnd(){if(!CINE.on)return;CINE.on=false;const h=hz(),ro=MODE==='roma';if(CINE.R)scene.remove(CINE.R.g);CINE.R=null;
  const d=CINE.d;if(d){d.classList.remove('on');setTimeout(()=>d.remove(),500);}ui='play';mareShow();updateStats();
  toast('<span class="label">'+(ro?'La yegua vuelve a casa':'Aura vuelve a casa')+'</span><br>Se ha ido trotando con '+(ro?'Félix, el auriga':_t(805,'Eudico de Larisa'))+'. Ve a verle: te espera con tu potro.');}
function cineTick(dt){if(!CINE.on)return;CINE.t+=dt;const t=CINE.t,R0=CINE.R,g=R0.g,L=R0.legs,ease=k=>k<0?0:k>1?1:k*k*(3-2*k);
  const fx=Math.sin(g.rotation.y),fz=Math.cos(g.rotation.y),sx=fz,sz=-fx;   // adelante y costado de la yegua
  let rear=0;
  if(t>0.35&&!CINE.n){CINE.n=1;sfxNeigh();}
  if(t<2.2){rear=t<0.4?0:t<0.9?ease((t-0.4)/0.5)*0.85:t<1.6?0.85+Math.sin((t-0.9)*9)*0.05:0.85*(1-ease((t-1.6)/0.45));
    if(L.length===4){const kick=t>0.5&&t<1.8?Math.sin(t*15):0;L[0].rotation.x=-0.6*Math.min(1,rear/0.5)+kick*0.5;L[1].rotation.x=-0.6*Math.min(1,rear/0.5)-kick*0.5;L[2].rotation.x=rear*0.35;L[3].rotation.x=rear*0.35;}
    if(t>2.02&&!CINE.th){CINE.th=1;sfxHoofThud();for(let k=0;k<9;k++)dustPuff(g.position.x+fx*1.6+(Math.random()-0.5)*1.4,floorAt(g.position.x,g.position.z),g.position.z+fz*1.6+(Math.random()-0.5)*1.4,1.3);cineCap((MODE==='roma'?'La yegua':'Aura')+' se calma. Te huele la mano… pero quiere volver a casa.');}}
  else if(t<3.2){if(L.length===4)L.forEach(l=>l.rotation.x*=0.85);
    const n=CINE.npc;if(n){const want=Math.atan2(n.x-g.position.x,n.z-g.position.z);g.rotation.y+=wrapA(want-g.rotation.y)*Math.min(1,dt*3);}}
  else{const n=CINE.npc,want=n?Math.atan2(n.x-g.position.x,n.z-g.position.z):g.rotation.y;g.rotation.y+=wrapA(want-g.rotation.y)*Math.min(1,dt*3);
    const v=Math.min(7,(t-3.2)*5);g.position.x+=Math.sin(g.rotation.y)*v*dt;g.position.z+=Math.cos(g.rotation.y)*v*dt;g.position.y=floorAt(g.position.x,g.position.z)+Math.abs(Math.sin(t*9))*0.06;
    if(L.length===4){const s=Math.sin(t*9)*0.5;L[0].rotation.x=s;L[3].rotation.x=s;L[1].rotation.x=-s;L[2].rotation.x=-s;}
    CINE.da=(CINE.da||0)+dt*v*0.5;while(CINE.da>1){CINE.da-=1;const col=dustSurfaceOK(g.position.x,g.position.z);if(col)dustPuff(g.position.x-fx*1.1,floorAt(g.position.x,g.position.z),g.position.z-fz*1.1,1,col);}
    if(t>3.4&&!CINE.c2){CINE.c2=1;cineCap((MODE==='roma'?'La yegua':'Aura')+' se aleja trotando hacia '+(MODE==='roma'?_t(3580,'Félix'):'Eudico')+'.');}}
  R0.piv.rotation.x=-rear;
  // cámara: de perfil durante el encabritamiento; luego, desde detrás de quien juega, siguiéndola
  const tgt=t<3.2?{x:g.position.x+sx*7+fx*1.2,y:floorAt(g.position.x,g.position.z)+1.7,z:g.position.z+sz*7+fz*1.2}:{x:player.x,y:player.camY+0.6,z:player.z};
  const k=1-Math.exp(-dt*(t<0.6?3:2));CINE.cam.x+=(tgt.x-CINE.cam.x)*k;CINE.cam.y+=(tgt.y-CINE.cam.y)*k;CINE.cam.z+=(tgt.z-CINE.cam.z)*k;
  camera.position.set(CINE.cam.x,CINE.cam.y,CINE.cam.z);camera.lookAt(g.position.x,floorAt(g.position.x,g.position.z)+1.3+rear*1.2,g.position.z);
  if(t>7.2)cineEnd();}
addEventListener('keydown',e=>{if(!CINE.on)return;e.stopImmediatePropagation();e.preventDefault();if(e.code==='Escape'||e.code==='Enter'||e.code==='Space')cineEnd();},true);

// ============================================================ GAME FEEL 2: caballo vivo, animales que reaccionan, huellas, agua, saludos,
// viento en los árboles, diálogos que se escriben, monedas que vuelan, luciérnagas y humo de los hogares
// ---- partículas genéricas (agua, humo, luciérnagas)
const PFX={pool:[]};
function pfx(x,y,z,o){let P=PFX.pool.find(p=>!p.on);if(!P){if(PFX.pool.length>=110)return;const m=new THREE.SpriteMaterial({map:dustTex(),transparent:true,depthWrite:false});P={sp:new THREE.Sprite(m),on:false};scene.add(P.sp);PFX.pool.push(P);}
  Object.assign(P,{on:true,t:0,life:o.life||1,vx:o.vx||0,vy:o.vy||0,vz:o.vz||0,g:o.g||0,s0:o.s||0.4,grow:o.grow===undefined?1.5:o.grow,a:o.a||0.6,blink:o.blink||0,ph:Math.random()*10});
  P.sp.material.color.set(o.col||'#ffffff');P.sp.material.blending=o.add?THREE.AdditiveBlending:THREE.NormalBlending;P.sp.position.set(x,y,z);P.sp.visible=true;}
function pfxTick(dt){for(const P of PFX.pool){if(!P.on)continue;P.t+=dt;const k=P.t/P.life;if(k>=1){P.on=false;P.sp.visible=false;continue;}
  P.vy-=P.g*dt;P.sp.position.x+=P.vx*dt;P.sp.position.y+=P.vy*dt;P.sp.position.z+=P.vz*dt;const sc=P.s0*(1+k*P.grow);P.sp.scale.set(sc,sc,1);
  let a=P.a*(1-k)*(k<0.1?k/0.1:1);if(P.blink)a*=0.35+0.65*Math.max(0,Math.sin(P.t*P.blink+P.ph));P.sp.material.opacity=a;}}
function splash(x,z,big){const y=floorAt(x,z)+0.1;for(let i=0;i<(big?10:5);i++){const a=Math.random()*TAU,v=0.6+Math.random()*(big?1.6:0.9);pfx(x,y,z,{col:'#e8f2f4',vx:Math.cos(a)*v,vz:Math.sin(a)*v,vy:1.6+Math.random()*(big?2.2:1.2),g:9,life:0.6,s:big?0.35:0.22,grow:0.8,a:0.8});}ripple(x,z,big?1.6:1);}
// ---- marcas en el suelo: huellas, cascos y ondas en el agua (planos que se desvanecen)
const MARKS={pool:[],geo:null};
function mark(x,z,a,kind,y){if(!MARKS.geo)MARKS.geo=new THREE.CircleGeometry(1,16);let M2=MARKS.pool.find(m=>!m.on);
  if(!M2){if(MARKS.pool.length>=140)M2=MARKS.pool.reduce((o,m)=>m.t>o.t?m:o);else{const m=new THREE.Mesh(MARKS.geo,new THREE.MeshBasicMaterial({color:0x000000,transparent:true,depthWrite:false,polygonOffset:true,polygonOffsetFactor:-2}));m.rotation.x=-Math.PI/2;scene.add(m);M2={m,on:false};MARKS.pool.push(M2);}}
  const m=M2.m;Object.assign(M2,{on:true,t:0,kind,life:kind==='ripple'?1.4:kind==='hoof'?28:22});m.visible=true;
  if(kind==='ripple'){m.geometry=MARKS.ring||(MARKS.ring=new THREE.RingGeometry(0.85,1,28));m.material.color.set('#e8f4f6');m.material.opacity=0.55;m.position.set(x,y!==undefined?y:floorAt(x,z)+0.06,z);m.scale.set(0.3,0.3,1);M2.s=y;}
  else{m.geometry=MARKS.geo;m.material.color.set('#3a2a1a');m.material.opacity=kind==='hoof'?0.3:0.24;m.position.set(x,floorAt(x,z)+0.03,z);m.rotation.z=a||0;if(kind==='hoof')m.scale.set(0.11,0.13,1);else m.scale.set(0.07,0.14,1);}}
function ripple(x,z,s){const fl=floorAt(x,z);mark(x,z,0,'ripple',fl+0.08);const M2=MARKS.pool.find(m=>m.on&&m.kind==='ripple'&&m.t===0);if(M2)M2.big=s||1;}
function marksTick(dt){for(const M2 of MARKS.pool){if(!M2.on)continue;M2.t+=dt;const k=M2.t/M2.life;if(k>=1){M2.on=false;M2.m.visible=false;continue;}
  if(M2.kind==='ripple'){const s=(0.3+k*1.8)*(M2.big||1);M2.m.scale.set(s,s,1);M2.m.material.opacity=0.55*(1-k);}else if(k>0.6)M2.m.material.opacity=(M2.kind==='hoof'?0.3:0.24)*(1-(k-0.6)/0.4);}}
let footSide=1;
function footStep(kind){const yaw=player.yaw,rx=Math.cos(yaw),rz=-Math.sin(yaw);footSide=-footSide;const x=player.x+rx*0.13*footSide,z=player.z+rz*0.13*footSide;
  if(kind==='water'){splash(x,z,false);return;}if(kind==='sand'||(kind==='earth'&&player.x>8000))mark(x,z,-yaw,'foot');}
// ---- 1. caballo vivo: ritmos de cascos según el aire, resoplidos, crin y cola, derrapes
const HB={t:0,last:0,idle:6,vPrev:0,parts:null};
const GAITS=[{max:3.5,n:'paso',T:1.15,b:[0,0.25,0.5,0.75],v:0.11},{max:10,n:'trote',T:0.6,b:[0,0.03,0.5,0.53],v:0.15},{max:19,n:'medio galope',T:0.62,b:[0,0.16,0.24,0.42],v:0.18},{max:1e9,n:'galope',T:0.46,b:[0,0.08,0.18,0.26],v:0.2}];
function sfxBeat(vol,water){if(!aOK())return;const t=AUD.ctx.currentTime;if(water){gfNoise(t,'lowpass',800,1,vol*0.9,0.01,0.18);return;}gfNoise(t,'bandpass',780+Math.random()*200,3.5,vol,0.003,0.06);gfNoise(t,'lowpass',200,0.8,vol*0.8,0.003,0.08);}
function sfxSnort(){if(!aOK())return;const t=AUD.ctx.currentTime;gfNoise(t,'bandpass',900,0.9,0.07,0.03,0.25);gfNoise(t+0.28,'bandpass',700,0.9,0.05,0.02,0.2);}
function sfxSkid(){if(!aOK())return;const c=AUD.ctx,t=c.currentTime,s=c.createBufferSource();s.buffer=AUD.noise;const f=c.createBiquadFilter();f.type='bandpass';f.frequency.setValueAtTime(1600,t);f.frequency.exponentialRampToValueAtTime(400,t+0.5);s.connect(f).connect(envGain(t,0.12,0.02,0.5));s.start(t);s.stop(t+0.6);}
function horseAlive(dt){const g=MOUNT.g;if(!g||!g.visible)return;const v=MOUNT.riding?(MOUNT.v||0):0,now=performance.now()/1000;
  if(!HB.parts&&GLB.ok&&g.children.length>=3)HB.parts={mane:g.children[1],tail:g.children[2]};
  const P=HB.parts;if(P){P.tail.rotation.y=v<1?Math.sin(now*2.6)*0.07+Math.sin(now*7.3)*0.02:Math.sin(now*9)*0.03;P.tail.rotation.x=-Math.min(0.08,v*0.004);P.mane.rotation.z=Math.sin(now*(v>8?14:2))*Math.min(0.03,0.006+v*0.0015);}
  if(MOUNT.riding&&ui==='play'&&v>0.6){const G=GAITS.find(q=>v<q.max),T=G.T;HB.t+=dt;const c0=(HB.t-dt)%T,c1=HB.t%T;
    for(const b of G.b){const o=b*T;if((c0<o&&c1>=o)||(c1<c0&&(o>c0||o<=c1))){const water=inWaterK()<1;sfxBeat(G.v,water);
      const ry=g.rotation.y,side=(Math.random()-0.5)*0.4,hx=g.position.x+Math.sin(ry)*(b<0.3?-0.6:0.6)+Math.cos(ry)*side,hz=g.position.z+Math.cos(ry)*(b<0.3?-0.6:0.6)-Math.sin(ry)*side;
      if(water)splash(hx,hz,v>8);else if(gfSurface()==='sand')mark(hx,hz,0,'hoof');}}}
  else HB.t=0;
  // derrape: frenada brusca a galope
  if(MOUNT.riding){const dv=(HB.vPrev-v)/Math.max(dt,1e-3);if(dv>14&&HB.vPrev>12&&!HB.sk){HB.sk=1;sfxSkid();const col=dustSurfaceOK(player.x,player.z)||'#cdb88c';for(let k=0;k<12;k++)dustPuff(g.position.x+(Math.random()-0.5)*1.8,floorAt(g.position.x,g.position.z),g.position.z+(Math.random()-0.5)*1.8,1.4,col);}if(dv<4)HB.sk=0;}
  HB.vPrev=v;
  // parado: resopla y sacude la crin de vez en cuando
  if(v<0.4&&Math.hypot(g.position.x-player.x,g.position.z-player.z)<30){HB.idle-=dt;if(HB.idle<0){HB.idle=6+Math.random()*8;sfxSnort();HB.shake=0.6;}}
  if(HB.shake>0){HB.shake-=dt;if(P)P.mane.rotation.z+=Math.sin(HB.shake*30)*0.05*HB.shake;}}
// ---- 2. animales que reaccionan: gallinas y gansos huyen aleteando, cabras se apartan, palomas que levantan el vuelo
const FLEE={hen:1,rooster:1,goose:1,duck:1,quail:1};
function sfxCluck(){if(!aOK())return;const c=AUD.ctx;let t=c.currentTime+0.01;for(let i=0;i<3;i++){const o=c.createOscillator();o.type='square';const f=c.createBiquadFilter();f.type='bandpass';f.frequency.value=1400;f.Q.value=3;o.frequency.setValueAtTime(700+Math.random()*200,t);o.frequency.exponentialRampToValueAtTime(450,t+0.07);o.connect(f).connect(envGain(t,0.025,0.004,0.07));o.start(t);o.stop(t+0.09);t+=0.09+Math.random()*0.05;}}
function animalsReact(dt){const ps=MOUNT.riding?(MOUNT.v||0):Math.hypot(GF.vx,GF.vz);if(ui!=='play')return;
  for(const F of FAUNA){const g=F.A.g;if(!g.visible||F.cur)continue;const dx=g.position.x-player.x,dz=g.position.z-player.z,d=Math.hypot(dx,dz);
    if(F.flee>0){F.flee-=dt;if(F.flee<=0&&F.spd0){F.spd=F.spd0;F.spd0=0;}if(F.flee>0.6&&FLEE[F.sp])g.position.y+=Math.abs(Math.sin(F.flee*22))*0.12;continue;}
    const scary=FLEE[F.sp]?(d<3.6&&ps>3.2)||(d<5&&MOUNT.riding):(F.sp==='goat'||F.sp==='sheep'||F.sp==='pig')?(d<2.4&&ps>2)||(d<4&&MOUNT.riding&&ps>6):false;
    if(scary&&(F.beh==='wander'||F.beh==='peck')){const l=d||1;F.tx=g.position.x+dx/l*rr(5,9)+rr(-2,2);F.tz=g.position.z+dz/l*rr(5,9)+rr(-2,2);F.w=0;F.spd0=F.spd0||F.spd;F.spd=F.spd0*(FLEE[F.sp]?4:2.2);F.flee=FLEE[F.sp]?1.6:1.2;if(FLEE[F.sp]&&Math.random()<0.7)sfxCluck();}}}
const DOVES={fl:[],t:8};
function doveFlock(x,z){const n=5+Math.floor(Math.random()*5),body=new THREE.SphereGeometry(0.13,8,6),m=lam(pick(['#8a8a90','#9a9aa2','#7a7a84'])),birds=[];
  for(let i=0;i<n;i++){const g=new THREE.Group();const b=new THREE.Mesh(body,m);b.scale.set(1,0.85,1.5);b.position.y=0.13;g.add(b);const h=new THREE.Mesh(body,m);h.scale.setScalar(0.6);h.position.set(0,0.27,0.17);g.add(h);
    const wl=box(0.32,0.02,0.16,m,-0.12,0.18,0,g),wr=box(0.32,0.02,0.16,m,0.12,0.18,0,g);wl.visible=wr.visible=false;
    const px=x+(Math.random()-0.5)*4,pz=z+(Math.random()-0.5)*4;g.position.set(px,floorAt(px,pz),pz);g.rotation.y=Math.random()*TAU;scene.add(g);birds.push({g,head:h,wl,wr,ph:Math.random()*10,vx:0,vy:0,vz:0});}
  DOVES.fl.push({x,z,birds,st:'peck',t:0});}
function sfxFlap(){if(!aOK())return;const t=AUD.ctx.currentTime;for(let i=0;i<6;i++)gfNoise(t+i*0.05,'bandpass',1100+Math.random()*500,1,0.05,0.005,0.04);}
function dovesTick(dt){{DOVES.t-=dt;
    if(DOVES.t<0){DOVES.t=12+Math.random()*10;const near=DOVES.fl.some(f=>Math.hypot(f.x-player.x,f.z-player.z)<70);
      if(!near&&ui==='play'&&DAYF>0.3){const a=player.yaw+Math.PI+(Math.random()-0.5)*1.2,d=18+Math.random()*12,x=player.x-Math.sin(player.yaw)*d+(Math.random()-0.5)*10,z=player.z-Math.cos(player.yaw)*d+(Math.random()-0.5)*10;
        if(isFree(x,z,1.5)&&inWaterK()===1&&Math.abs(floorAt(x,z)-player.feet)<3)doveFlock(x,z);}}}
  const ps=MOUNT.riding?(MOUNT.v||0):Math.hypot(GF.vx,GF.vz),T=performance.now()/1000;
  for(const F of DOVES.fl){F.t+=dt;const d=Math.hypot(F.x-player.x,F.z-player.z);
    if(F.st==='peck'){if(d<(ps>4?9:5.5)){F.st='fly';sfxFlap();for(const b of F.birds){const a=Math.atan2(b.g.position.x-player.x,b.g.position.z-player.z)+(Math.random()-0.5)*0.8;b.vx=Math.sin(a)*rr(4,7);b.vz=Math.cos(a)*rr(4,7);b.vy=rr(3,5);b.g.rotation.y=a;b.wl.visible=b.wr.visible=true;}}
      else for(const b of F.birds){b.head.position.y=0.27-Math.max(0,Math.sin(T*5+b.ph))*0.12;}
      if(d>140){F.dead=1;}}
    else{for(const b of F.birds){b.g.position.x+=b.vx*dt;b.g.position.y+=b.vy*dt;b.g.position.z+=b.vz*dt;b.vy=Math.max(1.2,b.vy-dt*0.8);const f=Math.sin(T*28+b.ph)*0.9;b.wl.rotation.z=f;b.wr.rotation.z=-f;}if(F.t>40||F.birds[0].g.position.y>floorAt(F.x,F.z)+45)F.dead=1;}
    if(F.st==='fly'&&!F.t0)F.t0=F.t;}
  for(const F of DOVES.fl)if(F.dead)F.birds.forEach(b=>scene.remove(b.g));DOVES.fl=DOVES.fl.filter(F=>!F.dead);}
// ---- 4. espuma en la orilla
const FOAM={t:0};
function foamTick(dt){FOAM.t-=dt;if(FOAM.t>0||ui!=='play')return;FOAM.t=0.35;const sea=SEA?SEA.position.y:-2.2;
  for(let k=0;k<10;k++){const a=Math.random()*TAU,d=4+Math.random()*44,x=player.x+Math.cos(a)*d,z=player.z+Math.sin(a)*d,h=terrainH(x,z);
    if(h>sea-0.7&&h<sea+0.5&&riverWater(x,z)===null){mark(x,z,0,'ripple',sea+0.05);pfx(x,sea+0.15,z,{col:'#f4f8f8',life:1.6,s:0.7,grow:1.2,a:0.45});break;}}}
// ---- 5. gente que saluda y vendedores que levantan el brazo al pregonar
const SAL={A:['¡Khaîre!','¡Khaîre, forastero!','¡Salud!','¡Que los dioses te guarden!'],R:['¡Salve!','¡Salve, forastero!','¡Ave!','¡Salve!']};   // los saludos de verdad: khaîre («alégrate») en griego; salve y ave en latín
function greetTick(dt){if(ui!=='play')return;const now=performance.now();
  for(const w of walkers){const g=w.g;if(w.home||!g.visible)continue;if(w.gr&&now<w.gr.until){if(now>w.gr.down&&!w.gr.dn){w.gr.dn=1;armUp(g,null,0);}continue;}
    if(w.gr&&w.gr.sp){scene.remove(w.gr.sp);w.gr.sp=null;}
    const d=Math.hypot(g.position.x-player.x,g.position.z-player.z);if(d>3.4||d<1)continue;if(w.grNext&&now<w.grNext)continue;w.grNext=now+60000;if(Math.random()>0.4)continue;
    armUp(g,null,-2.5);const sp=labelSprite(v2Greet(),'',false);sp.position.set(g.position.x,g.position.y+2.5,g.position.z);scene.add(sp);
    g.rotation.y=Math.atan2(player.x-g.position.x,player.z-g.position.z);w.gr={until:now+1900,down:now+1300,sp,dn:0};if(w.wait!==undefined)w.wait=Math.max(w.wait,1.5);}}
// ---- 6. viento: las copas de los árboles se mecen (sombreado en la GPU) con rachas
const WIND={u:{value:0},s:{value:1}};
function windMat(mat){if(mat.userData.wind)return mat.userData.wind;const w=mat.clone(),prev=mat.onBeforeCompile;
  w.onBeforeCompile=function(sh,r){if(prev)prev.call(this,sh,r);sh.uniforms.uWT=WIND.u;sh.uniforms.uWS=WIND.s;
    sh.vertexShader='uniform float uWT;uniform float uWS;\n'+sh.vertexShader.replace('#include <project_vertex>','{\n#ifdef USE_INSTANCING\nfloat wph=instanceMatrix[3].x*0.13+instanceMatrix[3].z*0.11;\n#else\nfloat wph=0.0;\n#endif\nfloat wk=max(0.0,position.y-0.8);transformed.x+=sin(uWT*1.3+wph)*0.03*wk*uWS+sin(uWT*3.7+wph*2.0)*0.008*wk*uWS;transformed.z+=cos(uWT*1.05+wph*1.4)*0.022*wk*uWS;}\n#include <project_vertex>');};
  w.customProgramCacheKey=()=>'viento'+(mat.customProgramCacheKey?mat.customProgramCacheKey():'');mat.userData.wind=w;return w;}
function windTick(dt){const t=performance.now()/1000;WIND.u.value=t;const gust=0.7+0.45*Math.sin(t*0.13)+0.25*Math.sin(t*0.41+1.3);WIND.s.value=GF.reduced?0.3:Math.max(0.3,gust);}
// ---- 7. diálogos que se escriben solos, con una nota de lira al abrirse
const TW={on:false,nodes:[],i:0,acc:0,skip:false};
function twStart(){const B=$('dBody');if(!B||GF.reduced)return;const nodes=[];const tw=document.createTreeWalker(B,NodeFilter.SHOW_TEXT);for(let n=tw.nextNode();n;n=tw.nextNode()){if(n.parentElement&&n.parentElement.closest('input,textarea,button'))continue;if(n.nodeValue.trim()){nodes.push({n,full:n.nodeValue});n.nodeValue='';}}
  if(!nodes.length)return;TW.on=true;TW.nodes=nodes;TW.i=0;TW.acc=0;TW.c=0;TW.lt=performance.now();}
function twFinish(){if(!TW.on)return;for(const o of TW.nodes)o.n.nodeValue=o.full;TW.on=false;TW.nodes=[];try{glossScan();}catch(e){}}
function twTick(dt){if(!TW.on)return;if($('dialog').hidden){twFinish();return;}const nw=performance.now();TW.acc+=Math.min(1,(nw-(TW.lt||nw))/1000)*110;TW.lt=nw;let k=Math.floor(TW.acc);TW.acc-=k;
  while(k>0&&TW.i<TW.nodes.length){const o=TW.nodes[TW.i],cur=o.n.nodeValue.length,rest=o.full.length-cur,take=Math.min(rest,k);o.n.nodeValue=o.full.slice(0,cur+take);k-=take;if(cur+take>=o.full.length)TW.i++;}
  if(TW.i>=TW.nodes.length){TW.on=false;try{glossScan();}catch(e){}}}
(function twObserve(){const B=$('dBody'),D=$('dialog');if(!B||!D)return;let wasHidden=D.hidden;
  new MutationObserver(()=>{if(TW.busy)return;TW.busy=true;twFinish();twStart();TW.busy=false;}).observe(B,{childList:true});
  new MutationObserver(()=>{if(wasHidden&&!D.hidden&&aOK()){const t=AUD.ctx.currentTime;pluck(LYRE[2+Math.floor(Math.random()*3)],t+0.01,0.045);}wasHidden=D.hidden;}).observe(D,{attributes:true,attributeFilter:['hidden']});
  B.addEventListener('click',()=>twFinish());})();
// ---- 8. monedas que vuelan hasta el contador
function coinFly(n){const tgt=$('sObols');if(!tgt||GF.reduced)return;const r=tgt.getBoundingClientRect(),k=Math.min(6,Math.max(1,Math.round(n/2)));
  for(let i=0;i<k;i++){const c=document.createElement('div');c.style.cssText='position:fixed;z-index:57;width:16px;height:16px;border-radius:50%;background:radial-gradient(circle at 35% 35%,#fff3c4,#e0b04a 45%,#9a6a1e);box-shadow:0 0 8px rgba(255,210,120,.7);pointer-events:none;left:'+(innerWidth/2-8+(Math.random()-0.5)*60)+'px;top:'+(innerHeight*0.55+(Math.random()-0.5)*40)+'px;transition:left .7s cubic-bezier(.5,-0.3,.6,1),top .7s cubic-bezier(.3,.6,.5,1),transform .7s,opacity .25s .6s';
    document.body.appendChild(c);setTimeout(()=>{c.style.left=(r.left+8)+'px';c.style.top=(r.top+2)+'px';c.style.transform='scale(.6)';c.style.opacity='0';},60+i*90);setTimeout(()=>c.remove(),1000+i*90);}
  setTimeout(()=>{tgt.animate&&tgt.animate([{transform:'scale(1)'},{transform:'scale(1.25)',color:'#ffd77a'},{transform:'scale(1)'}],{duration:350});},760);}
// ---- 9. luciérnagas en las noches de verano y humo de los hogares por la mañana y al atardecer
const NIGHT={ff:0,sm:0};
function nightTick(dt){if(ui!=='play'&&ui!=='dialog')return;const mo=calNow().mo,h=clock.h;
  const summer=mo>=4&&mo<=7,outside=!gfInCity();
  if(summer&&DAYF<0.22&&outside&&!FLY.on){NIGHT.ff-=dt;if(NIGHT.ff<0){NIGHT.ff=0.18;const a=Math.random()*TAU,d=3+Math.random()*16,x=player.x+Math.cos(a)*d,z=player.z+Math.sin(a)*d;if(inWaterK()===1)pfx(x,floorAt(x,z)+0.4+Math.random()*1.6,z,{col:'#d8ff6a',add:true,life:3+Math.random()*3,vx:(Math.random()-0.5)*0.5,vz:(Math.random()-0.5)*0.5,vy:(Math.random()-0.5)*0.2,s:0.18,grow:0,a:0.9,blink:3+Math.random()*3});}}
  if((h>=6&&h<9)||(h>=18&&h<20.5)){NIGHT.sm-=dt;if(NIGHT.sm<0){NIGHT.sm=0.5;const hs=footprints.filter(f=>f.house&&Math.abs(f.x-player.x)<140&&Math.abs(f.z-player.z)<140);if(hs.length){const f=hs[Math.floor(Math.random()*hs.length)];if(!f.smoke)f.smoke=Math.random()<0.45?1:-1;
      if(f.smoke>0){const y=floorAt(f.x,f.z)+4.4;pfx(f.x+(Math.random()-0.5)*0.6,y,f.z+(Math.random()-0.5)*0.6,{col:'#b8b2a8',life:5+Math.random()*3,vy:0.55,vx:0.25,vz:0.05,s:0.9,grow:3,a:0.32});}}}}}
// ---- tick común
const STEP={acc:0};
function gf2Tick(dt){if(ui==='play'&&!MOUNT.riding&&!FLY.on&&!BOAT.on&&player.grounded){const sp=Math.hypot(GF.vx,GF.vz);STEP.acc+=sp*dt;if(STEP.acc>(sp>7?1.3:0.8)){STEP.acc=0;footStep(gfSurface());}}horseAlive(dt);animalsReact(dt);dovesTick(dt);foamTick(dt);greetTick(dt);windTick(dt);twTick(dt);nightTick(dt);pfxTick(dt);marksTick(dt);}

// ============================================================ equivalentes romanos (año 80): comercio desde el Emporio, la carrera del Circo Máximo,
// la huida de Miseno, el debate de Claudio sobre los galos, cuatro patrias nuevas, el capítulo «El pan de Roma» y tres misiones
const COM_TXT={atenas:{none:'No traes nada que vender. Compra vino en Quíos, trigo o atún en Bizancio, tierra blanca en Melos o madera en Olinto, y tráemelo.',
  how:'<p>El mercader rara vez es rico: pide un préstamo marítimo a un banquero o a un particular para comprar la carga, y si el barco se hunde, no lo devuelve. Por eso el interés es altísimo, un 20 o un 30 % por viaje. Se firma un contrato ante testigos con la ruta, la carga y el plazo.</p><p>El trigo es especial: una ley prohíbe a cualquiera que viva en el Ática llevar trigo a otro puerto que no sea Atenas, y prestar dinero para un barco que no lo traiga. Los guardianes del trigo vigilan que los revendedores no lo acaparen. Y no se navega en invierno, salvo necesidad.</p><p class="sub">Demóstenes XXXIV 37 y XXXV 10-13 y 50-51; Lisias XXII; Aristóteles, Constitución de los atenienses 51. Los precios del juego están simplificados.</p>'},
 roma:{none:'No traes nada que vender. Compra trigo en Cartago, aceite en Corduba, garum en Gades o plomo en Carthago Nova, y tráemelo aquí, al Emporio.',
  how:'<p>Roma, con casi un millón de habitantes, come trigo que viene del mar: según Flavio Josefo, África la alimenta ocho meses al año y Egipto, los otros cuatro. El Estado reparte trigo gratis cada mes a unos doscientos mil ciudadanos (la annona), y el prefecto de la annona compra y vigila los envíos. El emperador Claudio prometió compensar las pérdidas a los mercaderes que traían trigo en invierno, y premiaba a quienes construían barcos para ello.</p><p>El aceite de la Bética llega en ánforas redondas con sellos y etiquetas pintadas: el peso, el mercader, el control fiscal. Del 11 de noviembre al 10 de marzo, el mar está «cerrado»: casi nadie navega.</p><p class="sub">Flavio Josefo, La guerra de los judíos II 383-386; Suetonio, Claudio 18-19; Vegecio IV 39; Digesto XXII 2. Los precios del juego están simplificados.</p>'}};
function comTxt(){return COM_TXT[MODE==='roma'?'roma':'atenas'];}
function comMode(){if(MODE!=='roma'||COM.__r)return;for(const k in COM)delete COM[k];Object.defineProperty(COM,'__r',{value:true,enumerable:false});
  Object.assign(COM,{trigo:{k:'trigo',n:'saco de trigo de África',pl:'sacos de trigo de África',de:'himilcon',b:3,s:6},
   aceite:{k:'aceite',n:'ánfora de aceite de la Bética',pl:'ánforas de aceite de la Bética',de:'olearius',b:5,s:9},
   garum:{k:'garum',n:'ánfora de garum de Gades',pl:'ánforas de garum de Gades',de:'himilcon_gades',b:6,s:12},
   plomo:{k:'plomo',n:'lingote de plomo de Carthago Nova',pl:'lingotes de plomo de Carthago Nova',de:'eros_cn',b:4,s:8}});
  COM_EV.length=0;COM_EV.push(null,
   {t:'Ha llegado a Puteoli la flota del trigo de Alejandría: todo el mundo baja al muelle a verla, y el trigo baja de precio.',g:'trigo',f:0.75},
   {t:'Tito prepara los cien días de juegos del Anfiteatro: se necesita aceite para las lámparas y los cuerpos de los atletas.',g:'aceite',f:1.35},
   null,
   {t:'Después del gran incendio de este año, se reconstruye el Campo de Marte: se paga bien el plomo para tuberías y tejados.',g:'plomo',f:1.45},
   {t:'En los banquetes de moda no puede faltar el garum de Gades, el «garum de los aliados», el más caro.',g:'garum',f:1.35},
   null,
   {t:'Hay piratas cerca de Sicilia: los barcos esperan escolta y todo se encarece.',g:'*',f:1.2},
   {t:'Un mercader ha descargado un barco entero de aceite de la Bética: hay de sobra.',g:'aceite',f:0.75},
   {t:'El prefecto de la annona compra trigo para el reparto del mes.',g:'trigo',f:1.25});
  comPrice=function(g,sell){const G=COM[g],mo=calNow().mo;let f=1;const why=[];
    if(g==='trigo'){if(sell){if(mo>=10||mo<=2){f*=1.35;why.push('es invierno: el mar está cerrado y casi no llegan barcos');}else if(mo>=5&&mo<=8){f*=0.85;why.push('en verano llegan las flotas de África y de Egipto');}}else if(mo>=5&&mo<=8){f*=0.8;why.push('en África acaban de cosechar');}}
    if(g==='aceite'&&!sell&&(mo>=10||mo<=1)){f*=0.8;why.push('en la Bética acaban de recoger la aceituna');}
    if(g==='plomo'&&sell&&mo>=3&&mo<=8){f*=1.15;why.push('en la buena estación se construye más');}
    if(sell){const e=comEv();if(e&&(e.g===g||e.g==='*')){f*=e.f;why.push(e.t.charAt(0).toLowerCase()+e.t.slice(1,-1));}}
    return comLogos(sell?G.s:G.b,f,why,sell);};}
// ---- 2a. la carrera del Circo Máximo (desde Félix)
const CIRC={y:45,x0:35,x1:125,rin:9,rout:36};
function circD(x,y){const cx=clamp(x,CIRC.x0,CIRC.x1);return Math.hypot(x-cx,y-CIRC.y);}
function circPt(s,r){const S=CIRC.x1-CIRC.x0,A=Math.PI*r,L=2*S+2*A;s=((s%L)+L)%L;
  if(s<S)return[CIRC.x0+s,CIRC.y+r];s-=S;if(s<A){const th=Math.PI/2-s/r;return[CIRC.x1+r*Math.cos(th),CIRC.y+r*Math.sin(th)];}s-=A;
  if(s<S)return[CIRC.x1-s,CIRC.y-r];s-=S;const th=-Math.PI/2-s/r;return[CIRC.x0+r*Math.cos(th),CIRC.y+r*Math.sin(th)];}
function circLen(r){return 2*(CIRC.x1-CIRC.x0)+2*Math.PI*r;}
function circS(x,y){const r=Math.max(1,circD(x,y)),S=CIRC.x1-CIRC.x0,A=Math.PI*r;
  if(x>=CIRC.x0&&x<=CIRC.x1)return y>CIRC.y?x-CIRC.x0:S+A+(CIRC.x1-x);
  if(x>CIRC.x1){const th=Math.atan2(y-CIRC.y,x-CIRC.x1);return S+(Math.PI/2-th)*r;}
  let th=Math.atan2(y-CIRC.y,x-CIRC.x0);let ph=-Math.PI/2-th;ph=((ph%(2*Math.PI))+2*Math.PI)%(2*Math.PI);return 2*S+A+ph*r;}
function mgQuad(x,c,col,t){x.save();x.translate(c.x,c.y);x.rotate(c.a);if(c.crash)x.rotate(Math.sin(t*20)*0.4);
  x.fillStyle='#6b4a2e';x.fillRect(-1.6,-0.9,1.6,1.8);x.fillStyle=col;x.fillRect(-1.4,-0.7,1.2,1.4);x.strokeStyle='#3a2a1a';x.lineWidth=0.15;x.beginPath();x.moveTo(0,0);x.lineTo(1.2,0);x.stroke();
  const ph=t*14+(c.ph||0);for(let i=0;i<4;i++){const yy=-1.35+i*0.9,bob=Math.sin(ph+i)*0.15;x.fillStyle=['#5a3a22','#d8cfc0','#3a2a1e','#8a6a4a'][i];x.beginPath();x.ellipse(2.6+bob,yy,1.2,0.32,0,0,TAU);x.fill();x.beginPath();x.arc(3.7+bob,yy,0.22,0,TAU);x.fill();}
  if(c.me){x.strokeStyle='#e8b07a';x.lineWidth=0.3;x.strokeRect(-1.7,-1,1.8,2);}x.restore();
  if(c.me){x.fillStyle='#e8b07a';x.font='2.3px Georgia';x.textAlign='center';x.fillText('tú',c.x,c.y-2.6);x.textAlign='left';}}
const MG_CIRCO={id:'circo',title:'Una carrera en el Circo Máximo',
 intro:'<p>Félix te deja subir a su cuadriga para un entrenamiento… y esa noche sueñas que corres con los Verdes ante doscientas cincuenta mil personas. Tres vueltas (en las carreras de verdad son siete) alrededor de la spina, la barrera central con el obelisco de Augusto.</p><p>Las curvas, junto a las metae, son peligrosas: si chocas contra la spina o contra el muro a mucha velocidad, tu carro se hace pedazos (un naufragium) y pierdes un tiempo precioso. Usa el látigo con cuidado: los caballos se cansan.</p>',
 ctl:'<b>A</b> y <b>D</b> (o las flechas) para girar, <b>W</b> para el látigo, <b>S</b> para frenar.',ctlT:'Gira con <b>◀</b> y <b>▶</b>; <b>Látigo</b> para acelerar; <b>Frenar</b> en las curvas.',
 touch:[['ArrowLeft','◀'],['KeyS','Frenar'],['KeyW','Látigo'],['ArrowRight','▶']],
 src:'Plinio, Historia natural VIII 160 y XXXVI 102; Dionisio de Halicarnaso III 68; Suetonio, Calígula 55. Inscripción de Diocles, CIL VI 10048. En el juego hay cuatro carros; en el Circo podían correr doce.',
 first:'¡Cae la mappa! Las puertas de los carceres se abren.',winT:'¡Victoria de los Verdes!',failT:'No has ganado',
 init(G){const r=[14,19,24,29];G.cars=r.map((rr2,i)=>({x:CIRC.x0+2+i*0.5,y:CIRC.y+rr2,a:0,v:0,ln:rr2,me:i===1,col:['#c0392b','#2e8b3a','#e8e4da','#2f5d9a'][i],laps:0,half:false,top:15.6+Math.random()*2.6,ph:i,st:100,crash:0}));G.p=G.cars[1];G.done=false;G.place=0;G.order=[];},
 tick(G,dt){const P=G.p;
  for(const c of G.cars){if(c.crash>0){c.crash-=dt;c.v*=0.9;if(c.crash<=0){const s=circS(c.x,c.y),q=circPt(s,c.ln);c.x=q[0];c.y=q[1];}continue;}
    if(c.me){const tr=(mgk('KeyA','ArrowLeft')?-1:0)+(mgk('KeyD','ArrowRight')?1:0);const whip=mgk('KeyW','ArrowUp')&&c.st>0,brake=mgk('KeyS','ArrowDown');
      const tv=whip?21:brake?7:15;c.v+=(tv-c.v)*Math.min(1,dt*(brake?2:1.1));if(whip)c.st=Math.max(0,c.st-22*dt);else c.st=Math.min(100,c.st+8*dt);c.a+=tr*2.3*dt*(1-c.v/45);}
    else{const s=circS(c.x,c.y),q=circPt(s+7,c.ln),want=Math.atan2(q[1]-c.y,q[0]-c.x);c.a+=clamp(wrapA(want-c.a),-2.2*dt,2.2*dt);const curve=c.x<CIRC.x0+4||c.x>CIRC.x1-4;c.v+=((curve?c.top*0.78:c.top)-c.v)*dt*0.9;}
    c.x+=Math.cos(c.a)*c.v*dt;c.y+=Math.sin(c.a)*c.v*dt;
    if(c.me&&(c.x<CIRC.x0||c.x>CIRC.x1)&&c.v>14){const cx=c.x<CIRC.x0?CIRC.x0:CIRC.x1,dd=Math.hypot(c.x-cx,c.y-CIRC.y)||1,push=(c.v-14)*(c.v-14)*0.05*dt;c.x+=(c.x-cx)/dd*push;c.y+=(c.y-CIRC.y)/dd*push;if(!G.dw&&c.v>17){G.dw=1;mgSay('¡Derrapas en la curva! Afloja el látigo.',2);}}else if(c.me)G.dw=0;
    const d=circD(c.x,c.y);if(d<CIRC.rin+1.5||d>CIRC.rout-1.5){const hard=c.v>12;const cx=clamp(c.x,CIRC.x0,CIRC.x1),nx=(c.x-cx)/(d||1),ny=(c.y-CIRC.y)/(d||1),tgt=d<CIRC.rin+1.5?CIRC.rin+1.6:CIRC.rout-1.6;c.x=cx+nx*tgt;c.y=CIRC.y+ny*tgt;
      if(hard){c.crash=2.6;c.v=0;if(c.me)mgSay(d<CIRC.rin+2?'¡Naufragium! Rozas la spina en la curva y el carro vuelca. Los mozos lo enderezan…':'¡Naufragium! Te estrellas contra el muro. El público ruge.',3);}else c.v*=0.6;}
    // vueltas: cruzar la línea blanca (x=80) en la recta de abajo, después de haber pasado por la de arriba
    if(c.y<CIRC.y)c.half=true;if(c.half&&c.y>CIRC.y&&c.px!==undefined&&c.px<80&&c.x>=80){c.laps++;c.half=false;if(c.laps>=3&&!c.fin){c.fin=true;G.order.push(c);if(c.me)G.place=G.order.length;}
      else if(c.me&&c.laps<3)mgSay(_t(10310,'Vuelta ')+c.laps+' de 3. Un delfín de bronce se gira en la spina.',2.5);}
    c.px=c.x;}
  for(let i=0;i<G.cars.length;i++)for(let j=i+1;j<G.cars.length;j++){const a=G.cars[i],b=G.cars[j],d=Math.hypot(a.x-b.x,a.y-b.y);if(d<2.4){const nx=(a.x-b.x)/(d||1),ny=(a.y-b.y)/(d||1);a.x+=nx*0.5;a.y+=ny*0.5;b.x-=nx*0.5;b.y-=ny*0.5;a.v*=0.97;b.v*=0.97;}}
  if(G.place)return G.place===1?'win':'fail';if(G.order.length>=3&&!G.p.fin)return 'fail';return null;},
 draw(G,x){const t=G.t;x.fillStyle='#6a5a44';x.fillRect(0,0,160,90);x.fillStyle='#c9b48b';x.beginPath();x.arc(CIRC.x0,CIRC.y,CIRC.rout,Math.PI/2,Math.PI*1.5);x.lineTo(CIRC.x1,CIRC.y-CIRC.rout);x.arc(CIRC.x1,CIRC.y,CIRC.rout,-Math.PI/2,Math.PI/2);x.closePath();x.fill();
  for(let i=0;i<220;i++){x.fillStyle='rgba(120,90,60,.16)';x.fillRect((i*37.3)%160,(i*23.9)%90,0.5,0.5);}
  x.fillStyle='#b8a888';x.fillRect(CIRC.x0,CIRC.y-2.2,CIRC.x1-CIRC.x0,4.4);x.fillStyle='#7a9ab0';x.fillRect(CIRC.x0+4,CIRC.y-1,CIRC.x1-CIRC.x0-8,2);
  x.fillStyle='#d8c8a0';x.beginPath();x.moveTo(78,CIRC.y-1);x.lineTo(80,CIRC.y-6);x.lineTo(82,CIRC.y-1);x.fill();
  for(const mx of[CIRC.x0,CIRC.x1])for(let k=0;k<3;k++){x.fillStyle='#d9a93a';x.beginPath();x.moveTo(mx-1+k,CIRC.y-2.4);x.lineTo(mx-0.5+k,CIRC.y-5);x.lineTo(mx+k,CIRC.y-2.4);x.fill();}
  const laps=G.p.laps;for(let k=0;k<3;k++){x.fillStyle=k<laps?'#d9a93a':'#8a7a5a';x.beginPath();x.ellipse(96+k*4,CIRC.y,1.4,0.6,k<laps?Math.PI:0,0,TAU);x.fill();}
  x.strokeStyle='#f4f0e6';x.lineWidth=0.4;x.beginPath();x.moveTo(80,CIRC.y+CIRC.rin);x.lineTo(80,CIRC.y+CIRC.rout);x.stroke();
  x.fillStyle='#8a7a5a';for(let i=0;i<6;i++)x.fillRect(CIRC.x0-CIRC.rout-1,CIRC.y-15+i*5,3,4);
  x.fillStyle='rgba(30,20,10,.75)';x.font='2.4px Georgia';x.fillText('carceres',2,CIRC.y-18);x.fillText('PALATINO',70,3.2);x.fillText('AVENTINO',70,89);
  for(const c of G.cars)mgQuad(x,c,c.col,t);},
 hud(G){const P=G.p;return 'Vuelta: <b>'+Math.min(3,P.laps+1)+'</b> de 3 · Caballos: <span style="display:inline-block;width:90px;height:9px;background:rgba(255,255,255,.2);vertical-align:middle"><span style="display:block;height:100%;width:'+P.st.toFixed(0)+'%;background:#2e8b3a"></span></span>'+(P.crash>0?' · <span style="color:#ffb070">¡naufragium!</span>':'');},
 after(G,res){return (res==='win'?'<p>Cruzas la línea el primero. Los partidarios de los Verdes, que llevan pañuelos verdes, saltan en las gradas. El presidente de los juegos te entrega la palma y una corona.</p>':'<p>'+(G.place?'Llegas en '+['','primer','segundo','tercer','cuarto'][G.place]+' lugar.':'Otro carro cruza antes la línea.')+' Los aurigas profesionales tardan años en dominar las curvas.</p>')+
  '<p>Los aurigas eran casi siempre esclavos o libertos, pero los mejores se hacían ricos y famosísimos. Una inscripción de Roma cuenta la carrera de Diocles, un lusitano del siglo II: 4.257 carreras, 1.462 victorias y casi 36 millones de sestercios en premios. Muchos morían jóvenes en un naufragium.</p>';}};
// ---- 2b. la huida de Miseno (desde Plinio)
const MG_MISENO={id:'miseno',title:'La noche de Miseno',
 intro:'<p>Plinio te cuenta la noche del Vesubio, y sueñas que eres él. 25 de agosto del 79, en Miseno, al otro lado del golfo. Ha amanecido, pero la luz es débil y la tierra tiembla. Tu madre te pide que huyas solo; tú te niegas y la llevas de la mano.</p><p>Sal de la ciudad hacia el norte, lejos del mar, entre la multitud. Cae ceniza: de vez en cuando hay que pararse a sacudírsela, o el peso te aplastará. Cuidado con las piedras pómez que caen (sus sombras te avisan). No dejes atrás a tu madre.</p>',
 ctl:'<b>W A S D</b> (o las flechas) para caminar; mantén <b>Espacio</b> para sacudirte la ceniza.',ctlT:'Camina con las flechas; mantén <b>Sacudir</b> para quitarte la ceniza.',
 touch:[['ArrowLeft','◀'],['ArrowUp','▲'],['Space','Sacudir'],['ArrowDown','▼'],['ArrowRight','▶']],
 src:'Plinio el Joven, Cartas VI 16 y VI 20, escritas a Tácito.',
 first:'«Sigamos por el camino mientras aún se ve», dices a tu madre.',winT:'Habéis salido de Miseno',failT:'La oscuridad os alcanza',
 init(G){G.p={x:80,y:86,ash:0,hp:3};G.m={x:80,y:87};G.stones=[];G.crowd=[];for(let i=0;i<26;i++)G.crowd.push({x:rr(10,150),y:rr(15,80),vx:rr(-2,2),vy:rr(-4,1)});G.sT=1;G.dark=0;G.lost=0;},
 tick(G,dt){const P=G.p,M=G.m;G.dark=Math.min(1,G.t/40);const shake=mgk('Space');
  if(shake){P.ash=Math.max(0,P.ash-45*dt);}else P.ash=Math.min(100,P.ash+(4+G.dark*6)*dt);
  const sp=shake?0:4.4*(1-P.ash/160),mx=(mgk('KeyD','ArrowRight')?1:0)-(mgk('KeyA','ArrowLeft')?1:0),my=(mgk('KeyS','ArrowDown')?1:0)-(mgk('KeyW','ArrowUp')?1:0),l=Math.hypot(mx,my)||1;
  P.x=clamp(P.x+mx/l*sp*dt,4,156);P.y=clamp(P.y+my/l*sp*dt,3,88);
  const dm=Math.hypot(P.x-M.x,P.y-M.y);if(dm>2){const v=Math.min(dm-2,3.9*dt);M.x+=(P.x-M.x)/dm*v;M.y+=(P.y-M.y)/dm*v;}
  if(dm>9){G.lost+=dt;if(G.lost>0.2&&!G.wm){G.wm=1;mgSay('«¡Hijo, sigue tú, yo soy vieja y pesada!». No la sueltes: espérala.',3);}if(G.lost>5){mgSay('Has perdido a tu madre entre la multitud.',3);return 'fail';}}else{G.lost=0;G.wm=0;}
  if(P.ash>=100){mgSay('El peso de la ceniza te tira al suelo.',3);return 'fail';}if(P.ash>70&&!G.wa){G.wa=1;mgSay('Pesas mucho: para y sacúdete la ceniza (Espacio).',2.5);}if(P.ash<40)G.wa=0;
  for(const c of G.crowd){c.x+=c.vx*dt;c.y+=c.vy*dt;if(c.x<4||c.x>156)c.vx*=-1;if(c.y<4||c.y>86)c.vy*=-1;const d=Math.hypot(c.x-P.x,c.y-P.y);if(d<1.6){P.x+=(P.x-c.x)/d*0.4;P.y+=(P.y-c.y)/d*0.4;}}
  G.sT-=dt;if(G.sT<0){G.sT=0.4+Math.random()*0.6;G.stones.push({x:clamp(P.x+rr(-14,14),4,156),y:clamp(P.y+rr(-16,6),4,86),t:0,r:rr(1.2,2.2)});}
  for(const s of G.stones){s.t+=dt;if(s.t>1.2&&!s.hit){s.hit=1;if(Math.hypot(s.x-P.x,s.y-P.y)<s.r+0.6){P.hp--;mgSay(P.hp>0?'¡Una piedra te golpea en el hombro!':'Una piedra te derriba.',2);if(P.hp<=0)return 'fail';}}}
  G.stones=G.stones.filter(s=>s.t<1.8);if(P.y<6&&dm<9)return 'win';return null;},
 draw(G,x){const t=G.t,P=G.p;x.fillStyle='#4a4038';x.fillRect(0,0,160,90);x.fillStyle='#2a3a48';x.fillRect(0,86,160,4);
  x.fillStyle='#5a5048';for(let i=0;i<12;i++){x.fillRect(4+i*13,20+((i*7)%30),7,5);}x.strokeStyle='#6a5e52';x.lineWidth=3;x.beginPath();x.moveTo(80,90);x.bezierCurveTo(70,60,95,40,78,0);x.stroke();
  for(const c of G.crowd){x.fillStyle='#2a221c';x.beginPath();x.arc(c.x,c.y,0.8,0,TAU);x.fill();}
  for(const s of G.stones){if(s.t<1.2){x.fillStyle='rgba(0,0,0,'+(0.15+s.t*0.35)+')';x.beginPath();x.arc(s.x,s.y,s.r*(0.4+s.t/2),0,TAU);x.fill();}else{x.fillStyle='#b8b0a0';x.beginPath();x.arc(s.x,s.y,s.r*0.6,0,TAU);x.fill();}}
  x.fillStyle='#c9b48b';x.beginPath();x.arc(G.m.x,G.m.y,0.8,0,TAU);x.fill();x.fillStyle='#e8d8b0';x.beginPath();x.arc(P.x,P.y,0.85,0,TAU);x.fill();x.strokeStyle='rgba(232,216,176,.6)';x.lineWidth=0.15;x.beginPath();x.moveTo(P.x,P.y);x.lineTo(G.m.x,G.m.y);x.stroke();
  for(let i=0;i<40;i++){x.fillStyle='rgba(200,195,185,.35)';x.fillRect((i*31.7+t*3)%160,(i*17.3+t*9)%90,0.3,0.6);}
  const r=60-G.dark*42,g=x.createRadialGradient(P.x,P.y,r*0.3,P.x,P.y,r);g.addColorStop(0,'rgba(10,8,6,0)');g.addColorStop(1,'rgba(10,8,6,'+(0.5+G.dark*0.45)+')');x.fillStyle=g;x.fillRect(0,0,160,90);
  x.fillStyle='rgba(230,220,200,.7)';x.font='2.4px Georgia';x.fillText('al norte: fuera de la ciudad',58,4);x.fillText('Miseno · el puerto de la flota',4,89);},
 hud(G){return 'Ceniza: <span style="display:inline-block;width:90px;height:9px;background:rgba(255,255,255,.2);vertical-align:middle"><span style="display:block;height:100%;width:'+G.p.ash.toFixed(0)+'%;background:#b8b0a0"></span></span> · '+'●'.repeat(Math.max(0,G.p.hp))+(G.lost>0?' · <span style="color:#ffb070">¡tu madre se queda atrás!</span>':'');},
 after(G,res){return (res==='win'?'<p>Salís de la ciudad y os sentáis junto al camino. Cae una oscuridad «no como la de una noche sin luna, sino como la de una habitación cerrada con la lámpara apagada». Se oyen gritos de mujeres, llantos de niños, voces de hombres que llaman a sus padres, a sus hijos, a sus esposas.</p>':'<p>Te despiertas sobresaltado.</p>')+
  '<p>Plinio, que entonces tenía diecisiete años, contó aquella noche en dos cartas a su amigo Tácito. Su tío, Plinio el Viejo, almirante de la flota de Miseno, había cruzado el golfo con sus barcos para ayudar a los que huían y murió en la playa de Estabias, ahogado por los gases. Gracias a esas cartas, a las erupciones como aquella las llamamos hoy «plinianas».</p>';}};
// ---- 3. el debate de Claudio: ¿galos en el Senado? (desde Tácito)
const CLAUDIO_R=[
 {ath:'Italia no está tan agotada como para no poder dar senadores a su capital. Antes bastaban los nacidos aquí para gobernar a los pueblos de nuestra sangre. ¿Qué honor les quedará a los nobles que quedan, o a un senador pobre del Lacio, si los ricos de la Galia lo llenan todo?',ref:'Anales XI 23',
  op:[['«Mis antepasados, los Claudios, eran sabinos: Atta Clauso fue recibido a la vez en la ciudadanía y entre los patricios. Ese ejemplo me pide hacer lo mismo.»','Un senador viejo murmura: «Eso fue hace quinientos años, César». Pero otros asienten: la familia del propio emperador vino de fuera.','Anales XI 24'],
   ['«Ya tenemos senadores de Etruria, de Lucania, de toda Italia. Y la colonia de Vienne, en la Galia, nos ha dado senadores dignos. ¿Dónde está la frontera de la virtud?»','«Italia es Italia», responde alguien. Claudio sonríe: «Italia, un día, también fue el extranjero».','Anales XI 24; tabla de Lyon'],
   ['«¿Nos arrepentimos de que los Balbos vinieran de Hispania, y otros no menos ilustres de la Galia Narbonense? Sus descendientes siguen entre nosotros, y no aman menos a esta patria.»','Varios senadores miran a un Cornelio Balbo sentado en los bancos: su familia, de Gades, lleva un siglo en el Senado.','Anales XI 24']]},
 {ath:'¿Llenaremos el Senado con los descendientes de quienes mataron a nuestras legiones y sitiaron al divino Julio en Alesia? Que tengan el nombre de ciudadanos, pero no las insignias de los senadores ni los honores de los magistrados.',ref:'Anales XI 23',
  op:[['«Esparta y Atenas, tan fuertes en la guerra, cayeron porque trataban a los vencidos como extranjeros. Rómulo, en cambio, tuvo a muchos pueblos por enemigos y por ciudadanos el mismo día.»','Se hace el silencio. Es el argumento más famoso del discurso: la fuerza de Roma ha sido siempre convertir a los vencidos en romanos.','Anales XI 24'],
   ['«Los galos llevan cien años de paz y lealtad, incluso cuando mi padre Druso los sometió a censo en plena guerra contra los germanos.»','«Cien años», repite alguien. Muchos de los presentes tienen en sus villas esclavos y amigos galos.','Anales XI 24'],
   ['«Ya tienen nuestras costumbres, nuestras artes y se casan con los nuestros: que traigan aquí su oro y su riqueza, en vez de guardarlos aparte.»','Los senadores más ricos asienten: el oro galo en Roma les interesa a todos.','Anales XI 24']]}];
function claudioDlg(n){const B=$('dBody'),o=$('dOpts'),m=m386z();let r=0;const add=(t,fn,c)=>{const b=document.createElement('button');b.className=c||'';b.innerHTML='<span class="n">'+(o.children.length+1)+'</span><span>'+t+'</span>';b.onclick=fn;o.appendChild(b);};
  const round=()=>{const R0=CLAUDIO_R[r];o.innerHTML='';B.innerHTML='<p class="sub">Año 48. Los nobles de la Galia Comata, ciudadanos romanos, piden poder ser senadores. En la Curia, el emperador Claudio va a hablar, y tú hablas por él.</p><p><b>Un senador:</b> «'+R0.ath+'»</p><p class="sub">Tácito, '+R0.ref+'</p>';
    R0.op.forEach(op=>add(op[0],()=>{B.innerHTML='<p><b>Tú, como Claudio:</b> '+op[0]+'</p><p>'+op[1]+'</p><p class="sub">'+op[2]+'. Claudio usó de verdad este argumento.</p>';o.innerHTML='';r++;add(r<CLAUDIO_R.length?_t(3080,'Seguir'):'Llega la votación',r<CLAUDIO_R.length?round:decide);},'quiz'));};
  const decide=()=>{o.innerHTML='';B.innerHTML='<p>Claudio termina con una frase que Tácito recordará: «Todo lo que hoy se cree antiquísimo, padres conscriptos, fue un día nuevo… También esto que hoy defendemos con ejemplos se convertirá en un ejemplo». ¿Qué vota el Senado?</p>';
    add('Admitir a los nobles galos en el Senado',()=>end(true),'quiz');add('Rechazarlo: que sigan siendo ciudadanos sin honores',()=>end(false),'quiz');};
  const end=res=>{o.innerHTML='';const first=!m.claudio;m.claudio=res?'si':'no';if(first){qAdd('lo',3,'Has convencido al Senado.');qAdd('so',1);}save();
    B.innerHTML=(res?'<p>Así fue. El Senado aprobó la propuesta, y los primeros en ser admitidos fueron los eduos, aliados de Roma desde hacía siglos, a los que Roma llamaba «hermanos del pueblo romano».</p>':'<p>En la realidad el Senado aprobó la propuesta: los primeros fueron los eduos. Pero muchos senadores pensaban como tú, y Tácito recoge sus razones.</p>')+
      '<p>El discurso de Claudio se grabó en una gran tabla de bronce que se colocó en Lugdunum, la ciudad donde él había nacido. En 1528 la encontró un campesino en Lyon, y hoy se puede leer en el museo de la ciudad. Al compararla con el texto de Tácito vemos que el historiador resumió y mejoró el discurso, pero conservó sus argumentos.</p><p class="sub">Para pensar: ¿qué hace que alguien sea «de los nuestros»? ¿Por qué Roma duró tanto más que Atenas o Esparta?</p>'+(first?'<p class="sub">+3 Lógos · +1 Sophía</p>':'');
    add(_t(2954,'Volver a la conversación'),()=>{B.innerHTML=_t(2955,'<p>Pregunta lo que quieras.</p>');renderOpts();});};
  round();}
// ---- 4. patrias nuevas para el peregrino
ORIG.roma.push(
 {id:'cartago',n:'Cartago, en África',de:'de Cartago',gm:'cartaginés',gf:'cartaginesa',pn:'Lucio Cecilio Saturnino',pt:'De la estación de los africanos',look:{chiton:'#efe6d4',himation:'#8a5a2a',hair:'#1a120c',beard:true},
  pi:'¡Salve, paisano! Lucio Cecilio, de Cartago. Aquí nos miran raro: Cartago fue la enemiga de Roma. Pero hoy es una colonia romana, la capital de África, y sin nuestro trigo Roma pasaría hambre.',
  tp:[['¿Qué piensan aquí de Cartago?','Todos conocen la historia: Aníbal, los elefantes, «Cartago debe ser destruida». La destruyeron en el 146 antes de Cristo. Un siglo después, César y Augusto la refundaron como colonia romana. Hoy es una de las ciudades más grandes del Imperio. En casa hablamos púnico todavía, pero en el foro, latín.'],['¿Qué noticias hay de África?','Que el emperador Vespasiano, el padre de Tito, fue procónsul de África hace años, y en Hadrumetum el pueblo le tiró nabos en un motín. ¡Y ahora su hijo es emperador! África da trigo a Roma ocho meses al año: no te dejes mirar por encima del hombro.']],
  bark:['¿Cartaginés? ¡Que no venga Aníbal!','De África viene el trigo y viene el polvo, dicen.'],react:'Al oír «de Cartago», levanta una ceja: «¿De la Cartago de Aníbal?».'},
 {id:'gades',n:'Gades, en la Bética',de:'de Gades',gm:'gaditano',gf:'gaditana',pn:'Lucio Cornelio Balbo, nieto',pt:'De la estación de los gaditanos',look:{chiton:'#efe6d4',himation:'#6a3a5a',hair:'#2a1a12'},
  pi:'¡Salve! Soy un Cornelio Balbo, como el famoso. Gades es la ciudad más antigua de Occidente, la fundaron los fenicios de Tiro. Y fue un gaditano, mi antepasado Balbo, el primer cónsul de Roma nacido fuera de Italia.',
  tp:[['¿Quién fue Balbo?','Lucio Cornelio Balbo, gaditano, amigo y banquero de César. Fue cónsul en el 40 antes de Cristo, el primero nacido fuera de Italia. Su sobrino celebró un triunfo y construyó en Roma un teatro de piedra, el Teatro de Balbo, en el Campo de Marte. Y amplió Gades con una ciudad nueva.'],['¿Qué saben de Gades en Roma?','Que tenemos el templo de Hércules, adonde Aníbal fue a cumplir sus votos antes de partir hacia Italia y donde César lloró ante la estatua de Alejandro, que nuestro garum es el mejor y que nuestras bailarinas, las puellae gaditanae, bailan con crótalos en los banquetes. Marcial escribe de ellas. A los poetas les gusta más esto que nuestra historia.']],
  bark:['¿Gaditano? ¡Baila algo!','De Gades viene el mejor garum. ¿Traes un ánfora?'],react:'Al oír «de Gades», sonríe: «El fin del mundo, las Columnas de Hércules».'},
 {id:'lugdunum',n:'Lugdunum, en la Galia',de:'de Lugdunum',gm:'lugdunense',gf:'lugdunense',pn:'Gayo Julio Víctor',pt:'De la estación de los galos',look:{chiton:'#efe6d4',himation:'#4f6a3a',hair:'#8a5a2a',beard:true},
  pi:'¡Salve! Soy Gayo Julio Víctor, de Lugdunum. Nuestra ciudad es la capital de las tres Galias: allí se reúnen cada uno de agosto los delegados de sesenta pueblos ante el altar de Roma y de Augusto.',
  tp:[['¿Somos bien recibidos en Roma?','Mejor que antes. El emperador Claudio, que nació en Lugdunum, convenció al Senado de admitir a los nobles galos. Su discurso está grabado en bronce en nuestra ciudad. Pero aún hay quien nos llama «galos de pantalones» y recuerda que nuestros antepasados quemaron Roma hace cinco siglos.'],['¿Qué hacen los galos en Roma?','De todo: senadores, mercaderes de vino, soldados. Y la cerámica roja que se hace en el sur de la Galia se vende en todo el Imperio. Y los pantalones, que aquí se reían de ellos, ya los llevan hasta algunos romanos en invierno.']],
  bark:['¿Galo? ¡Esconde las ocas del Capitolio!','Los de Lugdunum tenéis buen vino. Y buenas tejas.'],react:'Al oír «de Lugdunum», asiente: «La ciudad de Claudio».'},
 {id:'antioquia',n:'Antioquía, en Siria',de:'de Antioquía',gm:'antioqueno',gf:'antioquena',pn:'Teófilo',pt:'De la estación de los sirios',look:{chiton:'#efe6d4',himation:'#2a5a6a',hair:'#1a120c',beard:true},
  pi:'¡Salud, paisano! Teófilo, de Antioquía. La tercera ciudad del mundo, después de Roma y Alejandría, con una gran calle de pórticos que la cruza de punta a punta. Aquí en Roma somos muchos los sirios.',
  tp:[['¿Qué noticias hay de Antioquía?','Que hace diez años, después de tomar Jerusalén, Tito pasó por Antioquía y la gente le pidió que expulsara a los judíos de la ciudad. Tito se negó: «Su patria ha sido destruida; ¿adónde iban a ir?». Lo cuenta Josefo. En Antioquía viven griegos, sirios, judíos y también esos a los que llaman cristianos: allí les pusieron ese nombre.'],['¿Cómo ven aquí a los sirios?','Con desconfianza y con curiosidad. Traemos tejidos, especias, músicos, adivinos, tañedoras de arpa. Un poeta dirá un día, quejándose, que el río Orontes se ha vertido en el Tíber. Pero Roma no sería Roma sin nosotros.']],
  bark:['¿Sirio? ¿Me lees el futuro?','De Antioquía vienen los mejores tejidos de púrpura.'],react:'Al oír «de Antioquía», se inclina: «La reina de Oriente».'});
// ---- 5. capítulo de historia: «El pan de Roma»
if(typeof STORY_ROMA!=='undefined')STORY_ROMA.push({cat:_t(9673,'Economía'),title:'El pan de Roma',
 actors:[{id:'tercia11',name:_t(10070,'Tercia'),title:_t(10071,'Tu hermana'),look:LKR.tercia,at:'npc:mercader',dx:5,dz:3}],
 intro:'Ha pasado un mes. Tercia, tu hermana, ya libre, no para de hacer preguntas. Hoy, en el Emporio, ha visto descargar sacos de trigo durante horas y quiere saber de dónde viene el pan que comen un millón de personas. Tiberio Claudio Eutiques, el comerciante de grano, os ofrece un viaje en uno de sus barcos.',
 steps:[
  {obj:'Reúnete con Tercia en el Emporio, junto al comerciante de grano',actor:'tercia11',scene:[
   [_t(10070,'Tercia'),'¡Mira cuántos sacos! ¿Todo esto se lo come Roma? ¿Y de dónde sale?'],
   [_t(9966,'Eutiques'),'De África y de Egipto, sobre todo. Flavio Josefo, el historiador judío que vive en Roma bajo la protección de los Flavios, dice que África alimenta a Roma ocho meses al año y Egipto los otros cuatro. Cada mes, el Estado reparte trigo gratis a unos doscientos mil ciudadanos.'],
   {who:_t(9966,'Eutiques'),ask:'Según Josefo, ¿cuántos meses al año alimenta África a Roma?',a:[_t(6738,'Ocho'),'Dos',_t(3595,'Doce')],ok:'Eso es: ocho. Y Egipto, los otros cuatro. Si un año falla la cosecha o se hunden los barcos, en Roma hay motines.',ko:'Más. África es el granero principal: ocho meses al año.'},
   [_t(9966,'Eutiques'),'Mi barco sale mañana hacia Cartago. Id a verlo con vuestros propios ojos.'],
   ['','Navegáis cuatro días hacia el sur, pasando junto a Sicilia. Cartago aparece al fondo de su golfo.'],{fn:()=>storyTravel('npc:himilcon',6,6)}]},
  {obj:'Habla con Gayo Julio Himilcón, el comerciante de trigo de Cartago',npc:'himilcon',scene:[
   ['Himilcón','¿Romanos, aquí? Mis abuelos maldecían a Roma; yo le vendo trigo, y me va bien. El trigo de África crece en las grandes fincas del interior, y baja en carros hasta el puerto.'],
   ['Himilcón','Pero el mar no está siempre abierto. Del 11 de noviembre al 10 de marzo casi nadie navega: es el «mar cerrado». Por eso el emperador Claudio prometía pagar las pérdidas a quien se arriesgara a traer trigo en invierno.'],
   {choose:[['«¿Y si un barco se hunde?»',[['Himilcón','Entonces pierdo la carga, y el prestamista pierde su dinero: por eso cobran tanto interés. Pero si llega, gano el doble.']],'riesgo'],['«¿Por qué no se cultiva el trigo en Italia?»',[['Himilcón','Se cultiva, pero los grandes propietarios prefieren las viñas y los olivos, que dan más. Y traerlo por mar desde aquí es más barato que en carro desde el interior de Italia.']],'campo']]},
   [_t(10070,'Tercia'),'Y el trigo de Egipto, ¿cómo es?'],['Himilcón','Id a verlo. A Alejandría, con un barco que sale hoy.'],{fn:()=>storyTravel('npc:heron',6,6)}]},
  {obj:'Habla con Herón, en Alejandría',npc:'heron',scene:[
   ['Herón','Egipto es del emperador, no del Senado: ningún senador puede venir sin su permiso, para que nadie se apodere del granero de Roma. El Nilo crece cada verano, y del limo nace el trigo.'],
   ['Herón','Las naves del trigo de Alejandría son las más grandes del mar: algunas cargan más de mil toneladas. Cuando llegan a Puteoli, toda la ciudad baja al muelle: son las únicas que pueden llevar desplegada la vela de arriba, y así se las reconoce de lejos.'],
   {who:'Herón',ask:'¿Por qué ningún senador podía entrar en Egipto sin permiso del emperador?',a:['Para que nadie pudiera apoderarse del trigo que alimentaba a Roma','Porque los egipcios no querían romanos','Porque estaba prohibido por los dioses'],ok:'Exacto. Quien controlara Egipto podía matar de hambre a Roma. Augusto lo convirtió en una provincia especial, gobernada por un prefecto suyo.',ko:'Piensa en el trigo: quien controla Egipto controla el pan de Roma.'},
   [_t(10070,'Tercia'),'Volvamos a casa. Quiero contárselo todo a mamá.'],{fn:()=>storyTravel('actor:tercia11',4,4)}]},
  {obj:'Vuelve con Tercia al Emporio',actor:'tercia11',scene:[
   [_t(10070,'Tercia'),'Entonces, cada pan que comemos ha cruzado el mar. Si hay tormenta, o guerra, o un mal año en el Nilo… en Roma hay hambre.'],
   {who:_t(10070,'Tercia'),ask:'¿Por qué los emperadores se preocupaban tanto del trigo?',a:['Porque una ciudad de un millón de personas dependía del mar para comer, y el hambre provocaba motines','Porque el trigo era sagrado','Porque los soldados no comían otra cosa'],ok:'Eso es. Juvenal resumirá lo que quería el pueblo de Roma en dos palabras: pan y circo.',ko:'Piensa en el millón de personas y en los barcos.'},
   [_t(10070,'Tercia'),'«Pan y circo». Bueno, el circo ya lo hemos visto. Mañana, ¿me llevas a ver una carrera?']]}],
 end:'Con Tercia has seguido el trigo desde los campos de África y el Nilo hasta el Emporio de Roma.',
 learn:'Roma, con cerca de un millón de habitantes, dependía del trigo importado por mar, sobre todo de África y de Egipto. El Estado repartía trigo gratuito a unos 200.000 ciudadanos (la annona), y los emperadores cuidaban el abastecimiento porque el hambre provocaba disturbios. Egipto era una provincia especial del emperador, cerrada a los senadores. La navegación se interrumpía en invierno (mare clausum).'});
// ---- 6. misiones romanas
Object.assign(MISION_TXT,{plomo:'Eros, en Carthago Nova, quiere saber si su plomo acaba en Roma: busca un tubo con sello en las Termas de Tito.',anforas:'Quinto Fulvio, en Corduba, quiere que mires las etiquetas de sus ánforas en los almacenes de Galba, en Roma.',oro:'Pintaio, en Las Médulas, quiere saber adónde va el oro que sacan de la montaña: pregunta en el templo de Saturno, en el Foro.'});
function m386OptsR(n,add){const m=m386z();if(MODE!=='roma')return;
  if(n.id==='auriga')add(m.mg_circo?'Volver a soñar con una carrera':'Soñar con una carrera en el Circo Máximo (minijuego)','quiz',()=>mgOpen(MG_CIRCO));
  if(n.id==='plinio')add(m.mg_miseno?'Volver a soñar la noche de Miseno':'Soñar la noche de Miseno (minijuego)','quiz',()=>mgOpen(MG_MISENO));
  if(n.id==='tacito')add(m.claudio?'Volver a hablar por Claudio':'Revivir el debate de Claudio sobre los galos','quiz',()=>claudioDlg(n));
  const one=(k,who,ask,on,ok,okFn)=>{if(n.id!==who)return;const st=m['ms_'+k];if(st==='fin')return;
    add(!st?ask:st==='hecho'?ok:'Sobre lo que me pediste…','quiz',()=>{const B=$('dBody');if(!st){m['ms_'+k]='on';save();B.innerHTML=on;toast('<span class="label">Misión</span><br>'+MISION_TXT[k]);renderOpts();}
      else if(st==='hecho'){m['ms_'+k]='fin';state.obols+=6+klBonus();qAdd('kl',2,'Has cumplido un encargo.');save();updateStats();sfxCoin();B.innerHTML=okFn();renderOpts();}else{B.innerHTML='<p>'+MISION_TXT[k]+'</p>';renderOpts();}});};
  one('plomo','eros_cn',_t(9574,'¿Puedo hacer algo por ti?'),'<p>«Cada lingote que sale de aquí lleva un sello con el nombre del dueño de la mina. Dicen que en Roma el plomo acaba en tuberías y en los tejados de los templos. Si vas, busca un tubo de plomo con letras y dime qué pone. Me gustaría saber que mi trabajo sirve para algo».</p>','He visto un tubo de plomo en las Termas de Tito',()=>'<p>Le cuentas que los tubos de las nuevas termas llevan grabado el nombre del emperador y el del fontanero que los hizo. Eros se ríe. «Así que el plomo es mío, el trabajo de los esclavos, y el nombre, del emperador. Siempre igual». Te da seis sestercios.</p>');
  one('anforas','olearius',_t(9574,'¿Puedo hacer algo por ti?'),'<p>«Mando cientos de ánforas a Roma cada año. Cada una lleva pintado el peso y mi nombre. Me han dicho que algunas no llegan a los almacenes de Galba, junto al Emporio. ¿Podrías mirar si están las mías?».</p>','He visto tus ánforas en los almacenes',()=>'<p>Le cuentas que has visto filas de ánforas redondas con su nombre pintado: «Q. Fulvi Rustici». Respira aliviado. «Las ánforas vacías no se pueden reutilizar: el aceite las impregna. En Roma las rompen y amontonan los trozos detrás de los almacenes. Dicen que ya hay una colina de cascotes». Te da seis sestercios.</p><p class="sub">Esa colina, el monte Testaccio, llegará a tener unos 50 millones de ánforas, la mayoría de aceite de la Bética.</p>');
  one('oro','astur',_t(9574,'¿Puedo hacer algo por ti?'),'<p>«Derribamos montañas enteras con agua para sacar el oro. Mi abuelo luchó contra Roma en estos montes; yo cavo para ella. Si vas a Roma, pregunta adónde va nuestro oro. Dicen que lo guardan en un templo».</p>','Ya sé adónde va el oro',()=>'<p>Le cuentas que Plinio calcula que de Asturia, Gallaecia y Lusitania salen unas veinte mil libras de oro al año, y que el oro de las minas va al tesoro del emperador, el fisco, no a los pueblos que lo sacan. Pintaio se queda callado mucho rato. «Veinte mil libras. Y aquí ni un anillo». Insiste en darte seis sestercios.</p>');}
function m386SetupR(){if(MODE!=='roma')return;const P=id=>placeAt(id);
  const te=P('ro_termas');if(te)egxObj(te.x+5,te.z+4,undefined,'m:fistula','Un tubo de plomo','fistula');
  const ho=P('ro_horrea');if(ho)egxObj(ho.x+4,ho.z+3,undefined,'m:anforas','Ánforas de la Bética','tituli picti');
  const sa=P('ro_saturno');if(sa)egxObj(sa.x+5,sa.z+3,undefined,'m:aerarium','El tesoro de Saturno','aerarium');}
function m386ActR(o){const m=m386z(),one=casaOpen('◆',o.data.name,o.data.role||''),B=$('dBody');
  if(o.act==='m:fistula'){B.innerHTML='<p>Unos obreros entierran tubos de plomo para llevar el agua a las nuevas termas. Cada tramo está hecho con una lámina doblada y soldada, y lleva letras en relieve: <b>IMP · TITI · CAESARIS · AVG</b> y, debajo, el nombre del fontanero que lo fabricó.</p><p class="sub">Frontino, Los acueductos de Roma; se conservan cientos de fistulae con sellos.</p>';if(m.ms_plomo==='on'){m.ms_plomo='hecho';save();toast('<span class="label">Misión</span><br>Vuelve a Carthago Nova y cuéntaselo a Eros.');}one(_t(3080,'Seguir'),closeDialog);return;}
  if(o.act==='m:anforas'){B.innerHTML='<p>Filas de ánforas redondas y panzudas, de las que se usan para el aceite de la Bética. Tienen pintados en rojo y negro el peso del aceite, el nombre del mercader, <b>Q · FVLVI · RVSTICI</b>, y las marcas del control fiscal.</p><p class="sub">Estas etiquetas, los tituli picti, se han conservado a miles en el monte Testaccio, sobre todo de los siglos II y III.</p>';if(m.ms_anforas==='on'){m.ms_anforas='hecho';save();toast('<span class="label">Misión</span><br>Vuelve a Corduba y cuéntaselo a Quinto Fulvio.');}one(_t(3080,'Seguir'),closeDialog);return;}
  if(o.act==='m:aerarium'){B.innerHTML='<p>Bajo el templo de Saturno se guarda el tesoro público de Roma, el aerarium. Un esclavo público te explica que el oro de las minas de Hispania no viene aquí, sino al fisco, la caja del emperador. Plinio calcula que Asturia, Gallaecia y Lusitania dan unas veinte mil libras de oro al año.</p><p class="sub">Plinio, Historia natural XXXIII 78.</p>';if(m.ms_oro==='on'){m.ms_oro='hecho';save();toast('<span class="label">Misión</span><br>Vuelve a Las Médulas y cuéntaselo a Pintaio.');}one(_t(3080,'Seguir'),closeDialog);return;}}

