function placeLive(id,name,greek,text,x,z,rot){place(id,name,greek,text,x,z,rot);const pl=PLACES[PLACES.length-1];const st=stele(pl.x,pl.z,pl.rot,pl.id);signObjs.push({kind:'sign',data:pl,g:st.g,mk:st.mk,x:pl.x,z:pl.z});if(state&&Array.isArray(state.places)&&state.places.includes(pl.id)&&st.mk)st.mk.visible=false;}   // estela añadida con la partida ya empezada
