function dtL(I,lx,lz){return[I.x+lx,I.z+lz];}
function dtStone(x,z,w,h,d,mat,a){const y=floorAt(x,z);const m=box(w,h,d,mat||M.limestone,x,y+h/2,z);if(a)m.rotation.y=a;addBox(x,z,w,d,a||0);return m;}
