function delterTick(){if(!DT.kith||!aOK()||ui!=='play')return;const d=Math.hypot(player.x-DT.kx,player.z-DT.kz);if(d>30)return;const now=performance.now();if(now<DT.lyreT)return;DT.lyreT=now+7000+Math.random()*5000;playPhrase();}

