  if(L('eu')>=5)s+='<ellipse cx="236" cy="200" rx="12" ry="4" fill="#d9a93a" stroke="'+c+'" stroke-width="1.4"/>';
  if(L('kl')>=5){const P=pjz();s+='<rect x="226" y="330" width="108" height="26" fill="rgba(217,135,74,.12)" stroke="'+c+'" stroke-width="1.6"/><text x="280" y="348" text-anchor="middle" font-size="13" fill="#ecc29a" font-family="Georgia">'+((P&&P.name)||'').slice(0,16)+'</text>';}
  if(all)s+='<text x="280" y="378" text-anchor="middle" font-size="12" fill="#c8a050" font-family="Georgia" font-style="italic">Estatua de bronce</text>';
