// enunciados de las palabras latinas que ya estaban en la lista general
const VOC_LAT_EN={guerra:'bellum, -i (n.)',ciudadano:'civis, -is (m./f.)',casa:'domus, -us (f.)',hijo:'filius, -i (m.)',río:'flumen, -inis (n.)',hermano:'frater, -tris (m.)',mar:'mare, -is (n.)',muerte:'mors, mortis (f.)',noche:'nox, noctis (f.)',paz:'pax, pacis (f.)',pueblo:'populus, -i (m.)',puerta:'porta, -ae (f.)',niño:'puer, -i (m.)',rey:'rex, regis (m.)',esclavo:'servus, -i (m.)',templo:'templum, -i (n.)',tierra:'terra, -ae (f.)',ciudad:'urbs, urbis (f.)',camino:'via, -ae (f.)'};
const VOC_LAT_SEC=[];   // secciones de los dos maestros nuevos: [nombre, [claves]]
(function vocLatParse(){const add=v=>{VOCAB.push(v);return v.k;};
  const nouns=[],names=[];
  for(const ln of VOC_LAT_N.split('\n')){const f=ln.split('|');if(f.length===1){nouns.push(f[0]);continue;}
    const[k,en,m,es,la,der,pre]=f,head=en.split(',')[0];
    if(!es){nouns.push(add({k:'la_'+k,ro:1,nos:1,en,m,es:[m],l:[head],el:der}));continue;}
    nouns.push(add({k:'la_'+k,ro:1,en,m,es:es.split(','),l:la.split(','),el:der,pre:pre==='1'?1:0}));}
  for(const ln of VOC_LAT_P.split('\n')){const[k,en,m,es,la]=ln.split('|');names.push(add({k:'lp_'+k,ro:1,en,m,es:es.split(','),l:la.split(','),el:''}));}
  VOC_LAT_SEC.push(['Sustantivos',nouns],['Nombres propios',names]);
  for(const[sec,txt]of VOC_LAT_O){const ks=[];for(const ln of txt.split('\n')){const[en,m,der]=ln.split('|');ks.push(add({k:'lo_'+en,ro:1,nos:1,en,m,es:[m],l:[en],el:der||''}));}VOC_LAT_SEC.push([sec,ks]);}
  for(const k in VOC_LAT_EN){const v=VOCAB.find(x=>x.k===k);if(v)v.en=VOC_LAT_EN[k];}for(const v of VOCAB)VOC_K[v.k]=v;})();
// trocea una sección en lecciones de seis palabras (la última se queda con el resto)
function vocChunk(ks,n){const L=[];for(let i=0;i<ks.length;i+=n)L.push(ks.slice(i,i+n));if(L.length>1&&L[L.length-1].length<3)L[L.length-2].push(...L.pop());return L;}
function vocSecLessons(name,ks){const head=k=>{const v=VOCAB.find(x=>x.k===k);return v?(v.en||v.l[0]).split(/[ ,]/)[0]:k;};return vocChunk(ks,6).map((L,i)=>[name+' '+(i+1)+': '+head(L[0])+' – '+head(L[L.length-1]),L]);}

VOC_T.roma.push(
 {id:'grammaticus',at:()=>artAnchor('ro_grammaticus',6,6)||artAnchor('ro_basilica_julia',-10,8),look:{chiton:'#e0d8c8',himation:'#5a4a6a',hair:'#8a8070',staff:true},name:'Valerio Probo',sub:'grammaticus de Berito',glyph:'G',
  intro:'Un hombre mayor lee un rollo a la sombra, rodeado de unos pocos jóvenes. «No tengo escuela: tengo amigos que vienen a preguntar», dice sin levantar la vista. «Si quieres leer a César y a Virgilio, empieza por las palabras que más usan».',
  note:'Marco Valerio Probo, de Berito (la actual Beirut), fue el gramático más sabio de la época flavia: corregía y comentaba los textos de Virgilio, Horacio y Lucrecio. Según Suetonio, no daba clases como un maestro corriente: recibía por la tarde a unos pocos discípulos y conversaba con ellos. Sus palabras son las de una lista escolar de latín: lo más frecuente en los autores que se leen en clase.',
  S:VOC_LAT_SEC.slice(0,4).map(([n,ks])=>[n,vocSecLessons(n,ks)])},
 {id:'rhetor',at:()=>artAnchor('ro_paz',-12,10)||artAnchor('ro_basilica_julia',12,-8),look:{chiton:'#e8e0d0',himation:'#e8e0d0',hair:'#3a2a1a'},name:_t(10322,'Quintiliano'),sub:'rhetor, maestro de oratoria',glyph:'Q',
  intro:'Un hispano de unos cuarenta y cinco años corrige a un alumno que declama con demasiados aspavientos. «Un orador sin palabras exactas es como un soldado sin armas», te dice. «Los verbos son la acción del discurso; las partículas, sus articulaciones. Empecemos».',
  note:'Marco Fabio Quintiliano, nacido en Calagurris (Calahorra), fue uno de los primeros maestros de retórica que cobró un sueldo del Estado, por decisión de Vespasiano. Hacia el 95 escribirá la Institutio oratoria, un tratado sobre cómo educar a un orador desde la infancia. Sus palabras son las de una lista escolar de latín.',
  S:VOC_LAT_SEC.slice(4).map(([n,ks])=>[n,vocSecLessons(n,ks)])});
for(const m in VOC_T)for(const T of VOC_T[m])if(!T.S)T.S=[['',T.L]];
const VOC={mode:'orig',re:null,map:null,ver:-1,vlen:-1};
try{const m=localStorage.getItem('nostos-voc');if(m==='orig'||m==='tr'||m==='off')VOC.mode=m;}catch(e){}
function vocz(){if(!state.voc||typeof state.voc!=='object')state.voc={w:{},l:{}};if(!state.voc.w)state.voc.w={};if(!state.voc.l)state.voc.l={};return state.voc;}
function vocKnown(k){return !!vocz().w[k];}
function VOCM(){return VOCAB.filter(v=>!v.ro||MODE==='roma');}
function vocCount(){return VOCM().filter(v=>vocKnown(v.k)).length;}
function vocEff(){return MODE==='roma'&&VOC.mode==='tr'?'orig':VOC.mode;}
function vocForm(v,i){const ro=MODE==='roma';return ro?v.l[i]:(vocEff()==='tr'?v.gt[i]:v.g[i]);}
function vocMean(v){return v.m||(v.es[2]?v.es[0]+' / '+v.es[2]:v.es[0]);}
function vocLbl(v,gi){return v.m||(gi===2&&v.es[2]?v.es[2]:v.es[0]);}
function vocShow(v,i,full){const ro=MODE==='roma';if(ro&&full&&v.en){const c=v.en.indexOf(',');return c>0&&!v.nos?'<b class="vw">'+v.en.slice(0,c)+'</b>'+v.en.slice(c):'<b class="vw">'+v.en+'</b>';}return '<b class="vw">'+(ro?v.l[i||0]:v.g[i||0])+'</b>'+(ro?'':' <i class="vtr">'+v.gt[i||0]+'</i>');}
// expresión regular con todas las formas en español de las palabras aprendidas
function vocBuild(){const known=Object.keys(vocz().w).filter(k=>VOC_K[k]&&!VOC_K[k].nos&&(!VOC_K[k].ro||MODE==='roma')),sig=known.join(',')+'|'+MODE+'|'+vocEff();if(VOC.sig===sig)return;VOC.sig=sig;
  VOC.map=new Map();for(const k of known){const v=VOC_K[k];v.es.forEach((f,i)=>{if(!VOC.map.has(f))VOC.map.set(f,[v,i]);});}
  const fs=[...VOC.map.keys()].sort((a,b)=>b.length-a.length);VOC.re=fs.length?new RegExp('(?<![\\p{L}])('+fs.join('|')+')(?![\\p{L}])','giu'):null;}
const VOC_PRE_VINO=/(?:^|[^\p{L}])(el|la|los|las|un|una|unos|unas|de|del|al|su|sus|mi|mis|tu|tus|buen|buena|mucho|mucha|poco|poca|este|esta|ese|esa|y|con|sin|o|más|menos|por|para|nuestra|nuestro|gran|copa|jarra|ánfora|pedir|pide|piden|pidió)\s+$/iu;
const VOC_SE=/(?:^|[^\p{L}])(se|te|me|le|lo|la|nos|os|les)\s+$/iu;
function vocWalk(root){if(!root||vocEff()==='off'||!state)return;vocBuild();if(!VOC.re)return;
  const tw=document.createTreeWalker(root,NodeFilter.SHOW_TEXT),nodes=[];while(tw.nextNode())nodes.push(tw.currentNode);
  for(const tn of nodes){const pe=tn.parentElement;if(!pe||pe.closest('.voc,.novoc,input,textarea,button,.label,script,style,svg'))continue;const txt=tn.nodeValue;VOC.re.lastIndex=0;let m,last=0,frag=null;
    while((m=VOC.re.exec(txt))){const low=m[0].toLowerCase(),hit=VOC.map.get(low);if(!hit)continue;const[v,i]=hit,before=txt.slice(Math.max(0,m.index-14),m.index);
      if(v.pre&&!VOC_PRE_VINO.test(before))continue;if(v.k==='casa'&&VOC_SE.test(before))continue;
      let out=vocForm(v,i);if(m[0][0]!==m[0][0].toLowerCase())out=out[0].toUpperCase()+out.slice(1);
      frag=frag||document.createDocumentFragment();frag.appendChild(document.createTextNode(txt.slice(last,m.index)));
      const s=document.createElement('span');s.className='voc';s.textContent=out;s.dataset.t=(MODE==='roma'?'':v.gt[i]+' · ')+m[0].toLowerCase();s.title=s.dataset.t;frag.appendChild(s);last=m.index+m[0].length;}
    if(frag){frag.appendChild(document.createTextNode(txt.slice(last)));tn.parentNode.replaceChild(frag,tn);}}}
// la sustitución se hace justo antes de que el diálogo empiece a escribirse solo
const twStart0=twStart;
twStart=function(){try{vocWalk($('dBody'));}catch(e){}twStart0();};
function vocCSS(){if($('vocCSS'))return;const s=document.createElement('style');s.id='vocCSS';s.textContent=
 '.voc{color:#f0c890;border-bottom:1px dotted rgba(240,200,144,.7);cursor:help;position:relative;white-space:nowrap}'+
 '.voc::after{content:attr(data-t);position:absolute;left:50%;bottom:calc(100% + 4px);transform:translateX(-50%);background:#1c140e;color:#f1e8d8;border:1px solid #d9874a;border-radius:6px;padding:2px 8px;font-size:.82em;font-style:normal;white-space:nowrap;opacity:0;pointer-events:none;transition:opacity .15s;z-index:5}'+
 '.voc:hover::after,.voc.on::after{opacity:1}'+
 '.vlist{margin:8px 0}.vlist div{padding:6px 0;border-bottom:1px solid rgba(217,135,74,.18)}.vw{font-size:1.15em;color:#f0c890}.vtr{opacity:.8}.vlist .sub{display:block;margin-top:2px}'+
 '.vq{text-align:center;margin:10px 0}.vq .vw{font-size:2em;display:block}';document.head.appendChild(s);}
vocCSS();
$('dBody').addEventListener('click',e=>{const v=e.target.closest&&e.target.closest('.voc');if(!v)return;document.querySelectorAll('.voc.on').forEach(x=>{if(x!==v)x.classList.remove('on');});v.classList.toggle('on');});
// ---- ajuste del menú
function vocLabel(){const ro=MODE==='roma';return (ro?'Palabras en latín':'Palabras en griego')+': '+(vocEff()==='off'?'no':ro?'sí':vocEff()==='tr'?'transliteradas':'alfabeto griego');}
function vocToggle(){const ro=MODE==='roma';VOC.mode=ro?(vocEff()==='off'?'orig':'off'):(VOC.mode==='orig'?'tr':VOC.mode==='tr'?'off':'orig');try{localStorage.setItem('nostos-voc',VOC.mode);}catch(e){}VOC.sig=null;
  toast(vocEff()==='off'?'Las palabras aprendidas se verán en español.':ro?'Las palabras que has aprendido aparecerán en latín en los diálogos.':vocEff()==='tr'?'Las palabras que has aprendido aparecerán en griego, escrito con nuestras letras.':'Las palabras que has aprendido aparecerán en griego, con su alfabeto.');}
GM_IC.voc='<path d="M4 4.5h16v11H10l-5 4v-4H4z"/><path d="M9 12.5l2.2-5.5 2.2 5.5M9.8 10.6h2.8"/><path d="M15.5 7.5v5"/>';
// ---- maestros
function vocSetup(){vocz();const L=VOC_T[MODE]||[];L.forEach((T,ti)=>{let f=T.at();if(!f)return;artPerson(f,T.look,'vc:'+ti,T.name,T.sub,3);});}
function vocLessonDone(T,si,li){return T.S[si][1][li][1].every(vocKnown);}
function vocAct(o){const ti=+String(o.act).slice(3),T=VOC_T[MODE][ti];if(!T)return;const one=casaOpen(T.glyph,T.name,T.sub),B=$('dBody'),ro=MODE==='roma',len=ro?'latín':'griego',tot=VOCM().length;
  const how=()=>'<div class="novoc"><p>Cuando aciertes el significado de un sustantivo, lo verás en '+len+' en el resto de diálogos del juego, en lugar de en español.'+(ro?' Los verbos, adjetivos y partículas solo se aprenden: meterlos en frases en español las volvería ilegibles.':' Puedes elegir verlo con el alfabeto griego o escrito con nuestras letras.')+'</p><p>Si no recuerdas qué significa, <b>pasa el ratón por encima o tócalo</b>.</p><p class="sub">Si te agobia, puedes cambiarlo o desactivarlo en el menú (Tab o el botón ☰) → «'+vocLabel()+'».</p></div>';
  const tail=()=>{if(vocCount())one('¿Qué palabras sé ya? ('+vocCount()+'/'+tot+')',()=>top(vocReview()));one('¿Cómo veré las palabras que aprenda?',()=>top(how()));one(_t(2951,'Despedirse'),closeDialog);};
  const lessons=(si)=>{T.S[si][1].forEach((Ls,li)=>{const n=Ls[1].filter(vocKnown).length,N=Ls[1].length,open=li===0||vocLessonDone(T,si,li-1);
      if(open)one((n===N?'Repasar: ':'Lección: ')+Ls[0]+' ('+n+'/'+N+')',()=>teach(si,li),n===N?'':'quiz');});};
  const secCount=si=>{const ks=T.S[si][1].flatMap(L=>L[1]);return ks.filter(vocKnown).length+'/'+ks.length;};
  const top=html=>{$('dOpts').innerHTML='';B.innerHTML=html;if(T.S.length===1)lessons(0);else T.S.forEach((S,si)=>one(S[0]+' ('+secCount(si)+')',()=>sec(si,'<div class="novoc"><p>«'+S[0]+'». Ve lección por lección: cada una se abre al terminar la anterior.</p></div>')));tail();};
  const sec=(si,html)=>{if(T.S.length===1)return top(html);$('dOpts').innerHTML='';B.innerHTML=html;lessons(si);one(_t(2961,'Volver'),()=>top('<div class="novoc"><p>«¿Qué más quieres aprender?»</p></div>'));};
  top('<div class="novoc"><p>'+T.intro+'</p><p class="sub">'+T.note+'</p><p class="sub">Sabes '+vocCount()+' de '+tot+' palabras en '+len+'.</p></div>');
  function teach(si,li){const Ls=T.S[si][1][li],W=Ls[1].map(k=>VOC_K[k]);$('dOpts').innerHTML='';
    B.innerHTML='<div class="novoc"><p>«'+Ls[0]+'». Escucha bien:</p><div class="vlist">'+W.map(v=>'<div>'+vocShow(v,0,true)+(!ro&&v.es[2]?' / '+vocShow(v,2):'')+(ro&&!v.en&&v.es[2]?' / '+vocShow(v,2):'')+' — <b>'+vocMean(v)+'</b>'+((ro?v.el:v.eg)?'<span class="sub">'+(ro?v.el:v.eg)+'</span>':'')+'</div>').join('')+'</div></div>';
    one('Ya me las sé: pregúntame',()=>quiz(si,li,0,0),'quiz');one(_t(2961,'Volver'),()=>sec(si,'<div class="novoc"><p>«Cuando quieras».</p></div>'));}
  function quiz(si,li,qi,ok){const Ls=T.S[si][1][li],W=Ls[1].map(k=>VOC_K[k]);if(qi>=W.length)return end(si,li,ok);const v=W[qi],gi=(qi%2&&v.es[2]&&!v.m)?2:0;$('dOpts').innerHTML='';
    B.innerHTML='<div class="novoc"><p class="sub">Pregunta '+(qi+1)+' de '+W.length+'</p><div class="vq">'+(v.nos?vocShow(v,0,true):vocShow(v,gi))+'</div><p>«¿Qué significa?»</p></div>';
    const others=W.filter(x=>x!==v&&vocLbl(x,gi)!==vocLbl(v,gi)).sort(()=>R()-0.5).slice(0,3),opts=[v,...others].sort(()=>R()-0.5);
    opts.forEach(x=>one(vocLbl(x,gi),()=>{const good=x===v,nw=good&&!vocKnown(v.k);
      if(good){vocz().w[v.k]=1;if(nw)state.obols+=1;save();updateStats();try{sfxTap();}catch(e){}}
      $('dOpts').innerHTML='';B.innerHTML='<div class="novoc"><div class="vq">'+(v.nos?vocShow(v,0,true):vocShow(v,gi))+'</div><p>'+(good?'«¡Eso es!» ':'«No». ')+'Significa <b>'+vocLbl(v,gi)+'</b>.'+(nw&&!v.nos?' <span class="sub">Desde ahora la verás en '+len+' en los diálogos.</span>':'')+'</p></div>';
      one(_t(3080,'Seguir'),()=>quiz(si,li,qi+1,ok+(good?1:0)),'quiz');}));}
  function end(si,li,ok){const L=T.S[si][1],Ls=L[li],done=vocLessonDone(T,si,li),k='l'+T.id+'_'+si+'_'+li,first=done&&!vocz().l[k];$('dOpts').innerHTML='';
    if(first){vocz().l[k]=1;qAdd('so',1);qAdd('lo',1,'Aprender otra lengua te da palabras para pensar.');save();}
    B.innerHTML='<div class="novoc"><p>Has acertado '+ok+' de '+Ls[1].length+'.</p><p>'+(done?(first?'«Muy bien. Ya conoces todas las palabras de esta lección».':'«Veo que no se te olvidan».')+(li<L.length-1&&first?' <span class="sub">Se abre la lección siguiente.</span>':'')+(first&&li===L.length-1?' <span class="sub">Has terminado esta parte.</span>':''):'«Las que has fallado no cuentan todavía. Repásalas y vuelve a intentarlo».')+'</p></div>';
    if(done&&li<L.length-1)one('Siguiente lección',()=>teach(si,li+1),'quiz');one(_t(2961,'Volver'),()=>sec(si,'<div class="novoc"><p>«¿Algo más?»</p></div>'));one(_t(2951,'Despedirse'),closeDialog);}}
function vocReview(){const ks=VOCM().filter(v=>vocKnown(v.k));return '<div class="novoc"><p>Palabras que ya conoces ('+ks.length+'/'+VOCM().length+'):</p><div class="vlist">'+ks.map(v=>'<div>'+vocShow(v,0,true)+' — '+vocMean(v)+'</div>').join('')+'</div></div>';}

// ============================================================ LA JORNADA ROMANA (a partir de J. Carcopino, «La vida cotidiana en Roma»)
// Solo en el modo Roma. Carcopino describe sobre todo la Roma de Trajano (h. 100-120 d.C.); aquí se usa lo que ya vale para el 80,
// y se avisa de lo que es posterior. Barbería y ornatrix, termas de Tito, cena de clientes, micatio, el reloj de Augusto y sucesos de la calle.
function jrz(){if(!state.jr||typeof state.jr!=='object')state.jr={d:{}};if(!state.jr.d)state.jr.d={};return state.jr;}
function jrDone(k){return jrz().d[k]===(state.day||1);}
function jrMark(k){jrz().d[k]=state.day||1;save();}
function jrHora(){return Math.floor(clock.h-6)+1;}            // 1..12 de día
// duración de las horas según la estación (Roma, 42° N): de 8 h 54 min de luz en invierno a 15 h 6 min en verano
function jrDayLen(){let mo=0;try{mo=calNow().mo;}catch(e){}const doy=mo*30.4+15;return 12+3.1*Math.sin(2*Math.PI*(doy-80)/365);}
const JR_OBJS=[];
const JR={t:30+Math.random()*40,last:''};
const JR_RUMOR=['«¿Has oído? Los juegos del anfiteatro de Tito van a durar cien días. Dicen que morirán cinco mil fieras en uno solo».',
 '«Del Capitolio no ha quedado nada: el incendio se llevó el templo de Júpiter, el Panteón de Agripa y medio Campo de Marte. Tito ha dicho que lo paga todo de su bolsillo».',
 '«En Campania aún sacan muertos de la ceniza. Pompeya y Herculano han desaparecido, y con ellas el almirante Plinio, que fue a ayudar con la flota».',
 '«Agrícola sigue avanzando por Britania: este verano ha llegado hasta un estuario que llaman Taus. Más allá ya no hay nada, solo niebla y bárbaros pintados».',
 '«Dicen que el hermano del emperador, Domiciano, se pasa el día cazando moscas con un punzón. Y que no soporta que Tito sea tan querido».',
 '«Tito despidió a la reina Berenice al subir al trono. Los romanos no querían una reina judía en el Palatino; él lloraba, ella también».',
 '«El emperador dice que ha perdido el día si no ha hecho un favor a alguien. Ojalá me lo haga a mí: debo tres meses de alquiler»'];
function jrSetup(){JR_OBJS.length=0;if(MODE!=='roma')return;jrz();
  const add=(f,look,act,name,sub)=>{if(!f)return;artPerson(f,look,act,name,sub,3);};
  add(artAnchor('ro_subura',-12,8),{chiton:'#b8a888',hair:'#3a2a1a'},'jr:tonsor',_t(10355,'Ciro'),_t(10356,'tonsor de la Subura'));
  add(artAnchor('ro_termas',12,-14),{chiton:'#c8bca0',hair:'#4a3a2a'},'jr:termas',_t(10357,'Fortunato'),_t(10358,'balneator de las termas de Tito'));
  add(artAnchor('ro_palatino',-16,-12)||artAnchor('ro_clivus',8,8),Object.assign({},TOGA,{hair:'#8a8070'}),'jr:cena',_t(10359,'Sexto Nevio'),_t(10360,'patrono rico, invita a cenar'));
  add(artAnchor('ro_marcelo',16,12),{chiton:'#9a8a70',hair:'#2a1a10'},'jr:micatio',_t(4137,'Gavio'),_t(10361,'ocioso del Pórtico de Octavia'));
  const f=artAnchor('ro_obelisco',5,5);if(f)JR_OBJS.push(egxObj(f[0],f[1],undefined,'jr:reloj',_t(10362,'El reloj de Augusto'),_t(10363,'¿qué hora es en Roma?'),3));
  if(!ESSAYS.find(e=>e.id==='jornada'))ESSAYS.push(JR_ESSAY);}
function jrAct(o){const k=String(o.act).slice(3);if(k==='tonsor')return jrTonsor();if(k==='termas')return jrTermas();if(k==='cena')return jrCena();if(k==='micatio')return jrMicatio();if(k==='reloj')return jrReloj();}
// ---- la barbería (tonstrina) y la ornatrix
function jrTonsor(){const fem=typeof pjFem==='function'&&pjFem(),one=casaOpen('✂',_t(10355,'Ciro'),_t(10356,'tonsor de la Subura')),B=$('dBody');
  const menu=html=>{$('dOpts').innerHTML='';B.innerHTML=html;
    if(!fem){one('Afeitarme con el maestro lento (2 sestercios)',()=>jrShave(true),'quiz');one('Afeitarme rápido, en la esquina (1 sestercio)',()=>jrShave(false),'quiz');}
    else one('¿Y las mujeres? ¿Dónde se peinan?',()=>jrOrnatrix(),'quiz');
    one('¿Qué se cuenta por ahí?',()=>menu('<p>'+JR_RUMOR[Math.floor(R()*JR_RUMOR.length)]+'</p><p class="sub">La barbería era uno de los grandes mentideros de Roma: los clientes esperaban en bancos, se miraban en los espejos de las paredes y comentaban las noticias.</p>'));
    one('¿Por qué os afeitáis todos?',()=>menu('<p>«Porque así va el emperador, y así iba Augusto. Barba solo llevan los filósofos, los soldados en campaña y los que están de luto. El primer afeitado de un joven es una fiesta: la <i>depositio barbae</i>. Los pelos se guardan en una cajita y se ofrecen a los dioses; Nerón ofreció los suyos a Júpiter en una caja de oro».</p><p class="sub">La moda de la barba no volverá hasta Adriano, que la dejó crecer hacia el 117.</p>'));
    one(_t(2951,'Despedirse'),closeDialog);};
  menu('<p>Una tienda abierta a la calle, con bancos para los que esperan y espejos de metal pulido en las paredes. El barbero afila una navaja de hierro en una piedra de Hispania, escupiendo en ella. «¿Afeitado? Aquí, o con aquel de la esquina, si tienes prisa y poca piel que perder».</p><p class="sub">Nadie se afeitaba solo: las navajas eran de hierro, se mellaban enseguida y no había jabón. Solo agua.</p>');}
function jrShave(slow){const B=$('dBody'),cost=slow?2:1;$('dOpts').innerHTML='';const one=casaOpen('✂',_t(10355,'Ciro'),_t(10356,'tonsor de la Subura'));
  if(state.obols<cost){B.innerHTML='<p>«Sin dinero no hay navaja», dice el barbero.</p>';one(_t(2961,'Volver'),jrTonsor);return;}
  state.obols-=cost;save();updateStats();const cut=!slow&&R()<0.45,first=!jrDone('tonsor');jrMark('tonsor');
  if(slow){clock.h=Math.min(23.5,clock.h+1);B.innerHTML='<p>El maestro trabaja con una lentitud desesperante: repasa cada pelo, mira el espejo, vuelve a empezar. Pasa una hora larga. Cuando acaba, tu piel está lisa como el mármol y ni una gota de sangre.</p><p class="sub">Los barberos famosos eran tan lentos que Augusto aprovechaba para leer o escribir mientras lo afeitaban; Marcial bromea con uno que tardaba tanto que, al acabar, ya te había vuelto a crecer la barba.</p>';}
  else if(cut)B.innerHTML='<p>Un empujón de la gente que pasa y la navaja resbala: ¡sangre! El barbero, sin inmutarse, te tapa el corte con un emplasto de <b>telarañas empapadas en aceite y vinagre</b>.</p><p class="sub">Es el remedio que recoge Plinio el Viejo para las heridas del afeitado. Los cortes eran tan frecuentes que los juristas fijaron quién pagaba los daños si un barbero de la calle hería a un cliente.</p>';
  else B.innerHTML='<p>Cuatro pasadas rápidas, un poco de agua fría y listo. Te escuece, pero no sangras: hoy tienes suerte.</p>';
  if(first&&!cut)qAdd('kl',1,'Bien afeitado, te miran mejor.');one(_t(2961,'Volver'),jrTonsor,'quiz');one(_t(2951,'Despedirse'),closeDialog);}
function jrOrnatrix(){const B=$('dBody');$('dOpts').innerHTML='';const one=casaOpen('✂','La ornatrix','peinadora, vecina del barbero');
  B.innerHTML='<p>El barbero se ríe: «Aquí solo vienen hombres. Las señoras se peinan en casa, con su <i>ornatrix</i>. Mi vecina lo es: pásate».</p><p>La ornatrix te sienta en un taburete y despliega su arsenal: peines de hueso, horquillas, un hierro de rizar que se calienta en las brasas, tarros de tinte y de afeites.</p><p class="sub">En época flavia está de moda un peinado altísimo: una diadema de rizos sobre la frente, como una torre, con el resto del pelo recogido en un moño de trenzas. Se usaban postizos y pelucas, a veces de pelo rubio germano.</p>';
  one('Peinado a la moda flavia (2 sestercios)',()=>{if(state.obols<2){B.innerHTML='<p>«Primero el dinero, querida».</p>';return;}state.obols-=2;const first=!jrDone('tonsor');jrMark('tonsor');save();updateStats();if(first)qAdd('kl',1,'Con ese peinado no pasas desapercibida.');
    $('dOpts').innerHTML='';B.innerHTML='<p>Dos horas de tirones, rizos y horquillas. Te maquilla: blanco de tiza en la frente, rojo de ocre en las mejillas, ceniza en las cejas. Al mirarte al espejo de bronce, apenas te reconoces: llevas una torre de rizos sobre la frente.</p><p class="sub">El blanco de plomo, también usado para blanquear la piel, era venenoso. Y las ornatrices sufrían a menudo la ira de sus amas por un rizo mal puesto, como cuentan Marcial y Juvenal.</p>';one(_t(2961,'Volver'),jrTonsor,'quiz');one(_t(2951,'Despedirse'),closeDialog);},'quiz');
  one(_t(2961,'Volver'),jrTonsor);}
// ---- las termas de Tito
function jrTermas(){const one=casaOpen('♨',_t(10357,'Fortunato'),_t(10358,'balneator de las termas de Tito')),B=$('dBody'),h=jrHora(),noct=clock.h<6||clock.h>=18;$('dOpts').innerHTML='';
  if(noct){B.innerHTML='<p>«Cerrado. Las termas abren de día y cierran a la puesta de sol. Vuelve mañana después de comer».</p>';one(_t(2951,'Despedirse'),closeDialog);return;}
  B.innerHTML='<p>Las termas que Tito acaba de inaugurar junto al anfiteatro huelen todavía a cal y a mármol nuevo. El encargado cobra la entrada en una mesita: <b>un cuadrante</b>, la moneda más pequeña de Roma. Los niños entran gratis.</p><p class="sub">Es la hora '+h+'. Lo normal es venir después del trabajo, hacia la hora octava, cuando el agua está en su punto: así lo recomienda Marcial. '+(h<8?'Ahora aún hay poca gente.':'Ahora está lleno.')+'</p>';
  one('Pagar el cuadrante y entrar',()=>jrBath(0),'quiz');one(_t(2951,'Despedirse'),closeDialog);}
function jrBath(st){const B=$('dBody'),fem=typeof pjFem==='function'&&pjFem();$('dOpts').innerHTML='';const one=casaOpen('♨',_t(4042,'Termas de Tito'),'THERMAE TITI');
  const S=[
   ['El vestuario (apodyterium)','<p>Te desnudas en el vestuario, entre nichos para la ropa. Un esclavo, el <i>capsarius</i>, se ofrece a vigilarla por una propina: los robos de ropa en las termas son famosos.</p>'+(fem?'<p class="sub">En el 80 no hay ninguna ley que separe a hombres y mujeres en las termas: muchas mujeres prefieren baños solo para ellas, pero otras vienen aquí por los juegos de la palestra. Adriano impondrá horarios separados.</p>':''),[['Pagarle (1 sestercio)',1],['Arriesgarme',0]]],
   [_t(6481,'La palestra'),'<p>Antes del baño, ejercicio al aire libre, rodeado de pórticos. Unos juegan al <i>trigon</i>, pasándose la pelota en triángulo; otros al <i>harpastum</i>, a empujones; hay quien hace rodar un aro con un gancho o levanta pesas de plomo; los luchadores se untan de aceite y cera y se cubren de polvo para agarrarse.</p>',[['Jugar al trigon',0],['Correr con el aro',0],['Luchar',0]]],
   ['El sudatorio y el caldarium','<p>Pasas a las salas calientes, que caldea un horno a través del suelo hueco y las paredes. En el sudatorio, aire seco que te hace sudar a chorros; en el caldarium, una bañera de agua caliente y una fuente para refrescarte la cara.</p><p class="sub">Para limpiarse, nada de jabón: aceite y el <i>strigilis</i>, una rasqueta curva de metal con la que se raspa el sudor y la suciedad.</p>',[['Pagar a un esclavo que me rasque (1 sestercio)',1],['Rascarme yo solo',0]]],
   ['El tepidarium y el frigidarium','<p>Una sala templada para no pasar de golpe del calor al frío, y después la piscina fría, al aire libre. El agua llega del acueducto. Sales nuevo.</p><p class="sub">Después del baño, mucha gente se queda: pasea por los jardines, charla, lee en la biblioteca o come algo de los vendedores. Las termas son el gran lugar de reunión del pueblo romano.</p>',[['Salir',0]]]];
  const s=S[st];B.innerHTML='<p class="sub">'+s[0]+'</p>'+s[1];
  s[2].forEach(([t,c])=>one(t,()=>{if(c&&state.obols>=c){state.obols-=c;save();updateStats();}
    if(st===0&&!c&&R()<0.3){toast('<span class="label">¡Te han robado!</span><br>Al volver, falta tu túnica buena. Sales con una vieja que alguien dejó.');}
    if(st+1<S.length)jrBath(st+1);else{const first=!jrDone('termas');jrMark('termas');if(first){qAdd('ar',1,'El ejercicio y el baño te dejan como nuevo.');}clock.h=Math.min(18,clock.h+1);closeDialog();}},'quiz'));}
// ---- la cena de clientes
function jrCena(){const one=casaOpen('🍷',_t(10359,'Sexto Nevio'),'patrono rico'),B=$('dBody'),h=clock.h;$('dOpts').innerHTML='';
  if(jrDone('cena')){B.innerHTML='<p>«Hoy ya has cenado en mi casa, amigo. ¿Quieres que la gente diga que vives de mi mesa?»</p>';one(_t(2951,'Despedirse'),closeDialog);return;}
  if(h<14||h>=21){B.innerHTML='<p>«Ven a cenar, si quieres: en mi casa se cena a la hora nona, después del baño, como todo el mundo».</p><p class="sub">La cena (cena) era la comida principal y se tomaba a media tarde. Por la mañana bastaba un vaso de agua o un trozo de pan; a mediodía, un bocado rápido (prandium).</p>';one(_t(2951,'Despedirse'),closeDialog);return;}
  B.innerHTML='<p>Un esclavo, el <i>nomenclator</i>, anuncia tu nombre y te lleva al comedor, el <i>triclinium</i>: tres lechos alrededor de una mesa cuadrada, tres invitados en cada uno. Te toca el lecho más bajo, el de los clientes. Te quitan las sandalias, te lavan las manos y te recuestas sobre el codo izquierdo.</p>';
  one('Empezar a comer',()=>jrCena2(),'quiz');one('Mejor no, gracias',closeDialog);}
function jrCena2(){const B=$('dBody');$('dOpts').innerHTML='';const one=casaOpen('🍷',_t(10359,'Sexto Nevio'),'patrono rico');
  B.innerHTML='<p>Primero, los entrantes (<i>gustatio</i>): huevos, aceitunas, lechuga y vino con miel, el <i>mulsum</i>. Después llegan los platos fuertes, y te das cuenta de algo: al anfitrión le sirven ostras y un rodaballo enorme; a ti, unos mejillones y un pescadito. Él bebe un Falerno añejo; a ti te llenan la copa con un vino de este año.</p><p class="sub">Marcial y Plinio el Joven se quejan de estos anfitriones que invitan a mucha gente y luego sirven distinta comida según el rango del invitado.</p>';
  const end=(txt,q)=>{jrMark('cena');if(q)qAdd(q[0],q[1],q[2]);$('dOpts').innerHTML='';B.innerHTML=txt+'<p>Llegan los postres (<i>secundae mensae</i>): fruta, pasteles con miel. Antes, una ofrenda a los Lares de la casa. Al despedirte, te llevas las sobras envueltas en tu servilleta, como hacen todos.</p>';one('Volver a casa',closeDialog,'quiz');};
  one('Callar y comer lo que me sirvan',()=>end('<p>Comes en silencio. Nadie se fija en ti; tampoco te vuelven a invitar con muchas ganas.</p>',null),'quiz');
  one('Hacer una broma ingeniosa al respecto',()=>{if(qLv('lo')>=4)end('<p>«¿Por qué no cenamos juntos, Sexto, si cenamos a la vez?», dices en voz alta. La mesa entera se ríe; el anfitrión, colorado, manda que te sirvan de su rodaballo.</p>',['lo',2,'Una broma a tiempo vale más que un discurso.']);else end('<p>Intentas una broma, pero se te traba la lengua y nadie se ríe. El anfitrión te mira con frialdad.</p>',null);},'quiz');
  one('Quejarme abiertamente',()=>end('<p>Te quejas. Se hace un silencio helado. Un esclavo te retira la copa: esa noche no vuelves a beber.</p><p class="sub">Un cliente dependía de su patrono: quejarse en su mesa era perderlo.</p>',null),'quiz');}
// ---- la micatio
function jrMicatio(){const one=casaOpen('✋',_t(4137,'Gavio'),_t(10361,'ocioso del Pórtico de Octavia')),B=$('dBody');$('dOpts').innerHTML='';
  const n=jrz().mic===state.day?(jrz().micn||0):0;
  B.innerHTML='<p>Bajo las columnas del Pórtico de Octavia, un hombre sin nada que hacer te reta: «¿Una partida de <i>micatio</i>? Dos sestercios. Sacamos los dos a la vez los dedos que queramos y cantamos cuántos suman entre los dos. El que acierta, gana».</p><p class="sub">Los dados estaban prohibidos fuera de las Saturnales, pero la micatio no: era un juego de vista y de rapidez. De un hombre muy honrado se decía que «se podía jugar a la micatio con él a oscuras». Todavía se juega en Italia: es la morra.</p>';
  if(n>=3){B.innerHTML+='<p>«Por hoy ya está bien. Vuelve mañana».</p>';one(_t(2951,'Despedirse'),closeDialog);return;}
  if(state.obols>=2)one('Jugar (2 sestercios)',()=>{state.obols-=2;save();updateStats();const z=jrz();z.mic=state.day;z.micn=n+1;jrMicRound(0);},'quiz');
  one(_t(2951,'Despedirse'),closeDialog);}
function jrMicRound(r){const B=$('dBody');$('dOpts').innerHTML='';const one=casaOpen('✋',_t(4137,'Gavio'),_t(10361,'ocioso del Pórtico de Octavia'));
  if(r>=6){B.innerHTML='<p>Seis tiradas y nadie acierta. «Tablas: te devuelvo lo tuyo».</p>';state.obols+=2;save();updateStats();one(_t(2961,'Volver'),jrMicatio,'quiz');return;}
  B.innerHTML='<p class="sub">Tirada '+(r+1)+'. ¿Cuántos dedos sacas?</p>';
  for(let f=0;f<=5;f++)one(f===0?'El puño cerrado':f+(f===1?' dedo':' dedos'),()=>{$('dOpts').innerHTML='';B.innerHTML='<p class="sub">Sacas '+f+'. ¿Qué total cantas?</p>';
    for(let c=f;c<=f+5;c++)one('«¡'+['Ninguno',_t(9795,'Uno'),'Dos',_t(3594,'Tres'),_t(10364,'Cuatro'),_t(6560,'Cinco'),_t(10365,'Seis'),_t(3593,'Siete'),_t(6738,'Ocho'),'Nueve','Diez'][c]+'!»',()=>{
      const g=Math.floor(R()*6),gc=g+Math.floor(R()*6),tot=f+g,you=c===tot,him=gc===tot;$('dOpts').innerHTML='';
      B.innerHTML='<p>Gavio saca '+g+' y canta '+gc+'. En total, <b>'+tot+'</b>.</p>';
      if(you&&!him){state.obols+=4;save();updateStats();B.innerHTML+='<p>¡Has acertado! Te llevas los cuatro sestercios.</p>';if(!jrDone('micatio')){jrMark('micatio');qAdd('so',1,'Calcular deprisa también es saber.');}one(_t(2961,'Volver'),jrMicatio,'quiz');}
      else if(him&&!you){B.innerHTML+='<p>Gavio acierta y se guarda tus dos sestercios con una sonrisa.</p>';one(_t(2961,'Volver'),jrMicatio,'quiz');}
      else{B.innerHTML+='<p>'+(you?'Acertáis los dos: ':'Nadie acierta: ')+'otra tirada.</p>';one(_t(3080,'Seguir'),()=>jrMicRound(r+1),'quiz');}},'quiz');},'quiz');}
// ---- el reloj de Augusto: horas que cambian de duración
function jrReloj(){const one=casaOpen('◷',_t(10362,'El reloj de Augusto'),'Horologium Augusti'),B=$('dBody'),L=jrDayLen(),dm=Math.round(L*60/12),nm=Math.round((24-L)*60/12),h=clock.h;$('dOpts').innerHTML='';
  B.innerHTML='<p>La sombra del obelisco cae sobre las líneas de bronce del pavimento. Ahora es '+(typeof horaRomana==='function'?horaRomana(h):'')+'.</p><p>Los romanos dividían el día, de la salida a la puesta del sol, en <b>doce horas</b>, y la noche en otras doce. Pero como los días son más largos en verano que en invierno, <b>las horas no duraban siempre lo mismo</b>: en pleno invierno, una hora del día duraba unos 45 de nuestros minutos; en pleno verano, unos 75.</p><p>Esta época del año, cada hora del día dura unos <b>'+dm+' minutos</b>, y cada hora de la noche, unos <b>'+nm+'</b>.</p><p class="sub">Para la noche, más que horas, se contaban cuatro «vigilias», los turnos de guardia de los soldados. Los relojes de agua (clepsidras) permitían medir el tiempo de noche y en los días nublados, pero nunca coincidían del todo: Séneca bromea con que es más fácil poner de acuerdo a los filósofos que a los relojes. Por eso la vida romana nunca tuvo la puntualidad de la nuestra.</p>';
  one('¿Cómo era un día normal?',()=>{$('dOpts').innerHTML='';B.innerHTML='<p>Al amanecer, todo el mundo en pie: los clientes, con la toga, a saludar a su patrono (la salutatio). Por la mañana, el trabajo, los negocios y los juicios: la mayoría de los oficios paraban hacia la hora sexta o séptima. A mediodía, un bocado y quizá la siesta. Por la tarde, las termas, hacia la hora octava, y después la cena, la gran comida del día, hacia la hora nona. Con la noche, a dormir: la luz de los candiles era tan mala que se aprovechaba el sol.</p>';one(_t(2961,'Volver'),jrReloj);one(_t(2951,'Despedirse'),closeDialog);},'quiz');
  one(_t(2951,'Despedirse'),closeDialog);}
// ---- sucesos de la calle (solo en la ciudad de Roma, mientras caminas)
const JR_STREET_DAY=['Desde un tercer piso alguien vacía un orinal sin mirar. ¡Por poco! La ley permite denunciar al vecino desde cuya ventana cayó.',
 'Un pregonero anuncia a gritos unas salchichas calientes; otro, unos garbanzos tostados. La calle es un mercado.',
 'Una litera pasa abriéndose paso a empujones: delante, unos esclavos apartan a la gente; dentro, un rico lee tranquilamente.',
 'Ruido de obras: en el Campo de Marte reconstruyen lo que quemó el incendio de esta primavera. Andamios, grúas de rueda y polvo por todas partes.',
 'Un mendigo pide limosna en las escaleras de un templo, con un cartel pintado que cuenta su naufragio.',
 'Una ínsula de seis pisos cruje sobre tu cabeza. Los vecinos dicen que el dueño ha mandado apuntalarla «hasta que la arreglen»: nadie se lo cree.',
 'Un maestro grita a sus alumnos bajo un toldo, en plena calle. Los vecinos se quejan del jaleo desde antes del alba.'];
const JR_STREET_NIGHT=['Retumban los carros: desde Julio César, los carros de transporte solo pueden circular por Roma de noche. Nadie duerme en las calles principales.',
 'Pasa una patrulla de vigiles, los bomberos y guardias nocturnos, con cubos, hachas y mantas mojadas. En Roma hay incendios casi cada noche.',
 'Unos borrachos vuelven de una taberna cantando. De noche, sin antorcha, las calles de Roma son peligrosas: no hay alumbrado público.'];
function jrTick(dt){if(MODE!=='roma'||!state||ui!=='play'||typeof storyOn==='function'&&storyOn())return;JR.t-=dt;if(JR.t>0)return;JR.t=110+Math.random()*120;
  const c=PLACES.find(p=>p.id==='ro_rostra');if(!c||Math.hypot(player.x-c.x,player.z-c.z)>1100||MOUNT.riding)return;
  const night=clock.h<6||clock.h>=19,L=night?JR_STREET_NIGHT:JR_STREET_DAY;let t=L[Math.floor(R()*L.length)];if(t===JR.last)return;JR.last=t;
  toast('<span class="label">'+(night?'Roma de noche':'En la calle')+'</span><br>'+t);}
const JR_ESSAY={id:'jornada',cat:_t(1867,'Contexto'),title:'Un día en Roma',body:[
 'La jornada romana empezaba al amanecer, porque la luz de los candiles era pobre y cara. Levantarse era rápido: se dormía con la ropa interior y la túnica, y bastaba con calzarse y, si había que salir de visita, envolverse en la toga, una gran pieza de lana blanca tan pesada y difícil de colocar que muchos necesitaban ayuda. El desayuno era un vaso de agua o un poco de pan; el aseo de verdad se dejaba para las termas.',
 'Las horas romanas no eran como las nuestras: el día, de sol a sol, se dividía en doce horas, y la noche en otras doce, así que en invierno una hora de día duraba unos 45 minutos y en verano unos 75. Relojes de sol y de agua daban horas distintas, y nadie esperaba puntualidad.',
 'La primera obligación de la mañana era la salutatio: los clientes iban con la toga a saludar a su patrono, esperaban su turno según su rango y recibían la espórtula, una pequeña cantidad de dinero o comida. Luego venía el trabajo. En Roma había más de ciento cincuenta oficios organizados en corporaciones, de los panaderos a los estibadores del puerto del Tíber, pero casi todos paraban hacia la hora sexta o séptima: la tarde era para el ocio.',
 'Los hombres se afeitaban a diario en la barbería, que era también un lugar de tertulia; las mujeres se peinaban en casa con su ornatrix, que en época flavia les levantaba altísimos peinados de rizos. Por la tarde, Roma iba a las termas: ejercicio en la palestra, sala caliente, rasqueta y aceite, y baño frío, todo por un cuadrante. Tito inaugura las suyas, junto al anfiteatro, precisamente en el año 80.',
 'Hacia la hora nona llegaba la cena, la gran comida del día, tumbados en los lechos del triclinio: entrantes, platos fuertes y postres. Algunos anfitriones daban a los clientes peor comida y peor vino que a sí mismos, y Marcial se queja de ello con gracia. Por la noche, las calles se llenaban del estruendo de los carros, que solo podían circular de noche, y los vigiles vigilaban los incendios, constantes en unas ínsulas de madera y de cinco o seis pisos.',
 'Una advertencia: Jérôme Carcopino describe sobre todo la Roma de Trajano, hacia el 100-120 d.C., con textos de Marcial, Juvenal y Plinio el Joven. En el juego solo se usa lo que ya valía en el 80, y se avisa cuando algo es posterior, como la moda de la barba (Adriano) o la separación de horarios en las termas.'],
 src:{a:['Marcial, Epigramas','Séneca, Cartas a Lucilio','Plinio el Viejo, Historia natural'],m:['J. Carcopino, La vida cotidiana en Roma en el apogeo del Imperio (1939; trad. inglesa Daily Life in Ancient Rome)'],n:['Los textos del juego resumen con palabras propias las ideas de esa obra; no reproducen su texto.']}};

// ============================================================ LA ACADEMIA EN DIRECTO: una sesión con Platón (modo Atenas)
// Platón acaba de abrir su escuela en el bosque de Academo (h. 387 a.C.). La sesión avanza sola, como una conversación de verdad,
// y se detiene cuando Platón pregunta al jugador. Va enlazando lo que el jugador ya sabe (lecciones, caverna, sueños, palabras griegas…)
// y termina con un mapa del conocimiento. Los textos son del juego; las ideas, de los diálogos de Platón (Menón, Hipias mayor, República).
function acaz(){if(!state.aca||typeof state.aca!=='object')state.aca={n:0,done:0,best:0};return state.aca;}
const ACA={on:false,fig:null,ppl:[],line:0,timer:0,paused:false,steps:null,i:0,ok:0,box:null};
const ACA_WHO={P:_t(85,'Platón'),E:_t(442,'Espeusipo'),T:_t(459,'Teeteto'),J:'Un joven ateniense',N:'Narración'};
const ACA_COL={P:'#f0c890',E:'#a8c4e0',T:'#c8e0a0',J:'#e0b0c8',N:'#c9b9a2',Y:'#ffe2a8'};
// figuras que Platón dibuja en la arena (SVG en el diálogo)
function acaFig(k){const S=(w,h,inner)=>'<svg viewBox="0 0 '+w+' '+h+'" style="width:min(260px,70%);display:block;margin:6px auto;background:#d9c49a;border-radius:8px" aria-hidden="true"><g fill="none" stroke="#5a3a1e" stroke-width="2" stroke-linecap="round">'+inner+'</g></svg>';
  const T=(x,y,t)=>'<text x="'+x+'" y="'+y+'" fill="#5a3a1e" stroke="none" font-size="13" font-family="Georgia" text-anchor="middle">'+t+'</text>';
  if(k==='sq')return S(200,150,'<rect x="60" y="25" width="80" height="80"/>'+T(100,125,'lado 2 · área 4'));
  if(k==='sq4')return S(200,190,'<rect x="20" y="10" width="160" height="160"/><path d="M100 10v160M20 90h160" stroke-dasharray="4 4"/>'+T(100,185,'lado 4 · área 16, no 8'));
  if(k==='sq3')return S(200,170,'<rect x="40" y="10" width="120" height="120"/>'+T(100,155,'lado 3 · área 9, no 8'));
  if(k==='diag')return S(200,200,'<rect x="20" y="20" width="160" height="160" stroke-dasharray="4 4"/><path d="M100 20L180 100L100 180L20 100Z" stroke-width="3"/><path d="M20 20h80v80h-80z"/>'+T(100,196,'el cuadrado sobre la diagonal: área 8'));
  if(k==='sun')return S(220,150,'<circle cx="60" cy="60" r="22"/><path d="M60 22v-12M60 98v12M22 60h-12M98 60h12M33 33l-8-8M87 87l8 8M33 87l-8 8M87 33l8-8"/><path d="M130 95q20-30 40 0q-20 30-40 0z"/><circle cx="150" cy="95" r="6"/><path d="M98 70L128 92" stroke-dasharray="3 4"/>'+T(110,140,'el sol hace ver; el Bien hace conocer'));
  if(k==='alma')return S(220,160,'<circle cx="110" cy="40" r="22"/><path d="M60 80h100l-15 30H75z"/><path d="M50 130h120"/>'+T(110,45,'razón')+T(110,100,'ánimo')+T(110,150,'deseo'));
  return '';}
// enlaces con lo que el jugador ya ha hecho en el juego (cada uno solo si es verdad)
function acaKnows(){const L=state.lessons||[],P=state.places||[],K={};const kn=k=>{try{return vocKnown(k);}catch(e){return false;}};
  K.n=L.length;K.pl=P.length;K.my=(state.myths||[]).length;
  try{K.dream=dreamCount()[0];}catch(e){K.dream=0;}
  try{K.cav=cavz().done||cavz().visits;}catch(e){K.cav=0;}
  try{K.gor=finz().gor;K.eleu=finz().eleu;}catch(e){}
  try{K.cefis=artz().done&&artz().done.cefis;}catch(e){}
  try{K.ovid=Object.keys(ovz().seen||{}).length;}catch(e){K.ovid=0;}
  try{K.daed=wz().own||wz().got.length>0;}catch(e){}
  K.teeteto=L.includes('teeteto');K.isocrates=L.includes('isocrates');K.aristipo=L.includes('aristipo');K.antistenes=L.includes('antistenes');K.orfeo=L.includes('orfeotelesta');
  K.pnyx=P.includes('pnyx');K.teatro=P.includes('teatro');
  K.verdad=kn('verdad');K.ley=kn('ley');K.ciudad=kn('ciudad');K.dios=kn('dios');K.escuela=kn('escuela');
  K.so=qLv('so');K.lo=qLv('lo');K.ar=qLv('ar');K.eu=qLv('eu');K.kl=qLv('kl');return K;}
function acaScript(){const K=acaKnows(),fem=typeof pjFem==='function'&&pjFem(),me=(typeof fxNombre==='function'?fxNombre():'')||'forastero',S=[];
  const s=(w,t,f)=>S.push({w,t,f}),ask=(q,opts)=>S.push({ask:q,opts}),pause=t=>S.push({w:'N',t});
  pause('Bajo los olivos sagrados del bosque de Academo, junto a una exedra de piedra, una docena de jóvenes se sienta en círculo. Nadie paga: Platón no cobra, a diferencia de los sofistas. En medio, una zona de arena alisada para dibujar.');
  if(fem)pause('Algunos te miran con sorpresa: no hay mujeres en el círculo. Platón les hace un gesto para que callen y te señala un sitio. (Dentro de unos años estudiarán aquí dos mujeres, Axiotea de Fliunte y Lastenia de Mantinea; de Axiotea se decía que venía vestida de hombre.)');
  s('P','Bienvenido'+(fem?'a':'')+', '+me+'. Hoy no voy a enseñaros nada. Vamos a buscar juntos qué es saber algo.');
  s('E','Mi tío dice siempre lo mismo, y luego se pasa la mañana preguntando.');
  if(K.n>0)s('P','Me dicen que en estos días has hablado con '+K.n+(K.n===1?' maestro':' maestros')+' de la ciudad'+(K.pl?', que conoces '+K.pl+(K.pl===1?' lugar':' lugares'):'')+(K.my?' y '+K.my+' relieves con sus mitos':'')+'. Mucho saber, ¿no? ¿O mucha opinión?');
  else s('P','Acabas de llegar a Atenas, pero seguro que ya crees saber muchas cosas. Veamos si las sabes, o solo las opinas.');
  ask('Un hombre conoce el camino a Larisa sin haber ido nunca, porque se lo han explicado bien. ¿Sabe el camino?',[
   ['Sí, lo sabe',0,'Lo recorrerá bien, es cierto. Pero si alguien le dice otra cosa, ¿cómo lo defenderá? No sabe por qué es ese el camino.'],
   ['Tiene una opinión verdadera, pero no sabe',1,'Exacto. La opinión verdadera sirve tanto como el saber mientras dura; pero se escapa, como las estatuas de Dédalo, que según dicen huían si no las atabas.'],
   ['No sabe nada en absoluto',0,'No tanto: si llega a Larisa, algo sabía. Lo que tiene es una opinión verdadera, que no es poco.']]);
  if(K.daed)s('J','¡Dédalo! '+me+' dice que lo ha visto, encerrado en su laberinto de Creta.');
  s('P','Para que una opinión verdadera se convierta en saber hay que atarla dando la razón de por qué es así. Os lo enseñaré con un dibujo.');
  s('P','Mirad este cuadrado: cada lado mide dos pies. ¿Cuánto mide su área?','sq');s('T','Cuatro pies cuadrados.','sq');
  s('P','Ahora quiero un cuadrado del doble de área: de ocho pies.','sq');
  ask('¿Qué lado tiene el cuadrado de área ocho?',[
   ['El doble: cuatro pies',0,'Dibújalo y cuéntalo: con lado cuatro salen dieciséis, el doble del doble. Es lo que contestó el esclavo de Menón la primera vez.','sq4'],
   ['Tres pies',0,'Más cerca, pero tres por tres son nueve, no ocho. También lo probó el esclavo. Mira ahora la diagonal.','sq3'],
   ['La diagonal del primer cuadrado',1,'¡Eso es! El cuadrado construido sobre la diagonal tiene exactamente el doble de área. Cuéntalo tú mismo: son cuatro medios cuadrados.','diag']]);
  s('P','Mira el dibujo: cuatro mitades del cuadrado pequeño dentro del grande. Ocho.','diag');
  s('T','Y fíjate en lo extraño: esa diagonal no se puede medir con el lado. No hay ningún número entero, ni ninguna fracción, que diga cuántas veces cabe uno en otro. Son inconmensurables.','diag');
  if(K.teeteto)s('T','Ya te lo conté el otro día: Teodoro lo demostró para las raíces de tres, de cinco y hasta la de diecisiete. Yo estoy intentando demostrarlo para todas.');
  s('P','Ahora decidme: nadie le enseñó esto al esclavo de Menón. Yo solo le pregunté. ¿De dónde sacó la respuesta?');
  ask('¿De dónde sacó el esclavo la respuesta, si nadie se la dio?',[
   ['La adivinó por suerte',0,'¿Por suerte, después de equivocarse dos veces y corregirse él solo? La suerte no corrige.'],
   ['Ya la tenía dentro: la recordó',1,'Eso creo yo. Aprender es recordar lo que el alma ya vio antes de nacer. Si es así, el alma es inmortal.'],
   ['Se la enseñó Platón sin darse cuenta',0,'Es una buena objeción, y la tengo en cuenta. Pero yo solo pregunté; las respuestas eran suyas.']]);
  if(K.verdad)s('P','Tú sabes ya algo de nuestra lengua: dime, ¿qué significa ἀλήθεια? «Lo que no se olvida», «lo que no está oculto». Fíjate: la verdad, en griego, es un des-olvido.');
  if(K.dream)s('E','Dicen que '+me+' ha visto en sueños '+K.dream+(K.dream===1?' mito':' mitos')+' como si los hubiera vivido.');
  if(K.dream||K.eleu||K.orfeo)s('P','No me extraña. Los sueños, los misterios'+(K.eleu?' de Eleusis, en los que te iniciaste,':'')+(K.orfeo?' y los cantos de los órficos':'')+' dicen a su manera lo mismo: el alma viene de otro lugar y lo recuerda a ratos.');
  s('P','Vamos un paso más allá. Hipias me dijo una vez que lo bello es una muchacha bella. Pero también es bella una yegua, una lira, incluso una olla bien hecha.');
  ask('Una muchacha, una yegua y una olla son bellas. ¿Qué tienen en común?',[
   ['Nada: cada una es bella a su manera',0,'Entonces la palabra «bello» no significaría nada. Y sí significa algo: algo comparten.'],
   ['Que son útiles',0,'¿Una muchacha bella es bella porque sea útil? Lo útil y lo bello no son lo mismo, aunque a veces vayan juntos.'],
   ['Todas participan de lo Bello mismo',1,'Así lo veo yo. Hay una Belleza que no es ninguna cosa bella y que hace bellas a todas: no envejece, no cambia, no depende de quién la mire. A esas realidades las llamo Ideas, Formas.']]);
  if(K.cefis)s('J','Como la estatua de la Paz que hace Cefisodoto: '+me+' le hizo de modelo.');
  if(K.cefis||K.teatro)s('P','Las estatuas y los poemas imitan las cosas, y las cosas imitan las Ideas: el artista copia una copia. Por eso desconfío un poco de los poetas'+(K.teatro?' que aplaudís en el teatro':'')+'.');
  if(K.ovid)s('E','Los poetas cuentan que todo se transforma: ninfas en árboles, hombres en lobos. '+me+' anda buscando esas historias por todas partes.');
  if(K.ovid)s('P','Las cosas de este mundo cambian sin parar, como decía Heráclito. Por eso no se las puede saber del todo. Solo lo que no cambia se puede saber.');
  s('P','Ahora, la pregunta que más me importa: ¿por qué ser justo?');
  ask('Si tuvieras un anillo que te volviera invisible, como el pastor Giges, ¿seguirías siendo justo?',[
   ['No: si nadie me ve, no hay castigo',0,'Eso responden casi todos con sinceridad. Pero entonces la justicia sería solo miedo. Yo creo que el injusto se daña a sí mismo, aunque nadie lo vea.'],
   ['Sí: la justicia es buena para el alma',1,'Esa es la respuesta que intento demostrar. Un alma justa es un alma en orden, y un alma en orden es feliz.'],
   ['Depende de lo que me convenga',0,'Eso decía Trasímaco: que la justicia es lo que conviene al más fuerte. ¿Y si lo que te conviene es ser justo?']]);
  s('P','Pensad en el alma como en tres partes: la razón, que piensa; el ánimo, que se indigna y se atreve; y el deseo, que quiere comer, beber, tener. La justicia es que cada parte haga lo suyo y la razón gobierne.','alma');
  s('P','Con la ciudad pasa lo mismo: gobernantes que piensan, guardianes valientes, productores que trabajan. Esta ciudad nuestra, que vota en la Pnix lo que dice el orador más hábil, ¿la gobierna la razón?','alma');
  if(K.pnyx)s('J',me+' ha estado en la Asamblea: que lo cuente.');
  if(K.gor)s('P','Tú derrotaste en un debate a un discípulo de Gorgias. Él enseña a convencer; yo intento enseñar a buscar la verdad. La retórica sin filosofía es como la cocina sin medicina: agrada, pero no cura.');
  if(K.isocrates)s('E','Isócrates, el de la escuela de al lado, dice que la filosofía de mi tío no sirve para nada práctico.');
  if(K.isocrates)s('P','Isócrates enseña a hablar bien de cosas probables. Yo prefiero buscar despacio cosas ciertas. Ya veremos qué escuela dura más.');
  s('P','Os enseñaré la última imagen. ¿Qué necesitan los ojos, además de las cosas, para ver?','sun');
  ask('¿Qué hace falta para que el ojo vea las cosas?',[
   ['Solo tener buenos ojos',0,'De noche tienes los mismos ojos y no ves. Falta algo.','sun'],
   [_t(2904,'La luz del sol'),1,'Eso es. El sol da la luz con la que vemos y hace crecer las cosas. Pues lo que el sol es para la vista, el Bien es para el saber: lo que hace que las Ideas se puedan conocer.','sun'],
   ['Que las cosas sean bonitas',0,'Lo feo también se ve. Falta algo que no está ni en el ojo ni en la cosa.','sun']]);
  if(K.cav)s('P','Tú lo sabes mejor que nadie: has salido de la caverna y has mirado ese sol. Nadie que haya subido quiere volver a las sombras… y, sin embargo, hay que volver, para ayudar a los que siguen dentro.');
  else s('P','Imaginad unos prisioneros que solo han visto sombras en el fondo de una cueva. Si uno sale y ve el sol, ¿le creerán cuando vuelva? Algún día escribiré esa imagen.');
  s('P','No os he enseñado nada hoy. Solo he preguntado. Lo que habéis encontrado ya era vuestro.');
  s('E','Siempre termina así. Y lo peor es que tiene razón.');
  return {S,K};}
// ---- la escena: oyentes alrededor de Platón
function acaScene(on){for(const g of ACA.ppl)scene.remove(g);ACA.ppl.length=0;if(!on)return;const P=npcObjs.find(o=>o.data.id==='platon');if(!P)return;
  const looks=[{chiton:'#ece6d8',himation:'#4a5a6e',beard:true,hair:'#3b2a1e'},{chiton:'#efe9dc',himation:'#6b7a4e',beard:true,hair:'#2a2018'},{chiton:'#e8e0d0',hair:'#3a2a1a'},{chiton:'#e0d8c8',himation:'#7a5a4a',hair:'#5a3a2a'},{chiton:'#ece4d4',hair:'#2a1a10'},{chiton:'#e4dccc',himation:'#5a6a7a',hair:'#4a3a2a'}];
  looks.forEach((lk,i)=>{const a=Math.PI*0.25+i*Math.PI*0.3,r=4.2,x=P.x+Math.cos(a)*r,z=P.z+Math.sin(a)*r;const g=makePerson(Object.assign({noVary:true},lk));
    g.position.set(x,floorAt(x,z)-0.35,z);g.rotation.y=Math.atan2(P.x-x,P.z-z);scene.add(g);ACA.ppl.push(g);});}
// ---- el motor de la sesión en directo
function acaOpts(n,add){if(MODE!=='atenas'||n.id!=='platon')return;const a=acaz();
  add(a.done?_t(10366,'Asistir de nuevo a una sesión de la Academia'):_t(10367,'Asistir a una sesión de la Academia, en directo'),'quiz',acaStart);
  if(a.done)add(_t(10368,'Ver mi mapa del conocimiento'),'',()=>{$('dBody').innerHTML=acaMap();renderOpts();});}
function acaStart(){if(clock.h<7||clock.h>17){$('dBody').innerHTML='<p>«Las sesiones son por la mañana, cuando la cabeza está despejada. Vuelve mañana temprano».</p>';renderOpts();return;}
  const {S,K}=acaScript();ACA.steps=S;ACA.K=K;ACA.i=0;ACA.ok=0;ACA.on=true;ACA.paused=false;acaScene(true);
  const one=casaOpen('Π',_t(2364,'La Academia'),'sesión en directo con Platón');const B=$('dBody');B.innerHTML='<div class="acaLog" id="acaLog"></div>';ACA.box=$('acaLog');
  if(!$('acaCSS')){const st=document.createElement('style');st.id='acaCSS';st.textContent='.acaLog{max-height:52vh;overflow-y:auto;display:flex;flex-direction:column;gap:6px;padding-right:4px}.acaL{animation:acaIn .35s ease-out;line-height:1.45}.acaL b{font-weight:600}.acaL.n{font-style:italic;opacity:.85}.acaL.y{border-left:3px solid #ffe2a8;padding-left:8px}@keyframes acaIn{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}';document.head.appendChild(st);}
  acaNext();}
function acaLine(w,t,fig){const d=document.createElement('div');d.className='acaL'+(w==='N'?' n':'')+(w==='Y'?' y':'');
  d.innerHTML=(w==='N'?'':'<b style="color:'+ACA_COL[w]+'">'+(w==='Y'?_t(9161,'Tú'):ACA_WHO[w])+':</b> ')+'<span></span>'+(fig?acaFig(fig):'');d.querySelector('span').textContent=w==='N'||w==='Y'?t:'«'+t+'»';
  ACA.box.appendChild(d);try{if(w!=='N'&&w!=='Y')vocWalk(d);}catch(e){}ACA.box.scrollTop=ACA.box.scrollHeight;
  try{if(aOK()&&w!=='N')sfxTap();}catch(e){}}
function acaCtl(){const o=$('dOpts');o.innerHTML='';const mk=(t,f,c)=>{const b=document.createElement('button');b.textContent=t;if(c)b.className=c;b.onclick=f;o.appendChild(b);};
  mk('Seguir ▸',()=>{clearTimeout(ACA.timer);acaNext();},'quiz');mk(ACA.paused?'Reanudar la sesión':_t(10369,'Pausa'),()=>{ACA.paused=!ACA.paused;clearTimeout(ACA.timer);if(!ACA.paused)acaNext();else acaCtl();});
  mk('Salir de la sesión',acaEnd);}
function acaNext(){if(!ACA.on||$('dialog').hidden){acaEnd(true);return;}const st=ACA.steps[ACA.i++];if(!st)return acaFinish();
  if(st.ask){acaLine('P',st.ask);const o=$('dOpts');o.innerHTML='';
    st.opts.slice().sort(()=>R()-0.5).forEach(([t,ok,rep,fig])=>{const b=document.createElement('button');b.className='quiz';b.textContent=t;b.onclick=()=>{acaLine('Y',t);if(ok)ACA.ok++;
      setTimeout(()=>{acaLine('P',(ok?'':'')+rep,fig);acaCtl();ACA.timer=setTimeout(acaNext,2600+rep.length*30);},700);o.innerHTML='';};o.appendChild(b);});return;}
  acaLine(st.w,st.t,st.f);acaCtl();if(!ACA.paused)ACA.timer=setTimeout(acaNext,1800+st.t.length*32);}
function acaFinish(){clearTimeout(ACA.timer);const a=acaz(),first=!a.done,tot=ACA.steps.filter(s=>s.ask).length;a.n++;a.best=Math.max(a.best||0,ACA.ok);a.done=1;save();
  if(first){qAdd('so',3,'Una mañana en la Academia te ha enseñado a preguntar.');qAdd('lo',2);qAdd('kl',1,'Ya te cuentan entre los que van a la Academia.');}
  else if(!a.day||a.day!==state.day){qAdd('so',1);}a.day=state.day;save();
  const o=$('dOpts');o.innerHTML='';acaLine('N','La sesión termina. Los alumnos se levantan y siguen discutiendo por el camino de vuelta a la ciudad. Has acertado '+ACA.ok+' de las '+tot+' preguntas de Platón.');
  const b=document.createElement('button');b.className='quiz';b.textContent=_t(10368,'Ver mi mapa del conocimiento');b.onclick=()=>{$('dBody').innerHTML=acaMap();o.innerHTML='';const c=document.createElement('button');c.textContent=_t(2951,'Despedirse');c.onclick=()=>acaEnd();o.appendChild(c);};o.appendChild(b);
  const c=document.createElement('button');c.textContent=_t(2951,'Despedirse');c.onclick=()=>acaEnd();o.appendChild(c);}
function acaEnd(silent){clearTimeout(ACA.timer);ACA.on=false;acaScene(false);if(!silent)closeDialog();}
// ---- el mapa del conocimiento: las Ideas en el centro y, alrededor, lo que el jugador ha enlazado con ellas
function acaMap(){const K=acaKnows();const N=[
  [_t(8837,'Geometría'),'el cuadrado doble'+(K.teeteto?' · Teeteto y los inconmensurables':''),true],
  ['El alma recuerda','aprender es recordar'+(K.verdad?' · ἀλήθεια':'')+(K.dream?' · tus sueños':'')+(K.eleu?' · Eleusis':''),!!(K.verdad||K.dream||K.eleu||K.orfeo)],
  ['Lo Bello','las Ideas'+(K.cefis?' · la estatua de Cefisodoto':'')+(K.teatro?' · el teatro':''),!!(K.cefis||K.teatro)],
  ['Lo que cambia',_t(7317,'Heráclito')+(K.ovid?' · '+K.ovid+' metamorfosis':''),K.ovid>0],
  ['La justicia','el anillo de Giges · el alma en tres partes'+(K.pnyx?' · la Asamblea':''),true],
  ['Retórica o filosofía',(K.gor?'tu debate con Gorgias':'convencer o buscar la verdad')+(K.isocrates?' · Isócrates':''),!!(K.gor||K.isocrates)],
  ['El Bien','el sol'+(K.cav?' · tu salida de la caverna':''),!!K.cav],
  ['Opinión y saber','el camino a Larisa'+(K.daed?' · las estatuas de Dédalo':''),true]];
  const cx=240,cy=195,R0=135;let svg='<svg viewBox="0 0 480 390" style="width:100%;max-width:440px;display:block;margin:auto" role="img" aria-label="Mapa del conocimiento"><g font-family="Georgia" text-anchor="middle">';
  N.forEach((n,i)=>{const a=-Math.PI/2+i*2*Math.PI/N.length,x=cx+Math.cos(a)*R0,y=cy+Math.sin(a)*R0;svg+='<line x1="'+cx+'" y1="'+cy+'" x2="'+x+'" y2="'+y+'" stroke="'+(n[2]?'#d9874a':'#6a5a4a')+'" stroke-width="'+(n[2]?2.5:1)+'" stroke-dasharray="'+(n[2]?'':'4 4')+'"/>';});
  svg+='<circle cx="'+cx+'" cy="'+cy+'" r="42" fill="#3a2a1a" stroke="#f0c890" stroke-width="2"/><text x="'+cx+'" y="'+(cy-2)+'" fill="#f0c890" font-size="15">Las Ideas</text><text x="'+cx+'" y="'+(cy+16)+'" fill="#c9b9a2" font-size="10">ἰδέαι</text>';
  N.forEach((n,i)=>{const a=-Math.PI/2+i*2*Math.PI/N.length,x=cx+Math.cos(a)*R0,y=cy+Math.sin(a)*R0;const w=n[0].split(' '),ln=n[0].length>11&&w.length>1?[w.slice(0,Math.ceil(w.length/2)).join(' '),w.slice(Math.ceil(w.length/2)).join(' ')]:[n[0]],dx=Math.abs(Math.cos(a))>0.5?Math.sign(Math.cos(a))*16:0,anc=dx>0?'start':dx<0?'end':'middle',ty=dx?y+4-(ln.length-1)*7:y+(Math.sin(a)>0.3?24:-14-(ln.length-1)*14);svg+='<circle cx="'+x+'" cy="'+y+'" r="9" fill="'+(n[2]?'#f0c890':'#3a3028')+'" stroke="#d9874a"/><text x="'+(x+dx)+'" y="'+ty+'" text-anchor="'+anc+'" fill="'+(n[2]?'#f1e8d8':'#8a7a6a')+'" font-size="12">'+ln.map((t,j)=>'<tspan x="'+(x+dx)+'" dy="'+(j?14:0)+'">'+t+'</tspan>').join('')+'</text>';});
  svg+='</g></svg>';
  const lit=N.filter(n=>n[2]).length;
  return '<div class="novoc"><p><b>Tu mapa del conocimiento</b> · '+lit+' de '+N.length+' enlaces encendidos</p>'+svg+'<ul>'+N.map(n=>'<li'+(n[2]?'':' style="opacity:.55"')+'><b>'+n[0]+'</b>: '+n[1]+(n[2]?'':' <span class="sub">(aún sin enlazar: búscalo por el juego)</span>')+'</li>').join('')+'</ul><p class="sub">Nota: Platón escribirá el Menón hacia el 385 y la República hacia el 375; en el 386 son ideas que está madurando. La famosa inscripción «que no entre quien no sepa geometría» es una leyenda muy posterior.</p></div>';}

// si se cierra el diálogo a mitad de sesión (Esc), se recoge la escena
const closeDialogAca=closeDialog;
closeDialog=function(){if(ACA.on){ACA.on=false;clearTimeout(ACA.timer);acaScene(false);}closeDialogAca();};

// ============================================================ VIDA Y MUERTE: funerales, medicina, Panateneas / reparto de trigo, infancia y juegos
// Prefijo de objetos «vm:». En los dos modos, salvo las Panateneas (Atenas) y el reparto de trigo (Roma).
function vmz(){if(!state.vm||typeof state.vm!=='object')state.vm={d:{},once:{},nuts:10};if(!state.vm.d)state.vm.d={};if(!state.vm.once)state.vm.once={};if(state.vm.nuts==null)state.vm.nuts=10;return state.vm;}
function vmOnce(k){const v=vmz();if(v.once[k])return false;v.once[k]=1;save();return true;}
function vmToday(k){return vmz().d[k]===(state.day||1);}
function vmMark(k){vmz().d[k]=state.day||1;save();}
// pantalla genérica: texto y botones [texto, función, clase]
function vmS(gl,name,sub,html,btns){casaOpen(gl,name,sub);$('dialog').hidden=false;$('dBody').innerHTML=html;const o=$('dOpts');o.innerHTML='';let k=1;
  for(const[t,f,c]of btns){const b=document.createElement('button');if(c)b.className=c;b.innerHTML='<span class="n">'+(k++)+'</span><span>'+t+'</span>';b.onclick=f;o.appendChild(b);}}
const vmBye=[_t(2951,'Despedirse'),()=>closeDialog()];
function vmSetup(){vmz();const ro=MODE==='roma',add=(f,look,act,name,sub)=>{if(f)artPerson(f,look,act,name,sub,3);};
  if(!ro){add(artAnchor('ceramico',-12,10),{female:true,chiton:'#3a3430',himation:'#2a2624',hair:'#5a4a3a'},'vm:funA','Arquipe','viuda, en el Cerámico');
    add(artAnchor('asklepieion',6,6),{chiton:'#efe9dc',himation:'#e8e0d0',beard:true,hair:'#9a9080',staff:true},'vm:incA','Tímeo','sacerdote de Asclepio');
    add(findFree(AG.x+30,AG.z+40,1),{chiton:'#d8d0c0',himation:'#6a7a8a',beard:true,hair:'#5a4a3a'},'vm:medA','Eurífon','médico de la escuela de Cos');
    add(artAnchor('pompeion',8,-6)||artAnchor('dipilon',10,10),{chiton:'#f0e8d8',himation:'#8a3a2a',beard:true,hair:'#6a5a4a',staff:true},'vm:pan',_t(7271,'Licurgo'),'hieropoiós de las Panateneas');
    add(findFree(AG.x-40,AG.z-30,1),{female:true,chiton:'#c8b8a0',himation:'#7a6a8a',hair:'#3a2a1a'},'vm:nino','Nicarete','madre de un recién nacido');}
  else{add(artAnchor('ro_appia',8,-10),Object.assign({},TOGA,{hair:'#6a5a4a'}),'vm:funR','Quinto Vibio','del colegio funerario');
    add(artAnchor('ro_isla',6,4),{chiton:'#efe9dc',himation:'#e8e0d0',beard:true,hair:'#9a9080',staff:true},'vm:incR','Diocles','sacerdote de Esculapio');
    add(artAnchor('ro_subura',18,-14),{chiton:'#d8d0c0',himation:'#5a6a7a',hair:'#3a2a1a'},'vm:medR','Hermógenes','medicus griego');
    add(artAnchor('ro_pompeyo',60,-30)||artAnchor('ro_horrea',10,10),Object.assign({},TOGA,{hair:'#8a8070'}),'vm:frum','Cayo Atilio','encargado del reparto de trigo');
    add(artAnchor('ro_subura',-30,26),{female:true,chiton:'#d0c0a8',himation:'#8a4a5a',hair:'#3a2a1a'},'vm:nino','Pomponia Rufa','madre de un recién nacido');}
  add(ro?artAnchor('ro_circo',30,30):findFree(AG.x+60,AG.z+10,1),{chiton:'#d8c8a8',hair:'#3a2a1a',scale:0.62,short:true},'vm:juegos',ro?'Lucio y Tulia':'Lisis y Glicera',ro?'niños jugando a las nueces':'niños jugando a las tabas');}
function vmAct(o){const k=String(o.act).slice(3);const F={funA:vmFunA,funR:vmFunR,incA:()=>vmInc(false),incR:()=>vmInc(true),medA:()=>vmMed(false),medR:()=>vmMed(true),pan:vmPan,frum:vmFrum,nino:vmNino,juegos:vmJuegos}[k];if(F)F(0);}
// ================= 1. FUNERALES
const VM_FUN_A=[
 ['La prótesis','<p>En la casa de Arquipe, el abuelo yace en un lecho, con los pies hacia la puerta. Las mujeres de la familia lo han lavado, ungido con aceite y vestido de blanco; lleva una corona en la cabeza y, en la boca, un óbolo para el barquero Caronte. Junto a la puerta, una jarra de agua de otra casa, para que se purifiquen los que salen.</p><p>Las mujeres se golpean el pecho, se arañan las mejillas y cantan el lamento.</p>',[['Cortarte un mechón y unirte al lamento',2],['Acompañar en silencio',1]]],
 ['El cortejo','<p>Antes del amanecer —así lo manda una ley de Solón, para que el entierro no sea un espectáculo— sale el cortejo hacia el Cerámico: delante, las mujeres con las ofrendas; luego el muerto, en un carro; detrás, los hombres. Solón también limitó quién podía ir: solo las parientes y las mujeres mayores de sesenta años.</p>',[['Ir con los hombres, detrás',1]]],
 ['La tumba','<p>Junto a la Vía Sagrada, fuera de la muralla, el cuerpo se entierra (también se puede quemar). Se vierten libaciones de leche, miel, vino y aceite, y se dejan junto a la tumba unos frascos blancos pintados, los lécitos. Encima se alzará una estela: en las de ahora, el muerto y un familiar se dan la mano para despedirse.</p>',[['Verter una libación',2],['Mirar las estelas de alrededor',1]]],
 ['Después','<p>A los tres días y a los nueve se celebran comidas y ofrendas en la tumba, y la casa se purifica. Cada año, la familia volverá a llevar ofrendas, y en otoño toda la ciudad honra a sus muertos en las Genesias.</p><p>Arquipe te da las gracias. «Ahora ya está en paz. Lo que no se perdona en Atenas es dejar a un muerto sin enterrar: ni siquiera a un enemigo».</p>',[]]];
const VM_FUN_R=[
 ['La pompa','<p>Por la Vía Apia baja un cortejo: es el entierro de un senador. Abren la marcha los músicos de tibia y las plañideras, mujeres pagadas que cantan las virtudes del difunto. Detrás, algo que te pone los pelos de punta: <b>actores con las máscaras de cera de los antepasados</b>, vestidos con la toga de los cargos que tuvieron, como si los muertos de la familia acompañaran al nuevo.</p>',[['Seguir el cortejo',1]]],
 ['El elogio','<p>El cortejo ha pasado antes por el Foro. Allí, desde los Rostra, el hijo del muerto ha pronunciado la <i>laudatio</i>: las hazañas del padre y, una por una, las de cada antepasado cuya máscara estaba presente. Así aprendían los jóvenes romanos qué se esperaba de ellos.</p><p class="sub">Polibio, un griego que vivió en Roma, decía que no había espectáculo más inspirador para un joven.</p>',[['Escuchar con respeto',2],['Fijarte en las máscaras',1]]],
 ['La pira','<p>Las Doce Tablas prohíben enterrar o quemar a nadie dentro de la ciudad: por eso las tumbas bordean las calzadas. Encienden la pira con el rostro apartado. Al final se riegan las cenizas con vino, se recogen los huesos en una urna y se entierra un dedo cortado antes de quemar, para que el muerto tenga sepultura. Nueve días después, el banquete que cierra el luto.</p>',[['Echar un puñado de tierra',2]]],
 ['Los pobres','<p>Quinto Vibio, que ha estado a tu lado todo el tiempo, se encoge de hombros. «Los pobres no tenemos máscaras ni pira de leña olorosa. Por eso pago cada mes a mi colegio funerario: cuando me muera, me pondrán en un nicho del columbario, con mi nombre en una placa. Y en febrero, en las Parentalia, mi hija me traerá vino y violetas».</p><p class="sub">En mayo, en las Lemuria, el padre de familia se levanta a medianoche y arroja habas negras a su espalda para alejar a los espíritus de la casa.</p>',[]]];
function vmFun(ro,st,eu){const S=ro?VM_FUN_R:VM_FUN_A,s=S[st],gl='⚱',nm=ro?'Quinto Vibio':'Arquipe',sub=ro?'del colegio funerario':'viuda, en el Cerámico';eu=eu||0;
  if(!s){if(vmOnce(ro?'funR':'funA'))qAdd('eu',2,'Honrar a los muertos es la primera piedad.');else if(eu>=3&&!vmToday('fun')){vmMark('fun');qAdd('eu',1);}closeDialog();return;}
  const b=s[2].map(([t,v])=>[t,()=>vmFun(ro,st+1,eu+v),'quiz']);if(!b.length)b.push(['Despedirte',()=>vmFun(ro,st+1,eu),'quiz']);
  vmS(gl,nm,sub,'<p class="sub">'+s[0]+'</p>'+s[1],b);}
function vmFunA(){vmS('⚱','Arquipe','viuda, en el Cerámico','<p>Una mujer vestida de negro, con el pelo cortado al ras en señal de luto, prepara cestas de ofrendas. «Mi suegro ha muerto esta noche. Mañana, antes del alba, lo llevamos al Cerámico. ¿Nos acompañarás? Cuantos más le lloren, más honrado irá».</p>',[['Acompañar a la familia',()=>vmFun(false,0),'quiz'],vmBye]);}
function vmFunR(){vmS('⚱','Quinto Vibio','del colegio funerario','<p>Un hombre sencillo, con una toga gastada, mira pasar un cortejo enorme. «¿Has visto un funeral de los grandes? Ven, que te explico cómo se entierra en Roma: a los ricos… y a los demás».</p>',[['Ir con él',()=>vmFun(true,0),'quiz'],vmBye]);}
// ================= 2. MEDICINA: el médico y la noche en el santuario
const VM_CASE=[
 {who:'un barquero del Pireo',sym:'tiene fiebre cada dos días: un día tirita, al siguiente arde, luego descansa y vuelta a empezar',q:'¿Dónde vive?',a:'«Junto a las marismas del Falero, donde el agua está quieta»',ok:'Dieta ligera, reposo y salir de las marismas',bad:['Un amuleto contra la fiebre','Hacerle sangrar mucho y que siga trabajando'],why:'Los médicos hipocráticos observaban el clima, el agua y el lugar donde vivía el enfermo: sabían que junto a las aguas estancadas las fiebres eran más frecuentes. (Hoy sabemos que es el paludismo, que transmiten los mosquitos).'},
 {who:'un herrero',sym:'tose desde hace semanas, escupe flemas y está muy delgado',q:'¿En qué trabaja?',a:'«Todo el día junto a la fragua, entre humo, y luego salgo al frío de la calle»',ok:'Reposo, buena comida, leche y aire limpio',bad:['Que trabaje más para sudar la enfermedad','Una purga fuerte cada día'],why:'Para los hipocráticos la salud era el equilibrio de los humores (sangre, flema, bilis amarilla y bilis negra), y el tratamiento empezaba por la dieta y el modo de vida.'},
 {who:'una niña',sym:'se ha caído de un muro y tiene el brazo torcido y muy hinchado',q:'¿Qué ha pasado?',a:'«Estaba jugando y se cayó de espaldas»',ok:'Tirar del brazo para colocar el hueso y entablillarlo',bad:['Esperar a que se cure solo','Cortar para sacar la hinchazón'],why:'Los tratados hipocráticos sobre fracturas y articulaciones describen con mucho detalle cómo reducir y entablillar un hueso roto.'}];
function vmMed(ro){const nm=ro?'Hermógenes':'Eurífon',sub=ro?'medicus griego':'médico de la escuela de Cos',c=VM_CASE[(state.day||1)%VM_CASE.length];
  const intro=ro?'<p>Una tienda en la Subura convertida en consultorio: sobre una mesa, bisturís de bronce, sondas, pinzas y ventosas, como los que se han encontrado en una casa de Pompeya. El médico es griego, como casi todos en Roma. «Los romanos se fían poco de nosotros», sonríe. «Catón decía que bastaba con la col para curarlo todo, y Plinio dice que la medicina es el único oficio en el que matar sale gratis. Pero luego vienen todos».</p>':'<p>En su consulta, un médico formado en Cos, la isla de Hipócrates, examina a un paciente sin prisa: le mira la cara, le toca la piel, le pregunta qué come, cómo duerme, dónde vive. «Nada de dioses ni de demonios», dice. «Cada enfermedad tiene una causa natural. Hay que observar, anotar y prever cómo va a evolucionar».</p>';
  vmS('⚕',nm,sub,intro+'<p class="sub">Hoy atiende a '+c.who+'.</p>',[['Ayudar con el enfermo',()=>vmCase(ro,c,0),'quiz'],['¿Qué es eso del juramento?',()=>vmS('⚕',nm,sub,'<p>«Los médicos de mi escuela juramos por Apolo y Asclepio enseñar el oficio a los hijos de nuestro maestro, no dar veneno aunque nos lo pidan, guardar en secreto lo que veamos en las casas y ayudar al enfermo, o al menos no hacerle daño».</p><p class="sub">El juramento hipocrático, con cambios, todavía se recita hoy en muchas facultades de medicina.</p>',[[_t(2961,'Volver'),()=>vmMed(ro)],vmBye])],vmBye]);}
function vmCase(ro,c,st){const nm=ro?'Hermógenes':'Eurífon',sub=ro?'medicus griego':'médico de la escuela de Cos';
  if(st===0)return vmS('⚕',nm,sub,'<p>El enfermo '+c.sym+'.</p><p>«Antes de tratar, hay que preguntar», dice el médico. «Hazlo tú».</p>',[[c.q,()=>vmCase(ro,c,1),'quiz']]);
  const opts=[c.ok,...c.bad].sort(()=>R()-0.5);
  vmS('⚕',nm,sub,'<p>'+c.a+'.</p><p>«¿Y qué le recetarías?»</p>',opts.map(t=>[t,()=>{const ok=t===c.ok;if(ok&&!vmToday('med')){vmMark('med');qAdd('so',1,'Observar antes de curar: así piensa un médico.');}
    vmS('⚕',nm,sub,'<p>'+(ok?'«Eso haría yo». ':'«No», dice el médico. «Yo haría esto: '+c.ok.toLowerCase()+'». ')+'</p><p class="sub">'+c.why+'</p>',[[_t(2961,'Volver'),()=>vmMed(ro)],vmBye]);},'quiz']));}
const VM_DREAM=['Sueñas que un hombre barbudo, con un bastón en el que se enrosca una serpiente, se inclina sobre ti y te toca donde te duele. Al despertar, el dolor es menor.','Sueñas que una serpiente enorme te lame la frente, sin miedo. Despiertas descansado como no lo estabas desde hace semanas.','Sueñas con un niño que te da un remedio: miel, una hierba y agua de una fuente. El sacerdote lo interpreta y te lo prepara por la mañana.'];
function vmInc(ro){const nm=ro?'Diocles':'Tímeo',sub=ro?'sacerdote de Esculapio':'sacerdote de Asclepio',god=ro?_t(5759,'Esculapio'):'Asclepio';
  const intro=ro?'<p>En la isla del Tíber, con forma de barco, está el templo de Esculapio, traído de Epidauro hace casi cuatro siglos para frenar una peste. Bajo los pórticos duermen enfermos de toda Roma. Entre ellos, varios esclavos: sus amos los han abandonado aquí por no pagar su curación. «El emperador Claudio decretó que, si se curan, quedan libres», te dice el sacerdote. «Algunos se curan».</p>':'<p>En la ladera sur de la Acrópolis, el santuario de Asclepio tiene apenas treinta años: lo fundó un tal Telémaco, y dicen que el poeta Sófocles hospedó en su casa al dios —es decir, a su serpiente sagrada— mientras se construía. Bajo el pórtico duermen los enfermos, esperando un sueño del dios.</p>';
  vmS('⚕',nm,sub,intro,[['Pasar la noche en el santuario',()=>{if(clock.h<16&&clock.h>=6){vmS('⚕',nm,sub,'<p>«La incubación es de noche. Vuelve al atardecer».</p>',[vmBye]);return;}
    vmS('⚕',nm,sub,'<p>Te purificas en la fuente, te cortas el pelo y ofreces al dios unas tortas de miel. '+(ro?'':'Hay quien ofrece un gallo: Sócrates, antes de morir, pidió que pagaran por él un gallo a Asclepio. ')+'Luego te tumbas sobre una piel en la sala de los durmientes, entre otros enfermos. Las serpientes sagradas, inofensivas, se deslizan entre los camastros. Se apagan las lámparas.</p>',[['Dormir',()=>{clock.h=6.5;const d=VM_DREAM[Math.floor(R()*VM_DREAM.length)],f=vmOnce(ro?'incR':'incA');if(f)qAdd('eu',2,'Has dormido bajo la mirada de '+god+'.');
      vmS('⚕',nm,sub,'<p>'+d+'</p><p>Por la mañana, como todos, dejas una ofrenda: una figurita de barro con la forma de la parte del cuerpo que te curó. Las paredes del santuario están llenas de piernas, ojos, manos y orejas de barro, y de tablillas que cuentan curaciones milagrosas.</p><p class="sub">Esas tablillas se conservan: en Epidauro hay inscripciones que cuentan curas asombrosas, a veces increíbles. Los médicos hipocráticos y los santuarios convivían: muchos enfermos probaban las dos cosas.</p>',[vmBye]);},'quiz']]);},'quiz'],vmBye]);}
// ================= 3a. LAS GRANDES PANATENEAS (Atenas, verano del 386: tercer año de la 98.ª Olimpiada)
function vmPanDaysTo(){const c=calNow();if(c.mo===6)return 0;const d=state.day||1;for(let k=1;k<400;k++)if(calNow(d+k).mo===6)return k;return 0;}
function vmPan(){const nm=_t(7271,'Licurgo'),sub='hieropoiós de las Panateneas',n=vmPanDaysTo();
  const intro='<p>«Este verano tocan las <b>Grandes Panateneas</b>, las que se celebran cada cuatro años, el tercero de cada Olimpiada: la fiesta del cumpleaños de Atenea, en el mes de Hecatombeón». El encargado de los sacrificios repasa una lista de bueyes. «Cien bueyes, ni uno menos. Y el peplo nuevo para la diosa, que tejen desde hace nueve meses unas muchachas elegidas».</p>';
  if(n>0)return vmS('🏺',nm,sub,intro+'<p>Faltan '+n+' días para Hecatombeón.</p>',[['Esperar en Atenas hasta las fiestas ('+n+' días)',()=>{state.day=(state.day||1)+n;clock.h=5.5;save();updateStats();toast('<span class="label">Hecatombeón</span><br>Han pasado '+n+' días. Hoy empiezan las Grandes Panateneas.');vmPan();},'quiz'],['¿Qué se hace en la fiesta?',()=>vmS('🏺',nm,sub,'<p>«Concursos de música y de recitado de Homero; carreras, lucha y pancracio; carreras de caballos y de carros; la danza pírrica con armas; un concurso de belleza masculina por tribus; y la carrera de antorchas. El premio son ánforas llenas de aceite de los olivos sagrados de Atenea: con la diosa pintada en un lado y la prueba en el otro».</p>',[[_t(2961,'Volver'),vmPan],vmBye])],vmBye]);
  vmS('🏺',nm,sub,intro+'<p><b>¡Hoy es el gran día!</b> Al amanecer, la procesión se forma en el Pompeion, junto a la puerta del Dípilon.</p>',[['Unirte a la procesión',()=>vmPanRole(),'quiz'],['Correr la carrera de antorchas',()=>vmTorch(0,0),'quiz'],vmBye]);}
function vmPanRole(){const fem=typeof pjFem==='function'&&pjFem(),ciu=!!(state.fx&&state.fx.ciu),nm=_t(7271,'Licurgo'),sub='hieropoiós de las Panateneas';
  const role=fem?(ciu?'canéfora: llevas sobre la cabeza la cesta con el cuchillo y la cebada del sacrificio, un honor para las muchachas de buena familia':'portadora de sombrilla: las hijas de los metecos llevan sombrillas y taburetes detrás de las canéforas'):(ciu?'portador de ramos: con los ciudadanos mayores, llevas una rama de olivo':'portador de bandejas: los metecos llevan bandejas con pasteles y panales para el sacrificio, vestidos de púrpura');
  vmS('🏺',nm,sub,'<p>Cada uno tiene su sitio en la procesión, según quién es en la ciudad. A ti te toca ir como <b>'+role+'</b>.</p><p>La procesión cruza el Ágora por la Vía de las Panateneas, sube la cuesta de la Acrópolis entre la multitud y entra por los Propileos. Delante, el peplo azafrán bordado con la lucha de los dioses contra los gigantes, que se entregará a la vieja imagen de madera de Atenea Polias. Detrás, los cien bueyes del sacrificio, la caballería, los vencedores de los concursos.</p>',[['Llegar al gran altar',()=>{if(vmOnce('pan'))qAdd('eu',3,'Has caminado con toda Atenas hasta su diosa.');
    vmS('🏺',nm,sub,'<p>En el gran altar de Atenea se sacrifican los cien bueyes: la hecatombe. El humo sube hacia el Partenón. Por la tarde, la carne se reparte entre los ciudadanos, por demos, en el Cerámico: es de los pocos días del año en que muchos atenienses comen carne.</p>',[['Ir a la carrera de antorchas',()=>vmTorch(0,0),'quiz'],vmBye]);},'quiz']]);}
function vmTorch(st,flame){const nm='La carrera de antorchas',sub='lampadedromía';
  const legs=['Sales del altar de Eros, a la entrada de la Academia, con la antorcha encendida. Si se apaga, quedas eliminado.','Atraviesas el Cerámico entre gritos. La gente golpea a los corredores lentos con la mano abierta, para animarlos.','Entras por el Dípilon y cruzas el Ágora a la luz de las antorchas.','La última cuesta, hacia la Acrópolis. Ves el altar de Atenea.'];
  if(st>=legs.length){const ar=qLv('ar'),win=flame<=1&&R()<0.35+ar*0.07;
    if(win&&vmOnce('torch')){state.obols+=12;save();updateStats();qAdd('kl',3,'Has ganado en las Panateneas.');qAdd('ar',1);}
    return vmS('🔥',nm,sub,win?'<p>¡Llegas el primero con la llama viva y enciendes el fuego del altar! Te coronan y te dan un <b>ánfora panatenaica</b> llena de aceite sagrado: Atenea con lanza y escudo en un lado, unos corredores en el otro. Vendes parte del aceite: 12 óbolos.</p>':'<p>'+(flame>1?'Tu antorcha se ha apagado por el camino.':'Llegas con la llama, pero otro corredor ha encendido el altar antes que tú.')+' La próxima vez, mejor.</p><p class="sub">'+(ar<5?'Con más Areté tendrías más posibilidades.':'')+'</p>',[vmBye]);}
  vmS('🔥',nm,sub,'<p>'+legs[st]+'</p>',[['Correr a toda velocidad',()=>{const out=R()<0.45;toast(out?'¡El viento casi te apaga la antorcha!':'Ganas terreno.');vmTorch(st+1,flame+(out?1:0));},'quiz'],['Proteger la llama con la mano y correr algo menos',()=>vmTorch(st+1,flame),'quiz']]);}
// ================= 3b. EL REPARTO DE TRIGO (Roma)
function vmFrum(){const nm='Cayo Atilio',sub='encargado del reparto de trigo',fem=typeof pjFem==='function'&&pjFem(),ciu=typeof fxEsCiu==='function'&&fxEsCiu(),mo=calNow().mo,got=vmz().frum===mo+'-'+calNow().year;
  const intro='<p>Bajo un pórtico del Campo de Marte se forman colas desde el alba. Cada hombre lleva una <b>tablilla</b> (tessera) con un número: el día del mes y la ventanilla que le tocan. Al llegar, un esclavo público mide cinco <i>modios</i> de trigo, unos treinta y tantos kilos: la ración gratuita del mes.</p><p class="sub">Unos doscientos mil ciudadanos varones que viven en Roma tienen derecho a este trigo. Las mujeres y los no ciudadanos, no: Carcopino lo deduce de los relieves y de las listas, en los que solo aparecen hombres.</p>';
  const b=[];
  if(!fem&&ciu&&!got)b.push(['Presentar tu tablilla y recoger tus cinco modios',()=>{vmz().frum=mo+'-'+calNow().year;save();vmS('🌾',nm,sub,'<p>Te llenan el saco. Ahora tienes trigo para un mes… pero hay que molerlo y cocerlo. ¿Qué haces con él?</p>',[['Llevarlo a una panadería para que te lo cuezan',()=>{if(vmOnce('frum'))qAdd('kl',1);vmS('🌾',nm,sub,'<p>En la panadería, un asno da vueltas a la muela de piedra, y el panadero te devuelve hogazas redondas, partidas en ocho gajos, como las que se han encontrado carbonizadas en Pompeya. Te cobra por el trabajo, pero comerás todo el mes.</p>',[vmBye]);},'quiz'],['Venderlo a un comerciante (5 sestercios)',()=>{state.obols+=5;save();updateStats();vmS('🌾',nm,sub,'<p>El comerciante te lo compra sin preguntar: mucha gente vende su ración. Así, el trigo del Estado acaba otra vez en el mercado.</p>',[vmBye]);},'quiz']]);},'quiz']);
  else if(got)b.push(['Ya recogiste tu trigo este mes',()=>vmS('🌾',nm,sub,'<p>«Vuelve el mes que viene, con tu tablilla».</p>',[vmBye])]);
  else b.push(['¿Y yo no tengo derecho?',()=>vmS('🌾',nm,sub,'<p>«Lo siento: '+(fem?'el trigo se da a los ciudadanos varones; tu marido o tu padre lo recogen por la familia':'solo los ciudadanos romanos que viven en la ciudad están en las listas')+'. Pero si quieres ganar unos sestercios, en los almacenes del Emporio siempre necesitan gente para descargar».</p>',[['Ir a descargar al Emporio',()=>vmAnnona(),'quiz'],vmBye])]);
  b.push(['¿De dónde sale tanto trigo?',()=>vmAnnona(true),'']);b.push(vmBye);vmS('🌾',nm,sub,intro,b);}
function vmAnnona(info){const nm=_t(4799,'El Emporio'),sub='almacenes junto al Tíber';
  vmS('🌾',nm,sub,'<p>Roma come trigo de Egipto, de África y de Sicilia. Las grandes naves de la flota de Alejandría llegan a Puteoli o al puerto que Claudio construyó junto a Ostia; allí el grano pasa a barcazas que remontan el Tíber, tiradas por bueyes desde la orilla, hasta los almacenes (horrea) del Emporio, al pie del Aventino. Todo lo organiza el prefecto de la anona: si un año faltaba el trigo, Roma se amotinaba.</p><p class="sub">La anona, el abastecimiento de Roma, tenía su propia diosa: Annona, con una espiga y la proa de un barco.</p>'+(info?'':'<p>Pasas la mañana cargando sacos por una pasarela. Al final, el capataz te paga.</p>'),[...(info?[]:[['Cobrar (3 sestercios)',()=>{if(!vmToday('annona')){vmMark('annona');state.obols+=3;save();updateStats();qAdd('ar',1);}closeDialog();},'quiz']]),vmBye]);}
// ================= 4. INFANCIA: nacer y recibir un nombre
function vmNino(){const ro=MODE==='roma',nm=ro?'Pomponia Rufa':'Nicarete',sub='madre de un recién nacido';
  const txt=ro?'<p>«Hoy es el noveno día desde que nació mi hijo: el <i>dies lustricus</i>». (Para las niñas es el octavo.) «Hasta hoy no era del todo de la familia: muchos niños mueren en los primeros días. Hoy lo purificamos, le ponemos su nombre y le colgamos al cuello la <b>bula</b>, el amuleto que lo protegerá hasta que se ponga la toga de hombre».</p><p>Los parientes le traen sonajeros y pequeños amuletos. La bula de los ricos es de oro; la de los pobres, de cuero.</p><p class="sub">Las niñas llevaban también amuletos y, la víspera de su boda, ofrecían sus muñecas a los Lares de la casa. Al nacer, el padre decidía si «levantaba» al niño del suelo y lo aceptaba; si no, podía exponerlo, abandonarlo, una práctica dura que la ley permitía.</p>':'<p>«Hace cinco días que nació mi hija. Hoy es la <i>Anfidromía</i>»: alguien de la casa, desnudo, corre alrededor del hogar con la niña en brazos, para presentarla a Hestia y a los dioses de la familia. En la puerta cuelga un vellón de lana; si fuera un niño, una rama de olivo.</p><p>«Al décimo día haremos un sacrificio y una fiesta, y le pondremos el nombre: el de su abuela, como es costumbre».</p><p class="sub">Muchos recién nacidos no sobrevivían, y el padre podía también no aceptar al niño y exponerlo: una práctica que conocemos por los mitos (Edipo, Ion) y por textos de la época, y que hoy nos estremece.</p>';
  vmS('👶',nm,sub,txt,[['Llevar un regalo al bebé',()=>{if(vmOnce('nino'))qAdd('eu',1,'Has bendecido a una criatura recién llegada.');vmS('👶',nm,sub,'<p>'+(ro?'Le das una pequeña campanilla de bronce, para ahuyentar los malos espíritus. La madre sonríe.':'Le das una figurita de barro con forma de muñeca. «Cuando crezca, la ofrecerá a Ártemis antes de casarse», dice la madre.')+'</p>',[vmBye]);},'quiz'],vmBye]);}
// ================= 4b. JUEGOS: las tabas y las nueces
const VM_TABA=[[1,_t(10370,'el perro')],[3,'el lado plano'],[4,'el lado cóncavo'],[6,'el lado del rey']];
function vmJuegos(){const ro=MODE==='roma',nm=ro?'Lucio y Tulia':'Lisis y Glicera',sub=ro?'niños jugando a las nueces':'niños jugando a las tabas',v=vmz();
  const b=[['Jugar a las tabas (apuestas 2 nueces)',()=>vmTabas(),'quiz']];if(ro)b.push(['Jugar al castillo de nueces',()=>vmCastillo(),'quiz']);b.push(['¿A qué más jugáis?',()=>vmS('🎲',nm,sub,'<p>«Al aro, que se lleva rodando con un palo con gancho; a la peonza, a la gallinita ciega, al columpio, a pares o nones, a llevarse a caballo unos a otros… '+(ro?'Y las niñas, a las muñecas articuladas de hueso o de marfil.':'Y a la ostrakinda: se tira una concha negra por un lado y blanca por el otro, y según cómo caiga, un equipo persigue al otro.')+'»</p><p class="sub">Las tabas son los huesecillos del tobillo de una oveja o una cabra. Se jugaba con ellas en Grecia y en Roma, niños y mayores: hay estatuas y pinturas de muchachas jugando a las tabas.</p>',[[_t(2961,'Volver'),vmJuegos],vmBye])],vmBye);
  vmS('🎲',nm,sub,'<p>Unos niños juegan en el suelo, muy concentrados. '+(ro?'Tienen montoncitos de nueces: en Roma, «dejar las nueces» quiere decir dejar de ser niño.':'Lanzan unas tabas y gritan a cada tirada.')+' Te ofrecen unirte. Tienes <b>'+v.nuts+' nueces</b>.</p>',b);}
function vmTabas(){const v=vmz(),nm='Las tabas',sub='cuatro huesecillos';if(v.nuts<2){v.nuts=10;save();return vmS('🎲',nm,sub,'<p>Te has quedado sin nueces. Los niños, generosos, te dan diez más.</p>',[[_t(2961,'Volver'),vmJuegos]]);}
  const roll=()=>[0,1,2,3].map(()=>VM_TABA[Math.floor(R()*4)]),sc=r=>{const u=new Set(r.map(x=>x[0]));if(u.size===4)return[100,'¡Venus! Las cuatro caras distintas: la mejor tirada'];if(u.size===1&&r[0][0]===1)return[-1,'¡El perro! Cuatro unos: la peor tirada'];return[r.reduce((a,x)=>a+x[0],0),''];};
  const me=roll(),him=roll(),a=sc(me),b=sc(him),win=a[0]>b[0],tie=a[0]===b[0];v.nuts+=tie?0:win?2:-2;save();
  if(win&&!vmToday('tabas')){vmMark('tabas');qAdd('kl',1);}
  vmS('🎲',nm,sub,'<p>Tu tirada: '+me.map(x=>x[0]).join(' · ')+(a[1]?' — <b>'+a[1]+'</b>':' (suma '+a[0]+')')+'.</p><p>La suya: '+him.map(x=>x[0]).join(' · ')+(b[1]?' — <b>'+b[1]+'</b>':' (suma '+b[0]+')')+'.</p><p>'+(tie?_t(10371,'Empate.'):win?'¡Ganas dos nueces!':'Pierdes dos nueces.')+' Tienes '+v.nuts+'.</p><p class="sub">Cada taba tiene cuatro caras que valen 1, 3, 4 y 6. La tirada de Venus, con las cuatro caras distintas, era la mejor; Augusto, que era muy aficionado, la menciona en sus cartas.</p>',[['Otra tirada',vmTabas,'quiz'],[_t(2961,'Volver'),vmJuegos]]);}
function vmCastillo(){const v=vmz(),nm='El castillo de nueces',sub='tres nueces y una encima';
  vmS('🌰',nm,sub,'<p>Los niños colocan tres nueces juntas y una cuarta encima: un «castillo». Hay que derribarlo tirando otra nuez desde una raya. Si lo derribas, te quedas las cuatro.</p>',[['Tirar suave',()=>vmCast(0.35)],['Tirar con fuerza media',()=>vmCast(0.5+qLv('ar')*0.02)],['Tirar fuerte',()=>vmCast(0.3)],[_t(2961,'Volver'),vmJuegos]]);
  function vmCast(p){const ok=R()<p;v.nuts+=ok?4:-1;if(v.nuts<0)v.nuts=0;save();vmS('🌰',nm,sub,'<p>'+(ok?'¡Derribas el castillo! Te quedas las cuatro nueces.':'Tu nuez pasa de largo y se la queda el dueño del castillo.')+' Tienes '+v.nuts+' nueces.</p>',[[_t(10372,'Otra vez'),vmCastillo,'quiz'],[_t(2961,'Volver'),vmJuegos]]);}}

// ============================================================ CANTERAS Y PIGMENTOS
// Atenas: la cantera del Pentélico (el mármol del Partenón). Roma: las canteras de travertino de Tíbur (la piedra del anfiteatro de Tito)
// y el muelle de los mármoles junto al Emporio. En las dos ciudades, un taller de pigmentos para pintar estatuas y edificios.
// La cantera es una zona aparte, como el estadio o el Telesterion: a 4.200 m de altura, en X 9500, Z 9000 (prefijo de objetos «qc:»).
const QC={X:9500,Z:9000,Y:4200,built:false,back:null};
function qcz(){if(!state.qc||typeof state.qc!=='object')state.qc={d:{},once:{},blocks:0};if(!state.qc.d)state.qc.d={};if(!state.qc.once)state.qc.once={};return state.qc;}
function qcOnce(k){const q=qcz();if(q.once[k])return false;q.once[k]=1;save();return true;}
function qcIn(){return QC.built&&Math.abs(player.x-QC.X)<160&&Math.abs(player.z-QC.Z)<160&&player.feet>QC.Y-60&&player.feet<QC.Y+200;}
function qcBuild(){if(QC.built)return;QC.built=true;const ro=MODE==='roma',X=QC.X,Z=QC.Z,Y=QC.Y,g=grp(X,Y,Z,0);
  const stone=lam(ro?'#d8ccae':'#eeeae2'),cut=lam(ro?'#c8b890':'#dcd6ca'),dirt=lam(ro?'#a89878':'#b8b0a0'),wood=lam('#7a5a3a'),rope=lam('#b89a6a'),dark=lam('#5a5048');
  // suelo de la cantera, con lascas de piedra, y paredes que no dejan caer
  box(150,1,150,dirt,0,-0.5,0,g);addPlat(X,Z,150,150,0,Y);
  for(const[a,b,c,d]of[[-74,-74,74,-74],[74,-74,74,74],[74,74,-74,74],[-74,74,-74,-74]])addSeg(X+a,Z+b,X+c,Z+d,0.6);
  for(let i=0;i<220;i++){const x=(R()-0.5)*140,z=(R()-0.5)*120,s=0.2+R()*0.5;box(s,s*0.5,s*0.8,R()<0.5?stone:cut,x,0.15,z,g);}
  // el frente de la cantera, en escalones (bancos), al norte
  for(let k=0;k<5;k++){const d=8,h=4.5;box(150,h*(k+1),d,k%2?stone:cut,0,h*(k+1)/2,-40-k*d,g);}
  addSeg(X-75,Z-36,X+75,Z-36,0.6);
  // canales abiertos alrededor de un bloque en el primer banco, y otros bloques a medio sacar
  for(const[x,w]of[[-30,6],[-12,5],[8,7],[30,5]]){box(w,3.4,3,stone,x,2.2,-34,g);box(w+0.6,0.3,3.6,dark,x,0.5,-34,g);}
  // las montañas alrededor
  const mt=lam(ro?'#7f8a68':'#8e9280'),mt2=lam(ro?'#9a9a80':'#b4b2a6');for(let i=0;i<11;i++){const a=-Math.PI*1.05+i*Math.PI*0.21,r=210+R()*80,geo=new THREE.IcosahedronGeometry(1,2),ps=geo.attributes.position;
    for(let k=0;k<ps.count;k++){const vx=ps.getX(k),vy=ps.getY(k),vz=ps.getZ(k),n=1+0.18*Math.sin(vx*5.1+i)*Math.cos(vz*4.3)+0.1*Math.sin(vy*7+i*2);ps.setXYZ(k,vx*n,Math.max(vy,-0.2)*n,vz*n);}geo.computeVertexNormals();
    const c=new THREE.Mesh(geo,i%3?mt:mt2);c.scale.set(80+R()*60,35+R()*45,70+R()*50);c.position.set(Math.cos(a)*r,0,Math.sin(a)*r-40);g.add(c);}
  // obreros con picos y mazas
  const looks=[{chiton:'#a89878',hair:'#2a1a10'},{chiton:'#8a7a60',hair:'#3a2a1a',beard:true},{chiton:'#b0a080',hair:'#1a1008'},{chiton:'#9a8a70',hair:'#4a3a2a',beard:true}];
  [[-28,-30],[-10,-30],[10,-30],[28,-30],[-36,-6],[18,4]].forEach(([x,z],i)=>{const p=makePerson(Object.assign({noVary:true},looks[i%4]));p.position.set(x,0,z);p.rotation.y=z<-20?Math.PI:R()*6;g.add(p);});
  // la rampa (o la grúa en Roma) y el transporte
  if(!ro){box(8,0.6,60,cut,-50,0.3,10,g);for(let z=-15;z<40;z+=5){box(0.25,1.4,0.25,wood,-55,0.7,z,g);box(0.25,1.4,0.25,wood,-45,0.7,z,g);}
    box(4,0.4,2.2,wood,-50,0.8,5,g);box(3.4,2,2,stone,-50,2,5,g);box(0.08,0.08,25,rope,-50,1.2,-8,g);
    box(5,1,2.6,wood,-50,1.2,40,g);for(const s of[-1,1]){const w=new THREE.Mesh(new THREE.CylinderGeometry(1,1,0.3,12),wood);w.rotation.z=Math.PI/2;w.position.set(-50+s*2.6,1,40);g.add(w);}box(3,2,2.2,stone,-50,2.7,40,g);
    for(let i=0;i<3;i++)for(const s of[-1,1]){const ox=new THREE.Group(),bd=lam('#7a6a5a');box(1,1.1,2.2,bd,0,1.3,0,ox);box(0.6,0.6,0.8,bd,0,1.6,1.4,ox);for(const[a,b]of[[-0.35,-0.8],[0.35,-0.8],[-0.35,0.8],[0.35,0.8]])box(0.2,0.8,0.2,bd,a,0.4,b,ox);ox.position.set(-50+s*1.2,0,46+i*3.5);g.add(ox);}}
  else{// grúa de rueda: dos patas, un mástil inclinado y la rueda donde caminan los hombres
    const cx=-40,cz=-12;box(0.6,16,0.6,wood,cx-2,8,cz,g);box(0.6,16,0.6,wood,cx+2,8,cz,g);box(5,0.6,0.6,wood,cx,16,cz,g);
    const wh=new THREE.Mesh(new THREE.TorusGeometry(3.4,0.25,6,24),wood);wh.position.set(cx+5,3.6,cz+3);wh.rotation.y=Math.PI/2;g.add(wh);box(0.12,0.12,12,rope,cx,9,cz-5,g);box(3,2,2,stone,cx,3,cz-10,g);
    // sierra de marco con agua y arena
    box(5,0.3,0.15,wood,22,2.4,8,g);box(0.15,2,0.15,wood,19.6,1.4,8,g);box(0.15,2,0.15,wood,24.4,1.4,8,g);box(6,2,3,stone,22,1,8,g);
    // el río Anio y una barcaza cargada
    const wt=new THREE.Mesh(new THREE.PlaneGeometry(150,22),new THREE.MeshLambertMaterial({color:0x4a6a6a}));wt.rotation.x=-Math.PI/2;wt.position.set(0,0.05,60);g.add(wt);
    box(14,1.4,4,wood,-20,0.6,60,g);box(4,2,3,stone,-24,2.3,60,g);box(4,2,3,stone,-17,2.3,60,g);addSeg(X-75,Z+49,X+75,Z+49,0.6);}
  // puntos de interés
  const P=(x,z,act,name,sub)=>egxObj(X+x,Z+z,Y,act,name,sub,3.2);
  P(0,-30,'qc:frente','El frente de la cantera',ro?'travertino de Tíbur':'mármol del Pentélico');
  P(4,-26,'qc:cunas','Un bloque a medio sacar','las cuñas');
  if(!ro){P(-50,0,'qc:rampa','La rampa de bajada','el trineo y las cuerdas');P(-50,36,'qc:carro','El carro de bueyes','hacia Atenas');}
  else{P(-40,-6,'qc:grua','La grúa de rueda','magna rota');P(22,4,'qc:sierra','La sierra','agua y arena');P(-20,54,'qc:barca','La barcaza','por el Anio hacia Roma');}
  P(0,30,'qc:volver','Volver a la ciudad',ro?'por la Vía Tiburtina':'en el carro de vuelta');}
function qcGo(){qcBuild();QC.back={x:player.x,z:player.z};closeDialog();fzPut(QC.X,QC.Z+20,0);toast('<span class="label">'+(MODE==='roma'?'Las canteras de Tíbur':'La cantera del Pentélico')+'</span><br>'+(MODE==='roma'?'Casi treinta kilómetros al este de Roma, donde el Anio baja de los montes.':'A unos quince kilómetros de Atenas, en la ladera del monte Pentélico.'));}
function qcBack(){closeDialog();const b=QC.back;if(b)fzPut(b.x,b.z);}
const regionName0=regionName;regionName=function(){if(qcIn())return MODE==='roma'?'Las canteras de Tíbur':'La cantera del Pentélico';return regionName0();};
// ---- personajes de la ciudad: el transportista (Atenas) y el marmolista del muelle (Roma); el taller de pigmentos
function qcSetup(){qcz();const ro=MODE==='roma',add=(f,look,act,name,sub)=>{if(f)artPerson(f,look,act,name,sub,3);};
  if(!ro){add(artAnchor('ceramico',10,-16)||findFree(AG.x-60,AG.z-60,1),{chiton:'#9a8a70',hair:'#4a3a2a',beard:true},'qc:viaje','Mnesíteo','transportista de mármol');
    add(findFree(AG.x+50,AG.z-50,1),{chiton:'#c8b8a0',himation:'#8a3a3a',beard:true,hair:'#bab0a0'},'qc:pig',_t(9740,'Calias'),'pintor y fabricante de colores');}
  else{add(artAnchor('ro_emporio',14,12)||artAnchor('ro_horrea',10,10),{chiton:'#b8a888',hair:'#3a2a1a'},'qc:viaje',_t(3580,'Félix'),'marmolista del muelle');
    add(artAnchor('ro_subura',40,-40),{chiton:'#c8b8a0',himation:'#8a3a3a',hair:'#3a2a1a'},'qc:pig','Vestorino','vendedor de colores');}}
function qcAct(o){const k=String(o.act).slice(3);const F={viaje:qcViaje,pig:qcPig,frente:qcFrente,cunas:qcCunas,rampa:qcRampa,carro:qcCarro,grua:qcGrua,sierra:qcSierra,barca:qcBarca,volver:qcBack}[k];if(F)F();}
function qcViaje(){const ro=MODE==='roma';
  if(!ro)vmS('⛏','Mnesíteo','transportista de mármol','<p>Un hombre cubierto de polvo blanco descarga un bloque en el taller de un escultor. «Vengo del Pentélico, como cada semana. De allí salió todo el mármol del Partenón y de los Propileos: miles y miles de bloques. ¿Quieres verlo? Te llevo en el carro vacío; es medio día de camino».</p><p class="sub">También se sacaba piedra del Himeto, un mármol gris azulado, y del Pireo, una piedra caliza blanda para cimientos y casas.</p>',[['Ir a la cantera del Pentélico',qcGo,'quiz'],vmBye]);
  else vmS('⛏',_t(3580,'Félix'),'marmolista del muelle','<p>En la orilla del Tíber, al pie del Aventino, se amontonan bloques de todos los colores, recién descargados de los barcos: es el muelle de los mármoles. Cada bloque lleva pintada o grabada la cantera, la fecha y el lote, como si fuera un paquete.</p><p>«Mira: mármol blanco de Luna, en Etruria; amarillo de Numidia; morado y blanco de Frigia; verde con vetas de Eubea; pórfido rojo de Egipto, durísimo. Todo el imperio cabe en este muelle. Pero la piedra con la que se ha hecho el anfiteatro de Tito no viene por mar: es travertino de Tíbur. ¿Quieres ver de dónde sale?»</p>',[['Ir a las canteras de Tíbur',qcGo,'quiz'],vmBye]);}
// ---- estaciones de la cantera
function qcFrente(){const ro=MODE==='roma';vmS('⛏',ro?'El frente de la cantera':'El frente de la cantera',ro?'travertino de Tíbur':'mármol del Pentélico',ro?'<p>El travertino es una piedra caliza que se formó en las aguas termales del Anio: por eso tiene esos agujeritos. Es fácil de cortar recién sacada y se endurece al aire. Se extrae en bancos escalonados, como una gran escalera tallada en el monte.</p><p>Del anfiteatro de Tito, que acaba de inaugurarse, dicen que lleva unos cien mil metros cúbicos: su fachada entera es de esta piedra, sujeta con grapas de hierro.</p><p class="sub">En las canteras trabajan esclavos y hombres libres; en algunas canteras imperiales lejanas, condenados.</p>':'<p>Toda la ladera está cortada en escalones, bancos de varios metros de alto. Los canteros abren a pico, golpe a golpe, unos canales estrechos alrededor de cada bloque, por los lados y por detrás. Siguen las capas naturales de la piedra: el «lecho». Cortar a contrapelo la hace saltar.</p><p>Los atenienses llaman a este mármol «pentélico»: blanco, de grano fino, y con un poco de hierro que con los años le da un tono dorado.</p><p class="sub">Todavía hoy se ven en el Pentélico las marcas de los picos antiguos y la rampa por la que se bajaban los bloques.</p>',[vmBye]);}
function qcCunas(){const ro=MODE==='roma',nm='Un bloque a medio sacar',sub='las cuñas';
  vmS('⛏',nm,sub,'<p>El bloque ya tiene los canales abiertos por tres lados. Ahora hay que despegarlo por debajo: se tallan unas ranuras en fila y se meten <b>cuñas de hierro</b>, entre dos chapas para que no se atasquen. Luego se golpean.</p><p>«¿Lo intentas?», te dice el capataz, y te da una maza.</p>',[['Golpear todas las cuñas por turnos, poco a poco',()=>qcSplit(true),'quiz'],['Golpear fuerte la primera cuña hasta el fondo',()=>qcSplit(false),'quiz'],vmBye]);}
function qcSplit(ok){const ro=MODE==='roma',nm='Un bloque a medio sacar',sub='las cuñas',q=qcz(),first=!q.d.split||q.d.split!==state.day;
  if(ok){if(first){q.d.split=state.day;q.blocks++;state.obols+=ro?4:6;save();updateStats();qAdd('ar',1,'Partir piedra es oficio de brazos y de paciencia.');}
    vmS('⛏',nm,sub,'<p>Golpe a golpe, todas a la vez, la tensión se reparte. De pronto se oye un crujido seco: el bloque se ha despegado limpio, en una sola pieza. El capataz silba de admiración.</p>'+(first?'<p>Te paga el jornal: '+(ro?'cuatro sestercios':'una dracma, seis óbolos')+'.</p><p class="sub">'+(ro?'Un jornal normal en Roma rondaba los cuatro sestercios.':'En las cuentas del Erecteion, grabadas en piedra hace unos veinte años, canteros, escultores y peones cobran lo mismo: una dracma al día, ya fueran ciudadanos, metecos o esclavos.')+'</p>':''),[vmBye]);}
  else vmS('⛏',nm,sub,'<p>La primera cuña se clava hasta el fondo y la piedra se raja en diagonal: medio bloque se parte en pedazos. El capataz se lleva las manos a la cabeza. «¡Días de trabajo perdidos! Hay que golpearlas todas por igual, para que la piedra se abra por donde queremos».</p>',[['Probar otra vez',qcCunas,'quiz'],vmBye]);}
function qcRampa(){vmS('⛏','La rampa de bajada','el trineo y las cuerdas','<p>Por una rampa empedrada, muy empinada, baja un bloque sobre un trineo de madera. No lo empujan: lo <b>frenan</b>. Unas cuerdas gruesas dan varias vueltas a postes clavados a los lados, y unos hombres van soltándolas poco a poco. Si una cuerda se rompe, el bloque baja solo y arrasa lo que encuentra.</p><p class="sub">Esta rampa, la «lithagogía», se conserva todavía en el Pentélico, con los agujeros de los postes.</p>',[vmBye]);}
function qcCarro(){if(qcOnce('carro'))qAdd('so',1,'Ya sabes cuánto cuesta un templo.');vmS('⛏','El carro de bueyes','hacia Atenas','<p>Abajo espera un carro de ruedas macizas con varias yuntas de bueyes. Para un tambor de columna grande hacían falta treinta o cuarenta parejas, y el viaje de quince kilómetros hasta la ciudad duraba dos o tres días. En las cuentas del santuario de Eleusis se anotan los bueyes, los carreteros y hasta el forraje.</p><p>Los bloques se tallaban casi enteros en la cantera, para pesar menos, pero se dejaba una capa protectora y unos salientes para atar las cuerdas. El acabado fino se hacía ya en su sitio, en el templo.</p>',[vmBye]);}
function qcGrua(){vmS('⛏','La grúa de rueda','magna rota','<p>Una grúa enorme levanta un bloque. Funciona con una rueda grande, de madera, en la que caminan dos o tres hombres por dentro, como hámsteres. Al girar, enrolla la cuerda en un eje, y unas poleas multiplican la fuerza: así unos pocos hombres alzan varias toneladas.</p><p class="sub">Vitruvio describe estas máquinas, y en un relieve algo posterior, el de la tumba de los Haterios, se ve una grúa de rueda trabajando en un templo.</p>',[vmBye]);}
function qcSierra(){vmS('⛏','La sierra','agua y arena','<p>Dos hombres mueven adelante y atrás una sierra de hierro sin dientes, tensada en un marco de madera. El que corta no es el hierro: es la <b>arena</b> dura que un chico echa en la ranura con agua. Así se sacan placas finas de mármol para revestir paredes y suelos. Es lentísimo: unos centímetros al día.</p>',[vmBye]);}
function qcBarca(){if(qcOnce('barca'))qAdd('so',1,'Ya sabes cómo llega la piedra a Roma.');vmS('⛏','La barcaza','por el Anio hacia Roma','<p>Los bloques bajan en barcazas por el río Anio hasta el Tíber y, de allí, hasta Roma: el agua es el camino más barato para una carga tan pesada. Otros van en carros por la Vía Tiburtina. Estrabón cuenta que la piedra de Tíbur y de Gabios llegaba a Roma por el río.</p><p class="sub">En Roma se construye también con toba, una piedra volcánica blanda; con ladrillo; y con hormigón hecho con «polvo de Puteoli», una ceniza volcánica que fragua incluso bajo el agua.</p>',[vmBye]);}
// ---- el taller de pigmentos
const QC_PIG=[
 ['Azul egipcio','κύανος · caeruleum','El primer pigmento artificial de la historia. Se hace mezclando arena, cobre (o limaduras de bronce), cal y natrón, y cociéndolo en un horno muy caliente durante horas: sale un vidrio azul que se muele. Lo inventaron en Egipto hace dos mil años.',{a:'En Atenas lo compramos a mercaderes de Oriente.',r:'Vitruvio cuenta que un tal Vestorio montó un taller en Puteoli, en Campania, para fabricarlo aquí.'}],
 ['Bermellón (cinabrio)','κιννάβαρι · minium','Un rojo vivo, precioso y carísimo: es un mineral de mercurio. Se muele y se lava.',{a:'Calias, el que tienes delante, descubrió hace unos veinte años cómo sacarlo del mineral de las minas de Laurio. Lo cuenta Teofrasto.',r:'El mejor viene de Sisapo, en Hispania, y es monopolio del Estado: se trae en bruto a Roma y se refina en unos talleres entre el templo de Flora y el de Quirino, según Plinio.'}],
 ['Ocre rojo y amarillo','μίλτος · rubrica, sil','Tierras con hierro, baratas y resistentes. Calentando el ocre amarillo se vuelve rojo.',{a:'El mejor rojo es el de la isla de Ceos; Atenas vigila de cerca su comercio, y pronto se lo reservará por ley.',r:'Plinio distingue entre colores «austeros», baratos como estos, y «floridos», tan caros que los paga el cliente aparte.'}],
 ['Blanco de plomo','ψιμύθιον · cerussa','Se cuelgan láminas de plomo sobre vinagre en vasijas cerradas; el vapor las cubre de una costra blanca que se raspa. Es venenoso: lo usan pintores y también mujeres para blanquearse la cara.',{a:'Teofrasto describe el proceso.',r:'Vitruvio y Plinio lo describen; Vitruvio ya avisa de que el plomo es dañino.'}],
 ['Verde y azul de cobre','malaquita y azurita','Dos minerales de cobre que se muelen: la malaquita da un verde y la azurita un azul profundo. Cuanto más fino se muele, más claro sale el color.',{a:'',r:''}],
 ['Negro','μέλαν · atramentum','Hollín de quemar resina, madera o huesos, mezclado con cola. El mismo negro sirve para la tinta.',{a:'',r:''}],
 ['Púrpura','πορφύρα · purpurissum','Sale de unos caracoles marinos, los múrices: hacen falta miles para un poco de color. Vale más que el oro.',{a:'',r:''}]];
function qcPig(){const ro=MODE==='roma',nm=ro?'Vestorino':_t(9740,'Calias'),sub=ro?'vendedor de colores':'pintor y fabricante de colores';
  const intro=ro?'<p>Una tienda llena de cuencos con polvos de colores, ordenados como en una botica. «Para las paredes de una casa, para una estatua, para los barcos… lo que quieras. Las paredes se pintan al fresco: con el enlucido todavía húmedo, para que el color quede dentro de la cal. Y las estatuas, como siempre: nadie quiere una estatua blanca, parece sin terminar».</p>':'<p>Un viejo con las manos manchadas de colores muele algo rojo en un mortero. «Las estatuas y los templos no se quedan blancos, forastero: se pintan. Los ojos, los labios, el pelo, la ropa con sus cenefas, los relieves con fondo azul. Y al final, a las estatuas de mármol se les da una capa de cera caliente que les da un brillo de piel. Mira mis colores».</p>';
  vmS('🎨',nm,sub,intro,[...QC_PIG.map((p,i)=>[p[0],()=>qcPigOne(i),'quiz']),['Ayudar a pintar una estatua',qcPinta,'quiz'],vmBye]);}
function qcPigOne(i){const ro=MODE==='roma',p=QC_PIG[i],extra=ro?p[3].r:p[3].a,q=qcz();q.pig=q.pig||{};const nw=!q.pig[i];q.pig[i]=1;save();
  if(nw&&Object.keys(q.pig).length===QC_PIG.length&&qcOnce('pigall'))qAdd('so',2,'Ya sabes de dónde sale cada color.');
  vmS('🎨',ro?'Vestorino':_t(9740,'Calias'),p[1],'<p><b>'+p[0]+'</b>. '+p[2]+'</p>'+(extra?'<p class="sub">'+extra+'</p>':''),[['Ver otro color',qcPig],vmBye]);}
function qcPinta(){const ro=MODE==='roma',nm=ro?'Vestorino':_t(9740,'Calias');
  vmS('🎨',nm,'pintar una estatua','<p>Tenéis delante una estatua de mármol de una diosa, recién tallada. ¿Qué color le das al manto?</p>',[['Azul egipcio, con una cenefa de ocre',()=>qcPinta2(true),'quiz'],['Ninguno: mejor dejarla blanca',()=>qcPinta2(false),'quiz']]);}
function qcPinta2(ok){const ro=MODE==='roma',nm=ro?'Vestorino':_t(9740,'Calias');if(ok&&qcOnce('pinta'))qAdd('kl',1,'Has ayudado a pintar una estatua.');
  vmS('🎨',nm,'pintar una estatua',ok?'<p>Mezcláis el pigmento con un aglutinante —clara de huevo, cola o cera— y lo dais con pinceles finos. Después, el pelo de ocre oscuro, los labios de bermellón, los ojos dibujados. Al final, la cera caliente. La diosa parece respirar.</p><p class="sub">Durante siglos se pensó que las estatuas antiguas eran blancas, porque la pintura se había borrado con el tiempo. Hoy, con luz ultravioleta y análisis químicos, se encuentran restos de color en muchísimas.</p>':'<p>«¿Blanca?», se ríe. «Así la querrán los que la desentierren dentro de dos mil años, cuando se le haya borrado la pintura. Aquí, una estatua sin pintar está sin terminar».</p>',[['Probar otra vez',qcPinta,'quiz'],vmBye]);}

// ============================================================ EL CAMINO DEL FORASTERO: de extranjero a ciudadano (Atenas 386 a.C. · Roma 80 d.C.)
// Une lo que ya existía (prostátes, metoíkion, énktesis por decreto, ciudadanía por el emperador o por Malaca, hospitalidad)
// en un camino de diez pasos que se ve en el Diario (pestaña «Forastero»), y añade los pasos que faltaban.
// Cada modo guarda su partida aparte, así que fxz().ciu es la ciudadanía ateniense en Atenas y la romana en Roma.
function cvYear(){try{return calNow().year;}catch(e){return 0;}}
function cvServ(){const f=fxz();f.serv=f.serv||{};try{if(vmz().once.pan)f.serv.pan=1;}catch(e){}return f.serv;}
const CV_SERV={eis:'Pagar la contribución de guerra (eisphorá)',pan:'Llevar las bandejas en las Panateneas',flota:'Servir en la flota con Ifícrates',don:'Donar piedra para las murallas de Conón'};
function cvLatin(){const o=origen();return !!(o&&o.id==='malaca');}
// ---- los diez pasos, para el Diario
function cvSteps(){const f=fxz(),ro=MODE==='roma',fem=pjFem(),c=cz(),fr=bestFriend(),S=[];const st=(ok,h,t)=>S.push({ok:!!ok,h,t});
  if(!ro){const sv=Object.keys(cvServ()).length,y=cvYear();
    st(true,'Forastero de paso','Te protegen la hospitalidad y el próxeno de tu ciudad.');
    st(f.prost,'Un ciudadano que responda por ti','Tu prostátes. Pídeselo a tu paisano.');
    st(f.st==='meteco','Inscripción como meteco','Con el demarco de Mélite, pagando el metoíkion.');
    st(f.st==='meteco'&&(f.iso||f.mkY===y),'El metoíkion de este año','Se paga cada año: '+(fem?'seis':'doce')+' dracmas. Quien no paga o vive sin prostátes puede ser juzgado y vendido como esclavo.');
    st(sv>=3,'Servir a la ciudad ('+sv+' de 3)','Opciones: '+Object.entries(CV_SERV).map(([k,t])=>(cvServ()[k]?'✓ ':'')+t).join(' · ')+'.');
    st(c.st>=2,'Derecho a casa y tierra (énktesis)','Un decreto de la Asamblea: pregunta a Formión, en la mesa de Pasión.');
    st(f.iso,'Igualdad de impuestos (isotéleia)','Dejas de pagar el metoíkion. Pídelo a tu paisano cuando hayas servido a la ciudad.');
    if(!fem){st(fr,'Un ciudadano que proponga tu ciudadanía','Un amigo con al menos «Confianza».');
      st(f.ciu,'Dos votaciones y un juicio','La Asamblea vota el decreto; en la siguiente, seis mil ciudadanos en voto secreto; y cualquiera puede impugnarlo por ilegal ante un tribunal.');
      st(f.ciu,'Ciudadano de Atenas','Inscrito en el demo de Mélite, la tribu Cecrópide y una fratría. Votas en la Pnyx y desfilas como ciudadano. Un ciudadano por decreto no puede ser arconte ni sacerdote; sus hijos sí.');}
    else{st(f.hon,'Benefactora de la ciudad','Las mujeres, atenienses o no, no tenían derechos políticos. Tu camino termina en los honores: un decreto con una corona de olivo y tu nombre en una estela.');
      st(f.hon,'Tu nombre en la Acrópolis','Algunas mujeres, sobre todo sacerdotisas y benefactoras, recibieron decretos de honor. Ninguna votó en la Asamblea.');}}
  else{const lat=cvLatin(),anon=f.anon||0;
    st(true,fem?'Peregrina':'Peregrino','Persona libre de provincia: sin toga, sin matrimonio legítimo con romanos, juzgada por el pretor de los extranjeros.');
    st(fr||(state.lessons||[]).includes('cliente'),'Un patrono','Ve a la salutatio y hazte amigo de alguien importante.');
    st(Object.keys(f.tes||{}).length,'Hospitalidad','Una tésera de hospitalidad con alguien de otra ciudad.');
    st(f.ciu&&f.via==='municipio','Vía municipal: magistrado en un municipio latino','Malaca, en la Bética, tiene el derecho latino desde Vespasiano: sus magistrados se hacen ciudadanos.'+(fem?' Las mujeres no podían ser magistradas: esta vía no es para ti.':''));
    st(false,'Vía militar: veinticinco años en las tropas auxiliares',(f.vet?'Ya la conoces: ':'')+'Conoce al veterano Tiberio Claudio Dases, junto al Templo de la Paz: te enseñará su diploma de bronce.');
    st(f.ciu&&f.via==='anona'||f.liber,'Vía del trigo: seis años trayendo trigo a Roma ('+anon+' de 6)',lat?'Eres latino de Malaca: si tienes barco, ponlo al servicio de la anona (habla con Cayo Atilio, en el reparto de trigo).':'Solo para latinos, como los de Malaca, con barco propio.');
    st(false,'Vía de los vigiles','Los latinos que servían seis años como bomberos de Roma se hacían ciudadanos. Seis años son demasiados para este juego.');
    st(f.ciu&&(f.via==='emperador'||!f.via),'Vía del favor imperial','Un amigo importante pide al emperador la ciudadanía para ti: habla con el argentario Sexto Afranio.');
    st(f.ciu,'El día del cambio','Nombre nuevo, con el del emperador: '+(fem?'Flavia':'Tito Flavio')+'. Inscripción en una tribu, normalmente la Quirina. Derecho a la toga.');
    st(f.ciu,fem?'Ciudadana romana':'Ciudadano romano','Matrimonio legítimo, testamento romano, apelar al emperador, no ser azotado ni torturado'+(fem?'. Sin voto ni cargos, como todas las romanas':'')+'.');}
  return S;}
function cvPanel(){const S=cvSteps(),ro=MODE==='roma',via=S.slice(3,8).some(s=>s.ok),n=ro?S.filter((s,i)=>s.ok&&(i<3||i>7)).length+(via?1:0):S.filter(s=>s.ok).length,tot=ro?6:S.length;return '<div class="entry"><span class="label">Tu camino a la ciudadanía · '+n+' de '+tot+(ro?' (basta con una de las vías 4 a 8)':'')+'</span><h3>'+(MODE==='roma'?'De peregrino a ciudadano romano':'De forastero a ciudadano de Atenas')+'</h3><ol style="margin:6px 0 0;padding-left:20px;line-height:1.45">'+S.map(s=>'<li style="margin:4px 0;'+(s.ok?'':'opacity:.72')+'"><b>'+(s.ok?'✓ ':'')+s.h+'</b><br><span class="sub">'+s.t+'</span></li>').join('')+'</ol></div>';}
const fxJournal0=fxJournal;fxJournal=function(){const h=fxJournal0();return h.replace(/<\/div>$/,cvPanel()+'</div>');};
// ---- opciones nuevas en las conversaciones
function cvOpts(n,add){const f=fxz(),ro=MODE==='roma',fem=pjFem(),y=cvYear();
  if(!ro&&n.id==='demarco'&&f.st==='meteco'){const fee=fem?36:72;
    if(!f.iso&&f.mkY!==y)add(_t(10373,'Pagar el metoíkion de este año (')+(f.mkLate?fee*2:fee)+' óbolos)','quiz',()=>{const t=f.mkLate?fee*2:fee,B=$('dBody');if(state.obols<t){B.innerHTML='<p>«Te faltan '+(t-state.obols)+_t(10374,' óbolos. No tardes».</p>');renderOpts();return;}
      state.obols-=t;f.mkY=y;const late=f.mkLate;f.mkLate=0;save();updateStats();B.innerHTML=_t(10375,'<p>Nausícrates tacha tu nombre en la lista de deudores. ')+(late?_t(10376,'«Te has librado por poco: te habían denunciado ante el polemarco por no pagar. Con la multa queda arreglado, pero otra vez podrías acabar en el mercado de esclavos».'):_t(10377,'«Al día, como debe ser».'))+'</p>';renderOpts();});
    if(!cvServ().eis)add(_t(10378,'Pagar la contribución de guerra, la eisphorá (30 óbolos)'),'quiz',()=>{const B=$('dBody');if(state.obols<30){B.innerHTML='<p>«Te faltan '+(30-state.obols)+_t(10379,' óbolos».</p>');renderOpts();return;}
      state.obols-=30;cvServ().eis=1;save();updateStats();qAdd('kl',1);B.innerHTML=_t(10380,'<p>«La eisphorá es un impuesto extraordinario para la guerra, y los metecos pagan su parte, como los ciudadanos ricos. La ciudad no lo olvidará».</p><p class="sub">Los metecos pagaban la eisphorá en una proporción mayor que los ciudadanos.</p>');renderOpts();});}
  if(!ro&&n.id==='ificrates'&&f.st==='meteco'&&!cvServ().flota)add(_t(10381,'Ofrecerme para servir en la flota'),'quiz',()=>{cvServ().flota=1;save();qAdd('ar',1);qAdd('kl',1);$('dBody').innerHTML=_t(10382,'<p>«Bien. Los metecos reman en los trirremes y forman como hoplitas cuando la ciudad los llama. En la guerra que acaba de terminar, muchos metecos lucharon por Atenas, y en tiempos de Trasíbulo algunos se ganaron así la ciudadanía». Te apunta en una lista.</p>');renderOpts();});
  if(n.id==='paisano'&&!ro&&f.st==='meteco'){
    if(!f.iso)add(_t(10383,'¿Puedo dejar de pagar el metoíkion? (isotéleia)'),'quiz',()=>{const sv=Object.keys(cvServ()).length,B=$('dBody');
      if(sv<3||qLv('kl')<5){B.innerHTML=_t(10384,'<p>«La isotéleia, pagar como un ciudadano, la vota la Asamblea a quien ha servido bien a la ciudad. Te falta: ')+[sv<3?_t(10385,'servir a la ciudad (')+sv+_t(10386,' de 3: mira tu Diario)'):'',qLv('kl')<5?_t(10387,'Kléos 5 (tienes ')+qLv('kl')+')':''].filter(Boolean).join(' y ')+'».</p>';renderOpts();return;}
      f.iso=1;save();qAdd('kl',2);B.innerHTML=_t(10388,'<p>Unos días después, la Asamblea vota tu isotéleia: «por su buena disposición hacia el pueblo de los atenienses». Ya no pagas el metoíkion y tributas como un ciudadano.</p>');toast(_t(10389,'<span class="label">Isotéleia</span><br>Ya no pagas el impuesto de los metecos.'));renderOpts();});
    else if(!f.ciu&&!fem)add(_t(10390,'Quiero pedir la ciudadanía de Atenas'),'quiz',()=>cvPetA());
    else if(fem&&!f.hon)add(_t(10391,'¿Puede la ciudad honrarme por lo que he hecho?'),'quiz',()=>{const B=$('dBody');if(cz().st<2||qLv('kl')<8){B.innerHTML=_t(10392,'<p>«Primero necesitas el derecho a casa y tierra y una gran fama (Kléos 8; tienes ')+qLv('kl')+')».</p>';renderOpts();return;}
      f.hon=1;save();qAdd('kl',3);B.innerHTML=_t(10393,'<p>La Asamblea vota un decreto en tu honor: alabarte y coronarte con una corona de olivo «por su virtud y su buena disposición hacia el pueblo de los atenienses». Se graba en una estela.</p><p class="sub">Como mujer, en Atenas no podías ser ciudadana con derechos políticos: ni las atenienses lo eran. Pero sí podías recibir honores.</p>');renderOpts();});}
  if(ro&&n.id==='paisano'&&!f.ciu)add(_t(10394,'¿Qué caminos hay para hacerme ciudadano romano?'),'quiz',()=>{$('dBody').innerHTML=_t(10395,'<p>«Hay varios, y ninguno es corto. El de los magistrados de un municipio latino, como nuestra Malaca. El de los soldados de las tropas auxiliares, después de veinticinco años. El de los latinos que traen trigo a Roma en su barco durante seis años. El de los bomberos latinos, después de seis. Y el más rápido: que un amigo importante se lo pida al emperador».</p><p class="sub">En tu Diario, pestaña «Forastero», tienes el camino paso a paso.</p>');renderOpts();});}
// ---- Atenas: la petición de ciudadanía (dos votaciones y un juicio)
function cvPetA(){const f=fxz(),fr=bestFriend(),lack=[];if(cz().st<2)lack.push('el derecho a casa y tierra (énktesis)');if(!f.iso)lack.push('la isotéleia');if(qLv('kl')<8)lack.push('Kléos 8 (tienes '+qLv('kl')+')');if(qLv('lo')<6)lack.push('Lógos 6 (tienes '+qLv('lo')+')');if(!fr)lack.push('un amigo ciudadano con «Confianza»');
  if(lack.length)return vmS('Π',origen()?origen().pn:'Tu paisano','tu prostátes','<p>«La ciudadanía de Atenas es lo más difícil de conseguir en toda Grecia. Pasión, el banquero, empezó como esclavo y aún la está esperando. Te falta: '+lack.join('; ')+'».</p>',[vmBye]);
  vmS('Π','La Asamblea','primera votación','<p>'+fr.name+' sube a la tribuna de la Pnyx y propone el decreto: «Que '+fxNombre()+' sea ateniense, por los servicios que ha hecho a la ciudad». Recuerda tu donación, tus servicios en la flota, tu isotéleia. La Asamblea vota a mano alzada: sí.</p><p>Pero no basta. En la siguiente Asamblea votarán al menos <b>seis mil</b> ciudadanos, en secreto, con piedrecillas.</p>',[['Esperar a la segunda votación',()=>{
    const ok=R()<0.55+qLv('kl')*0.04;if(!ok)return vmS('Π','La Asamblea','segunda votación','<p>Las piedrecillas se cuentan una a una… y no llegan a seis mil. Alguien ha hecho correr que eres amigo de los espartanos. Tendrás que intentarlo otro día.</p>',[vmBye]);
    vmS('⚖','La Asamblea','segunda votación','<p>Más de seis mil votos a favor. Pero al salir, un ciudadano se acerca al tesmóteta y presenta una <b>acusación por ilegalidad</b> (graphé paranómon) contra el decreto: dice que no mereces la ciudadanía. Habrá juicio.</p><p class="sub">Le pasó a Lisias: Trasíbulo le hizo dar la ciudadanía en el 403 por haber ayudado a la democracia, y un tal Arquino la anuló por ilegal.</p>',[['Ir al juicio',()=>cvJuicio(0,0),'quiz']]);},'quiz'],vmBye]);}
function cvJuicio(i,pts){const Q=[['El acusador dice que eres un extranjero interesado. ¿Qué respondes?',[['Enumero mis servicios con testigos: la eisphorá, la flota, la donación',2],['Digo que en mi tierra soy alguien importante',0],['Lloro y presento a mis amigos llorando',1]]],
  ['Dice que el decreto no siguió el procedimiento. ¿Qué haces?',[['Pido que se lea el decreto y las dos votaciones, con sus fechas',2],['Digo que eso son tecnicismos',0],['Le acuso a él de algo peor',0]]],
  ['El último turno es tuyo. ¿Cómo terminas?',[['Pido a los jueces que piensen en lo que Atenas gana con ciudadanos como yo',2],['Les recuerdo que he pagado mucho dinero',0],['Juro por los dioses que amo a Atenas',1]]]];
  if(i>=Q.length){const f=fxz(),win=pts+qLv('lo')/3>=5;if(!win)return vmS('⚖','El tribunal','acusación por ilegalidad','<p>Los jueces votan con sus fichas de bronce. Pierdes por pocos votos: el decreto queda anulado. Como Lisias. Podrás volver a intentarlo más adelante.</p>',[vmBye]);
    f.ciu=1;f.dciu=state.day||1;save();qAdd('kl',5,'Ya eres ateniense.');qAdd('lo',2);
    toast('<span class="label">Ciudadano de Atenas</span><br>'+fxNombre()+', del demo de Mélite.');
    return vmS('⚖','El tribunal','acusación por ilegalidad','<p>Los jueces votan: ganas. El decreto se graba en una estela y te inscriben en el registro del demo de Mélite y en la tribu Cecrópide; una fratría te acepta con un sacrificio. Ya eres ciudadano de Atenas.</p><p>Desde hoy puedes hablar y votar en la Pnyx, ser jurado y desfilar en las Panateneas como un ciudadano. No podrás ser arconte ni sacerdote, pero tus hijos sí.</p><p class="sub">Muy pocos extranjeros lo consiguieron. Pasión el banquero lo logró unos años después del 386; su hijo Apolodoro llegó a trierarco.</p>',[vmBye]);}
  const [q,o]=Q[i];vmS('⚖','El tribunal','acusación por ilegalidad','<p>'+q+'</p>',o.slice().sort(()=>R()-0.5).map(([t,p])=>[t,()=>cvJuicio(i+1,pts+p),'quiz']));}
// ---- Roma: el veterano con su diploma y la vía del trigo
function cvSetup(){if(MODE!=='roma')return;const f=artAnchor('ro_paz',22,-12);if(f)artPerson(f,{chiton:'#b8a888',himation:'#7a4a3a',hair:'#bab0a0',beard:true},'cv:vet','Tiberio Claudio Dases','veterano de un ala tracia',3);}
function cvAct(o){if(o.act==='cv:vet')cvVet();}
function cvVet(){const f=fxz();f.vet=1;save();vmS('⚔','Tiberio Claudio Dases','veterano de un ala tracia','<p>Un viejo jinete tracio te enseña, orgulloso, dos placas de bronce unidas con alambre: su <b>diploma militar</b>. «Veinticinco años en un ala de caballería, en Germania. Al licenciarme, el emperador me dio la ciudadanía romana, a mí, a mis hijos y a mis descendientes, y el derecho a casarme legalmente con mi mujer, que es de allí. Aquí está escrito, copiado del original que está colgado en Roma, en el Capitolio».</p><p>«Por eso me llamo Tiberio Claudio: me licenciaron en tiempos de Claudio, y los que reciben la ciudadanía toman el nombre del emperador».</p><p class="sub">Se han encontrado cientos de estos diplomas. Los ciudadanos servían en las legiones; los no ciudadanos, en las tropas auxiliares, y salían ciudadanos. Así se fue romanizando el imperio.</p>',[vmBye]);}
function cvAnona(){const f=fxz(),fem=pjFem(),mo=calNow().mo+'-'+cvYear();let own=false;try{own=bz().st===3;}catch(e){}
  if(!cvLatin()||!own)return vmS('🌾','Cayo Atilio','encargado del reparto de trigo','<p>«Claudio prometió la ciudadanía a los latinos que construyeran un barco de al menos diez mil modios y trajeran trigo a Roma durante seis años. '+(!cvLatin()?'Pero tú no eres latino.':'Pero necesitas un barco propio.')+'»</p>',[vmBye]);
  if(f.anonM===mo)return vmS('🌾','Cayo Atilio','encargado del reparto de trigo','<p>«Tu barco ya ha hecho su viaje este año. Vuelve el que viene». <span class="sub">('+(f.anon||0)+' de 6 viajes. En el juego, cada mes cuenta como un año).</span></p>',[vmBye]);
  f.anonM=mo;f.anon=(f.anon||0)+1;save();qAdd('kl',1);
  if(f.anon>=6){if(fem){f.liber=1;save();return vmS('🌾','Cayo Atilio','encargado del reparto de trigo','<p>Seis años de trigo para Roma. Claudio dio a los hombres latinos la ciudadanía; a las mujeres, los privilegios de las madres de cuatro hijos: llevar sus asuntos sin tutor. Desde hoy los tienes.</p>',[vmBye]);}
    f.ciu=1;f.via='anona';save();try{pjAvatar();}catch(e){}qAdd('kl',4);toast('<span class="label">Ciudadanía romana</span><br>Por tus seis años al servicio de la anona.');
    return vmS('🌾','Cayo Atilio','encargado del reparto de trigo','<p>«Seis años trayendo trigo a Roma. El prefecto de la anona firma tu certificado: por la ley de Claudio, eres ciudadano romano». Tomas el nombre del emperador: '+fxNombre()+'.</p>',[vmBye]);}
  vmS('🌾','Cayo Atilio','encargado del reparto de trigo','<p>Tu barco descarga en Ostia diez mil modios de trigo de Egipto para la anona. El funcionario lo anota: viaje '+f.anon+' de 6.</p><p class="sub">Claudio ofreció este premio después de un invierno de hambre en que la plebe lo acorraló en el Foro a pedradas y pedazos de pan.</p>',[vmBye]);}
const vmFrum0=vmFrum;vmFrum=function(){vmFrum0();const f=fxz();if(MODE==='roma'&&!f.ciu&&cvLatin()){const o=$('dOpts'),b=document.createElement('button');b.className='quiz';b.innerHTML='<span class="n">9</span><span>Poner mi barco al servicio de la anona ('+(f.anon||0)+' de 6)</span>';b.onclick=cvAnona;o.insertBefore(b,o.lastChild);}};
// ---- la Asamblea de la progresión: en Atenas, solo los ciudadanos hablan y votan
const progAct0=progAct;progAct=function(o){if(MODE==='atenas'&&o.act==='pg:asamblea'&&!fxz().ciu){const fem=pjFem();
  return vmS('✦','La Asamblea','en la Pnyx','<p>En la Pnyx, seis mil ciudadanos escuchan al heraldo: «¿Quién quiere tomar la palabra?». Tú no puedes: '+(fem?'ninguna mujer, ateniense o no, habla ni vota en la Asamblea':'como meteco, no hablas ni votas')+'. Miras desde fuera, como tantos otros.</p><p>Pero hay otra manera de pesar en la ciudad: escribir el discurso para un ciudadano, como hace Lisias, que también es meteco.</p>',[['Escribir un discurso para un ciudadano amigo',()=>{if(progToday('asam')){vmS('✦','La Asamblea','en la Pnyx','<p>Hoy ya escribiste uno.</p>',[vmBye]);return;}progMark('asam');const ok=R()<0.4+qLv('lo')*0.06;if(ok){qAdd('lo',1);qAdd('kl',1);}save();
    vmS('✦','La Asamblea','en la Pnyx','<p>'+(ok?'Tu amigo lee tu discurso con buena voz y la propuesta sale adelante. Nadie sabe que las palabras eran tuyas, pero tú sí.':'Tu amigo lee tu discurso, pero otro orador le gana la partida. Mañana será otro día.')+'</p>',[vmBye]);},'quiz'],vmBye]);}
  return progAct0(o);};
// ---- el metoíkion se renueva cada año: aviso y denuncia si no se paga
const CVT={t:20};
function cvTick(dt){if(MODE!=='atenas'||!state||ui!=='play')return;CVT.t-=dt;if(CVT.t>0)return;CVT.t=60;const f=fxz();if(f.st!=='meteco'||f.iso)return;
  const y=cvYear();if(f.mkY===undefined){f.mkY=calNow(f.dm||state.day).year;save();return;}
  if(f.mkY===y)return;if(!f.mkY0||f.mkY0!==y){f.mkY0=y;f.mkD=state.day||1;save();toast('<span class="label">Año nuevo</span><br>Toca pagar el metoíkion: ve al demarco de Mélite.');return;}
  if(!f.mkLate&&(state.day||1)-f.mkD>=8){f.mkLate=1;save();toast('<span class="label">¡Denunciado!</span><br>Alguien te ha denunciado ante el polemarco por no pagar el metoíkion. Págalo con multa al demarco antes de que te subasten como esclavo.');}}

// ============================================================ EL HADES GRIEGO: la bajada órfica (modo Atenas)
// Misma idea que los Infiernos de la Eneida en Roma (un camino largo de estaciones), pero con lo que es solo griego:
// la laminilla de oro órfica, el óbolo de Caronte, la torta de miel para Cerbero, los tres jueces del Gorgias, la fuente del Olvido
// junto al ciprés blanco y el lago de Mnemósine, Perséfone, la sombra de Aquiles y la elección de vidas del mito de Er.
// Zona aparte: X 9500, Z 12000, Y 4200. Objetos «hd:». Estado en state.hades.
const HD={Z:12000,built:false};
function hdz(){if(!state.hades||typeof state.hades!=='object')state.hades={st:0,lam:0,done:0};return state.hades;}
function hdIn(){return HD.built&&Math.abs(player.x-FZ.X)<60&&player.z>HD.Z-90&&player.z<HD.Z+280&&player.feet>FZ.Y-60&&player.feet<FZ.Y+200;}
const regionName1=regionName;regionName=function(){if(hdIn())return player.z-HD.Z>180?_t(2897,'Los Campos Elíseos'):'El Hades';return regionName1();};
function hdOrfico(){return !!(state.fest&&state.fest.orficos);}
function hdBuild(){if(HD.built)return;HD.built=true;const X=FZ.X,Z=HD.Z,Y=FZ.Y,g=grp(X,Y,Z,0),rk=lam('#34302e'),dk=lam('#1e1c1c');
  box(30,0.6,330,dk,0,-0.3,95,g);addPlat(X,Z+95,30,330,0,Y);addSeg(X-14,Z-70,X-14,Z+260,0.4);addSeg(X+14,Z-70,X+14,Z+260,0.4);addSeg(X-14,Z-70,X+14,Z-70,0.4);addSeg(X-14,Z+260,X+14,Z+260,0.4);
  for(let i=0;i<70;i++){const s=R()<0.5?-1:1;const b=box(rr(2,5),rr(5,16),rr(2,5),rk,s*rr(10,14),0,rr(-70,175),g);b.position.y=b.geometry.parameters.height/2;}
  // la fosa de la entrada, como la de Odiseo, y el Aqueronte con la barca
  box(3,0.3,3,lam('#3a1a14'),0,0.05,-50,g);fzSp('#ff7a30',6,4,0.5,null,X,Y+1.2,Z-50);
  {const w=new THREE.Mesh(new THREE.PlaneGeometry(28,12),new THREE.MeshPhongMaterial({color:'#1e2a2e',shininess:70}));w.rotation.x=-Math.PI/2;w.position.set(X,Y+0.03,Z-18);scene.add(w);const b=grp(X-4,Y,Z-18,0);box(2,0.5,5,lam('#3a2a1e'),0,0.3,0,b);
    const ch=makePerson({noVary:true,chiton:'#4a4038',hair:'#d8d0c2',beard:true,beardC:'#d8d0c2',staff:true});ch.position.set(0,0.5,1.5);b.add(ch);}
  // Cerbero
  {const c=grp(X,Y,Z+25,Math.PI);box(2.4,1.2,1,lam('#2a2020'),0,1,0,c);for(const dx of[-0.7,0,0.7])box(0.5,0.5,0.8,lam('#2a2020'),dx,1.9,0.8,c);for(const dx of[-0.9,0.9])box(0.25,0.9,0.25,lam('#2a2020'),dx,0.45,0,c);fzSp('#ff4020',3,2,0.35,c,0,2,0.8);}
  // los tres jueces, sentados en sus tronos
  [['Minos',-5],['Radamantis',0],[_t(782,'Éaco'),5]].forEach(([n,dx])=>{box(2,2.6,1.4,lam('#4a4440'),dx,1.3,58,g);const j=divineFigure(X+dx,Z+57,{chiton:'#d8d0c2',himation:'#3a3a4a',beard:true,hair:'#d8d0c2',staff:true},'#b0b0d0',n,'',1.05);j.lb.visible=false;j.mk.visible=false;j.g.rotation.y=Math.PI;});
  // el Tártaro, al fondo a la izquierda: resplandor rojo y la roca de Sísifo en una cuesta
  fzSp('#ff3010',26,16,0.55,null,X-12,Y+6,Z+86);{const r=new THREE.Mesh(new THREE.IcosahedronGeometry(1.4,0),lam('#5a5048'));r.position.set(X-10,Y+3,Z+84);scene.add(r);const sl=box(6,0.4,10,rk,-10,1.2,84,g);sl.rotation.x=-0.35;}
  // el ciprés blanco y la fuente del Olvido, a la izquierda; el lago de Mnemósine, más allá, con dos guardianes
  {const t=grp(X-8,Y,Z+110,0);box(0.5,3,0.5,lam('#e8e4dc'),0,1.5,0,t);const c=new THREE.Mesh(new THREE.ConeGeometry(1.2,8,8),lam('#f0eee8'));c.position.y=6.5;t.add(c);
    const w=new THREE.Mesh(new THREE.CircleGeometry(2.2,16),new THREE.MeshPhongMaterial({color:'#8a9aa0',shininess:30}));w.rotation.x=-Math.PI/2;w.position.set(X-5,Y+0.04,Z+112);scene.add(w);}
  {const w=new THREE.Mesh(new THREE.PlaneGeometry(22,12),new THREE.MeshPhongMaterial({color:'#3a6a9a',shininess:90}));w.rotation.x=-Math.PI/2;w.position.set(X,Y+0.04,Z+140);scene.add(w);fzSp('#a0d0ff',20,6,0.35,null,X,Y+2,Z+140);
    for(const dx of[-6,6]){const gd=divineFigure(X+dx,Z+132,{chiton:'#2a2a3a',himation:'#1a1a2a',hair:'#1a1a1a',beard:true},'#8090c0','Guardián','',1.1);gd.lb.visible=false;gd.mk.visible=false;gd.g.rotation.y=Math.PI;}}
  // Hades y Perséfone
  {box(9,0.6,4,lam('#2a2430'),0,0.3,165,g);for(const dx of[-2,2])box(1.8,3,1.4,lam('#3a2a4a'),dx,1.5,166,g);
    const h=divineFigure(X-2,Z+164.5,{chiton:'#1a1a22',himation:'#3a1a2a',beard:true,hair:'#1a1410'},'#6a5a8a',_t(5513,'Hades'),'',1.2);h.lb.visible=false;h.mk.visible=false;h.g.rotation.y=Math.PI;
    const p=divineFigure(X+2,Z+164.5,{female:true,chiton:'#e8e0d0',himation:'#6a2a3a',hair:'#3a2a1a',veil:true},'#e0b0c0',_t(5562,'Perséfone'),'',1.1);p.lb.visible=false;p.mk.visible=false;p.g.rotation.y=Math.PI;}
  // los Campos Elíseos y, al final, la llanura del Olvido del mito de Er
  box(28,0.62,50,lam('#8ab870'),0,0,200,g);for(let i=0;i<12;i++){const t=grp(X+rr(-12,12),Y+0.3,Z+rr(180,222),0);box(0.4,2.4,0.4,lam('#6a5236'),0,1.2,0,t);const c=new THREE.Mesh(new THREE.SphereGeometry(1.6,8,6),lam('#9ac880'));c.position.y=3;t.add(c);}
  fzSp('#fff0b0',40,40,0.85,null,X,Y+60,Z+300);{const a=divineFigure(X+4,Z+198,{chiton:'#d8c8a0',himation:'#8a2a1a',hair:'#c8a050'},'#ffe0a0',_t(846,'Aquiles'),'',1.15);a.lb.visible=false;a.mk.visible=false;a.g.rotation.y=-Math.PI/2;}
  box(28,0.63,30,lam('#c8c4bc'),0,0,240,g);
  const E=(dz,act,nm,sub,r,dx)=>egxObj(X+(dx||0),Z+dz,Y,act,nm,sub,r||4);
  E(-50,'hd:fosa','La fosa','la ofrenda a los muertos',4);E(-24,'hd:caronte','Caronte','el barquero del Aqueronte',4,-4);E(22,'hd:cerbero','Cerbero','el perro del Hades',4);
  E(52,'hd:jueces','Los tres jueces','Minos, Radamantis y Éaco',5);E(84,'hd:tartaro','El Tártaro','los castigados',5,-8);E(110,'hd:leteo','La fuente del ciprés blanco','la primera fuente',4,-5);
  E(134,'hd:mnemosine','El lago de Mnemósine','sus guardianes',5);E(160,'hd:persefone','Hades y Perséfone','los reyes de los muertos',5);E(196,'hd:aquiles','Una sombra','en los prados',4,4);E(236,'hd:er','La llanura del Olvido','la elección de vidas',6);}
function hdTp(dz){closeDialog();fzPut(FZ.X,HD.Z+dz,0);}
// ---- la entrada, en el Epiro, y la laminilla, con el órfico Arcesilao
function hdSetup(){if(MODE!=='atenas')return;const I=ISLANDS.find(i=>i.id==='dodona');if(!I)return;const c=I.town||I.arrive||{x:I.x,z:I.z},f=findFree(c.x+40,c.z-30,1);egxObj(f[0],f[1],undefined,'hd:entrada','El oráculo de los muertos','junto al río Aqueronte',4);}
function hdOpts(n,add){if(MODE!=='atenas'||n.id!=='orfeotelesta')return;const h=hdz();
  if(!h.lam)add(hdOrfico()?'Arcesilao, ¿qué pasa con el alma después de morir?':'¿Qué enseñan los órficos sobre la muerte?','quiz',()=>{const B=$('dBody');
    if(!hdOrfico()){B.innerHTML='<p>«Eso solo se lo cuento a los iniciados. Primero, la iniciación; luego, el camino del alma».</p><p class="sub">Pídele a Arcesilao la iniciación órfica (es uno de los ritos del calendario de cultos).</p>';renderOpts();return;}
    h.lam=1;save();B.innerHTML='<p>Arcesilao saca de una cajita una lámina de oro, fina como una hoja, doblada muchas veces. «Esto se entierra con los iniciados, junto a la mano o en la boca. Son las instrucciones para el alma».</p><p>Te lee: «A la izquierda de la casa de Hades encontrarás una fuente, y junto a ella un ciprés blanco: no te acerques. Más allá hallarás otra, el agua fresca que mana del lago de Mnemósine, con guardianes delante. Diles: <i>Soy hijo de la Tierra y del Cielo estrellado; tengo sed y me muero: dadme de beber</i>».</p><p>«Y si alguna vez quieres bajar en vida… en el Epiro, junto al río Aqueronte, hay un oráculo de los muertos. Los vivos van allí a hablar con las sombras».</p><p class="sub">Se han encontrado laminillas de oro con textos así en tumbas griegas del sur de Italia, de Tesalia y de Creta. La de Hiponio, en Calabria, es de hacia el 400 a.C.</p>';
    toast('<span class="label">La laminilla de oro</span><br>Instrucciones para el alma. El oráculo de los muertos está en el Epiro, cerca de Dodona.');renderOpts();});}
function hdAct(o){const a=String(o.act),h=hdz();
  if(a==='hd:entrada'){const need=[];if(!h.lam)need.push('la laminilla de oro de los órficos (habla con Arcesilao en Atenas)');if(qLv('eu')<8)need.push('Eusébeia 8 (tienes '+qLv('eu')+')');
    if(need.length)return vmS('Ψ','El oráculo de los muertos','junto al Aqueronte','<p>En la confluencia de dos ríos, junto a la laguna Aquerusia, hay un santuario oscuro. Los que vienen a consultar a los muertos pasan días a oscuras, purificándose y comiendo cosas extrañas antes de bajar a la cámara.</p><p class="sub">Heródoto cuenta que el tirano Periandro de Corinto mandó consultar aquí a su mujer muerta, Melisa. Para bajar necesitas: '+need.join('; ')+'.</p>',[vmBye]);
    return vmS('Ψ','El oráculo de los muertos','junto al Aqueronte','<p>Después de tres días a oscuras, el sacerdote te lleva por un pasillo de piedra que gira y gira, como un laberinto, hasta una puerta de hierro. «Más allá están las sombras. Vuelve, si puedes».</p>',[[_t(10396,'Bajar'),()=>{closeDialog();fzGo('Bajas a oscuras…','El aire se vuelve frío. Se oye agua correr muy abajo.',()=>{hdBuild();if(h.st<1)h.st=0;save();fzPut(FZ.X,HD.Z-58,0);setTimeout(()=>toast('<span class="label">El Hades</span><br>Como Odiseo, empieza por la fosa: los muertos vienen a la sangre del sacrificio.'),800);});},'quiz'],vmBye]);}
  const S=(t,html,b)=>vmS('Ψ',t,'El Hades',html,b||[vmBye]);
  if(a==='hd:fosa'){if(h.st<1){h.st=1;save();}return S('La fosa','<p>Como hizo Odiseo, cavas una fosa de un codo y viertes en ella leche con miel, vino, agua y harina de cebada, y prometes un sacrificio a los muertos. Enseguida se acercan las sombras, pálidas, sin fuerza, como humo: no pueden hablar hasta que beben.</p><p class="sub">En el canto XI de la Odisea, Odiseo no baja: llama a los muertos desde la orilla del mundo. Los griegos contaban también las bajadas de Heracles, de Orfeo y de Teseo.</p>');}
  if(a==='hd:caronte'){if(h.st<1)return S('Caronte','<p>El barquero te mira sin interés. Primero haz la ofrenda en la fosa.</p>');
    return S('Caronte','<p>Un viejo sucio, con una barca de remos, cobra a cada alma un óbolo por cruzar el Aqueronte. Por eso los griegos ponen una moneda en la boca de sus muertos.'+(vmz&&vmz().once&&vmz().once.funA?' Lo viste en el entierro del suegro de Arquipe, en el Cerámico.':'')+'</p><p>Las almas que no tienen moneda, o que nadie enterró, vagan por la orilla.</p>',[['Pagarle un óbolo',()=>{if(state.obols<1){S('Caronte','<p>No tienes ni un óbolo. Caronte ni te mira.</p>');return;}state.obols-=1;updateStats();if(h.st<2){h.st=2;save();}hdTp(14);},'quiz'],vmBye]);}
  if(a==='hd:cerbero'){if(h.st<2)return S('Cerbero','<p>Todavía no has cruzado el río.</p>');
    return S('Cerbero','<p>El perro del Hades, de tres cabezas, deja entrar a todos y no deja salir a nadie. Heracles lo sacó a rastras como último trabajo, y Orfeo lo durmió con su lira.</p>',[['Darle una torta de miel',()=>{if(h.st<3){h.st=3;save();}S('Cerbero','<p>Las tres bocas se pelean por la torta de miel. Pasas mientras come.</p><p class="sub">Los griegos enterraban a sus muertos con tortas de miel, para el perro: Aristófanes las menciona en Lisístrata.</p>',[[_t(3080,'Seguir'),()=>hdTp(44),'quiz']]);},'quiz'],vmBye]);}
  if(a==='hd:jueces'){if(h.st<3)return S('Los tres jueces','<p>Todavía no puedes llegar hasta aquí.</p>');
    return S('Los tres jueces','<p>En una pradera, en el cruce de dos caminos, se sientan tres jueces: Minos, Radamantis y Éaco. Juzgan a las almas desnudas, sin cuerpo, sin ropa, sin riqueza ni fama, para que nada las disfrace. Las justas van a la derecha, hacia las Islas de los Bienaventurados; las injustas, al Tártaro.</p><p>Radamantis te mira: «¿Qué hace buena a un alma?»</p>',[
      ['Haber sido justa, aunque nadie la viera',()=>{if(h.st<4){h.st=4;save();}S('Los tres jueces','<p>Radamantis asiente y te señala el camino de la derecha.</p><p class="sub">Es el mito con el que termina el Gorgias de Platón. Platón dice que lo cuenta como un relato verdadero, aunque Calicles lo tome por un cuento de viejas.</p>',[[_t(3080,'Seguir'),()=>hdTp(100),'quiz']]);},'quiz'],
      ['Haber sido rica y famosa',()=>S('Los tres jueces','<p>«Aquí no queda nada de eso», dice Minos. «Piénsalo otra vez».</p>',[['Volver a responder',()=>hdAct({act:'hd:jueces'})]]),'quiz'],
      ['Haber hecho muchos sacrificios',()=>S('Los tres jueces','<p>«Los dioses no se compran», dice Éaco. «Piénsalo otra vez».</p>',[['Volver a responder',()=>hdAct({act:'hd:jueces'})]]),'quiz']]);}
  if(a==='hd:tartaro')return S('El Tártaro','<p>Muy abajo, tan lejos de la tierra como la tierra del cielo, está el Tártaro. Allí ves a Sísifo empujando una roca cuesta arriba, que siempre vuelve a caer; a Tántalo, con el agua al cuello y fruta sobre la cabeza, que se apartan cuando intenta comer o beber; a Ticio, con dos buitres devorándole el hígado; y a las Danaides, llenando de agua una tinaja agujereada.</p><p class="sub">Sísifo, Tántalo y Ticio aparecen ya en la Odisea. Platón usa la tinaja agujereada como imagen del alma que nunca se sacia.</p>');
  if(a==='hd:leteo'){if(h.st<4)return S('La fuente del ciprés blanco','<p>Todavía no puedes llegar hasta aquí.</p>');
    return S('La fuente del ciprés blanco','<p>Tienes una sed terrible. A la izquierda, junto a un ciprés blanco, mana una fuente. Muchas almas se agachan a beber.</p>',[['Beber de esta fuente',()=>{S('La fuente del ciprés blanco','<p>Bebes… y empiezas a olvidar: tu nombre, tu ciudad, por qué has venido. Es la fuente del Olvido, el Leteo. Sin saber cómo, vuelves a estar junto a los jueces.</p><p class="sub">La laminilla avisaba: no te acerques a la fuente del ciprés blanco.</p>',[['Volver a intentarlo',()=>hdTp(52)]]);},'quiz'],['Recordar la laminilla y no beber',()=>{if(h.st<5){h.st=5;save();}hdTp(126);},'quiz']]);}
  if(a==='hd:mnemosine'){if(h.st<5)return S('El lago de Mnemósine','<p>Todavía no puedes llegar hasta aquí.</p>');
    return S('El lago de Mnemósine','<p>Un lago de agua fresca: el de Mnemósine, la Memoria, la madre de las Musas. Dos guardianes te cierran el paso. «¿Quién eres? ¿De dónde vienes?»</p>',[
      ['«Soy hijo de la Tierra y del Cielo estrellado; tengo sed: dadme de beber»',()=>{if(h.st<6){h.st=6;save();}S('El lago de Mnemósine','<p>Los guardianes se apartan. Bebes del agua de la Memoria y recuerdas todo, incluso lo que no sabías que sabías. '+(state.olyKey?'Ya bebiste una vez de esta agua, con las Musas. ':'')+'</p><p class="sub">Es la respuesta de las laminillas órficas: el alma se reconoce de origen divino, hija del Cielo, y no solo de la Tierra.</p>',[[_t(3080,'Seguir'),()=>hdTp(152),'quiz']]);},'quiz'],
      ['«Soy '+fxNombre()+', un forastero en Atenas»',()=>S('El lago de Mnemósine','<p>Los guardianes no se mueven. Ese nombre es de tu vida de arriba; aquí no significa nada. Recuerda lo que decía la laminilla.</p>',[['Volver a responder',()=>hdAct({act:'hd:mnemosine'})]]),'quiz'],
      ['No decir nada y beber deprisa',()=>S('El lago de Mnemósine','<p>Los guardianes te empujan atrás sin decir palabra.</p>',[['Volver a responder',()=>hdAct({act:'hd:mnemosine'})]]),'quiz']]);}
  if(a==='hd:persefone'){if(h.st<6)return S('Hades y Perséfone','<p>Todavía no puedes llegar hasta aquí.</p>');
    if(h.st<7){h.st=7;save();}return S('Hades y Perséfone','<p>En sus tronos, el rey y la reina de los muertos. Hades, «el invisible», casi no habla. Perséfone, la hija de Deméter, pasa aquí una parte del año porque comió unos granos de granada: cuando vuelve con su madre, la tierra florece.'+(finz().eleu?' Lo viste representado en Eleusis.':'')+'</p><p>Saludas como dicen las laminillas: «Vengo pura de entre los puros, reina de los de abajo». Perséfone sonríe y te deja pasar a los prados.</p>',[['Ir a los prados',()=>hdTp(186),'quiz']]);}
  if(a==='hd:aquiles'){if(h.st<7)return S('Una sombra','<p>Todavía no puedes llegar hasta aquí.</p>');
    return S(_t(846,'Aquiles'),'<p>Una sombra alta, con armas de bronce: Aquiles. Odiseo le dijo que era feliz, porque reinaba entre los muertos. Aquiles le contestó que prefería ser jornalero de un campesino pobre, en la tierra, a reinar sobre todos los muertos.</p><p>«No hay gloria que valga un día de sol», te dice.</p><p class="sub">Es una de las escenas más famosas de la Odisea (canto XI). Para Homero, la vida de los muertos es una sombra triste; los órficos y Platón prometen algo mejor a las almas justas.</p>',[['Seguir hasta la llanura',()=>hdTp(228),'quiz'],vmBye]);}
  if(a==='hd:er'){if(h.st<7)return S('La llanura del Olvido','<p>Todavía no puedes llegar hasta aquí.</p>');
    return S('La llanura del Olvido','<p>Una llanura ardiente y sin árboles. Aquí, según el mito de Er que cuenta Platón, las almas que van a volver a nacer eligen su próxima vida. Una sacerdotisa tira los lotes y extiende en el suelo vidas de todo tipo: de tiranos, de pobres, de atletas, de animales. Y dice: «La responsabilidad es de quien elige; el dios no tiene culpa».</p><p>¿Qué vida eliges?</p>',[
      ['La de un tirano poderoso',()=>hdFin('Eliges la vida del tirano sin mirar bien. Demasiado tarde ves que en ella estaba escrito devorar a sus propios hijos. Es lo que le pasó, en el mito, a la primera alma que eligió.',false),'quiz'],
      ['Una vida sencilla y justa, aunque nadie la conozca',()=>hdFin('Eliges una vida tranquila y justa. En el mito de Er, la última alma en elegir es la de Odiseo: cansado de aventuras, busca mucho rato hasta encontrar la vida de un hombre sencillo que nadie quería, y dice que la habría escogido igual si le hubiera tocado la primera.',true),'quiz'],
      ['La de un atleta famoso',()=>hdFin('Eliges la gloria de los estadios. En el mito, Atalanta elige así, atraída por los honores del atleta. No es mala vida, pero ¿es la mejor?',true),'quiz']]);}}
function hdFin(txt,good){const h=hdz(),first=!h.done;h.done=1;save();if(first){qAdd('eu',5,'Has bajado al Hades y has vuelto.');qAdd('so',2);qAdd('kl',2);state.obols+=10;updateStats();}
  vmS('Ψ','La llanura del Olvido','El Hades','<p>'+txt+'</p><p>Antes de nacer, todas las almas beben del río de la Despreocupación, el Ameles, y olvidan. Er, el soldado del mito, no bebió, y por eso pudo contarlo al despertar en su pira. Tú tampoco bebes.</p><p class="sub">'+(good?'':'Platón quiere decir que hay que aprender a elegir bien, con filosofía, antes de que llegue el momento. ')+(acaz&&acaz().done?'Platón ya te habló de esto en la Academia.':'El mito de Er cierra la República de Platón, que se escribirá dentro de unos años.')+'</p>',[[_t(2982,'Despertar'),()=>{closeDialog();fzGo(_t(7348,'Despiertas…'),'Estás tumbado en la cámara del oráculo, junto al Aqueronte. Ha pasado una noche.',()=>{const e=EGX_OBJS.find(x=>x.act==='hd:entrada');if(e)fzPut(e.x+3,e.z+3,0);
    setTimeout(()=>{if(first)vmS('Ψ','La bajada','El Hades y el Averno','<div class="curio"><span class="label">Has vuelto del Hades</span><p>Has bajado al mundo de los muertos y has vuelto, como Odiseo, Heracles y Orfeo. Recibes diez óbolos.</p><p><b>¿En qué se diferencia del Averno romano?</b> En Roma, la bajada sigue la Eneida: la Sibila, la rama de oro, Dite y Proserpina, Anquises enseñando a las almas que serán los grandes romanos; es una bajada para ver el futuro de Roma. La griega es más antigua y más personal: el óbolo, los jueces, el olvido y la memoria, la elección de la propia vida. Y sus fuentes son otras: Homero, las laminillas órficas y Platón.</p></div>',[vmBye]);},900);});},'quiz']]);}

// ============================================================ MIRAR CON ATENCIÓN: θεωρία (Atenas) · animadversio (Roma)
// Mientras se mantiene Q (o el botón del ojo en pantallas táctiles) aparece una mira que nombra lo que tienes delante;
// con E sale una ficha breve. Al soltar Q se apaga. Sirve para personas, transeúntes, animales, dioses, objetos y edificios.
const AT={on:false,t:0,cur:null,card:false,stable:0,el:null};
// los objetos especiales guardan también su subtítulo, para describirlos
const egxObj0=egxObj;egxObj=function(x,z,y,act,name,sub,r){const o=egxObj0(x,z,y,act,name,sub,r);if(o&&o.data)o.data.sub=sub;return o;};
function atName(){return MODE==='roma'?['Animadversio','poner atención']:['Θεωρία','mirar con atención'];}
function atCSS(){if($('atCSS'))return;const s=document.createElement('style');s.id='atCSS';s.textContent='body.atOn #prompt{display:none!important}'+
 '#atLay{position:fixed;inset:0;pointer-events:none;z-index:40;background:radial-gradient(circle at 50% 50%,transparent 22%,rgba(12,8,4,.55) 75%);opacity:0;transition:opacity .2s}#atLay.on{opacity:1}'+
 '#atLay .ring{position:absolute;left:50%;top:50%;width:46px;height:46px;margin:-23px 0 0 -23px;border:2px solid rgba(240,200,144,.85);border-radius:50%;box-shadow:0 0 12px rgba(240,200,144,.5);transition:transform .15s}#atLay.hit .ring{transform:scale(.7);border-color:#ffe2a8}'+
 '#atLay .nm{position:absolute;left:50%;top:calc(50% + 34px);transform:translateX(-50%);text-align:center;color:#f3e6cf;font:600 16px Georgia,serif;text-shadow:0 1px 4px #000;white-space:nowrap;background:rgba(18,12,8,.62);padding:6px 12px;border-radius:8px}#atLay:not(.hit) .nm{background:none}#atLay .nm small{display:block;font:italic 13px Georgia,serif;color:#e8c37a}#atLay .nm em{display:block;font:12px Georgia,serif;color:#c9b9a2;margin-top:3px;font-style:normal}'+
 '#atLay .tt{position:absolute;left:50%;top:calc(12px + env(safe-area-inset-top,0px));transform:translateX(-50%);font:600 13px Georgia,serif;letter-spacing:.25em;color:#e8b07a;text-transform:uppercase;text-shadow:0 1px 3px #000}'+
 '#atCard{position:fixed;left:50%;bottom:calc(18px + env(safe-area-inset-bottom,0px));transform:translateX(-50%);width:min(560px,92vw);z-index:41;background:rgba(26,20,14,.94);border:1px solid #d9874a;border-radius:12px;padding:12px 16px;color:#f1e8d8;font-family:Alegreya,Georgia,serif;line-height:1.45;animation:atIn .2s ease-out;pointer-events:none}#atCard b{color:#f0c890;font-size:1.08em}#atCard .g{color:#e8b07a;letter-spacing:.12em;font-size:.82em;margin-left:6px}#atCard p{margin:6px 0 0}@keyframes atIn{from{opacity:0;transform:translateX(-50%) translateY(8px)}to{opacity:1;transform:translateX(-50%)}}'+
 '#atBtn{position:fixed;right:calc(16px + env(safe-area-inset-right,0px));bottom:calc(150px + env(safe-area-inset-bottom,0px));width:52px;height:52px;border-radius:50%;border:1px solid #d9874a;background:rgba(26,20,14,.8);color:#f0c890;font-size:22px;z-index:42;display:none;touch-action:none}body.tm #atBtn{display:block}';document.head.appendChild(s);}
function atLay(){let d=$('atLay');if(!d){atCSS();d=document.createElement('div');d.id='atLay';d.innerHTML='<div class="tt"></div><div class="ring"></div><div class="nm"></div>';document.body.appendChild(d);}return d;}
function atFirst(s){if(!s)return '';const m=String(s).replace(/<[^>]+>/g,'').match(/^(.{20,260}?[.!?»])(\s|$)/);return m?m[1]:String(s).replace(/<[^>]+>/g,'').slice(0,240);}
// candidatos: lo que se puede mirar, con su posición, su tamaño aparente y su descripción
function atWY(o,dy){if(o.g&&o.g.getWorldPosition){const v=new THREE.Vector3();o.g.getWorldPosition(v);return [v.x,v.y+dy,v.z];}return [o.x,floorAt(o.x,o.z)+dy,o.z];}
function atCands(){const C=[],ro=MODE==='roma';
  for(const o of npcObjs){if(o.hidden||(o.g&&!o.g.visible))continue;const d=o.data,[wx,wy,wz]=atWY(o,1.4);C.push({obj:o.g,x:wx,y:wy,z:wz,r:0.9,name:d.name,sub:d.title,txt:()=>atFirst(d.summary)+' '+atFirst(d.intro&&d.intro.replace(/^[^.]*\./,''))});}
  for(const o of godObjs){if(!o.shown&&o.g&&!o.g.visible)continue;const d=o.data,[wx,wy,wz]=atWY(o,1.6);C.push({obj:o.g,x:wx,y:wy,z:wz,r:1,name:d.name,sub:d.title,txt:()=>(ro?'Un dios de Roma':'Un dios del Olimpo')+(d.where?', '+d.where:'')+'. Si le hablas, quizá te encargue algo.'});}
  for(const o of EGX_OBJS){if(!isFinite(o.x))continue;const y=(o.y!==undefined?o.y:floorAt(o.x,o.z))+1.2;C.push({obj:o.g||null,x:o.x,y,z:o.z,r:1.1,name:o.data.name,sub:o.data.sub||o.data.role||'',txt:()=>atDescOf(o)||((o.data.sub?o.data.sub.charAt(0).toUpperCase()+o.data.sub.slice(1)+'. ':'')+'Acércate y pulsa E (sin mirar con atención) para interactuar.')});}
  for(const F of FAUNA){const g=F.A&&F.A.g;if(!g||!g.visible)continue;const I=faunaInfo(F.info)||[F.sp,''];C.push({obj:g,x:g.position.x,y:g.position.y+0.5,z:g.position.z,r:0.7,name:I[0],sub:ro?'animal de Roma':'animal de Atenas',txt:()=>atFirst(I[1])+' '+atFirst((I[1]||'').slice(atFirst(I[1]).length).trim())});}
  for(const w of walkers){const g=w.g;if(!g||!g.visible)continue;C.push({obj:g,x:g.position.x,y:g.position.y+1.4,z:g.position.z,r:0.8,name:ro?'Un transeúnte':'Un ateniense de la calle',sub:'gente de la ciudad',txt:()=>ro?'La mayoría de la gente va por la calle solo con túnica: la toga, pesada y cara, se reserva para las ocasiones solemnes y la salutatio. Por la ropa se adivina algo, pero no todo: un liberto rico viste mejor que muchos ciudadanos.':'Ciudadanos, metecos y esclavos visten casi igual: quitón y, si hace fresco, himation. Un autor de la época se quejaba de que en Atenas no se podía pegar a un esclavo ajeno por la calle, porque no se distinguía de un ciudadano.'});}
  if(MOUNT.g&&MOUNT.g.visible&&!MOUNT.riding)C.push({obj:MOUNT.g,x:MOUNT.g.position.x,y:MOUNT.g.position.y+1.4,z:MOUNT.g.position.z,r:1.2,name:typeof horseName==='function'?horseName():'Tu caballo',sub:'tu caballo',txt:()=>'Tu caballo. Recoge las esferas doradas cuando vayas montado para que gane experiencia.'});
  for(const p of PLACES){if(!isFinite(p.x))continue;C.push({x:p.x,y:floorAt(p.x,p.z)+5,z:p.z,r:16,place:1,name:p.name,sub:p.greek||'',txt:()=>atFirst(p.text)+' '+atFirst((p.text||'').slice(atFirst(p.text).length).trim())});}
  return C;}
function atPick(){const cam=camera,P=new THREE.Vector3(),D=new THREE.Vector3();cam.getWorldPosition(P);cam.getWorldDirection(D);let best=null,bs=1e9;
  for(const c of atCands()){const vx=c.x-P.x,vy=c.y-P.y,vz=c.z-P.z,d=Math.hypot(vx,vy,vz);if(d<0.5||d>(c.place?420:60))continue;const cos=(vx*D.x+vy*D.y+vz*D.z)/d;if(cos<0.7)continue;
    const ang=Math.acos(Math.min(1,cos)),thr=Math.atan(c.r/d)+(c.place?0.01:0.035);if(ang>thr)continue;const sc=ang/thr+(c.place?1.2:0)+d/400;if(sc<bs){bs=sc;best=c;}}
  return best;}
function atShow(on){const d=atLay();AT.on=on;document.body.classList.toggle('atOn',!!on);d.classList.toggle('on',on);if(!on){AT.cur=null;atCardHide();d.classList.remove('hit');return;}d.querySelector('.tt').textContent=atName()[0]+' · '+atName()[1];atUpdate();}
function atUpdate(){const d=atLay(),c=atPick(),nm=d.querySelector('.nm');const same=c&&AT.cur&&c.name===AT.cur.name&&c.sub===AT.cur.sub;AT.cur=c;d.classList.toggle('hit',!!c);
  if(!same){AT.stable=0;atCardHide();}
  nm.innerHTML=c?(c.name+(c.sub?'<small>'+c.sub+'</small>':'')+((c.def!==undefined?c.def:(c.def=c.place?'':(()=>{try{return atShort(c.txt());}catch(e){return '';}})()))?'<i class="df">'+c.def+'</i>':'')+'<em>'+(document.body.classList.contains('tm')?'mantén la mirada para saber más':'clic izquierdo o E: saber más')+'</em>'):'<em>'+(typeof regionName==='function'?regionName():'')+'</em>';}
function atCardShow(){const c=AT.cur;if(!c)return;atCardHide();const e=document.createElement('div');e.id='atCard';e.innerHTML='<b>'+c.name+'</b>'+(c.sub?'<span class="g">'+c.sub+'</span>':'')+'<p>'+(c.txt()||'').trim()+'</p>';document.body.appendChild(e);AT.card=true;try{if(aOK())sfxTap();}catch(e){}
  try{const k='at:'+c.name;state.atSeen=state.atSeen||{};if(!state.atSeen[k]){state.atSeen[k]=1;const n=Object.keys(state.atSeen).length;if(n%15===0)qAdd('so',1,'Mirar con atención también es aprender.');save();}}catch(e){}}
function atCardHide(){const e=$('atCard');if(e)e.remove();AT.card=false;}
function atTick(dt){{const b=$('atBtn');if(b){const v=ui==='play'?'':'none';if(b.style.display!==v)b.style.display=v;}}if(!AT.on)return;if(ui!=='play'){atShow(false);return;}AT.t-=dt;if(AT.t<=0){AT.t=0.12;atUpdate();}
  if(document.body.classList.contains('tm')&&AT.cur&&!AT.card){AT.stable+=dt;if(AT.stable>0.8)atCardShow();}}
window.addEventListener('keydown',e=>{if(e.code==='KeyQ'&&!e.repeat&&ui==='play'&&!(e.target&&e.target.tagName==='INPUT')){atShow(true);e.preventDefault();return;}
  if(AT.on&&e.code==='KeyE'){e.stopImmediatePropagation();e.preventDefault();if(AT.cur)atCardShow();}},true);
window.addEventListener('keyup',e=>{if(e.code==='KeyQ'&&AT.on)atShow(false);},true);
window.addEventListener('blur',()=>{if(AT.on)atShow(false);});
(function(){atCSS();const b=document.createElement('button');b.id='atBtn';b.type='button';b.setAttribute('aria-label','Mirar con atención');b.title='Mantén pulsado para mirar con atención';b.textContent='👁';
  const on=e=>{e.preventDefault();e.stopPropagation();if(ui==='play')atShow(true);},off=e=>{e.preventDefault();e.stopPropagation();if(AT.on)atShow(false);};
  b.addEventListener('touchstart',on,{passive:false});b.addEventListener('touchend',off,{passive:false});b.addEventListener('touchcancel',off,{passive:false});b.addEventListener('mousedown',on);b.addEventListener('mouseup',off);document.body.appendChild(b);})();
// ============================================================ ROMA: antes de bajar, enterrar a Miseno (Eneida VI 149-235)
const infBuild0=infBuild;infBuild=function(){const was=FZ.built.inf;infBuild0();if(!was){const X=FZ.X,Z=6000,Y=FZ.Y;
  const b=grp(X-7,Y,Z-44,0);box(1.6,0.4,2.4,lam('#5a4a3a'),0,0.2,0,b);const m=makePerson({noVary:true,chiton:'#c8bca0',hair:'#3a2a1a'});m.rotation.x=-Math.PI/2;m.position.set(0,0.55,-0.9);b.add(m);
  egxObj(X-7,Z-44,Y,'fi:miseno','Miseno','un compañero sin enterrar',3.5);}};
const infAct0=infAct;infAct=function(o){const f=finz(),a=o.act;
  if(a==='fi:miseno'){if(f.misen)return vmS('⚱','El túmulo de Miseno','en el cabo que lleva su nombre','<p>Bajo el túmulo descansa Miseno, con sus armas, su remo y su trompeta. El cabo junto a Cumas se llama, desde entonces y para siempre, Miseno.</p>',[vmBye]);
    const knew=typeof vmz==='function'&&vmz().once&&vmz().once.funR;
    return vmS('⚱','Miseno','un compañero sin enterrar','<p>En la playa yace el cuerpo de Miseno, el trompetero de Eneas, ahogado por Tritón por haberse atrevido a desafiar a los dioses con su trompeta. La Sibila es clara: «Uno de los tuyos está sin sepultura y mancha a todos con su muerte. Antes de bajar, entiérralo como se debe» (VI 149-155).</p><p>'+(knew?'Recuerdas el entierro que viste en la Vía Apia: sabes lo que hay que hacer.':'Hay que hacerlo todo según el rito.')+'</p>',[['Cumplir los ritos',()=>{f.misen=1;save();qAdd('eu',1,'Has dado sepultura a un muerto.');
      vmS('⚱','Miseno','un compañero sin enterrar','<p>Cortáis pinos, encinas y fresnos para una pira enorme, con cipreses oscuros delante (VI 179-182, 215-216). Mientras talas, dos palomas, las aves de Venus, te guían por el bosque hacia el árbol de la rama de oro. Laváis y ungís el cuerpo, lo ponéis sobre la pira con su ropa de púrpura y la encendéis con la cara vuelta. Al final se riegan las cenizas con vino, se recogen los huesos en una urna de bronce y uno de los compañeros os purifica a todos rociándoos con agua y un ramo de olivo. Sobre la tumba, un gran túmulo, con el remo y la trompeta de Miseno.</p><p class="sub">Para los griegos y los romanos, quedar sin sepultura era lo peor que podía pasarle a alguien: su sombra no podía cruzar el río y vagaba cien años por la orilla. Por eso Antígona desafía al rey para enterrar a su hermano, y por eso más adelante Palinuro, el piloto de Eneas, le suplicará en la orilla que lo entierre.</p>',[['Seguir hacia el Averno',closeDialog,'quiz']]);},'quiz'],vmBye]);}
  if(a==='fi:caronte'&&!f.misen){const one=casaOpen('Σ','Caronte','el barquero');$('dBody').innerHTML='<p>La Sibila te detiene antes de llegar a la orilla: «Aún no. Primero entierra a Miseno, que yace en la playa: quien deja a un compañero sin sepultura no puede presentarse ante los muertos» (VI 149-155).</p><p class="sub">Busca su cuerpo cerca de la entrada del bosque.</p>';one(_t(2775,'Cerrar'),closeDialog);return;}
  if(a==='fi:caronte'&&f.misen&&!f.palin){f.palin=1;save();setTimeout(()=>toast('<span class="label">Palinuro</span><br>Entre las almas sin enterrar, el piloto de Eneas te ruega que busquen su cuerpo. La Sibila le promete que un cabo llevará su nombre: el cabo Palinuro (VI 337-383).'),1200);}
  return infAct0(o);};

// ============================================================ EL ANFITEATRO FLAVIO POR DENTRO: muros, deambulatorios, vomitoria y el acceso del espectador
// 1) Sobre los túneles de los ejes mayores el anfiteatro seguía cerrado: muro interior y gradas por encima del túnel.
// 2) Techos de los deambulatorios en cada piso, para que por los arcos no se vea ni el cielo ni la parte de atrás de las gradas.
// 3) Vomitoria en la cavea y el recorrido real del espectador: tésera (arco, sector, grada, asiento), deambulatorio, escalera y vomitorio.
const COLX={A:94,B:78,gy:2,ai:41.5,bi:24,ST:30,seats:[]};
function colTier(j){return 4.2+(40-4.2)*(j+1)/COLX.ST;}
const romaColosseum0=romaColosseum;romaColosseum=function(){romaColosseum0();try{colPlus();}catch(e){console.warn('colPlus',e);}};
function colPlus(){const C=ROMA.col,{A,B,gy,ai,bi,ST}=COLX,ao=A-7,bo=B-7,tunnel=u=>Math.abs(Math.sin(u*TAU))<0.13,j0=3;
  // muro interior y gradas por encima de los túneles de los ejes
  ringMesh(ringGeo(2,96,(u,k)=>{const t=u*TAU;return[ao*Math.cos(t),k?40:7.8,bo*Math.sin(t)];},u=>!tunnel(u),()=>'#bfb39a'),C.x,gy,C.z);
  ringMesh(ringGeo(2,240,(u,k)=>{const t=u*TAU;return[ao*Math.cos(t),k?7.8:0,bo*Math.sin(t)];},u=>!tunnel(u)||Math.abs(Math.sin(u*TAU))*bo<3.6,()=>'#bfb39a'),C.x,gy,C.z);   // a los lados del túnel, también abajo
  const K=1+2*(ST-j0),P=(u,k)=>{const t=u*TAU;let s,y;if(k===0){s=j0/ST;y=7.8;}else{const j=j0+Math.floor((k-1)/2),e=(k-1)%2;s=(j+e)/ST;y=colTier(j);}return[lerp(ai,ao,s)*Math.cos(t),y,lerp(bi,bo,s)*Math.sin(t)];};
  ringMesh(ringGeo(K,128,P,u=>!tunnel(u),k=>k%2?'#e6dccb':'#bfb39b'),C.x,gy,C.z);
  CAVEAS.push({k:'c',x:C.x,z:C.z,a:0,gy,ai,bi,ao,bo,ST,s0:j0/ST,rr:ao+1});   // las gradas se pisan: se sube y se baja por ellas
  // techos de los deambulatorios (bóvedas vistas desde abajo) y cubierta del último piso
  const ann=(y,r1a,r1b,r2a,r2b,col)=>{const s=new THREE.Shape();s.absellipse(0,0,r1a,r1b,0,TAU,false,0);const h=new THREE.Path();h.absellipse(0,0,r2a,r2b,0,TAU,true,0);s.holes.push(h);
    const g=new THREE.ShapeGeometry(s,96);g.rotateX(-Math.PI/2);const m=new THREE.Mesh(g,new THREE.MeshLambertMaterial({color:col,side:THREE.DoubleSide}));m.position.set(C.x,gy+y,C.z);m.receiveShadow=true;scene.add(m);return m;};
  for(const y of[10.3,22.1,33.9])ann(y,A-1.4,B-1.4,ao,bo,'#a89c84');ann(46,A-0.6,B-0.6,ao-1,bo-1,'#b8ab90');
  // vomitoria: bocas oscuras en la cavea, en la parte alta de cada meniano
  const dark=lam('#1a1410'),lin=lam('#d8ccb4');
  for(const[j,n]of[[9,24],[19,32],[27,36]]){const s=(j+1)/ST,a=lerp(ai,ao,s),b=lerp(bi,bo,s),y=gy+colTier(j);
    for(let i=0;i<n;i++){const t=(i+0.5)/n*TAU;if(Math.abs(Math.sin(t))<0.2&&j<9)continue;const x=C.x+a*Math.cos(t),z=C.z+b*Math.sin(t),g=grp(x,y,z,Math.atan2(-Math.cos(t),-Math.sin(t)));
      box(2.2,2.6,0.6,dark,0,1.3,0.1,g);box(2.8,0.4,0.8,lin,0,2.8,0.1,g);try{atReg(x,z,y,'vomitorium',1.4);}catch(e){}}}
  // las cuatro entradas del público, con su número de arco
  COLX.ent=[];[[0.33,'XXIV'],[0.67,'LIII'],[0.17,'IX'],[0.83,'LXVII']].forEach(([f,num])=>{const t=f*TAU,x=C.x+(A+3)*Math.cos(t),z=C.z+(B+3)*Math.sin(t);COLX.ent.push({t,num,x,z});});}
function colSetup(){if(MODE!=='roma'||!COLX.ent)return;COLX.seats.length=0;for(const e of COLX.ent)egxObj(e.x,e.z,undefined,'col:entrada','Arco '+e.num,'entrada del público',4);}
// ---- el acceso del espectador
function colz(){if(!state.colos||typeof state.colos!=='object')state.colos={};return state.colos;}
function colSeat(){const fem=pjFem(),ciu=fxz().ciu;return fem?{m:'el meniano más alto, en las gradas de madera',j:28,who:'Las mujeres, por una ley de Augusto, se sientan arriba del todo, en las gradas de madera, lejos de los hombres; solo las Vestales tienen sitio de honor abajo.'}
  :ciu?{m:'el segundo meniano, entre los ciudadanos con toga',j:14,who:'Augusto ordenó los asientos por clases: los senadores en el podio, junto a la arena; los caballeros en las catorce primeras filas; luego los ciudadanos, que deben llevar toga; arriba, los pobres, los esclavos y las mujeres.'}
  :{m:'la parte alta, con la plebe y los forasteros',j:24,who:'Como no eres ciudadano, te toca arriba, con la plebe, los extranjeros y los esclavos. Los senadores se sientan en el podio y los caballeros en las catorce primeras filas.'};}
function colAct(o){const e=COLX.ent&&COLX.ent.reduce((b,x)=>!b||Math.hypot(x.x-o.x,x.z-o.z)<Math.hypot(b.x-o.x,b.z-o.z)?x:b,null);if(o.act==='col:salir')return colSalir();if(!e)return;
  const S=colSeat(),cu=['I','II','III','IV','V','VI','VII','VIII','IX','X','XI','XII'][Math.floor(e.t/TAU*12)%12],gr=S.j+1,loc=1+Math.floor((e.t*37)%40);
  vmS('🎟','Arco '+e.num,'entrada del público','<p>Sobre cada arco de la planta baja hay un número grabado: del I al LXXVI. (Los cuatro de los ejes no tienen número: son las entradas de honor y de los gladiadores.) Un empleado mira tu tésera, una ficha de hueso o de barro que te dio tu patrono, y te indica el camino.</p><div class="curio"><span class="label">Tu tésera</span><p><b>ARCVS '+e.num+' · CVNEVS '+cu+' · GRADVS '+gr+' · LOCVS '+loc+'</b></p><p class="sub">Arco '+e.num+', sector '+cu+', grada '+gr+', asiento '+loc+': '+S.m+'.</p></div><p class="sub">'+S.who+' La entrada era gratuita: las téseras las repartían los organizadores de los juegos.</p>',
    [['Entrar y buscar tu asiento',()=>colEntrar(e,S),'quiz'],vmBye]);}
function colEntrar(e,S){const C=ROMA.col,{ai,bi,ST}=COLX,ao=COLX.A-7,bo=COLX.B-7,s=(S.j+0.5)/ST,t=e.t,x=C.x+lerp(ai,ao,s)*Math.cos(t),z=C.z+lerp(bi,bo,s)*Math.sin(t),y=COLX.gy+colTier(S.j);
  const k='s'+S.j+'_'+e.num;if(!COLX.seats.includes(k)){COLX.seats.push(k);egxObj(x+0.2,z+0.2,y,'col:salir','Salir del anfiteatro','por el vomitorio',2.2);}
  COLX.back={x:e.x,z:e.z};closeDialog();
  vmS('🏟','El deambulatorio','dentro del anfiteatro','<p>Pasas bajo el arco '+e.num+' y entras en un pasillo abovedado que da la vuelta entera al edificio, lleno de gente, de vendedores de comida y de cojines de alquiler. Sigues los números pintados en las paredes hasta tu escalera, subes los escalones de travertino y llegas a un pasillo más estrecho que acaba en una boca de luz: el <b>vomitorio</b>.</p><p class="sub">Se llaman vomitoria porque por ellos el anfiteatro «vomitaba» a la gente: con ochenta entradas y decenas de escaleras, cincuenta mil espectadores podían salir en pocos minutos.</p>',
    [['Salir a la cavea',()=>{closeDialog();fzPut(x,z,Math.atan2(-(C.x-x),-(C.z-z)));const st=colz();if(!st.vis){st.vis=1;save();qAdd('so',1,'Ya sabes cómo se llena un anfiteatro.');}
      setTimeout(()=>toast('<span class="label">La cavea</span><br>Cincuenta mil personas. Arriba, los marineros de la flota de Miseno tensan el toldo, el velario. A veces se rocía al público con agua perfumada de azafrán.'),500);},'quiz']]);}
function colSalir(){vmS('🏟','Salir','por el vomitorio','<p>Vuelves al vomitorio, bajas la escalera y sales por el mismo arco por el que entraste.</p>',[['Salir',()=>{closeDialog();const b=COLX.back;if(b)fzPut(b.x,b.z);},'quiz'],vmBye]);}

// ============================================================ MODO FOTO: oculta la interfaz, zoom y foto con pie (lugar, coordenadas y día) para guardar
const PH={on:false,fov:null,cap:true,url:null,blob:null};
function phCSS(){if($('phCSS'))return;const s=document.createElement('style');s.id='phCSS';s.textContent=
 'body.photo #hud,body.photo #atBtn,body.photo #tbtns,body.photo #keys,body.photo #toast,body.photo #atLay{display:none!important}'+
 '#phUI{position:fixed;left:50%;bottom:calc(14px + env(safe-area-inset-bottom,0px));transform:translateX(-50%);z-index:60;display:flex;gap:8px;align-items:center;flex-wrap:wrap;justify-content:center;background:rgba(20,15,10,.72);border:1px solid #d9874a;border-radius:12px;padding:8px 12px;color:#f1e8d8;font:14px Alegreya,Georgia,serif;max-width:94vw}'+
 '#phUI button,#phPrev button{font:inherit;padding:7px 12px;border-radius:8px;border:1px solid #d9874a;background:rgba(217,135,74,.18);color:#f1e8d8;cursor:pointer}#phUI button.main,#phPrev button.main{background:#d9874a;color:#1a120c}#phUI .h{opacity:.8;font-size:12px}'+
 '#phFlash{position:fixed;inset:0;background:#fff;z-index:61;pointer-events:none;animation:phF .35s ease-out forwards}@keyframes phF{from{opacity:.85}to{opacity:0}}'+
 '#phPrev{position:fixed;inset:0;z-index:62;background:rgba(10,8,6,.82);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;padding:16px}#phPrev img{max-width:92vw;max-height:72vh;border:2px solid #d9874a;border-radius:8px;box-shadow:0 8px 30px #000}#phPrev .row{display:flex;gap:10px;flex-wrap:wrap;justify-content:center}';document.head.appendChild(s);}
function phToggle(on){on=on===undefined?!PH.on:on;if(on&&ui!=='play')return;phCSS();PH.on=on;document.body.classList.toggle('photo',on);
  if(on){PH.fov=camera.fov;let u=$('phUI');if(!u){u=document.createElement('div');u.id='phUI';document.body.appendChild(u);}
    u.innerHTML=_t(10397,'<b>📷 Modo foto</b><button class="main" id="phShot">Hacer foto</button><button id="phCap"></button><button id="phZi">＋</button><button id="phZo">－</button><button id="phX">Salir</button><span class="h">')+(document.body.classList.contains('tm')?'':_t(10398,'Clic o Espacio: foto · rueda o +/−: zoom · P o Esc: salir'))+'</span>';
    $('phShot').onclick=e=>{e.stopPropagation();phShot();};$('phCap').onclick=e=>{e.stopPropagation();PH.cap=!PH.cap;phCapLbl();};$('phZi').onclick=e=>{e.stopPropagation();phZoom(-6);};$('phZo').onclick=e=>{e.stopPropagation();phZoom(6);};$('phX').onclick=e=>{e.stopPropagation();phToggle(false);};phCapLbl();}
  else{const u=$('phUI');if(u)u.remove();PH.z=null;}}
function phCapLbl(){const b=$('phCap');if(b)b.textContent=_t(10399,'Pie de foto: ')+(PH.cap?'sí':'no');}
function phZoom(d){PH.z=clamp((PH.z||camera.fov)+d,15,90);}
function phCaption(){const ro=MODE==='roma',p=player;let dia='';try{const c=calNow();dia=_t(2,'día ')+(state.day||1)+' · '+c.mes+' · '+(typeof horaRomana==='function'&&ro?horaRomana(clock.h):'~'+Math.floor(clock.h)+' h');}catch(e){}
  return ['Nóstos · '+(ro?_t(10270,'Roma, 80 d.C.'):_t(10271,'Atenas, 386 a.C.'))+' · '+(typeof regionName==='function'?regionName():''),'x '+Math.round(p.x)+' · z '+Math.round(p.z)+_t(10400,' · altura ')+p.feet.toFixed(1)+' · '+dia];}
function phShot(){try{if(!(typeof gfxRender==='function'&&gfxRender()))renderer.render(scene,camera);const src=renderer.domElement,W=src.width,H=src.height,c=document.createElement('canvas');c.width=W;c.height=H;const x=c.getContext('2d');x.drawImage(src,0,0);
    if(PH.cap){const L=phCaption(),fs=Math.max(14,Math.round(H/48));x.font='600 '+fs+'px Georgia, serif';const w=Math.max(...L.map(t=>x.measureText(t).width))+fs*1.4,h=fs*1.45*L.length+fs*0.8;
      x.fillStyle='rgba(20,15,10,.7)';x.fillRect(fs*0.6,H-h-fs*0.6,w,h);x.fillStyle='#f3e6cf';L.forEach((t,i)=>{x.font=(i?'':'600 ')+Math.round(fs*(i?0.82:1))+'px Georgia, serif';x.fillText(t,fs*1.3,H-h-fs*0.6+fs*1.25+i*fs*1.45);});}
    const f=document.createElement('div');f.id='phFlash';document.body.appendChild(f);setTimeout(()=>f.remove(),400);try{if(aOK())sfxTap();}catch(e){}
    c.toBlob(b=>{if(!b)return;PH.blob=b;if(PH.url)URL.revokeObjectURL(PH.url);PH.url=URL.createObjectURL(b);phPreview();},'image/png');}
  catch(e){toast(_t(10401,'No se ha podido hacer la foto: ')+e.message);}}
function phName(){const d=new Date(),z=n=>String(n).padStart(2,'0');return 'nostos_'+(MODE==='roma'?'roma':'atenas')+'_'+d.getFullYear()+z(d.getMonth()+1)+z(d.getDate())+'_'+z(d.getHours())+z(d.getMinutes())+z(d.getSeconds())+'.png';}
function phPreview(){let p=$('phPrev');if(p)p.remove();p=document.createElement('div');p.id='phPrev';p.innerHTML=_t(10402,'<img alt="Tu foto"><div class="row"><button class="main" id="phSave">Guardar la foto</button><button id="phAgain">Hacer otra</button><button id="phClose">Salir del modo foto</button></div>');document.body.appendChild(p);p.querySelector('img').src=PH.url;
  $('phSave').onclick=async()=>{const name=phName();try{const dl=window.claude&&window.claude.use?await window.claude.use('downloads'):null;if(dl){await dl.save({filename:name,data:PH.blob});p.remove();toast(_t(10403,'<span class="label">Foto guardada</span><br>')+name);return;}}catch(e){if(e&&e.code==='declined'){return;}}
    try{const a=document.createElement('a');a.href=PH.url;a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>a.remove(),300);p.remove();toast(_t(10403,'<span class="label">Foto guardada</span><br>')+name);}catch(e){toast(_t(10404,'No se ha podido guardar: mantén pulsada la imagen para guardarla.'));}};
  $('phAgain').onclick=()=>p.remove();$('phClose').onclick=()=>{p.remove();phToggle(false);};}
window.addEventListener('keydown',e=>{if(e.target&&e.target.tagName==='INPUT')return;
  if((e.code==='KeyP'||e.code==='F2')&&!e.repeat&&(ui==='play'||PH.on)){if($('phPrev'))return;e.preventDefault();e.stopImmediatePropagation();phToggle();return;}
  if(!PH.on)return;if(e.code==='Escape'){e.preventDefault();e.stopImmediatePropagation();if($('phPrev'))$('phPrev').remove();else phToggle(false);return;}
  if(e.code==='Space'&&!$('phPrev')){e.preventDefault();e.stopImmediatePropagation();phShot();}if(e.code==='Equal'||e.code==='NumpadAdd')phZoom(-5);if(e.code==='Minus'||e.code==='NumpadSubtract')phZoom(5);},true);
window.addEventListener('wheel',e=>{if(PH.on&&!$('phPrev')){phZoom(e.deltaY>0?3:-3);}},{passive:true});
