function hbIcon(k){if(k==='amuleto'&&MODE!=='roma')return state&&state.fest&&state.fest.orficos?'<rect x="6" y="4" width="12" height="16" rx="1"/><path d="M8.5 8h7M8.5 11h7M8.5 14h5M8.5 17h3"/>':'<path d="M5 20C9 15 13 9 19 4"/><path d="M9 15l-3-1M11 12.5l3 1.5M13 10l-3-2M15.5 7.5l2.5 1"/><circle cx="7" cy="12.5" r="1"/><circle cx="15" cy="14.5" r="1"/>';if(k==='amuleto')return '<circle cx="12" cy="5" r="2"/><path d="M12 7v6M8 9.5l4 2 4-2M12 13l-3 7M12 13l3 7"/><path d="M15.5 9l2-3"/>';if(k==='bolsa'&&MODE!=='roma')return HB_SVG.bolsa+'<circle cx="12" cy="14" r="1.8"/>';return HB_SVG[k];}
function hbAmuletoHas(){if(MODE==='roma'){try{return cz().st>=3||cultz().n>0;}catch(e){return false;}}return !!(hbz().got.espino||(state.fest&&state.fest.orficos));}
function hbAmuletoName(){if(MODE==='roma')return 'Figurillas de los Lares';return state.fest&&state.fest.orficos?'Laminilla de oro (órfica)':'Ramita de espino';}
function hbGive(k,why){const h=hbz();if(h.got[k])return;h.got[k]=1;save();const it=HB_ITEMS.find(i=>i.k===k);hbRender(true);try{sfxCoin();}catch(e){}
  toast('<span class="label">Nuevo objeto · '+(it?it.n():k)+'</span><br>'+why+'<br><span class="sub">Está en tu barra de objetos: elígelo con la rueda o las teclas 1-9 y úsalo con R.</span>');}
