function hbRender(force){hbCSS();let b=$('hbar');if(!b){b=document.createElement('div');b.id='hbar';document.body.appendChild(b);const n=document.createElement('div');n.id='hbName';n.style.opacity=0;document.body.appendChild(n);
    b.addEventListener('click',e=>{const s=e.target.closest('.s');if(!s)return;e.stopPropagation();const i=+s.dataset.i;if(HBAR.sel===i&&document.body.classList.contains('tm'))hbUse();else hbSelect(i);});
    b.addEventListener('contextmenu',e=>{e.preventDefault();const s=e.target.closest('.s');if(s){hbSelect(+s.dataset.i);hbUse();}});}
  const h=hbz(),key=hbSlots().map(it=>(it.has()?1:0)+''+(it.on&&it.on()?1:0)).join('')+HBAR.sel+h.odre;if(!force&&key===HBAR.last)return;HBAR.last=key;
  b.innerHTML=hbSlots().map((it,i)=>{const has=it.has();return '<div class="s'+(has?'':' off')+(i===HBAR.sel?' sel':'')+(has&&it.on&&it.on()?' on':'')+'" data-i="'+i+'" title="'+(has?it.n():'Aún no lo tienes: '+it.how)+'"><span class="k">'+(i+1)+'</span><svg viewBox="0 0 24 24">'+hbIcon(it.k)+'</svg>'+(it.k==='odre'&&has?'<span class="c">'+h.odre+'</span>':'')+'</div>';}).join('');}
const HBAR={sel:0,last:'',nt:0};
function hbSelect(i){HBAR.sel=(i+9)%9;hbz().sel=HBAR.sel;hbRender(true);const it=hbSlots()[HBAR.sel],n=$('hbName');if(n){n.textContent=it.has()?it.n():'Vacío · '+it.how;n.style.opacity=1;HBAR.nt=2.2;}try{if(aOK())sfxTap();}catch(e){}}
function hbUse(){if(ui!=='play')return;const it=hbSlots()[HBAR.sel];if(!it.has()){toast('<span class="label">Casilla vacía</span><br>'+it.how);return;}it.use();setTimeout(()=>hbRender(true),60);}
function hbTick(dt){if(!state)return;const b=$('hbar');if(b)b.style.display=ui==='play'&&$('hud')&&!$('hud').hidden?'':'none';if(HBAR.nt>0){HBAR.nt-=dt;if(HBAR.nt<=0&&$('hbName'))$('hbName').style.opacity=0;}
  hbRender(false);const h=hbz();
  // conseguir objetos al pasar por los sitios
  if(!h.got.odre||!h.got.rollo){let I=null;try{I=islandOf(player.x);}catch(e){}if(I){if(!h.got.odre)hbGive('odre','«Toma, que el camino es largo y seco», te dice el cochero, y te da un odre viejo de piel de cabra. Se rellena en fuentes y ríos.');if(!h.got.rollo&&I.sea)hbGive('rollo',MODE==='roma'?'El capitán te regala un itinerario viejo: un rollo con los puertos, las calzadas y las distancias en millas. Ábrelo para ver el mapa.':'El capitán te regala un periplo viejo: un rollo con los puertos y las jornadas de navegación. Ábrelo para ver el mapa.');}}
  if(!h.got.strigil&&HB_GYM()){hbGive('strigil',MODE==='roma'?'En la entrada de las termas compras un estrígilo de bronce y un frasquito de aceite: el kit de cualquier romano que va a los baños.':'Un atleta de la palestra te regala un estrígilo viejo y un aríbalo de aceite: «Aquí nadie se lava sin rascarse antes el polvo y el sudor».');}
  if(MODE!=='roma'&&!h.got.espino&&!(state.fest&&state.fest.orficos)){try{if(calNow().mes==='Antesterión')hbGive('espino','Una vecina te da una ramita de espino: «Mastícala en las Antesterias, que salen las Keres». Úsala para los ritos de los espíritus.');}catch(e){}}}
let HB_GYMP=null;function HB_GYM(){if(!HB_GYMP){HB_GYMP=[];for(const id of(MODE==='roma'?['ro_termas']:['palestra','academia','liceo'])){const p=PLACES.find(q=>q.id===id);if(p)HB_GYMP.push([p.x,p.z]);}}return HB_GYMP.some(p=>Math.hypot(p[0]-player.x,p[1]-player.z)<45);}
function hbSetup(){HBAR.sel=hbz().sel||0;hbRender(true);}
// ---- usos
function hbBolsa(){const n=state.obols||0;let t;if(MODE==='roma'){const d=Math.floor(n/4),s=n%4;t='Llevas <b>'+n+' sestercios</b>'+(d?': '+d+' denario'+(d>1?'s':'')+' de plata'+(s?' y '+s+' sestercio'+(s>1?'s':'')+' de latón':''):'')+'.<br><span class="sub">Un denario vale cuatro sestercios, y un sestercio, cuatro ases de cobre. Un legionario cobra unos tres sestercios al día; una hogaza de pan cuesta medio as o un as.</span>';}
  else{const d=Math.floor(n/6),o=n%6;t='Llevas <b>'+n+' óbolos</b>'+(d?': '+d+' dracma'+(d>1?'s':'')+(o?' y '+o+' óbolo'+(o>1?'s':''):''):'')+'.<br><span class="sub">Seis óbolos hacen una dracma de plata, con la lechuza de Atenea. Muchos atenienses llevan las monedas pequeñas en la boca, a falta de bolsillos; un jornal es de una dracma.</span>';}
  toast('<span class="label">Tu bolsa</span><br>'+t);}
function hbNearWater(){try{if(typeof riverWater==='function'&&riverWater(player.x,player.z)!==null)return true;}catch(e){}try{const near=PLACES.some(p=>/fuente|fons|krene|clepsidra|acueducto|aqua/i.test(p.id+' '+p.name)&&Math.hypot(p.x-player.x,p.z-player.z)<30);if(near)return true;}catch(e){}return terrainH(player.x,player.z)<0.6;}
function hbOdre(){const h=hbz();if(hbNearWater()&&h.odre<3){h.odre=3;save();toast('<span class="label">Odre lleno</span><br>'+(MODE==='roma'?'Lo llenas de agua. Los soldados le añaden un chorro de vinagre: la posca, que quita la sed y, sin saberlo, mata algunos gérmenes.':'Lo llenas de agua fresca. En Grecia el agua buena es un tesoro: cada ciudad cuida sus fuentes, y Atenas tiene la de las Nueve Bocas.'));return;}
  if(h.odre<=0){toast('<span class="label">El odre está vacío</span><br>Rellénalo junto a un río, una fuente o la orilla del mar (¡aunque el agua del mar no se bebe!).');return;}
  h.odre--;const d=state.day||1;let extra='';try{const f=farmz();if(typeof f.en==='number'){const m=fMax();if(f.en<m){f.en=Math.min(m,f.en+8);extra=' Recuperas fuerzas para el trabajo de la granja ('+f.en+'/'+m+').';}}}catch(e){}save();
  toast('<span class="label">Bebes del odre</span><br>Un trago tibio que sabe a cuero.'+extra+' <span class="sub">Quedan '+h.odre+' tragos.</span>');}
function hbStrigil(){const h=hbz(),d=state.day||1;if(!HB_GYM()){toast('<span class="label">Estrígilo</span><br>'+(MODE==='roma'?'Esto se usa en las termas, después del ejercicio y antes del baño caliente.':'Esto se usa en la palestra, después del ejercicio.'));return;}
  if(h.str===d){toast('Hoy ya te has untado y rascado. Mañana más.');return;}h.str=d;qAdd('ar',1);save();
  toast('<span class="label">Aceite y estrígilo</span><br>Te untas de aceite, haces ejercicio y luego te rascas con la hoja curva el aceite, el sudor y el polvo. '+(MODE==='roma'?'En las termas, lo que se raspa del cuerpo de los gladiadores famosos se vende en frasquitos.':'Los atletas lo hacen igual: en la palestra hay un cuarto solo para el aceite, el elaiothésion.'));}
function hbTablilla(){const L=(state.lessons||[]).filter(id=>LESSONS[id]);const obj=$('objective')?$('objective').innerHTML:'';
  const notes=L.length?L.map(id=>'<details><summary><b>'+LESSONS[id].title+'</b> <span class="sub">· '+(LESSONS[id].cat||'')+'</span></summary><p class="sub">'+LESSONS[id].summary+'</p></details>').join(''):'<p class="sub">Aún no has tomado apuntes: aprende una lección con un maestro y aparecerá aquí.</p>';
  vmS(MODE==='roma'?'✎':'✎',MODE==='roma'?'Tu tablilla de cera':'Tu pínax de cera','objetivos y apuntes','<div class="curio"><span class="label">Lo que tienes que hacer</span><p>'+(obj||'Explora la ciudad.')+'</p></div><p><span class="label">Apuntes · '+L.length+' lecciones</span></p>'+notes+
    '<p class="sub">Las tablillas eran dos o más tablas de madera unidas, con un hueco relleno de cera negra. Se escribía con un punzón de hueso o metal, el stilus, y con el otro extremo, plano, se borraba alisando la cera. En clase te ayudan: con tus apuntes descartas una respuesta falsa.</p>',[['Abrir el diario completo',()=>{closeDialog();openJournal();},'quiz'],vmBye]);}
// la tablilla en clase: el primer maestro te la da; luego, en cada pregunta, tus apuntes tachan una respuesta falsa (si tu Sophía aún no lo hace)
const startQuiz0=startQuiz;startQuiz=function(){if(!hbz().got.tablilla)hbGive('tablilla',MODE==='roma'?'El maestro te tiende unas tablillas de cera y un estilo: «Para tus apuntes. Quien no escribe, olvida».':'El maestro te tiende un pínax de cera y un punzón: «Para tus apuntes. Quien no escribe, olvida».');
  startQuiz0();try{if(qLv('so')>=4)return;const n=dlg.n,q=n.quiz,o=$('dOpts'),bs=[...o.querySelectorAll('button')].slice(0,q.a.length);const w=bs.find(b=>b.textContent.replace(/^\d+/,'').trim()!==q.a[0].replace(/<[^>]+>/g,'').trim());
    if(w){const sp=w.querySelector('span:last-child');if(sp){sp.style.textDecoration='line-through';sp.style.opacity='.45';}w.disabled=true;$('dBody').innerHTML+='<p class="sub">Miras tus apuntes en la tablilla y tachas una respuesta que sabes falsa. Es la ayuda de llevar apuntes; cuando tu '+(MODE==='roma'?'Sapientia':'Sophía')+' llegue al nivel 4, ya no la necesitarás.</p>';}}catch(e){}};
window.addEventListener('wheel',e=>{if(ui!=='play'||(typeof PH!=='undefined'&&PH.on)||!state)return;if(Math.abs(e.deltaY)<4)return;hbSelect(HBAR.sel+(e.deltaY>0?1:-1));},{passive:true});
window.addEventListener('keydown',e=>{if(ui!=='play'||!state||(e.target&&e.target.tagName==='INPUT'))return;const m=/^Digit([1-9])$/.exec(e.code);if(m){hbSelect(+m[1]-1);return;}if(e.code==='KeyR'&&!e.repeat)hbUse();});
/* el clic derecho es ahora para mirar con atención; los objetos se usan con R */

// ============================================================ LOS ESPÍRITUS: Lares, Genio, Manes y Lemures (Roma); Agathós Daímon, Hécate y las Keres (Atenas)
// Se presenta lo que creían: las «presencias» solo se ven de noche y con la antorcha, en los meses en que se las esperaba.
function spz(){if(!state.sp||typeof state.sp!=='object')state.sp={bd:1+Math.floor(Math.random()*60),gen:{},man:{},ker:{},hec:-1,ad:-1,comp:-1,seen:{},touch:0};return state.sp;}
const SPC={g:[],t:0,card:false};
function spMonthOn(){try{const m=calNow().mes,n=clock.h>=21||clock.h<4;if(!n)return false;if(MODE==='roma')return m==='Maius'&&!cultz().lem[cultDia().yr];return m==='Antesterión'&&!spz().ker[calNow().year];}catch(e){return false;}}
function spGhost(){const g=new THREE.Group(),m=new THREE.MeshBasicMaterial({color:0xcfe0ff,transparent:true,opacity:0.1,depthWrite:false});const b=new THREE.Mesh(new THREE.CylinderGeometry(0.22,0.55,1.6,10,1,true),m);b.position.y=0.95;g.add(b);const h=new THREE.Mesh(new THREE.SphereGeometry(0.24,10,8),m);h.position.y=1.95;g.add(h);
  const gl=new THREE.Sprite(new THREE.SpriteMaterial({map:TORCH_TEX,color:0x9fc0ff,transparent:true,opacity:0.1,depthWrite:false,blending:THREE.AdditiveBlending}));gl.scale.set(2.6,3.4,1);gl.position.y=1.2;g.add(gl);g.userData={m,gl,ph:Math.random()*6};scene.add(g);return g;}
function spTick(dt){if(!state||ui!=='play'){return;}const on=spMonthOn()&&!(typeof fzIn==='function'&&fzIn())&&player.feet<200;
  if(!on){if(SPC.g.length){for(const g of SPC.g)scene.remove(g);SPC.g.length=0;}return;}
  while(SPC.g.length<3){const g=spGhost(),a=Math.random()*TAU,d=26+Math.random()*16;g.position.set(player.x+Math.cos(a)*d,0,player.z+Math.sin(a)*d);g.position.y=floorAt(g.position.x,g.position.z);SPC.g.push(g);}
  const tor=typeof TORCH!=='undefined'&&TORCH.on,t=performance.now()/1000;
  for(const g of SPC.g){const u=g.userData,dx=player.x-g.position.x,dz=player.z-g.position.z,d=Math.hypot(dx,dz);
    if(d>70){const a=Math.random()*TAU;g.position.x=player.x+Math.cos(a)*30;g.position.z=player.z+Math.sin(a)*30;continue;}
    const v=(tor?0.9:1.3)*dt;g.position.x+=dx/d*v+Math.sin(t*0.7+u.ph)*0.4*dt;g.position.z+=dz/d*v;g.position.y=floorAt(g.position.x,g.position.z)+0.2+Math.sin(t*1.3+u.ph)*0.15;g.rotation.y=Math.atan2(dx,dz);
    const op=(tor?0.42:0.05)*(0.75+0.25*Math.sin(t*3+u.ph))*Math.min(1,d/4);u.m.opacity=op;u.gl.material.opacity=op*0.7;
    if(tor&&d<14&&!spz().seen.first){spz().seen.first=1;save();spCard();}
    if(d<1.4){const s=spz();s.touch++;const a=Math.atan2(-dz,-dx);g.position.x=player.x+Math.cos(a)*28;g.position.z=player.z+Math.sin(a)*28;spTouch();}}}
function spTouch(){const f=document.createElement('div');f.style.cssText='position:fixed;inset:0;z-index:58;pointer-events:none;background:radial-gradient(ellipse at center,rgba(160,190,255,0) 30%,rgba(120,160,255,.55));animation:spF .9s ease-out forwards';document.body.appendChild(f);setTimeout(()=>f.remove(),1000);
  const ro=MODE==='roma';qAdd('eu',-1);toast('<span class="label">'+(ro?'Un frío te atraviesa':'Algo te roza en la oscuridad')+'</span><br>'+(ro?'Un romano diría que un lemur te ha alcanzado: los muertos sin descanso vuelven a casa porque nadie ha cumplido con ellos. El rito de las habas negras, a medianoche ante un larario, los aleja hasta el año que viene.':'Un ateniense diría que una Ker te ha tocado: en las Antesterias las almas de los muertos andan sueltas por la ciudad. Usa tu ramita de espino (casilla 9) para hacer el rito que las echa.')+' <span class="sub">−1 '+(ro?'Pietas':'Eusébeia')+'</span>');}
function spCard(){const ro=MODE==='roma';vmS('☾',ro?'Lemures':'Keres',ro?'los muertos sin descanso':'las almas de los muertos','<p>Con la luz de la antorcha ves unas figuras pálidas que se acercan sin hacer ruido.</p>'+(ro?'<p>Los romanos distinguían entre los <b>Manes</b>, los muertos de la familia, que descansan tranquilos si se les honra, y los <b>Lemures</b> o Larvas: los que murieron antes de tiempo, sin sepultura o sin familia que los recuerde, y que vagan de noche por las casas. Para echarlos estaban las <b>Lemurias</b>, tres noches de mayo.</p><p class="sub">Fuentes: Ovidio, Fastos V 419-492; Plauto, la comedia El fantasma (Mostellaria); Plinio el Joven, Cartas VII 27, el fantasma con cadenas de una casa de Atenas.</p>':'<p>En las <b>Antesterias</b>, la fiesta del vino nuevo, se abría la tinaja del vino y, según se creía, también el mundo de los muertos. Las almas, las <b>Keres</b>, salían y andaban por la ciudad. Se masticaban hojas de espino, se untaban las puertas con pez y, al final de la fiesta, se las echaba con una fórmula: «¡Fuera, Keres: ya no son las Antesterias!».</p><p class="sub">Fuentes: los léxicos de Focio y la Suda («Θύραζε Κῆρες»); sobre la fiesta, Tucídides II 15 y la comedia de Aristófanes Los acarnienses.</p>')+'<p class="sub">El juego muestra lo que ellos creían, no lo que existía.</p>',[vmBye]);}
// ---- el menú de los ritos (amuleto, casilla 9)
function spMenu(){const ro=MODE==='roma',s=spz(),d=state.day||1,c=calNow(),D=cultDia(),btn=[];let h='';
  if(ro){const enCasa=player.feet>CASA.Y-50;h=_t(10433,'<p>Tus figurillas de los Lares: dos muchachos de bronce que bailan con un cuerno de beber. Hoy son ')+D.nombre+'.</p>';
    if(enCasa)btn.push([_t(10434,'Ir al larario de tu casa'),()=>{closeDialog();cultoAct({ctx:'casa',data:{name:'Tu larario'}});},'quiz']);
    const bdIs=((d-1)%60)+1===s.bd;h+=_t(10435,'<p class="sub">Tu cumpleaños en el juego es el día ')+s.bd+_t(10436,' de cada año de sesenta días')+(bdIs?_t(10437,': <b>¡es hoy!</b>'):'.')+'</p>';
    if(bdIs&&!s.gen[c.year])btn.push([(pjFem()?_t(10438,'Honrar a tu Juno'):_t(10439,'Honrar a tu Genio'))+_t(10440,' (es tu cumpleaños)'),()=>{s.gen[c.year]=1;qAdd('eu',2);save();vmS('✶',pjFem()?_t(10441,'Tu Juno'):_t(10442,'Tu Genio'),_t(10443,'el día de tu cumpleaños'),_t(10444,'<p>Te pones una toga limpia, enciendes incienso, viertes vino puro y dejas una torta y unas flores ante el altar: nunca sangre, que el día de tu nacimiento no se mata. ')+(pjFem()?_t(10445,'La Juno es el espíritu que acompaña a cada mujer, como el Genio a cada hombre.'):_t(10446,'El Genio nace contigo y te acompaña toda la vida: es tu fuerza y tu buena estrella.'))+_t(10447,' Tus amigos te felicitan y te regalan algo.</p><p class="sub">Fuentes: Censorino, El día del nacimiento 2; Tibulo II 2; Horacio, Odas III 17. +2 Pietas</p>'),[vmBye]);},'quiz']);
    if(c.mes==='Februarius'&&!s.man[c.year])btn.push([_t(10448,'Llevar ofrendas a los Manes (Parentales)'),()=>{s.man[c.year]=1;qAdd('eu',2);save();vmS('⚱',_t(10449,'Parentales'),_t(10450,'febrero, el mes de los muertos'),_t(10451,'<p>Tus muertos están lejos, en tu tierra. Haces lo que hacen los romanos: compras unas violetas, un poco de pan mojado en vino, sal y trigo, y lo dejas en una tumba de la Vía Apia que nadie parece cuidar. Ovidio dice que a los Manes les basta poco: una teja con flores es suficiente.</p><p class="sub">Fuentes: Ovidio, Fastos II 533-570. +2 Pietas</p>'),[vmBye]);},'quiz']);
    if(c.mes==='Maius')h+=_t(10452,'<p class="sub">Es mayo: en las noches de las Lemurias vagan los Lemures. Si los ves con la antorcha, haz el rito de las habas negras a medianoche ante un larario (el de tu casa o el de la Domus del Celio).</p>');}
  else{const orf=state.fest&&state.fest.orficos;h='<p>'+(orf?_t(10453,'Tu laminilla de oro de los órficos: unas líneas para orientarte en el Hades. Al lado, una ramita de espino.'):_t(10454,'Tu ramita de espino, para alejar a los espíritus.'))+_t(10455,' Hoy es ')+(D.i===0?_t(10456,'la luna nueva, el primer día del mes'):_t(10457,'el día ')+(D.i+1)+_t(10458,' del mes de ')+c.mes)+'.</p>';
    if(s.ad!==d)btn.push([_t(10459,'Dar unas gotas de vino puro al Agathós Daímon'),()=>{s.ad=d;qAdd('eu',1);save();vmS('🐍',_t(10460,'Agathós Daímon'),_t(10461,'el buen espíritu de la casa'),_t(10462,'<p>Antes de beber, viertes unas gotas de vino sin mezclar para el <b>Agathós Daímon</b>, el «buen espíritu» de la casa, que se imagina como una serpiente que vive junto al hogar y trae la abundancia. En el banquete se hace lo mismo al terminar de comer, antes de mezclar el vino con agua.</p><p class="sub">Fuente: Aristófanes, Los caballeros 85-106 y Las avispas 525. +1 Eusébeia</p>'),[vmBye]);},'quiz']);
    if(D.i===0&&s.hec!==d)btn.push([_t(10463,'Dejar la cena de Hécate en una encrucijada (es luna nueva)'),()=>{s.hec=d;qAdd('eu',2);save();vmS('☾',_t(10464,'La cena de Hécate'),_t(10465,'luna nueva'),_t(10466,'<p>Al caer la tarde dejas en un cruce de caminos una cesta con pan, huevos y queso para <b>Hécate</b>, la diosa de las encrucijadas, de la noche y de los fantasmas, que se representa con tres cuerpos mirando a tres caminos. Así la casa queda limpia de malos espíritus para el mes que empieza. Al rato, ves que un mendigo se acerca y se la come: en Atenas todo el mundo lo sabe y nadie se escandaliza.</p><p class="sub">Fuente: Aristófanes, Pluto 594-597. +2 Eusébeia</p>'),[vmBye]);},'quiz']);
    if(c.mes==='Antesterión'&&!s.ker[c.year])btn.push([_t(10467,'Hacer el rito contra las Keres (Antesterias)'),()=>spKeres(),'quiz']);}
  btn.push([_t(10468,'¿Qué espíritus hay?'),()=>vmS('✶',_t(10469,'Los espíritus'),ro?_t(10470,'lo que creían los romanos'):_t(10471,'lo que creían los atenienses'),ro?_t(10472,'<p><b>Lares</b>: los guardianes de la casa y de las encrucijadas. <b>Penates</b>: los de la despensa. <b>Genio</b> y <b>Juno</b>: el espíritu de cada hombre y de cada mujer, que se honra el día del cumpleaños. <b>Manes</b>: los muertos de la familia, en las Parentales de febrero. <b>Lemures</b>: los muertos sin descanso, que se echan en las Lemurias de mayo. Por las calles verás los altares de los <b>Lares de las encrucijadas</b>.</p>'):_t(10473,'<p><b>Agathós Daímon</b>: el buen espíritu de la casa, una serpiente. <b>Hécate</b>: la diosa de las encrucijadas, que recibe una cena cada luna nueva. <b>Keres</b>: las almas de los muertos, que salen en las Antesterias. Y los <b>héroes</b>, muertos poderosos a los que se hacen ofrendas en su tumba.</p>'),[vmBye])]);
  btn.push(vmBye);vmS(ro?'Λ':'✶',hbAmuletoName(),_t(10474,'los ritos de los espíritus'),h,btn);}
function spKeres(){const P=[['¿Qué se mastica por la mañana para protegerse?',['Hojas de espino','Ajo crudo','Laurel'],'El espino, con sus pinchos, aleja a los espíritus.'],['¿Con qué se untan las puertas de la casa?',['Con pez','Con miel','Con aceite'],'La pez negra y pegajosa: los muertos no cruzan una puerta untada.'],['¿Qué se dice al final de la fiesta?',['«¡Fuera, Keres: ya no son las Antesterias!»','«¡Bienvenidas, almas de los muertos!»','«¡Que vuelvan el año que viene!»'],'Θύραζε Κῆρες, οὐκέτ᾽ Ἀνθεστήρια: así se las despedía.']];let i=0,err=0;
  const step=()=>{if(i>=P.length){const s=spz(),y=calNow().year;if(!err){s.ker[y]=1;qAdd('eu',3);}save();for(const g of SPC.g)scene.remove(g);if(!err)SPC.g.length=0;vmS('✶','Las Keres','Antesterias',err?'<p>Te has equivocado '+err+' '+(err===1?'vez':'veces')+': un ateniense empezaría otra vez desde el principio.</p>':'<p>Las Keres se marchan hasta el año que viene. Esta noche ya no las verás.</p><p class="sub">+3 Eusébeia</p>',[vmBye]);return;}
    const q=P[i],ord=[0,1,2].sort(()=>Math.random()-0.5);vmS('✶','Las Keres','paso '+(i+1)+' de '+P.length,'<p>'+q[0]+'</p>',ord.map(a=>[q[1][a],()=>{if(a!==0){err++;toast('<i>No es así.</i> '+q[2]);}else toast(q[2]);i++;step();},'quiz']));};step();}
// ---- los altares de los Lares de las encrucijadas (Roma) y una Hécate de tres cuerpos (Atenas)
function spSetup(){const ro=MODE==='roma';const S=ro?[['ro_subura',14,10],['ro_emporio',-16,12],['ro_circo',18,-40]]:[];
  for(const[id,dx,dz]of S){const p=artAnchor(id,dx,dz);if(!p)continue;const[x,z]=p,g=grp(x,floorAt(x,z),z,Math.random()*TAU);box(1.8,2.2,1,lam('#d9c9a8'),0,1.1,0,g);box(2.1,0.25,1.3,lam('#b0563a'),0,2.35,0,g);box(1.3,0.9,0.05,lam('#c0583c'),0,1.6,0.53,g);box(1.2,0.6,1.4,lam('#cdbd9c'),0,0.3,0.9,g);addCirc(x,z,1.2);egxObj(x,z,undefined,'sp:compitum','Compitum','los Lares de la encrucijada',3);}
  if(!ro&&typeof AG!=='undefined'){const p=findFree(AG.x+62,AG.z+48,1);if(p){const[x,z]=p,g=grp(x,floorAt(x,z),z,0),m=lam('#e6dccb');box(0.6,2.6,0.6,m,0,1.3,0,g);for(let k=0;k<3;k++){const a=k/3*TAU,f=box(0.5,1.5,0.25,m,Math.sin(a)*0.42,1.6,Math.cos(a)*0.42,g);f.rotation.y=a;const hd=new THREE.Mesh(new THREE.SphereGeometry(0.16,8,6),m);hd.position.set(Math.sin(a)*0.42,2.5,Math.cos(a)*0.42);g.add(hd);}addCirc(x,z,0.8);egxObj(x,z,undefined,'sp:hecate','Hekataion','Hécate de las encrucijadas',3);}}}
function spAct(o){const ro=MODE==='roma',s=spz(),d=state.day||1,c=calNow();
  if(o.act==='sp:compitum'){const ian=c.mes==='Ianuarius';const bt=[];if(s.comp!==d)bt.push([ian?_t(10475,'Colgar muñecas y bolas de lana (Compitalia)'):_t(10476,'Dejar una guirnalda y un poco de incienso'),()=>{s.comp=d;qAdd('eu',ian?2:1);save();vmS('Λ','Compitum','ofrenda',ian?_t(10477,'<p>Cuelgas en el altar una muñeca de lana por cada persona libre de tu casa y una bola de lana por cada esclavo: es la costumbre de las Compitalia. Se dice que así los Lares, o los espíritus que rondan los cruces, se llevan la lana en vez de a la gente.</p><p class="sub">Fuente: Macrobio, Saturnales I 7, 34-35, y Festo. +2 Pietas</p>'):_t(10478,'<p>Dejas una guirnalda y unos granos de incienso. Una vecina, que pasa con el cántaro, te sonríe.</p><p class="sub">+1 Pietas</p>'),[vmBye]);},'quiz']);
    bt.push(vmBye);vmS('Λ','Compitum','los Lares de la encrucijada',_t(10479,'<p>En cada cruce de calles hay un altarcito como este, con dos Lares pintados que bailan. Cada barrio, el <b>vicus</b>, lo cuida con sus propios magistrados, los <b>vicomagistri</b>, que suelen ser libertos. Augusto reorganizó Roma en 265 barrios y mandó poner en estos altares, junto a los Lares, a su propio Genio: así cada vecino honraba al emperador en su esquina.</p><p>En invierno se celebran las <b>Compitalia</b>, la fiesta de los cruces, en la que hasta los esclavos tienen fiesta.</p><p class="sub">Fuentes: Suetonio, Augusto 30-31; Ovidio, Fastos V 129-148.')+(ian?_t(10480,' <b>Es Ianuarius: estamos en las Compitalia.</b>'):'')+'</p>',bt);return;}
  if(o.act==='sp:hecate'){const nm=cultDia().i===0;vmS('☾','Hekataion','Hécate de las encrucijadas',_t(10481,'<p>Un pilar con tres figuras de mujer dándose la espalda: <b>Hécate</b>, que mira a la vez a los tres caminos de un cruce. Es la diosa de las encrucijadas, de la noche, de la magia y de los fantasmas. Hay imágenes como esta delante de muchas casas y en los cruces. El escultor Alcámenes hizo una famosa, de tres cuerpos, junto a la entrada de la Acrópolis: búscala junto al templo de Atenea Nike.</p><p class="sub">Fuentes: Pausanias II 30, 2; Aristófanes, Avispas 804 y Pluto 594-597. ')+(nm?_t(10482,'Hoy es luna nueva: puedes dejarle su cena con tu ramita de espino (casilla 9).'):_t(10483,'Cada luna nueva se le deja una cena en los cruces.'))+'</p>',[vmBye]);return;}}

// ============================================================ MEJORAS VISUALES 2: luna con fases, lejanía según la hora, ventanas encendidas, incienso,
// desenfoque en el modo foto y sombras de contacto (oclusión ambiental) dentro de la iluminación realzada.
// La luna sigue el calendario del juego: las Kalendas son luna nueva, las Nonas cuarto creciente y los Idus luna llena (el calendario romano antiguo era lunar; el ático también).
const VIS={win:null,winMat:null,inc:[],incT:0};
function visMoonPhase(){try{return cultDia().i*0.125;}catch(e){return 0.5;}}
const updateSky0=updateSky;updateSky=function(){updateSky0();try{
  if(SKY.uniforms.mph)SKY.uniforms.mph.value=visMoonPhase();
  // lejanía: de día el aire limpio deja ver lejos; al alba hay bruma; al atardecer el polvo dorado acorta la vista; de noche, casi nada
  const ov=(typeof CAV!=='undefined'&&CAV.ovr)||(typeof FZ!=='undefined'&&FZ.ovr);
  if(!ov&&scene.fog){const day=DAYF,h=clock.h,dawn=Math.max(0,1-Math.abs(h-6.6)/1.4),dusk=Math.max(0,1-Math.abs(h-18.4)/1.5);
    scene.fog.near=lerp(150,260,day)-dawn*90-dusk*40;scene.fog.far=lerp(1250,2400,day)-dawn*700-dusk*350;
    if(dusk>0)scene.fog.color.lerp(_c1.set('#e0a86e'),dusk*0.35);if(dawn>0)scene.fog.color.lerp(_c1.set('#c9c4cf'),dawn*0.4);}
  if(VIS.winMat){const night=clamp(1-DAYF*1.6,0,1);VIS.winMat.opacity=night*0.95;VIS.win.visible=night>0.02;}}catch(e){}};
// ventanas con luz de lucerna: dos o tres por casa, en sus fachadas
function visWindows(){const hs=footprints.filter(f=>f.house&&f.w>3&&f.d>3);if(!hs.length)return;const per=3,N=hs.length*per;
  const c=document.createElement('canvas');c.width=32;c.height=48;const x=c.getContext('2d'),g=x.createLinearGradient(0,0,0,48);g.addColorStop(0,'#ffcf7a');g.addColorStop(1,'#ff9a3a');x.fillStyle=g;x.fillRect(0,0,32,48);x.fillStyle='rgba(60,30,10,.85)';x.fillRect(14,0,4,48);x.fillRect(0,22,32,3);
  const m=new THREE.MeshBasicMaterial({map:new THREE.CanvasTexture(c),transparent:true,opacity:0,depthWrite:false,fog:true}),im=new THREE.InstancedMesh(new THREE.PlaneGeometry(0.75,1.05),m,N),d=new THREE.Object3D(),R=mulberry32(4242);let k=0;
  for(const f of hs){const a=f.a||0;for(let i=0;i<per;i++){if(R()<0.35)continue;const side=Math.floor(R()*4),u=(R()-0.5)*0.7;let lx,lz,nx,nz;
      if(side===0){lx=u*f.w;lz=f.d/2+0.06;nx=0;nz=1;}else if(side===1){lx=u*f.w;lz=-f.d/2-0.06;nx=0;nz=-1;}else if(side===2){lx=f.w/2+0.06;lz=u*f.d;nx=1;nz=0;}else{lx=-f.w/2-0.06;lz=u*f.d;nx=-1;nz=0;}
      const p=toW(lx,lz,f.x,f.z,a),wn=toW(nx,nz,0,0,a),gy=terrainH(p[0],p[1]);if(!isFinite(gy))continue;d.position.set(p[0],gy+(R()<0.5?2.4:5.6),p[1]);d.rotation.set(0,Math.atan2(wn[0],wn[1]),0);d.updateMatrix();im.setMatrixAt(k++,d.matrix);}}
  im.count=k;im.instanceMatrix.needsUpdate=true;im.frustumCulled=false;im.renderOrder=2;scene.add(im);VIS.win=im;VIS.winMat=m;}
// incienso en los altares cercanos (lararios, altares de las encrucijadas, la Hécate)
function visSetup(){try{visWindows();}catch(e){console.warn('visWindows',e);}
  VIS.inc=[];try{for(const o of CULT_OBJS)VIS.inc.push([o.x,o.z]);}catch(e){}for(const o of EGX_OBJS)if(o.act==='sp:compitum'||o.act==='sp:hecate')VIS.inc.push([o.x,o.z]);}
function visTick(dt){VIS.incT-=dt;if(VIS.incT>0)return;VIS.incT=0.3;for(const[x,z]of VIS.inc){if(Math.abs(x-player.x)>40||Math.abs(z-player.z)>40)continue;const y=floorAt(x,z)+1.6;pfx(x+(Math.random()-0.5)*0.2,y,z+(Math.random()-0.5)*0.2,{col:'#d9d4ca',vx:(Math.random()-0.5)*0.15,vy:0.55,vz:(Math.random()-0.5)*0.15,g:0,life:3.2,s:0.16,grow:0.5,a:0.32});}}
// ---- desenfoque (profundidad de campo) en el modo foto
const DOF={on:false,ready:false,loading:null,comp:null,pass:null};
function dofLoad(){if(DOF.ready)return Promise.resolve();if(DOF.loading)return DOF.loading;const base='https://cdn.jsdelivr.net/npm/three@0.128.0/examples/js/';
  const L=['shaders/CopyShader.js','shaders/BokehShader.js','postprocessing/EffectComposer.js','postprocessing/RenderPass.js','postprocessing/ShaderPass.js','postprocessing/BokehPass.js'].filter(f=>!(f.endsWith('CopyShader.js')&&THREE.CopyShader)&&!(f.endsWith('EffectComposer.js')&&THREE.EffectComposer)&&!(f.endsWith('RenderPass.js')&&THREE.RenderPass)&&!(f.endsWith('ShaderPass.js')&&THREE.ShaderPass));
  DOF.loading=L.reduce((p,f)=>p.then(()=>new Promise((ok,ko)=>{const s=document.createElement('script');s.src=base+f;s.onload=ok;s.onerror=()=>ko(new Error(f));document.head.appendChild(s);})),Promise.resolve()).then(()=>{
    const W=innerWidth,H=innerHeight,pr=renderer.getPixelRatio(),rt=new THREE.WebGLRenderTarget(W*pr,H*pr,{format:THREE.RGBAFormat,depthBuffer:true,stencilBuffer:true}),c=new THREE.EffectComposer(renderer,rt);c.setPixelRatio(pr);c.setSize(W,H);c.addPass(new THREE.RenderPass(scene,camera));
    const b=new THREE.BokehPass(scene,camera,{focus:20,aperture:0.00012,maxblur:0.008,width:W,height:H});c.addPass(b);DOF.comp=c;DOF.pass=b;DOF.ready=true;addEventListener('resize',()=>{if(DOF.comp)DOF.comp.setSize(innerWidth,innerHeight);});});return DOF.loading;}
const _dofRay=new THREE.Raycaster();
function dofFocus(){try{_dofRay.setFromCamera({x:0,y:0},camera);_dofRay.far=600;const hits=_dofRay.intersectObjects(scene.children,true).filter(h=>h.object.visible&&!(h.object.material&&h.object.material.transparent));const d=hits.length?hits[0].distance:60;DOF.pass.uniforms.focus.value=d;DOF.pass.uniforms.aperture.value=0.00012*Math.min(3,40/Math.max(4,d));return d;}catch(e){return 0;}}
function dofToggle(){if(DOF.on){DOF.on=false;dofLbl();return;}toast('Cargando el desenfoque…');dofLoad().then(()=>{DOF.on=true;const d=dofFocus();dofLbl();toast('<span class="label">Desenfoque</span><br>Enfocado a '+Math.round(d)+' m: lo que está en el centro de la imagen. Mueve la vista y pulsa «Enfocar» otra vez.');}).catch(()=>toast('No se ha podido cargar el desenfoque (¿sin conexión?).'));}
function dofLbl(){const b=$('phDof');if(b)b.textContent='Desenfoque: '+(DOF.on?'sí':'no');const f=$('phFoc');if(f)f.hidden=!DOF.on;}
const phToggle0=phToggle;phToggle=function(on){phToggle0(on);if(PH.on&&$('phUI')&&!$('phDof')){const u=$('phUI'),x=$('phX'),b=document.createElement('button');b.id='phDof';b.onclick=e=>{e.stopPropagation();dofToggle();};u.insertBefore(b,x);const f=document.createElement('button');f.id='phFoc';f.textContent=_t(10484,'Enfocar');f.onclick=e=>{e.stopPropagation();if(DOF.on){const d=dofFocus();toast(_t(10485,'Enfocado a ')+Math.round(d)+' m.');}};u.insertBefore(f,x);dofLbl();}if(!PH.on)DOF.on=false;};
// ---- sombras de contacto (SSAO) dentro de la iluminación realzada: más sombra en rincones, bajo los pórticos y al pie de los muros
GFX.ao=false;try{GFX.ao=localStorage.getItem('nostos-ao')==='on';}catch(e){}
function aoLabel(){return 'Sombras de contacto: '+(GFX.ao?'sí':'no');}
function aoLoad(){if(GFX.aoPass)return Promise.resolve();const base='https://cdn.jsdelivr.net/npm/three@0.128.0/examples/js/';const L=['math/SimplexNoise.js','shaders/SSAOShader.js','postprocessing/SSAOPass.js'];
  return L.reduce((p,f)=>p.then(()=>new Promise((ok,ko)=>{const s=document.createElement('script');s.src=base+f;s.onload=ok;s.onerror=()=>ko(new Error(f));document.head.appendChild(s);})),Promise.resolve()).then(()=>{
    const p=new THREE.SSAOPass(scene,camera,innerWidth,innerHeight);p.kernelRadius=1.2;p.minDistance=0.00008;p.maxDistance=0.0012;try{const W=innerWidth*renderer.getPixelRatio(),H=innerHeight*renderer.getPixelRatio(),dt=new THREE.DepthTexture();dt.type=THREE.UnsignedIntType;p.normalRenderTarget.dispose();p.normalRenderTarget=new THREE.WebGLRenderTarget(W,H,{minFilter:THREE.NearestFilter,magFilter:THREE.NearestFilter,format:THREE.RGBAFormat,depthTexture:dt});p.ssaoMaterial.uniforms.tNormal.value=p.normalRenderTarget.texture;p.ssaoMaterial.uniforms.tDepth.value=dt;if(p.depthRenderMaterial)p.depthRenderMaterial.uniforms.tDepth.value=dt;p.beautyRenderTarget.dispose();p.beautyRenderTarget=new THREE.WebGLRenderTarget(W,H,{minFilter:THREE.LinearFilter,magFilter:THREE.LinearFilter,format:THREE.RGBAFormat,stencilBuffer:true});p.ssaoMaterial.uniforms.tDiffuse.value=p.beautyRenderTarget.texture;if(p.blendMaterial&&p.blendMaterial.uniforms.tDiffuse)p.blendMaterial.uniforms.tDiffuse.value=p.blendRenderTarget?p.blendRenderTarget.texture:p.blendMaterial.uniforms.tDiffuse.value;}catch(e){console.warn('ssao 32 bits',e);}GFX.comp.insertPass(p,1);GFX.aoPass=p;addEventListener('resize',()=>p.setSize(innerWidth,innerHeight));});}
function aoSet(on){GFX.ao=on;try{localStorage.setItem('nostos-ao',on?'on':'off');}catch(e){}
  if(!on){if(GFX.aoPass)GFX.aoPass.enabled=false;toast('Sombras de contacto desactivadas.');return;}
  const go=()=>aoLoad().then(()=>{GFX.aoPass.enabled=true;toast('<span class="label">Sombras de contacto</span><br>Funcionan junto con la iluminación realzada. Si el juego va lento, desactívalas.');}).catch(()=>{GFX.ao=false;toast('No se han podido cargar las sombras de contacto (¿sin conexión?).');});
  if(!GFX.on){gfxSet(true);const w=setInterval(()=>{if(GFX.on&&GFX.comp){clearInterval(w);go();}},400);setTimeout(()=>clearInterval(w),30000);}else go();}
if(GFX.ao)setTimeout(()=>{const w=setInterval(()=>{if(GFX.on&&GFX.comp){clearInterval(w);aoSet(true);}},800);setTimeout(()=>clearInterval(w),40000);},4500);
GM_IC.ao='<circle cx="9" cy="12" r="5"/><path d="M14 7a5 5 0 0 1 0 10"/><path d="M4 20h16"/>';

// ============================================================ EL TIEMPO: sol, nubes, niebla, viento, lluvia, tormenta, calor y nieve, según la estación
// Cada tiempo trae cambios: la lluvia apaga la antorcha y embarra los caminos, el calor cansa (el odre lo arregla), la tormenta impide zarpar
// y disuelve la Asamblea (señal de Zeus o de Júpiter), en invierno el mar está «cerrado», y la sequía se combate con ritos.
const WX_T={
 sol:{n:'despejado',cl:0,rain:0,fog:0},nubes:{n:'nublado',cl:0.55,rain:0,fog:0.1},niebla:{n:'niebla',cl:0.45,rain:0,fog:1},viento:{n:'viento',cl:0.2,rain:0,fog:0,wind:1},
 lluvia:{n:'lluvia',cl:0.85,rain:0.6,fog:0.4},tormenta:{n:'tormenta',cl:1,rain:1,fog:0.5,wind:1},calor:{n:'calor',cl:0,rain:0,fog:0.05,heat:1},nieve:{n:'nieve',cl:0.8,rain:0,snow:1,fog:0.5}};
const WX_ORDER=['auto','sol','nubes','niebla','viento','lluvia','tormenta','calor','nieve'];
const WXS={cl:0,rain:0,fog:0,snow:0,heat:0,rainM:null,snowM:null,flash:0,nextBolt:5,bow:null,bowT:0,heatE:0,snd:null,torchMsg:false};
function wxz(){if(!state.wx||typeof state.wx!=='object')state.wx={k:'sol',end:0,dry:0,lastRain:0,man:'auto',seen:{},rite:0};const w=state.wx;w.seen=w.seen||{};return w;}
function wxNow(){return((state&&state.day)||1)*24+clock.h;}
function wxK(){const w=wxz();return w.man&&w.man!=='auto'?w.man:w.k;}
function wxPick(){const mo=calNow().mo,ro=MODE==='roma',h=clock.h,w=wxz();let W;
  if(mo>=10||mo<=1)W={sol:3,nubes:3,lluvia:3,tormenta:1,niebla:1.5,viento:1.5,nieve:ro?0.35:0.3};
  else if(mo<=4)W={sol:5,nubes:3,lluvia:2,tormenta:0.8,niebla:1,viento:1.5};
  else if(mo<=7)W={sol:6,calor:mo>=6?4:1.5,nubes:1,tormenta:0.5,viento:ro?1:2.5};
  else W={sol:4,nubes:3,lluvia:2.5,tormenta:1.2,niebla:1.5,viento:1};
  if(!(h>=4&&h<=9))delete W.niebla;if(w.rite){W.lluvia=(W.lluvia||0)+8;W.nubes=(W.nubes||0)+2;w.rite=0;}
  let t=0;for(const k in W)t+=W[k];let r=Math.random()*t;for(const k in W){r-=W[k];if(r<=0)return k;}return 'sol';}
function wxChange(k){const w=wxz(),prev=w.k;w.k=k;w.end=wxNow()+(k==='niebla'?2+Math.random()*3:k==='tormenta'?1.5+Math.random()*3:3+Math.random()*9);
  if(WX_T[k].rain){w.dry=0;w.lastRain=state.day||1;}save();if(prev!==k&&ui==='play')wxAnnounce(k,prev);}
const WX_TXT={
 lluvia:['Llueve sobre Roma. Los romanos se echan por encima la paenula, una capa de lana con capucha. Las calles se llenan de barro (por eso hay piedras pasaderas para cruzar las calzadas), y el agua de los tejados cae al impluvium de cada casa y se guarda en una cisterna. Con lluvia, la antorcha no prende y el barro te hace ir más despacio.',
   'Llueve sobre Atenas. Zeus es quien manda la lluvia; los atenienses le rezaban: «Llueve, llueve, querido Zeus, sobre los campos y las llanuras de los atenienses» (lo recuerda Marco Aurelio, Meditaciones V 7). El agua de los tejados se guarda en cisternas, porque en verano las fuentes no bastan. Con lluvia, la antorcha no prende y el barro te hace ir más despacio.'],
 tormenta:['Truena. Para un romano, el rayo es un signo de Júpiter que interpretan los augures y los harúspices etruscos; si truena, no se pueden celebrar las asambleas del pueblo. Donde cae un rayo, los sacerdotes lo «entierran» y rodean el sitio con un brocal, el bidental, que nadie debe pisar. Con este temporal ningún barco zarpa.',
   'Truena: es Zeus. Una señal suya, como un trueno o un terremoto, disuelve la Asamblea en el acto; Aristófanes se burla de ello en Los acarnienses, y Tucídides (V 45) cuenta una asamblea interrumpida por un terremoto. Los sitios donde ha caído un rayo se cercan y se consagran a Zeus Kataibátes, «el que baja». Con este temporal ningún barco zarpa.'],
 niebla:['Niebla del Tíber: hasta media mañana no se ve la otra orilla y los barqueros del puerto fluvial esperan a que levante.','Bruma de la mañana sobre el Iliso y el Cefiso. Desde la Acrópolis, el mar ha desaparecido.'],
 viento:['Sopla el viento. Los marinos lo conocen por su nombre: el Aquilón del norte, el Austro del sur, el Favonio de poniente, que trae la primavera. Con buen viento, los barcos de Alejandría llegan a Puteoli en dos semanas.',
   'Sopla el Bóreas, el viento del norte. Los atenienses le tienen cariño: según Heródoto (VII 189), le rezaron antes de la batalla del Artemisio, su temporal hundió muchas naves persas y luego le levantaron un altar junto al Iliso. En verano soplan los etesios, los vientos regulares del norte que frenan a los barcos que van hacia el mar Negro.'],
 calor:['La canícula: los días en que Sirio, la estrella del Perro, sale con el sol. Quien puede se va de Roma a su villa; los demás duermen la siesta del mediodía, la meridiatio. Con este calor te cansas antes: bebe del odre y busca la sombra.',
   'Sirio, la estrella del Perro, sale con el sol: son los días más calurosos. Hesíodo aconseja sentarse a la sombra de una roca con buen vino y pan de leche (Trabajos y días 582-596). Con este calor te cansas antes: bebe del odre y busca la sombra.'],
 nieve:['Nieva, cosa que en Roma no pasa todos los años. Horacio describe el monte Soracte blanco de nieve y aconseja echar leña al fuego y sacar el vino añejo (Odas I 9). Con nieve se camina más despacio.','Nieva sobre el Ática, cosa que pasa algún invierno. Los pastores bajan los rebaños del Parnés y del Himeto. Con nieve se camina más despacio.'],
 nubes:['Se nubla el cielo sobre las siete colinas.','Se nubla el cielo sobre el Himeto.'],
 sol:['Escampa: vuelve el sol.','Escampa: vuelve el sol.']};
function wxAnnounce(k,prev){const w=wxz(),ro=MODE==='roma',t=WX_TXT[k][ro?0:1],first=!w.seen[k];w.seen[k]=1;save();
  const lb={sol:'Despejado',nubes:'Nublado',niebla:'Niebla',viento:'Viento',lluvia:'Lluvia',tormenta:'Tormenta',calor:'Calor',nieve:'Nieve'}[k];
  toast('<span class="label">El tiempo · '+lb+'</span><br>'+(first?t:t.split('. ')[0]+'.'));
  if(k==='sol'&&prev&&WX_T[prev].rain&&DAYF>0.5)wxRainbow();}
function wxSpeed(){const k=wxK();let f=1;if(WX_T[k].rain&&!MOUNT.riding)f*=0.92;if(k==='nieve')f*=0.86;if(WXS.heatE>=3)f*=0.85;return f;}
// ---- arco iris tras la lluvia
function wxRainbow(){if(WXS.bow){scene.remove(WXS.bow);WXS.bow=null;}if(SUNDIR.y>0.62||SUNDIR.y<0.02)return;   // con el sol a más de ~40° el arco iris queda bajo el horizonte: no se ve (Aristóteles, Meteorológicos III 5)
  // arco iris de verdad: anillo de 42° alrededor del punto opuesto al sol, banda fina (~2°), rojo por fuera y violeta por dentro;
  // va pegado a la cámara (como el cielo) y lo tapan los edificios. Antes era un toro enorme y cercano que se veía como una cúpula de niebla
  const D=1800,r0=D*Math.tan(41*Math.PI/180),r1=D*Math.tan(43*Math.PI/180),g=new THREE.RingGeometry(r0,r1,128,1);
  const m=new THREE.ShaderMaterial({transparent:true,depthWrite:false,fog:false,blending:THREE.AdditiveBlending,uniforms:{op:{value:0},r0:{value:r0},r1:{value:r1},cy:{value:0}},
   vertexShader:'varying vec2 vp;varying float wy;void main(){vp=position.xy;wy=(modelMatrix*vec4(position,1.0)).y;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}',
   fragmentShader:'uniform float op,r0,r1,cy;varying vec2 vp;varying float wy;vec3 hsv(float h){vec3 k=clamp(abs(mod(h*6.0+vec3(0.0,4.0,2.0),6.0)-3.0)-1.0,0.0,1.0);return k;}void main(){if(wy<cy)discard;float u=clamp((length(vp)-r0)/(r1-r0),0.0,1.0);float a=sin(u*3.14159);gl_FragColor=vec4(hsv(0.78*(1.0-u))*a*op,1.0);}'});
  const b=new THREE.Mesh(g,m);b.frustumCulled=false;b.renderOrder=-1;b.userData.D=D;scene.add(b);WXS.bow=b;WXS.bowT=90;wxBowPlace();
  const w=wxz();if(!w.seen.bow){w.seen.bow=1;save();setTimeout(()=>toast('<span class="label">Arco iris</span><br>Para griegos y romanos, el arco iris es Iris, la mensajera de los dioses, que baja por él del Olimpo con sus alas de colores. En la Ilíada es ella quien lleva los mensajes de Zeus.'),2500);}}
function wxBowPlace(){const b=WXS.bow;if(!b)return;const D=b.userData.D,a=new THREE.Vector3(-SUNDIR.x,-SUNDIR.y,-SUNDIR.z).normalize();b.position.copy(camera.position).addScaledVector(a,D);b.lookAt(camera.position);b.material.uniforms.cy.value=camera.position.y;}
// ---- partículas de lluvia y nieve alrededor de la cámara
function wxMakeRain(){const n=2600,p=new Float32Array(n*6);for(let i=0;i<n;i++){const x=(Math.random()-0.5)*90,y=Math.random()*45,z=(Math.random()-0.5)*90;p.set([x,y,z,x+0.08,y-0.9,z],i*6);}
  const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.BufferAttribute(p,3));const m=new THREE.LineSegments(g,new THREE.LineBasicMaterial({color:0xaab6c4,transparent:true,opacity:0,depthWrite:false}));m.frustumCulled=false;scene.add(m);return m;}
function wxMakeSnow(){const n=2200,p=new Float32Array(n*3);for(let i=0;i<n;i++)p.set([(Math.random()-0.5)*80,Math.random()*40,(Math.random()-0.5)*80],i*3);
  const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.BufferAttribute(p,3));const m=new THREE.Points(g,new THREE.PointsMaterial({color:0xffffff,size:0.14,transparent:true,opacity:0,depthWrite:false}));m.frustumCulled=false;scene.add(m);return m;}
function wxSound(on,vol){try{if(!AUD.ctx||!AUD_ON){if(WXS.snd)WXS.snd.g.gain.value=0;return;}const C=AUD.ctx;if(!WXS.snd){const b=C.createBuffer(1,C.sampleRate*2,C.sampleRate),d=b.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=Math.random()*2-1;
    const s=C.createBufferSource();s.buffer=b;s.loop=true;const f=C.createBiquadFilter();f.type='bandpass';f.frequency.value=1400;f.Q.value=0.6;const g=C.createGain();g.gain.value=0;s.connect(f);f.connect(g);g.connect(AUD.master||C.destination);s.start();WXS.snd={s,g};}
    WXS.snd.g.gain.value=on?vol:0;}catch(e){}}
function wxThunder(delay){try{if(!AUD.ctx||!AUD_ON)return;const C=AUD.ctx,t=C.currentTime+delay,b=C.createBuffer(1,C.sampleRate*3,C.sampleRate),d=b.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=(Math.random()*2-1)*Math.pow(1-i/d.length,1.6);
  const s=C.createBufferSource();s.buffer=b;const f=C.createBiquadFilter();f.type='lowpass';f.frequency.value=180;const g=C.createGain();g.gain.setValueAtTime(0.0001,t);g.gain.exponentialRampToValueAtTime(0.9,t+0.08);g.gain.exponentialRampToValueAtTime(0.001,t+2.8);s.connect(f);f.connect(g);g.connect(AUD.master||C.destination);s.start(t);}catch(e){}}
function wxBolt(){WXS.flash=1;const f=document.createElement('div');f.style.cssText='position:fixed;inset:0;z-index:57;pointer-events:none;background:#eef2ff;opacity:.55;transition:opacity .35s';document.body.appendChild(f);requestAnimationFrame(()=>requestAnimationFrame(()=>f.style.opacity=0));setTimeout(()=>f.remove(),450);wxThunder(0.6+Math.random()*2.2);
  const w=wxz();if(!w.seen.rayo&&ui==='play'){w.seen.rayo=1;save();setTimeout(()=>vmS('ϟ',MODE==='roma'?'El rayo de Júpiter':'El rayo de Zeus','un signo de los dioses',MODE==='roma'?'<p>Para los romanos, el rayo no es un accidente: es un mensaje de Júpiter. Los augures observan de qué parte del cielo viene, y los harúspices, siguiendo los libros de los etruscos, explican qué significa. Si truena durante una asamblea, el magistrado debe disolverla: «cuando Júpiter truena, es sacrílego celebrar los comicios», escribe Cicerón (Sobre la adivinación II 42-43).</p><p>Donde cae un rayo se «entierra» (fulgur conditum) y se rodea con un brocal, el bidental. En el Foro hay uno famoso, el puteal de Libón, junto al que se reúnen los prestamistas.</p>':'<p>Para los griegos, el rayo es el arma de Zeus, que se la forjaron los Cíclopes. Un trueno, un relámpago o un terremoto son una diosemía, una «señal de Zeus»: si ocurre durante la Asamblea, se disuelve en el acto. Aristófanes se burla de los que la invocaban para librarse de una votación incómoda (Los acarnienses 170-171).</p><p>El sitio donde cae un rayo se cerca y queda consagrado a Zeus Kataibátes, «el que baja»: nadie puede pisarlo.</p>',[vmBye]),1200);}}
function wxTick(dt){if(!state)return;const w=wxz();if(w.man==='auto'&&wxNow()>=w.end)wxChange(wxPick());
  const k=wxK(),T=WX_T[k],a=Math.min(1,dt*0.35);const inside=player.feet>CASA.Y-50||(typeof fzIn==='function'&&fzIn())||(typeof cavIn==='function'&&cavIn());
  WXS.cl+=((inside?0:T.cl)-WXS.cl)*a;WXS.rain+=((inside?0:T.rain||0)-WXS.rain)*a;WXS.fog+=((inside?0:T.fog||0)-WXS.fog)*a;WXS.snow+=((inside?0:T.snow||0)-WXS.snow)*a;WXS.heat+=((T.heat&&clock.h>10&&clock.h<18?1:0)-WXS.heat)*a;
  // lluvia y nieve
  if(WXS.rain>0.02){if(!WXS.rainM)WXS.rainM=wxMakeRain();const m=WXS.rainM;m.visible=true;m.material.opacity=0.42*WXS.rain*(0.5+0.5*DAYF)+0.08;m.position.set(camera.position.x,camera.position.y-20,camera.position.z);
    const p=m.geometry.attributes.position.array,v=dt*(20+8*WXS.rain);for(let i=0;i<p.length;i+=6){p[i+1]-=v;p[i+4]-=v;if(p[i+4]<0){p[i+1]+=45;p[i+4]+=45;}}m.geometry.attributes.position.needsUpdate=true;}else if(WXS.rainM)WXS.rainM.visible=false;
  if(WXS.snow>0.02){if(!WXS.snowM)WXS.snowM=wxMakeSnow();const m=WXS.snowM;m.visible=true;m.material.opacity=0.85*WXS.snow;m.position.set(camera.position.x,camera.position.y-18,camera.position.z);
    const p=m.geometry.attributes.position.array,t=performance.now()/1000;for(let i=0;i<p.length;i+=3){p[i+1]-=dt*1.3;p[i]+=Math.sin(t+i)*dt*0.3;if(p[i+1]<0)p[i+1]+=40;}m.geometry.attributes.position.needsUpdate=true;}else if(WXS.snowM)WXS.snowM.visible=false;
  wxSound(WXS.rain>0.05&&ui==='play',0.09*WXS.rain);
  // relámpagos
  if(k==='tormenta'&&!inside){WXS.nextBolt-=dt;if(WXS.nextBolt<=0){WXS.nextBolt=6+Math.random()*16;wxBolt();}}
  if(WXS.flash>0||WXS.fl0){WXS.flash=Math.max(0,WXS.flash-dt*4);if(WXS.hb!==undefined)hemi.intensity=WXS.hb+WXS.flash*1.2;WXS.fl0=WXS.flash>0;}
  // viento
  if(T.wind&&typeof WIND!=='undefined'&&WIND.s)WIND.s.value=Math.max(WIND.s.value,k==='tormenta'?2.2:1.8);
  // la lluvia apaga la antorcha
  if(WXS.rain>0.4&&typeof TORCH!=='undefined'&&TORCH.on&&!inside){try{toggleTorch0wx();}catch(e){TORCH.on=false;}if(!WXS.torchMsg){WXS.torchMsg=true;toast('<span class="label">Se apaga la antorcha</span><br>La lluvia apaga la llama. Espera a que escampe, o resguárdate bajo techo.');}}
  if(WXS.rain<0.2)WXS.torchMsg=false;
  // el calor cansa: cada hora de juego al sol, entre la hora cuarta y la décima, sin beber
  if(WXS.heat>0.5&&!inside&&ui==='play'){WXS.heatE+=dt*clock.speed;if(WXS.heatE>=3&&!WXS.heatMsg){WXS.heatMsg=true;toast('<span class="label">Agotado por el calor</span><br>Caminas más despacio. Bebe del odre (casilla 4) o espera a que caiga la tarde.');}}else if(WXS.heat<0.2){WXS.heatE=Math.max(0,WXS.heatE-dt*clock.speed);if(WXS.heatE<1)WXS.heatMsg=false;}
  if(WXS.bow){WXS.bowT-=dt;WXS.bow.material.uniforms.op.value=0.35*clamp(Math.min(WXS.bowT/10,(90-WXS.bowT)/6),0,1)*(1-WXS.cl)*clamp(SUNDIR.y*4,0,1);wxBowPlace();if(WXS.bowT<=0){scene.remove(WXS.bow);WXS.bow=null;}}}
// sin antorcha bajo la lluvia
// con lluvia, la antorcha no prende: en su lugar, un farol de cuerno (la llama va dentro de una caja con paredes de cuerno raspado), que alumbra menos
const toggleTorch0wx=toggleTorch;toggleTorch=function(){if(state&&typeof TORCH!=='undefined'&&!TORCH.on&&WXS.rain>0.4&&!(player.feet>CASA.Y-50)){TORCH.lantern=true;
  if(!state.seen['farol']){state.seen['farol']=1;toast('<span class="label">Un farol de cuerno</span><br>Con esta lluvia una antorcha no prendería: enciendes un farol, una lamparilla de aceite dentro de una caja con paredes de cuerno raspado, tan fino que deja pasar la luz. Alumbra menos, pero no se apaga.'+(MODE==='roma'?' Marcial hace hablar a uno: «guía del camino, llevo la llama encerrada, y la lamparilla va a salvo en mi seno» (Epigramas 14, 61).':''));}
  else toast('Enciendes el farol de cuerno.');return toggleTorch0wx();}
  if(TORCH&&TORCH.on)TORCH.lantern=false;return toggleTorch0wx();};
{const u0=updateTorch;updateTorch=function(dt,t){u0(dt,t);if(TORCH.on&&TORCH.lantern&&TORCH.light){TORCH.light.intensity*=0.62;if(TORCH.fl)TORCH.fl.scale.multiplyScalar(0.55);}};}
// el cielo, la luz y la niebla según el tiempo (sobre lo que ya calcula updateSky)
const updateSkyWx=updateSky;updateSky=function(){updateSkyWx();try{const c=WXS.cl,f=WXS.fog,r=WXS.rain;if(c<0.01&&f<0.01&&WXS.heat<0.01)return;
  WXS.hb=hemi.intensity;const gr=_c2.setRGB(0.55,0.58,0.62).multiplyScalar(0.18+0.82*DAYF);for(const u of['top','mid','bot'])SKY.uniforms[u].value.lerp(gr,c*0.8);SKY.uniforms.glow.value*=1-c;
  sun.intensity*=1-0.72*c;hemi.intensity*=1-0.2*c;WXS.hb=hemi.intensity;STARS.material.opacity*=1-c;
  const ov=(typeof CAV!=='undefined'&&CAV.ovr)||(typeof FZ!=='undefined'&&FZ.ovr);
  if(!ov&&scene.fog){scene.fog.color.lerp(gr,c*0.7);scene.fog.near*=1-0.75*f;scene.fog.far=Math.max(140,scene.fog.far*(1-0.8*f)*(1-0.35*r));if(WXS.heat>0)scene.fog.color.lerp(_c1.set('#e8d2a8'),WXS.heat*0.25);}}catch(e){}};
// la hora del HUD dice también el tiempo
