// ---- animales salvajes hechos con piezas sencillas (no hay modelos de Blender para ellos)
const WILD={deer:{c:'#9a6a40',b:'#e8d8c0',L:1.35,H:0.95,W:0.42,leg:0.9,neck:0.55,head:0.32,ant:1},boar:{c:'#3a2e26',b:'#4a3a30',L:1.15,H:0.62,W:0.5,leg:0.45,neck:0.1,head:0.4,tusk:1},
 wolf:{c:'#7a7268',b:'#c8c0b4',L:1.0,H:0.6,W:0.34,leg:0.6,neck:0.25,head:0.3,ears:1},bear:{c:'#4a3424',b:'#5a4232',L:1.55,H:0.95,W:0.75,leg:0.6,neck:0.1,head:0.42,ears:1},
 hare:{c:'#9a846a',b:'#e0d4c4',L:0.42,H:0.26,W:0.2,leg:0.2,neck:0.08,head:0.15,long:1},ox:{c:'#eeeae0',b:'#dcd6c8',L:2.0,H:1.15,W:0.75,leg:0.85,neck:0.2,head:0.5,horn:1}};
function wildBuild(sp,o){const S=WILD[sp],g=new THREE.Group(),m=lam((o&&o.c&&o.c.coat)||S.c),mb=lam(S.b),dk=lam('#1e1814');
  const body=new THREE.Mesh(new THREE.SphereGeometry(1,12,8),m);body.scale.set(S.W,S.H*0.42,S.L*0.55);body.position.set(0,S.leg+S.H*0.3,0);body.castShadow=true;g.add(body);
  const head=new THREE.Group();head.position.set(0,S.leg+S.H*0.5+S.neck*0.6,-S.L*0.52);g.add(head);
  const hm=new THREE.Mesh(new THREE.SphereGeometry(1,10,7),m);hm.scale.set(S.head*0.55,S.head*0.55,S.head);hm.position.z=-S.head*0.5;head.add(hm);
  if(S.neck>0.15){const nk=new THREE.Mesh(new THREE.CylinderGeometry(S.W*0.32,S.W*0.42,S.neck*1.4,8),m);nk.rotation.x=-0.6;nk.position.set(0,-S.neck*0.45,S.head*0.2);head.add(nk);}
  if(S.ant)for(const s of[-1,1]){const a=new THREE.Mesh(new THREE.CylinderGeometry(0.02,0.035,0.55,5),lam('#cdb48a'));a.position.set(s*0.12,S.head*0.55+0.22,-S.head*0.2);a.rotation.z=s*0.5;head.add(a);for(const k of[0.1,0.25]){const t=new THREE.Mesh(new THREE.CylinderGeometry(0.012,0.02,0.22,4),lam('#cdb48a'));t.position.set(s*(0.12+k*0.7),S.head*0.55+0.1+k*1.2,-S.head*0.2-0.06);t.rotation.set(-0.5,0,s*0.2);head.add(t);}}
  if(S.tusk)for(const s of[-1,1]){const t=new THREE.Mesh(new THREE.ConeGeometry(0.025,0.14,5),lam('#efe8d8'));t.position.set(s*0.1,-0.04,-S.head*1.3);t.rotation.x=-2.4;head.add(t);}
  if(S.ears)for(const s of[-1,1]){const e=new THREE.Mesh(new THREE.ConeGeometry(0.05*S.head/0.3,0.12*S.head/0.3,4),m);e.position.set(s*S.head*0.35,S.head*0.5,-S.head*0.1);head.add(e);}
  if(S.long)for(const s of[-1,1]){const e=new THREE.Mesh(new THREE.CylinderGeometry(0.02,0.03,0.16,5),m);e.position.set(s*0.04,0.13,0);e.rotation.z=s*0.2;head.add(e);}
  if(S.horn)for(const s of[-1,1]){const h=new THREE.Mesh(new THREE.CylinderGeometry(0.03,0.05,0.4,6),lam('#d8ccb0'));h.position.set(s*0.26,S.head*0.45,-S.head*0.1);h.rotation.z=s*1.1;head.add(h);}
  const tail=new THREE.Mesh(new THREE.CylinderGeometry(0.03,0.05,S.L*0.25,5),S.long?mb:m);tail.position.set(0,S.leg+S.H*0.42,S.L*0.55);tail.rotation.x=0.9;g.add(tail);
  const legs=[];for(const[x,z]of[[-1,-1],[1,-1],[-1,1],[1,1]]){const lg=new THREE.Group();lg.position.set(x*S.W*0.55,S.leg+0.05,z*S.L*0.38);const lm=new THREE.Mesh(new THREE.CylinderGeometry(S.W*0.13,S.W*0.1,S.leg+0.05,6),m);lm.position.y=-(S.leg+0.05)/2;lg.add(lm);const hf=new THREE.Mesh(new THREE.CylinderGeometry(S.W*0.1,S.W*0.12,0.06,6),dk);hf.position.y=-(S.leg+0.05);lg.add(hf);g.add(lg);legs.push(lg);}
  g.scale.setScalar((o&&o.s)||1);scene.add(g);return{g,body,head,tail,legs,ex:{},sp};}
const animalNat=animal;animal=function(sp,o){if(WILD[sp])return wildBuild(sp,o);return animalNat(sp,o);};
Object.assign(FAUNA_INFO,{
 deer:{A:['Ciervo','El animal de Ártemis cazadora. Acteón la vio bañarse en una fuente del Citerón y la diosa lo convirtió en ciervo: sus propios perros lo despedazaron. Jenofonte enseña a cazar ciervos con perros y redes.','Ovidio, Metamorfosis III 138-252; Jenofonte, Cinegético IX'],R:['Ciervo','El animal de Diana. En el bosque de Nemi, junto a su lago, se le ofrecen exvotos con forma de ciervo. Los romanos ricos los crían en sus cotos de caza, los vivaria.','Varrón, Sobre el campo III 13']},
 boar:{A:['Jabalí','El más temido de la caza. Heracles atrapó vivo al de Erimanto, y Meleagro mató al de Calidón, enviado por Ártemis. Odiseo tenía en la pierna la cicatriz de un jabalí, y por ella lo reconoció su nodriza.','Homero, Odisea XIX 390-466; Apolodoro II 5, 4'],R:['Jabalí','El plato fuerte de los banquetes: Petronio cuenta que en la cena de Trimalción sirvieron un jabalí entero con cestillos de dátiles colgando de los colmillos.','Petronio, Satiricón 40']},
 wolf:{A:['Lobo','El lobo es el animal de Apolo Liceo y de Zeus Liceo, en Arcadia. Según el mito, el rey Licaón ofreció a Zeus carne humana y fue convertido en lobo. Los pastores guardan los rebaños con perros molosos.','Ovidio, Metamorfosis I 209-243; Pausanias VIII 2, 3'],R:['Lobo','Una loba amamantó a Rómulo y Remo, y su estatua de bronce está en el Capitolio. En la lengua de los sabinos, el lobo se llama hirpus: de ahí los Hirpi Sorani, los «lobos de Sorano», sacerdotes del Soracte.','Livio I 4; Servio, Comentario a la Eneida XI 785']},
 bear:{A:['Oso','En Arcadia se cuenta que Calisto, compañera de Ártemis, fue convertida en osa; Zeus la subió al cielo como la Osa Mayor, y a su hijo Arcas, el padre de los arcadios, como el Guardián de la Osa.','Ovidio, Metamorfosis II 401-530; Pausanias VIII 3, 6-7'],R:['Oso','En los montes de Italia aún quedan osos. Muchos acaban en los juegos del anfiteatro: Marcial escribe epigramas sobre osos de la arena.','Marcial, Libro de los espectáculos']},
 hare:{A:['Liebre','La presa favorita de los cazadores a pie: Jenofonte dedica casi todo su tratado de caza a perseguirla con perros laconios. Una liebre era un regalo de amor típico entre los atenienses.','Jenofonte, Cinegético V-VI'],R:['Liebre','Los romanos la crían en cercados, los leporaria. Se decía que comer liebre hacía más guapo durante siete días, y Marcial se burla de ello.','Marcial V 29; Plinio, Historia natural XXVIII 260']},
 ox:{R:['Buey blanco del Clitumno','Virgilio dice que los rebaños blancos y los toros que se sacrifican en los triunfos se bañan en el río Clitumno, y que de ahí sale su blancura. Por eso los bueyes de esta comarca son tan buscados para los grandes sacrificios.','Virgilio, Geórgicas II 146-148'],A:['Buey','El buey ara y tira de los carros.','']}});
// ---- piezas del paisaje
// el sitio llano más cercano (desnivel pequeño en un círculo de radio rad), para fuentes, eras y fiestas: en una ladera el agua o un corro de gente quedan flotando
function flatNear(x,z,rad,maxR){rad=rad||3;maxR=maxR||60;const sl=(px,pz)=>{const c=terrainH(px,pz);let m=0;for(let i=0;i<6;i++){const a=i/6*TAU;m=Math.max(m,Math.abs(terrainH(px+Math.cos(a)*rad,pz+Math.sin(a)*rad)-c));}return m;};
  let best=[x,z],bs=sl(x,z);if(bs<rad*0.12)return best;for(let r=8;r<=maxR;r+=8)for(let i=0;i<10;i++){const a=i/10*TAU+r*0.37,px=x+Math.cos(a)*r,pz=z+Math.sin(a)*r;if(riverWater&&riverWater(px,pz)!==null)continue;if(!isFree(px,pz,rad))continue;const v=sl(px,pz);if(v<bs){bs=v;best=[px,pz];if(v<rad*0.12)return best;}}return best;}
function natSpring(x,z){[x,z]=flatNear(x,z,2.4,70);const gy=terrainH(x,z),g=grp(x,gy,z,0);for(let i=0;i<10;i++){const a=i/10*TAU,r=new THREE.Mesh(new THREE.DodecahedronGeometry(0.35+R()*0.25,0),M.stone);r.position.set(Math.cos(a)*1.9,terrainH(x+Math.cos(a)*1.9,z+Math.sin(a)*1.9)-gy+0.15,Math.sin(a)*1.9);g.add(r);}
  let lo=0;for(let i=0;i<8;i++){const a=i/8*TAU;lo=Math.min(lo,terrainH(x+Math.cos(a)*1.7,z+Math.sin(a)*1.7)-gy);}const w=new THREE.Mesh(new THREE.CircleGeometry(1.7,20),new THREE.MeshLambertMaterial({color:'#4f8a96',transparent:true,opacity:0.85}));w.rotation.x=-Math.PI/2;w.position.y=lo+0.12;g.add(w);addCirc(x,z,2);return g;}
function natAltar(x,z,col){const gy=terrainH(x,z),g=grp(x,gy,z,R()*TAU);box(1.4,1,1,lam(col||'#d8ccb4'),0,0.5,0,g);box(1.6,0.15,1.2,lam('#c8bca4'),0,1.05,0,g);addCirc(x,z,1);return g;}
function natAshAltar(x,z){const gy=terrainH(x,z),g=grp(x,gy,z,0);const c=new THREE.Mesh(new THREE.ConeGeometry(4,2.4,14),lam('#4a4440'));c.position.y=1.1;g.add(c);for(const s of[-1,1]){const p=new THREE.Mesh(new THREE.CylinderGeometry(0.35,0.4,5,10),lam('#d8ccb4'));p.position.set(s*3,2.5,-6);g.add(p);const e=new THREE.Mesh(new THREE.SphereGeometry(0.45,8,6),lam('#d6a640'));e.position.set(s*3,5.3,-6);g.add(e);addCirc(x+s*3,z-6,0.5);}addCirc(x,z,3.6);return g;}
function natKiln(x,z){const gy=terrainH(x,z),g=grp(x,gy,z,R()*TAU);const k=new THREE.Mesh(new THREE.ConeGeometry(2,2.4,10),lam('#5a4a3c'));k.position.y=1.2;g.add(k);const s=new THREE.Sprite(new THREE.SpriteMaterial({map:dustTex(),color:0x6a6460,transparent:true,opacity:0.5,depthWrite:false}));s.position.set(0,7,0);s.scale.set(5,10,1);g.add(s);addCirc(x,z,2.1);return g;}
function natReeds(x,z,n){const m=lam('#7a8a4a');for(let i=0;i<n;i++){const px=x+rr(-4,4),pz=z+rr(-4,4),h=rr(1.2,2.2),r=new THREE.Mesh(new THREE.CylinderGeometry(0.02,0.03,h,4),m);r.position.set(px,terrainH(px,pz)+h/2,pz);r.rotation.z=rr(-0.15,0.15);scene.add(r);}}
const NAT_FOREST=(I,n)=>forestBuild(I,n);   // bosques con sus especies, densos y con su historia (ver «BOSQUES»)
// ---- los mapas (definición con el sistema de «mapas de paso» de siempre)


Object.assign(SIMPLE_GR,{
 citeron:{label:'el Citerón',blobs:[[0,-170,330,170],[-280,140,200,90],[260,170,180,70]],site:[150,60,18],houses:2,spread:40,arr:[-380,-60],
  steles:[['citeron_monte','El Citerón','ΚΙΘΑΙΡΩΝ','La frontera entre el Ática y Beocia es este monte de pinos y pastos. Aquí suben los rebaños de los dos lados: en el Edipo rey de Sófocles, un pastor de Tebas y uno de Corinto se encuentran en el Citerón, y por eso el niño Edipo, abandonado aquí con los pies atados, acabó en Corinto. En este monte las mujeres de Tebas despedazaron a Penteo, según Las bacantes de Eurípides.']],
  extra(I){NAT_FOREST(I,620);const s=[I.x+40,I.z-120];caveMouth(s[0],s[1],0);natSpring(I.x-120,I.z+60);natAltar(I.x+150,I.z+60,'#cfc0a0');
   place('esfragitides','La cueva de las ninfas Esfragítides','ΣΦΡΑΓΙΤΙΔΕΣ','En una cueva del Citerón viven las ninfas Esfragítides, que en otro tiempo daban oráculos. Antes de la batalla de Platea (479 a.C.), el oráculo de Delfos mandó a los atenienses rezarles a ellas y a otros dioses del lugar, como cuenta Plutarco.',s[0]+8,s[1]+8,0);
   place('acteon','La fuente de Acteón','ΑΚΤΑΙΩΝ','Pausanias vio en el camino de Megara a Platea una roca a la que llamaban «el lecho de Acteón», donde el cazador dormía, y la fuente en la que vio a Ártemis bañándose. La diosa lo convirtió en ciervo y sus propios perros lo despedazaron.',I.x-110,I.z+72,0);
   place('menades','Las ménades','ΜΑΙΝΑΔΕΣ','Cada dos años, en invierno, grupos de mujeres suben de noche a los montes para celebrar a Dioniso con antorchas, danzas y tambores: es la oreibasía, la «subida al monte». Eurípides, que murió hace pocos años, la convirtió en tragedia en Las bacantes.',I.x+160,I.z+74,0);}},
 nemea:{label:_t(2425,'Nemea'),blobs:[[-260,-200,230,110],[270,-170,210,95],[0,320,200,60]],site:[0,-40,24],temple:{name:'Templo de Zeus Nemeo'},houses:5,spread:60,
  steles:[['juegos_nemeos','Los juegos de Nemea','ΝΕΜΕΑ','Cada dos años se celebran aquí juegos en honor de Zeus, uno de los cuatro grandes certámenes de Grecia. El premio es una corona de apio silvestre. Según el mito, los fundaron los Siete contra Tebas en memoria del niño Ofeltes, al que mató una serpiente junto a una fuente mientras su nodriza les daba de beber. El templo que ves es el antiguo; uno nuevo y más grande se levantará dentro de unos cincuenta años.']],
  extra(I){NAT_FOREST(I,380);caveMouth(I.x+250,I.z-120,Math.PI*0.9);caveMouth(I.x+262,I.z-150,Math.PI*0.2);natSpring(I.x-60,I.z+80);
   place('leon_nemea','La cueva del león','ΛΕΩΝ','En esta colina estaba, según el mito, la cueva de dos bocas del león de Nemea, cuya piel no atravesaba ninguna arma. Heracles tapó una entrada, entró por la otra y lo estranguló con los brazos: fue su primer trabajo. Desde entonces lleva su piel. Hoy no quedan leones en el Peloponeso; Heródoto dice que solo los hay en el norte, entre los ríos Nesto y Aqueloo.',I.x+238,I.z-112,0);}},
 liceo:{label:'el monte Liceo',blobs:[[0,-210,340,200],[-300,170,190,80],[290,190,170,60]],houses:3,spread:60,
  steles:[['licaon','Licaón','ΛΥΚΑΩΝ','Pausanias cuenta que el rey Licaón sacrificó a un niño en el altar de Zeus Liceo y que en el acto se convirtió en lobo. Ovidio lo narra así: Licaón sirvió carne humana a Zeus para probar si era un dios. Por eso la montaña y su dios llevan el nombre del lobo, lýkos.'],['calisto','Calisto y Arcas','ΚΑΛΛΙΣΤΩ','Calisto, cazadora del séquito de Ártemis, tuvo con Zeus un hijo, Arcas, el antepasado de los arcadios. Convertida en osa por los celos de Hera o por la ira de Ártemis, Zeus la subió al cielo como la Osa Mayor.']],
  extra(I){NAT_FOREST(I,520);natAshAltar(I.x,I.z-300);natAltar(I.x-120,I.z-60,'#cfc0a0');
   const pts=[];for(let i=0;i<=24;i++){const t=i/24;pts.push([I.x-I.R*1.1+t*I.R*2.2,I.z+150+Math.sin(t*5)*20]);}addRiver(pts,12,{dep:1.6,name:'Un arroyo de Arcadia'});natReeds(I.x+40,I.z+136,40);
   place('altar_ceniza','El altar de Zeus Liceo','ΖΕΥΣ ΛΥΚΑΙΟΣ','En la cumbre hay un altar hecho solo de la ceniza de los sacrificios, y delante, mirando al este, dos columnas con águilas doradas. Nadie puede entrar en el recinto sagrado; se dice que quien entra no proyecta sombra y muere antes de un año (Pausanias VIII 38, 6-7).',I.x+10,I.z-288,0);
   place('pan_arcadia','Pan, dios de Arcadia','ΠΑΝ','Arcadia es la tierra de Pan, el dios de los pastores, con patas y cuernos de cabra. En el monte Liceo tiene un santuario y aquí se celebran los juegos Liceos. Los arcadios dicen que, si la caza va mal, azotan su estatua.',I.x-110,I.z-48,0);}},
 tempe:{label:'el Tempe',blobs:[[0,-330,300,320],[0,330,280,220]],houses:3,spread:40,
  steles:[['tempe_valle',_t(2431,'El valle del Tempe'),'ΤΕΜΠΗ','Entre el Olimpo y el Osa, el río Peneo se abre paso por una garganta llena de plátanos, hiedra y laureles. Eliano lo describe como un lugar de sombra y fuentes donde los viajeros se paran a descansar. Por aquí pasa el camino de Tesalia a Macedonia; en el 480 a.C. los griegos vinieron a defenderlo de Jerjes, pero se retiraron.']],
  extra(I){NAT_FOREST(I,420);const pts=[];for(let i=0;i<=28;i++){const t=i/28;pts.push([I.x-I.R*1.15+t*I.R*2.3,I.z+Math.sin(t*4)*25]);}addRiver(pts,22,{dep:2.4,name:'El Peneo'});
   place('apolo_tempe','El laurel de Apolo','ΔΑΦΝΗ','Después de matar a la serpiente Pitón en Delfos, Apolo vino al Tempe a purificarse. Cada ocho años, un muchacho de Delfos hace el mismo camino y corta aquí el laurel para las coronas de los Juegos Píticos (Eliano, Historias varias III 1). Para los poetas, el laurel fue antes Dafne, hija del río.',I.x+40,I.z-50,0);}},
 parnaso:{label:'el Parnaso',blobs:[[0,-200,320,240],[-280,200,180,90],[280,180,170,70]],houses:2,spread:40,
  steles:[['parnaso_monte','El Parnaso','ΠΑΡΝΑΣΣΟΣ','El gran monte que domina Delfos, nevado medio año. Aquí se posó el arca de Deucalión y Pirra cuando bajaron las aguas del diluvio, y aquí viven las Musas, cerca de la fuente Castalia. Cada dos años, en invierno, las Tíades, mujeres de Atenas y de Delfos, suben a sus cumbres para celebrar a Dioniso.']],
  extra(I){NAT_FOREST(I,450);const s=[I.x-60,I.z-140];caveMouth(s[0],s[1],0.3);natAltar(s[0]+10,s[1]+12,'#cfc0a0');natSpring(I.x+120,I.z+40);
   place('coricia','La cueva Coricia','ΚΩΡΥΚΙΟΝ ΑΝΤΡΟΝ','Pausanias dice que es la cueva más hermosa que ha visto: está consagrada a Pan y a las ninfas Coricias, y por dentro se puede caminar largo rato sin antorcha. Los peregrinos dejan exvotos: figurillas, anillos y, sobre todo, tabas. Los arqueólogos han encontrado aquí más de veinte mil (Pausanias X 32, 2-7).',s[0]+12,s[1]+16,0);}}});
Object.assign(SIMPLE_RO,{
 nemi:{label:'Nemi',roman:true,blobs:[[0,-330,260,170],[0,330,260,150],[-330,0,210,150],[330,0,210,150]],lake:[0,0,165,145],site:[0,-215,22],rtemple:{name:'Templo de Diana Nemorense',W:14,L:24},houses:3,spread:40,arr:[-260,180],
  steles:[['rex_nemorensis','El rey del bosque','REX NEMORENSIS','El sacerdote de Diana en Nemi es siempre un esclavo fugitivo que ha matado a su predecesor y vigila espada en mano a que otro venga a matarlo a él. Estrabón lo cuenta, y Suetonio dice que a Calígula le pareció que el sacerdote de entonces llevaba demasiado tiempo en el cargo y le buscó un rival más fuerte.'],['speculum','El espejo de Diana','SPECVLVM DIANAE','Así llaman a este lago redondo, en el cráter de un antiguo volcán, rodeado de bosque. Calígula mandó construir aquí dos barcos enormes, verdaderos palacios flotantes; tras su muerte quedaron abandonados y hoy reposan en el fondo.']],
  extra(I){NAT_FOREST(I,450);natSpring(I.x+150,I.z-150);
   place('egeria','La fuente de Egeria','EGERIA','Egeria, una ninfa, aconsejaba de noche al rey Numa y le dictó las leyes sagradas de Roma. Cuando Numa murió, lloró tanto en este bosque que Diana la convirtió en una fuente. Aquí también se venera a Virbio: Hipólito, el hijo de Teseo, devuelto a la vida (Ovidio, Metamorfosis XV 482-551; Fastos III 261-276).',I.x+162,I.z-138,0);}},
 soracte:{label:'el Soracte',roman:true,blobs:[[0,-110,230,240]],site:[0,-110,14],rtemple:{name:'Templo de Apolo Sorano',W:10,L:16,pod:2},houses:3,spread:50,arr:[-300,200],
  steles:[['hirpi','Los Hirpi Sorani','HIRPI SORANI','Unas pocas familias del Soracte, los Hirpi Sorani, «lobos de Sorano», caminan descalzas sobre brasas en la fiesta de Apolo sin quemarse: por eso el Senado las ha librado del servicio militar y de otras cargas (Plinio, Historia natural VII 19). Virgilio pone en boca de un guerrero: «Apolo, guardián del Soracte… los tuyos pisan las brasas, fiados en su piedad» (Eneida XI 785-788).'],['soracte_nieve','La nieve del Soracte','SORACTE','Desde Roma se ve este monte solitario, blanco en invierno: Horacio empieza una oda famosa mirándolo cubierto de nieve y aconseja echar leña al fuego, sacar el vino de cuatro años y dejar lo demás a los dioses (Odas I 9).']],
  extra(I){NAT_FOREST(I,300);natAltar(I.x+20,I.z-60,'#d8ccb4');}},
 clitumno:{label:'el Clitumno',roman:true,blobs:[[-280,-220,220,80],[280,-200,200,70]],site:[30,-50,18],rtemple:{name:'Templo del dios Clitumno',W:9,L:14,pod:2},houses:4,spread:50,
  steles:[['clitumno_plinio','Las fuentes del Clitumno','FONS CLITVMNI','Plinio el Joven las describe en una carta: bajo una colina de cipreses brota el agua tan clara que se pueden contar las monedas y las piedrecitas del fondo. El templo es antiguo; dentro está el dios Clitumno vestido con la toga pretexta, y sus suertes escritas dan oráculos. Alrededor hay capillitas de otros dioses, y los visitantes escriben en las paredes alabanzas a la fuente (Cartas VIII 8).']],
  extra(I){NAT_FOREST(I,180);natSpring(I.x+10,I.z-80);const pts=[];for(let i=0;i<=22;i++){const t=i/22;pts.push([I.x+10+t*I.R*1.1,I.z-70+t*I.R*0.9+Math.sin(t*4)*10]);}addRiver(pts,14,{dep:1.4,name:'El Clitumno'});
   for(let i=0;i<3;i++)natAltar(I.x-30+i*18,I.z-90,'#e6dccb');}},
 sila:{label:'la Sila',roman:true,blobs:[[0,-200,300,170],[-280,180,200,110],[270,170,190,90]],houses:4,spread:60,
  steles:[['pix_bruttia','La pez de los brucios','PIX BRVTTIA','La Sila es un bosque inmenso de abetos y pinos, en las montañas de los brucios. De su madera se hacen barcos, y de su resina, la pez brucia, la mejor de Italia: sirve para calafatear los barcos y para impermeabilizar las ánforas de vino. Los romanos se quedaron con el bosque cuando vencieron a los brucios, aliados de Aníbal (Estrabón VI 1, 9; Plinio, Historia natural XIV 127).']],
  extra(I){NAT_FOREST(I,800);for(let i=0;i<4;i++)natKiln(I.x-120+i*60,I.z+90+(i%2)*20);natAltar(I.x+80,I.z-60,'#b8a888');
   place('silvano',_t(4691,'Silvano'),'SILVANVS','En el bosque, un altar rústico de Silvano, el dios de los bosques y de los límites de los campos: lo veneran los leñadores, los pastores y los esclavos. Se le ofrecen uvas, espigas, leche y, a veces, un cerdo. Virgilio lo llama dios de los campos y del ganado (Eneida VIII 600-601).',I.x+92,I.z-48,0);}}});
// ---- ninfas y divinidades del lugar: aparecen junto a su cueva o su fuente, con un leve resplandor
const NAT_NY={
 citeron:{dx:40,dz:-108,n:'Ninfa Esfragítide',s:'de la cueva del Citerón',c:'#dfe9e6',t:'<p>«¿Vienes a consultarnos, como hacían antes? Ya no damos oráculos, pero los pastores aún nos dejan leche y miel a la entrada de la cueva.»</p><p>Las ninfas eran divinidades menores de la naturaleza: de las fuentes (náyades), de los árboles (dríades), de los montes (oréades). Vivían muchísimo, pero no eran inmortales.</p>',src:'Pausanias IX 3, 9; Plutarco, Arístides 11'},
 nemea:{dx:-60,dz:92,n:_t(2425,'Nemea'),s:'la ninfa del valle',c:'#e6e2c8',t:'<p>«Soy Nemea, hija del río Asopo: el valle lleva mi nombre. Junto a esta fuente murió el pequeño Ofeltes, y por él se celebran los juegos. ¿Ves el apio silvestre que crece en la orilla? Con él se tejen las coronas de los vencedores.»</p>',src:'Pausanias II 15, 3; Apolodoro III 6, 4'},
 liceo:{dx:40,dz:140,n:'Siringe',s:'náyade de Arcadia',c:'#d8e8d0',t:'<p>«Pan me persiguió hasta la orilla del Ladón, otro río de Arcadia. Pedí ayuda a mis hermanas del agua y me convirtieron en cañas. Cuando Pan las abrazó, el viento sonó entre ellas, y él las cortó y las unió con cera: así nació la flauta que lleva mi nombre, la siringa.»</p>',src:'Ovidio, Metamorfosis I 689-712'},
 tempe:{dx:40,dz:-62,n:'Dafne',s:'la hija del Peneo',c:'#d6e6c4',t:'<p>«Apolo me persiguió por este valle. Cuando ya me alcanzaba, pedí a mi padre, el río Peneo, que me quitara esta figura, y me convertí en laurel. Desde entonces Apolo lleva mis hojas en la cabeza, y los vencedores de Delfos también.»</p><p class="sub">Ovidio sitúa el mito en el Tempe; otros autores, en Arcadia.</p>',src:'Ovidio, Metamorfosis I 452-567'},
 parnaso:{dx:-40,dz:-124,n:'Ninfa Coricia',s:'de la cueva de Pan',c:'#e2e0ec',t:'<p>«Bienvenido a nuestra cueva. Los peregrinos de Delfos suben hasta aquí y nos dejan tabas, la mayoría pintadas o agujereadas, y figurillas de barro. Pan toca la siringa por las noches, y las Musas bajan a veces de las cumbres.»</p>',src:'Pausanias X 32, 2-7'},
 nemi:{dx:160,dz:-126,n:'Egeria',s:'la ninfa de la fuente',c:'#dbe8ee',t:'<p>«Aconsejé de noche al rey Numa, el segundo rey de Roma, y le enseñé los ritos con los que se honra a los dioses. Cuando murió, lloré tanto que Diana me convirtió en esta fuente. Las mujeres que esperan un hijo vienen al bosque con antorchas a pedir a Diana un buen parto.»</p>',src:'Ovidio, Metamorfosis XV 482-551; Fastos III 261-276'},
 soracte:{dx:30,dz:-40,n:'Feronia',s:'diosa del bosque del Soracte',c:'#e8e0c8',t:'<p>«Al pie del monte está mi bosque sagrado. A mí me rezan los libertos: en mi templo de Terracina, los esclavos que se liberan reciben el gorro de la libertad. Aquí, en mi fiesta, los Hirpi caminan sobre las brasas.»</p><p class="sub">Estrabón sitúa el paso por las brasas en la fiesta de Feronia; Plinio y Virgilio, en la de Apolo Sorano.</p>',src:'Estrabón V 2, 9; Servio, Comentario a la Eneida VIII 564'},
 clitumno:{dx:24,dz:-66,n:'Náyade del Clitumno',s:'de las fuentes',c:'#d8ecf0',t:'<p>«Mira el fondo: cuenta las monedas que han echado los visitantes. Más abajo, el río está consagrado: aguas arriba del puente solo se puede ir en barca; aguas abajo, cualquiera puede bañarse.»</p>',src:'Plinio el Joven, Cartas VIII 8'},
 sila:{dx:92,dz:-70,n:_t(4691,'Silvano'),s:'dios de los bosques',c:'#d4ccb4',g:'old',t:'<p>«No soy una ninfa: soy Silvano, viejo como los árboles. Los leñadores me piden permiso antes de talar, y los pastores, que guarde sus rebaños del lobo. Respeta mis árboles, forastero, y te dejaré pasar.»</p><p class="sub">Silvano se representa como un viejo con una rama de pino o una hoz de podar, y a menudo con un perro.</p>',src:'Virgilio, Eneida VIII 600-601; Horacio, Epodos 2, 21-22'}};
const NAT_FA={citeron:[['deer',3,-150,40,60],['wolf',2,60,-60,80],['goat',4,200,100,50]],nemea:[['hare',3,-80,120,60],['boar',1,220,-60,60],['goat',4,-200,60,60]],liceo:[['bear',1,-120,-140,60],['wolf',3,140,-80,80],['goat',6,-220,160,60]],
 tempe:[['deer',3,-120,60,60],['goat',3,160,-60,50]],parnaso:[['wolf',2,100,-120,80],['goat',5,-160,120,60]],nemi:[['deer',3,-120,-200,60],['boar',2,200,-180,60]],soracte:[['wolf',3,-120,80,60],['goat',3,120,60,50]],
 clitumno:[['ox',5,120,60,40],['hare',2,-160,80,50]],sila:[['wolf',3,-120,-80,70],['deer',2,140,80,60],['bear',1,40,-200,60],['boar',2,-200,160,60]]};
const NAT={ny:[]};
function natz(){if(!state.nat||typeof state.nat!=='object')state.nat={};return state.nat;}
// ---- más mapas de transición (segunda tanda): Pentélico, Eta, Aqueloo, Taigeto y rocas Escironias; Silva Ciminia, Horcas Caudinas, canteras de Luna, delta del Po y Rubicón
Object.assign(MED_POS,{pentelico:[23.89,38.08],eta:[22.25,38.8],achelous:[21.3,38.7],taigeto:[22.35,36.95],escironides:[23.15,37.93]});
Object.assign(MED_POS_RO,{ciminia:[12.2,42.4],caudium:[14.55,41.05],lunae:[10.1,44.08],padus:[12.15,44.95],rubico:[12.4,44.1]});
function natBlocks(x,z,n){const m=lam('#efece4');for(let i=0;i<n;i++){const px=x+rr(-25,25),pz=z+rr(-15,15),w=rr(1.5,3.2),h=rr(1,2),d=rr(1.5,3);box(w,h,d,m,px,terrainH(px,pz)+h/2,pz);addBox(px,pz,w,d,0);}
  for(let k=0;k<4;k++){const zz=z-40-k*8,W=40-k*6;let lo=1e9,hi=-1e9;for(let u=-0.5;u<=0.5;u+=0.125){const h=terrainH(x+u*W,zz);lo=Math.min(lo,h);hi=Math.max(hi,h);}const H=hi-lo+5;box(W,H,2,m,x,lo-0.3+H/2,zz);}}   /* cada grada arranca de lo más bajo bajo su anchura */
function natHives(x,z,n){for(let i=0;i<n;i++){const px=x+(i%4)*2.4,pz=z+Math.floor(i/4)*2.4,g=grp(px,terrainH(px,pz),pz,0),c=new THREE.Mesh(new THREE.CylinderGeometry(0.35,0.4,0.9,10),lam('#b8885a'));c.rotation.z=Math.PI/2;c.position.y=0.55;g.add(c);box(0.8,0.2,0.8,lam('#8a7a62'),0,0.1,0,g);addCirc(px,pz,0.5);}}
function natPyre(x,z){const gy=terrainH(x,z),g=grp(x,gy,z,0);for(let i=0;i<6;i++){const l=new THREE.Mesh(new THREE.CylinderGeometry(0.15,0.15,3.4,6),lam('#3a2a1e'));l.rotation.z=Math.PI/2;l.rotation.y=i*0.5;l.position.y=0.3+i*0.28;g.add(l);}const a=new THREE.Mesh(new THREE.ConeGeometry(2.6,0.9,12),lam('#3e3834'));a.position.y=0.3;g.add(a);addCirc(x,z,2.4);}
function natPoplars(x,z,n){const tr=new THREE.MeshLambertMaterial({color:'#5a4a38'}),lf=new THREE.MeshLambertMaterial({color:'#6a8a3a'});for(let i=0;i<n;i++){const px=x+rr(-40,40),pz=z+rr(-20,20),gy=terrainH(px,pz),h=rr(9,14);const t=new THREE.Mesh(new THREE.CylinderGeometry(0.18,0.28,h,6),tr);t.position.set(px,gy+h/2,pz);scene.add(t);const c=new THREE.Mesh(new THREE.CylinderGeometry(0.6,1.4,h*0.75,8),lf);c.position.set(px,gy+h*0.62,pz);scene.add(c);addCirc(px,pz,0.4);}}
Object.assign(SIMPLE_GR,{
 pentelico:{label:'el Pentélico',blobs:[[0,-200,320,170],[-300,150,180,60]],houses:3,spread:50,
  steles:[['pan_filipides','Pan y Filípides','ΠΑΝ','Antes de la batalla de Maratón, el corredor Filípides iba a Esparta a pedir ayuda y, en un monte de Arcadia, se le apareció Pan: le preguntó por qué los atenienses no le hacían caso si él siempre les había sido favorable. Tras la victoria, Atenas le dedicó una cueva bajo la Acrópolis, con sacrificios y una carrera de antorchas cada año (Heródoto VI 105).'],['pentelico_marmol','El mármol del Pentélico','ΠΕΝΤΕΛΗ','De estas laderas sale el mármol blanco, de grano fino, del Partenón y de los Propileos: al sol se vuelve dorado por el hierro que tiene. Y en las faldas del monte, como en el cercano Himeto, hay colmenas: la miel del Ática es la más famosa de Grecia.']],
  extra(I){NAT_FOREST(I,300);caveMouth(I.x+150,I.z-60,Math.PI*0.6);natHives(I.x-150,I.z+80,8);natBlocks(I.x-20,I.z-170,8);
   place('cueva_pan_maraton','La cueva de Pan','ΠΑΝΟΣ ΣΠΗΛΑΙΟΝ','Pausanias describe, cerca de Maratón, una cueva de Pan cuya entrada es estrecha y que por dentro tiene salas y bañeras, y unas rocas que parecen cabras: «el rebaño de Pan» (Pausanias I 32, 7).',I.x+162,I.z-48,0);}},
 eta:{label:'el Eta',blobs:[[0,-180,320,220],[-280,170,180,80]],houses:2,spread:40,
  steles:[['pira_heracles','La pira de Heracles','ΠΥΡΑ','Envenenado por la túnica que le dio Deyanira, empapada en la sangre del centauro Neso, Heracles subió al Eta, mandó levantar una pira y se tendió encima. Solo Filoctetes se atrevió a encenderla, y Heracles le dio su arco. Del fuego subió al Olimpo como dios (Sófocles, Las traquinias; Diodoro IV 38). En la cumbre hay un santuario donde aún se queman ofrendas.'],['eta_anopea','El sendero de Efialtes','ΑΝΟΠΑΙΑ','Por un sendero de estos montes, la Anopea, un pastor llamado Efialtes guio a los persas de noche para rodear a Leónidas y a los suyos en las Termópilas (Heródoto VII 213-218).']],
  extra(I){NAT_FOREST(I,450);natPyre(I.x,I.z-300);natSpring(I.x+120,I.z+60);}},
 achelous:{label:'el Aqueloo',blobs:[[-300,-220,220,90],[300,-200,200,80]],houses:4,spread:50,
  steles:[['aqueloo_rio','El Aqueloo','ΑΧΕΛΩΙΟΣ','El río más largo de Grecia, frontera entre Etolia y Acarnania. Arrastra tanto barro que va uniendo al continente las islas de su desembocadura, las Equínades, como explica Tucídides (II 102). Su dios es el padre de muchas ninfas y de las Sirenas; en todo el mundo griego se le hacen ofrendas como al más venerable de los ríos.']],
  extra(I){NAT_FOREST(I,320);const pts=[];for(let i=0;i<=28;i++){const t=i/28;pts.push([I.x+Math.sin(t*5)*30,I.z-I.R*1.15+t*I.R*2.3]);}addRiver(pts,34,{dep:2.8,name:'El Aqueloo'});natReeds(I.x+30,I.z+40,40);}},
 taigeto:{label:'el Taigeto',blobs:[[0,-150,330,260],[-300,200,170,80]],houses:2,spread:40,
  steles:[['taigeto_monte','El Taigeto','ΤΑΫΓΕΤΟΣ','La gran sierra que separa Laconia de Mesenia, nevada hasta la primavera. Debe su nombre a Taigete, una de las Pléyades, madre de Lacedemón. Aquí cazan los espartanos con sus perros laconios, y en la cumbre del Taleto sacrifican caballos al Sol (Pausanias III 1, 2 y III 20, 4).'],['caiadas','El Céadas','ΚΑΙΑΔΑΣ','En una sima del Taigeto, el Céadas, los espartanos arrojaban a los condenados a muerte; Tucídides dice que quisieron arrojar allí al regente Pausanias (I 134). Plutarco cuenta además que los recién nacidos débiles se abandonaban en un barranco del monte, las Apótetas; hoy los historiadores discuten hasta qué punto era así.']],
  extra(I){NAT_FOREST(I,520);natAltar(I.x+40,I.z-320,'#cfc0a0');caveMouth(I.x-160,I.z-60,0.4);}},
 escironides:{label:'las rocas Escironias',blobs:[[0,-200,360,230]],houses:2,spread:40,
  steles:[['esciron','Escirón','ΣΚΙΡΩΝ','El camino de Megara al Istmo va colgado sobre el mar, al pie de estos acantilados. Aquí esperaba el bandido Escirón: obligaba a los viajeros a lavarle los pies y, cuando se agachaban, los tiraba de una patada al mar, donde se los comía una tortuga gigante. Teseo, camino de Atenas, le hizo lo mismo (Plutarco, Teseo 10; Pausanias I 44, 8).']],
  extra(I){NAT_FOREST(I,260);
   place('roca_moluris','La roca Moluríade','ΜΟΛΟΥΡΙΣ','Desde esta roca se arrojó al mar Ino con su hijo Melicertes, huyendo de su marido enloquecido. Los dioses del mar la acogieron: ella se convirtió en Leucótea, la «diosa blanca» que ayuda a los náufragos, y el niño en Palemón, en cuyo honor se fundaron los juegos Ístmicos (Pausanias I 44, 7-8).',I.x+60,I.z+60,0);}}});
Object.assign(SIMPLE_RO,{
 ciminia:{label:'la Silva Ciminia',roman:true,blobs:[[0,-220,300,150],[-280,180,190,80],[280,170,170,70]],lake:[160,120,90,70],houses:3,spread:40,
  steles:[['ciminia_livio','El bosque Ciminio','SILVA CIMINIA','Livio escribe que en el 310 a.C. este bosque era más impenetrable y espantoso que lo son hoy los bosques de Germania, y que ningún comerciante lo había cruzado nunca. El cónsul Fabio mandó a su hermano, disfrazado de pastor etrusco, a explorarlo antes de atravesarlo con el ejército (Livio IX 36-37).'],['lago_vico','El lago Ciminio','LACVS CIMINIVS','Según una leyenda, Hércules desafió a los del lugar a arrancar del suelo la clava que había clavado; como nadie pudo, la sacó él, y del agujero brotó el agua que formó el lago (Servio, Comentario a la Eneida VII 697).']],
  extra(I){NAT_FOREST(I,700);natAltar(I.x-100,I.z-40,'#b8a888');}},
 caudium:{label:'las Horcas Caudinas',roman:true,blobs:[[-260,0,240,170],[260,0,240,170]],houses:3,spread:40,
  steles:[['furculae','Las Horcas Caudinas','FVRCVLAE CAVDINAE','En este valle cerrado por dos desfiladeros, en el 321 a.C., los samnitas atraparon a un ejército romano entero. Para dejarlos marchar, obligaron a los soldados a pasar desarmados, uno a uno, bajo un yugo de lanzas: la mayor humillación de la historia de Roma, que Livio cuenta con todo detalle (IX 2-6). De ahí viene nuestra expresión «pasar por las horcas caudinas».']],
  extra(I){NAT_FOREST(I,420);const g=grp(I.x,terrainH(I.x,I.z+40),I.z+40,0);for(const s of[-1,1])box(0.12,2.2,0.12,M.wood,s*1.1,1.1,0,g);box(2.6,0.12,0.12,M.wood,0,2.15,0,g);natAltar(I.x+40,I.z-60,'#d8ccb4');}},
 lunae:{label:'las canteras de Luna',roman:true,blobs:[[0,-200,320,250],[-280,180,170,80]],houses:4,spread:50,
  steles:[['marmor_lunense','El mármol de Luna','MARMOR LVNENSE','Estos montes son de mármol blanco y gris azulado, en bloques tan grandes que se sacan columnas de una sola pieza: Estrabón cuenta que los bajan al puerto de Luna y por mar llegan a Roma (V 2, 5). Con él se ha revestido media ciudad: Augusto presumía de haber encontrado una Roma de ladrillo y dejarla de mármol (Suetonio, Augusto 28).']],
  extra(I){NAT_FOREST(I,260);natBlocks(I.x,I.z-120,14);natBlocks(I.x+120,I.z-40,8);}},
 padus:{label:'el delta del Po',roman:true,blobs:[[-320,-260,180,40]],houses:4,spread:50,
  steles:[['faeton','Faetonte y las Helíades','ERIDANVS','Faetonte, hijo del Sol, perdió el control del carro de su padre y Júpiter lo derribó con un rayo: cayó en el Erídano, que es el Po. Sus hermanas, las Helíades, lo lloraron tanto en la orilla que se convirtieron en chopos, y sus lágrimas, endurecidas por el sol, en ámbar (Ovidio, Metamorfosis II 319-366). Plinio se burla de esta historia: el ámbar viene de las costas del norte (Historia natural XXXVII 31-32).']],
  extra(I){const pts=[];for(let i=0;i<=28;i++){const t=i/28;pts.push([I.x-I.R*1.15+t*I.R*2.3,I.z+Math.sin(t*3)*30]);}addRiver(pts,48,{dep:2.8,name:'El Po'});const p2=[];for(let i=0;i<=20;i++){const t=i/20;p2.push([I.x+t*I.R*1.1,I.z+60+t*160]);}addRiver(p2,22,{dep:2,name:'Un brazo del Po'});
   natPoplars(I.x-80,I.z-60,24);natReeds(I.x+60,I.z+40,60);natReeds(I.x-140,I.z+50,40);}},
 rubico:{label:'el Rubicón',roman:true,blobs:[[-300,-240,200,60],[300,-260,200,50]],houses:5,spread:60,
  steles:[['alea','La suerte está echada','ALEA IACTA EST','En enero del 49 a.C., Julio César llegó aquí con una legión. El Rubicón era la frontera de su provincia: cruzarlo armado era declarar la guerra a la República. Suetonio cuenta que dudó largo rato y que al final dijo: «Echada está la suerte» (Julio 31-32). Hoy no se sabe con seguridad cuál de los riachuelos de la zona era el Rubicón.']],
  extra(I){NAT_FOREST(I,160);const pts=[];for(let i=0;i<=24;i++){const t=i/24;pts.push([I.x+Math.sin(t*4)*15,I.z-I.R*1.1+t*I.R*2.2]);}addRiver(pts,10,{dep:1.3,name:_t(4862,'El Rubicón')});}}});
Object.assign(NAT_NY,{
 pentelico:{dx:150,dz:-48,n:'Pan',s:'el dios de los pastores',c:'#8a6a4a',g:'old',t:'<p>Una figura con patas de cabra y cuernos te mira desde la entrada de la cueva y toca unas notas en su siringa. «Los atenienses tardaron en hacerme caso, ¿sabes? Hasta que les ayudé en Maratón. Cuando de repente os entra un miedo sin motivo en el monte, eso es cosa mía: el pánico.»</p>',src:'Heródoto VI 105; Pausanias I 32, 7'},
 eta:{dx:30,dz:-280,n:'Oréade del Eta',s:'ninfa de la montaña',c:'#e4dcd0',t:'<p>«Desde aquí vimos subir el humo de la pira y a Heracles alzarse hacia el Olimpo. Los de Traquis aún suben cada año a quemar ofrendas en la cumbre, y los pastores te enseñarán el sendero por el que los persas rodearon a Leónidas.»</p>',src:'Sófocles, Las traquinias 1191-1278'},
 achelous:{dx:40,dz:30,n:'Aqueloo',s:'el dios del río',c:'#6a7a7a',g:'old',t:'<p>Un viejo de barba verdosa, con un solo cuerno en la frente, sale del agua. «Luché con Heracles por Deyanira. Me convertí en serpiente y en toro, y aun así me venció: me arrancó un cuerno. Las náyades lo llenaron de frutos y flores, y ahora es el cuerno de la abundancia.»</p>',src:'Ovidio, Metamorfosis IX 1-97; Sófocles, Las traquinias 9-21'},
 taigeto:{dx:40,dz:-300,n:'Taigete',s:'la Pléyade del monte',c:'#e6e0d0',t:'<p>«Soy Taigete, hija de Atlas. Huyendo de Zeus, Ártemis me escondió convirtiéndome en cierva; en agradecimiento le consagré una cierva de cuernos de oro, la que Heracles tuvo que atrapar. Ahora brillo en el cielo con mis seis hermanas: las Pléyades. Cuando salen, empieza la siega.»</p>',src:'Pausanias III 1, 2; Píndaro, Olímpica III 29-30; Hesíodo, Trabajos y días 383-384'},
 escironides:{dx:70,dz:72,n:'Leucótea',s:'la diosa blanca del mar',c:'#e8f0f4',t:'<p>«Fui Ino, una mortal. Desde esta roca me tiré al mar con mi hijo en brazos, y los dioses me hicieron una de ellos. Cuando un barco está a punto de hundirse, a veces aparezco: a Odiseo le di mi velo para que no se ahogara.»</p>',src:'Homero, Odisea V 333-353; Pausanias I 44, 7-8'},
 ciminia:{dx:-100,dz:-28,n:_t(4677,'Fauno'),s:'el dios de los bosques del Lacio',c:'#8a6a4a',g:'old',t:'<p>«Soy Fauno: los griegos me llaman Pan. Doy oráculos en los bosques, de noche, a quien duerme sobre las pieles de los animales sacrificados. Mis fiestas son las Lupercales, en febrero, cuando los lupercos corren por Roma.»</p>',src:'Virgilio, Eneida VII 81-101; Ovidio, Fastos II 267-452'},
 caudium:{dx:40,dz:-46,n:'El genio del lugar',s:'Genius loci',c:'#d8ccb4',g:'old',t:'<p>«Cada sitio tiene su genio, su espíritu protector: un valle, una fuente, una ciudad. A veces me dejo ver como una serpiente, como cuando Eneas sacrificaba en la tumba de su padre. Los romanos escriben en sus altares: GENIO LOCI, “al genio del lugar”, por si acaso no saben qué dios vive allí.»</p>',src:'Virgilio, Eneida V 84-96; inscripciones votivas'},
 lunae:{dx:20,dz:-60,n:'Oréade de los montes de Luna',s:'ninfa del mármol',c:'#f0f0ec',t:'<p>«Los canteros cortan la montaña a golpe de cuña, y las vetas blancas se llevan a Roma por mar. A veces les pido que dejen algo para mí: en estos montes nadie sube sin dejar una ofrenda.»</p>',src:'Estrabón V 2, 5; Plinio, Historia natural XXXVI 14'},
 padus:{dx:-80,dz:-50,n:'Las Helíades',s:'hermanas de Faetonte',c:'#d6e0b4',t:'<p>Entre los chopos, unas voces de muchacha: «Somos las hijas del Sol. Lloramos a nuestro hermano Faetonte, que cayó en este río, hasta que la corteza nos cubrió. Mira las gotas de ámbar en nuestras ramas: son nuestras lágrimas.»</p>',src:'Ovidio, Metamorfosis II 319-366'},
 rubico:{dx:30,dz:20,n:'La Patria',s:'según el poeta Lucano',c:'#e8e0d0',t:'<p>Una mujer gigantesca, con el pelo blanco y la corona de torres de Roma, aparece de noche junto al río. «¿Adónde vais? ¿Adónde lleváis mis estandartes? Si venís como ciudadanos, hasta aquí podéis llegar.» Así describe el poeta Lucano la visión que tuvo César antes de cruzar el Rubicón.</p>',src:'Lucano, Farsalia I 183-227'}});
Object.assign(NAT_FA,{pentelico:[['goat',5,-120,100,60],['hare',2,100,60,60]],eta:[['wolf',2,-80,-60,80],['deer',2,120,40,60],['goat',3,-160,140,50]],achelous:[['boar',2,-160,-100,60],['ox',3,140,120,50]],
 taigeto:[['deer',3,-100,-60,70],['boar',2,140,-100,60],['wolf',2,60,80,70],['goat',3,-200,180,50]],escironides:[['goat',4,-80,-40,60]],ciminia:[['boar',3,-120,-100,70],['deer',2,120,-60,60],['wolf',2,-60,140,70]],
 caudium:[['goat',4,-160,60,60],['wolf',1,180,-60,60]],lunae:[['goat',4,-120,80,60]],padus:[['hare',3,-120,90,60],['deer',2,140,-90,60]],rubico:[['ox',3,-120,80,50],['hare',2,120,-60,50]]});

// dentro de un edificio (su planta rectangular, aunque por dentro, en el patio, no haya muros que choquen)
function inBuilding(x,z){for(const f of footprints){if(!f.w||!f.house)continue;const c=Math.cos(f.a||0),s=Math.sin(f.a||0),dx=x-f.x,dz=z-f.z,u=dx*c-dz*s,v=dx*s+dz*c;if(Math.abs(u)<f.w/2+1&&Math.abs(v)<f.d/2+1)return true;}return false;}
function natSetup(){NAT.ny.length=0;for(const id in NAT_NY){const I=ISLANDS.find(q=>q.id===id);if(!I)continue;const N=NAT_NY[id];let p=findFree(I.x+N.dx,I.z+N.dz,1)||[I.x+N.dx,I.z+N.dz];
  if(inBuilding(p[0],p[1])){out:for(let r=6;r<=60;r+=6)for(let k=0;k<12;k++){const a=k/12*TAU,x=I.x+N.dx+Math.cos(a)*r,z=I.z+N.dz+Math.sin(a)*r;if(!inBuilding(x,z)&&isFree(x,z,1)&&terrainH(x,z)>0.5){p=[x,z];break out;}}}
    const g=makePerson(N.g==='old'?{chiton:'#8a7a5a',himation:'#5a4a30',hair:'#d8d2c8',beard:true}:{female:true,chiton:N.c,himation:'#a8c8c8',hair:'#5a3a24'});
    g.traverse(o=>{if(o.isMesh&&o.material){o.material=o.material.clone();o.material.transparent=true;o.material.opacity=0.82;if(o.material.emissive)o.material.emissive.set('#26302c');}});
    const gl=new THREE.Sprite(new THREE.SpriteMaterial({map:TORCH_TEX,color:0xcfe6ff,transparent:true,opacity:0.35,depthWrite:false,blending:THREE.AdditiveBlending}));gl.scale.set(2.6,3.6,1);gl.position.y=1.1;g.add(gl);
    g.position.set(p[0],floorAt(p[0],p[1]),p[1]);g.rotation.y=R()*TAU;scene.add(g);NAT.ny.push({id,g,y:g.position.y,ph:R()*6});egxObj(p[0],p[1],undefined,'nat:'+id,N.n,N.s,3.2);}
  for(const id in NAT_FA){const I=ISLANDS.find(q=>q.id===id);if(!I)continue;for(const[sp,n,dx,dz,r]of NAT_FA[id])for(let i=0;i<n;i++){const x=I.x+dx+rr(-r/2,r/2),z=I.z+dz+rr(-r/2,r/2);try{faunaAdd(sp,x,z,{r,beh:'wander'});}catch(e){}}}}
function natTick(dt){const t=performance.now()/1000;for(const N of NAT.ny){if(Math.abs(N.g.position.x-player.x)>300)continue;N.g.position.y=N.y+0.25+Math.sin(t*1.2+N.ph)*0.12;N.g.rotation.y+=dt*0.15;}}
function natAct(o){const id=o.act.slice(4),N=NAT_NY[id];if(!N)return;const s=natz(),first=!s[id];
  vmS(N.g==='old'?'♣':'❦',N.n,N.s,N.t+'<p class="sub">Fuente: '+N.src+'. El juego muestra lo que creían los antiguos.'+(first?' <b>+1 '+(MODE==='roma'?'Sapientia':'Sophía')+' y +1 '+(MODE==='roma'?'Pietas':'Eusébeia')+'</b>':'')+'</p>',[[MODE==='roma'?'Dejar una ofrenda de leche y flores':'Dejar una ofrenda de leche y miel',()=>{if(!s[id]){s[id]=1;qAdd('so',1);qAdd('eu',1);save();}closeDialog();toast('Dejas tu ofrenda junto a la '+(N.g==='old'?'piedra del altar':'fuente')+'. Por un momento te parece oír una risa entre los árboles.');},'quiz'],vmBye]);}

// ---- el camino en los mapas de transición: hermas, montones de Hermes, posadas, fortines, miliarios, tumbas y viajeros (todo documentado)
function natHerm(x,z,a){const gy=terrainH(x,z),g=grp(x,gy,z,a||0),m=lam('#e6dccb');box(0.5,1.6,0.42,m,0,0.8,0,g);const h=new THREE.Mesh(new THREE.SphereGeometry(0.28,10,8),m);h.position.y=1.9;g.add(h);box(0.36,0.22,0.08,m,0,2.0,0.22,g);addCirc(x,z,0.5);}
function natCairn(x,z){const gy=terrainH(x,z),g=grp(x,gy,z,0);for(let i=0;i<18;i++){const r=new THREE.Mesh(new THREE.DodecahedronGeometry(0.22+R()*0.2,0),M.stone);const k=i/18;r.position.set(rr(-0.9,0.9)*(1-k),k*1.4,rr(-0.9,0.9)*(1-k));g.add(r);}addCirc(x,z,1);}
function natInn(x,z,a,roman){const gy=minGround(x,z,10.5,8,a||0)-0.05,g=grp(x,gy,z,a||0);   /* apoyada en el punto más bajo de su planta: no cuelga en las laderas */box(10,4,7,lam(roman?'#e3d8c2':'#d8ccb0'),0,2,0,g);gableRoof(g,10.6,7.6,4,1.6,M.tile,lam('#c9bc9f'),true);box(1.4,2.4,0.2,lam('#4a3424'),0,1.2,3.55,g);box(6,0.2,2.4,M.wood,0,2.6,4.6,g);for(const s of[-1,1])box(0.18,2.6,0.18,M.wood,s*2.8,1.3,5.7,g);
  const sg=box(1.2,0.6,0.08,lam('#c9a46a'),2.2,3.2,3.6,g);addBox(x,z,10,7,a||0);return g;}
function natTower(x,z){const gy=minGround(x,z,7,7,0)-0.05,g=grp(x,gy,z,0),m=lam('#b8ab94');const t=new THREE.Mesh(new THREE.CylinderGeometry(3.2,3.4,9,14),m);t.position.y=4.5;g.add(t);for(let i=0;i<7;i++){const a=i/7*TAU;box(5,2.6,1.2,m,Math.cos(a)*9,1.3,Math.sin(a)*9,g).rotation.y=-a;}addCirc(x,z,3.5);}
function natMile(x,z){const gy=terrainH(x,z),g=grp(x,gy,z,0),m=lam('#d8ccb0');const c=new THREE.Mesh(new THREE.CylinderGeometry(0.32,0.34,2,12),m);c.position.y=1;g.add(c);box(0.8,0.3,0.8,m,0,0.15,0,g);addCirc(x,z,0.5);}
function natTomb(x,z,a){const gy=terrainH(x,z),g=grp(x,gy,z,a||0),m=lam('#d6cbb2');box(4,3,4,m,0,1.5,0,g);const d=new THREE.Mesh(new THREE.CylinderGeometry(1.6,1.8,2.4,14),m);d.position.y=4.2;g.add(d);box(1.4,0.8,0.1,lam('#efe8d8'),0,2.2,2.05,g);addBox(x,z,4,4,a||0);}
const NAT_ROAD={
 pentelico:I=>{const a=I.arrive;natHerm(a.x+30,a.z+18,0);place('herma_hiparco','Una herma de Hiparco','ΕΡΜΗΣ','Hiparco, hijo del tirano Pisístrato, mandó poner hermas a mitad de camino entre Atenas y cada demo, con versos para educar a los caminantes. En una se lee: «Monumento de Hiparco: camina pensando cosas justas»; en otra: «No engañes a un amigo» (Hiparco, diálogo atribuido a Platón, 228d-229a).',a.x+36,a.z+24,0);},
 citeron:I=>{const a=I.arrive;natHerm(a.x+30,a.z+18,0);natTower(I.x-60,I.z-30);place('enoe','La fortaleza de Énoe','ΟΙΝΟΗ','En el camino del Citerón, en la frontera con Beocia, los atenienses tienen un fortín amurallado: Énoe. Tucídides cuenta que fue lo primero que atacaron los espartanos al invadir el Ática en el 431 a.C. (II 18-19). Desde estas torres se vigila el paso hacia Platea y Tebas.',I.x-48,I.z-16,0);},
 nemea:I=>{const a=I.arrive;natCairn(a.x+28,a.z+16);natInn(I.x-120,I.z+120,0.3,false);place('pandokeion','Una posada','ΠΑΝΔΟΚΕΙΟΝ','Junto al camino hay una posada, un pandokeîon, donde «se acoge a todos»: cama, fuego y comida a cambio de unos óbolos. Tienen mala fama. En Las ranas de Aristófanes, dos posaderas se lanzan contra Heracles porque la última vez se comió dieciséis panes y no pagó (549-578), y Platón propone vigilar de cerca a los posaderos (Leyes XI 918-919).',I.x-104,I.z+132,0);},
 liceo:I=>{const a=I.arrive;natCairn(a.x+28,a.z+16);place('hermaion','Un montón de Hermes','ΕΡΜΑΙΟΝ','En los caminos de montaña, cada viajero echa una piedra al pasar junto a estos montones, consagrados a Hermes, el dios de los caminos. Así crecen poco a poco y señalan la ruta aunque haya niebla o nieve.',a.x+34,a.z+22,0);},
 tempe:I=>{const a=I.arrive;natCairn(a.x+28,a.z+16);natInn(I.x+140,I.z+90,-0.4,false);},
 parnaso:I=>{const a=I.arrive;natCairn(a.x+28,a.z+16);},
 eta:I=>{const a=I.arrive;natCairn(a.x+28,a.z+16);},
 achelous:I=>{const a=I.arrive;natCairn(a.x+28,a.z+16);natInn(I.x-150,I.z-120,0.2,false);},
 taigeto:I=>{const a=I.arrive;natCairn(a.x+28,a.z+16);},
 escironides:I=>{const a=I.arrive;natCairn(a.x+28,a.z+16);},
 nemi:I=>{const a=I.arrive;natMile(a.x+26,a.z+14);natInn(I.x-150,I.z+200,0.2,true);for(let i=0;i<3;i++)natTomb(a.x+50+i*14,a.z-26,0);
   place('aricia','La posada de Aricia','ARICIA','Aquí al lado, en Aricia, hizo Horacio su primera parada cuando viajó de Roma a Brundisium con Mecenas: «Al salir de la gran Roma, me acogió Aricia en una posada modesta» (Sátiras I 5, 1-2). Las tumbas flanquean la Vía Apia porque la ley prohíbe enterrar dentro de la ciudad.',I.x-134,I.z+214,0);
   place('miliario','Una columna miliaria','MILIARIVM','Cada mil pasos, unos 1.480 metros, una columna de piedra indica la distancia hasta Roma y el nombre del magistrado o del emperador que hizo o reparó la calzada. Vespasiano y Tito han restaurado muchas vías de Italia, y sus nombres se leen en cientos de miliarios.',a.x+32,a.z+20,0);},
 soracte:I=>{const a=I.arrive;natMile(a.x+26,a.z+14);place('flaminia','La Vía Flaminia','VIA FLAMINIA','La calzada que va de Roma a Ariminum, en el Adriático, construida por el censor Gayo Flaminio en el 220 a.C. Vespasiano acaba de mejorarla: en el 76-77 d.C. mandó abrir un túnel en la roca en el paso del Furlo, y la inscripción que lo recuerda aún se conserva.',a.x+32,a.z+20,0);},
 clitumno:I=>{const a=I.arrive;natMile(a.x+26,a.z+14);natInn(I.x-150,I.z+110,0.3,true);},
 sila:I=>{const a=I.arrive;natMile(a.x+26,a.z+14);},
 ciminia:I=>{const a=I.arrive;natMile(a.x+26,a.z+14);},
 caudium:I=>{const a=I.arrive;natMile(a.x+26,a.z+14);natInn(I.x-120,I.z+150,0.2,true);for(let i=0;i<2;i++)natTomb(a.x+50+i*14,a.z-26,0);
   place('caupona_caudi','Las posadas de Caudio','CAVPONA','Horacio también paró aquí, en su viaje a Brundisium: cuenta que en una «villita junto al puente de Campania» y en las posadas de Caudio cenaron y se rieron con las bromas de dos bufones (Sátiras I 5, 45-70). En las posadas de camino se duerme mal: Horacio se queja de los mosquitos, de las ranas y del agua mala.',I.x-104,I.z+164,0);},
 lunae:I=>{const a=I.arrive;natMile(a.x+26,a.z+14);},
 padus:I=>{const a=I.arrive;natMile(a.x+26,a.z+14);},
 rubico:I=>{const a=I.arrive;natMile(a.x+26,a.z+14);}};
for(const S of[SIMPLE_GR,SIMPLE_RO])for(const id in NAT_ROAD){const o=S[id];if(!o)continue;const e0=o.extra;o.extra=function(I){if(e0)e0.call(this,I);try{NAT_ROAD[id](I);}catch(e){console.warn('natRoad',id,e);}};}
// viajeros con los que hablar (frases basadas en las fuentes)
const NAT_TRAV={
 pentelico:['Un apicultor','con sus colmenas',{chiton:'#b8a07a',short:true,noHimation:true},'«La mejor miel del Ática sale de las flores del tomillo de estos montes y del Himeto. La cosecho con humo, para que las abejas no me piquen.»'],
 citeron:['Un pastor beocio','con sus cabras',{chiton:'#8a7a5a',short:true,noHimation:true},'«En verano subo las cabras al Citerón; en invierno las bajo a los llanos. Aquí arriba nos encontramos los pastores de Tebas y los del Ática, como en la historia de Edipo.»'],
 nemea:['Un atleta de camino a los juegos','de Argos',{chiton:'#d8ccb4'},'«Voy a Nemea a correr el estadio. Si gano, me darán una corona de apio silvestre, que no vale nada… y en mi ciudad me harán una estatua.»'],
 liceo:['Una pastora arcadia','con su siringa',{female:true,chiton:'#a8906a',himation:'#6a5a40'},'«Aquí todos sabemos tocar la siringa: nos enseñó Pan. Los de la ciudad dicen que somos rudos, pero los arcadios somos el pueblo más antiguo de Grecia, más que la Luna.»'],
 tempe:['Un mercader tesalio','con sus mulas',{chiton:'#b0a080',himation:'#7a6040'},'«Llevo caballos de Tesalia a Macedonia. El rey Amintas paga bien por ellos. Por el Tempe se pasa en un día, pero con la crecida del Peneo el camino se inunda.»'],
 parnaso:['Una tíade de Delfos','sacerdotisa de Dioniso',{female:true,chiton:'#e8dcc8',himation:'#6a2a4a'},'«En pleno invierno subimos al Parnaso por la noche, con antorchas, a despertar a Dioniso. Una vez la nieve nos atrapó y los hombres tuvieron que subir a rescatarnos.»'],
 eta:['Un pastor de Traquis','',{chiton:'#8a7a5a',short:true,noHimation:true},'«Cada año subimos a la cumbre a quemar ofrendas a Heracles, donde ardió su pira. Mi abuelo decía que conocía el sendero que enseñó Efialtes a los persas. Nadie en el pueblo habla de ese traidor.»'],
 achelous:['Un barquero','del Aqueloo',{chiton:'#7a8a8a',short:true,noHimation:true},'«El río trae tanto barro que mi padre recordaba islas que hoy ya son tierra firme. Cuando crece, se lleva puentes y cosechas: por eso lo pintan como un toro.»'],
 taigeto:['Un cazador espartano','con dos perros laconios',{chiton:'#7a2a24'},'«La caza es parte de la educación de un espartano. Mis perros no ladran al seguir el rastro: así la presa no se entera hasta que es tarde. Jenofonte, el ateniense que vive en Escilunte, los admira mucho.»'],
 escironides:['Un arriero de Megara','con sus burros',{chiton:'#9a8a6a',short:true,noHimation:true},'«Por este camino hay que ir despacio: a un lado la roca, al otro el mar. Desde que Teseo acabó con Escirón, lo peor son los desprendimientos.»'],
 nemi:['Un viajero que vuelve de Brundisium','',{chiton:'#d8ccb4',himation:'#7a5a3a'},'«Diez días por la Apia. Las posadas, llenas de chinches y de posaderos tramposos; en el Foro de Apio, el agua era tan mala que preferí no cenar. Lo mismo que cuenta Horacio, ¿eh?»'],
 soracte:['Un peregrino','de camino al templo',{chiton:'#d8ccb4',himation:'#8a6a3a'},'«Subo a ver a los Hirpi andar sobre las brasas en la fiesta de Apolo. Dicen que no se queman porque los protege el dios.»'],
 clitumno:['Una mujer de Hispellum','',{female:true,chiton:'#e8dcc8',himation:'#5a6a7a'},'«Venimos a bañarnos río abajo, donde está permitido, y a dejar una moneda en la fuente. Mira cuántas se ven en el fondo.»'],
 sila:['Un pegunero brucio','fabrica pez',{chiton:'#5a4a3a',short:true,noHimation:true},'«Hacemos cortes en los pinos, recogemos la resina y la cocemos en estos hornos. La pez sale negra y pegajosa: la quieren los astilleros y los que fabrican ánforas.»'],
 ciminia:['Un leñador etrusco','',{chiton:'#6a5a40',short:true,noHimation:true},'«Mi bisabuelo contaba que antes nadie se atrevía a cruzar este bosque. Ahora pasa la Vía Cassia, pero de noche aún hay lobos.»'],
 caudium:['Un campesino samnita','',{chiton:'#8a7a5a',short:true,noHimation:true},'«Aquí mis antepasados hicieron pasar a los romanos bajo el yugo. Luego Roma ganó la guerra, claro. Ahora somos todos ciudadanos.»'],
 lunae:['Un cantero','de las canteras de Luna',{chiton:'#c8c0b0',short:true,noHimation:true},'«Abrimos la roca con cuñas de madera que mojamos para que se hinchen, o con cuñas de hierro a golpe de maza. Luego bajamos los bloques en trineos por la ladera, frenándolos con cuerdas.»'],
 padus:['Un pescador del delta','',{chiton:'#7a8a7a',short:true,noHimation:true},'«En las lagunas hay anguilas y mújoles. Los barcos suben por el Po hasta Placentia y más allá: es el gran camino del norte de Italia.»'],
 rubico:['Un veterano','de las guerras civiles',{chiton:'#9a3a2a'},'«Mi abuelo cruzó este río con César. Decía que el general dudó mucho rato y que luego dijo aquello de la suerte. Y la suerte, desde luego, estaba echada.»']};
function natTravSetup(){for(const id in NAT_TRAV){const I=ISLANDS.find(q=>q.id===id);if(!I||!I.arrive)continue;const T=NAT_TRAV[id],p=findFree(I.arrive.x+40,I.arrive.z+30,1);if(!p)continue;artPerson(p,T[2],'nat:tr_'+id,T[0],T[1]||'viajero',3);}}
const natActTr=natAct;natAct=function(o){const id=o.act.slice(4);if(id.startsWith('tr_')){const T=NAT_TRAV[id.slice(3)];if(T)vmS('✦',T[0],T[1]||'',`<p>${T[3]}</p>`,[vmBye]);return;}return natActTr(o);};
const natSetup0=natSetup;natSetup=function(){natSetup0();try{natTravSetup();}catch(e){console.warn('natTrav',e);}};

// ---- los mitos en su sitio: fragmentos de Ovidio trasladados, esferas de sueño en los mapas de transición y apariciones en los montes
WILD.lion={c:'#c49a5a',b:'#d8b680',L:1.6,H:0.9,W:0.55,leg:0.7,neck:0.2,head:0.42,ears:1};
const wildBuildMane=wildBuild;wildBuild=function(sp,o){const A=wildBuildMane(sp,o);if(sp==='lion'){const m=new THREE.Mesh(new THREE.SphereGeometry(0.55,10,8),lam('#7a4a24'));m.scale.set(1,1,0.8);m.position.z=0.1;A.head.add(m);}return A;};
function natAt(id,dx,dz){const I=ISLANDS.find(q=>q.id===id);return I?[I.x+(dx||0),I.z+(dz||0)]:null;}
function epiWild(S,sp,x,z,r,s){const A=wildBuild(sp,{s:s||1});S.g.add(A.g);A.g.position.set(x,0,z);A.g.rotation.y=r||0;return A;}
const NAT_EPIS=[
{id:'leon_nemea',mode:'atenas',name:'Heracles y el león de Nemea',at:()=>natAt('nemea',225,-95),h:16,
 teaser:'un león al que no hieren las flechas, una cueva de dos bocas, unos brazos que aprietan y una piel que se convierte en armadura.',
 build(S){S.ground('#9a9a62');const A=S.a;S.hill(30,-30,40,18,'#8a8a5a');A.cave=S.box(8,6,2,'#1a1410',22,3,-12);A.her=S.person({chiton:'#c96a4a',hair:'#3a2a1e',beard:true,staff:true},0,10,Math.PI);A.lion=epiWild(S,'lion',10,-4,0,1.6);A.pelt=S.box(1.6,0.2,1.2,'#c49a5a',0,2.2,10);A.pelt.visible=false;},
 beats:[
  {h:16,cam:[0,8,40,0,2,0],d:12,txt:'El rey Euristeo mandó a Heracles su primer trabajo: traerle la piel del león de Nemea, una fiera hija de monstruos que asolaba el valle y cuya piel no atravesaba ningún arma. Heracles llegó a Nemea y se alojó en casa de un campesino pobre, Molorco.',enter(S){const A=S.a;A.lion.g.position.set(10,0,-4);A.lion.g.visible=true;A.her.position.set(0,0,10);A.pelt.visible=false;},upd(t,dt,S){const A=S.a;A.lion.g.position.x=10-Math.sin(t*0.4)*6;}},
  {h:17,cam:[-14,5,24,6,2,0],d:12,txt:'Le disparó flechas, pero rebotaban en la piel. Lo golpeó con la clava, y el león, aturdido, huyó a su cueva, que tenía dos bocas. Heracles tapó una con piedras y entró por la otra.',upd(t,dt,S){const A=S.a,k=clamp(t/8,0,1);A.lion.g.position.set(lerp(6,22,k),0,lerp(0,-10,k));A.her.position.set(lerp(0,16,k),0,lerp(10,-4,k));}},
  {h:17,cut:true,cam:[18,3,4,22,1.5,-10],d:12,txt:'Dentro, en la oscuridad, lo agarró por el cuello con los brazos y apretó hasta ahogarlo. Luego le arrancó la piel usando las propias garras del león, lo único que podía cortarla.',enter(S){const A=S.a;A.her.position.set(20,0,-8);A.lion.g.position.set(22,0,-11);},upd(t,dt,S){const A=S.a;A.lion.g.rotation.z=Math.min(1.4,t*0.15);armUp(A.her,-1.4,-1.4);}},
  {h:18,cam:[0,6,30,0,2,0],d:14,txt:'Desde entonces Heracles lleva la piel del león como armadura y su cabeza como casco: así lo pintan en los vasos. Según algunos, en recuerdo de esta hazaña se celebran los juegos de Nemea.<p class="sub">Fuentes: Hesíodo, Teogonía 327-332; Apolodoro, Biblioteca II 5, 1. Así lo contaban los griegos.</p>',enter(S){const A=S.a;A.lion.g.visible=false;A.her.position.set(0,0,10);A.pelt.visible=true;A.pelt.position.set(0,1.6,10);}}]},
{id:'pira_eta',mode:'atenas',name:'La pira de Heracles en el Eta',at:()=>natAt('eta',25,-270),h:18,
 teaser:'una túnica envenenada, una montaña, una pira que nadie quiere encender, un arco que cambia de dueño y un trueno.',
 build(S){S.ground('#7a8a52');const A=S.a;S.hill(0,-40,60,30,'#6f7a4a');A.her=S.person({chiton:'#efe6d4',hair:'#3a2a1e',beard:true},0,0,0);A.fil=S.person({chiton:'#7a5a3a',hair:'#2a1e14'},6,6,-0.6);A.pyre=[];for(let i=0;i<6;i++){const l=S.box(4,0.3,0.4,'#3a2a1e',0,0.3+i*0.3,0);l.rotation.y=i*0.5;A.pyre.push(l);}A.fire=[];for(let i=0;i<7;i++){const f=fireSprite(S,rr(-1.5,1.5),rr(1,4),rr(-1.5,1.5),rr(3,6));f.visible=false;A.fire.push(f);}A.glow=glowSprite(S,0,3,0,8,0xffe0a0);A.glow.visible=false;},
 beats:[
  {h:17,cam:[0,4,22,0,1.5,0],d:13,txt:'Deyanira, la esposa de Heracles, temía perderlo. Años antes, el centauro Neso, moribundo, le había dicho que su sangre serviría de filtro de amor. Ella empapó en ella una túnica y se la envió. Era veneno: la tela se pegó a la piel de Heracles y empezó a quemarlo.',enter(S){const A=S.a;A.her.position.set(-8,0,6);A.fire.forEach(f=>f.visible=false);A.glow.visible=false;A.her.visible=true;},upd(t,dt,S){armUp(S.a.her,-0.6-Math.sin(t*3)*0.4,-0.6+Math.sin(t*3)*0.4);}},
  {h:18,cam:[-10,6,18,0,1.5,0],d:12,txt:'Sabiendo que iba a morir, subió al monte Eta, mandó cortar troncos y levantar una pira, y se tendió encima sobre la piel del león. Nadie se atrevía a prender el fuego.',enter(S){S.a.her.position.set(0,1.9,0);S.a.her.rotation.x=-Math.PI/2;}},
  {h:19,cam:[8,4,14,0,1.5,0],d:12,txt:'Solo Filoctetes, un joven de la zona, aceptó encenderla, y Heracles le regaló su arco y sus flechas. Con ese arco, años después, Filoctetes sería necesario para tomar Troya.',enter(S){S.a.fire.forEach(f=>f.visible=true);},upd(t,dt,S){S.a.fire.forEach((f,i)=>{const q=1+Math.sin(t*8+i)*0.2;f.scale.set(4*q,6*q,1);});}},
  {h:20,storm:true,cam:[0,10,30,0,8,0],d:14,txt:'Entonces cayó un rayo, se oyó un trueno, y Heracles subió al Olimpo como dios. Allí se casó con Hebe, la juventud. En la cumbre del Eta, los de la comarca siguen quemando ofrendas en su honor.<p class="sub">Fuentes: Sófocles, Las traquinias; Ovidio, Metamorfosis IX 134-272; Apolodoro II 7, 7. Así lo contaban los griegos.</p>',enter(S){epiFlash();S.a.glow.visible=true;S.a.her.rotation.x=0;},upd(t,dt,S){const A=S.a;A.her.position.y=1.9+t*1.4;A.glow.position.set(0,A.her.position.y+1,0);A.fire.forEach(f=>f.visible=t<5);}}]},
{id:'pan_siringe',mode:'atenas',name:'Pan y Siringe',at:()=>natAt('liceo',60,120),h:17,
 teaser:'una ninfa que huye, un dios con patas de cabra, un río que corta el paso, unas cañas que suenan con el viento.',
 build(S){S.ground('#8a9a5a');const A=S.a;S.water(0,-14,200,12);A.sy=S.person({female:true,chiton:'#dfe9e6',himation:'#9ac0c8',hair:'#5a3a24'},0,10,Math.PI);A.pan=S.person({chiton:'#6a4a2a',hair:'#3a2a1e',beard:true},0,30,Math.PI);A.reeds=[];for(let i=0;i<12;i++){const r=S.box(0.08,rr(1.4,2.2),0.08,'#7a8a4a',rr(-2,2),0.9,-6+rr(-1,1));r.visible=false;A.reeds.push(r);}},
 beats:[
  {h:16,cam:[10,4,30,0,1.5,10],d:12,txt:'Siringe era una ninfa de Arcadia, cazadora y virgen como Ártemis: se vestía como ella y podía confundirse con la diosa, aunque su arco era de cuerno y el de Ártemis de oro. Un día la vio Pan, que volvía del monte Liceo coronado de pino.',enter(S){const A=S.a;A.sy.visible=true;A.sy.position.set(0,0,10);A.pan.position.set(0,0,30);A.reeds.forEach(r=>r.visible=false);}},
  {h:17,cam:[16,6,20,0,1.5,0],d:12,txt:'Ella huyó sin escucharlo, por los campos, hasta que el río Ladón le cortó el paso. Allí rogó a sus hermanas, las ninfas del agua, que la transformaran.',upd(t,dt,S){const A=S.a,k=clamp(t/10,0,1);A.sy.position.z=lerp(10,-4,k);A.pan.position.z=lerp(30,4,k);}},
  {h:17,cut:true,cam:[4,2,6,0,1.4,-5],d:12,txt:'Cuando Pan creía tenerla ya en los brazos, solo abrazó unas cañas de la orilla. Suspiró, y el aire, al pasar entre las cañas, hizo un sonido suave, como un lamento.',enter(S){const A=S.a;A.sy.visible=false;A.reeds.forEach(r=>r.visible=true);A.pan.position.set(0,0,-3);}},
  {h:18,cam:[6,3,10,0,1.4,-4],d:14,txt:'Encantado con aquella música, Pan cortó cañas de distinta longitud y las unió con cera: «Así hablaré siempre contigo», dijo. Desde entonces la flauta de los pastores se llama siringa.<p class="sub">Fuente: Ovidio, Metamorfosis I 689-712 (Mercurio se lo cuenta a Argos para dormirlo). Así lo contaban los antiguos.</p>',upd(t,dt,S){armUp(S.a.pan,-1.2,-1.2);}}]},
{id:'teseo_esciron',mode:'atenas',name:'Teseo y Escirón',at:()=>natAt('escironides',70,40),h:11,
 teaser:'un camino colgado sobre el mar, un bandido sentado en una roca, un pie que pide ser lavado y una tortuga gigante.',
 build(S){S.ground('#9a8a62');const A=S.a;S.water(0,40,600,60);S.hill(0,-30,40,24,'#8a7a5a');A.th=S.person({chiton:'#efe6d4',hair:'#c9a46a',staff:true},-20,10,Math.PI/2);A.sc=S.person({chiton:'#5a3a2a',hair:'#2a1e14',beard:true},4,6,-Math.PI/2);A.rock=S.box(3,1,3,'#8a8070',4,0.5,6);A.sc.position.y=1;A.turtle=S.box(4,1.2,5,'#4a5a3a',8,0.3,30);},
 beats:[
  {h:10,cam:[-10,6,30,0,1.5,6],d:13,txt:'El joven Teseo, criado en Trecén, quiso ir a Atenas a conocer a su padre, el rey Egeo. Pudo ir en barco, pero eligió el camino por tierra, lleno de bandidos, para imitar a Heracles y librar de ellos a los viajeros.',upd(t,dt,S){S.a.th.position.x=-20+t*1.2;}},
  {h:11,cam:[0,4,22,4,1.5,6],d:12,txt:'En este paso, sobre los acantilados, esperaba Escirón. Obligaba a los viajeros a lavarle los pies y, cuando se agachaban, les daba una patada y los tiraba al mar, donde una tortuga enorme se los comía.',enter(S){S.a.th.position.set(-2,0,8);}},
  {h:11,cut:true,cam:[6,3,16,4,1.2,6],d:12,txt:'Teseo hizo como que obedecía, pero agarró al bandido por los pies y lo lanzó por el acantilado. La tortuga tuvo esta vez otra comida.',upd(t,dt,S){const A=S.a;if(t>3){const k=clamp((t-3)/4,0,1);A.sc.position.set(4+k*4,1+Math.sin(k*Math.PI)*4-k*3,6+k*22);A.sc.rotation.z=k*3;}}},
  {h:12,cam:[-6,8,30,0,1,10],d:14,txt:'Siguió su camino hacia Atenas, donde su madrastra Medea intentó envenenarlo antes de que su padre lo reconociera. Los megarenses, en cambio, decían que Escirón no era un bandido, sino un hombre justo que castigaba a los ladrones.<p class="sub">Fuentes: Plutarco, Teseo 10; Pausanias I 44, 8. Así lo contaban los griegos.</p>'}]},
{id:'numa_egeria',mode:'roma',name:'Numa y Egeria',at:()=>natAt('nemi',140,-140),h:21,
 teaser:'un rey que prefiere la paz, un bosque de noche, una ninfa que dicta leyes y una fuente hecha de lágrimas.',
 build(S){S.ground('#5f7a4a');const A=S.a;for(let i=0;i<14;i++)S.tree(rr(-30,30),rr(-30,-8),1,'#3f5a2a');S.water(8,-2,8,8);A.numa=S.person({chiton:'#efe6d4',himation:'#efe6d4',hair:'#d8d0c2',beard:true,beardC:'#e0d8cc'},-6,8,Math.PI/4);A.eg=S.person({female:true,chiton:'#dbe8ee',himation:'#9ac0c8',hair:'#5a3a24'},6,2,-Math.PI*0.7);A.glow=glowSprite(S,6,1.4,2,4,0xcfe6ff);},
 beats:[
  {h:20,cam:[0,4,24,0,1.5,0],d:13,txt:'Después de Rómulo, el rey guerrero, los romanos eligieron a un sabino sabio y pacífico, Numa Pompilio. Quiso que aquel pueblo de soldados aprendiera a temer y honrar a los dioses.',enter(S){S.a.eg.visible=true;S.a.glow.visible=true;S.a.numa.visible=true;}},
  {h:22,cam:[-4,3,12,0,1.5,4],d:13,txt:'De noche iba a un bosque sagrado a reunirse con la ninfa Egeria, que según él le aconsejaba. De esas conversaciones salieron los ritos de Roma: el calendario de días fastos y nefastos, los pontífices, las vestales, los salios que bailan con escudos sagrados.'},
  {h:23,cam:[4,3,10,4,1.5,2],d:13,txt:'Livio, siempre prudente, sugiere otra cosa: que Numa se inventó lo de la ninfa para que el pueblo aceptara sus leyes con más respeto (Livio I 19, 5).'},
  {h:6,cut:true,cam:[10,2,10,8,0.5,-2],d:14,txt:'Cuando Numa murió, ya muy viejo, Egeria se retiró al bosque de Aricia y lloró tanto que Diana, compadecida, la convirtió en una fuente de agua fresca. Es la que brota junto al lago de Nemi.<p class="sub">Fuentes: Livio I 19-21; Ovidio, Metamorfosis XV 482-551 y Fastos III 261-276. Así lo contaban los romanos.</p>',enter(S){S.a.numa.visible=false;},upd(t,dt,S){const A=S.a,k=clamp(t/8,0,1);A.eg.scale.setScalar(1-k*0.99);A.glow.scale.setScalar(4+k*6);}}]},
{id:'cesar_rubicon',mode:'roma',name:'César en el Rubicón',at:()=>natAt('rubico',30,10),h:22,
 teaser:'una cena para disimular, un carro de mulas que se pierde de noche, un río pequeño, una duda larga y una frase.',
 build(S){S.ground('#6f7a4a');const A=S.a;S.water(0,0,700,10);A.ces=S.person({chiton:'#efe6d4',himation:'#a02a2a',hair:'#3a2a1e'},0,14,Math.PI);A.sol=[];for(let i=0;i<8;i++)A.sol.push(S.person({chiton:'#9a3a2a',hair:'#2a1e14',spear:true},rr(-8,8),rr(18,26),Math.PI));A.piper=S.person({chiton:'#efe6d4',hair:'#c9a46a'},4,4,0);A.piper.scale.setScalar(1.6);A.piper.visible=false;},
 beats:[
  {h:20,cam:[0,4,40,0,1.5,14],d:13,txt:'Enero del año 49 a.C. El Senado ha ordenado a César que licencie su ejército. Si cruza armado el Rubicón, la frontera de su provincia, será la guerra. Para disimular, pasa el día en Ravena viendo espectáculos y luego da una cena.',enter(S){S.a.ces.position.set(0,0,14);S.a.piper.visible=false;}},
  {h:23,cam:[6,3,30,0,1.5,10],d:13,txt:'De noche sale a escondidas en un carro de mulas de una panadería; se pierden y vagan hasta el amanecer. Al llegar al río, se detiene. Suetonio cuenta que dijo a los suyos: «Aún podemos volver atrás; si cruzamos este puentecillo, todo se decidirá con las armas».'},
  {h:5,cam:[-6,3,16,4,2,4],d:13,txt:'Entonces, dice Suetonio, apareció de pronto un hombre de gran estatura y belleza que tocaba una flauta de caña. Le quitó la trompeta a un soldado, tocó a guerra y cruzó el río.',enter(S){S.a.piper.visible=true;},upd(t,dt,S){S.a.piper.position.z=4-t*0.8;}},
  {h:6,cam:[0,6,26,0,1,0],d:15,txt:'«Vayamos adonde nos llaman las señales de los dioses y la injusticia de los enemigos. La suerte está echada.» Y cruzó. Empezaba la guerra civil que acabaría con la República.<p class="sub">Fuentes: Suetonio, Julio 31-33; Plutarco, César 32; Lucano, Farsalia I 183-227. Plutarco dice que César pronunció la frase en griego, citando a Menandro.</p>',enter(S){S.a.piper.visible=false;},upd(t,dt,S){const A=S.a;A.ces.position.z=14-t*1.6;A.sol.forEach((p,i)=>p.position.z-=dt*1.6);}}]}];
EPISODES.push(...NAT_EPIS);
