for(const[id,k,map,dx,dz]of[['acteon','A','citeron',-30,24],['penteo','A','citeron',26,-20],['licaon','A','liceo',10,-60],['calisto','A','liceo',-26,20],['dafne','A','tempe',20,-16],['diluvio','A','parnaso',-20,20],['hercules','A','eta',16,-30],['aqueloo','A','achelous',20,10],['ino','A','escironides',24,22],['heliades','R','padus',-30,-14],['hipolito','R','nemi',58,-40]]){const o=OVID.find(q=>q.id===id);if(o)o[k]=['i',map,dx,dz];}
// ---- apariciones en los montes: ménades en el Citerón (invierno, de noche), Pan al atardecer en el Liceo, la cacería de Ártemis en el Taigeto (noche)
const NAT_APP={g:null,id:null,ph:0};
function natAppWant(){if(ui!=='play'||!state)return null;let I=null;try{I=islandOf(player.x);}catch(e){}if(!I)return null;const h=clock.h,mo=calNow().mo,night=h>=20.5||h<4.5;
  if(I.id==='citeron'&&night&&(mo>=10||mo<=1))return'menades';if(I.id==='liceo'&&h>=17.5&&h<20.5)return'pan';if(I.id==='taigeto'&&night)return'artemis';return null;}
function natAppBuild(kind){const I=islandOf(player.x),g=new THREE.Group(),a=R()*TAU,cx=player.x+Math.cos(a)*40,cz=player.z+Math.sin(a)*40;g.position.set(cx,floorAt(cx,cz),cz);scene.add(g);g.userData={kind,ps:[]};
  if(kind==='menades'){for(let i=0;i<6;i++){const p=makePerson({female:true,chiton:'#e8dcc8',himation:pick(['#6a2a4a','#4a2a5a','#7a3a2a']),hair:'#2a1e14'});g.add(p);g.userData.ps.push(p);const f=new THREE.Sprite(new THREE.SpriteMaterial({map:TORCH_TEX,blending:THREE.AdditiveBlending,transparent:true,depthWrite:false}));f.scale.set(1.2,1.6,1);f.position.y=2.4;p.add(f);}}
  if(kind==='pan'){const p=makePerson({chiton:'#6a4a2a',hair:'#3a2a1e',beard:true});g.add(p);g.userData.ps.push(p);}
  if(kind==='artemis'){const p=makePerson({female:true,chiton:'#f4f0e8',himation:'#c9a24a',hair:'#c9a24a'});g.add(p);g.userData.ps.push(p);const gl=new THREE.Sprite(new THREE.SpriteMaterial({map:TORCH_TEX,color:0xdfe8ff,blending:THREE.AdditiveBlending,transparent:true,depthWrite:false,opacity:0.6}));gl.scale.set(3,4,1);gl.position.y=1.2;p.add(gl);for(let i=0;i<2;i++){const d=wildBuild('deer',{});scene.remove(d.g);g.add(d.g);g.userData.ps.push(d.g);}}
  return g;}
function natAppTick(dt){const want=natAppWant();if(want!==NAT_APP.id){if(NAT_APP.g){scene.remove(NAT_APP.g);NAT_APP.g=null;}NAT_APP.id=want;if(want){NAT_APP.g=natAppBuild(want);NAT_APP.ph=0;NAT_APP.seen=false;}}
  const G=NAT_APP.g;if(!G)return;NAT_APP.ph+=dt;const t=NAT_APP.ph,k=G.userData.kind,ps=G.userData.ps;
  if(k==='menades')ps.forEach((p,i)=>{const a=t*0.8+i/ps.length*TAU;p.position.set(Math.cos(a)*4,Math.abs(Math.sin(t*4+i))*0.3,Math.sin(a)*4);p.rotation.y=-a;armUp(p,-2.4+Math.sin(t*5+i)*0.4,-1.2);});
  if(k==='pan'){armUp(ps[0],-1.3,-1.3);ps[0].rotation.y=Math.atan2(player.x-G.position.x,player.z-G.position.z);}
  if(k==='artemis'){const a=t*0.35;G.position.x+=Math.cos(a)*dt*6;G.position.z+=Math.sin(a)*dt*6;G.position.y=floorAt(G.position.x,G.position.z);ps.forEach((p,i)=>{p.position.set(i?6+i*3:0,0,i?-4:0);p.rotation.y=a+Math.PI/2;});}
  const d=Math.hypot(G.position.x-player.x,G.position.z-player.z);
  if(!NAT_APP.seen&&d<45){NAT_APP.seen=true;const z=natz();const key='ap_'+k;if(!z[key]){z[key]=1;save();setTimeout(()=>{if(ui!=='play')return;
    vmS(k==='pan'?'♪':'☾',k==='menades'?'Ménades en el monte':k==='pan'?'Pan al atardecer':'La cacería de Ártemis','lo que creían los antiguos',
     k==='menades'?'<p>Entre los pinos ves un corro de mujeres con antorchas, el pelo suelto y pieles de cervatillo, que bailan y gritan «¡Evohé!». Es una oreibasía, la subida al monte para celebrar a Dioniso, que algunas ciudades hacían cada dos años, en pleno invierno.</p><p class="sub">Fuentes: Eurípides, Las bacantes; Pausanias X 4, 3. Las ménades del mito despedazaban animales; las mujeres reales celebraban ritos nocturnos que los hombres no podían ver.</p>':
     k==='pan'?'<p>En la ladera, una figura con barba y patas de cabra toca la siringa mientras cae el sol. Los pastores de Arcadia decían que Pan dormía al mediodía y que había que guardar silencio para no despertarlo; al atardecer, en cambio, tocaba para las ninfas.</p><p class="sub">Fuentes: Teócrito, Idilio I 15-18; Himno homérico a Pan.</p>':
     '<p>A la luz de la luna pasa una cazadora con túnica corta y arco, seguida de dos ciervos: Ártemis, que según los poetas recorre de noche los montes del Taigeto con sus ninfas. Los espartanos la veneraban como Ártemis Ortia.</p><p class="sub">Fuente: Homero, Odisea VI 102-104 (Ártemis cazando por el Taigeto y el Erimanto).</p>',[vmBye]);},600);}}}

// ---- los doce trabajos de Heracles en su sitio (Apolodoro, Biblioteca II 5, 1-12): cuatro mapas de transición nuevos y once esferas de sueño más
Object.assign(MED_POS,{lerna:[22.72,37.55],erimanto:[21.8,37.97],estinfalo:[22.46,37.85],tenaro:[22.48,36.39]});
// sustituye a la versión anterior: ahora los animales salen de wildBuild
epiWild=function(S,sp,x,z,r,s,c){const A=wildBuild(sp,{s:s||1,c:c||{}});S.g.add(A.g);A.g.position.set(x,0,z);A.g.rotation.y=r||0;return A;};
function epiNeck(seg,bx,by,bz,dx,dy,dz,t,ph){seg.forEach((s,i)=>{const k=i/seg.length;s.position.set(bx+dx*k+Math.sin(t*2+ph+k*3)*0.6*k,by+dy*k+Math.sin(t*1.5+ph)*0.4*k,bz+dz*k);});}
Object.assign(SIMPLE_GR,{
 lerna:{label:_t(2452,'Lerna'),blobs:[[-260,-220,220,120],[260,-240,200,90]],lake:[60,120,110,80],houses:4,spread:50,
  steles:[['lerna_fuentes','Las fuentes de Lerna','ΛΕΡΝΑ','Una costa pantanosa al sur de Argos, llena de manantiales y cañaverales. Aquí, bajo un plátano junto a la fuente Amimone, vivía la Hidra. Pausanias cuenta que en el lago Alcionio, que no tiene fondo, Dioniso bajó al Hades a buscar a su madre Sémele, y que aquí se celebran unos misterios de Deméter (II 36-37).']],
  extra(I){NAT_FOREST(I,260);natReeds(I.x+40,I.z+60,70);natSpring(I.x-60,I.z+40);natReeds(I.x-80,I.z+80,40);}},
 erimanto:{label:'el Erimanto',blobs:[[0,-200,330,210],[-280,180,190,90]],houses:2,spread:40,
  steles:[['folo','El centauro Folo','ΦΟΛΟΣ','En los bosques de Fóloe, junto al Erimanto, vivía el centauro Folo, que acogió a Heracles cuando venía a cazar el jabalí. Heracles le pidió vino, y al abrir la tinaja común de los centauros, el olor los atrajo a todos, furiosos. En la pelea, una flecha envenenada hirió por accidente al sabio Quirón, que siendo inmortal no podía morir del dolor (Apolodoro II 5, 4).']],
  extra(I){NAT_FOREST(I,620);caveMouth(I.x+120,I.z-60,0.5);}},
 estinfalo:{label:'el Estínfalo',blobs:[[-270,-200,230,120],[270,-200,220,110]],lake:[0,40,170,110],site:[-140,160,20],temple:{name:'Templo de Ártemis Estinfalia',W:10,L:18},houses:4,spread:50,
  steles:[['estinfalo_lago',_t(2458,'El lago Estínfalo'),'ΣΤΥΜΦΑΛΙΣ','Un lago de montaña en el norte de Arcadia, que en invierno crece y en verano se convierte en pantano: el agua se escapa por una sima. Pausanias vio en el techo del templo de Ártemis Estinfalia las aves esculpidas, y detrás del templo, unas doncellas de mármol con patas de pájaro (VIII 22, 4-7).']],
  extra(I){NAT_FOREST(I,280);natReeds(I.x+40,I.z+150,60);natReeds(I.x-70,I.z-60,50);}},
 tenaro:{label:'el Ténaro',blobs:[[0,-150,300,150]],site:[80,140,18],temple:{name:'Templo de Poseidón Tenario',W:10,L:16},houses:2,spread:40,arr:[-300,-40],
  steles:[['tenaro_cueva','La cueva del Ténaro','ΤΑΙΝΑΡΟΝ','En la punta más al sur de Grecia, junto al templo de Poseidón, hay una cueva por la que, según los poetas, Heracles subió a Cerbero desde el Hades; por aquí bajó también Orfeo (Virgilio la llama «las fauces del Ténaro»). Pausanias la visitó y no vio ningún camino bajo tierra (III 25, 5).'],['arion','Arión y el delfín','ΑΡΙΩΝ','Heródoto cuenta que el músico Arión, arrojado al mar por unos marineros que querían robarle, fue llevado a hombros por un delfín hasta este cabo. En el templo de Poseidón había una figurilla de bronce de un hombre sobre un delfín (I 23-24). El templo es además un asilo: aquí se refugian los suplicantes, también los hilotas.']],
  extra(I){NAT_FOREST(I,140);caveMouth(I.x+40,I.z+90,Math.PI*0.3);}}});
Object.assign(NAT_NY,{
 lerna:{dx:-60,dz:52,n:'Amimone',s:'la ninfa de la fuente',c:'#dbe8ee',t:'<p>«Era una de las cincuenta hijas de Dánao. Argos estaba seca y vine a buscar agua; un sátiro me atacó y Poseidón me salvó. Luego clavó su tridente en la roca y brotaron estas fuentes. Bajo aquel plátano vivía la Hidra.»</p>',src:'Apolodoro II 1, 4; Pausanias II 37, 1'},
 erimanto:{dx:130,dz:-48,n:'Folo',s:'el centauro hospitalario',c:'#9a7a5a',g:'old',t:'<p>«Soy Folo. A diferencia de mis hermanos, sé tratar a los huéspedes: a Heracles le serví la carne asada, aunque yo la como cruda. Abrir aquella tinaja de vino fue un error… y luego, por curiosidad, saqué una de sus flechas, se me cayó en el pie y morí del veneno.»</p>',src:'Apolodoro II 5, 4'},
 estinfalo:{dx:-130,dz:150,n:'Ártemis Estinfalia',s:'señora del lago',c:'#f4f0e8',t:'<p>«Este lago es mío, y también los pájaros que lo pueblan. Los estinfalios dicen que las aves de Heracles eran del tamaño de grullas, con picos que atravesaban el bronce. Otros cuentan que en realidad venían de Arabia.»</p><p class="sub">Pausanias da las dos versiones y no se decide.</p>',src:'Pausanias VIII 22, 4-7'},
 tenaro:{dx:50,dz:100,n:'Sombra en la cueva',s:'un alma del Hades',c:'#c8d0dc',t:'<p>Una voz débil sale de la cueva: «Por aquí bajó Heracles a por Cerbero, con el permiso de Perséfone, y por aquí lo sacó, atado, sin usar armas, solo con sus brazos. El perro babeaba de miedo a la luz, y de su baba brotó una planta venenosa, el acónito.»</p>',src:'Apolodoro II 5, 12; Ovidio, Metamorfosis VII 406-419'}});
