// ---- la barra lee las casillas configuradas
// (las funciones de la barra usan hbSlots en lugar del catálogo completo; ver el reemplazo en el código fuente)
// ---- el zurrón
function objZurron(){if(ui!=='play'&&ui!=='zurron')return;let o=$('zurron');if(o){o.remove();ui='play';return;}ui='zurron';releasePointer();o=document.createElement('div');o.id='zurron';o.style.cssText='position:fixed;inset:0;z-index:63;background:rgba(14,10,7,.9);color:#f1e8d8;font:15px Alegreya,Georgia,serif;overflow:auto;padding:16px';
  const draw=()=>{const bar=hbBar(),sel=HBAR.sel;o.innerHTML=_t(10524,'<div style="max-width:760px;margin:0 auto"><h3 style="color:#f0c890;margin:4px 0">Tu zurrón</h3><p class="sub" style="opacity:.8">Elige una casilla de la barra (abajo) y luego el objeto que quieres poner en ella. Los objetos que aún no tienes salen en gris, con la pista de cómo conseguirlos.</p>')+
   '<div style="display:flex;gap:4px;flex-wrap:wrap;margin:8px 0">'+bar.map((k,i)=>{const it=HB_ITEMS.find(x=>x.k===k)||HB_EMPTY;return '<button data-s="'+i+'" style="width:52px;height:52px;border-radius:8px;border:2px solid '+(i===sel?'#f0b070':'#6a4a30')+';background:rgba(241,232,216,.06);color:#f1e8d8;cursor:pointer"><svg viewBox="0 0 24 24" style="width:30px;height:30px;fill:none;stroke:currentColor;stroke-width:1.6">'+hbIcon(it.k)+'</svg></button>';}).join('')+'</div>'+
   '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:6px">'+HB_ITEMS.filter(it=>!(it.k==='pinakion'&&RO())&&!((it.k==='diploma'||it.k==='rama')&&!RO())).map(it=>{const has=it.has(),c=it.cnt?' ×'+hbCnt(it.cnt):'';return '<button data-k="'+it.k+'" '+(has?'':'disabled')+' style="text-align:left;display:flex;gap:8px;align-items:center;padding:6px;border-radius:8px;border:1px solid #6a4a30;background:'+(has?'rgba(217,135,74,.14)':'rgba(255,255,255,.03)')+';color:'+(has?'#f1e8d8':'#8a7a6a')+';font:inherit;cursor:'+(has?'pointer':'default')+'"><svg viewBox="0 0 24 24" style="flex:none;width:28px;height:28px;fill:none;stroke:currentColor;stroke-width:1.6">'+hbIcon(it.k)+'</svg><span><b>'+it.n()+c+'</b>'+(has?(it.passive?_t(10525,'<br><span style="opacity:.7;font-size:13px">funciona solo con llevarlo</span>'):''):'<br><span style="font-size:13px">'+it.how+'</span>')+'</span></button>';}).join('')+'</div>'+
   _t(10526,'<p style="text-align:center;margin-top:12px"><button id="zClose" style="font:inherit;padding:8px 16px;border-radius:8px;border:1px solid #d9874a;background:#d9874a;color:#1a120c">Cerrar (I)</button></p></div>');
   o.querySelectorAll('[data-s]').forEach(b=>b.onclick=()=>{HBAR.sel=+b.dataset.s;hbz().sel=HBAR.sel;draw();});
   o.querySelectorAll('[data-k]').forEach(b=>b.onclick=()=>{const bar=hbBar(),k=b.dataset.k,j=bar.indexOf(k);if(j>=0)bar[j]=bar[HBAR.sel];bar[HBAR.sel]=k;save();hbRender(true);draw();});$('zClose').onclick=()=>{o.remove();ui='play';};};
  document.body.appendChild(o);draw();}
window.addEventListener('keydown',e=>{if(e.target&&(e.target.tagName==='INPUT'||e.target.tagName==='TEXTAREA'))return;if(e.code==='KeyI'&&!e.repeat&&state&&(ui==='play'||ui==='zurron')){e.preventDefault();objZurron();}});
