// ---- uso según el contexto: la casilla útil brilla; si el objeto está en el zurrón, una pista
const OBJ={ctx:null,t:0,hinted:{}};
function objNear(list,r){return list.some(p=>Math.hypot(p[0]-player.x,p[1]-player.z)<r);}
function objContext(){if(ui!=='play'||!state)return null;const h=hbz();
  if(hbz().got.odre&&h.odre<3&&hbNearWater())return'odre';
  if((clock.h>=20||clock.h<5)&&typeof TORCH!=='undefined'&&!TORCH.on&&!(player.feet>CASA.Y-50))return _t(10405,'antorcha');
  if(PLACES.some(p=>p.text&&!(state.places||[]).includes(p.id)&&Math.hypot(p.x-player.x,p.z-player.z)<6))return'tablilla';
  if(HB_GYM())return'strigil';
  if(EGX_OBJS.some(o=>/^(sp:|nat:|rd:tumba)/.test(o.act)&&Math.hypot(o.x-player.x,o.z-player.z)<7)||CULT_OBJS.some(o=>Math.hypot(o.x-player.x,o.z-player.z)<6))return'amuleto';
  if(objAsclep())return'exvoto';
  if(FAUNA.some(F=>(F.sp==='goat'||F.sp==='sheep')&&Math.hypot(F.A.g.position.x-player.x,F.A.g.position.z-player.z)<15))return'siringa';
  return null;}
function objAsclep(){try{const I=islandOf(player.x);if(I&&I.id==='epidauro')return true;const p=PLACES.find(q=>q.id==='ro_isla');return !!(p&&Math.hypot(p.x-player.x,p.z-player.z)<70);}catch(e){return false;}}
function objTick(dt){if(!state)return;OBJ.t-=dt;if(OBJ.t>0)return;OBJ.t=0.5;const c=objContext();const it=c&&HB_ITEMS.find(i=>i.k===c);const useful=it&&it.has()?c:null;
  if(useful!==OBJ.ctx){OBJ.ctx=useful;hbRender(true);}
  if(useful&&!hbBar().includes(useful)&&!OBJ.hinted[useful]){OBJ.hinted[useful]=1;toast('Aquí te vendría bien: <b>'+it.n()+'</b>. Lo tienes en el zurrón (tecla I).');}
  const h=hbz();if(h.got.strigil&&h.cnt&&h.cnt.aceite===undefined){h.cnt.aceite=2;save();}if(!RO()&&fxz().ciu&&!h.got.pinakion)hbGive('pinakion','Como ciudadano, recibes tu pinákion de bronce, con tu nombre y tu demo: ya puedes ser jurado.');
  if(fxz().ciu&&!h.got.anillo)hbGive('anillo','Te haces grabar un anillo de sello: con él firmarás contratos y cartas.');
  if(RO()&&!h.got.diploma&&(qLv('kl')>=3||fxz().ciu))hbGive('diploma','Un magistrado agradecido te concede un diploma para usar las postas del correo público.');}
// la casilla brillante
const hbRenderObj=hbRender;hbRender=function(force){hbRenderObj(force);try{const b=$('hbar');if(!b)return;const bar=hbBar();[...b.children].forEach((s,i)=>{s.style.boxShadow=bar[i]===OBJ.ctx?'0 0 0 2px #9ad06a,0 0 14px #9ad06a':'';const it=HB_ITEMS.find(x=>x.k===bar[i]);if(it&&it.cnt&&it.has()){let c=s.querySelector('.c2');if(!c){c=document.createElement('span');c.className='c';c.classList.add('c2');s.appendChild(c);}c.textContent=hbCnt(it.cnt);}});}catch(e){}};
// ---- efectos de los objetos pasivos y de uso
const wxTickObj=wxTick;wxTick=function(dt){const h0=WXS.heatE;wxTickObj(dt);if(hbz().got.petaso&&WXS.heatE>h0)WXS.heatE=h0+(WXS.heatE-h0)*0.5;};
const wxSpeedObj=wxSpeed;wxSpeed=function(){let f=wxSpeedObj();if(hbz().got.capa&&WX_T[wxK()].rain&&!MOUNT.riding)f/=0.92;return f;};
const fareOfObj=fareOf;fareOf=function(from,to,land){let f=fareOfObj(from,to,land);if(land&&RO()&&hbz().got.diploma)return 0;if(hbz().got.tesera)f=Math.max(land?0:1,Math.round(f*0.8));return f;};
const hbStrigilObj=hbStrigil;hbStrigil=function(){if(HB_GYM()&&hbCnt('aceite')<=0){toast('Sin aceite no puedes usar el estrígilo. Compra un '+(RO()?'frasco':_t(7257,'aríbalo'))+' de aceite con la bolsa.');return;}const s0=hbz().str;hbStrigilObj();if(hbz().str!==s0)hbAddCnt('aceite',-1);};
function objTone(notes,type){try{if(!AUD.ctx||!AUD_ON)return;const C=AUD.ctx;let t=C.currentTime;for(const f of notes){const o=C.createOscillator(),g=C.createGain();o.type=type;o.frequency.value=f;g.gain.setValueAtTime(0.0001,t);g.gain.exponentialRampToValueAtTime(0.12,t+0.03);g.gain.exponentialRampToValueAtTime(0.0001,t+0.45);o.connect(g);g.connect(AUD.master||C.destination);o.start(t);o.stop(t+0.5);t+=0.28;}}catch(e){}}
function objPlay(k){const z=natz(),d=state.day||1;if(k==='siringa'){objTone([523,587,659,784,659,587,523],'sine');RD.dogT=600;let I=null;try{I=islandOf(player.x);}catch(e){}
    if(I&&RD_MAPS.includes(I.id)&&(clock.h>=19||clock.h<5)&&z.sirN!==d){z.sirN=d;qAdd('eu',1);save();toast('Tocas la siringa en el monte. Entre los árboles brilla un momento una luz pálida y se oye una risa: las ninfas te han escuchado. Los perros pastores se tumban tranquilos.');}else toast('Tocas la siringa. Los perros pastores se calman y las cabras levantan la cabeza.');return;}
  objTone([392,494,587,784,587,494,392],'triangle');let city=false;try{city=!islandOf(player.x);}catch(e){}if(city&&clock.h>8&&clock.h<20&&z.liraN!==d){z.liraN=d;qAdd('kl',1);save();toast('Tocas '+(RO()?'la cítara':'la lira')+' y se forma un corrillo a tu alrededor. Alguien te echa una moneda. Tu fama crece.');state.obols+=1;updateStats();}else toast('Tocas '+(RO()?'la cítara':'la lira')+'. '+(RO()?'Nerón presumía de cantar con ella; a los romanos serios no les parecía cosa de emperadores.':'En Atenas, todo joven bien educado aprende a tocarla con el citarista.'));}
function objSling(){const a=player.yaw;pfx(player.x,player.feet+1.6,player.z,{col:'#6e6252',vx:-Math.sin(a)*22,vy:5,vz:-Math.cos(a)*22,g:9.8,life:1.4,s:0.12,a:1});const z=natz(),d=state.day||1;if(z.honN!==d){z.honN=d;qAdd('ar',1);save();}toast('Volteas la honda y lanzas una piedra lejísimos. Los pastores la usan para espantar a los lobos y guiar al rebaño; en la guerra, los honderos de Rodas y de las Baleares eran los más temidos.');}
function objRing(){const z=natz();if(!z.anillo){z.anillo=1;qAdd('lo',1);save();}vmS('◍','Anillo de sello','',RO()?'<p>Una piedra grabada con tu emblema, engastada en hierro u oro. Se aprieta sobre la cera para cerrar cartas, testamentos y contratos: el sello vale como tu firma. Augusto selló primero con una esfinge, luego con la cabeza de Alejandro y al final con su propio retrato (Suetonio, Augusto 50).</p>':'<p>Una piedra grabada, la sphragís, con tu emblema. Se aprieta sobre la cera o la arcilla para cerrar cartas, jarras y cofres: el sello es tu firma. Solón prohibió que los grabadores guardaran copia de los sellos que vendían (Diógenes Laercio I 57).</p>',[vmBye]);}
function objExvoto(){if(!objAsclep()){toast('Este exvoto se ofrece en un santuario de '+(RO()?_t(5759,'Esculapio'):'Asclepio')+'.');return;}hbAddCnt('exvoto',-1);WXS.heatE=0;qAdd('eu',1);vmS('⚕',RO()?_t(5759,'Esculapio'):'Asclepio','un exvoto',RO()?'<p>Dejas en el templo de la isla Tiberina una pieza de barro con la forma de la parte del cuerpo que quieres que el dios cure: una mano, un pie, un ojo, una oreja. Hay montones. Desde que llegó la serpiente de Epidauro, en el 291 a.C., los enfermos duermen aquí esperando un sueño que los cure (Livio X 47; Ovidio, Metamorfosis XV 622-744).</p>':'<p>Cuelgas en el santuario una pieza de barro con la forma de la parte del cuerpo que quieres que el dios cure. En Epidauro, unas estelas cuentan las curaciones milagrosas: un ciego que recobró la vista, un hombre al que le salió el pelo… Los enfermos duermen en el ábaton esperando la visita del dios en sueños.</p>',[vmBye]);}
