const hbBolsaObj=hbBolsa;hbBolsa=function(){hbBolsaObj();try{const O=$('dOpts'),ro=RO(),c1=ro?'sestercio':_t(2849,'óbolo'),add=(t,cost,fn)=>{const b=document.createElement('button');b.className='quiz';b.innerHTML='<span class="n">·</span><span>'+t+'</span>';b.onclick=()=>{if(state.obols<cost){toast('No tienes bastante dinero.');return;}state.obols-=cost;save();updateStats();try{sfxCoin();}catch(e){}fn();closeDialog();};O.insertBefore(b,O.lastChild);};
  let city=false;try{city=!islandOf(player.x)||islandOf(player.x).town;}catch(e){}
  add('Comprar '+(ro?'una ampolla':'un aríbalo')+' de aceite (1 '+c1+')',1,()=>{hbAddCnt('aceite',1);toast('Tienes '+hbCnt('aceite')+' de aceite.');});
  add('Comprar dos tortas de miel (1 '+c1+')',1,()=>{hbAddCnt('tortas',2);});
  if(!hbz().got.petaso)add('Comprar un '+(ro?'sombrero de viaje':'pétaso')+' (3)',3,()=>hbGive('petaso','Un sombrero de fieltro de ala ancha, el de los viajeros y el de Hermes.'));
  if(!hbz().got.capa)add('Comprar una '+(ro?'paenula':'clámide')+' (6)',6,()=>hbGive('capa',ro?'Una paenula de lana gruesa, con capucha: la capa de los viajeros y los soldados.':'Una clámide, el manto corto que se abrocha en el hombro: la ropa de viaje de los jóvenes y los jinetes.'));
  if(!hbz().got.lira)add('Comprar '+(ro?'una cítara':'una lira')+' (15)',15,()=>hbGive('lira','Caja de concha de tortuga, dos brazos y siete cuerdas: la lira que, según el mito, inventó Hermes.'));
  if(objAsclep())add('Comprar un exvoto de barro (1 '+c1+')',1,()=>hbAddCnt('exvoto',1));}catch(e){}};
