const natActObj=natAct;natAct=function(o){const id=o.act.slice(4);natActObj(o);try{if(id.startsWith('tr_')){const m=id.slice(3),h=hbz(),z=natz();
   if(['citeron','eta','liceo'].includes(m)){if(!h.got.baston)hbGive('baston','El pastor te regala un cayado: «Para el monte, mejor tres piernas que dos».');else if(!h.got.honda)hbGive('honda','El pastor te enseña a usar la honda y te regala una: «Con esto se espanta al lobo».');}
   if(['nemi','tempe','escironides'].includes(m)&&!h.got.tesera)hbGive('tesera','Partís en dos una ficha de hueso y os quedáis cada uno con una mitad: si alguna vez pasas por su ciudad, tendrás casa y mesa. Es la hospitalidad antigua, que obliga también a los hijos y a los nietos.');
   if(h.odre>0&&!z['agua_'+m]){const O=$('dOpts'),b=document.createElement('button');b.className='quiz';b.innerHTML='<span class="n">·</span><span>Ofrecerle agua de tu odre</span>';b.onclick=()=>{h.odre--;z['agua_'+m]=1;save();qAdd('eu',1);qAdd('kl',1);hbRender(true);closeDialog();toast('Bebe con ganas y te da las gracias en nombre de Zeus Xenios, el protector de los viajeros. Quien ayuda al caminante, decían, ayuda a un dios disfrazado.');};O.insertBefore(b,O.firstChild);}}
  if(id==='liceo'&&!hbz().got.siringa){const giveS=()=>hbGive('siringa','Siringe deja a tus pies una siringa de siete cañas unidas con cera: «Tócala en el monte al anochecer».');if(natz().liceo)giveS();else{const b=$('dOpts')&&$('dOpts').querySelector('button');if(b)b.addEventListener('click',()=>setTimeout(giveS,600));}}
  if(id==='tenaro'&&hbCnt('obolo')===0&&!natz().obolo){natz().obolo=1;hbAddCnt('obolo',1);toast('<span class="label">Un óbolo</span><br>«Llévalo siempre contigo», dice la voz. «Sin él, Caronte no te pasará al otro lado».');}}catch(e){}};
// el inframundo: óbolo, tortas y rama dorada
const hdActObj=hdAct;hdAct=function(o){if(o.act==='hd:caronte'&&hbCnt('obolo')>0){hbAddCnt('obolo',-1);setTimeout(()=>toast('Le das tu óbolo a Caronte. El viejo barquero lo muerde, gruñe y te deja subir.'),400);}
  if(o.act==='hd:cerbero'&&hbCnt('tortas')>0){hbAddCnt('tortas',-1);setTimeout(()=>toast('Le echas una torta de miel a Cerbero. Sus tres cabezas se pelean por ella y pasas.'),400);}return hdActObj(o);};
const infActObj=infAct;infAct=function(o){const r=infActObj(o);try{if(o.act==='fi:rama'&&!hbz().got.rama)hbGive('rama','Arrancas la rama de oro: se desprende sola, como dice Virgilio que pasa cuando los hados te llaman. En su lugar brota otra igual.');if(o.act==='fi:cerbero'&&hbCnt('tortas')>0){hbAddCnt('tortas',-1);toast('Le echas a Cerbero una torta de miel, como hizo la Sibila: se la traga y se duerme.');}}catch(e){}return r;};
// la tablilla junto a una estela: copiar la inscripción
const hbTablillaObj=hbTablilla;hbTablilla=function(){const p=PLACES.find(p=>p.text&&!(state.places||[]).includes(p.id)&&Math.hypot(p.x-player.x,p.z-player.z)<6);if(p){state.places.push(p.id);save();qAdd('so',1);toast('<span class="label">Copias la inscripción</span><br>'+(p.greek||p.name)+' · ya está en tu álbum de la tablilla.');return;}return hbTablillaObj();};
// el jurado con pinákion cobra
const cyActObj=cyAct;cyAct=function(o){if(o.act==='cy:klero'&&hbz().got.pinakion&&fxz().ciu){const z=cyz(),d=state.day||1;if(z.jur!==d){z.jur=d;const w=Math.random()<0.5;save();if(w){state.obols+=3;updateStats();}vmS('⚖','Klērōtḗrion','el sorteo de los jurados','<p>Metes tu pinákion en la ranura. El magistrado echa las bolas… '+(w?'<b>¡blanca!</b> Hoy juzgas: te sientas con otros quinientos jurados a escuchar los discursos, y al final cobras tus tres óbolos.':'<b>negra.</b> Hoy no te toca. Mañana, otra vez.')+'</p>',[vmBye]);return;}}return cyActObj(o);};

