function evpTick(){const g=EVP.g;if(!g)return;EVP.t+=3;   // eduTick llama cada 3 s; el paso fino lo hace evpStep en el bucle
  if(EVP.t>90){scene.remove(g);EVP.g=null;}}
function evpStep(dt){const g=EVP.g;if(!g||!state)return;const dx=player.x-g.position.x,dz=player.z-g.position.z,d=Math.hypot(dx,dz);
  if(EVP.leave){g.position.x-=dx/d*dt*1.3;g.position.z-=dz/d*dt*1.3;g.position.y=floorAt(g.position.x,g.position.z);g.rotation.y=Math.atan2(-dx,-dz);EVP.ph+=dt*6;personWalk(g,EVP.ph,1);if(d>30){scene.remove(g);EVP.g=null;}return;}
  g.rotation.y=Math.atan2(dx,dz);
  if(d>2.2){if(d>60){scene.remove(g);EVP.g=null;return;}const v=Math.min(d-2.2,dt*1.4);g.position.x+=dx/d*v;g.position.z+=dz/d*v;g.position.y=floorAt(g.position.x,g.position.z);EVP.ph+=dt*6;personWalk(g,EVP.ph,1);return;}
  personWalk(g,0,0);if(ui!=='play')return;const E=EVP.E,z=eduz(),day=state.day||1;EVP.leave=true;EVP.lb.visible=false;
  vmS('✉',E[0],evpWho(E).toLowerCase()+' se te acerca','<p>'+E[1]+'</p>',E[2]?[['Aceptar',()=>{E[2]();closeDialog();toast('Hecho.');},'quiz'],['Mejor no',()=>closeDialog()]]:[['Prestárselo (5)',()=>{if(state.obols<5){toast('No tienes tanto.');return;}state.obols-=5;z.loan={d:day+5};save();updateStats();closeDialog();},'quiz'],['No prestarle',()=>closeDialog()]]);}
