const eduEntriesV=eduEntries;eduEntries=function(){const E=eduEntriesV(),v=vestz();for(const it of vestList())if(it.p===0||v.own[it.k+'_'+it.s])E.push({c:_t(10544,'Vestuario'),n:it.n,t:it.t+(it.lock&&it.lock()?' '+it.lock():'')});return E;};
