function amb2Pts(n,col,size){const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.BufferAttribute(new Float32Array(n*3),3));const P=new THREE.Points(g,new THREE.PointsMaterial({color:col,size,transparent:true,depthWrite:false}));P.frustumCulled=false;P.userData.noCol=true;scene.add(P);return {P,ph:[...Array(n)].map(()=>[R()*10,rr(0.3,1.2),rr(0.6,1.6)])};}
