for(const id of['siracusa','aetna','caralis','aleria',...R3_DESTS.map(d=>d[0]),...R4_DESTS.map(d=>d[0])])if(SIMPLE_RO[id])SIMPLE_RO[id].early=true;

// ============================================================ ROMA: lo que les faltaba a los mapas nuevos — esferas de sueño, segunda misión del barquero, casas de Oriente
// ---- casas de tejado plano (Galilea, Tiro, Judea): piedra o adobe, terraza con pretil y escalera exterior
function r5FlatHouses(I,cx,cz,n,spread){const W=['#d8c8a0','#cdb88e','#e0d4b4','#c8b48a'];let k=0;for(let t=0;t<n*10&&k<n;t++){const x=cx+rr(-spread,spread),z=cz+rr(-spread,spread);if(!isFree(x,z,7))continue;
  const h0=terrainH(x,z);if(h0<1.4)continue;if(Math.abs(terrainH(x+5,z)-terrainH(x-5,z))+Math.abs(terrainH(x,z+5)-terrainH(x,z-5))>3)continue;
  const w=rr(6,10),d=rr(6,9),h=rr(3,4.4),a=R()<0.5?0:Math.PI/2,gy=minGround(x,z,w,d,a),g=grp(x,gy,z,a),m=lam(pick(W));
  box(w,h+1,d,m,0,(h+1)/2-1,0,g);box(w+0.2,0.25,d+0.2,lam('#a8987a'),0,h+0.1,0,g);for(const[s,ax]of[[-1,'x'],[1,'x'],[-1,'z'],[1,'z']]){if(ax==='x')box(0.2,0.6,d,m,s*w/2,h+0.5,0,g);else box(w,0.6,0.2,m,0,h+0.5,s*d/2,g);}
  box(1,1.9,0.1,lam('#2a1e14'),0,0.95,d/2+0.01,g);for(let s=0;s<6;s++)box(0.9,0.3,0.6,m,w/2+0.5,0.15+s*h/6,-d/2+0.6+s*0.6,g);
  addBox(x,z,w,d,a);footprints.push({x,z,w,d,a,c:'#cdb994',house:true});k++;}}
for(const id of['galilaea','tyrus','hierosolyma']){const o=SIMPLE_RO[id];if(!o)continue;const n=id==='tyrus'?34:id==='galilaea'?16:8,sp=o.spread||80;o.houses=1;o.spread=4;const ex=o.extra;
  o.extra=function(I){ex.call(this,I);const t=I.town;r5FlatHouses(I,t.x,t.z,n,sp);};}
SIMPLE_RO.hierosolyma.steles.push(['casas_judea','Casas de terraza','DOMVS','En Judea, Galilea y Fenicia las casas tienen el tejado plano, de vigas cubiertas de barro apisonado, con un pretil alrededor para que nadie se caiga, como manda la Ley de Moisés. Se sube por una escalera de fuera: en la terraza se seca la fruta, se duerme en verano y se reza.']);
// ---- esferas de sueño en los mapas nuevos
const R5_EP=[
{id:'r_sibila',mode:'roma',name:_t(7514,'Eneas y la Sibila de Cumas'),at:()=>natAt('cumae',-120,-120),h:18,teaser:'una cueva de cien bocas, una profetisa poseída, una rama de oro y la puerta de los muertos.',
 build(S){S.ground('#6a7a4a');const A=S.a;A.cave=S.box(14,8,4,'#141010',0,4,-16);A.sib=S.person({female:true,chiton:'#efe6d0',himation:'#6a3a5a',hair:'#d8d0c2'},0,-10,0);A.en=S.person({chiton:'#a8392b',himation:'#c9a24a',hair:'#3a2a1e',beard:true,spear:true},0,4,Math.PI);A.ach=S.person({chiton:'#7a6a50',hair:'#3a2a1e',beard:true},3,6,Math.PI);
  A.lake=S.water(30,10,40,30);A.tr=S.tree(-20,0,1.4,'#3f5a2a');A.gold=glowSprite(S,-20,5,0,1.2,0xffd060);},
 beats:[{h:18,cam:[0,4,20,0,2,-10],d:13,txt:'Eneas desembarcó en Cumas y subió al templo de Apolo. En la roca había una cueva enorme, con cien bocas por las que salían cien voces: las respuestas de la Sibila. Poseída por el dios, con el pelo revuelto y el pecho jadeante, le anunció guerras y le dijo lo que necesitaba para bajar al mundo de los muertos.'},
  {h:19,cam:[-10,5,12,-20,4,0],d:13,txt:'Necesitaba una rama de oro escondida en un árbol del bosque, como regalo para Proserpina. Dos palomas, las aves de su madre Venus, lo guiaron hasta ella, y la rama se dejó arrancar.'},
  {h:20,cam:[20,6,30,30,0,10],d:14,txt:'Luego, junto al lago Averno, de aguas negras, sacrificaron a los dioses de abajo, y la Sibila gritó: «¡Ahora necesitas valor, Eneas!». Y se metió en la boca de la cueva, y él detrás de ella.<p class="sub">Fuentes: Virgilio, Eneida VI 1-263. Así lo contaban los antiguos.</p>'}]},
{id:'r_vesubio',mode:'roma',name:'El Vesubio despierta',at:()=>natAt('pompeii',-260,120),h:12,teaser:'una nube como un pino, una lluvia de piedras, un almirante sabio y una ciudad que desaparece.',
 build(S){S.ground('#8a8a6a');const A=S.a;A.mt=S.hill(0,-120,90,70,'#6a6460');A.cloud=[];for(let i=0;i<8;i++)A.cloud.push(glowSprite(S,0,70+i*12,-120,30+i*6,0x5a5450));A.house=[];for(let i=0;i<6;i++)A.house.push(S.box(8,5,8,'#e3d8c2',-30+i*12,2.5,20));A.pl=S.person({toga:true,chiton:'#efe9dc',himation:'#f3eee2',hair:'#d8d0c2'},10,40,Math.PI);
  A.pp=[];for(let i=0;i<5;i++)A.pp.push(S.person({short:true,chiton:'#a08a62',hair:'#3a2a1e'},-20+i*8,30,0));},
 beats:[{h:12,cam:[0,10,90,0,40,-120],d:13,txt:'Hacia el mediodía, sobre el Vesubio apareció una nube enorme. Plinio el Joven, que la vio desde Miseno, escribió que tenía la forma de un pino: un tronco altísimo que se abría en ramas arriba. Era una columna de piedra pómez y ceniza que subía hasta el cielo.',upd(t,dt,S){S.a.cloud.forEach((c,i)=>{c.position.y=70+i*12+t*2;});}},
  {h:15,cam:[10,6,60,0,4,20],d:13,txt:'Sobre Pompeya empezó a caer una lluvia de piedras ligeras, y luego ceniza. Las casas se oscurecieron; los tejados se hundían bajo el peso. Mucha gente huyó con lo que pudo; otros se encerraron, esperando que pasara.',upd(t,dt,S){S.a.pp.forEach((p,i)=>{p.position.z=30+t*1.5;});}},
  {h:7,cut:true,cam:[20,8,70,0,10,0],d:14,txt:'Plinio el Viejo, el almirante de la flota y autor de la Historia natural, cruzó la bahía para rescatar a los que huían y para observar de cerca. Al día siguiente, una nube ardiente bajó por la ladera y lo cubrió todo. Plinio murió en la playa de Estabias. Pompeya quedó enterrada diecisiete siglos.<p class="sub">Fuentes: Plinio el Joven, Cartas VI 16 y VI 20 (escritas hacia el 106); Dion Casio LXVI 21-23.</p>'}]},
{id:'r_arquimedes',mode:'roma',name:'La muerte de Arquímedes',at:()=>natAt('siracusa',-300,140),h:21,teaser:'una ciudad asediada, unas máquinas imposibles, unos círculos en la arena y un soldado impaciente.',
 build(S){S.ground('#c8b890');const A=S.a;A.wall=S.box(60,10,3,'#d8cdb2',0,5,-20);A.arq=S.person({chiton:'#efe9dc',himation:'#4f6a7d',hair:'#e0dcd2',beard:true},0,6,0);A.arq.rotation.x=0.3;A.circ=[];for(let i=1;i<4;i++){const r=new THREE.Mesh(new THREE.RingGeometry(i*0.6,i*0.6+0.05,32),lam('#5a4a3a'));r.rotation.x=-Math.PI/2;r.position.set(0,0.05,4);S.g.add(r);}
  A.sol=S.person({short:true,noHimation:true,chiton:'#a8392b',hair:'#3a2a1e'},10,14,-Math.PI*0.8);A.crane=S.box(1,16,1,'#6a4a2a',-20,8,-24);A.arm=S.box(14,0.8,0.8,'#6a4a2a',-14,16,-24);},
 beats:[{h:15,cam:[-30,12,20,-20,10,-24],d:13,txt:'Durante dos años, la flota y las legiones de Marcelo no pudieron tomar Siracusa. Arquímedes había inventado catapultas que lanzaban piedras enormes y grúas que agarraban los barcos por la proa, los levantaban y los dejaban caer al mar. Los soldados romanos huían en cuanto veían asomar una viga por la muralla.',upd(t,dt,S){S.a.arm.rotation.z=Math.sin(t*0.6)*0.3;}},
  {h:21,cam:[4,3,14,0,0.5,4],d:13,txt:'Por fin, en el 212 a.C., aprovechando una fiesta, los romanos entraron de noche. Arquímedes, ajeno a todo, estaba en su casa, inclinado sobre unas figuras geométricas dibujadas en la arena.'},
  {h:21,cam:[12,4,18,4,1,6],d:14,txt:'Llegó un soldado y le ordenó que lo siguiera. «No me estropees los círculos», dicen que contestó. El soldado, furioso, lo mató. Marcelo, que había ordenado respetarlo, lloró y buscó a su familia para honrarla.<p class="sub">Fuentes: Plutarco, Marcelo 14-19; Livio XXV 31; Valerio Máximo VIII 7 ext. 7. Las palabras exactas son una tradición posterior.</p>',upd(t,dt,S){S.a.sol.position.z=14-Math.min(6,t);}}]},
{id:'r_proserpina',mode:'roma',name:'El rapto de Proserpina',at:()=>natAt('henna',-160,80),h:10,teaser:'un lago lleno de flores, un carro negro que sale de la tierra y una madre con dos antorchas.',
 build(S){S.ground('#7a9a4a');const A=S.a;A.lake=S.water(0,-20,60,40);A.fl=[];for(let i=0;i<30;i++)A.fl.push(glowSprite(S,rr(-30,30),0.4,rr(0,20),0.5,pick([0xd08ae0,0xffffff,0xffd040])));A.pro=S.person({female:true,chiton:'#f0e8d8',himation:'#d8a0b0',hair:'#c9a24a'},0,10,0);
  A.pl=S.person({chiton:'#1a1414',himation:'#2a1a1a',hair:'#1a1410',beard:true},14,4,-Math.PI/2);A.h=[S.beast('caballo',18,0,-Math.PI/2),S.beast('caballo',18,2.5,-Math.PI/2)];A.cer=S.person({female:true,chiton:'#e8dca8',himation:'#8a6a2a',hair:'#8a6a3a'},-20,30,Math.PI);A.t1=glowSprite(S,-21,2.6,30,0.8,0xffa040);A.t2=glowSprite(S,-19,2.6,30,0.8,0xffa040);},
 beats:[{h:10,cam:[0,4,26,0,1,8],d:13,txt:'Junto al lago de Pérgusa, en un bosque donde siempre es primavera, Proserpina, la hija de Ceres, cogía violetas y lirios con sus amigas y llenaba la falda y los cestos.'},
  {h:10,cam:[10,4,20,14,1,4],d:13,txt:'Plutón, el rey de los muertos, la vio, se enamoró de ella y se la llevó en su carro de caballos negros. Ella gritaba llamando a su madre; las flores se le cayeron de la túnica. El dios golpeó la tierra con el cetro y se hundió con ella por la grieta.',upd(t,dt,S){const A=S.a;if(t>4){A.pro.position.x=Math.min(14,(t-4)*3);A.pro.position.y=-Math.max(0,(t-8)*0.8);A.pl.position.y=A.h[0].position.y=A.h[1].position.y=-Math.max(0,(t-8)*0.8);}}},
  {h:21,cut:true,cam:[-20,4,44,-20,2,30],d:14,txt:'Ceres la buscó por toda la tierra, de día y de noche, con dos antorchas encendidas en el Etna. Al fin, Júpiter decidió que Proserpina pasaría una parte del año con su madre y otra con su marido. Cuando está abajo, Ceres está triste y es invierno.<p class="sub">Fuentes: Ovidio, Metamorfosis V 385-571 y Fastos IV 417-620; Cicerón, Verrinas II 4.106-107.</p>'}]},
{id:'r_zama',mode:'roma',name:'La batalla de Zama',at:()=>natAt('zama',-160,120),h:9,teaser:'ochenta elefantes, unos pasillos vacíos, las trompetas, y el fin de la guerra de Aníbal.',
 build(S){S.ground('#c8a870');const A=S.a;A.el=[];for(let i=0;i<6;i++){const e=new THREE.Group();const b=new THREE.Mesh(new THREE.SphereGeometry(1.8,10,8),lam('#7a7470'));b.scale.set(1,0.9,1.4);b.position.y=2.6;e.add(b);for(const[a,c]of[[-0.8,-1],[0.8,-1],[-0.8,1],[0.8,1]]){const l=new THREE.Mesh(new THREE.CylinderGeometry(0.4,0.4,2,8),lam('#7a7470'));l.position.set(a,1,c);e.add(l);}const tr=new THREE.Mesh(new THREE.CylinderGeometry(0.2,0.35,2.4,8),lam('#7a7470'));tr.position.set(0,2,2.6);tr.rotation.x=0.3;e.add(tr);e.position.set(-30+i*12,0,-30);S.g.add(e);A.el.push(e);}
  A.leg=[];for(let i=0;i<5;i++)for(let j=0;j<3;j++)A.leg.push(S.person({short:true,noHimation:true,chiton:'#a8392b',hair:'#3a2a1e',spear:true},-36+i*18+(j-1)*2.4,20+j*2,Math.PI));A.sc=S.person({chiton:'#a8392b',himation:'#efe9dc',hair:'#3a2a1e'},0,34,Math.PI);},
 beats:[{h:9,cam:[0,10,50,0,2,0],d:13,txt:'En el 202 a.C., en una llanura de África, se enfrentaron por fin los dos mejores generales de su tiempo: Aníbal, que había pasado quince años en Italia, y el joven Publio Cornelio Escipión, que había llevado la guerra a la puerta de Cartago.'},
  {h:9,cam:[-10,6,30,-10,2,-10],d:13,txt:'Aníbal lanzó primero ochenta elefantes. Pero Escipión no había puesto a sus manípulos en tablero, como siempre, sino en columnas, dejando pasillos vacíos entre ellos. Sonaron todas las trompetas y cuernos a la vez; los elefantes, aterrados, corrieron por los pasillos o se volvieron contra su propio ejército.',upd(t,dt,S){S.a.el.forEach((e,i)=>{e.position.z=-30+t*5;e.position.x=-30+i*12+(i%2?1:-1)*Math.max(0,t-4)*1.5;});}},
  {h:10,cut:true,cam:[0,8,40,0,2,0],d:14,txt:'Después chocaron las infanterías, y la caballería de Masinisa, que volvía de perseguir a la cartaginesa, atacó a Aníbal por la espalda. Cartago perdió la guerra, su flota y su imperio. A Escipión lo llamaron, desde entonces, el Africano.<p class="sub">Fuentes: Polibio XV 9-16; Livio XXX 29-35.</p>'}]},
{id:'r_coloso',mode:'roma',name:'La caída del Coloso',at:()=>natAt('rhodus',-200,100),h:6,teaser:'una estatua del Sol más alta que un templo, doce años de trabajo y un terremoto.',
 build(S){S.ground('#c8b890');const A=S.a;A.sea=S.water(0,-40,200,60);A.col=new THREE.Group();const m=lam('#a88a4a');const b=new THREE.Mesh(new THREE.CylinderGeometry(2.2,3,14,10),m);b.position.y=20;A.col.add(b);const h=new THREE.Mesh(new THREE.SphereGeometry(2.2,10,8),m);h.position.y=29;A.col.add(h);for(const s of[-1,1]){const l=new THREE.Mesh(new THREE.CylinderGeometry(1.2,1.4,13,8),m);l.position.set(s*1.4,6.5,0);A.col.add(l);}const ar=new THREE.Mesh(new THREE.CylinderGeometry(0.8,0.8,12,8),m);ar.rotation.z=-0.6;ar.position.set(5,26,0);A.col.add(ar);
  A.col.position.set(0,2,-4);S.g.add(A.col);S.box(10,2,10,'#d8cdb2',0,1,-4);A.pp=[];for(let i=0;i<5;i++)A.pp.push(S.person({chiton:'#d8ccb0',hair:'#3a2a1e'},-10+i*5,20,Math.PI));},
 beats:[{h:7,cam:[0,10,60,0,18,-4],d:13,txt:'Después de resistir un año de asedio del rey Demetrio, los rodios vendieron las máquinas de guerra que había abandonado y, con el dinero, encargaron al escultor Cares de Lindos una estatua del Sol, su dios. Tardó doce años en terminarla: más de treinta metros de bronce, sobre un esqueleto de hierro relleno de piedras.'},
  {h:7,cam:[20,6,40,0,14,-4],d:13,txt:'Hacia el 226 a.C., solo cincuenta y seis años después, un terremoto sacudió Rodas. El Coloso se partió por las rodillas y cayó.',upd(t,dt,S){if(t>3)S.a.col.rotation.x=Math.min(1.5,(t-3)*0.5);}},
  {h:8,cam:[10,4,30,0,2,0],d:14,txt:'Un oráculo prohibió a los rodios levantarlo otra vez. Ahí sigue, tumbado en pedazos: Plinio cuenta que pocos pueden abrazar su pulgar, y que sus dedos son más grandes que muchas estatuas. Anacronismo: la imagen del Coloso con una pierna a cada lado del puerto es una invención medieval.<p class="sub">Fuentes: Plinio XXXIV 41; Estrabón XIV 2.5; Polibio V 88.</p>',upd(t,dt,S){S.a.col.rotation.x=1.5;}}]},
{id:'r_pegaso',mode:'roma',name:_t(7489,'Belerofonte y Pegaso'),at:()=>natAt('corinthus',-180,140),h:6,teaser:'una fuente, un caballo con alas que nadie puede tocar y una brida de oro caída del cielo.',
 build(S){S.ground('#7a8a52');const A=S.a;A.f=S.box(10,3,4,'#d8cdb2',0,1.5,-10);A.w=S.water(0,-5,10,4);A.peg=S.beast('caballo',4,-2,0);A.peg.traverse(o=>{if(o.isMesh)o.material=lam('#f4f2ee');});A.wings=[];for(const s of[-1,1]){const w=S.box(3,0.1,1.2,'#ffffff',4+s*1.8,2.2,-2);w.rotation.z=s*0.4;A.wings.push(w);}
  A.bel=S.person({chiton:'#4f6a7d',himation:'#c9a24a',hair:'#3a2a1e'},-8,6,Math.PI/2);A.br=glowSprite(S,-6,2,6,0.7,0xffd060);},
 beats:[{h:6,cam:[0,4,20,0,1.5,-4],d:13,txt:'Pegaso, el caballo alado nacido de la sangre de Medusa, bajaba a beber a la fuente de Pirene, en Corinto. Nadie conseguía acercarse a él. El joven Belerofonte lo intentó muchas veces, sin éxito.'},
  {h:22,cam:[-8,3,14,-8,1.5,6],d:13,txt:'Por consejo de un adivino, durmió una noche en el altar de Atenea. En sueños, la diosa le dio una brida de oro; al despertar, la brida estaba de verdad junto a él.'},
  {h:7,cam:[0,6,24,0,3,-2],d:14,txt:'Con ella fue a la fuente y Pegaso se dejó poner la brida, manso. Montado en él, Belerofonte mató a la Quimera. Pero luego, orgulloso, quiso volar hasta el Olimpo: Pegaso lo tiró, y él vagó solo el resto de su vida. Las monedas de Corinto llevan a Pegaso.<p class="sub">Fuentes: Píndaro, Olímpica XIII 63-92; Homero, Ilíada VI 155-202; Pausanias II 4.1.</p>',upd(t,dt,S){const A=S.a;if(t>5){A.peg.position.y=Math.min(8,(t-5)*1.5);A.wings.forEach(w=>w.position.y=2.2+A.peg.position.y);}}}]},
{id:'r_europa',mode:'roma',name:'Europa y el toro blanco',at:()=>natAt('tyrus',-200,140),h:9,teaser:'una playa de Fenicia, una princesa, un toro demasiado manso y un mar que se abre.',
 build(S){S.ground('#d8c8a0');const A=S.a;A.sea=S.water(0,-60,300,100);A.eu=S.person({female:true,chiton:'#f0e0e8',himation:'#8a2a5a',hair:'#3a2a1e'},-4,10,0);A.am=[];for(let i=0;i<3;i++)A.am.push(S.person({female:true,chiton:'#efe6d0',hair:'#5a3a24'},-10+i*3,16,0));A.bull=S.beast('toro',2,4,-Math.PI/2);A.bull.traverse(o=>{if(o.isMesh)o.material=lam('#f8f6f0');});},
 beats:[{h:9,cam:[0,4,26,0,1,8],d:13,txt:'Europa, hija del rey de Tiro, jugaba en la playa con sus amigas cogiendo flores. Entre el ganado de su padre apareció un toro blanco como la nieve, con los cuernos como una luna creciente, tan manso que se dejaba acariciar.'},
  {h:9,cam:[6,3,16,2,1.5,4],d:13,txt:'Europa le puso guirnaldas en los cuernos y, jugando, se sentó en su lomo. Entonces el toro echó a andar hacia el agua, despacio, y luego más deprisa, y entró en el mar.',upd(t,dt,S){const A=S.a;if(t>5){A.bull.position.z=4-(t-5)*4;A.eu.position.set(A.bull.position.x,1.4,A.bull.position.z);}}},
  {h:10,cut:true,cam:[0,10,-20,0,0,-80],d:14,txt:'Era Zeus. La llevó nadando hasta Creta, y allí, bajo un plátano junto a un río de Gortina, tuvo con ella tres hijos: Minos, Radamantis y Sarpedón. Su hermano Cadmo salió a buscarla y nunca la encontró; en cambio, fundó Tebas.<p class="sub">Fuentes: Mosco, Europa; Ovidio, Metamorfosis II 833-875; Heródoto I 2 (la versión «racional» de los fenicios).</p>'}]},
{id:'r_boudica',mode:'roma',name:'La rebelión de Boudica',at:()=>natAt('londinium',-220,-140),h:14,teaser:'una reina humillada, un carro de guerra, tres ciudades en llamas y una batalla.',
 build(S){S.ground('#5a7a3a');const A=S.a;A.q=S.person({female:true,chiton:'#7a3a2a',himation:'#3a5a2a',hair:'#b04a20'},0,10,Math.PI);A.q.scale.setScalar(1.1);A.car=S.box(2.4,1,3,'#6a4a2a',0,0.8,12);A.h=[S.beast('caballo',-0.8,16,0),S.beast('caballo',0.8,16,0)];
  A.br=[];for(let i=0;i<10;i++)A.br.push(S.person({short:true,noHimation:true,chiton:pick(['#5a7a3a','#7a3a2a','#3a4a6a']),hair:pick(['#b04a20','#d8b060','#3a2a1e'])},-14+i*3,20+rr(-2,2),Math.PI));A.fire=[];for(let i=0;i<6;i++)A.fire.push(glowSprite(S,-20+i*8,4,-30,4,0xff6020));for(let i=0;i<6;i++)S.box(6,4,6,'#7a5a3a',-20+i*8,2,-30);},
 beats:[{h:14,cam:[0,4,28,0,2,10],d:13,txt:'Prasutago, rey de los icenos, dejó al morir la mitad de su reino al emperador, esperando proteger así a su familia. Los romanos se lo quedaron todo: azotaron a su viuda, Boudica, y ultrajaron a sus hijas.'},
  {h:16,cam:[0,6,40,0,3,-20],d:13,txt:'En el año 60, Boudica levantó a los icenos y a los trinovantes. Arrasaron Camuloduno, donde estaba el odiado templo del divino Claudio, y luego Londinium y Verulamio. Tácito habla de setenta mil muertos.'},
  {h:15,cut:true,cam:[0,8,50,0,2,0],d:14,txt:'El gobernador Suetonio Paulino, con apenas diez mil soldados, eligió un desfiladero con un bosque detrás y esperó. Los britanos, muchos más, cargaron. La disciplina romana venció. Boudica, dice Tácito, se envenenó para no caer prisionera.<p class="sub">Fuentes: Tácito, Anales XIV 31-37 y Agrícola 16; Dion Casio LXII 1-12.</p>'}]},
{id:'r_espartaco',mode:'roma',name:'Espartaco escapa de Capua',at:()=>natAt('capua',-220,160),h:22,teaser:'unos cuchillos de cocina, un carro de armas, un volcán y un ejército de esclavos.',
 build(S){S.ground('#7a8a52');const A=S.a;A.lu=S.box(20,4,14,'#d8cdb2',0,2,-10);A.sp=S.person({short:true,noHimation:true,chiton:'#8a7a5a',hair:'#3a2a1e',beard:true,spear:true},0,4,Math.PI);A.g=[];for(let i=0;i<8;i++)A.g.push(S.person({short:true,noHimation:true,chiton:'#a08a62',hair:'#2a1a12'},-8+i*2,6+rr(-1,1),Math.PI));A.ves=S.hill(60,-140,60,50,'#6a6460');},
 beats:[{h:22,cam:[0,4,22,0,2,-4],d:13,txt:'En el 73 a.C., en la escuela de gladiadores de Léntulo Batiato, en Capua, unos doscientos hombres planearon escapar. Los descubrieron, pero unos setenta y ocho se adelantaron: cogieron cuchillos y asadores de la cocina y salieron a la calle.',upd(t,dt,S){S.a.g.forEach(p=>{p.position.z=6+t*1.2;});S.a.sp.position.z=4+t*1.2;}},
  {h:10,cam:[0,10,60,40,20,-120],d:13,txt:'En el camino encontraron unos carros que llevaban armas de gladiador a otra ciudad, y se armaron. Se refugiaron en el Vesubio, entonces un monte verde y dormido. Los romanos los cercaron, pero ellos bajaron por los acantilados con cuerdas de sarmientos y los sorprendieron por la espalda.'},
  {h:16,cut:true,cam:[0,8,40,0,2,0],d:14,txt:'Su jefe era Espartaco, un tracio que, dice Plutarco, era más inteligente y más humano de lo que su suerte hacía esperar. Llegó a mandar un ejército de decenas de miles de esclavos y venció a varios cónsules, hasta que Craso lo derrotó en el 71 a.C.<p class="sub">Fuentes: Plutarco, Craso 8-11; Apiano, Guerras civiles I 116-120; Salustio, Historias III.</p>'}]},
{id:'r_eleusis',mode:'roma',name:'Deméter en Eleusis',at:()=>natAt('eleusis',-160,140),h:17,teaser:'una anciana junto a un pozo, un niño en el fuego y una diosa que se revela.',
 build(S){S.ground('#a8987a');const A=S.a;A.pozo=S.box(3,1,3,'#d8cdb2',0,0.5,-4);A.dem=S.person({female:true,chiton:'#5a4a3a',himation:'#3a2a1e',hair:'#d8d0c2'},-2,-2,0);A.gi=[];for(let i=0;i<4;i++)A.gi.push(S.person({female:true,chiton:'#efe6d0',himation:'#c9a24a',hair:'#5a3a24'},4+i*2,4,-Math.PI/2));A.fire=glowSprite(S,-10,1,10,1.4,0xff8030);A.glow=glowSprite(S,-2,2,-2,0.1,0xffe8a0);},
 beats:[{h:17,cam:[0,3,16,0,1.5,-2],d:13,txt:'Buscando a su hija Perséfone, Deméter llegó a Eleusis disfrazada de anciana y se sentó junto al pozo de las Doncellas. Las hijas del rey Céleo, que venían por agua, la llevaron a su casa y la contrataron como niñera de su hermano pequeño.'},
  {h:23,cam:[-8,3,18,-10,1,10],d:13,txt:'Cada noche, a escondidas, la diosa ponía al niño en el fuego para hacerlo inmortal. Una noche lo vio su madre, Metanira, y gritó aterrada.'},
  {h:23,cam:[0,4,14,-2,2,-2],d:14,txt:'Entonces Deméter se reveló: creció, se volvió hermosa y la casa se llenó de luz y de perfume. Pidió que le construyeran un templo, y allí enseñó a los eleusinos sus ritos secretos: los Misterios. Quien los conoce, dice el himno, tiene un destino distinto tras la muerte.<p class="sub">Fuentes: Himno homérico a Deméter 98-304 y 473-482.</p>',upd(t,dt,S){const g=S.a.glow;const k=Math.min(18,t*3);g.scale.set(k,k,1);}}]}];
EPISODES.push(...R5_EP);
// ---- segunda misión del barquero (modo Roma): cuatro tesoros en los puertos nuevos
const R5_IT=[
 {key:'copa_alfeo',where:'siracusa',kind:'cup',name:'Una copa de oro en la fuente',sub:'en el fondo, entre los peces',short:'la copa del Alfeo',gl:'🏆',cname:'La copa del Alfeo',
  txt:'<p>En el fondo de la fuente de Aretusa brilla una copa de oro.</p><p>Los antiguos creían que el río Alfeo, de Olimpia, pasaba por debajo del mar hasta Siracusa para unirse a la ninfa Aretusa. Estrabón y Pausanias cuentan que una copa echada al Alfeo en Olimpia apareció en esta fuente, y que el agua se enturbiaba aquí cuando en Olimpia se sacrificaban bueyes. Que esta sea aquella copa es <b>licencia del juego</b>.</p><p class="src">Estrabón VI 2.4; Pausanias V 7.2-3.</p>'},
 {key:'brida',where:'corinthus',kind:'ring',name:'Una brida de oro',sub:'junto a la fuente de Pirene',short:'la brida de Pegaso',gl:'🐎',cname:'La brida de oro de Belerofonte',
  txt:'<p>Junto a la fuente de Pirene encuentras una brida de oro, tan fina que parece hecha para un caballo de aire.</p><p>Atenea se la dio en sueños a Belerofonte para domar a Pegaso, que bajaba a beber aquí. Corinto tenía un templo de Atenea Calinitis, «la de la brida», por esta historia. Que sea aquella brida es <b>licencia del juego</b>.</p><p class="src">Píndaro, Olímpica XIII 63-92; Pausanias II 4.1.</p>'},
 {key:'ceston',where:'cyprus',kind:'girdle',name:'Una cinta bordada',sub:'sobre una piedra de la playa',short:'el cinturón de Afrodita',gl:'🎀',cname:'El cinturón bordado de Afrodita',
  txt:'<p>Sobre una piedra de la playa, mojada por la espuma, hay una cinta bordada con colores que cambian.</p><p>La Ilíada cuenta que Afrodita tenía una cinta bordada en la que estaban «el amor, el deseo y la conversación seductora que roba el juicio incluso a los sabios»; Hera se la pidió prestada para enamorar a Zeus. Que sea esta es <b>licencia del juego</b>.</p><p class="src">Homero, Ilíada XIV 214-221.</p>'},
 {key:'rayo_sol',where:'rhodus',kind:'ray',name:'Un rayo de bronce dorado',sub:'entre los trozos del Coloso',short:'un rayo de la corona de Helios',gl:'☀',cname:'Un rayo de la corona del Coloso',
  txt:'<p>Entre los pedazos del Coloso, un rayo de bronce dorado de la corona del dios Sol.</p><p>Píndaro cuenta que cuando los dioses se repartieron la tierra, el Sol estaba de viaje y no le tocó nada. Entonces vio una isla que salía del fondo del mar y la pidió para él: era Rodas. Que este rayo sea de la corona del Coloso es <b>licencia del juego</b>.</p><p class="src">Píndaro, Olímpica VII 54-76; Plinio XXXIV 41.</p>'}];
function r5z(){const z=swz();if(!z.m2)z.m2=0;if(!z.it2)z.it2={};return z;}
function r5ItemMesh(kind){const g=new THREE.Group(),gold=new THREE.MeshLambertMaterial({color:'#e8c050',emissive:'#604008'});
  if(kind==='cup'){const c=new THREE.Mesh(new THREE.CylinderGeometry(0.35,0.15,0.4,14,1,true),gold);c.material.side=THREE.DoubleSide;c.position.y=0.5;g.add(c);const f=new THREE.Mesh(new THREE.CylinderGeometry(0.05,0.2,0.3,10),gold);f.position.y=0.15;g.add(f);}
  else if(kind==='girdle'){const t=new THREE.Mesh(new THREE.TorusGeometry(0.4,0.06,6,20),new THREE.MeshLambertMaterial({color:'#d870a0',emissive:'#401020'}));t.rotation.x=Math.PI/2;t.position.y=0.3;g.add(t);}
  else if(kind==='ray'){const c=new THREE.Mesh(new THREE.ConeGeometry(0.15,1.6,6),gold);c.rotation.z=1.2;c.position.y=0.3;g.add(c);}
  else{const t=new THREE.Mesh(new THREE.TorusGeometry(0.35,0.05,6,18),gold);t.position.y=0.5;g.add(t);}
  const h=new THREE.Sprite(new THREE.SpriteMaterial({map:HALO_TEX,color:0xffe0a0,transparent:true,opacity:0.5,depthWrite:false}));h.scale.set(2.4,2.4,1);h.position.y=0.6;g.add(h);return g;}
const R5={objs:{}};
function r5Setup(){if(MODE!=='roma')return;R5.objs={};for(const it of R5_IT){const P=PORTS[it.where];if(!P)continue;const f=findFree(P.x+18*Math.cos(P.yaw||0),P.z-18*Math.sin(P.yaw||0),1),g=r5ItemMesh(it.kind);g.position.set(f[0],floorAt(f[0],f[1]),f[1]);scene.add(g);
  const o=egxObj(f[0],f[1],undefined,'r5:it:'+it.key,it.name,it.sub,3);o.g=g;R5.objs[it.key]=o;}r5Vis();}
function r5Vis(){if(MODE!=='roma')return;const z=r5z();for(const it of R5_IT){const o=R5.objs[it.key];if(!o)continue;const on=z.m2===1&&!z.it2[it.key];o.g.visible=on;o.r=on?3:0;}}
function r5Act(o){const a=String(o.act).slice(3);if(!a.startsWith('it:'))return;const it=R5_IT.find(q=>q.key===a.slice(3)),z=r5z();if(!it||z.it2[it.key]||z.m2!==1)return;
  z.it2[it.key]=1;save();r5Vis();if(typeof sfxCoin==='function')sfxCoin();const n=R5_IT.filter(q=>z.it2[q.key]).length;
  vmS(it.gl,it.cname,'tesoro '+n+' de '+R5_IT.length,it.txt+(n>=R5_IT.length?'<p class="src">Ya los tienes todos. Vuelve con Fulvio, en el Emporio de Roma.</p>':'<p class="src">Llevas '+n+' de '+R5_IT.length+'.</p>'),[vmBye]);}
// Fulvio ofrece el segundo encargo cuando el primero está terminado
{const ot0=swOwnerTalk;swOwnerTalk=function(first){const z=swz();if(MODE!=='roma'||z.m<3)return ot0(first);const D=swD(),O=D.owner,y=r5z(),n=R5_IT.filter(q=>y.it2[q.key]).length;
  if(y.m2===0)return vmS('⚓',O.name,O.sub,'<p>«¡Tú otra vez! Oye, con lo que me trajiste me he hecho famoso entre los coleccionistas del Emporio. Ahora un senador me pide más cosas: piezas de las historias de los griegos. Dicen que están en los puertos del este: Siracusa, Corinto, Pafos y Rodas. ¿Te atreves? Esta vez pago el doble».</p>',
    [['Acepto',()=>{y.m2=1;save();r5Vis();vmS('⚓',O.name,O.sub,'<p>«Busca en Siracusa, en la fuente de Aretusa; en Corinto, junto a la fuente de Pirene; en Pafos, en la playa de la diosa; y en Rodas, entre los trozos del Coloso. Llega en barco o en nave de pasaje, como prefieras. Con tu barca puedes cruzar los mares hasta allí».</p>',[vmBye]);}],[_t(7362,'Ahora no'),()=>vmS('⚓',O.name,O.sub,'<p>«Aquí estaré».</p>',[vmBye])]]);
  if(y.m2===1&&n<R5_IT.length)return vmS('⚓',O.name,O.sub,'<p>«Llevas '+n+' de '+R5_IT.length+'. Siracusa, Corinto, Pafos y Rodas: no tiene pérdida».</p>',[vmBye]);
  if(y.m2===1){y.m2=2;state.obols+=D.reward*2;save();updateStats();r5Vis();if(typeof sfxCoin==='function')sfxCoin();if(typeof qAdd==='function')qAdd('kl',2);
    return vmS('⚓',O.name,O.sub,'<p>«¡La copa del Alfeo, la brida de Pegaso, el cinturón de Afrodita y un rayo del Sol! El senador no se lo va a creer. Aquí tienes: '+(D.reward*2)+' sestercios. Y la barca sigue siendo tuya, claro».</p><p class="sub">Todo esto es licencia del juego: ninguno de estos objetos se ha encontrado nunca. Pero las historias, sí, son antiguas.</p>',[vmBye]);}
  return ot0(first);};}
// ============================================================ ROMA: capítulo extra del modo Historia — «Las historias de Tácito» (se ofrece al terminar la historia)
const STORY_EXTRA_ROMA={cat:_t(123,'Historia'),title:_t(10563,'Las historias de Tácito'),extra:true,
 intro:_t(10564,'Tácito, el joven senador que te aconsejó cuando buscabas a Tercia, está casado con la hija de Gneo Julio Agrícola, el gobernador de Britania. Sueña con escribir algún día la historia de su tiempo, «sin ira y sin parcialidad». Para eso necesita testigos. Y tú tienes una barca, y ganas de ver mundo.'),
 steps:[
  {obj:_t(10565,'Habla con Tácito, junto a la Curia'),npc:'tacito',scene:[[_t(9950,'Tácito'),_t(10566,'Has demostrado que sabes buscar la verdad entre papeles y mentiras. Te propongo un trabajo. Quiero escribir la historia de estos años: la guerra de Judea, la rebelión del Rin, Britania… y el Vesubio. Pero no me fío de lo que se cuenta en los banquetes.')],
    [_t(9950,'Tácito'),_t(10567,'Busca a cuatro testigos: un superviviente de Pompeya, un veterano de Jerusalén, alguien de Colonia que viviera la rebelión de Civil, y un soldado de mi suegro en Britania. Pregúntales qué vieron. Yo pago el viaje.')],
    {who:_t(9950,'Tácito'),ask:_t(10568,'¿Por qué Tácito quiere hablar con testigos en lugar de copiar lo que se cuenta?'),a:[_t(10569,'Porque un historiador debe buscar fuentes fiables, no rumores'),_t(10570,'Porque así le pagan más'),_t(10571,'Porque los testigos escriben mejor que él')],ok:_t(10572,'Exacto. Tucídides ya lo decía: hay que preguntar a los que estuvieron allí, y aun así comparar lo que dicen.'),ko:_t(10573,'No: un buen historiador busca fuentes fiables y las compara. Los rumores de banquete no sirven.')}]},
  {obj:_t(10574,'Busca en Pompeya a Herenio, el superviviente'),npc:'fossor',scene:[['Herenio',_t(10575,'¿Un historiador? Dile que no fue solo la ceniza. Primero cayeron piedras ligeras toda la tarde y toda la noche; los tejados se hundían. Muchos se quedaron en casa, esperando. Lo que los mató fue lo de la mañana: una nube ardiente que bajó corriendo por el monte.')],
    ['Herenio',_t(10576,'Y dile también que el emperador mandó ayuda. Eso hay que reconocérselo a Tito.')],
    ['',_t(10577,'Apuntas sus palabras en tus tablillas de cera. Primer testimonio.')]]},
  {obj:_t(10578,'Busca en Jerusalén a Lucio Antonio, el veterano'),npc:'veteranus',scene:[['Lucio Antonio',_t(10579,'Que escriba lo que fue: un asedio terrible para los dos bandos. Hambre dentro de la ciudad, crucifixiones fuera. Cuando ardió el templo, nadie supo decirme quién dio la orden.')],
    ['Lucio Antonio',_t(10580,'Y que no escriba que los judíos son cobardes: lucharon hasta el final. Lo sé porque yo estaba delante.')],
    ['',_t(10581,'Muchos años después, Tácito escribirá sobre los judíos con desprecio y muchos errores. No siempre los historiadores escuchan a sus testigos.')]]},
  {obj:_t(10582,'Busca en Colonia a Ennio, el soplador de vidrio'),npc:'vitrarius',scene:[['Ennio',_t(10583,'La rebelión de Civil… Los germanos de la otra orilla nos pedían que matáramos a todos los romanos de la ciudad y derribáramos las murallas. Nosotros dijimos que no: aquí vivimos mezclados, nuestros hijos tienen madres romanas.')],
    ['Ennio',_t(10584,'Tuvimos que fingir que estábamos con los rebeldes para sobrevivir. Cuando volvieron las legiones, nos acusaron de traidores. Así es la guerra en una frontera.')]]},
  {obj:_t(10585,'Busca en el campamento de Agrícola a Tito Flavio'),npc:'miles_agricolae',scene:[['Tito Flavio',_t(10586,'¿Te manda el yerno del general? Pues dile que su suegro es un buen jefe: elige él mismo dónde acampar, no deja que los oficiales roben y castiga poco pero en serio.')],
    ['Tito Flavio',_t(10587,'Y dile también lo que no dicen los informes: que a los britanos les quemamos las cosechas, y que muchos de sus hijos acaban vendidos en el mercado de Londinium.')],
    {who:'Tito Flavio',ask:_t(10588,'¿Qué le pasa a un testimonio de un soldado sobre su propio general?'),a:[_t(10589,'Puede ser sincero, pero también interesado: hay que compararlo con otros'),_t(10590,'Siempre es falso'),_t(10591,'Siempre es verdad')],ok:_t(10592,'Eso es pensar como un historiador.'),ko:_t(10593,'Ni siempre verdad ni siempre mentira: hay que compararlo con otras fuentes.')}]},
  {obj:_t(10594,'Vuelve con Tácito, junto a la Curia'),npc:'tacito',scene:[[_t(9950,'Tácito'),_t(10595,'Cuatro testigos, cuatro guerras distintas, y en todos lo mismo: la gente corriente paga los errores de los poderosos. Lo escribiré, aunque tarde años.')],
    [_t(9950,'Tácito'),_t(10596,'Y lo haré. Escribiré la vida de mi suegro, y luego las Historias, y luego los Anales. Y pondré en boca de un jefe britano lo que me has traído de Britania: «Donde crean un desierto, lo llaman paz».')],
    ['',_t(10597,'Tácito escribirá la Vida de Agrícola en el 98, las Historias hacia el 105 y los Anales hacia el 115. De sus obras se conserva solo una parte.')]]}],
 end:_t(10598,'Has recorrido el imperio de un extremo a otro buscando testigos: Pompeya bajo la ceniza, Jerusalén en ruinas, Colonia en la frontera del Rin y el campamento de Agrícola en el norte de Britania.'),
 learn:_t(10599,'La historia se escribe con fuentes. Los historiadores antiguos, como Tucídides o Tácito, buscaban testigos y documentos, pero también tenían sus prejuicios y sus intereses. Por eso, hoy, comparamos siempre varias fuentes y nos preguntamos quién habla, cuándo y por qué.')};
{const fin0=storyFinale;storyFinale=function(){fin0();if(MODE!=='roma'||!state.story||state.story.extraDone)return;
  if(state.story.extra&&STORY.includes(STORY_EXTRA_ROMA)){state.story.extraDone=1;save();$('dBody').innerHTML+=_t(10600,'<p class="sub">Has completado también el capítulo extra, «Las historias de Tácito».</p>');return;}
  const o=$('dOpts'),b=document.createElement('button');b.innerHTML=_t(10601,'<span class="n">2</span><span>Capítulo extra: «Las historias de Tácito» (un viaje por las provincias)</span>');
  b.onclick=()=>{closeDialog();state.story.extra=1;if(!STORY.includes(STORY_EXTRA_ROMA))STORY.push(STORY_EXTRA_ROMA);state.story.ch=STORY.length-1;state.story.st=0;save();storyResume(true);};o.appendChild(b);};}
{const ss0=startStory;startStory=function(){const r=ss0.apply(this,arguments);if(MODE==='roma'&&state.story&&state.story.extra&&!STORY.includes(STORY_EXTRA_ROMA)){STORY.push(STORY_EXTRA_ROMA);if(state.story.ch>=STORY.length-1&&!state.story.extraDone)storyResume(false);}return r;};}
