const bg0=buildGeoGR;buildGeoGR=function(){bg0();try{colonoBuild();}catch(e){console.warn('colono',e);}};
function colonoBuild(){if(MODE!=='atenas')return;const f=findFree(ACADEMY.x+330,ACADEMY.z-60,6);COLONO.x=f[0];COLONO.z=f[1];COLONO.on=true;
  groveIn(null,f[0],f[1],130,130,95,{laurel:3,wolive:2},31.7);
  place('colono','Colono Hípico, el bosque de las Euménides','ΚΟΛΩΝΟΣ ΙΠΠΙΟΣ','Una colina con un bosque sagrado de laureles, olivos y vides, lleno de ruiseñores: así lo describe Sófocles, que nació aquí, en su <i>Edipo en Colono</i>. Es el bosque de las Euménides, las «Benévolas»: nadie entra en él, se pasa de largo en silencio y sin mirar. Aquí, según la tragedia, vino a morir Edipo, ciego y desterrado, y su tumba secreta protege a Atenas. En la colina se veneran Poseidón Hípico, el dios de los caballos, y Atenea Hípica. Sófocles murió hace veinte años, y la obra se estrenó después de su muerte, en el 401.',f[0],f[1]+70,0);}
// ---- añadidos a destinos que ya existen
{const w=(id,fn)=>{const o=SIMPLE_RO[id];if(!o)return;const ex=o.extra;o.extra=function(I){if(ex)ex.call(this,I);try{fn(I);}catch(e){console.warn('bosque '+id,e);}};};
 // el Averno: encinar oscuro alrededor del lago y la rama de oro
 w('cumae',I=>{const L={x:I.x+60,z:I.z-60};groveIn(I,L.x,L.z,300,300,260,{holm:4,oak:1,laurel:1},41.3,(x,z)=>Math.hypot(x-L.x,z-L.z)<52);
   const rx=L.x-30,rz=L.z-82,ry=terrainH(rx,rz);if(GLB.ok)placeModules('T_olive',[{x:rx,y:ry,z:rz,a:0.4,sx:2.0,sy:1.9,sz:2.0,cf:new THREE.Color('#33482b')}],{far:1600});addCirc(rx,rz,1.2);
   const gm=new THREE.MeshBasicMaterial({color:'#f2c84a'}),g=grp(rx+1.2,ry+3.1,rz+0.4,0.6);const st=new THREE.Mesh(new THREE.CylinderGeometry(0.03,0.05,1.3,5),gm);st.rotation.z=1.1;g.add(st);
   for(let k=0;k<7;k++){const lf=new THREE.Mesh(new THREE.ConeGeometry(0.07,0.22,4),gm);lf.position.set(-0.5+k*0.15,0.15+((k%2)?0.08:-0.04),0);lf.rotation.z=k%2?0.6:-0.6;g.add(lf);}
   egxObj(rx+1.5,rz+1.5,undefined,'av:rama','Una rama dorada','entre las hojas de una encina',3);
   place('averno_bosque','Los bosques del Averno','AVERNVS','Virgilio rodea el lago de bosques oscuros, tan espesos que no dejan ver el cielo, y en uno de ellos esconde la rama de oro sin la que nadie puede bajar a los Infiernos (<i>Eneida</i> 6, 136-148 y 237-238). Estrabón cuenta que esos bosques daban miedo de verdad, hasta que Agripa los taló en el 37 a.C. para hacer aquí el puerto Julio y abrir un túnel hasta Cumas: desde entonces el lugar perdió su misterio (<i>Geografía</i> 5, 4, 5). Quedan algunos encinares.',L.x+50,L.z-60,0);});
 // Massilia: lo que queda del bosque sagrado que César mandó talar
 w('massilia',I=>{const f=findFree(I.x-260,I.z-230,8),cx=f[0],cz=f[1];groveIn(I,cx,cz,170,170,190,{oak:3,holm:2,cypress:1},52.9);
   const RL=forRng(52.91),wd=lam('#5a4636'),wd2=lam('#6e5a44');
   for(let k=0;k<26;k++){const x=cx+(RL()-0.5)*150,z=cz+(RL()-0.5)*150;if(!isFree(x,z,1))continue;const r=0.4+RL()*0.4,h=0.5+RL()*0.5,m=new THREE.Mesh(new THREE.CylinderGeometry(r,r*1.15,h,8),wd);m.position.set(x,terrainH(x,z)+h/2,z);m.castShadow=true;scene.add(m);addCirc(x,z,r);}   // tocones
   for(let k=0;k<4;k++){const a=k/4*TAU,x=cx+Math.cos(a)*14,z=cz+Math.sin(a)*14,gy=terrainH(x,z),g=grp(x,gy,z,a+Math.PI);box(0.7,2.6,0.6,wd2,0,1.3,0,g);box(0.5,0.1,0.1,lam('#2a2018'),0,2.1,0.31,g);box(0.12,0.12,0.1,lam('#2a2018'),-0.15,2.35,0.31,g);box(0.12,0.12,0.1,lam('#2a2018'),0.15,2.35,0.31,g);addCirc(x,z,0.5);}   // ídolos: troncos tallados sin arte
   place('massilia_lucus','El bosque sagrado de Massilia','LVCVS','Lucano describe un bosque junto a Massilia que nadie había tocado desde tiempos remotos, tan espeso que no entraba el sol: los pájaros no se posaban en él, los dioses eran troncos tallados sin arte y los altares estaban manchados de sangre. Cuando César sitió la ciudad, en el 49 a.C., mandó talarlo para hacer máquinas de asedio; los soldados no se atrevían, hasta que él mismo cogió un hacha y golpeó el primero un roble (<i>Farsalia</i> 3, 399-452). Lucano escribe como poeta, unos cien años después: no sabemos cuánto hay de verdad. Aquí ves lo que podría quedar: tocones y una arboleda que ha vuelto a crecer.',cx,cz+90,0);});
 // Dafne, junto a Antioquía: laureles, cipreses y fuentes de Apolo
 w('antiochia',I=>{const f=findFree(I.x+250,I.z+230,8),cx=f[0],cz=f[1];groveIn(I,cx,cz,200,200,230,{laurel:3,cypress:3,plane:1},63.1);
   const wm=new THREE.MeshPhongMaterial({color:'#4f8a96',shininess:60});for(const[dx,dz]of[[-30,-20],[25,10],[-5,40]]){const x=cx+dx,z=cz+dz,w2=new THREE.Mesh(new THREE.CircleGeometry(3.2,20),wm);w2.rotation.x=-Math.PI/2;w2.position.set(x,terrainH(x,z)+0.15,z);scene.add(w2);addCirc(x,z,3.4);}
   place('dafne_bosque','El bosque de Dafne','DAPHNE','A cuarenta estadios de Antioquía, un gran bosque sagrado de laureles y cipreses atravesado por fuentes, con el templo de Apolo y de Ártemis. Es un asilo: quien se refugia en él no puede ser apresado (Estrabón, <i>Geografía</i> 16, 2, 6). Pompeyo le añadió tierras, y está prohibido cortar sus cipreses. Aquí, dicen los de Antioquía, la ninfa Dafne se convirtió en laurel para huir de Apolo.',cx,cz-70,0);});}
// la rama de oro
function avAct(o){const z=state.seen||(state.seen={});if(!z.ramaOro){z.ramaOro=1;save();qAdd('so',1,'Conoces la rama de oro.');}
  vmS('✦','La rama de oro','en una encina junto al Averno','<p>Entre las hojas oscuras brilla una rama con las hojas y el tallo de oro. La Sibila se lo había dicho a Eneas: en un árbol sombrío se esconde una rama de oro, consagrada a la reina de los muertos; todo el bosque la oculta, y sin ella nadie baja a los Infiernos. Si el destino te llama, se deja arrancar sola; si no, no la cortarás ni con hierro. Y cuando se arranca una, nace otra igual (<i>Eneida</i> 6, 136-148).</p><p>Dos palomas de su madre, Venus, guiaron a Eneas hasta el árbol (6, 190-211).</p><p class="sub">Siglos más tarde, el antropólogo James Frazer tituló <i>La rama dorada</i> su gran libro sobre los mitos y los ritos, empezando por el rey del bosque de Nemi.</p>',[vmBye]);}
{const f=egxAct0;egxAct0=function(o){if(String(o.act).startsWith('av:'))return avAct(o);return f(o);};}
