function bvWalker(w){const g=w.g,u=g.userData;w.bv=1;if(!GLB.ok||!g)return;g.rotation.order='YXZ';const P=bvParts(g),moving=w.speed>0,r=Math.random(),r2=Math.random();
  const kidOK=moving&&!P.has('P_beard')&&!P.has('P_hydria')&&!P.has('P_amphora')&&!P.has('P_spear')&&!P.has('P_scutum')&&!P.has('P_galea')&&!w.barks&&!bvGreyHair(g);
  if(kidOK&&r<0.4){const s=0.6+Math.random()*0.16;g.scale.set(s,s,s);u.bt='niño';w.speed*=1.15;w.sf=1.5;if(Math.random()<0.35){u.bt='niño que corre';w.speed*=1.6;u.legAmp=0.62;u.lean=0.06;}}
  else if(r2<0.1){u.bt='anciano';u.stoop=0.1+Math.random()*0.06;u.legAmp=0.26;w.sf=1.3;if(moving)w.speed*=0.6;bvGrey(g);if(!P.has('P_staff')&&Math.random()<0.55)bvStick(g);}
  else{const q=Math.random();if(q<0.14){g.scale.x*=1.16;g.scale.z*=1.16;u.bt='grueso';if(moving)w.speed*=0.88;}else if(q<0.26){g.scale.x*=0.88;g.scale.z*=0.88;u.bt='flaco';}
    if(moving){const k=Math.random();if(P.has('P_hydria')||P.has('P_amphora')){u.gait='carga';w.speed*=0.85;u.lean=0.04;w.sf=1.1;}
      else if(k<0.15){u.gait='prisa';w.speed*=1.35;u.legAmp=0.52;u.lean=0.05;w.sf=0.95;}else if(k<0.27){u.gait='cansado';w.speed*=0.75;u.stoop=0.04;u.legAmp=0.3;}else if(k<0.33){u.gait='cojea';w.speed*=0.7;u.limp=1;}}}
  u.post=bvPost(g,P);if(u.stoop)g.rotation.x=u.stoop;try{stWalker(w,g,P);}catch(e){}}
function bvNpc(o){const g=o.g,u=g.userData;o.bv=1;if(!GLB.ok||!g)return;g.rotation.order='YXZ';const P=bvParts(g),d=o.data||{},tt=((d.title||'')+' '+(d.name||'')).toLowerCase();
  if(/ancian|viej[oa]\b|\bvieja|\bviejo|senex|geronte/.test(tt)){u.stoop=0.08;g.rotation.x=0.08;}u.post=bvPost(g,P);try{stNpc(o,g,P,tt);}catch(e){}}
{const pg=pjGreet;pjGreet=function(n,first){let r=pg(n,first);try{r+=memGreet(n,first);}catch(e){}return r;};}
{const pw=personWalk;personWalk=function(g,ph,amp){pw(g,ph,amp);const u=g.userData;if(u.stoop===undefined&&u.lean===undefined&&!u.limp)return;
  g.rotation.x=(u.stoop||0)+(u.lean||0)*amp;if(u.limp&&u.legs){u.legs[0].rotation.x*=0.45;const s=Math.sin(ph);g.rotation.z=(s>0?0.075:0.015)*s*amp;}};}
{const r0=gsRig;gsRig=function(g){const had=g.userData.gs,gs=r0(g);if(!had){gs.g=g;if(g.userData.post==='cruzados'||g.userData.post==='espalda'||g.userData.post==='apoyado')gsRest(gs);}return gs;};}
Object.assign(GSET,{cruzados:[-0.42,-0.28,-0.42,-0.28,0.04,0,-1.75,-1.6]});
{const r0=gsRest;gsRest=function(gs){r0(gs);const g=gs.g,p=g&&g.userData.post;if(!p||g===GS.dlgG)return;if(p==='cruzados')gsSet(gs,'cruzados',1,true);else if(p==='espalda'||p==='apoyado')gsSet(gs,'espalda',1,true);};}
function bvTick(dt){if(!state||ui==='start')return;BV.t-=dt;if(BV.t<=0){BV.t=1.5;let n=0;const t0=performance.now();for(const w of walkers)if(w.bv===undefined&&w.g){bvWalker(w);if(++n>90)break;}for(const o of npcObjs)if(o.bv===undefined&&o.g){bvNpc(o);if(++n>120)break;}BV.ms=performance.now()-t0;if(n)BV.t=0.25;}
  const P=player,t=performance.now()/1000;
  // brazos cruzados de verdad: los antebrazos giran hacia dentro, por delante del pecho
  for(const g of GS.list){const gs=g.userData.gs;if(!gs||!gs.fore||!g.visible)continue;const on=Math.abs((gs.tgt.rf||0)-GSET.cruzados[7])<0.01&&Math.abs((gs.tgt.lf||0)-GSET.cruzados[6])<0.01,k=Math.min(1,dt*5);
    for(let i=0;i<2;i++){const f=gs.fore[i];if(!f)continue;const tg=on?-(gs.side?gs.side[i]:(i?1:-1))*0.95:0;f.rotation.z+=(tg-f.rotation.z)*k;}}
  for(const g of GS.list){const u=g.userData,p=u.post;if(!p||!g.visible||u.pose||u.sitting)continue;const dx=g.position.x-P.x,dz=g.position.z-P.z;if(dx*dx+dz*dz>400)continue;
    const mv=u._px!==undefined&&Math.abs(g.position.x-u._px)+Math.abs(g.position.z-u._pz)>0.003;u._px=g.position.x;u._pz=g.position.z;if(mv){u._st=0;continue;}u._st=(u._st||0)+dt;if(u._st<0.6)continue;
    const k=Math.min(1,dt*3),ph=(u.gs&&u.gs.t)||0;
    if(p==='peso'){g.rotation.z+=((0.03+0.012*Math.sin(t*0.45+ph))-g.rotation.z)*k;if(u.legs)u.legs[1].rotation.x+=(-0.13-u.legs[1].rotation.x)*k;}
    else if(p==='apoyado')g.rotation.x+=((u.stoop||0)-0.07-g.rotation.x)*k;}}
// ============================================================ RIGOR VISUAL: peinados y barbas de cada época, distintivos y objetos de oficio
// Atenas 386: el hombre adulto lleva barba (afeitarse se pondrá de moda con Alejandro: Ateneo 13, 565a); muchas mujeres recogen el pelo en un
// sakkos o una redecilla (kekryphalos), como en los vasos áticos. Roma 80: los hombres van afeitados (la barba vuelve con Adriano, Historia
// Augusta, Adriano 26); las damas llevan el tupé de rizos flavio (retratos de Julia, hija de Tito); los niños libres, la bulla al cuello
// (Plutarco, Cuestiones romanas 101); los senadores, calcei negros. Objetos de oficio en la mano de los personajes según su título.
// La primera vez que ves de cerca cada cosa, un aviso la explica (una vez por partida).
const ST={t:0,curl:null,front:{}};
const ST_TXT={
 sakkos:['El sakkos','Muchas atenienses se recogen el pelo en un sakkos, una bolsa de tela a veces bordada, o en una redecilla (kekryphalos). Así aparecen en los vasos áticos pintados de esta época: hilando, en la fuente o preparando una boda.'],
 barba:['La barba del ciudadano','En Atenas el hombre adulto lleva barba; ir afeitado es cosa de muchachos. Solo dentro de medio siglo, con Alejandro Magno, se pondrá de moda afeitarse (lo cuenta Ateneo, 13, 565a).'],
 afeitado:['Caras afeitadas','En la Roma del 80 casi todos los hombres van afeitados, y el barbero (tonsor) es visita de cada día. La primera afeitada de un joven se celebra: es la depositio barbae. Solo llevan barba los filósofos y quienes están de luto, hasta que el emperador Adriano, dentro de unos cuarenta años, la ponga de moda.'],
 flavio:['El peinado flavio','Las damas de Roma lucen sobre la frente un alto tupé de rizos, hechos con tenacillas calientes (calamistrum) y a veces con postizos. Es la moda de la corte de los Flavios: así aparece Julia, la hija de Tito, en sus retratos. Peinarlas es trabajo de esclavas especialistas, las ornatrices.'],
 bulla:['La bulla','Los niños libres de Roma llevan al cuello la bulla, un amuleto contra el mal de ojo: de oro los ricos, de cuero los pobres. El muchacho la deja, ofrecida a los Lares de la casa, el día que viste la toga viril, hacia los dieciséis años.'],
 calcei:['Los zapatos del senador','Fíjate en sus pies: el senador no lleva sandalias, sino calcei senatorii, botines de cuero negro atados con correas. Los de familia patricia llevan además una lunula, una media luna de marfil.'],
 rollo:['Un rollo de papiro','Los libros de esta época son rollos: hojas de papiro pegadas en una tira larga. Se leen desenrollando con una mano y enrollando con la otra; una obra larga ocupa muchos rollos («libros»).'],
 tablillas:['Tablillas de cera','Dos o más tablas de madera con una capa de cera, unidas como un librito. Se escribe con un punzón (stylos en griego, stilus en latín) y se borra alisando la cera con el otro extremo, que es plano. Sirven para cuentas, cartas y deberes de escuela.'],
 estrigil:['El estrígil','Una rasqueta curva de bronce. En el gimnasio el atleta se unta de aceite y polvo y, tras el ejercicio, se rasca la piel con ella para limpiarse el sudor y la arena.'],
 cayado:['El cayado','El cayado del pastor (kalaúrops en griego, pedum en latín): con el gancho se atrapa por la pata a la oveja o la cabra que se escapa. Es también el atributo de Pan.']};
function stHair(g){let c=null;g.traverse(o=>{if(c||!o.isMesh)return;const p=(o.userData.part||(o.parent&&o.parent.userData.part)||'');if(/^P_hair/.test(p))c=o.material.color.clone();});return c||new THREE.Color('#3b2a1e');}
function stHead(g,m){const gs=g.userData.gs;if(gs&&gs.head){m.position.y-=1.55;gs.head.add(m);}else g.add(m);return m;}
function stFind(g,part){let r=null;g.traverse(o=>{if(!r&&o.userData&&o.userData.part===part)r=o;});return r;}
function stCurlGeo(){if(ST.curl)return ST.curl;const F=faceSpots(),R0=(F.bl!=null?F.bl:0.11)+0.004,s=new THREE.SphereGeometry(0.024,7,5).toNonIndexed(),pos=[],nor=[];
  for(let r=0;r<3;r++){const n=11-r*2;for(let i=0;i<n;i++){const a=-1.15+2.3*i/(n-1)+(r%2)*0.06,R=R0*(0.9-r*0.16),y=1.915+r*0.032;
    const P=s.attributes.position,N=s.attributes.normal;for(let k=0;k<P.count;k++){pos.push(P.getX(k)+Math.sin(a)*R,P.getY(k)+y,P.getZ(k)+Math.cos(a)*R-0.035);nor.push(N.getX(k),N.getY(k),N.getZ(k));}}}
  const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));g.setAttribute('normal',new THREE.Float32BufferAttribute(nor,3));return ST.curl=g;}
function stFront(names,y0,y1){const k=names.join()+y0;if(ST.front[k]!==undefined)return ST.front[k];let mz=-1,v=new THREE.Vector3();for(const n of names){const P=GLB.parts[n];if(!P)continue;for(const m of P.meshes){const a=m.geo.attributes.position;for(let i=0;i<a.count;i+=2){v.fromBufferAttribute(a,i).applyMatrix4(m.mat);const y=v.y+P.pos.y;if(y>y0&&y<y1&&v.z+P.pos.z>mz)mz=v.z+P.pos.z;}}}return ST.front[k]=mz>0?mz:0.14;}
function stHand(g,item){const a=g.userData.arms&&g.userData.arms[1];if(!a)return false;g.updateMatrixWorld(true);const b=new THREE.Box3().setFromObject(a),sy=g.scale.y||1,hy=(b.min.y-g.position.y)/sy;if(!(hy>0.4&&hy<1.2))return false;
  const y=hy-a.position.y+0.05,W=M.wood;let m;
  if(item==='rollo'){m=new THREE.Mesh(new THREE.CylinderGeometry(0.028,0.028,0.27,8),lam('#e6d8b8'));m.rotation.x=Math.PI/2;m.position.set(0,y,0.06);}
  else if(item==='tablillas'){m=new THREE.Mesh(new THREE.BoxGeometry(0.035,0.21,0.15),lam('#7a5232'));m.position.set(0.02,y-0.06,0.03);}
  else if(item==='estrigil'){m=new THREE.Mesh(new THREE.TorusGeometry(0.06,0.009,4,10,Math.PI*1.1),M.bronze||lam('#a8803a'));m.rotation.y=Math.PI/2;m.position.set(0,y-0.05,0.02);}
  else if(item==='cayado'){m=new THREE.Group();const st=new THREE.Mesh(new THREE.CylinderGeometry(0.018,0.022,1.7,6),W);st.position.y=0;m.add(st);const hk=new THREE.Mesh(new THREE.TorusGeometry(0.06,0.016,5,10,Math.PI*1.3),W);hk.position.set(0.06,0.85,0);m.add(hk);m.position.set(0,0.85-a.position.y+0.02,0.06);}
  if(!m)return false;m.traverse(o=>{if(o.isMesh)o.castShadow=true;});m.userData.keep=1;a.add(m);return true;}
function stItem(tt){if(/maestr|gramátic|filósof|poeta|escritor|historiador|orador|retóric|rétor|sofista|bibliotec|rapsod|lector/.test(tt))return'rollo';
  if(/escriba|secretari|contable|banquer|trapezit|argentari|cambista|mercader|comerciante|negociante|publicano|naviero|notari|escribano|alumno|estudiante/.test(tt))return'tablillas';
  if(/atleta|luchador|pancraci|púgil|pugil|gimnas|pedotrib|entrenador|corredor/.test(tt))return'estrigil';
  if(/pastor|cabrer|boyer|porquer|vaquer/.test(tt))return'cayado';return null;}
function stFeat(g,k){(g.userData.feat||(g.userData.feat=[])).push(k);}
function stWalker(w,g,P){const u=g.userData,ro=MODE==='roma',kid=/^niño/.test(u.bt||''),fem=P.has('P_hair_f')||P.has('P_chiton_f'),male=P.has('P_hair_m')&&!fem,arm=P.has('P_galea')||P.has('P_spear')||P.has('P_helmet');
  if(!ro){if(male&&!kid&&!arm&&!P.has('P_beard')&&Math.random()<0.8){const b=glbPart('P_beard',{hair:lam('#'+stHair(g).getHexString())});if(b){stHead(g,b);stFeat(g,'barba');}}else if(P.has('P_beard'))stFeat(g,'barba');
    if(fem&&!kid&&!P.has('P_veil')&&!P.has('P_hydria')&&Math.random()<0.45){const s=new THREE.Mesh(ST.sg||(ST.sg=new THREE.SphereGeometry(0.135,14,10)),lam(['#7a2a1e','#2f4a6a','#d8c8a8','#6a3a5a','#8a6a2a'][Math.floor(Math.random()*5)]));s.scale.set(0.95,0.88,1.22);s.position.set(0,1.87,-0.105);s.castShadow=true;stHead(g,s);stFeat(g,'sakkos');}}
  else{if(P.has('P_beard')&&Math.random()<0.9){const b=stFind(g,'P_beard');if(b){b.parent.remove(b);const F=faceSpots();g.traverse(o=>{if(o.isMesh&&o.material===F.mat&&o.geometry.attributes.color){const c=o.geometry.attributes.color;o.geometry=faceGeo('#'+new THREE.Color(c.getX(0),c.getY(0),c.getZ(0)).getHexString(),true);}});}}
    if(male&&!kid&&!stFind(g,'P_beard')){stTrim(g);stFeat(g,'afeitado');}
    if(fem&&!kid&&!P.has('P_veil')&&Math.random()<0.45){const m=new THREE.Mesh(stCurlGeo(),personMat('#'+stHair(g).getHexString(),'hair'));const cg=m.geometry;if(!cg.attributes.color){const n=cg.attributes.position.count;cg.setAttribute('color',new THREE.Float32BufferAttribute(new Float32Array(n*3).fill(0.9),3));}m.castShadow=true;stHead(g,m);stFeat(g,'flavio');}
    if(kid){const z=stFront(['P_tunic_short','P_chiton_m','P_chiton_f','P_toga'],1.22,1.42);const b=new THREE.Mesh(ST.bg||(ST.bg=new THREE.SphereGeometry(0.034,10,8)),lam('#d4a640'));b.scale.set(1,1,0.35);b.position.set(0,1.31,z+0.01);g.add(b);
      const c=new THREE.Mesh(ST.cg||(ST.cg=new THREE.TorusGeometry(0.1,0.004,4,18)),lam('#6a4a2a'));c.rotation.x=Math.PI/2-0.5;c.position.set(0,1.5,0.03);g.add(c);stFeat(g,'bulla');}}
  if(!kid&&!u.stoop&&!P.has('P_hydria')&&!P.has('P_amphora')&&!P.has('P_basket')&&!arm&&!u.post){const r=Math.random();const it=r<0.06?'tablillas':r<0.09?'rollo':null;if(it&&stHand(g,it))stFeat(g,it);}}
// patillas: el pelo masculino del modelo baja hasta la mandíbula y de frente parece barba; al romano afeitado se le recorta a la altura de la oreja
function stTrim(g){const hp=stFind(g,'P_hair_m');if(!hp)return;hp.updateMatrix();hp.traverse(o=>{if(!o.isMesh)return;let ng=(ST.trim||(ST.trim=new Map())).get(o.geometry);
  if(!ng){ng=o.geometry.clone();const A=ng.attributes.position,v=new THREE.Vector3(),M4=new THREE.Matrix4().multiplyMatrices(hp.matrix,o.matrix),Mi=M4.clone().invert();
    for(let i=0;i<A.count;i++){v.fromBufferAttribute(A,i).applyMatrix4(M4);if(v.z>-0.03&&v.y<1.83){v.y=1.83+(v.y-1.83)*0.08;v.z=Math.min(v.z,0.07);v.applyMatrix4(Mi);A.setXYZ(i,v.x,v.y,v.z);}}ng.computeVertexNormals();ST.trim.set(o.geometry,ng);}o.geometry=ng;});}
function stNpc(o,g,P,tt){if(!GLB.ok)return;const it=stItem(tt);if(it&&!(it==='cayado'&&P.has('P_staff'))&&!P.has('P_spear')&&!g.userData.pose&&!P.has('P_basket')){if(stHand(g,it)){stFeat(g,it);if(g.userData.post==='cruzados'||g.userData.post==='espalda')g.userData.post='peso';}}
  if(MODE==='roma'&&/senador|cónsul|pretor|censor|emperador/.test(tt)){const sd=lam('#5a3d26'),bk=lam('#1f1612');let ch=false;g.traverse(m=>{if(m.isMesh&&m.material===sd){m.material=bk;ch=true;}});if(ch)stFeat(g,'calcei');}}
function stTick(dt){if(!state||ui!=='play')return;ST.t-=dt;if(ST.t>0)return;ST.t=1;const P=player,seen=state.seen||(state.seen={});let best=null,bd=4.5;
  const chk=g=>{if(!g||!g.visible)return;const f=g.userData.feat;if(!f)return;const d=Math.hypot(g.position.x-P.x,g.position.z-P.z);if(d>=bd)return;for(const k of f)if(!seen['st:'+k]&&ST_TXT[k]){best=k;bd=d;return;}};
  for(const w of walkers)if(!w.home&&Math.abs(w.g.position.x-P.x)<5&&Math.abs(w.g.position.z-P.z)<5)chk(w.g);for(const o of npcObjs)if(!o.hidden&&Math.abs(o.x-P.x)<5&&Math.abs(o.z-P.z)<5)chk(o.g);
  if(best){seen['st:'+best]=1;const T=ST_TXT[best];toast('<span class="label">Fíjate · '+T[0]+'</span><br>'+T[1]);}}
// ============================================================ PERSONAS, NO CARTELES: memoria y fama, familias y acompañantes, pleitos, comer, la fuente, el calor
// Fama: lo que haces corre de boca en boca (Hesíodo, Trabajos y días 760-764: la phḗmē «también es una diosa»; Virgilio, Eneida 4, 173-188).
// Se deduce de lo que ya guarda la partida (lecciones, favores a los dioses, capítulos, caballo, ciudadanía, casa) y de los empujones.
const MEM={t:0,gT:0};
function memz(){if(!state.memLog){state.memLog=[];const L=state.memLog;for(const id of state.lessons||[])L.push({k:'lec',r:id,d:0});
  for(const id in ((state.gods||{}).q||{}))if(state.gods.q[id]==='done')L.push({k:'god',r:id,d:0});if(state.story&&state.story.done)L.push({k:'cap',r:state.story.done,d:0});
  try{if(hz().own)L.push({k:'horse',d:0});if(cz().st>=2)L.push({k:'ciu',d:0});if(cz().st>=3)L.push({k:'casa',d:0});}catch(e){}}return state.memLog;}
function memHas(k,r){return memz().some(e=>e.k===k&&(r===undefined||e.r===r));}
function memTick(dt){if(!state||ui==='start')return;MEM.t-=dt;if(MEM.t>0)return;MEM.t=3;const L=memz(),d=state.day||1,add=(k,r)=>{if(!memHas(k,r)){L.push({k,r,d});if(L.length>60)L.shift();}};
  for(const id of state.lessons||[])add('lec',id);for(const id in ((state.gods||{}).q||{}))if(state.gods.q[id]==='done')add('god',id);
  if(state.story&&state.story.done&&!memHas('cap',state.story.done))add('cap',state.story.done);try{if(hz().own)add('horse');if(cz().st>=2)add('ciu');if(cz().st>=3)add('casa');}catch(e){}
  if((state.bumps||0)>=6&&!memHas('bump'))add('bump');
  // por la calle: alguien te reconoce
  if(ui==='play'&&performance.now()/1000-MEM.gT>120&&Math.random()<0.3){const P=player;for(const w of walkers){if(w.home||!w.g.visible||w.fol)continue;const dd=Math.hypot(w.g.position.x-P.x,w.g.position.z-P.z);if(dd<4.5&&dd>1.2){const s=memSay(true);if(s){MEM.gT=performance.now()/1000;toast('<i>«'+s+'»</i>');memFirst();}break;}}}}
function memFama(){let f=0;for(const e of memz())f+=e.k==='lec'?2:e.k==='god'?3:e.k==='cap'?2:e.k==='casa'?3:e.k==='bump'?0:1;return f-Math.min(20,Math.floor((state.bumps||0)/3));}
function memName(id){const n=(typeof NPCS!=='undefined'?NPCS:[]).find(n=>n.id===id);if(n)return n.name;const g=(typeof GODS!=='undefined'?GODS:[]).find(g=>g.id===id);return g?g.name:null;}
function memSay(street,n){const p=pjz()||{},f=p.g==='f',ro=MODE==='roma',L=memz().filter(e=>e.d>0||Math.random()<0.5).slice(-12).reverse();if(!L.length)return null;
  const heard=n?(state.seen['mm:'+n.id]||[]):[];const e=L.find(e=>!heard.includes(e.k+(e.r||'')))||null;if(!e)return null;
  const quien=f?'la que':'el que',ese=f?'esa':'ese',nm=e.r!==undefined?memName(e.r):null;let s=null;
  if(street){s=e.k==='lec'&&nm?'Mira, '+ese+' es '+(p.name||'')+', '+quien+' supo responder a '+nm+'.':e.k==='god'&&nm?'¿Ves a '+ese+'? Dicen que '+nm+' le debe un favor.':e.k==='horse'?'¡Qué caballo lleva '+ese+' forastero!'.replace('forastero',f?'forastera':'forastero'):e.k==='casa'?'Ahí va '+(f?'la nueva vecina':'el nuevo vecino')+'.':e.k==='bump'?'Cuidado, que ahí viene '+quien+' va empujando a todo el mundo.':e.k==='cap'?'Ese nombre, '+(p.name||'')+'… se oye mucho últimamente.':null;}
  else{s=e.k==='lec'&&nm?(n&&e.r===n.id?'Todavía me acuerdo de lo bien que respondiste.':'¿Tú eres '+quien+' respondió tan bien a '+nm+'? Me lo contaron en '+(ro?_t(10503,'las termas'):'la fuente')+'.'):
    e.k==='god'&&nm?'Me han dicho que hiciste un favor a '+nm+'. Los dioses no olvidan, y nosotros tampoco.':e.k==='horse'?'Así que ahora tienes caballo… Se te ve subir en el mundo.':e.k==='ciu'?(ro?'¡Ciudadano romano! Enhorabuena: eso abre muchas puertas.':'Me dicen que la Asamblea votó un decreto en tu favor. No se ve todos los días.'):
    e.k==='casa'?'Ahora eres '+(f?'vecina':'vecino')+': ya sé que has comprado casa.':e.k==='bump'?'¿No serás tú '+quien+' va por ahí empujando a la gente? Ten más cuidado.':e.k==='cap'?'Se habla de ti: andas metido en asuntos importantes.':null;
    if(s&&n){heard.push(e.k+(e.r||''));state.seen['mm:'+n.id]=heard;}}
  return s;}
function memFirst(){if(state.seen['st:fama'])return;state.seen['st:fama']=1;toast('<span class="label">Fíjate · La fama</span><br>'+(MODE==='roma'?'En Roma todo se sabe: se habla en el foro, en las termas, en la barbería. Virgilio pinta a la Fama como un monstruo con tantos ojos, lenguas y orejas como plumas, que crece mientras corre (Eneida 4, 173-188). Lo que haces cambia cómo te tratan.':'En una ciudad griega todo se sabe: se habla en la fuente, en la barbería, en el ágora. Hesíodo avisa de que el rumor, la phḗmē, nunca muere del todo: «también ella es una diosa» (Trabajos y días 760-764). Lo que haces cambia cómo te tratan.'));}
function memGreet(n,first){if(!n||!state)return '';const F=memFama();let s='';
  if(!first&&F>=14&&Math.random()<0.5)s='<p class="sub">Te recibe con una sonrisa de verdad: «¡'+(pjz()||{}).name+'! Siempre es un gusto verte».</p>';
  else if(F<0&&Math.random()<0.6){s='<p class="sub">Te mira con desconfianza: «Ah… tú».</p>';setTimeout(()=>{try{const g=GS.dlgG;if(g&&g.userData.gs)gzExpr(g.userData.gs,'enfado',3);}catch(e){}},300);}
  if(Math.random()<0.45){const r=memSay(false,n);if(r){s+='<p class="sub">«'+r+'»</p>';memFirst();}}return s;}
// ---- familias y acompañantes: el niño con su madre o su pedagogo; el amo con un esclavo detrás
const FAM={t:0,n:0,argT:60,arg:null,lT:0,li:0};
const FAM_ARG={a:[['¡Esa higuera está en mi lado de la linde!','¡Mentira! La plantó mi abuelo.'],['¡Tu cabra se ha vuelto a comer mis coles!','¡Pues cierra tu huerto como es debido!'],['¡Me debes tres dracmas desde las Dionisias!','¡Te las pagué, y hay testigos!'],['¡Te veré ante los jueces!','¡Y yo a ti, sicofanta!']],
  r:[['¡El agua de tu tejado cae en mi patio!','¡Siempre ha caído ahí, y la ley me da la razón!'],['¡Tu gallo canta antes del alba!','¡Y tu perro ladra toda la noche!'],['¡Esas ramas tuyas me quitan la luz!','¡Pues pódalas tú, si te atreves!'],['¡In ius te voco! ¡Ante el pretor!','¡Vamos, vamos, que te conviene!']]};
Object.assign(ST_TXT,{
 pedagogo:MODE==='roma'?['El pedagogo','El niño no va solo al ludus del maestro: lo acompaña el paedagogus, a menudo un esclavo griego, que le lleva las tablillas, vigila sus modales y le enseña griego.']:['El pedagogo','El niño no va solo a la escuela: lo acompaña un esclavo de confianza, el paidagogós («el que conduce al niño»), que le lleva las tablillas y vigila sus modales. De ahí viene nuestra palabra pedagogo.'],
 acolito:MODE==='roma'?['El pedisecuo','Ningún romano acomodado sale solo: detrás va un esclavo, el pedisequus («el que sigue a pie»), con lo que haga falta. Cuantos más acompañantes, más importante pareces.']:['El acólito','El akólouthos («el que sigue») es el esclavo que acompaña a su amo por la calle y le lleva las cosas, como Jantias carga con el equipaje de Dioniso en las Ranas de Aristófanes.'],
 pleito:MODE==='roma'?['Pleitos entre vecinos','Las Doce Tablas, la ley más antigua de Roma, ya regulaban las peleas de vecinos: las ramas que dan sombra al campo ajeno, la fruta que cae al otro lado, el agua de lluvia. «In ius vocare» es citar a alguien ante el pretor.']:['Pleitos entre vecinos','Los atenienses tienen fama de pleiteadores. En las Nubes de Aristófanes, a un campesino le enseñan Atenas en un mapa y no se lo cree: «¡No veo jueces sentados!» (v. 207-208).'],
 fuente:MODE==='roma'?['La fuente del barrio','En Roma casi nadie tiene agua corriente en casa: se va a los lacus, las fuentes de los barrios que alimentan los acueductos. Frontino, que dirigirá las aguas de Roma en el 97, contará 591 (De aquaeductu 78).']:['La fuente','Ir a la fuente con la hidria es tarea de mujeres y esclavas, cada mañana y cada tarde. Es uno de los pocos sitios donde las atenienses se encuentran y charlan fuera de casa: los vasos pintados lo muestran a menudo.'],
 almuerzo:MODE==='roma'?['El prandium','A mediodía, un bocado rápido: pan, queso, fruta o las sobras de la víspera, muchas veces de pie, en la calle o en una popina. La comida importante es la cena, a partir de la hora nona.']:['El áriston','A mediodía se toma algo ligero, el áriston: pan o torta de cebada (maza), queso, aceitunas, higos. La comida fuerte es la cena, el deîpnon, al caer la tarde.'],
 calor:MODE==='roma'?['La siesta','En verano, después del prandium llega la meridiatio: la ciudad se para y quien puede busca la sombra de los pórticos. «La hora sexta es el descanso de los cansados», dice Marcial (Epigramas 4, 8).']:['El calor del mediodía','En verano, a mediodía, la ciudad va más despacio: quien puede busca la sombra de las stoas, los pórticos del ágora, hechos precisamente para eso. Ahí se charla y se filosofa: de la Stoa Pintada tomarán su nombre los estoicos.']});
function famLink(f,l,kind,off){f.fol=l;f.foff=off;f.wait=1e9;f.moving=false;l.lead=(l.lead||0)+1;f.fkind=kind;const P=player,far=Math.hypot(l.g.position.x-P.x,l.g.position.z-P.z)>45;
  if(far){const a=l.g.rotation.y;f.g.position.set(l.g.position.x+Math.cos(a)*off[0]+Math.sin(a)*off[1],0,l.g.position.z-Math.sin(a)*off[0]+Math.cos(a)*off[1]);f.g.position.y=terrainH(f.g.position.x,f.g.position.z);}
  stFeat(kind==='kid'?l.g:f.g,kind==='kid'?(l.g.userData.bt||'').match(/anciano/)||!/P_hair_m/.test([...bvParts(l.g)].join())?'madre':'pedagogo':'acolito');FAM.n++;}
function famForm(){const P=player,mv=walkers.filter(w=>!w.home&&w.g&&w.bv&&w.speed>0&&!w.fol&&!w.lead&&Math.hypot(w.g.position.x-P.x,w.g.position.z-P.z)<400);
  const kids=mv.filter(w=>/^niño$/.test(w.g.userData.bt||'')),adults=mv.filter(w=>!w.g.userData.bt||w.g.userData.bt==='grueso'||w.g.userData.bt==='flaco');
  for(const k of kids){if(FAM.n>=14)break;let b=null,bd=180;for(const a of adults){if(a.lead||a.fol)continue;const d=Math.hypot(a.g.position.x-k.g.position.x,a.g.position.z-k.g.position.z);if(d<bd){bd=d;b=a;}}if(b)famLink(k,b,'kid',[0.75,0.15]);}
  const slaves=mv.filter(w=>!w.lead&&!w.fol&&!w.g.userData.bt&&(()=>{const s=bvParts(w.g);return s.has('P_tunic_short')||s.has('P_basket')||s.has('P_amphora');})());
  const rich=mv.filter(w=>!w.lead&&!w.fol&&!/^niño/.test(w.g.userData.bt||'')&&(()=>{const s=bvParts(w.g);return !s.has('P_tunic_short')&&!s.has('P_hydria')&&!s.has('P_basket')&&!s.has('P_amphora')&&(MODE==='roma'?(s.has('P_toga')||s.has('P_hair_m')):s.has('P_himation_m'));})());
  for(const s of slaves){if(FAM.n>=22||!rich.length)break;const r=rich.find(r=>!r.lead&&Math.hypot(r.g.position.x-s.g.position.x,r.g.position.z-s.g.position.z)<200);if(r)famLink(s,r,'slave',[0.35,-1.4]);}}
function famTick(dt){if(!state||ui==='start')return;FAM.t-=dt;if(FAM.t<=0){FAM.t=4;try{famForm();}catch(e){}}const P=player;
  for(const w of walkers){const l=w.fol;if(!l)continue;const g=w.g;w.home=l.home;if(l.home){g.visible=false;continue;}if(!l.g.visible){g.visible=false;continue;}g.visible=true;
    const dx0=g.position.x-P.x,dz0=g.position.z-P.z;if(dx0*dx0+dz0*dz0>160*160)continue;
    const a=l.g.rotation.y,tx=l.g.position.x+Math.cos(a)*w.foff[0]+Math.sin(a)*w.foff[1],tz=l.g.position.z-Math.sin(a)*w.foff[0]+Math.cos(a)*w.foff[1],dx=tx-g.position.x,dz=tz-g.position.z,d=Math.hypot(dx,dz);
    if(d>25){g.position.x=tx;g.position.z=tz;g.position.y=terrainH(tx,tz);continue;}
    if(d>0.3){const sp=Math.max(l.speed*1.2,1.1)*(d>2?1.6:1),st=Math.min(d,sp*dt);if(!npcStep(g,dx/d,dz/d,st)){g.position.x+=dx/d*st;g.position.z+=dz/d*st;}g.position.y=terrainH(g.position.x,g.position.z);
      w.ph=(w.ph===undefined?w.phase:w.ph)+st*4.6*(w.sf||1);g.rotation.y+=wrapA(Math.atan2(dx,dz)-g.rotation.y)*Math.min(1,dt*6);personWalk(g,w.ph,1);w.fmv=1;}
    else{if(w.fmv){w.fmv=0;personWalk(g,0,0);}g.rotation.y+=wrapA(a-g.rotation.y)*Math.min(1,dt*3);}}
  // pleitos: de vez en cuando, una pareja de un corrillo cercano se pone a discutir
  FAM.argT-=dt;const A=FAM.arg;
  if(!A&&FAM.argT<=0){FAM.argT=20;for(const w of walkers){if(!w.pal||!w.spk||!w.g.visible)continue;const d=Math.hypot(w.g.position.x-P.x,w.g.position.z-P.z);if(d<20&&d>3){FAM.arg={a:w,b:w.pal,t:16,c:0,s:0,L:FAM_ARG[MODE==='roma'?'r':'a'][Math.floor(Math.random()*4)],li:0,lT:1};FAM.argT=150+Math.random()*120;break;}}}
  if(A){A.t-=dt;A.c-=dt;A.lT-=dt;const ok=A.a.pal===A.b&&A.a.g.visible;if(!ok||A.t<=0){for(const w of[A.a,A.b]){const gs=w.g.userData.gs;if(gs){gsRest(gs);gs.ct=1;}}FAM.arg=null;}
    else{for(const w of[A.a,A.b]){const gs=gsRig(w.g);gs.ct=2;}if(A.c<=0){A.c=1.1;A.s^=1;const sp=A.s?A.a:A.b,ls=A.s?A.b:A.a,g1=sp.g.userData.gs,g2=ls.g.userData.gs;gsSet(g1,['alto','senala','palmas'][Math.floor(Math.random()*3)],1.25);gzExpr(g1,'enfado',2);gsSet(g2,'pecho',0.9);gzExpr(g2,'enfado',2);}
      const d=Math.hypot(A.a.g.position.x-P.x,A.a.g.position.z-P.z);if(A.lT<=0&&A.li<2&&d<14){A.lT=5;toast('<i>«'+A.L[A.li]+'»</i>');A.li++;stFeat(A.a.g,'pleito');}}}}
