// ============================================================ ROMA: lo que faltaba según la Forma Urbis de Lanciani (revisión lámina a lámina, v217)
// Láminas 8, 9, 10, 14, 15, 16, 21, 22, 23, 28, 29, 30, 34, 35, 36, 42 frente al plano del juego. Se corrigieron en 029 la Saepta Julia
// (de norte a sur junto a la Vía Lata), las termas de Agripa (pegadas al sur del Panteón) y la Vía Recta con el puente de Nerón (al norte
// del Panteón). Aquí, lo que existía en el 80 d.C. y no estaba: termas de Nerón, teatro y cripta de Balbo, el área sagrada de Largo
// Argentina, el templo de Quirino, el pórtico de Livia, los jardines de Salustio, Lúculo y Mecenas, el Macellum Magnum y el circo vaticano.
// Lo posterior al 80 que sale en las láminas (estadio de Domiciano, termas de Trajano, Ludus Magnus, foro de Trajano) no se añade.
Object.assign(PSRC,{
 ro_saepta:{a:['Dion Casio LIII 23 (Agripa la termina, 26 a.C.) y LXVI 24 (arde en el 80)','Marcial II 14 y IX 59 (las tiendas de lujo de la Saepta)'],m:['R. Lanciani, Forma Urbis Romae (1893-1901), láms. 15 y 21',_t(4002,'F. Coarelli, Roma (2007)')],n:[]},
 ro_termas_neron:{a:['Marcial VII 34 («¿Qué hay peor que Nerón? ¿Y qué mejor que las termas de Nerón?»)','Suetonio, Nerón 12'],m:['Lanciani, lám. 15 (las rehace Alejandro Severo: thermae Alexandrianae)'],n:['La planta del juego es esquemática.']},
 ro_balbo:{a:['Suetonio, Augusto 29','Dion Casio LIV 25 y LXVI 24 (arde en el 80)'],m:['D. Manacorda, Crypta Balbi (2001)','Lanciani, lám. 21'],n:[]},
 ro_argentina:{a:['Cicerón, Sobre las leyes II 28 (Fortuna Huiusce Diei)','Plutarco, César 66 (la curia de Pompeyo)'],m:['F. Coarelli, L’Area Sacra di Largo Argentina (1981)'],n:['Se descubrió al derribar el barrio en 1926-1929; Lanciani aún no la conocía. La atribución de los templos A, C y D a dioses concretos es discutida.']},
 ro_quirino:{a:['Augusto, Res gestae 19','Dion Casio LIV 19','Vitruvio III 2, 7 (templo díptero)'],m:['Lanciani, lám. 16',_t(4001,'L. Richardson, A New Topographical Dictionary of Ancient Rome (1992)')],n:[]},
 ro_livia:{a:['Ovidio, Fastos VI 639-648','Dion Casio LIV 23 y LV 8','Plinio, Historia natural XIV 11 (la parra del pórtico)'],m:['Lanciani, lám. 23'],n:[]},
 ro_horti:{a:['Tácito, Anales XI 1 y 32-38 (Mesalina en los jardines de Lúculo)','Dion Casio LXVI 10 (Vespasiano en los de Salustio)','Suetonio, Nerón 38 (la torre de Mecenas)','Horacio, Sátiras I 8 (el cementerio del Esquilino convertido en jardín)'],m:['Lanciani, láms. 9, 10 y 23','M. Cima y E. La Rocca (eds.), Horti Romani (1998)'],n:[]},
 ro_macellum:{a:['Dion Casio LXI 18 (Nerón lo inaugura en el 59)'],m:['Richardson (1992), s.v. Macellum Magnum'],n:['Su ubicación exacta en el Celio se discute; el juego lo pone junto a la Puerta Celimontana.']},
 ro_vaticano:{a:['Plinio, Historia natural XVI 201 y XXXVI 74 (el obelisco)','Tácito, Anales XV 44 (los cristianos en los jardines de Nerón)','Suetonio, Claudio 21'],m:['Lanciani, láms. 7 y 14'],n:['El obelisco es el que hoy está en la plaza de San Pedro, trasladado en 1586.']}});
function romaLanciani(){const H=(x,z)=>romaH(x,z),ok=(x,z,r)=>isFree(x,z,r);
  // termas de Nerón, al oeste del Panteón
  {const x=-770,z=-545,g=grp(x,H(x,z)-0.2,z,0);box(70,14,44,PLAST,0,7,0,g);box(24,18,20,PLAST,0,9,0,g);const dm=new THREE.Mesh(new THREE.SphereGeometry(11,18,9,0,TAU,0,Math.PI/2),LEAD);dm.position.y=18;g.add(dm);
   for(const s of[-1,1]){const b=new THREE.Mesh(new THREE.PlaneGeometry(14,10),lam('#4f8a96'));b.rotation.x=-Math.PI/2;b.position.set(s*24,14.05,0);g.add(b);}
   addBox(x,z,70,44,0);footprints.push({x,z,w:70,d:44,a:0,c:'#e2d6c0',name:'Termas de Nerón'});
   place('ro_termas_neron','Termas de Nerón','THERMAE NERONIANAE','Las termas que Nerón hizo construir hacia el 62, junto a su gimnasio, al oeste del Panteón: salas calientes, piscinas al aire libre y jardines. Marcial bromea: «¿Hay algo peor que Nerón? ¿Y algo mejor que sus termas?». Siguen abiertas y son de las más concurridas del Campo de Marte.',x,z+26,0);}
  place('ro_saepta','La Saepta Julia','SAEPTA IVLIA','Un enorme recinto alargado, rodeado de pórticos, que Julio César empezó y Agripa terminó en el 26 a.C. para las votaciones de los comicios: aquí se encerraba por tribus a los ciudadanos que votaban. Con los emperadores ya casi no se vota y se usa para combates de gladiadores, exhibiciones y, sobre todo, tiendas de lujo: Marcial se burla de los que pasean entre esclavos de precio y muebles de carey sin comprar nada. El incendio de este año la ha dañado.',-472,-425,0);
  // teatro de Balbo y su cripta
  theatre({x:-505,z:-118,rot:-Math.PI/2,R0:12,R1:40,H:18,name:'Teatro de Balbo'});
  {const x=-430,z=-118;porticus(x-20,z-20,x+20,z-20,6,6,'tuscan',1,H(x,z));porticus(x-20,z+20,x+20,z+20,6,6,'tuscan',-1,H(x,z));footprints.push({x,z,w:44,d:44,a:0,c:'#d8ccb4',name:'Cripta de Balbo'});}
  place('ro_balbo','Teatro de Balbo','THEATRVM BALBI','El más pequeño de los tres teatros de piedra de Roma, inaugurado en el 13 a.C. por Lucio Cornelio Balbo, un gaditano que llegó a cónsul: Augusto animaba a los ricos a embellecer la ciudad. Detrás tiene un patio con pórticos, la «cripta». También ardió en el incendio de este año.',-470,-160,0);
  // área sagrada de Largo Argentina: cuatro templos republicanos en fila, ante la curia de Pompeyo
  {const zs=[-262,-238,-212,-190];zs.forEach((z,i)=>{if(i===1)roundTemple({x:-535,z,r:6,colD:0.6,colH:7,n:18,pod:2,rot:Math.PI/2,name:'Templo de la Fortuna de Este Día'});
     else romanTemple({x:-535,z,rot:Math.PI/2,W:10,L:16,pod:2.2,colD:0.7,colH:7,nW:4,deep:1,name:['Templo A','','Templo C','Templo D'][i]});});
   footprints.push({x:-535,z:-226,w:20,d:90,a:0,c:'#d8ccb4',name:'Área sagrada'});
   place('ro_argentina','Cuatro templos antiguos','AREA SACRA','En fila, cuatro templos de los tiempos de la República, mucho más antiguos que los pórticos de Pompeyo que tienen detrás. El redondo lo prometió Quinto Lutacio Cátulo a la Fortuna de Este Día en la batalla contra los cimbrios (101 a.C.). Justo detrás está la sala de reuniones de Pompeyo donde mataron a César en los idus de marzo del 44 a.C.; Augusto la mandó cerrar.',-510,-226,0);}
  // templo de Quirino, en el Quirinal
  {const x=-215,z=-650;romanTemple({x,z,rot:0,W:30,L:54,pod:3,colD:1.2,colH:12,nW:8,deep:3,peri:true,name:'Templo de Quirino'});
   place('ro_quirino','Templo de Quirino','AEDES QVIRINI','Quirino es Rómulo convertido en dios. Augusto le reconstruyó en el 16 a.C. este templo enorme, rodeado por dos filas de columnas (un «díptero», dice Vitruvio): setenta y seis columnas en total. La colina, el Quirinal, toma de él su nombre.',x+24,z+30,0);}
  // pórtico de Livia, en el Opio, junto al Clivo Suburano
  {const x=330,z=-290,gy=H(x,z);porticus(x-45,z-30,x+45,z-30,7,7,'corinthian',1,gy);porticus(x-45,z+30,x+45,z+30,7,7,'corinthian',-1,gy);porticus(x-45,z-30,x-45,z+30,7,7,'corinthian',-1,gy);porticus(x+45,z-30,x+45,z+30,7,7,'corinthian',1,gy);
   {const g=grp(x,gy,z,0);box(8,4,6,M.marble,0,2,0,g);addBox(x,z,8,6,0);}
   footprints.push({x,z,w:96,d:66,a:0,c:'#d8ccb4',reserve:true});
   place('ro_livia','Pórtico de Livia','PORTICVS LIVIAE','Un gran patio con pórticos y jardines en el Opio. Aquí estaba la casa de Vedio Polión, un liberto riquísimo y cruel que echaba a sus esclavos a las morenas; al heredarla, Augusto la mandó derribar entera y Livia levantó en su lugar este pórtico abierto a todos (7 a.C.), con un santuario de la Concordia. Una sola parra da sombra a los paseos y doce ánforas de vino al año, cuenta Plinio.',x,z+36,0);}
  // jardines: Salustio, Lúculo, Mecenas (árboles, un pabellón y su estela)
  const garden=(x,z,id,nm,gr,txt,pav)=>{const tr=[];for(let i=0;i<46;i++){const a=i*2.39996,r=8+Math.sqrt(i)*9,px=x+Math.cos(a)*r,pz=z+Math.sin(a)*r;if(ok(px,pz,2))tr.push({x:px,z:pz,kind:['pine','cypress','plane','pine'][i%4],k:1});}if(GLB.ok&&tr.length)treesGLB(tr);
    if(pav){const g=grp(x+pav[0],H(x+pav[0],z+pav[1]),z+pav[1],pav[2]||0);box(pav[3],7,pav[4],PLAST,0,3.5,0,g);const ap=new THREE.Mesh(new THREE.CylinderGeometry(pav[4]/2,pav[4]/2,7,16,1,false,0,Math.PI),PLAST);ap.position.set(pav[3]/2,3.5,0);g.add(ap);addBox(g.position.x,g.position.z,pav[3],pav[4],pav[2]||0);footprints.push({x:g.position.x,z:g.position.z,w:pav[3],d:pav[4],a:pav[2]||0,name:nm,house:true});}
    footprints.push({x,z,r:55,c:'#c8d0a8',reserve:true});place(id,nm,gr,txt,x,z+6,0);};
  garden(-110,-860,'ro_salustio',_t(4072,'Jardines de Salustio'),'HORTI SALLVSTIANI','Los jardines que el historiador Salustio se pagó con lo que ganó gobernando África. Hoy son del emperador: Vespasiano pasaba aquí más tiempo que en el Palatino y recibía a quien quisiera verlo. Hay pabellones, estatuas, fuentes y un obelisco.',[16,-14,0.3,22,10]);
  garden(-330,-975,'ro_luculo',_t(4074,'Jardines de Lúculo'),'HORTI LVCVLLIANI','En la colina de los jardines, el Pincio, Lúculo, el general rico de los banquetes famosos, construyó unos jardines en terrazas. Mesalina, la mujer del emperador Claudio, los codició, hizo matar a su dueño y fue aquí donde la mataron a ella en el 48, cuando Claudio descubrió que se había casado con su amante (Tácito, Anales XI).',null);
  garden(700,-290,'ro_mecenas',_t(4062,'Jardines de Mecenas'),'HORTI MAECENATIS','Mecenas, el amigo de Augusto y protector de Virgilio y Horacio, convirtió el viejo cementerio de los pobres del Esquilino en unos jardines: Horacio se ríe de las brujas que antes rondaban las tumbas. Tienen una sala semicircular para lecturas y una torre: desde ella, dicen, contempló Nerón el incendio del 64 cantando la caída de Troya.',[-14,10,0,20,12]);
  // Macellum Magnum de Nerón, en el Celio
  {const x=520,z=330,gy=H(x,z),g=grp(x,gy,z,0);for(const[a,b,c,d]of[[-20,-20,20,-20],[20,-20,20,20],[20,20,-20,20],[-20,20,-20,-6],[-20,6,-20,-20]]){const L=Math.hypot(c-a,d-b),w=box(L>0?(Math.abs(c-a)>0?L:1):1,5,Math.abs(d-b)>0?L:1,PLAST,(a+c)/2,2.5,(b+d)/2,g);}
   const th=new THREE.Mesh(new THREE.CylinderGeometry(7,7,8,20),PLAST);th.position.y=4;g.add(th);const rf=new THREE.Mesh(new THREE.ConeGeometry(8,4,20),M.tile||PLAST);rf.position.y=10;g.add(rf);addCirc(x,z,7.2);
   for(const[a,b,c,d]of[[-20,-20,20,-20],[20,-20,20,20],[20,20,-20,20],[-20,20,-20,6],[-20,-6,-20,-20]])addSeg(x+a,z+b,x+c,z+d,0.5);
   footprints.push({x,z,w:42,d:42,a:0,c:'#d8ccb4',name:'Macellum Magnum',house:true});
   place('ro_macellum','El gran mercado de Nerón','MACELLVM MAGNVM','Nerón inauguró en el 59 este mercado de lujo en el Celio: un patio rodeado de tiendas de dos pisos con un pabellón redondo en el centro, de cúpula, donde se vendía el pescado y la carne más caros. Salió en sus monedas.',x-26,z,0);}
  // el circo vaticano de Gayo y Nerón, al otro lado del río
  {const x=-1260,z=-720,gy=H(x,z),g=grp(x,gy,z,0);for(const s of[-1,1])box(220,5,8,PLAST,0,2.5,s*24,g);box(160,1.2,3,M.marble||PLAST,0,0.6,0,g);addBox(x,z,160,3,0);for(const s of[-1,1])addSeg(x-110,z+s*24,x+110,z+s*24,4);
   if(GLB.ok&&GLB.parts.B_obelisk)placeModules('B_obelisk',[{x,y:gy+1.2,z,a:0,sx:0.9}],{far:2400});
   footprints.push({x,z,w:224,d:56,a:0,c:'#d8ccb0',name:'Circo de Gayo y Nerón'});
   place('ro_vaticano','El circo del Vaticano','CIRCVS GAI ET NERONIS','Al otro lado del río, en la llanura del Vaticano, Calígula se construyó un circo privado en los jardines de su madre Agripina, y trajo de Egipto, en un barco gigantesco, el obelisco de la espina. Nerón corría aquí con sus caballos. En el 64, tras el incendio, en estos jardines hizo matar a los cristianos, cuenta Tácito; la tradición dirá que Pedro murió aquí.',x+40,z+34,0);}}
// la roca Tarpeya: el acantilado de toba del Capitolio (antes solo había la estela, un bloque blanco). Peñascos de toba con textura de roca,
// en la cara que baja (se busca con la pendiente del terreno), y colisión. Toba volcánica, «cappellaccio», como el resto de la colina
function romaTarpeya(){const P=PLACES.find(q=>q.id==='ro_tarpeya');const x0=P?P.x:-205,z0=P?P.z:66,H=(x,z)=>terrainH(x,z);
  let gx=H(x0+4,z0)-H(x0-4,z0),gz=H(x0,z0+4)-H(x0,z0-4);const gl=Math.hypot(gx,gz)||1;gx/=gl;gz/=gl;   // hacia abajo: -gradiente
  const dx=-gx,dz=-gz,px=-dz,pz=dx,mat=triplanar(new THREE.MeshLambertMaterial({color:'#b9a98c'}),PTEX.rock,2.2),r=mulberry32(4242);
  for(let i=0;i<14;i++){const s=(i-6.5)/6.5,along=s*18+(r()-0.5)*3,out=-(4+r()*22),x=x0+px*along+dx*out,z=z0+pz*along+dz*out,sc=3+r()*4;   // peñascos que asoman de la ladera, cuesta arriba
    const geo=new THREE.IcosahedronGeometry(1,1),pa=geo.attributes.position,sd=r()*100;   // la deformación depende del punto, no del vértice: los triángulos (que no comparten vértices) siguen unidos
    for(let k=0;k<pa.count;k++){const vx=pa.getX(k),vy=pa.getY(k),vz=pa.getZ(k),hh=Math.sin(Math.round(vx*50)*12.9898+Math.round(vy*50)*78.233+Math.round(vz*50)*37.719+sd)*43758.5453,f=0.78+(hh-Math.floor(hh))*0.4;pa.setXYZ(k,vx*f,vy*f*1.25,vz*f);}geo.computeVertexNormals();
    const m=new THREE.Mesh(geo,mat);m.scale.set(sc,sc*1.3,sc*0.9);m.rotation.set(r()*0.4,r()*6,r()*0.4);m.position.set(x,H(x,z)+sc*0.15,z);m.castShadow=true;m.receiveShadow=true;scene.add(m);addCirc(x,z,sc*0.8);}}
// ============================================================ CRETA (3): el este de la isla (modo Atenas, 386 a.C.)
// Malia (palacio, graneros, la piedra de las cazoletas, las abejas de oro de Crisólaco), la meseta del Lasithi (la cueva Dictea donde nació
// Zeus y Karfi, el pueblo refugio del final de la Edad del Bronce), Dreros y Lato (las primeras leyes escritas), Gurnia (un pueblo minoico
// entero), Praiso (los eteocretenses, que aún hablan una lengua que no es griego) y Zacro con el valle de los Muertos.
Object.assign(CRX_TX,{
 kernos:['Una piedra con hoyuelos','en el patio del palacio','Una piedra redonda con un círculo de treinta y tantas cazoletas y una mayor en el centro. ¿Para ofrendas de semillas? ¿Para un juego? Nadie lo recuerda.','Es el «kernos» de Malia (hacia 1700 a.C.), con 34 cazoletas. Unos creen que servía para ofrecer las primicias de la cosecha; otros, que era un tablero de juego. No hay acuerdo.','F. Chapouthier, BCH 52 (1928)','🪨'],
 graneros:['Ocho fosas redondas','en la esquina del palacio','Ocho silos redondos de piedra, en dos filas. En uno todavía hay tierra negra, como de grano podrido.','Probablemente eran graneros para guardar los cereales que entraban en el palacio: un indicio de que los palacios almacenaban y redistribuían la cosecha de la llanura.','O. Pelon, en Ergon (1979)','🌾'],
 abejas:['El cementerio de oro','junto al mar','La gente llama a este recinto de tumbas «el pozo de oro»: dicen que los saqueadores sacaron de aquí joyas, hace mucho.','En Crisólaco («pozo de oro»), un gran recinto funerario de Malia, se encontró en 1930 un colgante de oro de hacia el 1800 a.C.: dos abejas o avispas que sostienen una gota de miel, una de las joyas más famosas de la Creta minoica (Museo de Heraclión).','P. Demargne, Fouilles exécutées à Mallia (1945)','🐝'],
 cripta:['Una sala con pilares','con signos grabados','Una sala oscura con dos pilares cuadrados. En las piedras hay signos tallados: una estrella, un hacha doble.','Las «criptas de pilares» eran probablemente salas de culto; los signos grabados en los sillares (marcas de cantero o símbolos sagrados, como el hacha doble) aparecen en muchos palacios.','N. Marinatos, Minoan Religion (1993)','🏛'],
 dictea:['La cueva Dictea','donde nació Zeus','Bajas por la boca de la cueva. Abajo, a la luz de la antorcha, las estalactitas brillan; en las grietas hay hachas dobles de bronce clavadas, figurillas, agujas, anillos: siglos de ofrendas.','La cueva de Psicro, en el Lasithi, suele identificarse con la Dictea. Hogarth la excavó en 1900 y encontró cientos de exvotos de bronce, entre ellos hachas dobles metidas en las grietas de las estalactitas. Se usó desde la época minoica hasta la griega arcaica. Otros prefieren situar el nacimiento de Zeus en la cueva del Ida.','Hesíodo, Teogonía 477-484; D. G. Hogarth, BSA 6 (1899-1900)','🕳'],
 karfi:['Un pueblo en lo alto','sobre la meseta','Casas pequeñas de piedra apiñadas entre las rocas de la cumbre, a más de mil metros. Hace muchísimo frío y sopla el viento. ¿Quién viviría aquí arriba?','Karfi fue un pueblo refugio de hacia 1200-1000 a.C.: tras el hundimiento de los palacios micénicos, mucha gente subió a vivir a sitios altos y fáciles de defender. J. Pendlebury lo excavó en 1937-1939 y encontró grandes figuras de diosas de barro con los brazos levantados.','J. D. S. Pendlebury, BSA 38 (1937-1938); L. Day, en Karphi Revisited (2006)','⛰'],
 ley_dreros:['La ley grabada en el templo','la más antigua que se conoce','En la pared del templo de Apolo Delfinio, una piedra con letras antiguas: «Así lo ha decidido la ciudad: cuando uno haya sido cosmos, el mismo no lo será de nuevo hasta pasados diez años…».','Es la ley griega escrita más antigua que conservamos, de hacia el 650-600 a.C.: limita la repetición en el cargo de cosmos, el magistrado principal, para que nadie se eternice en el poder; si alguien la incumple, todo lo que haga como cosmos será nulo.','R. Meiggs y D. Lewis, Greek Historical Inscriptions (1969), n.º 2','📜'],
 bronces:['Tres estatuillas de bronce','en el templo','Junto al hogar del templo, tres figuras de bronce martilleado sobre un alma de madera: un hombre joven y dos mujeres. Dicen que son Apolo, su madre Leto y su hermana Ártemis.','Las estatuas de Dreros (hacia el 700 a.C.) son de las más antiguas de Grecia hechas con planchas de bronce martilleadas (sphyrelata). Se encontraron en 1935 y están en el museo de Heraclión.','S. Marinatos, BCH 60 (1936)','🗿'],
 herramientas:['Herramientas de bronce','en un rincón','En una casa enterrada del pueblo viejo asoman herramientas: sierras, cinceles, un hacha. Un campesino dice que su abuelo encontró aquí pesas de telar.','En Gurnia se encontraron talleres de carpintero, de herrero, de alfarero y de tejedora, con sus herramientas de bronce y pesas de telar: es la mejor imagen que tenemos de la vida diaria de un pueblo minoico hacia el 1500 a.C.','H. Boyd Hawes, Gournia, Vasiliki and Other Prehistoric Sites (1908)','🔨'],
 diosa_gurnia:['Un pequeño santuario','en lo alto del pueblo','Una salita con un banco y, encima, una figura de barro de una mujer con los brazos levantados, con serpientes enroscadas.','El santuario de Gurnia (hacia 1300 a.C., ya en época micénica) tenía figuras de diosas con los brazos levantados y tubos de barro con serpientes. Es el mismo tipo de diosa que luego aparece en Karfi.','Boyd Hawes (1908)','🐍'],
 eteocretense:['Una inscripción que nadie entiende','en letras griegas','Las letras son griegas: puedes leerlas en voz alta. Pero las palabras no significan nada en griego. Un hombre del pueblo sonríe: «Es nuestra lengua, la de antes».','En Praiso y en Dreros se han encontrado inscripciones en eteocretense, una lengua no griega escrita con el alfabeto griego entre los siglos VII y III a.C. Podría descender de la lengua de los minoicos (la del lineal A), pero nadie ha podido traducirla.','Y. Duhoux, L’Étéocrétois (1982)','🔤'],
 cisterna_zacro:['Una sala con un estanque redondo','con escalones','Dentro del palacio enterrado hay una sala con un estanque redondo al que se baja por unos escalones; todavía le llega agua de un manantial.','En Zacro, la «sala de la cisterna» tenía un estanque circular de unos 7 m alimentado por una fuente. Para qué servía (¿un baño ritual? ¿un estanque de peces? ¿un acuario?) se discute.','N. Platon, Zakros: The Discovery of a Lost Palace of Ancient Crete (1971)','💧'],
 colmillos:['Lingotes y colmillos','en un almacén','En un rincón, cubiertos de tierra quemada, unos lingotes de cobre con forma de piel de buey y unos colmillos enormes de elefante.','En el palacio de Zacro, que nunca fue saqueado, N. Platon encontró en 1962 lingotes de cobre de Chipre y colmillos de elefante de Siria: Zacro era el puerto de Creta hacia Oriente. Allí aparecieron también vasos de piedra preciosísimos, como un ritón de cristal de roca.','Platon (1971)','🐘'],
 tumbas_valle:['Cuevas en la pared','del barranco','En las paredes del barranco hay muchas cuevas pequeñas. En algunas se ven huesos y vasijas rotas.','Por eso se llama el «valle de los Muertos»: en sus cuevas enterraron a sus muertos los habitantes de la zona desde el tercer milenio a.C., mucho antes del palacio.','Platon (1971)','💀']});
const CRE_SRC={
 malia:{a:['Homero, Ilíada II 647 (Mileto de Creta)','Estrabón XIV 1, 6 (Sarpedón funda Mileto de Asia)'],m:['J.-C. Poursat, Les Minoens (2008)','O. Pelon, Le palais de Malia (1980-1992)'],n:['El palacio lo excavó la Escuela Francesa de Atenas desde 1921; el juego muestra las ruinas como visibles.']},
 lasithi:{a:['Hesíodo, Teogonía 477-484','Aristóteles, Política II 10, 1271b (Licto, colonia de Esparta)','Calímaco, Himno a Zeus 4-14 (siglo III a.C.)'],m:['Hogarth (1900)','Pendlebury (1938)'],n:['Si la cueva de Psicro es la Dictea de los antiguos se discute.']},
 dreros:{a:['Ley de Dreros (ML 2)','Aristóteles, Política II 10'],m:['M. Gagarin, Writing Greek Law (2008)','Willetts (1955)'],n:['Lato fue muy importante desde el siglo IV; casi todo lo que hoy se ve en ella es de época helenística.']},
 gurnia:{a:[],m:['Boyd Hawes (1908)','L. V. Watrous et al., The Gournia Project (2010-)'],n:['Harriet Boyd fue una de las primeras mujeres en dirigir una gran excavación en el Egeo (1901-1904).']},
 praiso:{a:['Homero, Odisea XIX 175-177','Estrabón X 4, 6 y 12'],m:['Duhoux (1982)','J. Whitley, «Praisos», BSA 93 (1998)'],n:['El «Himno de los Curetes» de Palecastro está grabado en una piedra de época romana, aunque el texto es más antiguo.']},
 zacro:{a:[],m:['Platon (1971)','L. Platon (ed.), Zakros (2015)'],n:['El palacio se descubrió en 1962; en el 386 era un montón de tierra.']}};
// los cretenses de las ruinas, sin olivos dentro del yacimiento (ver mnSite)
// ================================================================ MALIA
crDest({id:'malia',pos:[25.49,35.29],links:[['amniso','malia']],label:'Malia',
 isl:{name:'Malia',gr:'ΜΑΛΙΑ',sub:'Las ruinas de un palacio junto al mar, entre la llanura y la montaña.',R:440,H:22,seed:66.4,days:'un día de camino hacia el este de Amniso',fare:1,dir:[1,0],coast:[0,-1],coastAt:0.36},
 cfg:{blobs:[[60,330,260,100],[-260,260,170,60]],houses:6,spread:40,tx:-150,tz:40,tr:40,pads:[[20,40,54]]},
 steles:[['malia_palacio','El palacio de Malia','ΜΑΛΙΑ','Entre la llanura y el mar están las ruinas de un palacio tan grande como el de Festo: un patio enlosado, almacenes, salas con pilares. Los pastores lo llaman «la ciudad de Sarpedón», el hermano de Minos. Usa «Imaginarlo» para verlo hacia el 1700 a.C.',CRE_SRC.malia],
  ['malia_abejas','Las abejas de oro','ΜΕΛΙΣΣΑΙ','Junto al mar hay un gran recinto de tumbas al que llaman el pozo de oro. Allí se encontrará en 1930 un colgante de oro: dos abejas que sostienen una gota de miel. Los minoicos eran grandes apicultores, y la miel era tan valiosa que se ofrecía a los dioses.',CRE_SRC.malia],
  ['malia_sarpedon','Sarpedón y Mileto','ΣΑΡΠΗΔΩΝ','Cuentan que Sarpedón, hermano de Minos, perdió la lucha por el trono y se marchó de Creta con los suyos desde una ciudad de esta costa llamada Mileto. En Asia fundó otra Mileto, la gran ciudad de Jonia. Homero cita la Mileto cretense entre las ciudades que mandaron naves a Troya.',{a:['Estrabón XIV 1, 6 (citando a Éforo)','Homero, Ilíada II 647','Heródoto I 173'],m:[],n:['Es una tradición legendaria.']}],
  ['malia_escritura','Signos sobre el barro','ΓΡΑΜΜΑΤΑ','En las ruinas a veces aparecen sellos de piedra con dibujitos y trozos de barro con signos. Hoy sabemos que en Creta hubo tres escrituras: los jeroglíficos cretenses (muy usados en Malia), el lineal A de los palacios, que nadie sabe leer, y el lineal B, que es griego y trajeron los micénicos.',{a:[],m:['J.-P. Olivier y L. Godart, Corpus Hieroglyphicarum Inscriptionum Cretae (1996)','J. Chadwick, The Decipherment of Linear B (1958)'],n:['En el 386 nadie sabía leer estas escrituras.']}]],
 npc:{id:'licon_malia',name:'Licón',title:'Cabrero de Malia',glyph:'Λ',look:{chiton:'#8a7a5a',short:true,noHimation:true,hair:'#3a2a1e',beard:true,staff:true},
  cat:_t(123,'Historia'),lesson:'Las escrituras de Creta',where:'En Malia, junto al palacio en ruinas',
  summary:'En la Creta de la Edad del Bronce hubo tres escrituras: los jeroglíficos cretenses (hacia 1900-1600 a.C.), el lineal A de los palacios minoicos (hacia 1800-1450), que todavía no se ha descifrado porque escribe una lengua desconocida, y el lineal B (hacia 1450-1200), que M. Ventris descifró en 1952 y resultó ser griego: la lengua de los micénicos que gobernaron Cnosos. Las tablillas son sobre todo inventarios: ovejas, lana, aceite, armas, ofrendas a los dioses.',
  intro:'¿Has visto mis cabras? Siempre se meten entre las piedras del palacio viejo. Soy Licón. Mira lo que encontré ayer entre las raíces de un olivo: un trozo de barro con rayitas.',
  topics:[['¿Qué son esas rayitas?','Mi abuelo decía que es la escritura de los de antes. No son nuestras letras: son dibujitos, palitos, una mano, un hacha doble. Los he llevado al sacerdote y tampoco sabe leerlos. Seguramente dice cuántas cabras tenía alguien, como yo cuando hago muescas en un palo.'],
   ['¿Quién vivía en el palacio?','Dicen que Sarpedón, el hermano de Minos. Yo solo sé que era gente rica: aquí se encuentran trozos de vasos finos como hojas, y una vez mi primo sacó una cuenta de oro.'],
   ['¿Y las fosas redondas?','Graneros, seguro. Mira qué grandes: ahí cabía el trigo de toda la llanura. El que guarda el trigo, manda.'],
   ['¿Hay abejas por aquí?','Muchísimas: el tomillo de estos montes da la mejor miel de Creta. Ahí, junto al mar, en el cementerio viejo, dicen que se encontró una vez una abeja de oro.']],
  quiz:{q:'¿Cuál de las escrituras de la Creta de la Edad del Bronce es griego?',a:['El lineal B','El lineal A','Los jeroglíficos cretenses'],ko:'No. Solo el lineal B escribe griego (lo descifró Ventris en 1952); el lineal A y los jeroglíficos cretenses escriben una lengua que no conocemos.'}},
 src:{a:[],m:['Chadwick (1958)','J. Driessen, «Linear B and Linear A», en Cline (ed.), The Oxford Handbook of the Bronze Age Aegean (2010)'],n:['Licón es un personaje inventado.']},
 trav:['Un apicultor de Malia','con sus colmenas de barro',{chiton:'#8a7a5a',short:true,noHimation:true},'«Las colmenas las hago de barro, como tubos tumbados. Con humo se apartan las abejas y se saca el panal.»'],
 fauna:[['goat',4,-180,120,70],['hare',2,160,180,60]],
 vida:{kinds:['olive','olive','cypress','pine'],fauna:[['dog',2],['hen',4],['goat',3]],barks:['El palacio viejo está lleno de cabras.','La miel de este año es de tomillo.','Allá arriba, en la meseta, hace frío hasta en verano.']},
 build(I){
  mnSite(I,'malia_pal',{x:20,z:40,a:0.1,name:'El palacio de Malia',when:'1700 a.C.',txt:'El palacio de Malia hacia el 1700 a.C.: un patio de 48 × 22 m con pórticos, una sala de pilares al norte, almacenes al este y al oeste, una cripta de pilares y, en la esquina, ocho graneros redondos.',
   courts:[[0,0,22,48]],cols:[[11,-14],[11,-6],[11,2],[11,10],[-4,-29],[4,-29],[-19,-4],[-19,4]],
   walls:[[-13,-25,13,-25],[13,-25,13,25],[13,25,4,25],[-4,25,-13,25],[-13,25,-13,8],[-13,0,-13,-25],[-13,-25,-13,-34],[-13,-34,13,-34],[13,-34,13,-25],
    [-24,-25,-13,-25],[-24,-25,-24,25],[-24,25,-13,25],[-24,-8,-13,-8],[-24,8,-13,8],[-24,14,-13,14],[-24,20,-13,20],
    [13,-25,24,-25],[24,-25,24,25],[24,25,13,25],[13,-15,24,-15],[13,-9,24,-9],[13,-3,24,-3],[13,3,24,3],[13,9,24,9]],
   rooms:[[-18.5,0,11,50,2],[18.5,0,11,50,1],[0,-29.5,26,9,2]],horns:[[-18.5,-24,7.2],[0,-34,7.2]],fresco:[[0,-24.6,0,'espirales']],
   people:[[0,0,'hombre',0],[-4,6,'mujer',0.5],[4,8,'mujer2',-0.6],[-8,-12,'hombre2',1.2],[2,-20,'sacerdotisa',Math.PI]],
   extra(ru,re){mnKernos(ru,-10,22);mnKernos(re,-10,22);for(let i=0;i<8;i++){const x=-34+(i%4)*5.2,z=28+Math.floor(i/4)*5.2;const r=new THREE.Mesh(new THREE.CylinderGeometry(2.2,2.3,0.9,16,1,true),MNM.stone);r.material=MNM.stone;r.position.set(x,0.45,z);ru.add(r);
     const c=new THREE.Mesh(new THREE.CylinderGeometry(2.2,2.3,3.4,16),MNM.plaster);c.position.set(x,1.7,z);re.add(c);const d=new THREE.Mesh(new THREE.SphereGeometry(2.2,14,8,0,TAU,0,Math.PI/2),MNM.plaster);d.position.set(x,3.4,z);re.add(d);}
     for(let k=0;k<6;k++){mnPithos(ru,20,-20+k*4,0.7);mnPithos(re,20,-20+k*4,0.85);}},
   see:[-30,44],olives:12,span:80,fw:72,fd:76});
  {const S=CRX.sites.malia_pal;if(S){let p=S.W(-10,22);crObj(p[0],p[1],'kernos',2.5);p=S.W(-31,31);crObj(p[0],p[1],'graneros',5);p=S.W(-19,0);crObj(p[0],p[1],'cripta',3);}}
  {const sh=shoreAlong(I.x+120,I.z,0,-1,I.R*1.5),g=grp(sh[0],terrainH(sh[0],sh[1]+18),sh[1]+18,0);for(const[x1,z1,x2,z2]of[[-19,-15,19,-15],[19,-15,19,15],[19,15,-19,15],[-19,15,-19,-15],[-6,-15,-6,15],[6,-15,6,15]]){const L=Math.hypot(x2-x1,z2-z1),b=box(Math.abs(x2-x1)||0.8,0.8,Math.abs(z2-z1)||0.8,MNM.stone,(x1+x2)/2,0.4,(z1+z2)/2,g);}
   addBox(g.position.x,g.position.z,38,30,0);crObj(g.position.x,g.position.z+18,'abejas',4);}
  crPerson(I.x+60,I.z+90,'campesina',0.3);}});
// ================================================================ LA MESETA DEL LASITHI
crDest({id:'lasithi',pos:[25.47,35.18],links:[['malia','lasithi']],label:'El Lasithi',
 isl:{name:'La meseta del Lasithi',gr:'ΔΙΚΤΗ',sub:'Una llanura alta rodeada de montañas: la cueva donde nació Zeus y un pueblo refugio en las cumbres.',R:460,H:30,seed:67.8,days:'un día de subida desde Malia',fare:1,dir:[0,1]},
 cfg:{blobs:[[0,-360,180,99],[300,-200,170,90],[340,150,170,90],[120,380,180,95],[-250,330,170,90],[-370,40,170,90],[-260,-280,170,90]],houses:5,spread:40,tx:60,tz:40,tr:50,pads:[[-30,-300,26]],green:true},
 steles:[['dicte_cueva','La cueva de Zeus','ΔΙΚΤΑΙΟΝ ΑΝΤΡΟΝ','Crono se comía a sus hijos al nacer, para que ninguno lo destronara. Rea, cuando iba a nacer Zeus, se escondió en Creta y lo dio a luz en una cueva; a Crono le dio una piedra envuelta en pañales. El niño creció escondido, alimentado con la leche de la cabra Amaltea y con miel, mientras los curetes bailaban golpeando sus escudos para que no se oyera su llanto. Aquí dicen que fue en esta cueva; los del Ida dicen que en la suya.',CRE_SRC.lasithi],
  ['karfi','El pueblo de las nubes','ΚΑΡΦΙ','En la cumbre del norte, a más de mil metros, hay ruinas de un pueblo de casas apiñadas. Lo construyeron, hace unos ochocientos años, gentes que huían de algo: piratas, guerras, el hundimiento de los reinos de antes. Desde allí arriba se ve el mar y se ve venir a cualquiera.',CRE_SRC.lasithi],
  ['lasithi_meseta','La llanura entre montañas','ΟΡΟΠΕΔΙΟΝ','Una llanura redonda y fértil a ochocientos metros de altura, rodeada de montañas. En invierno se inunda y se nieva; en verano se cultiva trigo y se pastorea. Los pastores de toda la zona suben aquí sus rebaños.',{a:[],m:['L. V. Watrous, Lasithi: A History of Settlement on a Highland Plain in Crete (1982)'],n:[]}],
  ['licto','Licto, la ciudad de los espartanos','ΛΥΚΤΟΣ','Al oeste de la meseta está Licto, una de las ciudades más poderosas de Creta. Hesíodo dice que Rea dio a luz a Zeus cerca de Licto. Sus habitantes dicen ser colonos de Esparta, y Aristóteles comparará sus leyes con las espartanas.',{a:['Hesíodo, Teogonía 477-484','Aristóteles, Política II 10, 1271b'],m:[],n:[]}]],
 trav:['Un pastor de la meseta','con un cordero al hombro',{chiton:'#7a6a50',short:true,noHimation:true},'«En la cueva se oyen a veces los escudos de los curetes. Eso dice mi abuela. Yo solo oigo el agua que gotea.»'],
 fauna:[['goat',6,-200,-120,90],['sheep',6,80,100,80],['hare',2,160,-60,60]],
 vida:{kinds:['olive','cypress','olive','pine'],fauna:[['dog',2],['sheep',4],['goat',3]],barks:['En invierno la llanura se convierte en un lago.','Arriba, en Karfi, no vive nadie desde hace siglos.','Si vas a la cueva, lleva antorcha.']},
 build(I){crCave(I,-210,150,0.6,'dictea');
  {const g=crPut(I,-196,140,0,2);if(g){for(let k=0;k<6;k++)mnLabrys(g,(k%3)*0.9-0.9,0,Math.floor(k/3)*0.9,0.55);}}
  mnSite(I,'karfi',{x:-30,z:-300,a:0.3,name:'Karfi',when:'1100 a.C.',H:2.6,txt:'Un pueblo refugio de hacia el 1100 a.C. en la cumbre: casas pequeñas de piedra, de una o dos habitaciones, pegadas unas a otras, y un santuario con diosas de barro con los brazos levantados.',
   walls:(()=>{const W=[];const rnd=forRng(0.7731);for(let i=0;i<9;i++){const cx=-16+(i%3)*12+(rnd()-0.5)*3,cz=-12+Math.floor(i/3)*11+(rnd()-0.5)*3,w=6+rnd()*3,d=5+rnd()*2;W.push([cx-w/2,cz-d/2,cx+w/2,cz-d/2],[cx+w/2,cz-d/2,cx+w/2,cz+d/2],[cx+w/2,cz+d/2,cx+0.8,cz+d/2],[cx-0.8,cz+d/2,cx-w/2,cz+d/2],[cx-w/2,cz+d/2,cx-w/2,cz-d/2]);}return W;})(),
   people:[[0,0,'campesino',0],[6,4,'campesina',1],[-8,6,'campesina',2]],
   extra(ru,re){for(let k=0;k<3;k++){const f=new THREE.Mesh(new THREE.CylinderGeometry(0.18,0.32,0.9,10),MNM.clay);f.position.set(10+k*0.8,0.45,-12);re.add(f);for(const s of[-1,1]){const a=new THREE.Mesh(new THREE.CylinderGeometry(0.04,0.04,0.4,5),MNM.clay);a.position.set(10+k*0.8+s*0.18,1,-12);a.rotation.z=-s*0.3;re.add(a);}}},
   see:[0,24],fw:44,fd:40});
  {const S=CRX.sites.karfi;if(S){const p=S.W(10,-12);crObj(p[0],p[1],'karfi',4);}}
  for(let k=0;k<5;k++){const x=I.x-60+k*40,z=I.z+60+(k%2)*20;try{box(30,0.2,18,lam(k%2?'#c9b07a':'#8a9a4a'),x,terrainH(x,z)+0.1,z);}catch(e){}}}});
// ================================================================ DREROS Y LATO
crDest({id:'dreros',pos:[25.63,35.24],links:[['malia','dreros']],label:'Dreros',
 isl:{name:'Dreros y Lato',gr:'ΔΡΗΡΟΣ',sub:'Ciudades dorias de montaña: aquí se grabó la ley griega más antigua que conocemos.',R:440,H:30,seed:68.2,days:'un día de camino hacia el este de Malia',fare:1,dir:[1,0]},
 cfg:{blobs:[[-40,-60,150,60],[110,-90,120,55],[-300,230,150,70]],houses:18,spread:60,tx:30,tz:60,tr:45,pads:[[20,-40,24],[-300,230,30]]},
 steles:[['dreros_ley','La ley más antigua','ΝΟΜΟΣ','En la pared del templo de Apolo Delfinio está grabada una ley de hace más de doscientos años: nadie puede volver a ser cosmos, el magistrado principal, hasta que pasen diez años. Si lo hace, deberá pagar el doble de las multas que imponga y quedará privado de sus derechos, y todo lo que haya hecho como cosmos no valdrá nada. Es la primera vez, que sepamos, que una ciudad griega escribe una ley para limitar el poder de los que mandan.',CRE_SRC.dreros],
  ['dreros_agora','El ágora con gradas','ΑΓΟΡΑ','Entre las dos cumbres de la ciudad está el ágora, con unas gradas de piedra a un lado donde se sientan los ciudadanos para las asambleas. Al lado, el templo de Apolo, pequeño, con su hogar en medio y un banco para las ofrendas.',CRE_SRC.dreros],
  ['lato','Lato','ΛΑΤΩ','Al otro lado del valle, en una ladera empinada, está Lato, la ciudad de Leto, la madre de Apolo y Ártemis. Sus casas suben en terrazas hasta el ágora, entre dos cumbres. Su puerto, Camara, está en la bahía, abajo.',CRE_SRC.dreros],
  ['dreros_juramento','El juramento de los jóvenes','ΟΡΚΟΣ','Cuando los muchachos de Dreros terminan su formación juran ante los dioses ser leales a la ciudad y enemigos para siempre de los de Lito. Las ciudades cretenses se pelean continuamente entre sí por tierras y pastos.',{a:['Juramento de los efebos de Dreros (IC I 9, 1; siglo III a.C.)'],m:['Chaniotis (1996)'],n:['La inscripción conservada es helenística; las rivalidades eran antiguas.']}]],
 npc:{id:'teodoro_dreros',name:_t(9231,'Teodoro'),title:'Antiguo cosmos de Dreros',glyph:'Θ',look:{chiton:'#d8cbb0',himation:'#4a5a6a',beard:true,hair:'#8d8a85',staff:true},
  cat:_t(15,'Política'),lesson:'Las primeras leyes escritas',where:'En Dreros, junto al templo de Apolo',
  summary:'Las primeras leyes griegas escritas aparecen en el siglo VII a.C., y algunas de las más antiguas son cretenses: la ley de Dreros (hacia 650-600 a.C.) prohíbe repetir en el cargo de cosmos antes de diez años. Poner las leyes por escrito y a la vista de todos limitaba el poder de los magistrados y de las familias poderosas, que antes las aplicaban de memoria a su manera. En Atenas, Dracón (hacia 621) y Solón (594) hicieron lo mismo.',
  intro:'Saludos. Soy Teodoro. Fui cosmos hace doce años, y no me han dejado volver a serlo hasta ahora: ¡así lo manda la ley de la pared! Y me parece bien, aunque te lo diga con la boca pequeña.',
  topics:[['¿Por qué esa ley?','Porque el poder gusta, forastero. El que ha mandado una vez quiere mandar siempre, y sus amigos con él. Nuestros antepasados lo escribieron en piedra para que ni el más rico pudiera saltárselo: diez años entre un mandato y otro.'],
   ['¿Qué hace un cosmos?','Manda en la guerra, juzga muchos pleitos, recibe a los embajadores. Somos varios, elegidos cada año entre unas pocas familias. Al terminar, si lo has hecho bien, entras en el consejo de ancianos.'],
   ['¿Y la gente común?','Votamos en la asamblea lo que nos proponen los cosmos y el consejo. Los siervos que trabajan la tierra, no. Así es en toda Creta.'],
   ['¿Y las estatuas de bronce del templo?','Son muy antiguas: Apolo, Leto y Ártemis, hechas con planchas de bronce martilleadas sobre madera. Antes de que se supiera fundir estatuas grandes, se hacían así.']],
  quiz:{q:'¿Qué prohibía la ley de Dreros?',a:['Volver a ser cosmos antes de diez años','Llevar armas en el ágora','Que las mujeres heredaran tierras'],ko:'No. La ley de Dreros (hacia 650-600 a.C.) prohibía repetir en el cargo de cosmos hasta pasados diez años.'}},
 src:{a:['Ley de Dreros (ML 2)'],m:['Gagarin (2008)'],n:['Teodoro es un personaje inventado.']},
 trav:['Un muchacho de Dreros','que vuelve de cazar',{chiton:'#7a6a50',short:true,noHimation:true},'«Los chicos vivimos juntos en la agela, la manada: cazamos, corremos, aprendemos a pelear. Los mayores dicen que así se hacen los hombres.»'],
 fauna:[['goat',4,-160,-140,70],['hare',2,140,120,60]],
 vida:{kinds:['olive','cypress','pine','olive'],fauna:[['dog',2],['hen',4],['goat',3]],barks:['Los de Lito nos quieren quitar los pastos de la sierra.','La asamblea se reúne en las gradas del ágora.','Desde la cumbre se ve toda la bahía.']},
 build(I){const p0=I.pads&&I.pads.find(p=>Math.abs(p.x-(I.x+20))<1&&Math.abs(p.z-(I.z-40))<1);
  {const g=crPut(I,20,-40,0,4);if(g){box(11,0.5,7.5,MNM.ashlar,0,0.25,0,g);for(const[a,b,c,d]of[[-5.5,-3.75,5.5,-3.75],[5.5,-3.75,5.5,3.75],[-5.5,-3.75,-5.5,3.75],[-5.5,3.75,-1.2,3.75],[1.2,3.75,5.5,3.75]]){const L=Math.hypot(c-a,d-b);box(Math.abs(c-a)||0.6,4,Math.abs(d-b)||0.6,MNM.stone,(a+c)/2,2.2,(b+d)/2,g);addSeg(g.position.x+a,g.position.z+b,g.position.x+c,g.position.z+d,0.35);}
    const h=new THREE.Mesh(new THREE.CylinderGeometry(0.8,0.8,0.3,12),MNM.dark);h.position.set(0,0.65,0);g.add(h);box(4,0.8,0.9,MNM.ashlar,0,0.9,-3,g);
    for(const[x,s]of[[-0.9,1],[0,0.8],[0.9,0.8]]){const st=makePerson({chiton:'#a07c44',himation:'#8a6a3a',skin:'#a07c44',hair:'#7d6a3e',female:x!==-0.9,noVary:true});st.scale.setScalar(s*0.5);st.position.set(x,1.3,-3);g.add(st);}
    crObj(g.position.x+4,g.position.z+5,'ley_dreros',3);crObj(g.position.x-3,g.position.z+5,'bronces',3);
    for(let i=0;i<6;i++)box(22,0.45,1.1,MNM.ashlar,0,0.22+i*0.45,14+i*1.1,g);addPlat(g.position.x,g.position.z+16.75,22,6.6,0,g.position.y+1.4);}}
  {const B=I.blobs[2],x=B.x,z=B.z;for(let i=0;i<6;i++){const zz=z+30-i*9,yy=terrainH(x,zz);box(40,3,1.4,MNM.stone,x,yy-0.5,zz);}place('lato_agora','El ágora de Lato','ΑΓΟΡΑ ΛΑΤΟΥΣ','En Lato el ágora es una plaza pequeña entre dos cumbres, con un altar, una escalinata que sube al pritaneo y casas en terrazas a los lados.',x+24,z,0);}}});
// ================================================================ GURNIA
crDest({id:'gurnia',pos:[25.79,35.11],links:[['dreros','gurnia']],label:'Gurnia',
 isl:{name:'Gurnia',gr:'ΓΟΥΡΝΙΑ',sub:'Un pueblo minoico entero bajo la tierra, junto a la bahía de Mirabello.',R:420,H:20,seed:69.6,days:'un día de camino por la costa',fare:1,dir:[1,0],coast:[0,-1],coastAt:0.33},
 cfg:{blobs:[[0,20,120,26],[-260,220,170,60],[260,240,170,60]],houses:4,spread:30,tx:-170,tz:60,tr:35,pads:[[0,20,52]]},
 steles:[['gurnia_pueblo','El pueblo enterrado','ΚΩΜΗ','Esta colina baja junto al mar esconde un pueblo entero de hace más de mil años: calles empedradas, casas de dos pisos, talleres, una casa grande con su plaza. Lo desenterrará entre 1901 y 1904 una joven arqueóloga estadounidense, Harriet Boyd, con cientos de obreros del lugar. Usa «Imaginarlo» para verlo hacia el 1500 a.C.',CRE_SRC.gurnia],
  ['gurnia_vida','La vida en un pueblo minoico','ΒΙΟΣ','En sus casas aparecerán sierras, cinceles y hachas de bronce, pesas de telar, prensas de aceite, morteros, cerámica de todos los días. No era un palacio: era el pueblo de campesinos, pescadores y artesanos que mantenían a los palacios.',CRE_SRC.gurnia],
  ['gurnia_bahia','La bahía de Mirabello','ΚΟΛΠΟΣ','Delante, la bahía más bonita de Creta, con islotes: en Pseira y en Moclos hubo también pueblos minoicos de pescadores y comerciantes. Los barcos salían de aquí hacia las Cícladas.',{a:[],m:['P. Betancourt, Pseira (1995-)','J. Soles, Mochlos (2003-)'],n:[]}],
  ['gurnia_fin','El final','ΤΕΛΟΣ','Hacia el 1450 a.C. el pueblo ardió, como casi todos los de Creta menos Cnosos. Nadie sabe bien por qué: ¿guerras entre cretenses, la llegada de los micénicos, terremotos? Más tarde volvió a vivir aquí un poco de gente, con un pequeño santuario.',CRE_SRC.gurnia]],
 trav:['Un pescador de la bahía','con sus nasas',{chiton:'#6a5a48',short:true,noHimation:true},'«En la colina, cuando ara mi vecino, salen piedras de muros y trozos de cacharros. Dicen que ahí vivía gente antes que nosotros.»'],
 fauna:[['goat',3,-200,160,60]],
 vida:{kinds:['olive','olive','cypress','pine'],fauna:[['dog',2],['hen',4],['goat',2]],barks:['Hoy hay mucho pulpo en la bahía.','En la colina de enfrente salen piedras viejas al arar.','A Hierapitna se va por el istmo, en medio día.']},
 build(I){const W=[],ppl=[],R=[];   // un pueblo en cuadrícula irregular: manzanas de casas entre calles empedradas, la «casa grande» arriba con su plaza
  for(let bi=0;bi<4;bi++)for(let bj=0;bj<3;bj++){const x0=-40+bi*20,z0=-6+bj*17;if(bi===1&&bj===0)continue;for(let h=0;h<2;h++){const x=x0+h*8.7,w=8.2,d=14.2;W.push([x,z0,x+w,z0],[x+w,z0,x+w,z0+d],[x+w,z0+d,x+5,z0+d],[x+3,z0+d,x,z0+d],[x,z0+d,x,z0]);W.push([x,z0+7,x+w,z0+7]);R.push([x+w/2,z0+d/2,w,d,(bi+bj+h)%3?2:1]);ppl.push([x+4,z0+d+1.2,['hombre','mujer','hombre2','mujer2'][(bi+bj+h)%4],Math.PI*((bi+h)%2),null]);}}
  W.push([-20,-24,4,-24],[4,-24,4,-8],[4,-8,-8,-8],[-12,-8,-20,-8],[-20,-8,-20,-24],[-20,-16,4,-16]);   // la casa grande
  mnSite(I,'gurnia_pueblo',{x:0,z:20,a:-0.2,name:'Gurnia',when:'1500 a.C.',H:3.2,txt:'Un pueblo minoico hacia el 1500 a.C.: manzanas de casas de dos pisos entre callejas empedradas, talleres en las plantas bajas, una casa grande arriba y, delante, una plaza pública.',
   walls:W,courts:[[-8,-34,22,14]],rooms:R.concat([[-8,-16,24,16,2]]),people:ppl.slice(0,12),see:[-8,-44],olives:10,span:90,fw:96,fd:76,
   extra(ru,re){for(let k=0;k<4;k++){const w=new THREE.Mesh(new THREE.CylinderGeometry(0.06,0.06,0.1,6),MNM.clay);w.position.set(-30+k*0.2,0.05,2);ru.add(w);}box(1.6,0.9,1,MNM.wood,-31,0.45,4,re);}});
  {const S=CRX.sites.gurnia_pueblo;if(S){let p=S.W(-30,4);crObj(p[0],p[1],'herramientas',3);p=S.W(-16,-12);crObj(p[0],p[1],'diosa_gurnia',3);}}
  for(const[dz,r]of[[-180,22],[-60,16]]){const x=I.x+I.R*0.3+dz*0.2,z=I.z-I.R*1.25,m=new THREE.Mesh(new THREE.SphereGeometry(r,12,8,0,TAU,0,Math.PI/2),lam('#9a8f70'));m.scale.y=0.7;m.position.set(x+dz,-1,z);scene.add(m);}}});
