  for(const[dx,dz,a]of[[-150,-38,0.2],[-200,40,-2.9],[-110,36,3],[-240,-34,0.1],[-180,-36,0],[-260,38,-3]]){const x=I.x+dx,z=I.z+dz,g=grp(x,terrainH(x,z),z,a);box(1.4,1.6,0.6,MNM.dark,0,0.8,0,g);box(2.2,0.5,0.9,MNM.stone,0,1.8,0,g);}
