  const L=d.querySelector('.ilinks');L.innerHTML='';const lk=(t,id)=>{const b=document.createElement('button');b.textContent=t;b.onclick=()=>{const o=$(id);if(o)o.click();if(id!=='bBack')introEnd();};L.appendChild(b);};
  lk(_t(2961,'Volver'),'');L.lastChild.onclick=()=>{d.classList.remove('step2');introStep1();};
  if($('loadStart'))lk(_t(2785,'Cargar partida'),'loadStart');if($('libStart'))lk(_t(10619,'Leer la biblioteca'),'libStart');lk(_t(10610,'Cambiar de época'),'bBack');
