// ---------------------------------------------------------------- estado y desbloqueo
const AM={F:null,o:null};
function amz(){if(!state.diosa||typeof state.diosa!=='object')state.diosa={};const k=MODE==='roma'?'R':'A';if(!state.diosa[k])state.diosa[k]={met:0,base:0,seen:{}};return state.diosa[k];}
function amList(){return AM_TOPICS[MODE==='roma'?'roma':'atenas'];}
function amSeen(id){const z=amz(),first=!z.seen[id];z.seen[id]=1;save();if(first){qAdd('so',1,_t(10989,'Aprendiste con ')+amName());toast('<span class="label">'+amName()+_t(10990,' te ha enseñado</span><br>')+((amList().find(t=>t.id===id)||{}).t||'')+' · '+amLeft()+_t(10991,' por escuchar'));}
  setTimeout(()=>{if(ui==='play'&&!EPI.cur&&AM.o&&Math.hypot(player.x-AM.o.x,player.z-AM.o.z)<12)amTalk();},900);}
function amName(){return MODE==='roma'?_t(4558,'Minerva'):_t(5546,'Atenea');}
function amProg(){let n=(state.lessons||[]).length;if(state.seen)for(const k in state.seen)if(k.startsWith('ep:')&&!k.startsWith('ep:am_'))n++;return n;}
// cupo: 2 la primera vez + 2 por cada nivel de Sophía ganado desde entonces + 1 por cada 6 pasos de avance (lecciones y sueños)
function amCap(){const z=amz();return 2+2*Math.max(0,qLv('so')-z.base)+Math.floor(amProg()/6);}
function amUsed(){return Object.keys(amz().seen).length;}
function amLeft(){return Math.max(0,amCap()-amUsed());}
// ¿por qué está cerrado? null = abierto. need: id previo · número = cuántos del mismo ámbito hay que haber visto antes
function amLock(T){const z=amz(),L=amList();if(typeof T.need==='string'&&!z.seen[T.need]){const p=L.find(x=>x.id===T.need);return _t(10992,'Antes: «')+(p?p.t:T.need)+'»';}
  if(typeof T.need==='number'){const n=L.filter(x=>x.a===T.a&&z.seen[x.id]).length;if(n<T.need)return _t(10993,'Se abre cuando hayas escuchado ')+T.need+_t(10994,' de este ámbito (')+n+'/'+T.need+')';}return null;}
const AM_AMB={h:[_t(123,'Historia'),'⏳',_t(10995,'Del pasado lejano a lo que aún no ha pasado.')],m:['Mitología','✶',_t(10996,'Cinco mitos en los que tomé parte.')],s:[_t(143,'Sociedad'),'⚖',_t(10997,'Cómo vivís: cinco claves.')]};
// ---------------------------------------------------------------- diálogo
function amTalk(){const z=amz(),ro=MODE==='roma',nm=amName(),qn=ro?'Sapientia':'Sophía';let intro;
  if(!z.met){z.met=1;z.base=qLv('so');save();
    intro=ro?_t(10998,'<p>Te veo mirar hacia la cella, ennegrecida por el incendio de este año. No te asustes: soy Minerva, la de la mente. Juno y Júpiter duermen; yo prefiero a quien pregunta.</p><p>Puedo abrirte la memoria del mundo: la <b>historia</b> de Roma, mis <b>mitos</b> y cómo vive tu <b>sociedad</b>. Hoy podrás escuchar dos lecciones. Cuando tu ')+qn+_t(10999,' crezca un nivel, te enseñaré dos más.</p>')
     :_t(11000,'<p>Contemplas mi estatua: oro y marfil de Fidias, doce metros. Pero yo no estoy en el oro. Soy Atenea, y me gusta quien mira con atención.</p><p>Puedo abrirte la memoria del mundo: la <b>historia</b> de los griegos, mis <b>mitos</b> y cómo vive tu <b>sociedad</b>. Hoy podrás escuchar dos lecciones. Cuando tu ')+qn+_t(10999,' crezca un nivel, te enseñaré dos más.</p>');
    if(AM.F&&AM.F.mk)AM.F.mk.visible=false;}
  else intro='<p>'+(ro?_t(11001,'Vuelves a mi cella. ¿Qué quieres saber?'):_t(11002,'Vuelves al Partenón. ¿Qué quieres saber?'))+'</p>';
  const left=amLeft();intro+=_t(11003,'<p class="sub">Lecciones nuevas que puedes escuchar ahora: <b>')+left+'</b>'+(left?'':_t(11004,' · Sube un nivel de ')+qn+_t(11005,' (o sigue aprendiendo por el mundo) para escuchar más.'))+_t(11006,' Las ya escuchadas puedes repetirlas siempre.</p>');
  vmS(ro?'M':'Α',nm,ro?_t(4559,'diosa de la sabiduría y de los oficios'):_t(11007,'Παλλὰς Ἀθηνᾶ · diosa de la sabiduría'),intro,[
   ...['h','m','s'].map(a=>{const L=amList().filter(t=>t.a===a),n=L.filter(t=>z.seen[t.id]).length;return[AM_AMB[a][1]+' '+AM_AMB[a][0]+' <span class="sub">'+n+'/'+L.length+'</span>',()=>amAmb(a)];}),
   [_t(2951,'Despedirse'),()=>closeDialog()]]);}
function amAmb(a){const z=amz(),ro=MODE==='roma',A=AM_AMB[a],left=amLeft();
  const L=amList().filter(t=>t.a===a);let html='<p>'+A[2]+'</p><p class="sub">'+(left?_t(11008,'Puedes escuchar ')+left+_t(10627,' lección')+(left>1?'es':'')+' nueva'+(left>1?'s':'')+'.':_t(11009,'No te quedan lecciones nuevas por ahora: sube tu ')+(ro?'Sapientia':'Sophía')+'.')+'</p>';
  const btns=L.map(T=>{const seen=z.seen[T.id],lock=amLock(T);
    if(seen)return['✓ '+T.t+_t(11010,' <span class="sub">repetir</span>'),()=>amPlay(T)];
    if(lock)return['🔒 '+T.t+' <span class="sub">'+lock+'</span>',()=>{toast(lock);},'dis'];
    if(!left)return['◌ '+T.t+_t(11011,' <span class="sub">necesitas más ')+(ro?'Sapientia':'Sophía')+'</span>',()=>toast(_t(11012,'Sube un nivel de ')+(ro?'Sapientia':'Sophía')+_t(11013,' para escuchar dos lecciones más.')),'dis'];
    return['✦ '+T.t+' <span class="sub">'+T.ph.length+_t(11014,' fases</span>'),()=>amPlay(T)];});
  vmS(ro?'M':'Α',amName(),A[0],html,[...btns,[_t(2961,'Volver'),()=>amTalk()]]);}
function amPlay(T){if(EPI.cur||ui==='voyage'||ui==='episode')return;closeDialog();epiStart(amEpisode(T,amName()));}
// ---------------------------------------------------------------- colocación: Atenea ante la Parthenos; Minerva en su cella del templo capitolino
function amSpot(){if(MODE==='roma'){const fp=(footprints||[]).find(f=>f.name===_t(4761,'Templo de Júpiter Óptimo Máximo'));const cx=fp?fp.x:-228,cz=fp?fp.z:22;return{x:cx+4.2,z:cz+7.2,face:[cx+4.2,cz+60]};}   // ante la puerta de la cella, junto a la imagen de culto (la cella del juego es única: la de Júpiter en el centro)
  const fp=(footprints||[]).find(f=>f.name===_t(12,'Partenón'));if(!fp)return null;const p=toW(3.5,6,fp.x,fp.z,fp.a),d=toW(0,24,fp.x,fp.z,fp.a);return{x:p[0],z:p[1],face:d};}
function amSetup(){AM.F=null;AM.o=null;const ro=MODE==='roma';const s=amSpot();if(!s)return;const y=floorAt(s.x,s.z);
  const look=ro?{female:true,chiton:'#efe6d4',himation:'#8a2a3a',hair:'#5a3a22',helmet:'attic',attrs:['G_aegis','P_spear','P_spearhead','P_shield']}
    :{female:true,chiton:'#efe6d4',himation:'#c9a24a',hair:'#5a3a22',helmet:'attic',attrs:['G_aegis','P_spear','P_spearhead','P_shield']};
  const F=divineFigure(s.x,s.z,look,'#ffe8b0',amName(),ro?_t(11015,'diosa de la sabiduría'):_t(11015,'diosa de la sabiduría'),1.2);F.g.position.y=y;F.g.rotation.y=Math.atan2(s.face[0]-s.x,s.face[1]-s.z);F.lb.visible=false;F.lb.userData.never=1;
  if(amz().met)F.mk.visible=false;AM.F=F;
  AM.o=egxObj(s.x,s.z,y,'am:talk',amName(),_t(11016,'pulsa E para hablar'),3.2);}
{const f=egxAct0;egxAct0=function(o){if(String(o.act).startsWith('am:'))return amTalk();return f(o);};}
// la diosa respira y mira al jugador cuando se acerca
{const f=uxTick;uxTick=function(dt){f(dt);const F=AM.F;if(!F||ui!=='play')return;const dx=player.x-F.g.position.x,dz=player.z-F.g.position.z,d=Math.hypot(dx,dz);if(d>30)return;
  const t=performance.now()/1000;F.g.position.y=floorAt(F.g.position.x,F.g.position.z)+0.06+Math.sin(t*1.3)*0.05;if(d<10){const want=Math.atan2(dx,dz);let a=want-F.g.rotation.y;a=Math.atan2(Math.sin(a),Math.cos(a));F.g.rotation.y+=a*Math.min(1,dt*2);}};}
{const st=document.createElement('style');st.textContent='#dOpts button.dis{opacity:.55}#dOpts button .sub{opacity:.75;font-size:.85em;margin-left:.4em}';document.head.appendChild(st);}
// ============================================================ HÉCATE EN LOS UMBRALES (Atenas) y TRIVIA / LOS DIOSES DE LA PUERTA (Roma)
// Comprobado con fuentes antiguas: Hesíodo, Teogonía 411-452 (el culto ya existe hacia el 700 a.C.); Aristófanes, Avispas 804 (hecateos «delante de las puertas», 422 a.C.)
// y Pluto 594-597 (cenas de Hécate); Pausanias II 30, 2 (la Hécate Epipyrgidía de Alcámenes, la primera de tres cuerpos, junto al templo de la Victoria sin alas).
// Roma: Hécate es Trivia, «la de los tres caminos», identificada con Diana triforme (Virgilio, Eneida IV 511; Horacio, Odas III 22); la puerta de la casa la guardan
// Jano, Forculo (las hojas), Cardea (los goznes) y Limentino (el umbral) (Agustín, Ciudad de Dios IV 8 y VI 7; Tertuliano, Sobre la idolatría 15).
function hecSetup(){if(MODE==='roma')return;const fp=(footprints||[]).find(f=>f.name===_t(2271,'Templo de Atenea Nike'));if(!fp)return;
  let p=null;for(const[lx,lz]of[[6,-3],[-6,-3],[6,3],[-6,3],[0,-7]]){const q=toW(lx,lz,fp.x,fp.z,fp.a||0);if(isFree(q[0],q[1],0.9)){p=q;break;}}if(!p)return;
  const[x,z]=p,y=floorAt(x,z),g=grp(x,y,z,R()*TAU),m=lam('#ece4d6');box(1.1,0.5,1.1,lam('#d8ccb4'),0,0.25,0,g);
  const pil=new THREE.Mesh(new THREE.CylinderGeometry(0.28,0.3,2.3,10),m);pil.position.y=1.65;g.add(pil);
  for(let k=0;k<3;k++){const a=k/3*TAU,f=makePerson({noVary:true,female:true,chiton:'#ece4d6',himation:'#ece4d6',hair:'#ece4d6',skin:'#ece4d6',attrs:[_t(4546,'G_diadem')]});f.scale.setScalar(0.95);f.position.set(Math.sin(a)*0.33,0.5,Math.cos(a)*0.33);f.rotation.y=a;f.userData.statue=1;g.add(f);
    const t=new THREE.Sprite(new THREE.SpriteMaterial({map:TORCH_TEX,blending:THREE.AdditiveBlending,depthWrite:false,transparent:true,opacity:0.8}));t.scale.set(0.4,0.6,1);t.position.set(Math.sin(a+0.5)*0.6,2.2,Math.cos(a+0.5)*0.6);g.add(t);}
  addCirc(x,z,0.8);egxObj(x,z,y,'hec:epi',_t(11017,'Hécate Epipyrgidía'),_t(11018,'la de tres cuerpos, de Alcámenes'),3);}
function hecAct(o){const s=spz(),d=state.day||1;
  if(o.act==='hec:epi'){vmS('☾',_t(11017,'Hécate Epipyrgidía'),_t(11019,'«la de junto a la torre», de Alcámenes'),_t(11020,'<p>Junto al bastión del templo de la Victoria, a la entrada de la Acrópolis, tres doncellas de mármol unidas de espaldas, con antorchas: es <b>Hécate</b>, que mira a la vez a todos los caminos. Pausanias dice que Alcámenes, el discípulo de Fidias, fue el primero en hacer a Hécate con tres cuerpos, hacia el 430-420 a.C., y que los atenienses la llaman <i>Epipyrgidía</i>, «la de junto a la torre».</p><p>Desde entonces se copian por todas partes, en los cruces y ante las puertas. Es diosa de los umbrales: de las puertas, de los cruces, del paso entre el día y la noche y entre los vivos y los muertos. Hesíodo ya la honraba como una gran diosa hacia el 700 a.C.</p><p class="sub">Fuentes: Pausanias II 30, 2; Hesíodo, Teogonía 411-452. Esta imagen del juego es una reconstrucción: la original no se conserva.</p>'),[vmBye]);return;}
  if(o.act==='hec:door'){const done=s.hecD===d;vmS('☾',_t(11021,'Ante la puerta'),_t(11022,'una ofrenda a Hécate Propylaía'),done?_t(11023,'<p>Ya has dejado hoy tu ofrenda ante el hecateo.</p>'):_t(11024,'<p>Dejas ante la imagen una tortita de miel y una ramita de mirto, y dices en voz baja: «Hécate, guarda esta puerta». Así lo hacía cualquier ateniense al salir o al volver de un viaje.</p><p class="sub">Aristófanes, Avispas 804; Teofrasto, Caracteres 16 (el supersticioso que no deja de honrar a Hécate). +1 Eusébeia</p>'),[vmBye]);if(!done){s.hecD=d;qAdd('eu',1);save();}return;}}
{const f=egxAct0;egxAct0=function(o){if(String(o.act).startsWith('hec:'))return hecAct(o);return f(o);};}
// en el hecateo de la puerta, además de leer, se puede dejar una ofrenda
{const f=ambAct;ambAct=function(o){f(o);if(o.act==='amb:hekataion'){const b=document.createElement('button');b.innerHTML='<span class="n">'+($('dOpts').children.length+1)+_t(11025,'</span><span>Dejar una ofrenda ante la puerta</span>');b.onclick=()=>hecAct({act:'hec:door'});$('dOpts').insertBefore(b,$('dOpts').firstChild);}};}
// Roma: en el compitum, ¿y Hécate?
{const f=spAct;spAct=function(o){f(o);if(o.act==='sp:compitum'){const b=document.createElement('button');b.innerHTML='<span class="n">'+($('dOpts').children.length+1)+_t(11026,'</span><span>¿Y Hécate? ¿Quién guarda las puertas?</span>');
  b.onclick=()=>vmS('☾',_t(11027,'Trivia'),_t(11028,'Hécate en Roma'),_t(11029,'<p>Aquí a Hécate la llamamos <b>Trivia</b>, «la de los tres caminos», y muchos la confunden con Diana: Virgilio habla de «Hécate de tres formas, los tres rostros de la virgen Diana». Hay estatuas suyas de tres cuerpos, sobre todo en casas de gente rica que imita lo griego. Pero los cruces de Roma son de los <b>Lares</b>, como este altar.</p><p>Y la puerta de casa no la guarda Hécate: la guardan nuestros propios dioses. <b>Jano</b> es el dios de las puertas y de los comienzos; <b>Forculo</b> cuida las hojas de la puerta, <b>Cardea</b> los goznes y <b>Limentino</b> el umbral. Por eso al entrar una novia en casa la levantan en brazos: que no tropiece en el umbral.</p><p class="sub">Fuentes: Virgilio, Eneida IV 511; Horacio, Odas III 22; Agustín, La ciudad de Dios IV 8 y VI 7; Plutarco, Cuestiones romanas 29.</p>'),[vmBye]);
  $('dOpts').insertBefore(b,$('dOpts').lastChild);}};}
// ============================================================ DIEZ MEJORAS DE JUEGO
// 1 rastro de tus viajes en el plano y % explorado · 2 cartas entre ciudades (los personajes se acuerdan) · 3 retos de clase e informe para el docente
// 4 calendario cívico: Asamblea en la Pnyx / Senado en calendas e idus · 5 comercio con riesgo de piratas y tormentas · 6 te tratan según vistes
// 7 sonido amortiguado dentro de los edificios · 8 móvil: vibración y botones grandes · 9 ficha de la foto con lugar y fuente · 10 modo ligero automático
function dzz(){if(!state.dz||typeof state.dz!=='object')state.dz={tr:{},carta:null,cartas:0,ev:{}};const z=state.dz;z.tr=z.tr||{};z.ev=z.ev||{};return z;}
