  const show=()=>{if(ui!=='play'){setTimeout(show,1500);return;}vmS(MODE==='roma'?'✦':'✦',_t(11333,'La honra'),R[1],R[3]+'<p class="sub">Fuente: '+R[4]+' · +'+gift+' '+(MODE==='roma'?'sestercios':_t(2851,'óbolos'))+_t(11334,', +2 Kléos</p>')+(r<honList().length-1?_t(11335,'<p class="sub">Siguiente honor: <b>')+honList()[r+1][1]+'</b> ('+sc+'/'+honList()[r+1][0]+_t(11336,' de honra). Míralo en el diario › La honra.</p>'):_t(11337,'<p class="sub">Has alcanzado el honor más alto.</p>')),[vmBye]);};
