function fiYear(){return MODE==='roma'?80:-386;}
function fiY(y){return y<0?(-y)+' a.C.':y+' d.C.';}
function fiWhen(A){const Y=fiYear(),s=A[2],e=A[3];if(e<Y-20)return{k:'antes',t:_t(11507,'anterior: escribió ')+(Y-e>0?'unos '+Math.round((Y-e)/10)*10+_t(11508,' años antes'):'antes')};
  if(s>Y+5)return{k:'despues',t:_t(11509,'posterior: escribió unos ')+Math.round((s-Y)/10)*10+_t(11510,' años después')};return{k:'epoca',t:_t(11511,'de la época del juego')};}
let FI=null,FI_BUSY=false;
function fiBuild(){if(FI&&FI.mode===MODE)return FI;FI_BUSY=true;const by=new Map();
  const ids=[];try{for(const sc of libSections())for(const it of sc.items)if(!it.id.startsWith('f:'))ids.push(it.id);}catch(e){}
  const scan=(txt,where)=>{if(!txt)return;for(let i=0;i<FI_AUTH.length;i++){const A=FI_AUTH[i];if(!A[1].test(txt))continue;let o=by.get(i);if(!o){o={items:new Set(),works:new Map(),other:0};by.set(i,o);}
      if(where)o.items.add(where);else o.other++;
      const re=new RegExp(A[0].replace(/ /g,'\\s')+',\\s*([A-ZÁÉÍÓÚ][^0-9;().,«»]{2,60}?)\\s*(?=[IVXL]+\\b|\\d)','g');let m;while((m=re.exec(txt))){const w=m[1].trim();o.works.set(w,(o.works.get(w)||0)+1);}}};
  for(const id of ids){try{scan(libPlain(id),id);}catch(e){}}
  // textos que no están en la Biblioteca: fichas del modo atención y temarios de Atenea/Minerva
  try{for(const k in ATX_DEF){const D=ATX_DEF[k];scan(D[2]+' '+D[3],null);}}catch(e){}
  try{for(const c in AM_TOPICS)for(const a in AM_TOPICS[c])for(const t of AM_TOPICS[c][a])scan(JSON.stringify(t),null);}catch(e){}
  FI_BUSY=false;FI={mode:MODE,by};return FI;}
function fiList(){const F=fiBuild();return[...F.by.keys()].sort((a,b)=>FI_AUTH[a][2]-FI_AUTH[b][2]);}
{const f=libSections;libSections=function(){const S=f();if(FI_BUSY)return S;try{const L=fiList();S.push({t:_t(11512,'Índice de fuentes'),items:[{id:'f:guia',title:_t(11513,'Antes, durante o después: cómo leer las fuentes')}].concat(L.map(i=>({id:'f:'+i,title:FI_AUTH[i][0]})))});}catch(e){}return S;};}
{const f=libPlain;libPlain=function(id){if(!id.startsWith('f:'))return f(id);const v=id.slice(2);if(v==='guia')return 'fuentes antes durante después época posterior anterior';const A=FI_AUTH[+v];return A?A[0]+' '+A[4]+' fuente autor':'';};}
{const f=showArticle;showArticle=function(id){if(!id.startsWith('f:'))return f(id);libCur=id;const v=id.slice(2),F=fiBuild(),Y=fiYear();let h='<article>';
  if(v==='guia'){const L=fiList(),grp={antes:[],epoca:[],despues:[]};L.forEach(i=>grp[fiWhen(FI_AUTH[i]).k].push(i));
    h+=_t(11514,'<span class="label">Índice de fuentes</span><h3>Antes, durante o después: cómo leer las fuentes</h3>')+
      _t(11515,'<p>El juego pasa en el ')+fiY(Y)+_t(11516,', y cada dato viene de algún autor antiguo, pero no todos vivieron entonces. Quien escribe <b>en la época</b> pudo verlo o hablar con quien lo vio; quien escribe <b>después</b> cuenta lo que se recordaba o lo que leyó, a veces siglos más tarde, y puede equivocarse o adornarlo. Por eso, en el juego, lo que viene de una fuente posterior se marca.</p>')+
      _t(11517,'<p class="sub">Pregunta para pensar: ¿por qué un historiador que escribe trescientos años después puede saber algo que no cuenta nadie de la época? ¿Y por qué puede equivocarse?</p>');
    const row=i=>{const A=FI_AUTH[i],o=F.by.get(i);return '<button data-fi="'+i+'" style="display:block;width:100%;text-align:left;margin:3px 0">'+A[0]+' <span class="sub">('+fiY(A[2])+' – '+fiY(A[3])+', '+A[4]+') · '+(o.items.size+o.other)+_t(11518,' citas</span></button>');};
    h+=_t(11519,'<h5>Anteriores al año del juego (')+grp.antes.length+')</h5>'+grp.antes.map(row).join('')+_t(11520,'<h5>De la época (')+grp.epoca.length+')</h5>'+grp.epoca.map(row).join('')+_t(11521,'<h5>Posteriores (')+grp.despues.length+')</h5>'+grp.despues.map(row).join('');}
  else{const i=+v,A=FI_AUTH[i],o=F.by.get(i)||{items:new Set(),works:new Map(),other:0},W=fiWhen(A);
    h+=_t(11522,'<span class="label">Índice de fuentes · ')+A[4]+'</span><h3>'+A[0]+'</h3><div class="meta">'+fiY(A[2])+' – '+fiY(A[3])+' · <b>'+W.t+_t(11523,'</b> (el juego pasa en el ')+fiY(Y)+')</div>';
    if(o.works.size)h+=_t(11524,'<h5>Obras citadas</h5><ul class="src">')+[...o.works].sort((a,b)=>b[1]-a[1]).map(([w,n])=>'<li>'+w+(n>1?' <span class="sub">('+n+')</span>':'')+'</li>').join('')+'</ul>';
    const its=[...o.items];h+=_t(11525,'<h5>Dónde aparece en la Biblioteca (')+its.length+')</h5>'+(its.length?its.map(x=>{let t=x;try{for(const sc of libSections())for(const it of sc.items)if(it.id===x)t=it.title;}catch(e){}return '<button data-go="'+x+'" style="display:block;text-align:left;margin:3px 0">'+t+'</button>';}).join(''):_t(11526,'<p class="sub">En ningún artículo.</p>'));
    if(o.other)h+=_t(11527,'<p class="sub">Además, ')+o.other+' '+(o.other===1?'cita':'citas')+_t(11528,' en las fichas del modo atención y en los temarios de ')+(MODE==='roma'?_t(4558,'Minerva'):_t(5546,'Atenea'))+'.</p>';
    h+=_t(11529,'<p><button data-go="f:guia">← Todas las fuentes</button></p>');}
  h+='</article>';$('libArt').innerHTML=h;$('libArt').scrollTop=0;
  $('libArt').querySelectorAll('[data-fi]').forEach(b=>b.onclick=()=>showArticle('f:'+b.dataset.fi));
  $('libArt').querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>showArticle(b.dataset.go));
  $('libList').querySelectorAll('button').forEach(b=>b.setAttribute('aria-current',b.dataset.id===id?'true':'false'));};}
// ============================================================ SALTAR MURETES: «E · Saltar el murete» y un salto lateral ágil
// Las colisiones del juego son planas (paredes sin altura), así que un pilón, un murete o un banco cortaban el paso aunque saltaras.
// Ahora, si empujas contra algo bajo (entre 35 cm y 1,4 m), despejado por encima y con suelo libre al otro lado a menos de 2 m,
// aparece «E · Saltar el murete». Al pulsarlo el personaje lo salva de un salto de lado, apoyando una mano (la cámara se ladea un poco).
const VT={can:null,on:null,t:0,near:[],nearT:0,nearX:1e9,nearZ:1e9,ray:null,seen:false,side:1};
function vtNear(){const P=player;if(VT.nearT>0&&Math.hypot(P.x-VT.nearX,P.z-VT.nearZ)<8)return VT.near;VT.nearT=1;VT.nearX=P.x;VT.nearZ=P.z;const L=[],s=new THREE.Sphere(),v=new THREE.Vector3(),m=new THREE.Matrix4();
  scene.traverse(o=>{if(!o.isMesh||!o.visible||!o.geometry||o.userData.noVault)return;for(let q=o;q;q=q.parent){if(q.visible===false||q.userData&&(q.userData.walk||q.userData.arms||q.userData.anim))return;}
    const mt=Array.isArray(o.material)?o.material[0]:o.material;if(mt&&(mt.transparent&&mt.opacity<0.9))return;
    if(o.isInstancedMesh){if(o.count>4000)return;let b=o.userData.vtB;if(!b){let x0=1e9,x1=-1e9,z0=1e9,z1=-1e9;for(let i=0;i<o.count;i++){o.getMatrixAt(i,m);v.setFromMatrixPosition(m).applyMatrix4(o.matrixWorld);x0=Math.min(x0,v.x);x1=Math.max(x1,v.x);z0=Math.min(z0,v.z);z1=Math.max(z1,v.z);}
        b=o.userData.vtB={x:(x0+x1)/2,z:(z0+z1)/2,r:Math.hypot(x1-x0,z1-z0)/2+6};}if(Math.hypot(b.x-P.x,b.z-P.z)<b.r+16)L.push(o);return;}
    if(!o.geometry.boundingBox)o.geometry.computeBoundingBox();const bx=VT.bb||(VT.bb=new THREE.Box3());bx.copy(o.geometry.boundingBox).applyMatrix4(o.matrixWorld);   // las piezas repetidas van juntas en mallas por zonas
    if(bx.max.x-bx.min.x>400||bx.max.z-bx.min.z>400)return;   // terreno y mar
    if(P.x>bx.min.x-16&&P.x<bx.max.x+16&&P.z>bx.min.z-16&&P.z<bx.max.z+16)L.push(o);});
  VT.near=L;return L;}
// rayo contra lo cercano. Las piezas repetidas (chunked) guardan su esfera envolvente ya en coordenadas del mundo y el raycast de
// three.js la vuelve a transformar por cada pieza, así que nunca acierta: para ellas se pasa el rayo a las coordenadas de cada pieza
// cercana y se prueba contra su caja (basta para saber la altura de un pilón o un murete).
const VT_M=new THREE.Matrix4(),VT_I=new THREE.Matrix4(),VT_P=new THREE.Vector3(),VT_R=new THREE.Ray(),VT_Q=new THREE.Vector3();
function vtHit(ox,oy,oz,dx,dy,dz,far){const R=VT.ray||(VT.ray=new THREE.Raycaster());const O=new THREE.Vector3(ox,oy,oz),D=new THREE.Vector3(dx,dy,dz).normalize();R.set(O,D);R.far=far;
  const plain=[],inst=[];for(const o of vtNear())(o.isInstancedMesh?inst:plain).push(o);let best=null;
  const h=R.intersectObjects(plain,false);if(h.length)best={point:h[0].point.clone(),distance:h[0].distance};
  for(const o of inst){const g=o.geometry;if(!g.boundingBox)g.computeBoundingBox();const bb=g.boundingBox,ext=Math.max(bb.max.x-bb.min.x,bb.max.y-bb.min.y,bb.max.z-bb.min.z);
    for(let i=0;i<o.count;i++){o.getMatrixAt(i,VT_M);VT_M.premultiply(o.matrixWorld);VT_P.setFromMatrixPosition(VT_M);const sc=Math.max(1,VT_Q.setFromMatrixScale(VT_M).x,VT_Q.y,VT_Q.z);
      if(Math.abs(VT_P.x-ox)>far+ext*sc+1||Math.abs(VT_P.z-oz)>far+ext*sc+1)continue;
      VT_I.copy(VT_M).invert();VT_R.origin.copy(O).applyMatrix4(VT_I);VT_R.direction.copy(D).transformDirection(VT_I);
      if(!VT_R.intersectBox(bb,VT_Q))continue;VT_Q.applyMatrix4(VT_M);const d=VT_Q.distanceTo(O);if(d<=far&&(!best||d<best.distance))best={point:VT_Q.clone(),distance:d};}}
  return best;}
function vtShift(x,z){const q={x,z};resolve(q,0.35);return Math.hypot(q.x-x,q.z-z);}
function vtProbe(){const P=player,fx=-Math.sin(P.yaw),fz=-Math.cos(P.yaw),f0=P.feet;
  if(vtShift(P.x+fx*0.55,P.z+fz*0.55)<0.08)return null;   // delante no hay nada que corte el paso
  let dl=0;for(let d=0.7;d<=2.2;d+=0.1){if(vtShift(P.x+fx*d,P.z+fz*d)<0.02){dl=d+0.3;break;}}if(!dl)return null;   // demasiado grueso: es un edificio
  const lx=P.x+fx*dl,lz=P.z+fz*dl,fL=floorAt(lx,lz);if(!isFinite(fL)||fL-f0>0.8||f0-fL>2.5)return null;
  if(vtShift(lx,lz)>0.05)return null;
  let top=-1e9;for(let d=0.45;d<=dl-0.2;d+=0.15){const h=vtHit(P.x+fx*d,f0+2.4,P.z+fz*d,0,-1,0,2.6);if(h)top=Math.max(top,h.point.y);}
  const H=top-f0;if(!(H>=0.35&&H<=1.4))return null;
  if(vtHit(P.x,f0+1.75,P.z,fx,0,fz,dl))return null;   // a la altura del pecho hay pared: es una ventana o un muro alto
  return{lx,lz,top,fL,H};}
function vtGo(){const c=VT.can;if(!c||VT.on)return;const P=player,peak=c.top-P.feet+0.35,vy=Math.sqrt(2*16*Math.max(0.5,peak)),air=2*vy/16;
  VT.on={t:0,T:Math.max(0.42,air*0.82),sx:P.x,sz:P.z,lx:c.lx,lz:c.lz};VT.side=-VT.side;VT.can=null;P.vy=vy;P.grounded=false;P.jumps=1;
  try{gfPulse();}catch(e){}try{if(aOK())sfxTap();}catch(e){}
  if(!VT.seen){VT.seen=true;try{const z=state.vt||(state.vt={});if(!z.n){toast(_t(11530,'<span class="label">Saltar</span><br>Apoyas una mano y pasas por encima de lado, sin perder el paso. Funciona con muretes, pilones y bancos bajos.'));}z.n=(z.n||0)+1;}catch(e){}}}
// mientras dura el salto, el movimiento lo lleva el salto (las paredes planas no frenan)
{const f=tryMove;tryMove=function(nx,nz){if(VT.on)return true;return f(nx,nz);};}
