function vtTick(dt){
  if(VT.on){const o=VT.on,P=player;o.t+=dt;const k=Math.min(1,o.t/o.T),e=k<0.5?2*k*k:1-Math.pow(-2*k+2,2)/2;P.x=o.sx+(o.lx-o.sx)*e;P.z=o.sz+(o.lz-o.sz)*e;
    const s=Math.sin(Math.PI*k);GF.roll=s*0.16*VT.side;const W=AVATAR.walk;if(W)W.rotation.z=-s*0.55*VT.side;
    if((k>=1&&P.grounded)||o.t>o.T+1.5){VT.on=null;if(W)W.rotation.z=0;try{if(state.vt&&state.vt.n%10===0)qAdd('ar',1,_t(11531,'Cada vez saltas con más soltura.'));save();}catch(e){}}
    return;}
  VT.nearT-=dt;
  // en móvil, el botón de hablar también salta
  {const b=$('tTalk');if(b&&!b.dataset.vt){b.dataset.vt=1;const o=b.onclick;b.onclick=function(ev){if(ui==='play'&&!focus&&VT.can){vtGo();return;}return o&&o.call(this,ev);};}}
  VT.pt=(VT.pt||0)-dt;const mvd=Math.hypot(player.x-(VT.px||0),player.z-(VT.pz||0))>0.05||Math.abs(player.yaw-(VT.py||0))>0.06;   // quieto ante el mismo murete: no se vuelve a medir
  if(VT.pt<=0&&mvd){VT.pt=0.12;VT.px=player.x;VT.pz=player.z;VT.py=player.yaw;const ok=ui==='play'&&!FLY.on&&!BOAT.on&&!MOUNT.riding&&player.grounded&&!(typeof RF!=='undefined'&&RF.onRoof);VT.can=ok?vtProbe():null;}
  const p=$('prompt');if(VT.can&&!focus&&p){p.innerHTML=_t(11532,'<kbd>E</kbd>Saltar el murete');p.hidden=false;}}
// ============================================================ CURRÍCULO: qué saberes trabaja cada lección (relación orientativa)
// Cada lección tiene una categoría (Política, Sociedad, Mitos…). Aquí se relaciona con los grandes bloques de saberes de la ESO
// (LOMLOE): Geografía e Historia, y Cultura Clásica, Latín y Griego. No son códigos oficiales: es una guía para que el docente vea
// qué ha trabajado cada alumno. Sale en el informe del alumno y en el Panel de clase (por alumno y para toda la clase).
const CUR_S={
 gh_poder:[_t(11533,'Geografía e Historia'),_t(11534,'Formas de gobierno y ciudadanía'),_t(11535,'la polis y la democracia; la República y el Imperio; quién participa y quién no')],
 gh_soc:[_t(11533,'Geografía e Historia'),_t(11536,'Sociedad, economía y vida cotidiana'),_t(11537,'libres y esclavos, mujeres, trabajo, comercio, educación, la casa')],
 gh_hist:[_t(11533,'Geografía e Historia'),_t(11538,'Hechos y procesos históricos'),_t(11539,'guerras, expansión, colonias, el territorio y sus cambios')],
 gh_pat:[_t(11533,'Geografía e Historia'),_t(11540,'Arte y patrimonio'),_t(11541,'templos, escultura, urbanismo; cómo se conserva y se estudia')],
 cc_mito:[_t(11542,'Cultura Clásica, Latín y Griego'),_t(11543,'Mitología y religión'),_t(11544,'dioses, héroes, ritos, oráculos y fiestas')],
 cc_pens:[_t(11542,'Cultura Clásica, Latín y Griego'),_t(11545,'Pensamiento y ciencia'),_t(11546,'filosofía, medicina, astronomía, técnica')],
 cc_leg:[_t(11542,'Cultura Clásica, Latín y Griego'),_t(11547,'Legado clásico'),_t(11548,'instituciones, palabras, arte e ideas que han llegado hasta hoy')]};
// los nombres van como valores (no como claves) para que se traduzcan igual que la categoría de las lecciones en catalán e inglés
const CUR_CAT=Object.fromEntries([[_t(15,'Política'),['gh_poder','cc_leg']],['Guerra',['gh_hist','gh_poder']],[_t(123,'Historia'),['gh_hist']],['Geografía',['gh_hist']],[_t(143,'Sociedad'),['gh_soc']],[_t(9673,'Economía'),['gh_soc']],[_t(2819,'Vida cotidiana'),['gh_soc']],['Técnica',['gh_soc','cc_pens']],[_t(9988,'Educación'),['gh_soc','cc_leg']],['Arte',['gh_pat','cc_leg']],[_t(161,'Cultura'),['gh_pat','cc_leg']],[_t(289,'Religión'),['cc_mito']],[_t(307,'Mitos'),['cc_mito']],['Mito',['cc_mito']],['Mitología',['cc_mito']],[_t(615,'Genealogías'),['cc_mito']],[_t(67,'Filosofía'),['cc_pens']],[_t(461,'Ciencia'),['cc_pens']],['Naturaleza',['cc_pens']]]);
function curOf(ids){const n={};for(const id of ids||[]){const L=LESSONS[id];if(!L)continue;for(const k of CUR_CAT[L.cat]||[])n[k]=(n[k]||0)+1;}return n;}
function curAll(){const n={};for(const id in LESSONS){const L=LESSONS[id];for(const k of CUR_CAT[L.cat]||[])n[k]=(n[k]||0)+1;}return n;}
// informe del alumno
{const f=dzReport;dzReport=function(){const r=f();try{const n=curOf(state.lessons),T=curAll();const L=['',_t(11549,'Relación orientativa con el currículo (lecciones superadas / disponibles):')];
  for(const k in CUR_S)if(T[k])L.push('  '+CUR_S[k][0]+' · '+CUR_S[k][1]+': '+(n[k]||0)+' / '+T[k]);
  const i=r.indexOf('--- datos para el panel');return i>=0?r.slice(0,i)+L.join('\n')+'\n\n'+r.slice(i):r+L.join('\n');}catch(e){return r;}};}
{const f=pdData;pdData=function(){const d=f();try{d.cur=curOf(state.lessons);d.curT=curAll();}catch(e){}return d;};}
// Panel de clase: tabla por saberes
{const f=pdRender;pdRender=function(){f();try{const O=$('pdOut'),R=PD.rows;if(!O||!R.length)return;
  const keys=Object.keys(CUR_S).filter(k=>R.some(r=>r.curT&&r.curT[k]));if(!keys.length)return;
  const esc=t=>String(t==null?'':t).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
  const cell=(r,k)=>{const a=(r.cur&&r.cur[k])||0,t=(r.curT&&r.curT[k])||0;if(!t)return '—';const p=a/t;return '<span title="'+a+' de '+t+'" style="display:inline-block;min-width:3.2em;padding:1px 4px;border-radius:4px;background:rgba(201,138,74,'+(0.12+p*0.7).toFixed(2)+')">'+a+'/'+t+'</span>';};
  let h=_t(11550,'<h3 style="margin-top:18px">Por saberes del currículo</h3><p class="sub">Relación orientativa entre las categorías de las lecciones y los bloques de saberes de la ESO (Geografía e Historia; Cultura Clásica, Latín y Griego). No son códigos oficiales. Cuanto más intenso el color, más lecciones superadas de ese bloque.</p>')+
    '<div style="overflow:auto"><table style="border-collapse:collapse;width:100%;font-size:.88em"><tr><th style="text-align:left;padding:4px;border-bottom:1px solid #6a4a30">Alumno</th>'+keys.map(k=>'<th style="text-align:left;padding:4px;border-bottom:1px solid #6a4a30" title="'+esc(CUR_S[k][2])+'">'+esc(CUR_S[k][1])+'<br><span class="sub" style="font-weight:normal">'+esc(CUR_S[k][0])+'</span></th>').join('')+'</tr>'+
    R.map(r=>'<tr><td style="padding:4px;border-bottom:1px solid #3a2a1e">'+esc(r.nombre)+'</td>'+keys.map(k=>'<td style="padding:4px;border-bottom:1px solid #3a2a1e">'+cell(r,k)+'</td>').join('')+'</tr>').join('')+'</table></div>';
  // lo menos trabajado por la clase
  const share=k=>{let a=0,t=0;for(const r of R){a+=(r.cur&&r.cur[k])||0;t+=(r.curT&&r.curT[k])||0;}return t?a/t:1;};const low=keys.slice().sort((a,b)=>share(a)-share(b)).slice(0,2);
  h+=_t(11551,'<p><b>Lo menos trabajado por la clase:</b> ')+low.map(k=>esc(CUR_S[k][1])+' ('+Math.round(share(k)*100)+'%)').join(' · ')+_t(11552,'. En Aprender › Rutas por temas hay recorridos guiados para reforzarlo.</p>');
  O.insertAdjacentHTML('beforeend',h);}catch(e){}};}
// ============================================================ CONVERSACIONES CON CONSECUENCIAS: rumores, votos que se recuerdan y recomendaciones
// Lo que haces deja huella en la gente:
//  1. Rumores. Tus actos (cómo votaste en la Asamblea o el Senado, las cartas que entregaste, con quién aprendiste) corren de boca en boca:
//     quien vive cerca te lo comenta al empezar a hablar, una vez por persona y hecho.
//  2. Tu voto se recuerda. Según lo que votaste, unos te dan la razón y otros te la discuten.
//  3. Una puerta que se abre. Cuando ya te conocen (lecciones y buena fama), te recomiendan a alguien que sabe de lo que menos has
//     trabajado, y te lo señalan con una columna de luz.
function cqz(){const s=state;if(!s.cq)s.cq={ev:[],told:{},rec:{}};return s.cq;}
function cqAdd(k,txt,x,z,good){const Z=cqz();if(Z.ev.some(e=>e.k===k))return;Z.ev.push({k,txt,x,z,good:good!==false,day:state.day||1});if(Z.ev.length>40)Z.ev.shift();save();}
// reacciones a cada voto (lo que dirán los vecinos); h: la que coincide con lo que pasó en la historia
const CQ_VOTE={
 paz:{si:_t(11553,'«Te oí en la Pnyx votar por la paz del Rey. Hiciste bien: con el trigo cortado en el Helesponto no se podía seguir. Aunque duele dejar Jonia a los persas».'),
      no:_t(11554,'«Así que votaste contra la paz… Valiente, pero la ciudad está agotada y sin trigo. Mi vecino dice que eres un exaltado; yo creo que tienes orgullo de ateniense».')},
 proxenia:{si:_t(11555,'«Votaste los honores para el extranjero que nos ayudó. Bien: quien trata bien a Atenas debe saber que Atenas no olvida».'),
      no:_t(11556,'«¿Votaste contra honrar al próxeno? Hay quien piensa como tú: que los honores se dan ya demasiado fácilmente».')},
 estrategos:{a:_t(11557,'«Diste tu mano a Cabrias. Buen soldado, sí, aunque hay diez puestos y caben más».'),b:_t(11558,'«Votaste a Ifícrates, el de los peltastas. Los aristócratas aún no le perdonan que sea hijo de un zapatero».'),
      c:_t(11559,'«Votaste a los dos generales. Eso es saber contar: son diez estrategos cada año».')},
 campania:{a:_t(11560,'«Se dice que en el Senado apostaste por el sorteo entre los consulares. Así se hace: que la suerte reparta y nadie se ofenda».'),b:_t(11561,'«Dicen que creías que se votaría a los comisionados para Campania. Aquí casi todo se deja a la suerte… o al príncipe».')},
 incendio:{a:_t(11562,'«Me contaron que en la Curia diste por hecho que pagaría el príncipe. Y así es: Tito abre su bolsa, y luego se le agradece».'),b:_t(11563,'«¿Creías que pagarían las ciudades de Italia? Bastante tienen con la ceniza del Vesubio».')}};
// 1-2. al votar
{const f=asEnd;asEnd=function(I,v,mine){f.apply(this,arguments);try{const R=CQ_VOTE[I.id];if(R&&R[v]){cqz().votes=cqz().votes||{};cqz().votes[I.id]=v;
  cqAdd('vote:'+I.id,R[v],player.x,player.z,v===I.hist||v===I.hist2);}}catch(e){}};}
// cartas entregadas y lecciones con personajes históricos: se apuntan como hechos
{const f=uxTick;uxTick=function(dt){f(dt);try{if(!state||ui!=='play')return;const Z=cqz();Z.chk=(Z.chk||0)+dt;if(Z.chk<2)return;Z.chk=0;
  const dz=typeof dzz==='function'?dzz():null;if(dz&&dz.cartas&&dz.cartas>(Z.cartas||0)){Z.cartas=dz.cartas;cqAdd('carta:'+dz.cartas,_t(11564,'«¿Tú eres quien trajo la carta desde tan lejos? Aquí eso se agradece: sin viajeros como tú, no sabríamos nada de los nuestros».'),player.x,player.z,true);}
  for(const id of state.lessons||[]){if(Z['l:'+id])continue;Z['l:'+id]=1;if(typeof HIST!=='undefined'&&HIST.has(id)){const n=NPCS.find(q=>q.id===id);if(n){const o=npcObjs.find(q=>q.data===n);cqAdd('les:'+id,_t(11565,'«Dicen que has estado hablando con ')+n.name+_t(11566,'. ¡Nada menos! ¿Es verdad todo lo que se cuenta?»'),o?o.x:player.x,o?o.z:player.z,true);}}}}catch(e){}};}
// el rumor aparece al empezar a hablar con alguien que vive cerca (a menos de 500 m del hecho), una vez por persona y hecho
{const f=openDialog;openDialog=function(n){f.apply(this,arguments);try{if(!n||!n.topics||ui!=='dialog')return;const Z=cqz(),o=npcObjs.find(q=>q.data===n);if(!o)return;const t=Z.told[n.id]||(Z.told[n.id]={});
  const ev=Z.ev.filter(e=>!t[e.k]&&Math.hypot(e.x-o.x,e.z-o.z)<500&&!e.k.endsWith(':'+n.id)).slice(-3);if(!ev.length)return;const e=ev[ev.length-1];t[e.k]=1;save();
  $('dBody').insertAdjacentHTML('beforeend','<p class="sub" style="border-left:3px solid #c98a4a;padding-left:8px">'+e.txt+'</p>');}catch(e){}};}
// 3. recomendaciones
function cqRecCat(){// el bloque del currículo que menos has trabajado, y una persona que sabe de él y aún no te ha enseñado
  let best=null;try{const n=curOf(state.lessons),T=curAll();let lo=2;for(const k in T){const p=(n[k]||0)/T[k];if(p<lo){lo=p;best=k;}}}catch(e){}
  const cats=best?Object.keys(CUR_CAT).filter(c=>CUR_CAT[c].includes(best)):null;
  const c=npcObjs.filter(o=>o.data.topics&&o.data.quiz&&!(state.lessons||[]).includes(o.data.id)&&(!cats||cats.includes(LESSONS[o.data.id]&&LESSONS[o.data.id].cat))&&o.x<8000);
  if(!c.length)return null;c.sort((a,b)=>Math.hypot(a.x-player.x,a.z-player.z)-Math.hypot(b.x-player.x,b.z-player.z));return c[Math.min(2,c.length-1)];}
{const f=renderOpts;renderOpts=function(extra){f(extra);try{const n=dlg&&dlg.n;if(!n||!n.topics)return;const Z=cqz(),L=(state.lessons||[]).length;let hs=0;try{hs=honScore();}catch(e){}
  if(L<6||hs<15||Z.rec[n.id]||!(state.lessons||[]).includes(n.id))return;   // te recomienda quien ya te ha enseñado algo
  const o=$('dOpts'),b=document.createElement('button');b.className='quiz';b.innerHTML=_t(11567,'<span class="n">☞</span><span>«¿Conoces a alguien que sepa más que yo de otras cosas?»</span>');
  b.onclick=()=>{const t=cqRecCat();Z.rec[n.id]=1;save();if(!t){$('dBody').innerHTML=_t(11568,'<p>«Ya conoces a todos los que yo conozco. ¡Ahora eres tú quien debería presentarme a mí!»</p>');renderOpts();return;}
    const L2=LESSONS[t.data.id]||{};$('dBody').innerHTML=_t(11569,'<p>«Ve a ver a <b>')+t.data.name+'</b>'+(t.data.title?', '+t.data.title.charAt(0).toLowerCase()+t.data.title.slice(1):'')+_t(11570,'. Dile que vas de mi parte: te hablará de <i>')+(L2.title||_t(11571,'lo suyo'))+_t(11572,'</i>. Te indico por dónde».</p><p class="sub">Verás una columna de luz donde está. Entre los antiguos, una carta o una palabra de recomendación abría puertas: Cicerón escribió un libro entero de ellas (Cartas a los familiares, libro 13).</p>');
    try{mtBeacon(t.x,t.z);MTR.beaconT=600;}catch(e){}cqz().recTo=t.data.id;save();renderOpts();};
  o.insertBefore(b,o.lastChild);}catch(e){}};}
// al llegar a la persona recomendada, te recibe de otra manera (y algo de fama)
{const f=openDialog;openDialog=function(n){f.apply(this,arguments);try{const Z=cqz();if(n&&Z.recTo===n.id){Z.recTo=null;qAdd('kl',1,_t(11573,'Vienes recomendado: eso abre puertas.'));save();
  $('dBody').insertAdjacentHTML('afterbegin',_t(11574,'<p class="sub" style="border-left:3px solid #c98a4a;padding-left:8px">«¿Vienes de parte de un amigo? Entonces pasa, siéntate: para ti tengo tiempo».</p>'));}}catch(e){}};}
// ============================================================ MISIÓN DE GRUPO (modo en línea): preparar un banquete entre varios
// Solo en una sala en línea. Cada jugador se encarga de uno o más papeles (traer la crátera, el vino, el agua…); cada uno va a su sitio,
// señalado con una columna de luz, y al final el grupo se reúne. Hace falta que colaboren al menos dos personas distintas.
// No usa mensajes nuevos: el estado de cada uno viaja en su «presencia» (campo q), como la posición.
const COOP={
 atenas:{id:'symposion',title:_t(11575,'Preparar un banquete'),meet:'casa',meetN:_t(11576,'tu casa'),
  intro:_t(11577,'Esta noche hay banquete (sympósion) en tu casa. Repartíos el trabajo: alguien trae la crátera de los alfareros, alguien el vino y alguien el agua de la fuente. Cuando esté todo, reuníos allí.'),
  roles:[{k:'krater',n:_t(11578,'La crátera'),at:'demo_kerameis',t:_t(11579,'En el barrio de los alfareros eliges una crátera pintada, el vaso grande donde se mezcla el vino con el agua.')},
         {k:'vino',n:_t(10263,'El vino'),at:'mercado',t:_t(11580,'En el mercado compras un ánfora de vino de Quíos: el mejor, y el más caro.')},
         {k:'agua',n:_t(11581,'El agua fresca'),at:'fuente',t:_t(11582,'Llenas una hidria en la fuente: el vino se bebe mezclado con mucha agua.')}],
  end:_t(11583,'<p>Os recostáis en los lechos, con coronas en la cabeza. Primero se vierte un poco de vino puro para el «buen genio» (Agathós Daímon); después el que preside, el simposiarca, decide cuánta agua lleva cada crátera. Beber el vino sin mezclar es cosa de bárbaros: se cuenta que el rey espartano Cleómenes enloqueció por beberlo puro, como los escitas (Heródoto 6, 84).</p><p>En el Banquete de Platón los invitados acuerdan beber con moderación para poder hablar del amor toda la noche (176a-e); en el de Jenofonte, hay música, acertijos y una bailarina. El banquete es eso: vino, conversación y amistad.</p>')},
 roma:{id:'cena',title:_t(11584,'Preparar una cena'),meet:'domus_triclinio',meetN:_t(11585,'el triclinio de la domus'),
  intro:_t(11586,'Esta noche hay cena en la domus. Repartíos el trabajo: alguien va al gran mercado por la comida, alguien al horno de la Subura por el pan, alguien a la fuente por agua y alguien a buscar al último invitado a la salida de las termas. Después, todos al triclinio.'),
  roles:[{k:'comida',n:_t(11587,'La comida'),at:'ro_macellum',t:_t(11588,'En el mercado de Nerón compras pescado, aceitunas, huevos y un buen trozo de cerdo.')},
         {k:'pan',n:_t(11589,'El pan'),at:'ro_subura',t:_t(11590,'En un horno (pistrinum) de la Subura compras panes redondos, marcados en ocho porciones.')},
         {k:'agua',n:_t(11591,'El agua'),at:'ro_lacus',t:_t(11592,'En la fuente del barrio llenas una jarra: el vino se sirve con agua, a veces caliente.')},
         {k:'invitado',n:_t(11593,'El último invitado'),at:'ro_termas',t:_t(11594,'A la salida de las Termas de Tito encuentras a tu amigo… y a uno que se apunta sin que nadie lo invite. Marcial se burla de uno así, que te persigue por todas las termas hasta que lo invitas a cenar (Epigramas 12, 82).')}],
  end:_t(11595,'<p>Os recostáis en tres lechos alrededor de la mesa, como manda la costumbre: el triclinio. Varrón decía que los invitados no deben ser menos que las Gracias ni más que las Musas: entre tres y nueve (en Aulo Gelio, Noches áticas 13, 11, 2). Primero los entrantes con huevos, luego los platos fuertes y, al final, la fruta: «del huevo a las manzanas» (Horacio, Sátiras 1, 3, 6-7).</p><p>Antes del postre se ofrece algo a los Lares. Después, conversación, música… y algún esclavo que lee poesía.</p>')}};
function coopDef(){return COOP[MODE==='roma'?'roma':'atenas'];}
function coopAt(id){const p=(PLACES||[]).find(q=>q.id===id);return p?{x:p.x,z:p.z}:null;}
function coopz(){const s=state;if(!s.coop)s.coop={done:{}};return s.coop;}
// estado de la misión a partir de mi q y de las presencias de los demás
function coopStatus(){const D=coopDef(),r=NET.room;const peers=[];if(r)for(const p of r.peers()){if(p.sameTab)continue;const pr=p.presence||{};peers.push({n:netClean(pr.n,20)||_t(10133,'Alguien'),x:+pr.x,z:+pr.z,q:pr.q});}
  const me={n:NET.name||_t(9161,'Tú'),x:player.x,z:player.z,q:NET.q,me:true},all=[me,...peers].filter(p=>p.q&&p.q.m===D.id&&p.q.r);
  const roles={};for(const R of D.roles)roles[R.k]={by:[],got:false};
  for(const p of all)for(const k in p.q.r){if(!roles[k])continue;roles[k].by.push(p.n);if(p.q.r[k])roles[k].got=true;}
  const contrib=all.filter(p=>Object.values(p.q.r).some(v=>v));const allGot=D.roles.every(R=>roles[R.k].got);
  const M=coopAt(D.meet),here=M?all.filter(p=>Math.hypot(p.x-M.x,p.z-M.z)<15):[];
  return{D,roles,all,contrib,allGot,M,here,ready:allGot&&contrib.length>=2&&here.length>=all.length};}
function coopOpen(){if(!NET.room){toast(_t(11596,'La misión de grupo es para jugar en línea: entra antes en una sala (menú › En línea).'));return;}const D=coopDef();
  eduOverlay('coopBox',D.title,'<p>'+D.intro+_t(11597,'</p><div id="coopL"></div><p class="sub">Hace falta que colaboren al menos dos personas. Cada uno ve en su pantalla lo que han conseguido los demás.</p>'));coopRender();}
function coopRender(){const L=$('coopL');if(!L)return;const S=coopStatus(),D=S.D,my=(NET.q&&NET.q.m===D.id)?NET.q.r:{};
  L.innerHTML=D.roles.map(R=>{const st=S.roles[R.k],mine=R.k in my;return '<div style="padding:8px;border:1px solid #6a4a30;border-radius:8px;margin:6px 0"><b>'+R.n+'</b> · '+(st.got?_t(11598,'✓ conseguido'):st.by.length?_t(11599,'se encarga: ')+st.by.join(', '):_t(11600,'nadie aún'))+
    (mine?(my[R.k]?'':_t(11601,' <span class="sub">(ve al sitio marcado)</span>')):' <button data-k="'+R.k+_t(11602,'">Me encargo yo</button>'))+'</div>';}).join('')+
    (S.allGot?_t(11603,'<p><b>¡Ya está todo! Reuníos en ')+D.meetN+'.</b></p>':'');
  L.querySelectorAll('button[data-k]').forEach(b=>b.onclick=()=>{if(!NET.q||NET.q.m!==D.id)NET.q={m:D.id,r:{}};NET.q.r[b.dataset.k]=0;try{netPresence(true);}catch(e){}
    const R=D.roles.find(x=>x.k===b.dataset.k),p=coopAt(R.at);if(p){try{mtBeacon(p.x,p.z);MTR.beaconT=600;}catch(e){}}toast('<span class="label">'+R.n+_t(11604,'</span><br>Te encargas tú. Ve al sitio marcado con la columna de luz.'));coopRender();});}
{const f=uxTick;uxTick=function(dt){f(dt);try{coopTick(dt);}catch(e){}};}
function coopTick(dt){if(!NET.room||!NET.q||ui!=='play')return;const D=coopDef();if(NET.q.m!==D.id)return;
  // llegar al sitio de cada papel propio
  for(const k in NET.q.r){if(NET.q.r[k])continue;const R=D.roles.find(x=>x.k===k),p=R&&coopAt(R.at);if(p&&Math.hypot(player.x-p.x,player.z-p.z)<8){NET.q.r[k]=1;try{netPresence(true);}catch(e){}
      toast('<span class="label">'+R.n+' ✓</span><br>'+R.t);try{netSay('',NET.name+': '+R.n.toLowerCase()+' ✓');}catch(e){}coopRender();}}
  NET.qt=(NET.qt||0)-dt;if(NET.qt>0)return;NET.qt=0.5;const S=coopStatus();
  if(S.allGot&&!NET.qMeet){NET.qMeet=1;if(S.M){try{mtBeacon(S.M.x,S.M.z);MTR.beaconT=900;}catch(e){}}toast('<span class="label">'+D.title+_t(11605,'</span><br>¡Ya está todo! Reuníos en ')+D.meetN+_t(11606,' (columna de luz).')+(S.contrib.length<2?_t(11607,' Pero falta que colabore alguien más: entre todos, al menos dos.'):''));coopRender();}
  if(S.ready){const z=coopz();const first=!z.done[D.id];z.done[D.id]=(z.done[D.id]||0)+1;NET.q=null;NET.qMeet=0;try{netPresence(true);}catch(e){}
    if(first){qAdd('kl',2,_t(11608,'El banquete ha sido un éxito.'));qAdd('eu',1);}save();
    eduOverlay('coopEnd',D.title+' ✓',_t(11609,'<p class="sub">Con ')+S.all.map(p=>p.n).join(', ')+'.</p>'+D.end);}}
// botón en el panel del modo en línea
{const f=netList;netList=function(){f.apply(this,arguments);try{const h=$('netHead');if(h&&!$('coopBtn')){const b=document.createElement('button');b.id='coopBtn';b.textContent=_t(11610,'Misión de grupo');b.style.cssText='margin-left:8px;pointer-events:auto;font:inherit;font-size:.85em;padding:2px 8px;border-radius:6px;border:1px solid #c98a4a;background:#c98a4a;color:#1e1712;cursor:pointer';b.onclick=()=>coopOpen();h.parentNode.appendChild(b);}}catch(e){}};}
// ============================================================ INTERIORES DE ROMA: el Panteón, las Termas de Tito y la Basílica Julia por dentro
// Antes eran bloques macizos. Ahora se entra, a su tamaño, con actividad:
//  · Panteón: la rotonda con sus hornacinas, las estatuas de Marte, Venus y el Divino Julio (Dion Casio 53, 27) y la luz de lo alto.
//  · Termas de Tito: vestuario, sala templada, sala caliente y sala fría; si las recorres en el orden de un baño romano, lo aprendes.
//  · Basílica Julia: la nave de arcadas y el tribunal de los centunviros, donde asistes a un pleito por una herencia y votas.
// Lo que no se sabe con seguridad se dice en la propia ficha (la forma del Panteón de Agripa, por ejemplo).
const INT={term:null,bas:null};
function intWallSeg(x1,z1,x2,z2){addSeg(x1,z1,x2,z2,0.45);}
// ---------------------------------------------------------------- Panteón (lo llama 029_roma.js, después de la rotonda)
function pantheonInterior(cx,cz,gy){const g=grp(cx,gy,cz,0),y0=0.25;
  const wall=new THREE.Mesh(new THREE.CylinderGeometry(25.2,25.2,24,48,1,true),lam('#e3d8c2',{side:THREE.BackSide}));wall.position.y=12;wall.userData.noCol=true;g.add(wall);
  const dome=new THREE.Mesh(new THREE.SphereGeometry(25.2,48,16,0,TAU,0.16,Math.PI/2-0.16),lam('#d8ccb4',{side:THREE.BackSide}));dome.scale.y=0.62;dome.position.y=24;dome.userData.noCol=true;g.add(dome);
  const fl=new THREE.Mesh(new THREE.CircleGeometry(25.2,48),lam('#cfc3aa'));fl.rotation.x=-Math.PI/2;fl.position.y=y0+0.02;g.add(fl);
  for(let r=4;r<25;r+=6){const ring=new THREE.Mesh(new THREE.RingGeometry(r,r+0.25,48),lam('#8a5a4a'));ring.rotation.x=-Math.PI/2;ring.position.y=y0+0.04;g.add(ring);}   // bandas de pórfido en el suelo
  // siete hornacinas (la de enfrente de la puerta, más grande); en tres, las estatuas que cita Dion Casio
  const gods=[[_t(4572,'Marte'),_t(11611,'padre de Rómulo y antepasado de los romanos')],[_t(4586,'Venus'),_t(11612,'madre de Eneas y de la familia Julia')],[_t(11613,'El Divino Julio'),_t(11614,'César, convertido en dios tras su muerte')]];
  for(let i=0;i<7;i++){const a=Math.PI/2+(i-3)*(Math.PI*2/8),x=Math.cos(a)*24.4,z=Math.sin(a)*24.4,big=i===3;
    const n=box(big?7:5,big?11:8,0.6,lam('#5a4a3a'),x,y0+(big?6:4.5),z,g);n.rotation.y=-a+Math.PI/2;n.userData.noCol=true;
    const ped=box(1.4,1.1,1.2,lam('#d8ccb4'),Math.cos(a)*23.2,y0+0.55,Math.sin(a)*23.2,g);ped.userData.noCol=true;
    const gi=i===3?2:i===2?0:i===4?1:-1;if(gi>=0){const st=makePerson({noVary:true,chiton:'#ece6da',himation:'#e2dccf',hair:'#e8e2d6',skin:'#ece6da',beard:gi!==1});
      st.position.set(cx+Math.cos(a)*23.2,gy+y0+1.1,cz+Math.sin(a)*23.2);st.rotation.y=Math.atan2(-Math.cos(a),-Math.sin(a));st.scale.setScalar(1.35);scene.add(st);
      egxObj(cx+Math.cos(a)*21.6,cz+Math.sin(a)*21.6,gy+y0,'int:pg'+gi,gods[gi][0],gods[gi][1],3);}}
  egxObj(cx,cz,gy+y0,'int:pcupula',_t(11615,'La cúpula y la luz'),_t(11616,'¿cómo era por dentro?'),5);
  // un haz de luz que cae del óculo
  const sh=new THREE.Mesh(new THREE.CylinderGeometry(4,4.6,38,24,1,true),new THREE.MeshBasicMaterial({color:0xfff2d0,transparent:true,opacity:0.07,depthWrite:false,side:THREE.DoubleSide,fog:false}));sh.position.set(cx,gy+20,cz);sh.userData.noCol=true;sh.userData.noVault=true;scene.add(sh);}
// ---------------------------------------------------------------- Termas de Tito (las llama 029_roma.js en lugar del bloque macizo)
const TERM_ROOMS=[
 {k:'apo',n:_t(11617,'Vestuario (apodyterium)'),x0:-35,x1:-17,z0:-26,z1:18,t:_t(11618,'Te desnudas y dejas la ropa en un hueco de la pared. Conviene pagar a un esclavo para que la vigile: los ladrones de ropa de las termas son famosos, y hay tablillas de maldición contra ellos.')},
 {k:'tep',n:_t(11619,'Sala templada (tepidarium)'),x0:17,x1:35,z0:-4,z1:18,t:_t(11620,'Una sala tibia para acostumbrar el cuerpo al calor. Aquí te untan de aceite y te lo raspan después con el estrígilo, una cuchilla curva de bronce: así se limpia la piel, sin jabón.')},
 {k:'cal',n:_t(11621,'Sala caliente (caldarium)'),x0:17,x1:35,z0:-26,z1:-4,t:_t(11622,'Calor húmedo: el aire caliente del horno pasa por debajo del suelo, que se apoya en pilas de ladrillo (el hipocausto), y por tubos dentro de las paredes. Hay una piscina caliente y una gran pila (labrum) para refrescarse la cara.')},
 {k:'fri',n:_t(11623,'Sala fría (frigidarium)'),x0:-17,x1:17,z0:-26,z1:18,t:_t(11624,'Una zambullida en el agua fría para cerrar los poros y terminar. Es la sala más grande y más alta, y la más fresca en verano.')}];
const TERM_ORDER=['apo','tep','cal','fri'];
function termasInterior(cx,cz,gy){const g=grp(cx,gy,cz,0),H=22,F=0.6,W=lam('#e6dccb'),warm=lam('#e8cfb0'),wa=lam('#5d8a90');INT.term={cx,cz,gy};
  // muros (1,5 m) con la puerta al sur, tabiques con pasos y techo; el suelo, a la altura del pórtico
  const wb=(w,h,d,x,y,z,m)=>{const b=box(w,h,d,m||W,x,y,z,g);return b;};
  wb(70,H+3,1.5,0,(H+3)/2-3,-25.25);wb(1.5,H+3,44,-34.25,(H+3)/2-3,-4);wb(1.5,H+3,44,34.25,(H+3)/2-3,-4);
  for(const sx of[-1,1])wb(32,H+3,1.5,sx*19,(H+3)/2-3,17.25);wb(6,H-9,1.5,0,9+(H-9)/2,17.25);
  wb(70,1,44,0,H,-4,lam('#d8ccb4'));wb(69,F,43,0,F/2-0.0,-4,lam('#cfc3aa'));
  // tabiques: vestuario | fría | (templada / caliente)
  for(const[sx]of[[-17],[17]]){wb(1,H,22,sx,H/2,-15);wb(1,H,14,sx,H/2,11);}   // pasos de 4 m a la altura de z=0..4 (puertas)
  wb(7,H,1,20.5,H/2,-4,warm);wb(7,H,1,31.5,H/2,-4,warm);   // templada / caliente, con un paso de 4 m en medio
  // colisiones (coordenadas del mundo; el edificio no está girado)
  const S=(x1,z1,x2,z2)=>intWallSeg(cx+x1,cz+z1,cx+x2,cz+z2);
  S(-35,-26,35,-26);S(-35,-26,-35,18);S(35,-26,35,18);S(-35,18,-3,18);S(3,18,35,18);
  for(const sx of[-17,17]){S(sx,-26,sx,-4);S(sx,4,sx,18);}   // pasos de 8 m (z -4..4): vestuario-fría y fría-templada
  S(17,-4,24,-4);S(28,-4,35,-4);   // templada-caliente
  addPlat(cx,cz-4,70,44,0,gy+F);
  // la piscina fría (con borde: se puede saltar), la caliente y el labrum
  wb(16,0.55,10,0,F+0.27,-6,lam('#d8ccb4'));const w1=new THREE.Mesh(new THREE.PlaneGeometry(15,9),new THREE.MeshPhongMaterial({color:0x5d8a90,shininess:90}));w1.rotation.x=-Math.PI/2;w1.position.set(0,F+0.5,-6);g.add(w1);
  addBox(cx,cz-6,16,10,0,0.3);
  wb(12,0.55,6,26,F+0.27,-21,warm);const w2=new THREE.Mesh(new THREE.PlaneGeometry(11,5),new THREE.MeshPhongMaterial({color:0x6f9a90,shininess:90}));w2.rotation.x=-Math.PI/2;w2.position.set(26,F+0.5,-21);g.add(w2);addBox(cx+26,cz-21,12,6,0,0.3);
  {const lb=new THREE.Mesh(new THREE.CylinderGeometry(1.4,0.5,0.5,20),lam('#d8ccb4'));lb.position.set(26,F+1.4,-10);g.add(lb);const pd=new THREE.Mesh(new THREE.CylinderGeometry(0.35,0.5,1.2,12),lam('#d8ccb4'));pd.position.set(26,F+0.6,-10);g.add(pd);addCirc(cx+26,cz-10,1.4);}
  // bancos y nichos del vestuario
  for(let i=0;i<6;i++){wb(1.2,0.5,4,-33.5,F+0.25,-22+i*7,lam('#bfb39a'));for(let j=0;j<3;j++)wb(0.3,0.9,1.2,-33.6,F+1.6+j*1.1,-22+i*7,lam('#5a4a3a'));}
  // un poco de vapor en la caliente
  for(let i=0;i<10;i++){const p=new THREE.Mesh(new THREE.SphereGeometry(1.6,8,6),new THREE.MeshBasicMaterial({color:0xffffff,transparent:true,opacity:0.06,depthWrite:false}));p.position.set(20+(i%5)*3,F+2+Math.floor(i/5)*2,-20+(i%3)*4);p.userData.noCol=true;p.userData.noVault=true;g.add(p);}
  for(const R of TERM_ROOMS)egxObj(cx+(R.x0+R.x1)/2,cz+(R.z0+R.z1)/2+(R.k==='fri'?8:0),gy+F,'int:t'+R.k,R.n,'termas',4);}
function termz(){const s=state;if(!s.term)s.term={seq:[],done:0};return s.term;}
function termTick(dt){const T=INT.term;if(!T||MODE!=='roma'||ui!=='play')return;const lx=player.x-T.cx,lz=player.z-T.cz;
  const R=TERM_ROOMS.find(r=>lx>r.x0&&lx<r.x1&&lz>r.z0&&lz<r.z1);const z=termz();if(!R){if(Math.abs(lx)>40||Math.abs(lz+4)>30)z.cur=null;return;}if(z.cur===R.k)return;z.cur=R.k;
  if(z.seq[z.seq.length-1]!==R.k)z.seq.push(R.k);if(z.seq.length>14)z.seq.shift();
  toast('<span class="label">'+R.n+'</span><br>'+R.t);
  // cuenta el orden de las salas aunque se cruce la fría de camino: vestuario, luego templada, luego caliente y, al final, la fría
  const s=z.seq.join(','),sub=(q,o)=>{let i=0;for(const k of q){if(k===o[i])i++;if(i===o.length)return true;}return false;},ok=R.k==='fri'&&sub(z.seq,TERM_ORDER);
  if(ok){z.seq=[];z.done++;if(z.done===1){qAdd('vi',2,_t(11625,'Te has bañado como un romano.'));qAdd('so',1);}save();
    setTimeout(()=>eduOverlay('termEnd',_t(11626,'Un baño completo'),_t(11627,'<p>Has hecho el recorrido de un baño romano: vestuario, sala templada, sala caliente y, para terminar, el agua fría. Se iba casi a diario, por la tarde, y por muy poco dinero: un cuarto de as (Horacio, Sátiras 1, 3, 137) y gratis los días que un magistrado o el emperador lo pagaban.</p><p>Vitruvio explica cómo se calientan las salas con el hipocausto y por qué la caliente mira al sol de la tarde (Sobre la arquitectura 5, 10). Séneca, que vivía encima de unos baños, se queja del ruido: los que levantan pesas resoplando, el depilador que grita para anunciarse, los vendedores de pasteles y salchichas (Cartas 56, 1-2).</p><p class="sub">Las Termas de Tito se inauguraron este año, junto al anfiteatro (Suetonio, Tito 7, 3). Su planta se conoce por los dibujos que hizo Andrea Palladio en el siglo XVI; la distribución de las salas en el juego es simplificada.</p>')),900);}
  else if(R.k==='fri'&&z.seq.length>=2&&!s.includes('cal')){setTimeout(()=>toast(_t(11628,'Un bañista se ríe: «¿Al agua fría tan pronto? Primero se entra en calor: templada, caliente… y luego la fría».')),1500);}}
{const f=uxTick;uxTick=function(dt){f(dt);try{termTick(dt);}catch(e){}};}
// ---------------------------------------------------------------- Basílica Julia (la llama basilica() en 026 cuando o.hollow)
function basilicaInterior(o,g,gy,base,h1,h2,pd){const L=o.L,D=o.D,a=o.rot||0,Hh=h1+h2+12,W=lam('#e3d8c2'),N=D-pd,zc=-pd/2;INT.bas={x:o.x,z:o.z,a,gy:gy+base};
  // muros del fondo y de los lados; el frente da al pórtico con cinco grandes arcos (pilares entre ellos)
  box(L-1,Hh,1.2,W,0,base+Hh/2,zc-N/2+0.6,g);for(const s of[-1,1])box(1.2,Hh,N,W,s*(L/2-1.1),base+Hh/2,zc,g);
  const fz=zc+N/2-0.6,nA=9,aw=(L-1)/nA;for(let i=0;i<=nA;i++){box(aw*0.42,Hh,1.2,W,-L/2+0.5+i*aw,base+Hh/2,fz,g);}box(L-1,Hh-h1-2,1.2,W,0,base+h1+2+(Hh-h1-2)/2,fz,g);
  box(L-1,1,N,lam('#d8ccb4'),0,base+Hh,zc,g);   // techo
  // dos filas de pilares que separan la nave de las naves laterales, y el suelo de mármoles de colores
  const nP=12;for(let i=0;i<nP;i++)for(const s of[-1,1]){const lx=-L/2+L*(i+0.5)/nP,lz=zc+s*N*0.28;box(1.6,Hh-2,1.6,lam('#d6cbb5'),lx,base+(Hh-2)/2,lz,g);const w=toW(lx,lz,o.x,o.z,a);addCirc(w[0],w[1],1.0);}
  for(let i=0;i<10;i++)for(let j=0;j<4;j++){const t=box(L/10-0.2,0.04,N/4-0.2,lam(((i+j)%2)?'#c9b9a0':'#9a7a6a'),-L/2+L*(i+0.5)/10,base+0.03,zc-N/2+N*(j+0.5)/4,g);t.userData.noCol=true;}
  // los cuatro tribunales de los centunviros: estrado, sillas de los jueces y bancos para el público
  for(let k=0;k<4;k++){const lx=-L/2+L*(k+0.5)/4,lz=zc-N*0.12;box(10,0.8,5,lam('#bfae92'),lx,base+0.4,lz,g);for(let c=0;c<5;c++)box(0.8,1.2,0.8,lam('#7a5434'),lx-3.2+c*1.6,base+1.4,lz-1.2,g);
    for(let r=0;r<2;r++)box(8,0.45,0.6,lam('#8a6a4a'),lx,base+0.23,lz+4+r*1.6,g);const w=toW(lx,lz,o.x,o.z,a);addBox(w[0],w[1],10,5,a,0.2);
    if(k===1){const e=toW(lx,lz+3,o.x,o.z,a);egxObj(e[0],e[1],gy+base,'int:jui',_t(11629,'Tribunal de los centunviros'),_t(11630,'pleitos de herencias'),4);}}
  // colisiones: fondo, lados y los pilares del frente (los arcos quedan libres)
  const S=(x1,z1,x2,z2)=>{const p=toW(x1,z1,o.x,o.z,a),q=toW(x2,z2,o.x,o.z,a);intWallSeg(p[0],p[1],q[0],q[1]);};
  S(-L/2+0.5,zc-N/2,L/2-0.5,zc-N/2);S(-L/2+0.5,zc-N/2,-L/2+0.5,zc+N/2);S(L/2-0.5,zc-N/2,L/2-0.5,zc+N/2);
  for(let i=0;i<=nA;i++){const lx=-L/2+0.5+i*aw,w=toW(lx,fz,o.x,o.z,a);addCirc(w[0],w[1],aw*0.21+0.3);}
  addPlat(o.x,o.z,L+2,D+2,a,gy+base);
  // tres peldaños delante, desde el Foro (la plataforma está 1,2 m más alta)
  for(let k=1;k<=3;k++){const lz=D/2+1+(k-0.5)*0.8,top=base-k*0.4;box(L,top+2,0.8,TRAV,0,top/2-1,lz,g);const w=toW(0,lz,o.x,o.z,a);addPlat(w[0],w[1],L,0.8,a,gy+top);}}
// ---------------------------------------------------------------- textos y el pleito
const INT_TX={
 pg0:_t(11631,'Marte, el dios de la guerra y padre de Rómulo. Dion Casio cuenta que en el Panteón de Agripa había estatuas de muchos dioses, entre ellas las de Marte y Venus, y una del Divino Julio (Historia romana 53, 27, 2-3). Agripa quiso poner también una de Augusto; Augusto no aceptó, y su estatua y la de Agripa se pusieron fuera, en el pórtico.'),
 pg1:_t(11632,'Venus, la madre de Eneas: los Julios decían descender de ella, así que honrarla aquí era honrar a la familia de Augusto (Dion Casio 53, 27, 2). Plinio cuenta que la Venus del Panteón llevaba en las orejas las dos mitades de una perla de Cleopatra (Historia natural 9, 121).'),
 pg2:_t(11633,'El Divino Julio: Julio César, que el Senado declaró dios después de su muerte. Su estatua estaba entre las de los dioses (Dion Casio 53, 27, 3).'),
 pcupula:_t(11634,'<p>Ves una rotonda con cúpula y una abertura redonda arriba, el óculo, por donde entra la única luz y también la lluvia (el suelo tiene desagües).</p><p><b>Cuidado: así es el Panteón que reconstruirá Adriano hacia el 125 d.C.</b>, el que se conserva. Del de Agripa (27-25 a.C.) no sabemos bien la forma: las excavaciones muestran que también miraba al norte, pero no si tenía cúpula. Plinio cuenta que tenía capiteles de bronce y cariátides del escultor ateniense Diógenes (Historia natural 34, 13 y 36, 38). Y este mismo año, el 80, un incendio lo ha dañado (Dion Casio 66, 24, 2).</p>')};
function intAct(o){const k=String(o.act).slice(4),ro=MODE==='roma';
  if(k==='jui')return juiOpen();
  if(k.startsWith('t')){const R=TERM_ROOMS.find(r=>'t'+r.k===k);if(R){openInfo(R.n,'<p>'+R.t+_t(11635,'</p><p class="sub">Recorre las salas en el orden de un baño: vestuario, templada, caliente y fría.</p>'));return;}}
  const t=INT_TX[k];if(t)openInfo(o.data.name,t.startsWith('<p>')?t:'<p>'+t+'</p>');}
function openInfo(title,html){eduOverlay('intBox',title,html);}
{const f=egxAct0;egxAct0=function(o){if(String(o.act).startsWith('int:'))return intAct(o);return f(o);};}
// el pleito: una querella de testamento «inoficioso» (el hijo desheredado sin motivo)
const JUI=[
 {who:_t(11636,'El abogado del heredero'),t:_t(11637,'«Jueces: el difunto Lucio Valerio era dueño de sus bienes y escribió su testamento con plena razón, ante siete testigos, con su sello. Dejó todo a su amigo Marco, que lo cuidó en la enfermedad. ¿Vamos a deshacer la voluntad de un hombre libre?»')},
 {who:_t(11638,'El abogado del hijo'),t:_t(11639,'«Jueces: un padre puede dejar sus bienes a quien quiera, sí. Pero dejar a su hijo sin nada, sin una sola razón, sin mencionarlo siquiera, va contra el deber de un padre (officium). Un testamento así no es fruto de la razón: es como si lo hubiera escrito un loco. Pedimos que se anule».')}];
function juiOpen(){const z=state.jui||(state.jui={n:0});let i=0;
  const B=()=>$('juiB');const show=()=>{const s=JUI[i];B().innerHTML='<p><b>'+s.who+'</b></p><p>'+s.t+'</p>';const O=$('juiO');O.innerHTML='';const b=document.createElement('button');b.textContent=i<JUI.length-1?_t(11640,'Escuchar a la otra parte'):_t(11641,'Votar');b.onclick=()=>{i++;i<JUI.length?show():vote();};O.appendChild(b);};
  const vote=()=>{B().innerHTML=_t(11642,'<p>Los jueces dan su voto. ¿Qué votas tú?</p>');const O=$('juiO');O.innerHTML='';
    for(const[t,v]of[[_t(11643,'Anular el testamento: el hijo debe recibir su parte'),'a'],[_t(11644,'Mantener el testamento: era su voluntad'),'m']]){const b=document.createElement('button');b.textContent=t;b.style.display='block';b.style.margin='6px 0';b.onclick=()=>fin(v);O.appendChild(b);}};
  const fin=v=>{z.n++;if(z.n===1){qAdd('kl',1,_t(11645,'Has juzgado en la Basílica Julia.'));qAdd('so',1);}save();
    B().innerHTML='<p>'+(v==='a'?_t(11646,'Votas con la mayoría: en casos así los centunviros solían dar la razón al hijo.'):_t(11647,'Votas con la minoría: en casos así los centunviros solían dar la razón al hijo.'))+_t(11648,' Esta reclamación se llama «querella de testamento inoficioso»: si un padre desheredaba sin motivo a sus hijos, el tribunal podía anular el testamento y darles su parte.</p><p>El tribunal de los centunviros juzga herencias aquí, en la Basílica Julia, con unos 180 jueces repartidos en cuatro salas; el público llena las galerías y se asoma para oír a los abogados. Plinio el Joven, abogado famoso en este tribunal, describe un pleito así, el de Atia Viriola, desheredada por su padre a los ochenta años de él (Cartas 6, 33). <span class="sub">(Plinio lo escribe hacia el 106 d.C.: dentro de unos veinticinco años.)</span> Quintiliano, que enseña retórica aquí al lado, habla a menudo de este tribunal en su Institución oratoria.</p>');
    $('juiO').innerHTML='';};
  eduOverlay('juiBox',_t(11629,'Tribunal de los centunviros'),'<div id="juiB"></div><div id="juiO"></div>');show();}
// bajo techo no llueve (la lluvia se dibuja alrededor de la cámara)
function intInside(){const x=player.x,z=player.z,T=INT.term,B=INT.bas;
  if(T&&Math.abs(x-T.cx)<35&&z>T.cz-26&&z<T.cz+18)return true;
  if(B){const l=toL(x,z,B.x,B.z,B.a);if(Math.abs(l[0])<50&&l[1]>-24&&l[1]<18)return true;}
  if(MODE==='roma'&&Math.hypot(x+640,z+540)<25)return true;return false;}
{const f=uxTick;uxTick=function(dt){f(dt);try{if(MODE==='roma'&&typeof WXS!=='undefined'&&WXS.rainM&&WXS.rainM.visible&&intInside())WXS.rainM.visible=false;}catch(e){}};}
// ============================================================ ARREGLOS DEL VÍDEO DE PARTIDA (16-11): avisos, lluvia bajo techo, el Capitolio y el modo atención
// 1. Los avisos se amontonaban (cinco a la vez tapando el plano): ahora se ven dos como mucho; el más antiguo se retira.
// 2. Bajo techo (templos, basílicas, la Curia, casas, termas, el Panteón) no llueve ni vuelan pájaros por dentro.
// 3. En las laderas muy empinadas (el Capitolio) el relieve que se ve quedaba hasta 4 m por encima del suelo con el que se calcula
//    la altura: el jugador se hundía en la colina y la veía «flotar» desde dentro. Ahora sus pies nunca quedan bajo el relieve visible.
// 4. Modo atención: las columnas rostrales del Foro se reconocen como tales (antes decía «Columna toscana»), y una columna
//    que forma parte de un monumento con ficha propia cede su sitio a esa ficha.
{const f=toast;toast=function(html){f(html);try{const c=$('toast');while(c&&c.children.length>2)c.firstChild.remove();}catch(e){}};}
function fxUnderRoof(){try{if(typeof dzUnderRoof==='function'&&dzUnderRoof())return true;}catch(e){}try{if(typeof intInside==='function'&&intInside())return true;}catch(e){}
  try{if(typeof hdIn==='function'&&hdIn())return true;}catch(e){}return false;}
{let was=false;const f=uxTick;uxTick=function(dt){f(dt);try{if(!state)return;const inn=fxUnderRoof();
  if(inn&&typeof WXS!=='undefined'&&WXS.rainM)WXS.rainM.visible=false;
  if(inn!==was){was=inn;for(const fl of (VIDA&&VIDA.flocks)||[])for(const b of fl.b)b.g.visible=!inn;}}catch(e){}};}
{const f=rfFloor;rfFloor=function(x,z,feet){const r=f(x,z,feet);try{if(BOAT.on||(RF&&RF.onRoof)||FLY.on||x>8000||r>terrainH(x,z)+0.05)return r;if(typeof cavIn==='function'&&cavIn())return r;const m=meshH(x,z);if(m!==null&&m>r&&m-r<6)return m;}catch(e){}return r;};}
