// ============================================================ JUEGO MÁS DINÁMICO (1): aguante, trepar, saltar a caballo y perseguir al ladrón
// D1. Aguante: correr cansa; andar o pararse lo recupera, y beber en una fuente mucho más deprisa. Con más Areté/Virtus, más aguante.
// D2. Trepar: ante un podio, una terraza o un escalón alto (0,65-2,4 m) con sitio arriba, «E · Trepar».
// D8. A caballo, ante un murete, la barra espaciadora lo salta (la E desmonta).
// D3. Si te roban (de noche, o un carterista en el mercado), el ladrón huye corriendo: alcánzalo antes de que se pierda.
const AGL={st:1,ex:false,bar:null,drank:0};
function agMax(){return 9+0.9*Math.min(10,qLv(MODE==='roma'?'ar':'ar'));}   // segundos de carrera seguida
function agFountain(){const x=player.x,z=player.z;try{for(const a of ATR.values())for(const o of a)if((o.k==='lacus'||o.k==='spring')&&Math.hypot(o.x-x,o.z-z)<5)return true;}catch(e){}
  try{for(const p of PLACES)if(/Fuente|fuente|Krene|Lacus/.test(p.name)&&Math.hypot(p.x-x,p.z-z)<6)return true;}catch(e){}return false;}
function agTick(dt){if(!state||ui!=='play')return;const moving=Math.hypot(GF.vx||0,GF.vz||0)>5.5,riding=MOUNT.riding||FLY.on||BOAT.on;
  if(!riding&&keys.run&&moving&&!AGL.ex){AGL.st-=dt/agMax();if(AGL.st<=0){AGL.st=0;AGL.ex=true;toast(_t(11670,'<span class="label">Sin aliento</span><br>Te paras a recuperar el resuello. Anda un poco, o bebe en una fuente.'));}}
  else{let k=moving?1/8:1/5;if(agFountain()){k*=4;if(AGL.st<0.95&&performance.now()-AGL.drank>60000){AGL.drank=performance.now();toast(_t(11671,'<span class="label">Agua fresca</span><br>Bebes en la fuente y recuperas el aliento.'));}}AGL.st=Math.min(1,AGL.st+dt*k);if(AGL.ex&&AGL.st>0.5)AGL.ex=false;}
  let b=AGL.bar;if(!b){b=AGL.bar=document.createElement('div');b.id='agBar';b.style.cssText='position:fixed;left:50%;bottom:74px;transform:translateX(-50%);width:160px;height:5px;border-radius:3px;background:rgba(20,14,10,.55);pointer-events:none;z-index:9;transition:opacity .4s';b.innerHTML='<i style="display:block;height:100%;border-radius:3px;background:#e0b070;width:100%"></i>';document.body.appendChild(b);}
  b.style.opacity=AGL.st<0.995?'1':'0';b.firstChild.style.width=Math.round(AGL.st*100)+'%';b.firstChild.style.background=AGL.ex?'#b0563a':'#e0b070';}
// sin aliento no se corre (la velocidad de carrera vuelve a la de andar)
{const f=v2Spd;v2Spd=function(){const v=f.apply(this,arguments);return AGL.ex&&keys.run&&!MOUNT.riding&&!FLY.on?v*4.8/11:v;};}
// ---------------------------------------------------------------- D2. trepar
function clProbe(){const P=player,fx=-Math.sin(P.yaw),fz=-Math.cos(P.yaw),f0=P.feet;if(vtShift(P.x+fx*0.55,P.z+fz*0.55)>0.08)return null;   // una pared: eso es para saltar, no para trepar
  const h1=floorAt(P.x+fx*0.7,P.z+fz*0.7)-f0;if(!(h1>0.65&&h1<=2.4))return null;const h2=floorAt(P.x+fx*1.4,P.z+fz*1.4)-f0;if(Math.abs(h2-h1)>0.35)return null;   // arriba hay suelo llano
  const lx=P.x+fx*1.4,lz=P.z+fz*1.4;if(vtShift(lx,lz)>0.05)return null;if(vtHit(P.x,f0+h1+1.6,P.z,fx,0,fz,1.6))return null;   // y sitio para ponerse de pie
  return{lx,lz,top:f0+h1,fL:f0+h2,H:h1,climb:true};}
{const f=vtProbe;vtProbe=function(){const r=f();if(r)return r;try{return clProbe();}catch(e){return null;}};}
// el aviso dice «Trepar» cuando es trepar, y a caballo «Espacio · Saltar con el caballo»
{const f=vtTick;vtTick=function(dt){
  if(!VT.on&&MOUNT.riding&&ui==='play'&&!FLY.on){VT.pt=(VT.pt||0)-dt;if(VT.pt<=0){VT.pt=0.12;const g=player.grounded;player.grounded=true;try{VT.can=vtProbe();}catch(e){VT.can=null;}player.grounded=g;if(VT.can&&VT.can.climb)VT.can=null;}
    const p=$('prompt');if(VT.can&&p){p.innerHTML=_t(11672,'<kbd>Espacio</kbd>Saltar con el caballo');p.hidden=false;}return;}
  f(dt);try{const p=$('prompt');if(VT.can&&VT.can.climb&&!focus&&p&&!p.hidden)p.innerHTML=_t(11673,'<kbd>E</kbd>Trepar');}catch(e){}};}
{const f=jump;jump=function(){if(MOUNT.riding&&VT.can&&!VT.on&&ui==='play'){vtGo();return;}return f.apply(this,arguments);};}
// ---------------------------------------------------------------- D3. el ladrón que huye
const THF={on:null};
function thfSpawn(n,why){if(THF.on)return;const P=player,a=P.yaw+Math.PI+(Math.random()-0.5)*1.2;const g=makePerson({noVary:true,short:true,chiton:'#3a3028',hair:'#2a2018',himation:'#2a221c'});
  const x=P.x-Math.sin(a)*-2,z=P.z-Math.cos(a)*-2;g.position.set(x,floorAt(x,z),z);scene.add(g);THF.on={g,x,z,a:a+Math.PI,n,t:0,why};
  toast(_t(11674,'<span class="label">¡Al ladrón!</span><br>')+why+_t(11675,' Corre tras él: si lo alcanzas, recuperas lo tuyo.'));try{mtBeacon(x,z);}catch(e){}}
function thfTick(dt){const T=THF.on;if(!T)return;if(ui!=='play')return;T.t+=dt;const P=player,dx=T.x-P.x,dz=T.z-P.z,d=Math.hypot(dx,dz);
  // huye en dirección contraria al jugador, zigzagueando; si choca, gira
  const want=Math.atan2(dx,dz)+Math.sin(T.t*1.7)*0.6,sp=(d<14?7.6:6.2)*dt;let ok=false;
  for(const off of[0,0.6,-0.6,1.2,-1.2,2,-2]){const a=want+off,q={x:T.x+Math.sin(a)*sp,z:T.z+Math.cos(a)*sp};resolve(q,0.35);if(Math.hypot(q.x-T.x,q.z-T.z)>sp*0.6&&Math.abs(floorAt(q.x,q.z)-floorAt(T.x,T.z))<0.7){T.x=q.x;T.z=q.z;T.a=a;ok=true;break;}}
  T.g.position.set(T.x,floorAt(T.x,T.z)+Math.abs(Math.sin(T.t*11))*0.08,T.z);T.g.rotation.y=T.a;try{MTR.beaconT=0;}catch(e){}
  if(d<1.8){scene.remove(T.g);THF.on=null;state.obols=(state.obols||0)+T.n+1;qAdd('ar',1,_t(11676,'¡Lo has alcanzado!'));save();updateStats();
    toast(_t(11677,'<span class="label">¡Atrapado!</span><br>Le agarras del manto. Te devuelve lo robado y una moneda más «por las molestias», y se escabulle entre la gente. ')+(MODE==='roma'?_t(11678,'No hay policía como la nuestra: los vigiles persiguen sobre todo incendios y ladrones nocturnos.'):_t(11679,'En Atenas no hay policía: quien pilla a un ladrón puede llevarlo él mismo ante los Once.')));return;}
  if(d>75||T.t>45){scene.remove(T.g);THF.on=null;toast(_t(11680,'<span class="label">Se ha escapado</span><br>El ladrón se pierde entre las callejuelas.'));}}
// de noche (091): el robo de siempre, y ahora el ladrón huye
{const f=uxThiefTick;uxThiefTick=function(dt){const o0=state&&state.obols;f(dt);try{if(state&&state.obols<o0)thfSpawn(o0-state.obols,_t(11681,'Te ha empujado y se ha llevado tu bolsa.'));}catch(e){}};}
// de día, un carterista en los mercados (una vez al día como mucho)
function thfMarket(dt){if(!state||ui!=='play'||THF.on||(state.obols||0)<6)return;const d=state.day||1;if(state.thfDay===d)return;
  AGL.mk=(AGL.mk||0)+dt;if(AGL.mk<4)return;AGL.mk=0;let near=false;for(const p of PLACES)if(/mercado|Macellum|Subura|Ágora|Agora/i.test(p.name)&&Math.hypot(p.x-player.x,p.z-player.z)<45){near=true;break;}
  if(!near||Math.random()>0.04)return;state.thfDay=d;const n=Math.min(6,2+Math.floor(state.obols*0.08));state.obols-=n;save();updateStats();thfSpawn(n,_t(11682,'Un carterista te ha cortado la bolsa del cinturón entre el gentío.'));}
{const f=uxTick;uxTick=function(dt){f(dt);try{agTick(dt);}catch(e){}try{thfTick(dt);}catch(e){}try{thfMarket(dt);}catch(e){}};}
// ============================================================ JUEGO MÁS DINÁMICO (2): carreras, recados, incendios, dados, la noche y la búsqueda del tesoro
// D4. Carreras: en Roma, dos vueltas al Circo Máximo contra tres cuadrigas (mejor a caballo); en Atenas, el tramo final de la
//     carrera de antorchas, del Dípilon a los Propileos, contra reloj.
// D5. Recados: alguien te pide llevar un mensaje a otra persona antes de que pase el tiempo; corre y busca atajos.
// D6. Incendio: de vez en cuando arde una casa cerca; coge agua en una fuente (E) y échala al fuego (E) antes de que se extienda.
// D7. Dados (tabas): una partida con la gente con la que hablas, con una apuesta pequeña.
// D9. La noche: en Roma, los carros entran en la ciudad de noche; en Atenas, el guardián de la puerta cobra por abrirla.
// D10. Búsqueda del tesoro: una tablilla con pistas escritas en las inscripciones de la ciudad (en griego o en latín).
const DYN={race:null,run:null,errand:null,fire:null,bucket:false,carts:[],hunt:null,hud:null};
function dynz(){const s=state;if(!s.dyn)s.dyn={};return s.dyn;}
function dynHud(t){let h=DYN.hud;if(!h){h=DYN.hud=document.createElement('div');h.style.cssText='position:fixed;left:50%;top:64px;transform:translateX(-50%);padding:6px 12px;border-radius:8px;background:rgba(22,16,12,.82);border:1px solid rgba(217,135,74,.5);color:#f3e6cf;font-size:.95rem;pointer-events:none;z-index:9';document.body.appendChild(h);}h.hidden=!t;if(t)h.innerHTML=t;}
const fmtS=s=>Math.floor(s/60)+':'+String(Math.floor(s%60)).padStart(2,'0');
function plc(id){return PLACES.find(p=>p.id===id);}
// ---------------------------------------------------------------- D4a. Circo Máximo
const CIRC_F=[[_t(11683,'Los rojos'),'russata','#a8392b',14.2],[_t(11684,'Los blancos'),'albata','#e8e2d4',13.6],[_t(11685,'Los verdes'),'prasina','#3f7a3a',14.8]];
function circPath(s){const C=ROMA.circus,L=172,r=20,P=4*L+TAU*r,u=((s%P)+P)%P;let lx,lz;   // óvalo alrededor de la espina, en sentido contrario a las agujas del reloj
  if(u<2*L){lx=-L+u;lz=r;}else if(u<2*L+Math.PI*r){const a=(u-2*L)/r;lx=L+Math.sin(a)*r;lz=Math.cos(a)*r;}else if(u<4*L+Math.PI*r){lx=L-(u-2*L-Math.PI*r);lz=-r;}else{const a=(u-4*L-Math.PI*r)/r;lx=-L-Math.sin(a)*r;lz=-Math.cos(a)*r;}
  const w=C.cr(lx,lz);return{x:w[0],z:w[1],P};}
function circStart(){if(DYN.race||!ROMA.circus)return;const P0=circPath(0).P,laps=2;const riv=CIRC_F.map((f,i)=>{const g=new THREE.Group(),c=lam(f[2]);box(1.4,0.9,1.2,c,0,0.9,0,g);box(2.4,1.4,1.0,lam('#6b4a30'),0,1.1,-2.2,g);const p=makePerson({noVary:true,short:true,chiton:f[2]});p.position.set(0,0.9,0.2);g.add(p);scene.add(g);return{f,g,s:-i*6-6,v:f[3]};});
  DYN.race={riv,t:-3,laps,P:P0,ps:0,last:circProj(),done:false};const a=circPath(0);player.x=a.x;player.z=a.z+0;player.feet=floorAt(a.x,a.z);
  toast(_t(11686,'<span class="label">Carrera en el Circo</span><br>Dos vueltas a la espina, en sentido contrario a las agujas del reloj. ¡A caballo se corre mejor! Las metas son los conos dorados de cada extremo.'));}
function circProj(){// distancia recorrida aproximada del jugador sobre el óvalo
  const C=ROMA.circus,l=(function(){const dx=player.x-C.C.x,dz=player.z-C.C.z,c=Math.cos(C.CA),s=Math.sin(C.CA);return[dx*c-dz*s,dx*s+dz*c];})();let best=0,bd=1e9;const P=circPath(0).P;
  for(let s=0;s<P;s+=6){const q=circPath(s),d=Math.hypot(q.x-player.x,q.z-player.z);if(d<bd){bd=d;best=s;}}return best;}
function circTick(dt){const R=DYN.race;if(!R)return;R.t+=dt;const tot=R.laps*R.P;
  for(const v of R.riv){if(R.t>0&&v.s<tot)v.s+=v.v*dt*(1+Math.sin(R.t*0.3+v.v)*0.05);const a=circPath(v.s),b=circPath(v.s+2);v.g.position.set(a.x,floorAt(a.x,a.z),a.z);v.g.rotation.y=Math.atan2(b.x-a.x,b.z-a.z);}
  const cur=circProj();let d=cur-R.last;if(d<-R.P/2)d+=R.P;if(d>R.P/2)d-=R.P;if(R.t>0&&Math.abs(d)<40)R.ps+=d;R.last=cur;
  const pos=1+R.riv.filter(v=>v.s>R.ps).length;
  dynHud(R.t<0?_t(11687,'Preparados… ')+Math.ceil(-R.t):_t(10310,'Vuelta ')+Math.min(R.laps,1+Math.floor(Math.max(0,R.ps)/R.P))+' de '+R.laps+_t(11688,' · vas ')+pos+'.º · '+fmtS(R.t));
  if(R.ps>=tot){const fin=1+R.riv.filter(v=>v.s>=tot).length;for(const v of R.riv)scene.remove(v.g);DYN.race=null;dynHud('');const z=dynz();z.circ=(z.circ||0)+1;if(fin===1){qAdd('kl',2,_t(11689,'¡Has ganado en el Circo!'));state.obols+=10;updateStats();}save();
    eduOverlay('dynEnd',_t(11690,'Carrera en el Circo Máximo'),_t(11691,'<p>Llegas ')+fin+'.º'+(fin===1?_t(11692,' ¡y ganas! Te dan una palma y diez sestercios.'):'.')+_t(11693,'</p><p>Las carreras de verdad duraban siete vueltas, de izquierda a derecha alrededor de la espina, y lo más peligroso eran los giros junto a las metas, donde chocaban los carros (el «naufragio»). Los aurigas corrían para cuatro facciones, rojos, blancos, verdes y azules, y la gente era hincha de una de ellas: Plinio el Joven se burla de que miles de hombres se apasionen «por un trapo de color» (Cartas 9, 6). Algunos aurigas, como Diocles, se hicieron riquísimos.</p>'));}
  if(R.t>600){for(const v of R.riv)scene.remove(v.g);DYN.race=null;dynHud('');}}
// ---------------------------------------------------------------- D4b. carrera de antorchas (Atenas)
const RUN_IDS=['dipilon','doce','eleusinion','propileos'];
function runStart(){if(DYN.run)return;const pts=RUN_IDS.map(plc).filter(Boolean);if(pts.length<3)return;let L=0;for(let i=1;i<pts.length;i++)L+=Math.hypot(pts[i].x-pts[i-1].x,pts[i].z-pts[i-1].z);
  DYN.run={pts,i:1,t:0,lim:Math.round(L/6.2)+15};player.x=pts[0].x+3;player.z=pts[0].z;player.feet=floorAt(player.x,player.z);try{mtBeacon(pts[1].x,pts[1].z);MTR.beaconT=600;}catch(e){}
  toast(_t(11694,'<span class="label">Carrera de antorchas</span><br>El último tramo de la lampadedromía: del Dípilon al altar de los Doce Dioses, al Eleusinion y a los Propileos. Tienes ')+DYN.run.lim+_t(11695,' segundos. Corre, pero no te quedes sin aliento.'));}
function runTick(dt){const R=DYN.run;if(!R)return;R.t+=dt;const p=R.pts[R.i];dynHud('🔥 '+p.name+' · '+fmtS(Math.max(0,R.lim-R.t)));
  if(Math.hypot(p.x-player.x,p.z-player.z)<12){R.i++;if(R.i>=R.pts.length){const ok=R.t<=R.lim;DYN.run=null;dynHud('');const z=dynz();if(ok&&!z.run){z.run=1;qAdd('ar',2,_t(11696,'Has llegado con la antorcha encendida.'));}save();
      eduOverlay('dynEnd',_t(11697,'Carrera de antorchas'),(ok?_t(11698,'<p>¡Llegas con la antorcha encendida en ')+fmtS(R.t)+'!</p>':_t(11699,'<p>Llegas, pero tarde: ')+fmtS(R.t)+'.</p>')+_t(11700,'<p>En la lampadedromía los corredores salían de noche del altar de Prometeo, en la Academia, y corrían hasta la ciudad con la antorcha encendida: gana quien llega primero sin que se le apague (Pausanias 1, 30, 2). En algunas fiestas se corría por relevos, por tribus. En el juego solo corres el tramo final.</p>'));return;}
    try{mtBeacon(R.pts[R.i].x,R.pts[R.i].z);MTR.beaconT=600;}catch(e){}}
  if(R.t>R.lim+60){DYN.run=null;dynHud('');toast(_t(11701,'Se te ha apagado la antorcha.'));}}
