// ---------------------------------------------------------------- D6. incendio con cubos
function fireStart(){if(DYN.fire||MODE==='x')return;const P=player;const hs=(footprints||[]).filter(f=>f.house&&f.x<8000&&Math.hypot(f.x-P.x,f.z-P.z)>40&&Math.hypot(f.x-P.x,f.z-P.z)<140);if(!hs.length)return;
  const f=hs[Math.floor(Math.random()*hs.length)],g=new THREE.Group(),fl=[];for(let i=0;i<7;i++){const m=new THREE.Mesh(new THREE.ConeGeometry(0.9+Math.random(),2.5+Math.random()*2,6),new THREE.MeshBasicMaterial({color:i%2?0xff8a2a:0xffc040,transparent:true,opacity:0.85,fog:false}));m.position.set((Math.random()-0.5)*6,4+Math.random()*3,(Math.random()-0.5)*6);g.add(m);fl.push(m);}
  const sm=[];for(let i=0;i<10;i++){const s=new THREE.Mesh(new THREE.SphereGeometry(2+Math.random()*2,8,6),new THREE.MeshBasicMaterial({color:0x5a5450,transparent:true,opacity:0.35,depthWrite:false}));s.position.set(0,8+i*2.5,0);g.add(s);sm.push(s);}
  g.position.set(f.x,floorAt(f.x,f.z),f.z);scene.add(g);DYN.fire={f,g,fl,sm,hp:5,t:0,lim:120};try{mtBeacon(f.x,f.z);MTR.beaconT=900;}catch(e){}
  toast(_t(11713,'<span class="label">¡Fuego!</span><br>Arde una casa ahí cerca. Coge agua en una fuente (E) y échala al fuego (E). Hacen falta cinco cubos antes de que se extienda.'));}
function fireNearFountain(){return agFountain();}
function fireTick(dt){const F=DYN.fire;if(!F){if(!state||ui!=='play')return;const z=dynz(),day=state.day||1;if(z.fireDay&&day-z.fireDay<2)return;DYN.fc=(DYN.fc||0)+dt;if(DYN.fc<30)return;DYN.fc=0;if(clock.h<8||clock.h>19||Math.random()>0.06)return;z.fireDay=day;save();fireStart();return;}
  F.t+=dt;const k=F.hp/5;F.fl.forEach((m,i)=>{m.scale.setScalar((0.4+k)*(1+Math.sin(F.t*8+i)*0.15));});F.sm.forEach((s,i)=>{s.position.y=8+((F.t*3+i*2.5)%25);s.material.opacity=0.35*k;});
  const d=Math.hypot(F.f.x-player.x,F.f.z-player.z);dynHud(_t(11714,'🔥 Cubos: ')+(5-F.hp)+_t(11715,' de 5')+(DYN.bucket?_t(11716,' · llevas agua'):'')+' · '+fmtS(Math.max(0,F.lim-F.t)));
  const p=$('prompt');if(ui==='play'&&!focus&&p){if(!DYN.bucket&&fireNearFountain()){p.innerHTML=_t(11717,'<kbd>E</kbd>Llenar el cubo');p.hidden=false;}else if(DYN.bucket&&d<9){p.innerHTML=_t(11718,'<kbd>E</kbd>Echar el agua al fuego');p.hidden=false;}}
  if(F.t>F.lim){scene.remove(F.g);DYN.fire=null;DYN.bucket=false;dynHud('');toast(_t(11719,'<span class="label">El fuego se ha extendido</span><br>Los vecinos consiguen apagarlo al final, pero la casa se ha perdido.'));}}
{const f=interact;interact=function(){const F=DYN.fire;if(F&&!focus&&ui==='play'){const d=Math.hypot(F.f.x-player.x,F.f.z-player.z);
    if(!DYN.bucket&&fireNearFountain()){DYN.bucket=true;try{sfxTap();}catch(e){}toast(_t(11720,'Llenas el cubo de cuero. ¡Rápido, al fuego!'));return;}
    if(DYN.bucket&&d<9){DYN.bucket=false;F.hp--;try{gfPulse();}catch(e){}if(F.hp<=0){scene.remove(F.g);DYN.fire=null;dynHud('');const z=dynz();z.fires=(z.fires||0)+1;qAdd('kl',2,_t(11721,'Has ayudado a apagar un incendio.'));qAdd('ar',1);save();
        eduOverlay('dynEnd',_t(11722,'¡Apagado!'),_t(11723,'<p>Entre todos habéis apagado el fuego.</p>')+(MODE==='roma'?_t(11724,'<p>En Roma los incendios eran continuos: casas de varios pisos, madera, braseros y lámparas de aceite. Augusto creó los vigiles, siete cohortes de libertos que vigilaban de noche con cubos, bombas de agua y hachas, uno por cada dos barrios (Suetonio, Augusto 30; Dion Casio 55, 26). Juvenal dice que vivir en un tercer piso es esperar a que te despierte el humo (Sátiras 3, 197-202).</p>'):_t(11725,'<p>En Atenas no había bomberos: cuando ardía una casa acudían los vecinos con cubos y vasijas, y se derribaba lo que hiciera falta para que el fuego no pasara a la de al lado.</p>')));}
      else toast(_t(11726,'¡Al fuego! Quedan ')+F.hp+' cubos.');return;}}
  return f.apply(this,arguments);};}
// ---------------------------------------------------------------- D7. dados (tabas)
function taliOpen(n){const ro=MODE==='roma',coin=ro?'sestercio':_t(2849,'óbolo');if((state.obols||0)<1){toast(_t(11727,'No tienes dinero para apostar.'));return;}
  const vals=[1,3,4,6],roll=()=>[0,0,0,0].map(()=>vals[Math.floor(Math.random()*4)]);
  const score=r=>{const u=new Set(r).size;if(u===4)return{v:100,t:ro?_t(11728,'¡Venus! (las cuatro distintas)'):_t(11729,'¡Afrodita! (las cuatro distintas)')};if(r.every(x=>x===1))return{v:-1,t:ro?_t(11730,'el perro (cuatro unos)'):_t(11730,'el perro (cuatro unos)')};return{v:r.reduce((a,b)=>a+b,0),t:'suma '+r.reduce((a,b)=>a+b,0)};};
  eduOverlay('taliBox',ro?_t(11731,'Tabas (tali)'):_t(11732,'Tabas (astrágaloi)'),'<p>'+n.name+_t(11733,' saca cuatro tabas, huesecillos de cordero con cuatro caras que valen 1, 3, 4 y 6. «¿Una partida? Una moneda»</p><div id="taliB"></div><div id="taliO" class="lrnRow"></div><p class="sub">La mejor tirada es la que saca las cuatro caras distintas: «Venus» para los romanos, «Afrodita» para los griegos; la peor, cuatro unos, «el perro». Augusto jugaba a esto con sus amigos y lo cuenta en sus cartas (Suetonio, Augusto 71).</p>'));
  const B=$('taliB'),O=$('taliO');const go=()=>{const a=roll(),b=roll(),sa=score(a),sb=score(b),win=sa.v>sb.v?1:sa.v<sb.v?-1:0;state.obols+=win;save();updateStats();
    B.innerHTML=_t(11734,'<p>Tú: <b>')+a.join(' · ')+'</b> — '+sa.t+'<br>'+n.name+': <b>'+b.join(' · ')+'</b> — '+sb.t+'</p><p><b>'+(win>0?_t(11735,'¡Ganas un ')+coin+'!':win<0?_t(11736,'Pierdes un ')+coin+'.':_t(10371,'Empate.'))+'</b></p>';O.innerHTML='';
    if((state.obols||0)>0){const c=document.createElement('button');c.textContent=_t(11737,'Otra');c.onclick=go;O.appendChild(c);}};
  const s=document.createElement('button');s.textContent=_t(11738,'Tirar');s.onclick=go;O.appendChild(s);}
{const f=renderOpts;renderOpts=function(extra){f(extra);try{const n=dlg&&dlg.n;if(!n||!n.topics||(typeof HIST!=='undefined'&&HIST.has(n.id)))return;const o=$('dOpts'),b=document.createElement('button');b.className='quiz';b.innerHTML=_t(11739,'<span class="n">⚄</span><span>«¿Echamos una partida a las tabas?»</span>');
  b.onclick=()=>{closeDialog();setTimeout(()=>taliOpen(n),60);};o.insertBefore(b,o.lastChild);}catch(e){}};}
// ---------------------------------------------------------------- D9. la noche
function nightNow(){return clock.h>=20.5||clock.h<5;}
function cartMake(){const g=new THREE.Group(),w=lam('#6b4a30');box(1.6,0.8,2.6,w,0,1.0,0,g);for(const sx of[-1,1])for(const sz of[-0.9,0.9]){const wh=new THREE.Mesh(new THREE.CylinderGeometry(0.5,0.5,0.15,10),lam('#4a3220'));wh.rotation.z=Math.PI/2;wh.position.set(sx*0.9,0.5,sz);g.add(wh);}
  box(0.7,1.1,1.8,lam('#6b5a4a'),0,1.1,2.5,g);box(0.35,0.4,0.6,lam('#6b5a4a'),0,1.7,3.4,g);const lt=new THREE.PointLight(0xffb060,0.8,10);lt.position.set(0,2.2,1.6);g.add(lt);scene.add(g);return g;}
function dynNightTick(dt){if(!state||ui!=='play')return;const z=dynz(),n=nightNow(),day=state.day||1;
  if(MODE==='roma'){if(!n||player.x>8000){for(const c of DYN.carts)scene.remove(c.g);DYN.carts=[];return;}
    if(z.cartN!==day&&DYN.carts.length){z.cartN=day;save();toast(_t(11740,'<span class="label">Carros de noche</span><br>Una ley de César prohíbe a los carros entrar en Roma de día; por eso la ciudad se llena de ellos al anochecer (Tabla de Heraclea, líneas 56-61). Juvenal dice que el ruido de las ruedas y de los arrieros no deja dormir a nadie (Sátiras 3, 236-238).'));}
    while(DYN.carts.length<5){const R=ROADS.filter(r=>r.pts&&r.pts.length>1&&r.pts.some(p=>Math.hypot(p[0]-player.x,p[1]-player.z)<220));if(!R.length)break;const r=R[Math.floor(Math.random()*R.length)];DYN.carts.push({g:cartMake(),r,i:0,u:Math.random(),dir:Math.random()<0.5?1:-1});}
    for(const c of DYN.carts){const p=c.r.pts;let a=p[c.i],b=p[Math.min(p.length-1,c.i+1)],L=Math.hypot(b[0]-a[0],b[1]-a[1])||1;c.u+=dt*2.2/L*c.dir;if(c.u>1){c.i++;c.u=0;if(c.i>=p.length-1){c.dir=-1;c.i=p.length-2;c.u=1;}}if(c.u<0){c.i--;c.u=1;if(c.i<0){c.dir=1;c.i=0;c.u=0;}}
      a=p[c.i];b=p[Math.min(p.length-1,c.i+1)];const x=a[0]+(b[0]-a[0])*c.u,zz=a[1]+(b[1]-a[1])*c.u;c.g.position.set(x,floorAt(x,zz),zz);c.g.rotation.y=Math.atan2((b[0]-a[0])*c.dir,(b[1]-a[1])*c.dir);
      if(Math.hypot(x-player.x,zz-player.z)>320){scene.remove(c.g);c.dead=1;}}DYN.carts=DYN.carts.filter(c=>!c.dead);}
  else if(n&&z.gateN!==day){for(const p of PLACES){if(!/Puerta|Dípilon|Πύλ/i.test(p.name)||Math.hypot(p.x-player.x,p.z-player.z)>14)continue;z.gateN=day;if((state.obols||0)>0){state.obols--;updateStats();}save();
      toast(_t(11741,'<span class="label">La puerta está cerrada</span><br>De noche las puertas de la muralla se cierran. El guardián te abre el postigo por un óbolo. Eneas el Táctico, que escribirá unas décadas después, explica cómo vigilar las puertas de noche y quién debe guardar las llaves (Poliorcética 18-20).'));break;}}}
// ---------------------------------------------------------------- D10. búsqueda del tesoro
