function huntAct(){const H=huntDef(),z=dynz();if(z.hunt==='fin'){openInfo(_t(11759,'La tablilla'),_t(11760,'<p>Ya encontraste el tesoro.</p>'));return;}if(typeof z.hunt!=='number')z.hunt=0;save();huntShow();}
function huntShow(){const H=huntDef(),z=dynz(),s=H.steps[z.hunt];openInfo(_t(11761,'Búsqueda del tesoro · pista ')+(z.hunt+1)+' de '+H.steps.length,'<p>'+s[1]+_t(11762,'</p><p class="sub">Encuentra la estela con esa inscripción y acércate a ella. Si te pierdes, el plano (M) muestra las estelas.</p>'));}
