 A:[[[0,1],[0.5,0],[1,1]],[[0.25,0.55],[0.75,0.55]]],C:[[[0.9,0.15],[0.5,0],[0.1,0.25],[0.05,0.6],[0.3,0.95],[0.9,0.85]]],L:[[[0.1,0],[0.1,1],[0.9,1]]],
