function tabPts(strokes){const P=[];for(const s of strokes)for(const p of s)P.push(p);return P;}
function tabNorm(P,n){// remuestrear a n puntos por longitud y normalizar a la caja 0..1
  let L=0;for(let i=1;i<P.length;i++)L+=Math.hypot(P[i][0]-P[i-1][0],P[i][1]-P[i-1][1]);if(!L)return null;const step=L/(n-1),out=[P[0].slice()];let acc=0;
  for(let i=1;i<P.length;i++){let a=P[i-1],b=P[i],d=Math.hypot(b[0]-a[0],b[1]-a[1]);while(acc+d>=step&&out.length<n){const t=(step-acc)/d,q=[a[0]+(b[0]-a[0])*t,a[1]+(b[1]-a[1])*t];out.push(q);a=q;d=Math.hypot(b[0]-a[0],b[1]-a[1]);acc=0;}acc+=d;}
  while(out.length<n)out.push(P[P.length-1].slice());let x0=1e9,y0=1e9,x1=-1e9,y1=-1e9;for(const p of out){x0=Math.min(x0,p[0]);y0=Math.min(y0,p[1]);x1=Math.max(x1,p[0]);y1=Math.max(y1,p[1]);}
  const s=Math.max(x1-x0,y1-y0)||1;return out.map(p=>[(p[0]-x0)/s,(p[1]-y0)/s]);}
function tabDist(a,b){let d=0;for(let i=0;i<a.length;i++)d+=Math.hypot(a[i][0]-b[i][0],a[i][1]-b[i][1]);return d/a.length;}
function tabRecognize(strokes,cands){const A=tabNorm(tabPts(strokes),40);if(!A)return null;let best=null,bd=1e9;
  for(const k of cands){const T=TAB_L[k];if(!T)continue;const B=tabNorm(tabPts(T),40),Br=tabNorm(tabPts(T.map(s=>s.slice().reverse())),40);for(const C of[B,Br]){if(!C)continue;const d=tabDist(A,C);if(d<bd){bd=d;best=k;}}}return{k:best,d:bd};}
function tabOpen(){const ro=MODE==='roma',set=ro?['A','C','L','M','N',_t(2915,'O'),'S','V','T']:['Α','Γ','Δ','Λ','Ο','Π','Σ','Τ'],names={'Α':'alfa','Γ':'gamma','Δ':'delta','Λ':'lambda','Ο':_t(11825,'ómicron'),'Π':'pi','Σ':'sigma','Τ':'tau'};
  let target=set[Math.floor(Math.random()*set.length)],ok=0,n=0;
  eduOverlay('tabBox',_t(11826,'La tablilla de cera'),'<p>'+(ro?_t(11827,'En la escuela se escribe con un punzón (stilus) sobre una tablilla de madera cubierta de cera; con el otro extremo, plano, se borra.'):_t(11828,'El maestro de letras (grammatistés) enseña a escribir sobre tablillas de cera con un punzón, letra a letra.'))+_t(11829,' Traza la letra que te pide el maestro.</p><p style="text-align:center">Escribe: <b id="tabT" style="font-size:2em"></b> <span id="tabN" class="sub"></span></p><canvas id="tabC" width="260" height="260" style="display:block;margin:0 auto;background:#8a6a3a;border:8px solid #5a3d26;border-radius:6px;touch-action:none;cursor:crosshair"></canvas><p id="tabS" style="text-align:center"></p><div id="tabO" style="text-align:center"></div>'));
  const C=$('tabC'),X=C.getContext('2d'),T=$('tabT'),S=$('tabS');let strokes=[],cur=null;const show=()=>{T.textContent=target;$('tabN').textContent=ro?'':'('+names[target]+')';X.fillStyle='#8a6a3a';X.fillRect(0,0,260,260);strokes=[];};show();
  const pos=e=>{const r=C.getBoundingClientRect(),p=e.touches?e.touches[0]:e;return[(p.clientX-r.left)/r.width,(p.clientY-r.top)/r.height];};
  const down=e=>{e.preventDefault();cur=[pos(e)];strokes.push(cur);},move=e=>{if(!cur)return;e.preventDefault();const p=pos(e),q=cur[cur.length-1];cur.push(p);X.strokeStyle='#e8d8b0';X.lineWidth=5;X.lineCap='round';X.beginPath();X.moveTo(q[0]*260,q[1]*260);X.lineTo(p[0]*260,p[1]*260);X.stroke();},up=()=>{cur=null;};
  C.onmousedown=down;C.onmousemove=move;addEventListener('mouseup',up);C.ontouchstart=down;C.ontouchmove=move;C.ontouchend=up;
  const O=$('tabO');O.appendChild(mgBtn(_t(11830,'Borrar'),show));O.appendChild(mgBtn(_t(11831,'Ya está'),()=>{if(!strokes.length)return;const r=tabRecognize(strokes,set);n++;const good=r&&r.k===target&&r.d<0.2;if(good)ok++;
    S.innerHTML=good?_t(11832,'¡Bien escrita! (')+ok+' de '+n+')':_t(11833,'El maestro no la reconoce')+(r&&r.k&&r.k!==target?_t(11834,': parece una ')+r.k:'')+'. ('+ok+' de '+n+')';
    if(n>=5){const z=mgz();z.tab=(z.tab||0)+1;if(ok>=4)qAdd('so',1,_t(11835,'Ya escribes las letras con soltura.'));state.obols+=ok>=4?2:0;save();updateStats();S.innerHTML+='<br><b>'+(ok>=4?_t(11836,'El maestro está contento: +2 ')+(ro?'sestercios':_t(2851,'óbolos')):_t(11837,'Hay que practicar más.'))+'</b>';n=0;ok=0;}
    target=set[Math.floor(Math.random()*set.length)];setTimeout(show,700);}));}
