  const all=[...new Set([...r.ok,...['pescado','sal','aceite',_t(11839,'orégano'),_t(11842,'harina de cebada'),'agua','queso','ajo','cilantro','vinagre','huevos','leche','miel','pimienta','garum'],...Object.keys(COC_TRAMPA)])].sort(()=>Math.random()-0.5).slice(0,14);for(const k of r.ok)if(!all.includes(k))all.push(k);
