  const L=$('cocL'),sel=new Set();for(const k of all){const b=document.createElement('button');b.textContent=k;b.style.cssText='font:inherit;padding:6px 10px;border-radius:8px;border:1px solid #6a4a30;background:#1e1712;color:#f3e6cf';b.onclick=()=>{if(sel.has(k)){sel.delete(k);b.style.background='#1e1712';}else{sel.add(k);b.style.background='#7a5434';}};L.appendChild(b);}
