function mgSetup(){for(const[id,dx,dz,act,n,sub]of MG_SPOTS[MODE==='roma'?'roma':'atenas']){const p=(PLACES||[]).find(q=>q.id===id);if(!p)continue;let x=p.x+dx,z=p.z+dz;for(let k=0;k<6&&!isFree(x,z,0.8);k++){x+=1.5;z-=1;}
  const g=grp(x,floorAt(x,z),z,0);box(1.2,0.8,0.8,lam('#7a5434'),0,0.4,0,g);egxObj(x,z,undefined,act,n,sub,2.6);}}
{const f=egxAct0;egxAct0=function(o){const a=String(o.act);if(a.startsWith('mg:')){const k=a.slice(3);({pot:mgPotter,smith:mgSmith,bake:mgBaker,copy:mgCopy,tab:tabOpen,coc:cocOpen}[k]||(()=>{}))();return;}return f(o);};}
