function athRun(k){const E=ATH_EV[k],G=$('athG'),S=$('athS');G.innerHTML=mgBar('ath')+'<div id="athO"></div>';S.innerHTML='<b>'+E.n+'</b>: '+E.t;const K=$('athK'),Z=$('athZ'),O=$('athO');let on=true,last=performance.now();
  const done=(val)=>{on=false;const z=cpz(),better=E.u==='s'?(!z.rec[k]||val<z.rec[k]):(!z.rec[k]||val>z.rec[k]);if(better){z.rec[k]=val;if(val&&((E.u==='m'&&val>E.max*0.85)||(E.u==='s'&&val<25)))qAdd('ar',1,_t(11888,'Una marca de campeón.'));}save();
    O.innerHTML='<p><b>'+(E.u==='s'?val.toFixed(1)+' segundos':val.toFixed(1)+' metros')+'</b>'+(better?_t(11889,' · ¡tu mejor marca!'):'')+_t(11890,'</p><p class="sub">Los vencedores de Olimpia recibían solo una corona de olivo, pero su ciudad los colmaba de honores; en las Panateneas el premio eran ánforas de aceite de los olivos sagrados.</p>');O.appendChild(mgBtn(_t(11891,'Otra prueba'),athOpen));};
  if(k==='estadio'){// alternar dos teclas (o dos botones) lo más deprisa posible: 190 m
    let d=0,v=0,t=0,lastK='';Z.style.width='0';const press=c=>{if(c===lastK)return;lastK=c;v=Math.min(10,v+0.9);};const kb=e=>{if(e.code==='KeyA'||e.code==='KeyD'){e.preventDefault();press(e.code);}};addEventListener('keydown',kb);
    O.appendChild(mgBtn(_t(11892,'◀ Izquierda (A)'),()=>press('A')));O.appendChild(mgBtn(_t(11893,'Derecha (D) ▶'),()=>press('D')));
    const step=now=>{if(!on||!$('athBox')){removeEventListener('keydown',kb);return;}const dt=Math.min(0.05,(now-last)/1000);last=now;t+=dt;v=Math.max(0,v-dt*2.2);d+=v*dt;K.style.left=Math.min(99,d/190*100)+'%';S.innerHTML='<b>'+E.n+_t(11894,'</b>: alterna A y D (o los botones). ')+d.toFixed(0)+' m · '+t.toFixed(1)+' s';
      if(d>=190){removeEventListener('keydown',kb);done(Math.round(t*10)/10);return;}if(t>90){removeEventListener('keydown',kb);done(90);return;}requestAnimationFrame(step);};requestAnimationFrame(step);return;}
  // lanzamientos y salto: fuerza (barra que sube y baja) y luego ángulo o momento
  Z.style.left='78%';Z.style.width='18%';let x=0,dir=1,phase=0,pow=0;
  const act=()=>{if(!on)return;if(phase===0){pow=x;phase=1;Z.style.left=(k==='salto'?'40%':'30%');Z.style.width='16%';x=0;dir=1;}
    else{const a=x,ideal=k==='salto'?0.48:0.38,acc=Math.max(0,1-Math.abs(a-ideal)*3.2);done(Math.round(E.max*(0.35+0.65*pow)*(0.45+0.55*acc)*10)/10);}};
  O.appendChild(mgBtn(_t(11895,'¡Ahora!'),act));const kb=e=>{if(e.code==='Space'){e.preventDefault();act();}};addEventListener('keydown',kb);
  const step=now=>{if(!on||!$('athBox')){removeEventListener('keydown',kb);return;}const dt=Math.min(0.05,(now-last)/1000);last=now;x+=dir*dt*(phase?0.8:1.3);if(x>1){x=1;dir=-1;}if(x<0){x=0;dir=1;}K.style.left=(x*100)+'%';
    S.innerHTML='<b>'+E.n+'</b>: '+(phase?(k==='salto'?_t(11896,'suelta las pesas en el momento justo'):_t(11897,'el ángulo: suelta en la franja'))+_t(11898,' (barra espaciadora)'):_t(11899,'coge impulso: pulsa cuando la fuerza esté en lo alto'));requestAnimationFrame(step);};requestAnimationFrame(step);}
