const TEA={atenas:{obra:_t(11966,'una comedia sobre el dios Pluto, la Riqueza, que es ciego y reparte el dinero sin mirar (Aristófanes la estrenó hace dos años, en el 388)'),papel:_t(11967,'el esclavo listo'),
  masks:[[_t(11968,'Máscara de esclavo: pelo rojizo, boca abierta en una mueca'),1],[_t(11969,'Máscara de rey trágico, con barba solemne'),0],[_t(11970,'Máscara de joven enamorada'),0]],
  lines:[_t(11971,'Amo, ¿por qué seguimos a este viejo ciego?'),_t(11972,'Dice que es Pluto, la Riqueza en persona.'),_t(11973,'¡Si recupera la vista, los honrados serán ricos!'),_t(11974,'Pues vamos al templo de Asclepio a curarlo.')],
  src:_t(11975,'En el teatro griego todos los actores son hombres y llevan máscara; en la comedia hay tres actores que se reparten los papeles y un coro que canta y baila. En estos años el coro de la comedia ya casi ha desaparecido.')},
 roma:{obra:_t(11976,'una comedia de Plauto sobre un viejo avaro que esconde una olla llena de oro'),papel:_t(11977,'el viejo avaro'),
  masks:[[_t(11978,'Máscara de viejo con el ceño fruncido'),1],[_t(11979,'Máscara de muchacha joven'),0],[_t(11980,'Máscara de soldado fanfarrón'),0]],
  lines:[_t(11981,'¡Fuera de mi casa, vieja curiosa!'),_t(11982,'Nadie debe saber lo que escondo.'),_t(11983,'Mi olla, mi preciosa olla… ¿sigue aquí?'),_t(11984,'¡Ay! ¡Me han robado! ¡Ladrones!')],
  src:_t(11985,'En Roma los actores suelen ser esclavos o libertos, y la ley los considera infames, aunque los mejores se hacen famosos. Las comedias de Plauto y Terencio siguen en cartel doscientos años después de escritas; pero al público de hoy lo que más le gusta es el pantomimo, un bailarín que hace todos los papeles en silencio.')}};
function teaOpen(){const T=TEA[MODE==='roma'?'roma':'atenas'];let i=0,err=0;eduOverlay('teaBox',_t(11986,'Subir al escenario'),_t(11987,'<p>Hoy se representa ')+T.obra+_t(11988,'. Te dan el papel de <b>')+T.papel+_t(11989,'</b>.</p><p>Primero, ¿qué máscara te pones?</p><div id="teaO"></div><p id="teaS"></p>'));
  const O=$('teaO'),S=$('teaS');for(const[t,ok]of T.masks.slice().sort(()=>Math.random()-0.5)){const b=mgBtn(t,()=>{if(!ok){S.textContent=_t(11990,'El director niega con la cabeza: esa máscara no es de tu papel.');err++;return;}S.textContent=_t(11991,'¡Eso es! Ahora di tus frases en orden: pulsa la que va primero.');O.innerHTML='';lines();});b.style.display='block';O.appendChild(b);}
  const lines=()=>{const L=T.lines.slice().sort(()=>Math.random()-0.5);O.innerHTML='';for(const l of L){const b=mgBtn('«'+l+'»',()=>{if(l===T.lines[i]){i++;b.disabled=true;b.style.opacity=.5;S.textContent=i<T.lines.length?_t(11992,'¡Bien! Sigue…'):'';if(i===T.lines.length)fin();}else{err++;S.textContent=_t(11993,'Te equivocas de frase: el apuntador te sopla la buena.');}});b.style.display='block';b.style.textAlign='left';O.appendChild(b);}};
  const fin=()=>{const z=cpz(),ok=err<=1;z.tea=(z.tea||0)+1;if(ok&&!z.teaOk){z.teaOk=1;qAdd('kl',1,_t(11994,'¡El público te aplaude!'));qAdd('eu',1);}save();
    S.innerHTML='<b>'+(ok?_t(11995,'¡Aplausos!'):_t(11996,'El público silba un poco, pero acabas la escena.'))+'</b><br><span class="sub">'+T.src+_t(11997,' Las frases de esta escena las ha escrito el juego, inspirándose en la obra.</span>');O.innerHTML='';O.appendChild(mgBtn(_t(10372,'Otra vez'),teaOpen));};}
