// ============================================================ AULA Y GRUPO: modo examen, concurso en línea y accesibilidad ampliada
// P10. Modo examen: en el modo profesor, «Crear examen» elige lecciones y lugares y da un código (y un enlace ?examen=…). El alumno lo
//      abre en Aprender › Examen o con el enlace; el resultado (aciertos a la primera, lugares visitados) sale en su informe y en el Panel.
// P11. En una sala en línea: concurso de preguntas (todos reciben las mismas, por turnos de dos minutos) con clasificación, y la
//      búsqueda del tesoro muestra cuántas pistas lleva cada uno. Viaja en la «presencia», como la posición.
// P12. Accesibilidad: colores para daltonismo, subtítulos de los sonidos importantes y pausar la hora del día.
const EXM={};
function exEnc(o){return btoa(unescape(encodeURIComponent(JSON.stringify(o)))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');}
function exDec(s){try{s=String(s).trim().replace(/-/g,'+').replace(/_/g,'/');while(s.length%4)s+='=';return JSON.parse(decodeURIComponent(escape(atob(s))));}catch(e){return null;}}
function exz(){return state.exam||null;}
function exStart(code){const o=exDec(code);if(!o||!o.l){toast(_t(12110,'Ese código de examen no es válido.'));return false;}if(o.m&&o.m!==MODE){toast(_t(12111,'Ese examen es del modo ')+(o.m==='roma'?_t(2864,'Roma'):_t(2865,'Atenas'))+'.');return false;}
  state.exam={code,t:o.t||_t(12112,'Examen'),l:o.l,p:o.p||[],t0:Date.now(),res:{},vis:{}};save();exOpen();return true;}
function exStat(){const E=exz();if(!E)return null;let ok=0,ko=0,vis=0;for(const id of E.l){const r=E.res[id];if(r===1)ok++;else if(r===0)ko++;}for(const id of E.p)if(E.vis[id])vis++;
  return{ok,ko,pend:E.l.length-ok-ko,vis,tot:E.l.length,ptot:E.p.length};}
function exOpen(){const E=exz();if(!E){eduOverlay('exBox',_t(12112,'Examen'),_t(12113,'<p>Escribe el código que te ha dado tu profesor o profesora:</p><input id="exI" style="width:100%;font:inherit;padding:6px"><div id="exO"></div>'));const I=$('exI');I.onkeydown=e=>e.stopPropagation();
    $('exO').appendChild(mgBtn(_t(10321,'Empezar'),()=>{const c=I.value;document.getElementById('exBox').remove();ui='play';exStart(c);}));return;}
  const S=exStat(),nm=id=>{const n=NPCS.find(q=>q.id===id);return n?n.name+' — '+(LESSONS[id]?LESSONS[id].title:''):id;},pn=id=>{const p=(PLACES||[]).find(q=>q.id===id);return p?p.name:id;};
  eduOverlay('exBox',E.t,_t(12114,'<p>Habla con estas personas y responde su pregunta (cuenta el primer intento):</p><ul>')+E.l.map(id=>'<li>'+(E.res[id]===1?'✓ ':E.res[id]===0?'✗ ':'· ')+nm(id)+'</li>').join('')+'</ul>'+
    (E.p.length?_t(12115,'<p>Y visita estos lugares:</p><ul>')+E.p.map(id=>'<li>'+(E.vis[id]?'✓ ':'· ')+pn(id)+'</li>').join('')+'</ul>':'')+'<p><b>'+S.ok+_t(12116,' bien · ')+S.ko+_t(12117,' mal · ')+S.pend+' pendientes'+(S.ptot?_t(12118,' · lugares ')+S.vis+'/'+S.ptot:'')+_t(12119,'</b></p><p class="sub">Cuando acabes, descarga tu informe (Aprender › ¿Qué he aprendido?) y entrégalo: lleva el resultado del examen.</p><div id="exO"></div>'));
  $('exO').appendChild(mgBtn(_t(12120,'Dejar el examen'),()=>{state.exam=null;save();document.getElementById('exBox').remove();ui='play';}));}
// el primer intento de cada pregunta del examen
{const f=answer;answer=function(ok){try{const E=exz(),n=dlg&&dlg.n;if(E&&n&&E.l.includes(n.id)&&E.res[n.id]===undefined){E.res[n.id]=ok?1:0;save();const S=exStat();toast(_t(12121,'<span class="label">Examen</span><br>')+(ok?_t(12122,'Bien'):_t(12123,'Fallada'))+' · '+S.ok+_t(12124,' bien, ')+S.ko+_t(12125,' mal, ')+S.pend+' pendientes.');}}catch(e){}return f.apply(this,arguments);};}
function exTick(dt){const E=exz();if(!E||ui!=='play')return;EXM.t=(EXM.t||0)+dt;if(EXM.t<1)return;EXM.t=0;for(const id of E.p){if(E.vis[id])continue;const p=(PLACES||[]).find(q=>q.id===id);if(p&&Math.hypot(p.x-player.x,p.z-player.z)<12){E.vis[id]=1;save();toast(_t(12126,'<span class="label">Examen</span><br>Lugar visitado: ')+p.name+'.');}}}
