function exCreate(){const L=NPCS.filter(n=>n.quiz&&LESSONS[n.id]&&npcObjs.some(o=>o.data===n&&o.x<8000)),P=(PLACES||[]).filter(p=>p.x<8000);
  eduOverlay('exCBox',_t(12131,'Crear un examen'),_t(12132,'<p>Título: <input id="exT" value="Examen de ')+(MODE==='roma'?_t(2864,'Roma'):_t(2865,'Atenas'))+_t(12133,'" style="font:inherit;padding:4px;width:60%"></p><p>Elige entre 3 y 10 lecciones:</p><input id="exF" placeholder="filtrar…" style="font:inherit;padding:4px"><div id="exL" style="max-height:220px;overflow:auto;border:1px solid #6a4a30;padding:6px;margin:6px 0"></div><p>Lugares que hay que visitar (opcional, hasta 5):</p><div id="exP" style="max-height:140px;overflow:auto;border:1px solid #6a4a30;padding:6px"></div><div id="exCO"></div><p id="exCS"></p>'));
  const sel=new Set(),psel=new Set(),draw=()=>{const q=($('exF').value||'').toLowerCase();$('exL').innerHTML=L.filter(n=>(n.name+' '+LESSONS[n.id].title+' '+LESSONS[n.id].cat).toLowerCase().includes(q)).map(n=>'<label style="display:block"><input type="checkbox" data-id="'+n.id+'" '+(sel.has(n.id)?'checked':'')+'> '+n.name+' — '+LESSONS[n.id].title+' <span class="sub">('+LESSONS[n.id].cat+')</span></label>').join('');
    $('exL').querySelectorAll('input').forEach(i=>i.onchange=()=>{i.checked?sel.add(i.dataset.id):sel.delete(i.dataset.id);});};
  $('exP').innerHTML=P.map(p=>'<label style="display:block"><input type="checkbox" data-p="'+p.id+'"> '+p.name+'</label>').join('');$('exP').querySelectorAll('input').forEach(i=>i.onchange=()=>{i.checked?psel.add(i.dataset.p):psel.delete(i.dataset.p);});
  $('exF').oninput=draw;$('exF').onkeydown=e=>e.stopPropagation();$('exT').onkeydown=e=>e.stopPropagation();draw();
  $('exCO').appendChild(mgBtn(_t(12134,'Generar el código'),()=>{if(sel.size<3||sel.size>10){$('exCS').textContent=_t(12135,'Elige entre 3 y 10 lecciones.');return;}const code=exEnc({v:1,m:MODE,t:$('exT').value.slice(0,60),l:[...sel],p:[...psel].slice(0,5)});
    const url=location.href.split('#')[0].split('?')[0]+'?modo='+MODE+'&examen='+code;$('exCS').innerHTML=_t(12136,'<b>Código:</b><br><textarea readonly style="width:100%;height:60px">')+code+_t(12137,'</textarea><br><b>Enlace para el alumnado:</b><br><textarea readonly style="width:100%;height:60px">')+url+'</textarea>';try{navigator.clipboard.writeText(url);}catch(e){}}));}
{const f=profeOpen;profeOpen=function(){f.apply(this,arguments);try{const A=$('profeA');if(A&&PROFE.ok&&!$('exCB')){const x=document.createElement('button');x.id='exCB';x.textContent=_t(12138,'Crear examen');x.onclick=()=>{profeClose();setTimeout(exCreate,60);};A.appendChild(x);}}catch(e){}};}
