  if(k===0){s.add(new THREE.HemisphereLight(0xd6e4f2,0x8a7552,0.62));const d=new THREE.DirectionalLight(0xfff0d2,1);d.position.set(-3,4,3);s.add(d);s.background=new THREE.Color('#a9c7e0');}
