{const f=windTick;windTick=function(dt){f(dt);try{if(GF.reduced)return;let ss='pri';try{ss=calNow().season.id;}catch(e){}const k=1+0.7*(WXS.cl||0)+(ss==='oto'?0.3:ss==='inv'?0.15:0);WIND.s.value*=k;}catch(e){}};}
