  const w=(WXS.rain||0)>0.15?Math.min(1,(WXS.rain||0)*1.4):Math.max(0,1-(now-X3.wetH)/5);const inside=typeof INT2!=='undefined'&&INT2.in;TERR_U.uWet.value=inside?0:w*(gqOn('medio')?1:0.6);
