{const f=legWin;legWin=function(){const k=LEY.kind,r=f.apply(this,arguments);try{if(leyRo()&&k==='caco'){const z=leyz();if(!z.open){z.open=1;save();MNT.msg=true;}}}catch(e){}return r;};}
