    for(let i=-3;i<3;i++)for(let j=-3;j<3;j++){if(Math.abs(i+0.5)<1.5&&Math.abs(j+0.5)<1.5)continue;if(r()<0.6)box(0.8,rr(0.8,2.2),8,wm,i*9+4.5,0.8,j*8+4,g);if(r()<0.6)box(9,rr(0.8,2.2),0.8,wm,i*9,0.8,j*8+8,g);}
